import React, { useState, useEffect, useRef } from "react";
import { Play, Pause, RotateCcw, AlertTriangle, Disc, Thermometer, ShieldCheck, Database, Volume2, Waves, Terminal, Sparkles, Activity, Gauge, Cpu, Radio, Flame, Sparkle, Network, Import, Music, LineChart, Zap } from "lucide-react";

/* =========================
   SPECIMEN CONFIGURATIONS (THE FIELD AGENTS)
========================= */
const SPECIMENS = [
  { 
    id: "alpha", 
    name: "SPECIMEN A-28 (WARM ANCHOR)", 
    freq: 0.08, 
    phase: 0.0, 
    mass: 0.45, 
    color: [0.85, 0.40, 0.12], // Amber Orange
    description: "Low-frequency thermal core. Coordinates baseline mass borders.",
    acousticSig: "55Hz deep floor hum subcarrier"
  },
  { 
    id: "beta", 
    name: "SPECIMEN B-140 (FLUID SHIFT)", 
    freq: 0.14, 
    phase: 1.8, 
    mass: 0.35, 
    color: [0.12, 0.55, 0.90], // Ice Blue
    description: "Liquefied thermodynamic wave. Core convective heat junction.",
    acousticSig: "Bandpass filtered fluid brown noise"
  },
  { 
    id: "gamma", 
    name: "SPECIMEN G-06 (STRUCTURAL MATRIX)", 
    freq: 0.05, 
    phase: 3.1, 
    mass: 0.40, 
    color: [0.0, 0.85, 0.70], // Cyber Teal
    description: "Crystalline grid reference. Anchor point for system coordination.",
    acousticSig: "110Hz sawtooth structural reference"
  },
  { 
    id: "delta", 
    name: "SPECIMEN D-400 (INSTABILITY BURST)", 
    freq: 0.25, 
    phase: 4.5, 
    mass: 0.28, 
    color: [0.75, 0.15, 0.85], // Violet
    description: "High-frequency chaotic emitter. Generates local thermal surges.",
    acousticSig: "Sweeping high-frequency instability chatter"
  }
];

/* =========================
   POTENTIAL FIELD ATTRACTORS BASELINE COORDINATES
========================= */
const BASINS_BASE = [
  { id: "nostalgia", name: "NOSTALGIA", x: -0.22, y: -0.18, baseDepth: 0.8, color: [0.85, 0.45, 0.1] },
  { id: "tension", name: "TENSION", x: 0.25, y: 0.22, baseDepth: 0.9, color: [0.9, 0.15, 0.2] },
  { id: "release", name: "RELEASE", x: -0.28, y: 0.20, baseDepth: 0.85, color: [0.0, 0.85, 0.7] },
  { id: "triumph", name: "TRIUMPH", x: 0.20, y: -0.25, baseDepth: 0.75, color: [0.75, 0.15, 0.85] }
];

/* =========================
   RING GRAPH COUPLING MATRIX (A -> B -> C -> D -> A)
========================= */
const COUPLING_MATRIX: Record<string, Record<string, number>> = {
  alpha: { delta: 1.0 },
  beta: { alpha: 1.0 },
  gamma: { beta: 1.0 },
  delta: { gamma: 1.0 }
};

// Helper for multi-vortex directional routing (asymmetric convection transport)
const getBranchingBias = (from: string, to: string) => {
  // Perimeter Convection Ring (Vortex Loop 1)
  if (from === "alpha" && to === "beta") return 1.0;
  if (from === "beta" && to === "gamma") return 1.0;
  if (from === "gamma" && to === "delta") return 1.0;
  if (from === "delta" && to === "alpha") return 1.0;

  if (from === "beta" && to === "alpha") return -1.0;
  if (from === "gamma" && to === "beta") return -1.0;
  if (from === "delta" && to === "gamma") return -1.0;
  if (from === "alpha" && to === "delta") return -1.0;

  // Intersecting Branching Bridges (Vortex Loop 2 & Junction splits)
  if (from === "alpha" && to === "gamma") return 1.5; 
  if (from === "delta" && to === "beta") return 1.5;  

  if (from === "gamma" && to === "alpha") return -1.5;
  if (from === "beta" && to === "delta") return -1.5;
  return 0.0;
};

// Helper to map and track edge indices deterministically
const getEdgeId = (from: string, to: string) => {
  const ids = [from, to].sort();
  return `${ids[0]}_${ids[1]}`;
};

// Structure of recorded escape events (Level 16 Simplified Measurement Model)
interface EscapeEvent {
  id: string;
  time: number;
  specimen: string;
  from: string;
  to: string;
  kineticEnergy: number;
  momentum: number;
  noise: number;
  audioAmp: number;
  wellDepth: number;
}

export default function Component() {
  const [isPlaying, setIsPlaying] = useState(false);
  const [time, setTime] = useState(0);
  const [speedMultiplier, setSpeedMultiplier] = useState(3.0); // Physics clock speed
  const [couplingStrength, setCouplingStrength] = useState(1.2); // Kuramoto K factor
  const [feedbackAlpha, setFeedbackAlpha] = useState(0.8); // Amplitude-Phase Coupling (Alpha)
  const [thermalNoiseFloor, setThermalNoiseFloor] = useState(0.15); // Entropy-driven random jitter (Noise)
  const [thermalDiffusionRate, setThermalDiffusionRate] = useState(0.5); // Fourier Heat Diffusion Beta
  const [vortexBias, setVortexBias] = useState(0.7); // Perimeter Convective Bias (Gamma)
  const [branchingBias, setBranchingBias] = useState(0.8); // Branching Diagonal Conductivity (Sigma)
  const [plasticityRate, setPlasticityRate] = useState(0.6); // Topological Plasticity Rate (Lambda)
  const [potentialGravity, setPotentialGravity] = useState(1.0); // Bounded Landscape Depth Scaler (Phi)
  const [landscapeAdaptationRate, setLandscapeAdaptationRate] = useState(0.5); // Level 13/14 Landscape Morph Rate (Mu)

  // Level 11: Flow Audio Injector Boundary State
  const [flowSongInput, setFlowSongInput] = useState("c5a1bbd9-882c-44de-8b3e-a22f892fe1f4"); 
  const [flowSongUrl, setFlowSongUrl] = useState<string | null>("https://storage.googleapis.com/producer-app-public/clips/c5a1bbd9-882c-44de-8b3e-a22f892fe1f4.m4a");
  const [flowAmplitude, setFlowAmplitude] = useState(0.0);
  const [isSongPlaying, setIsSongPlaying] = useState(false);

  // Level 15/16: Experimental Validation Engine State Metrics
  const [activePreset, setActivePreset] = useState<string>("default");
  const [transitionsCount, setTransitionsCount] = useState(0);
  const [meanVelocity, setMeanVelocity] = useState(0.0);
  const [relaxationTime, setRelaxationTime] = useState<number | null>(null);
  const [isRelaxing, setIsRelaxing] = useState(false);
  const [impulseActive, setImpulseActive] = useState(false);

  // Level 16 Stratified Entropy States (Lifetime vs 300-Frame Sliding Window)
  const [lifetimeEntropy, setLifetimeEntropy] = useState(1.0);
  const [windowEntropy, setWindowEntropy] = useState(1.0);
  const [basinOccupancy, setBasinOccupancy] = useState<Record<string, number>>({
    nostalgia: 0.25,
    tension: 0.25,
    release: 0.25,
    triumph: 0.25
  });

  // Level 16: Simplified Escape Event Log Dataset
  const [escapeLog, setEscapeLog] = useState<EscapeEvent[]>([]);

  const [fps, setFps] = useState(60);
  const [deltaTime, setDeltaTime] = useState(0);
  const [activeTab, setActiveTab] = useState<"visualizer" | "specimens" | "matrix" | "basins" | "lab">("visualizer");

  // Custom manual phase offsets (initial boundary conditions)
  const [phases, setPhases] = useState<Record<string, number>>({
    alpha: 0.0,
    beta: 1.8,
    gamma: 3.1,
    delta: 4.5
  });

  // Coupled Thermal Temperature State Variable for each specimen
  const [thermalEnergy, setThermalEnergy] = useState<Record<string, number>>({
    alpha: SPECIMENS[0].mass * 0.5,
    beta: SPECIMENS[1].mass * 0.5,
    gamma: SPECIMENS[2].mass * 0.5,
    delta: SPECIMENS[3].mass * 0.5
  });

  // Level 13 Adaptive Landscape: Dynamic depths for emotional basins
  const [basinDepths, setBasinDepths] = useState<Record<string, number>>({
    nostalgia: 0.8,
    tension: 0.9,
    release: 0.85,
    triumph: 0.75
  });

  // Level 14 Geometric Field Plasticity: Dynamic basin center coordinates drifting with specimen focus
  const [basinCenters, setBasinCenters] = useState<Record<string, { x: number; y: number }>>({
    nostalgia: { x: -0.22, y: -0.18 },
    tension: { x: 0.25, y: 0.22 },
    release: { x: -0.28, y: 0.20 },
    triumph: { x: 0.20, y: -0.25 }
  });

  // Level 13/14 Creative Momentum: Evolving mass/inertia driven by both instant temperature and stability duration
  const [creativeMomentum, setCreativeMomentum] = useState<Record<string, number>>({
    alpha: 1.0,
    beta: 1.0,
    gamma: 1.0,
    delta: 1.0
  });

  // Level 12 Particle Dynamics: Active Coordinates of the 4 specimens rolling across the landscape
  const [specimenCoords, setSpecimenCoords] = useState<Record<string, { x: number; y: number; vx: number; vy: number }>>({
    alpha: { x: -0.15, y: -0.10, vx: 0.0, vy: 0.0 },
    beta: { x: 0.22, y: 0.18, vx: 0.0, vy: 0.0 },
    gamma: { x: -0.28, y: 0.25, vx: 0.0, vy: 0.0 },
    delta: { x: 0.15, y: -0.28, vx: 0.0, vy: 0.0 }
  });

  // Level 10 Topological Plasticity: Dynamic Edge Weights Multipliers (Hebbian-like accumulators)
  const [edgePlasticity, setEdgePlasticity] = useState<Record<string, number>>({
    "alpha_beta": 1.0,
    "beta_gamma": 1.0,
    "gamma_delta": 1.0,
    "alpha_delta": 1.0,
    "alpha_gamma": 1.0,
    "beta_delta": 1.0
  });

  // Interactive boundary conditions
  const [activeSpecimens, setActiveSpecimens] = useState<Record<string, boolean>>({
    alpha: true,
    beta: true,
    gamma: true,
    delta: true
  });

  const [log, setLog] = useState<string[]>([
    "[00:00:00] PROTOCOL LOADED: ELY-STRATIFIED-ENTROPY-v3.5",
    "[00:00:00] LIFETIME VS. SLIDING WINDOW OBSERVER: MOUNTED",
    "[00:00:00] ESCAPE EVENT ENERGY DETECTOR: INITIALIZED",
    "[00:00:00] HIERARCHICAL COGNITIVE PLATFORM LOCKED"
  ]);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const physicsClockRef = useRef<number>(performance.now());

  // Web Audio Analyser for Flow Music reactiveness
  const flowMediaAnalyserRef = useRef<AnalyserNode | null>(null);
  const mediaSourceNodeRef = useRef<MediaElementAudioSourceNode | null>(null);
  const mediaPlayerRef = useRef<HTMLAudioElement | null>(null);

  // Web Audio Specimen references for real-time additive synth
  const specimenAudioRef = useRef<Record<string, {
    oscillator?: OscillatorNode;
    noise?: AudioScheduledSourceNode;
    filter: BiquadFilterNode;
    gain: GainNode;
    pan: StereoPannerNode;
  }>>({});

  // Single Source of Truth for Coupled Phase Angles
  const phasesRef = useRef<Record<string, number>>({
    alpha: SPECIMENS[0].phase,
    beta: SPECIMENS[1].phase,
    gamma: SPECIMENS[2].phase,
    delta: SPECIMENS[3].phase
  });

  // Level 15/16: Dynamic Accumulator Refs for Real-Time Path Tracking
  const lastClosestBasinRef = useRef<Record<string, string>>({
    alpha: "nostalgia",
    beta: "release",
    gamma: "tension",
    delta: "triumph"
  });
  const occupancyRef = useRef<Record<string, number>>({ nostalgia: 1, tension: 1, release: 1, triumph: 1 });
  const totalTicksRef = useRef<number>(4);
  const windowHistoryRef = useRef<string[]>([]); // Array of the last 300 specimen closest-basin ticks
  const relaxationClockRef = useRef<number>(0);

  // Helper to append telemetry log
  const addLog = (msg: string) => {
    const tStr = new Date().toTimeString().split(' ')[0];
    setLog(prev => [`[${tStr}] ${msg}`, ...prev.slice(0, 48)]);
  };

  // Compute Master Field Superposition Average
  const activeCount = Object.values(activeSpecimens).filter(Boolean).length;
  const totalFieldEntropy = activeCount > 0 
    ? Object.entries(thermalEnergy).reduce((sum, [id, val]) => sum + val, 0) / activeCount
    : 0.0;

  // Level 14: Calculate Landscape Diversity Metric (Normalized Shannon Entropy on active wells)
  const meanWellDepth = Object.values(basinDepths).reduce((s, v) => s + v, 0) / 4;
  const varianceWellDepth = Object.values(basinDepths).reduce((s, v) => s + Math.pow(v - meanWellDepth, 2), 0) / 4;
  // Normalized Diversity scale: 1.0 is completely balanced, drops as variance rises (polarization)
  const landscapeDiversity = Math.max(0.01, Math.min(1.0, 1.0 - Math.sqrt(varianceWellDepth)));

  /* =========================
     MULTI-CHANNEL AUDIO SYNTHESIS
  ========================= */
  const initAudioEngine = () => {
    if (audioContextRef.current) {
      if (audioContextRef.current.state === "suspended") {
        audioContextRef.current.resume();
      }
      return;
    }

    try {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.value = 0.8;
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // 1. SPECIMEN ALPHA (Warm Anchor): 55Hz Subcarrier Hum
      const oscAlpha = ctx.createOscillator();
      oscAlpha.type = "sine";
      oscAlpha.frequency.value = 55;
      const lpAlpha = ctx.createBiquadFilter();
      lpAlpha.type = "lowpass";
      lpAlpha.frequency.value = 80;
      const panAlpha = ctx.createStereoPanner();
      const gainAlpha = ctx.createGain();
      gainAlpha.gain.value = 0.0;
      oscAlpha.connect(lpAlpha);
      lpAlpha.connect(panAlpha);
      panAlpha.connect(gainAlpha);
      gainAlpha.connect(masterGain);
      oscAlpha.start();

      // 2. SPECIMEN BETA (Fluid Shift): Procedural Brown Noise Water Wave
      const bufferSize = ctx.sampleRate * 2;
      const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      let lastVal = 0;
      for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;
        lastVal = (lastVal + 0.02 * white) / 1.02;
        data[i] = lastVal * 3.5;
      }
      const noiseBeta = ctx.createBufferSource();
      noiseBeta.buffer = buffer;
      noiseBeta.loop = true;
      const lpBeta = ctx.createBiquadFilter();
      lpBeta.type = "bandpass";
      lpBeta.Q.value = 3.0;
      const panBeta = ctx.createStereoPanner();
      const gainBeta = ctx.createGain();
      gainBeta.gain.value = 0.0;
      noiseBeta.connect(lpBeta);
      lpBeta.connect(panBeta);
      panBeta.connect(gainBeta);
      gainBeta.connect(masterGain);
      noiseBeta.start();

      // 3. SPECIMEN GAMMA (Structural Reference): Sawtooth 110Hz Sub-Lead
      const oscGamma = ctx.createOscillator();
      oscGamma.type = "sawtooth";
      oscGamma.frequency.value = 110;
      const lpGamma = ctx.createBiquadFilter();
      lpGamma.type = "lowpass";
      lpGamma.frequency.value = 150;
      const panGamma = ctx.createStereoPanner();
      const gainGamma = ctx.createGain();
      gainGamma.gain.value = 0.0;
      oscGamma.connect(lpGamma);
      lpGamma.connect(panGamma);
      panGamma.connect(gainGamma);
      gainGamma.connect(masterGain);
      oscGamma.start();

      // 4. SPECIMEN DELTA (Instability Burst): Sawtooth 440Hz Sweeper
      const oscDelta = ctx.createOscillator();
      oscDelta.type = "sawtooth";
      oscDelta.frequency.value = 440;
      const lpDelta = ctx.createBiquadFilter();
      lpDelta.type = "bandpass";
      lpDelta.Q.value = 5.0;
      const panDelta = ctx.createStereoPanner();
      const gainDelta = ctx.createGain();
      gainDelta.gain.value = 0.0;
      oscDelta.connect(lpDelta);
      lpDelta.connect(panDelta);
      panDelta.connect(gainDelta);
      gainDelta.connect(masterGain);
      oscDelta.start();

      // Save references
      specimenAudioRef.current = {
        alpha: { oscillator: oscAlpha, filter: lpAlpha, gain: gainAlpha, pan: panAlpha },
        beta: { noise: noiseBeta, filter: lpBeta, gain: gainBeta, pan: panBeta },
        gamma: { oscillator: oscGamma, filter: lpGamma, gain: gainGamma, pan: panGamma },
        delta: { oscillator: oscDelta, filter: lpDelta, gain: gainDelta, pan: panDelta }
      };

      // Connect HTML5 mediaPlayer node to this audio graph if it exists
      if (mediaPlayerRef.current && !mediaSourceNodeRef.current) {
        const audioSource = ctx.createMediaElementSource(mediaPlayerRef.current);
        const flowAnalyser = ctx.createAnalyser();
        flowAnalyser.fftSize = 64;
        audioSource.connect(flowAnalyser);
        flowAnalyser.connect(masterGain);

        mediaSourceNodeRef.current = audioSource;
        flowMediaAnalyserRef.current = flowAnalyser;
      }

      addLog("[AUDIO] Summing synthesizer active. 4 specimen coupled generators connected.");
    } catch (e) {
      console.error("Failed to construct coupled audio bus", e);
    }
  };

  /* =========================
     AUDIO MODULATION DRIVER (SPATIAL COUPLING)
  ========================= */
  useEffect(() => {
    if (!audioContextRef.current) return;

    const ctx = audioContextRef.current;
    const nodes = specimenAudioRef.current;

    SPECIMENS.forEach((s) => {
      const node = nodes[s.id];
      if (node) {
        const rawE = thermalEnergy[s.id];
        const coords = specimenCoords[s.id] || { x: 0.0, y: 0.0 };
        const rawX = coords.x;

        // --- LEVEL 15/16 FORENSIC INSTRUMENTING TRACE ---
        if (!Number.isFinite(rawE)) {
          console.error(`[AUDIT] ELY-FIELD: Non-finite thermal energy detected on specimen ${s.id.toUpperCase()}`, {
            rawE,
            thermalEnergy,
            time
          });
        }
        if (!Number.isFinite(rawX)) {
          console.error(`[AUDIT] ELY-FIELD: Non-finite coordinate X detected on specimen ${s.id.toUpperCase()}`, {
            rawX,
            coords,
            specimenCoords,
            phases: phasesRef.current,
            time
          });
        }

        const e = isNaN(rawE) || !isFinite(rawE) ? 0.1 : rawE;
        const x = isNaN(rawX) || !isFinite(rawX) ? 0.0 : rawX;

        // Apply dynamic coupling gain limits based on the specimen configuration
        let maxGain = 0.08;
        let baseCutoff = 80.0;
        let sweepRange = 400.0;

        if (s.id === "alpha") {
          maxGain = 0.28;
          baseCutoff = 40.0;
          sweepRange = 180.0;
        } else if (s.id === "beta") {
          maxGain = 0.15;
          baseCutoff = 120.0;
          sweepRange = 1200.0;
        } else if (s.id === "delta") {
          maxGain = 0.04;
          baseCutoff = 400.0;
          sweepRange = 4500.0;
        }

        node.gain.gain.setTargetAtTime(e * maxGain, ctx.currentTime, 0.1);
        node.filter.frequency.setTargetAtTime(baseCutoff + e * sweepRange, ctx.currentTime, 0.15);
        node.pan.pan.setTargetAtTime(Math.min(1.0, Math.max(-1.0, x * 2.0)), ctx.currentTime, 0.1);
      }
    });
  }, [time, thermalEnergy, specimenCoords]);

  /* =========================
     ADAPTIVE THERMODYNAMIC INTEGRATION PHYSICS LOOP
  ========================= */
  useEffect(() => {
    if (!isPlaying) return;

    physicsClockRef.current = performance.now();
    let animId: number;

    const loop = () => {
      const now = performance.now();
      const dt = (now - physicsClockRef.current) / 1000;
      physicsClockRef.current = now;

      // Telemetry state sampling
      setDeltaTime(dt);
      if (dt > 0) {
        setFps(prev => Math.round(prev * 0.95 + (1 / dt) * 0.05));
      }

      // Delta time stabilization safety boundary
      const MAX_DT = 0.05;
      const clampedDt = Math.min(dt, MAX_DT);

      // --- FLOW MUSIC WAVEFORM INJECTION VALUE ---
      let instantMediaAmp = 0.0;
      if (flowMediaAnalyserRef.current && isSongPlaying) {
        const dataArr = new Uint8Array(flowMediaAnalyserRef.current.frequencyBinCount);
        flowMediaAnalyserRef.current.getByteFrequencyData(dataArr);
        let ampSum = 0;
        for (let i = 0; i < dataArr.length; i++) {
          ampSum += dataArr[i];
        }
        instantMediaAmp = (ampSum / dataArr.length) / 255.0; // scale to [0, 1]
        setFlowAmplitude(instantMediaAmp);
      }

      // --- LEVEL 13/14: ADAPTIVE LANDSCAPE (DEFORMING FIELD & ATTR DRIFT) ---
      const nextBasinDepths = { ...basinDepths };
      const nextBasinCenters = { ...basinCenters };

      BASINS_BASE.forEach((b) => {
        let activeInfluenceSum = 0.0;
        let weightedCenterX = 0.0;
        let weightedCenterY = 0.0;

        // Sum specimen proximity to evaluate "consolidation focus"
        SPECIMENS.forEach((s) => {
          if (activeSpecimens[s.id]) {
            const p = specimenCoords[s.id];
            const currentCenter = basinCenters[b.id];
            const dx = p.x - currentCenter.x;
            const dy = p.y - currentCenter.y;
            const distSq = dx * dx + dy * dy;
            const inf = Math.exp(-distSq / 0.04);

            activeInfluenceSum += inf;
            weightedCenterX += p.x * inf;
            weightedCenterY += p.y * inf;
          }
        });

        // 1. Saturated Basin Deepening with Diminishing Hebbian returns
        const currentD = basinDepths[b.id];
        const MaxWellDepth = 2.5;
        const saturationFactor = Math.max(0.01, 1.0 - (currentD / MaxWellDepth)); // Diminishing returns scaling
        const localConsolidation = activeInfluenceSum * 0.08 * landscapeAdaptationRate * saturationFactor;
        const decay = -0.04 * (currentD - b.baseDepth);
        const dDepth = localConsolidation + decay;

        // Ridge flattening via audio wave transient pressure
        const audioRidgeFlattening = instantMediaAmp * 0.35;
        const targetDepth = Math.min(MaxWellDepth, Math.max(0.1, currentD + clampedDt * speedMultiplier * dDepth));
        nextBasinDepths[b.id] = Math.max(0.05, targetDepth - audioRidgeFlattening);

        // 2. Level 14 Field Plasticity: Active Basin Center Drift (semantic attraction shift)
        if (activeInfluenceSum > 0.01) {
          const currentCenter = basinCenters[b.id];
          const targetCX = weightedCenterX / activeInfluenceSum;
          const targetCY = weightedCenterY / activeInfluenceSum;

          // Drift velocity scaled by landscape morph rate, with weak elastic spring pulling back to baseline
          const driftRate = 0.05 * landscapeAdaptationRate;
          const springK = 0.015;
          const dCx = driftRate * (targetCX - currentCenter.x) - springK * (currentCenter.x - b.x);
          const dCy = driftRate * (targetCY - currentCenter.y) - springK * (currentCenter.y - b.y);

          nextBasinCenters[b.id] = {
            x: currentCenter.x + clampedDt * speedMultiplier * dCx,
            y: currentCenter.y + clampedDt * speedMultiplier * dCy
          };
        }
      });
      setBasinDepths(nextBasinDepths);
      setBasinCenters(nextBasinCenters);

      // --- LEVEL 13/14: HIERARCHICAL CREATIVE MOMENTUM (PERSISTENCE INTEGRATOR) ---
      const nextMomentum = { ...creativeMomentum };
      SPECIMENS.forEach((s) => {
        const currentM = creativeMomentum[s.id];
        const temp = thermalEnergy[s.id];
        const p = specimenCoords[s.id];

        // Find closest attractor center to calculate spatial "persistence duration"
        let minBasinDistSq = 999.0;
        Object.values(nextBasinCenters).forEach((c) => {
          const dx = p.x - c.x;
          const dy = p.y - c.y;
          const dSq = dx * dx + dy * dy;
          if (dSq < minBasinDistSq) minBasinDistSq = dSq;
        });
        // Coherence Persistence Factor: higher as the specimen sits closer to any attractor center
        const proximityCoherence = Math.exp(-minBasinDistSq / 0.02);

        // Momentum equation incorporates both instant energy intensity and continuous stability duration
        const dM = 0.35 * temp + 0.25 * proximityCoherence - 0.08 * (currentM - 1.0);
        nextMomentum[s.id] = Math.min(3.0, Math.max(0.4, currentM + clampedDt * speedMultiplier * dM));
      });
      setCreativeMomentum(nextMomentum);

