            // Localized core center particle glow
            float core = smoothstep(0.025 + u_entropies[i] * 0.015, 0.0, dist);
            col += core * u_colors[i] * (0.4 + u_entropies[i] * 0.6);

            // Dynamic expansion thermal ripples
            float wave = sin(dist * 40.0 - u_time * (1.5 + u_entropies[i] * 4.0)) * 0.5 + 0.5;
            float envelope = smoothstep(u_masses[i] * 0.8, u_masses[i] * 0.8 - 0.01, dist) 
                           * (1.0 - smoothstep(u_masses[i] * 0.7, u_masses[i] * 0.8, dist));
            col += envelope * wave * u_colors[i] * u_entropies[i] * 0.35;
          }
        }

        // Bounded normalization
        float normalizedField = totalInfluence / (1.0 + totalWeight);

        // Project overlapping spatial wave interference
        if (normalizedField > 0.05) {
          float interference = sin(normalizedField * 22.0 - u_time * 2.0) * 0.5 + 0.5;
          col += vec3(0.0, 0.45, 0.65) * interference * (normalizedField * 0.22);
        }

        // High frequency ice noise map
        float noise = hash(uv * 8.0 + u_time * 0.1);
        col += vec3(0.5, 0.75, 1.0) * noise * (1.0 - clamp(normalizedField, 0.0, 1.0)) * 0.03;

        // Dark edge ambient vignette
        col *= 1.0 - length(p) * 0.7;

        gl_FragColor = vec4(col, 1.0);
      }
    `;

