                    <div className="flex items-center gap-3">
                      {/* Interactive toggle switch */}
                      <button 
                        onClick={() => {
                          setActiveSpecimens(prev => ({ ...prev, [s.id]: !prev[s.id] }));
                          addLog(`INTERPOLATE FIELD: Toggle specimen ${s.id.toUpperCase()}`);
                        }}
                        className={`text-[9px] px-1.5 py-0.5 rounded font-bold border transition-all ${isActive ? "bg-cyan-950/30 border-cyan-500/50 text-cyan-400" : "bg-red-950/20 border-red-950/50 text-red-500"}`}
                      >
                        {isActive ? "ACTIVE" : "MUTED"}
                      </button>
                      <div className="flex-1 h-2 bg-black/60 border border-cyan-950/30 rounded overflow-hidden relative">
                        <div 
                          className="h-full transition-all duration-100" 
                          style={{ 
                            width: `${ent * 100}%`, 
                            backgroundColor: `rgb(${s.color.map(c => c * 255).join(',')})` 
                          }} 
                        />
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* SYSTEM LOG / TELEMETRY LOG STRIP */}
          <div className="flex-1 flex flex-col justify-end">
            <div className="border-b border-cyan-950/30 pb-2 mb-2 text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
              <Terminal className="w-3.5 h-3.5 text-cyan-400" />
              STOCHASTIC INTEGRATOR OUTPUT
            </div>
            <div className="bg-black/50 border border-cyan-950/40 rounded p-3 h-48 overflow-y-auto flex flex-col-reverse gap-1.5 text-[10px] font-mono pr-2 scrollbar-thin scrollbar-thumb-cyan-950">
              {log.map((entry, idx) => (
                <div 
                  key={idx} 
                  className={`leading-relaxed border-l-2 pl-2 ${entry.includes("WARNING") || entry.includes("ERROR") || entry.includes("CEILING") ? "border-red-500 text-red-400" : entry.includes("PHASE") || entry.includes("COUPLING") || entry.includes("PLASTICITY") || entry.includes("INJECT") || entry.includes("LANDSPACE") || entry.includes("VORTEX") || entry.includes("BRANCH") || entry.includes("EXCHANGE") || entry.includes("DRIFT") || entry.includes("BOUNDARY") ? "border-orange-500 text-orange-400" : entry.includes("ACOUSTIC") || entry.includes("MANIFOLD RESET") ? "border-cyan-400 text-[#a0aab5]" : "border-cyan-950/30 text-[#697480]"}`}
                >
                  {entry}
                </div>
              ))}
            </div>
          </div>

        </div>

      </div>
    </div>
  );
}

