type IngestionState = "NOT LOADED" | "LOADING" | "VALIDATED" | "REJECTED";
type ScannerState = "NOT CONNECTED" | "SCANNING" | "RECONCILED" | "PCM_DECODED" | "FINGERPRINTED" | "FAILED";

interface EvidenceSchema {
  corpus_id?: string;
  version?: string;
  total_records?: number;
  timestamp?: string;
  reconciledClips?: number;
  fingerprintHash?: string;
  [key: string]: unknown;
}

interface ScannedFileInfo {
  name: string;
  size: number;
  hash: string;
  pcmStatus: "DECODED" | "FAILED";
}

export default function Component() {
  // Build 1 Curator State
  const [corpus, setCorpus] = useState<CorpusItem[]>(INITIAL_CORPUS);
  const [selectedId, setSelectedId] = useState<string>("CORPUS-001");
  const [searchQuery, setSearchQuery] = useState("");
  const [gateFilter, setGateFilter] = useState<string>("ALL");
  const [roomFilter, setRoomFilter] = useState<string>("ALL");
  const [activeProtocolStep, setActiveProtocolStep] = useState<number>(3);
  const [isPlaying, setIsPlaying] = useState(false);

  // Build 2 Ingestion Gate State
  const [ingestionState, setIngestionState] = useState<IngestionState>("NOT LOADED");
  const [jsonFileName, setJsonFileName] = useState<string | null>(null);
  const [evidenceData, setEvidenceData] = useState<EvidenceSchema | null>(null);
  const [jsonValidationError, setJsonValidationError] = useState<string | null>(null);
  const jsonFileInputRef = useRef<HTMLInputElement | null>(null);

  // Audio Corpus Directory Scanner State
  const [scannerState, setScannerState] = useState<ScannerState>("NOT CONNECTED");
  const [discoveredFilesCount, setDiscoveredFilesCount] = useState<number>(0);
  const [fileBreakdown, setFileBreakdown] = useState<{ audio: number; lyrics: number; json: number; images: number }>({ audio: 0, lyrics: 0, json: 0, images: 0 });
  const [reconciledCount, setReconciledCount] = useState<string | number>("NOT MEASURED");
  const [audioDecodedCount, setAudioDecodedCount] = useState<string | number>("NOT MEASURED");
  const [fingerprintedCount, setFingerprintedCount] = useState<string | number>("NOT MEASURED");
  const [scanError, setScanError] = useState<string | null>(null);
  const [scannedFileRecords, setScannedFileRecords] = useState<ScannedFileInfo[]>([]);
  const corpusDirectoryRef = useRef<HTMLInputElement | null>(null);

  const selectedItem = useMemo(() => {
    return corpus.find(item => item.id === selectedId) || corpus[0];
  }, [corpus, selectedId]);

  const filteredCorpus = useMemo(() => {
    return corpus.filter(item => {
      const matchesSearch = searchQuery === "" || 
        item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.physicalAnchor.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.lyricSnippet.toLowerCase().includes(searchQuery.toLowerCase());

      const matchesGate = gateFilter === "ALL" || item.gate === gateFilter;
      const matchesRoom = roomFilter === "ALL" || item.room.startsWith(roomFilter);

      return matchesSearch && matchesGate && matchesRoom;
    });
  }, [corpus, searchQuery, gateFilter, roomFilter]);

  const handleAuditAction = (decision: "Freeze" | "Demote" | "Advance" | "UnfreezeAll") => {
    setCorpus(prev => prev.map(item => {
      if (decision === "UnfreezeAll") {
        return { ...item, status: "In Audit", lastAudited: new Date().toISOString().split("T")[0] };
      }
      if (item.id !== selectedId) return item;
      if (decision === "Freeze") {
        return { ...item, gate: "G5", status: "Frozen (G5)", lastAudited: new Date().toISOString().split("T")[0] };
      }
      if (decision === "Advance") {
        const nextGates: Record<string, CorpusItem["gate"]> = { G1: "G2", G2: "G3", G3: "G4", G4: "G5", G5: "G5" };
        const nextGate = nextGates[item.gate];
        return { 
          ...item, 
          gate: nextGate, 
          status: nextGate === "G5" ? "Frozen (G5)" : "In Audit",
          lastAudited: new Date().toISOString().split("T")[0] 
        };
      }
      if (decision === "Demote") {
        const prevGates: Record<string, CorpusItem["gate"]> = { G5: "G4", G4: "G3", G3: "G2", G2: "G1", G1: "G1" };
        return { 
          ...item, 
          gate: prevGates[item.gate], 
          status: "In Audit",
          lastAudited: new Date().toISOString().split("T")[0] 
        };
      }
      return item;
    }));
  };

  // Build 2 Evidence JSON Reader with Record-Level Triage & Cure Diagnosis
  const handleJsonFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setJsonFileName(file.name);
    setIngestionState("LOADING");
    setJsonValidationError(null);
    setEvidenceData(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const json = JSON.parse(text);

        if (typeof json !== "object" || json === null) {
          throw new Error("SCHEMA REJECTED: Payload root must be a non-null JSON object or array.");
        }

        // Extract records array (support root array, json.items, json.songs, json.records, or json.clips)
        let records: any[] = [];
        if (Array.isArray(json)) {
          records = json;
        } else if (Array.isArray(json.songs)) {
          records = json.songs;
        } else if (Array.isArray(json.items)) {
          records = json.items;
        } else if (Array.isArray(json.records)) {
          records = json.records;
        } else if (Array.isArray(json.clips)) {
          records = json.clips;
        }

        // Evaluate G1-G5 Triage & Cure Status for each record in the JSON
        const triagedItems: CorpusItem[] = records.map((rec, idx) => {
          const title = rec.title || rec.name || `Track ${idx + 1}`;
          const lyricText = rec.lyrics || rec.lyricSnippet || rec.text || "";
          const physicalAnchor = rec.physicalAnchor || rec.anchor || (rec.localPath ? `Path: ${rec.localPath}` : "Physical anchor unverified");

          // Cure / Triage Heuristics
          let gate: CorpusItem["gate"] = "G1";
          let status: CorpusItem["status"] = "Pending G1";

          const hasLyrics = lyricText.length > 10;
          const hasAnchor = physicalAnchor && !physicalAnchor.includes("unverified");
          const isG5Locked = rec.gate === "G5" || rec.status === "Frozen (G5)" || (hasLyrics && hasAnchor);

          if (isG5Locked) {
            gate = "G5";
            status = "Frozen (G5)";
          } else if (hasLyrics && !hasAnchor) {
            gate = "G2";
            status = "In Audit"; // Cure Required for missing anchor
          } else if (!hasLyrics) {
            gate = "G1";
            status = "Quarantined";
          }

          return {
            id: rec.id || `CORPUS-${String(idx + 1).padStart(3, "0")}`,
            code: rec.code || `C${String(idx + 1).padStart(2, "0")}-${gate}`,
            title,
            gate,
            room: rec.room || "Room 02 (Vacuum)",
            witnessPillar: rec.witnessPillar || "Domestic",
            morphologyClass: rec.morphologyClass || "Class A",
            physicalAnchor,
            lyricSnippet: lyricText.slice(0, 120) || "No lyric transcript present",
            clipsCount: rec.clipsCount || 1,
            status,
            lastAudited: new Date().toISOString().split("T")[0]
          };
        });

        if (triagedItems.length > 0) {
          setCorpus(triagedItems);
          setSelectedId(triagedItems[0].id);
        }

        setEvidenceData(json as EvidenceSchema);
        setIngestionState("VALIDATED");
      } catch (err) {
        setIngestionState("REJECTED");
        setJsonValidationError(err instanceof Error ? err.message : "Failed to parse JSON file.");
      }
    };

    reader.onerror = () => {
      setIngestionState("REJECTED");
      setJsonValidationError("I/O Error reading selected file.");
    };

    reader.readAsText(file);
  };

  // Audio Directory Scanner Handler with File Classification & Real-Time Progress Updates
  const handleDirectoryChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);

    if (!files.length) {
      setScannerState("FAILED");
      setScanError("No local files selected.");
      return;
    }

    setScannerState("SCANNING");
    setScanError(null);
    setDiscoveredFilesCount(files.length);
    setScannedFileRecords([]);

    // Categorize discovered files
    const audioFiles = files.filter(f => /\.(mp3|wav|flac|m4a|aac|ogg|webm)$/i.test(f.name));
    const lyricFiles = files.filter(f => /\.(txt|lrc|md)$/i.test(f.name));
    const jsonFiles = files.filter(f => /\.json$/i.test(f.name));
    const imageFiles = files.filter(f => /\.(png|jpg|jpeg|webp)$/i.test(f.name));

    setFileBreakdown({
      audio: audioFiles.length,
      lyrics: lyricFiles.length,
      json: jsonFiles.length,
      images: imageFiles.length
    });

    setReconciledCount(audioFiles.length);
    setAudioDecodedCount(0);
    setFingerprintedCount(0);

    if (audioFiles.length === 0) {
      setScannerState("RECONCILED");
      return;
    }

    // Process audio files in async batches with live UI state updates
    let decodedCount = 0;
    let hashedCount = 0;
    const records: ScannedFileInfo[] = [];
    const maxProcess = Math.min(audioFiles.length, 100); // Process up to 100 audio specimens for performance

    for (let i = 0; i < maxProcess; i++) {
      const file = audioFiles[i];
      let isPcmDecoded = false;
      let hashHex = "PENDING";

      try {
        const buffer = await file.arrayBuffer();

        // Web Audio API PCM Audio Decode
        try {
          const audioCtx = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
          await audioCtx.decodeAudioData(buffer.slice(0));
          decodedCount++;
          isPcmDecoded = true;
          await audioCtx.close();
        } catch {
          isPcmDecoded = false;
        }

        // Byte-level SHA-256 File Hash
        const digest = await crypto.subtle.digest("SHA-256", buffer);
        const hashArray = Array.from(new Uint8Array(digest));
        hashHex = hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
        if (hashHex.length > 0) {
          hashedCount++;
        }
      } catch {
        // Handle unreadable files
      }

      records.push({
        name: file.name,
        size: file.size,
        hash: hashHex.slice(0, 16) + "...",
        pcmStatus: isPcmDecoded ? "DECODED" : "FAILED"
      });

      // Update live UI metrics after every file processed
      setAudioDecodedCount(decodedCount);
      setFingerprintedCount(hashedCount);
    }

    setScannedFileRecords(records);

    if (decodedCount === maxProcess && maxProcess > 0) {
      setScannerState("FINGERPRINTED");
    } else {
      setScannerState("RECONCILED");
    }
  };

  const handleExportTelemetryJson = () => {
    const telemetryManifest = {
      timestamp: new Date().toISOString(),
      system: "ELYZARETH OS v38.0",
      scanner_state: scannerState,
      discovered_files: discoveredFilesCount,
      reconciled_audio_files: reconciledCount,
      pcm_decoded_count: audioDecodedCount,
      file_hashed_count: fingerprintedCount,
      records: scannedFileRecords
    };

    const blob = new Blob([JSON.stringify(telemetryManifest, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `elyzareth_telemetry_${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col font-mono text-xs selection:bg-cyan-500 selection:text-slate-950">

      {/* Hidden Native File Inputs */}
      <input 
        type="file" 
        ref={jsonFileInputRef}
        onChange={handleJsonFileChange}
        accept=".json,application/json" 
        className="hidden" 
      />
      <input
        type="file"
        ref={(el) => {
          corpusDirectoryRef.current = el;
          if (el) {
            el.setAttribute("webkitdirectory", "");
            el.setAttribute("directory", "");
          }
        }}
        onChange={handleDirectoryChange}
        multiple
        className="hidden"
      />

      {/* Top OS Header */}
      <header className="border-b border-slate-800 bg-slate-900/80 px-4 py-2.5 flex flex-wrap items-center justify-between gap-3 sticky top-0 z-20 backdrop-blur">
        <div className="flex items-center gap-3">
          <div className="flex items-center justify-center w-7 h-7 rounded bg-cyan-950 border border-cyan-500/40 text-cyan-400">
            <Database className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-bold text-slate-100 text-sm tracking-wide">LYRICS CORPUS CURATOR</span>
              <span className="px-1.5 py-0.5 rounded text-[10px] bg-cyan-950 text-cyan-400 border border-cyan-800 font-semibold">
                ELYZARETH OS v38.0
              </span>
            </div>
            <p className="text-[10px] text-slate-400">327 Songs / 711 Clips Master Catalog • Immutable Witness Vault</p>
          </div>
        </div>

        {/* Telemetry Metrics */}
        <div className="flex items-center gap-4 bg-slate-950/60 border border-slate-800 px-3 py-1.5 rounded">
          <div className="flex items-center gap-1.5 text-slate-300">
            <Activity className="w-3.5 h-3.5 text-emerald-400" />
            <span>Mode: <strong className="text-emerald-400">3.2.1.0 Protocol</strong></span>
          </div>
          <div className="h-3 w-px bg-slate-800" />
          <div className="flex items-center gap-1.5 text-slate-300">
            <Lock className="w-3.5 h-3.5 text-amber-400" />
            <span>G5 Master Lock: <strong className="text-amber-400">ELYZARETH_FINAL/</strong></span>
          </div>
          <div className="h-3 w-px bg-slate-800" />
          <div className="flex items-center gap-1.5 text-slate-300">
            <ShieldCheck className="w-3.5 h-3.5 text-cyan-400" />
            <span>Witness Rules: <strong className="text-cyan-400">ACTIVE</strong></span>
          </div>
        </div>
      </header>

      {/* Main Grid */}
      <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-0">

        {/* Left Column: Filter Sidebar & List (5 cols) */}
        <div className="lg:col-span-5 border-r border-slate-800 flex flex-col bg-slate-900/40">

          {/* Controls Header */}
          <div className="p-3 border-b border-slate-800 flex flex-col gap-2.5 bg-slate-900/60">
            <div className="relative">
              <Search className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-slate-500" />
              <input
                type="text"
                placeholder="Search corpus, lyrics, anchors, codes..."
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded pl-8 pr-3 py-1.5 text-xs text-slate-200 placeholder-slate-500 focus:outline-none focus:border-cyan-500/60 transition"
              />
            </div>

            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-1 text-[11px] text-slate-400">
                <Filter className="w-3 h-3 text-cyan-400" />
                <span>Gate:</span>
                <select
                  value={gateFilter}
                  onChange={e => setGateFilter(e.target.value)}
                  className="bg-slate-950 border border-slate-800 text-slate-300 text-xs rounded px-2 py-0.5 focus:outline-none focus:border-cyan-500"
                >
                  <option value="ALL">ALL GATES</option>
                  <option value="G1">G1 (Lyric Witness)</option>
                  <option value="G2">G2 (Style Affordance)</option>
                  <option value="G3">G3 (Performance)</option>
                  <option value="G4">G4 (Production Env)</option>
                  <option value="G5">G5 (Release Lock)</option>
                </select>
              </div>

              <div className="flex items-center gap-1 text-[11px] text-slate-400">
                <span>Room:</span>
                <select
                  value={roomFilter}
                  onChange={e => setRoomFilter(e.target.value)}
                  className="bg-slate-950 border border-slate-800 text-slate-300 text-xs rounded px-2 py-0.5 focus:outline-none focus:border-cyan-500"
                >
                  <option value="ALL">ALL ROOMS</option>
                  <option value="Room 01">Room 01 (Shared)</option>
                  <option value="Room 02">Room 02 (Vacuum)</option>
                  <option value="Room 03">Room 03 (Control)</option>
                  <option value="Room 04">Room 04 (Memory)</option>
                  <option value="Room 05">Room 05 (Rustic)</option>
                  <option value="Room 06">Room 06 (Blank)</option>
                </select>
              </div>
            </div>
          </div>

          {/* List Items */}
          <div className="flex-1 overflow-y-auto divide-y divide-slate-800/60">
            {filteredCorpus.length === 0 ? (
              <div className="p-8 text-center text-slate-500">
                No corpus records matching current triage criteria.
              </div>
            ) : (
              filteredCorpus.map(item => {
                const isSelected = item.id === selectedId;
                return (
                  <div
                    key={item.id}
                    onClick={() => setSelectedId(item.id)}
                    className={`p-3 cursor-pointer transition flex flex-col gap-1.5 hover:bg-slate-800/40 ${
                      isSelected ? "bg-slate-800/70 border-l-2 border-l-cyan-400" : ""
