                    <div className="flex items-center justify-between text-[10px] text-slate-500 pt-1">
                      <span className="flex items-center gap-1 text-slate-400">
                        <Tag className="w-2.5 h-2.5 text-cyan-400" />
                        {item.room}
                      </span>
                      <span className="flex items-center gap-1 text-slate-400">
                        <Compass className="w-2.5 h-2.5 text-emerald-400" />
                        {item.witnessPillar}
                      </span>
                      <span>{item.clipsCount} clips</span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Right Column: Detailed Triage & Build 2 Evidence Pipeline Dashboard (7 cols) */}
        <div className="lg:col-span-7 flex flex-col bg-slate-950 overflow-y-auto">

          {/* Header of Selected Item */}
          <div className="p-4 border-b border-slate-800 bg-slate-900/60 flex flex-wrap items-center justify-between gap-3">
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs font-mono text-cyan-400 font-bold">{selectedItem.id}</span>
                <span className="text-xs text-slate-600">•</span>
                <span className="text-base font-bold text-slate-100">{selectedItem.title}</span>
              </div>
              <p className="text-xs text-slate-400 mt-0.5">Physical Anchor: <span className="text-slate-200">{selectedItem.physicalAnchor}</span></p>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => setIsPlaying(!isPlaying)}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-cyan-600 hover:bg-cyan-500 text-slate-950 font-bold transition shadow-sm"
              >
                {isPlaying ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5 fill-current" />}
                <span>{isPlaying ? "HALT AUDIT" : "3.2.1.0 LISTEN"}</span>
              </button>
            </div>
          </div>

          <div className="p-4 flex flex-col gap-5">

            {/* AUDIO CORPUS DIRECTORY SCANNER */}
            <div className="p-4 rounded-lg bg-slate-900 border border-emerald-900/60 flex flex-col gap-3">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <div>
                  <div className="font-bold text-emerald-400 text-xs tracking-wider flex items-center gap-2">
                    <Folder className="w-4 h-4 text-emerald-400" />
                    AUDIO CORPUS DIRECTORY SCANNER
                  </div>
                  <div className="text-[10px] text-slate-500 mt-0.5">
                    Pass-3 Client-Side Evidence Layer • Immutable 360 Baseline • PCM Validation Gate
                  </div>
                </div>

                <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${
                  scannerState === "FINGERPRINTED"
                    ? "bg-emerald-950 text-emerald-400 border-emerald-800"
                    : scannerState === "RECONCILED"
                    ? "bg-cyan-950 text-cyan-400 border-cyan-800"
                    : scannerState === "SCANNING"
                    ? "bg-purple-950 text-purple-400 border-purple-800 animate-pulse"
                    : scannerState === "FAILED"
                    ? "bg-rose-950 text-rose-400 border-rose-800"
                    : "bg-slate-950 text-slate-400 border-slate-800"
                }`}>
                  {scannerState}
                </span>
              </div>

              {/* Action Buttons */}
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={() => corpusDirectoryRef.current?.click()}
                  className="px-3.5 py-1.5 rounded bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-bold transition shadow-sm flex items-center gap-1.5"
                >
                  <Folder className="w-3.5 h-3.5" />
                  <span>Select Corpus Directory</span>
                </button>

                <button
                  onClick={handleExportTelemetryJson}
                  disabled={scannerState !== "FINGERPRINTED" && scannerState !== "RECONCILED"}
                  className="px-3.5 py-1.5 rounded bg-blue-600 hover:bg-blue-500 text-white font-bold disabled:opacity-40 transition flex items-center gap-1.5 shadow-sm"
                >
                  <Download className="w-3.5 h-3.5" />
                  <span>Export Telemetry JSON</span>
                </button>
              </div>

              {/* Metrics Grid */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2 pt-1">
                <div className="p-2.5 rounded bg-slate-950 border border-slate-800 flex flex-col gap-0.5">
                  <div className="text-[9px] text-slate-500 font-bold">FILES DISCOVERED</div>
                  <div className="text-base font-bold text-slate-100">{discoveredFilesCount}</div>
                </div>

                <div className="p-2.5 rounded bg-slate-950 border border-slate-800 flex flex-col gap-0.5">
                  <div className="text-[9px] text-slate-500 font-bold">RECONCILED</div>
                  <div className="text-base font-bold text-cyan-400">{reconciledCount}</div>
                </div>

                <div className="p-2.5 rounded bg-slate-950 border border-slate-800 flex flex-col gap-0.5">
                  <div className="text-[9px] text-slate-500 font-bold">PCM DECODED</div>
                  <div className="text-base font-bold text-emerald-400">{audioDecodedCount}</div>
                </div>

                <div className="p-2.5 rounded bg-slate-950 border border-slate-800 flex flex-col gap-0.5">
                  <div className="text-[9px] text-slate-500 font-bold">FILE HASHED (SHA-256)</div>
                  <div className="text-base font-bold text-amber-400">{fingerprintedCount}</div>
                </div>
              </div>

              {scanError && (
                <div className="p-2 rounded bg-rose-950/40 border border-rose-800 text-rose-300 text-xs">
                  {scanError}
                </div>
              )}

              <div className="text-[10px] text-slate-500 italic">
                Physical evidence remains NOT MEASURED until actual local audio files are selected and successfully decoded.
              </div>
            </div>

            {/* BUILD 2: PHYSICAL EVIDENCE JSON INGESTION GATE */}
            <div className="p-4 rounded-lg bg-slate-900 border border-slate-800 flex flex-col gap-3">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <div className="flex items-center gap-2">
                  <FileJson className="w-4 h-4 text-purple-400" />
                  <span className="font-bold text-slate-200 text-xs tracking-wider">BUILD 2: EVIDENCE JSON INGESTION GATE</span>
                </div>
                <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${
                  ingestionState === "VALIDATED"
                    ? "bg-emerald-950 text-emerald-400 border-emerald-800"
                    : ingestionState === "REJECTED"
                    ? "bg-rose-950 text-rose-400 border-rose-800"
                    : ingestionState === "LOADING"
                    ? "bg-cyan-950 text-cyan-400 border-cyan-800 animate-pulse"
                    : "bg-slate-950 text-slate-400 border-slate-800"
                }`}>
                  {ingestionState}
                </span>
              </div>

              {/* Native Input Controls */}
              <div className="flex flex-wrap items-center justify-between gap-3 bg-slate-950 p-3 rounded border border-slate-800/80">
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => jsonFileInputRef.current?.click()}
                    className="flex items-center gap-2 px-3 py-1.5 bg-purple-600 hover:bg-purple-500 text-slate-950 font-bold rounded transition shadow-sm"
                  >
                    <Upload className="w-3.5 h-3.5" />
                    <span>Import Evidence JSON</span>
                  </button>
                  <span className="text-[11px] text-slate-400 italic">
                    {jsonFileName ? jsonFileName : "No local file selected"}
                  </span>
                </div>

                <div className="text-[10px] text-slate-500">
                  Native Input: <code className="text-slate-300">&lt;input type="file" accept=".json"&gt;</code>
                </div>
              </div>

              {/* Schema Validation Feedback */}
              {ingestionState === "VALIDATED" && evidenceData && (
                <div className="p-3 bg-emerald-950/40 border border-emerald-800/60 rounded text-emerald-300 text-xs flex flex-col gap-1.5">
                  <div className="flex items-center gap-1.5 font-bold text-emerald-400">
                    <Check className="w-4 h-4" />
                    <span>JSON_VALIDATED • Physical Payload Schema Intact</span>
                  </div>
                  <pre className="text-[10px] bg-slate-950 p-2 rounded border border-emerald-900/60 text-slate-300 overflow-x-auto max-h-32 font-mono">
                    {JSON.stringify(evidenceData, null, 2)}
                  </pre>
                  <p className="text-[10px] text-slate-400 italic pt-1">
                    🔒 Build 1 Curator baseline and downstream audio states remain unchanged during validation test.
                  </p>
                </div>
              )}

              {ingestionState === "REJECTED" && (
                <div className="p-3 bg-rose-950/40 border border-rose-800/60 rounded text-rose-300 text-xs flex flex-col gap-1.5">
                  <div className="flex items-center gap-1.5 font-bold text-rose-400">
                    <XCircle className="w-4 h-4" />
                    <span>JSON_REJECTED • Evidence Verification Failure</span>
                  </div>
                  <p className="text-[11px] text-rose-200">{jsonValidationError}</p>
                </div>
              )}

              {ingestionState === "NOT LOADED" && (
                <div className="p-2.5 bg-slate-950/60 border border-slate-800 rounded text-[11px] text-slate-400 flex items-center gap-2">
                  <AlertOctagon className="w-4 h-4 text-amber-400 flex-shrink-0" />
                  <span>Evidence JSON = NOT LOADED • Physical evidence = NOT MEASURED • Gate = LOCKED 🔒</span>
                </div>
              )}
            </div>

            {/* 3.2.1.0 Protocol Triage Box */}
            <div className="p-4 rounded-lg bg-slate-900 border border-slate-800 flex flex-col gap-3">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <div className="flex items-center gap-2">
                  <Zap className="w-4 h-4 text-emerald-400" />
                  <span className="font-bold text-slate-200 text-xs tracking-wider">3.2.1.0 VALIDATION PROTOCOL (BUILD 1 CURATOR)</span>
                </div>
                <span className="text-[10px] text-slate-500">Listen • Evaluate • Decide • Freeze</span>
              </div>

              {/* Protocol Step Indicators */}
              <div className="grid grid-cols-4 gap-2 py-1">
                {[
                  { step: 3, name: "3. LISTEN", desc: "Acoustic Audit" },
                  { step: 2, name: "2. EVALUATE", desc: "Witness Constraints" },
                  { step: 1, name: "1. DECIDE", desc: "Gate Alignment" },
                  { step: 0, name: "0. FREEZE", desc: "G5 Lock" }
                ].map(s => {
                  const isActive = activeProtocolStep === s.step;
                  return (
                    <button
                      key={s.step}
                      onClick={() => setActiveProtocolStep(s.step)}
                      className={`p-2 rounded text-left border transition flex flex-col gap-0.5 ${
                        isActive
                          ? "bg-cyan-950/80 border-cyan-500 text-cyan-300"
                          : "bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-700"
                      }`}
                    >
                      <span className="font-bold text-[11px]">{s.name}</span>
                      <span className="text-[9px] text-slate-500">{s.desc}</span>
                    </button>
                  );
                })}
              </div>

              {/* Step Content Explanation */}
              <div className="p-3 bg-slate-950 rounded border border-slate-800/80 text-xs text-slate-300">
                {activeProtocolStep === 3 && (
                  <p>🔊 <strong>3. LISTEN (Audit Phase):</strong> Forensic STFT/FFT spectral centroid inspection for renderer temporal attractors and dry transient purity without decorative reverb.</p>
                )}
                {activeProtocolStep === 2 && (
                  <p>🔍 <strong>2. EVALUATE (Witness Constraint Gate):</strong> Grounding check. Verify zero poetic abstract tropes. Enforce concrete physical objects as sole witnesses.</p>
                )}
                {activeProtocolStep === 1 && (
                  <p>⚖️ <strong>1. DECIDE (Triage Alignment):</strong> Confirm room categorization ({selectedItem.room}) and morphological class ({selectedItem.morphologyClass}).</p>
                )}
                {activeProtocolStep === 0 && (
                  <p>❄️ <strong>0. FREEZE (G5 Release Lock):</strong> Commit master release to <code className="text-amber-400 font-mono">ELYZARETH_FINAL/</code>. Immutable source protection.</p>
                )}
              </div>

              {/* Protocol Actions */}
              <div className="flex items-center justify-end gap-2 pt-1">
                <button
                  onClick={() => handleAuditAction("Demote")}
                  className="px-3 py-1.5 rounded bg-rose-950/60 text-rose-300 border border-rose-800/60 hover:bg-rose-900/60 font-semibold transition"
                >
                  Demote Gate
                </button>
                <button
                  onClick={() => handleAuditAction("Advance")}
                  className="px-3 py-1.5 rounded bg-cyan-950/60 text-cyan-300 border border-cyan-800/60 hover:bg-cyan-900/60 font-semibold transition"
                >
                  Advance Gate
                </button>
                <button
                  onClick={() => handleAuditAction("Freeze")}
                  className="px-3 py-1.5 rounded bg-amber-500 text-slate-950 font-bold hover:bg-amber-400 transition flex items-center gap-1.5"
                >
                  <Lock className="w-3 h-3" />
                  FREEZE MASTER (G5)
                </button>
              </div>
            </div>

            {/* Lyric Corpus Transcript & Witness Constraints */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

              {/* Lyrics Box */}
              <div className="p-3.5 rounded-lg bg-slate-900 border border-slate-800 flex flex-col gap-2">
                <div className="flex items-center justify-between border-b border-slate-800 pb-1.5">
                  <span className="font-bold text-slate-200 text-xs flex items-center gap-1.5">
                    <FileText className="w-3.5 h-3.5 text-cyan-400" />
                    G1 LYRIC WITNESS
                  </span>
                  <span className="text-[10px] text-emerald-400 font-mono">VERIFIED</span>
                </div>
                <div className="bg-slate-950 p-3 rounded border border-slate-800/60 text-xs font-serif leading-relaxed text-slate-200 italic">
                  "{selectedItem.lyricSnippet}"
                </div>
                <div className="text-[10px] text-slate-500 flex justify-between pt-1">
                  <span>Pillar: <strong className="text-slate-300">{selectedItem.witnessPillar}</strong></span>
                  <span>Clips: <strong className="text-slate-300">{selectedItem.clipsCount}</strong></span>
                </div>
              </div>

              {/* Acoustic & Morphological Attributes */}
              <div className="p-3.5 rounded-lg bg-slate-900 border border-slate-800 flex flex-col gap-2.5">
                <div className="flex items-center justify-between border-b border-slate-800 pb-1.5">
                  <span className="font-bold text-slate-200 text-xs flex items-center gap-1.5">
                    <BarChart2 className="w-3.5 h-3.5 text-amber-400" />
                    ACOUSTIC MORPHOLOGY
                  </span>
                  <span className="text-[10px] text-cyan-400 font-mono">{selectedItem.morphologyClass}</span>
                </div>

                <div className="flex flex-col gap-2 text-xs">
                  <div className="flex justify-between items-center bg-slate-950 p-2 rounded border border-slate-800">
                    <span className="text-slate-400">Curator Room:</span>
                    <span className="font-bold text-cyan-400">{selectedItem.room}</span>
                  </div>
                  <div className="flex justify-between items-center bg-slate-950 p-2 rounded border border-slate-800">
                    <span className="text-slate-400">Physical Anchor:</span>
                    <span className="font-bold text-emerald-400 text-right truncate max-w-[180px]">{selectedItem.physicalAnchor}</span>
                  </div>
                  <div className="flex justify-between items-center bg-slate-950 p-2 rounded border border-slate-800">
                    <span className="text-slate-400">Last Audit Lock:</span>
                    <span className="font-mono text-slate-300">{selectedItem.lastAudited}</span>
                  </div>
                </div>
              </div>

            </div>

            {/* 5-Gate Triage Pipeline Visualizer */}
            <div className="p-3.5 rounded-lg bg-slate-900 border border-slate-800 flex flex-col gap-2.5">
              <span className="font-bold text-slate-200 text-xs flex items-center gap-1.5">
                <Layers className="w-3.5 h-3.5 text-cyan-400" />
                5-GATE NON-DESTRUCTIVE TRIAGE PIPELINE
              </span>

              <div className="grid grid-cols-5 gap-1.5 text-center pt-1">
                {[
                  { g: "G1", title: "Lyric Witness" },
                  { g: "G2", title: "Style Affordance" },
                  { g: "G3", title: "Performance" },
                  { g: "G4", title: "Production Env" },
                  { g: "G5", title: "Release Lock" }
                ].map((gateInfo, idx) => {
                  const gates = ["G1", "G2", "G3", "G4", "G5"];
                  const currentIdx = gates.indexOf(selectedItem.gate);
                  const isPassed = idx <= currentIdx;
                  const isCurrent = idx === currentIdx;

                  return (
                    <div
                      key={gateInfo.g}
                      className={`p-2 rounded border flex flex-col items-center gap-1 transition ${
                        isCurrent
                          ? "bg-cyan-950 border-cyan-400 text-cyan-200"
                          : isPassed
                          ? "bg-slate-950 border-emerald-800 text-emerald-400"
                          : "bg-slate-950/40 border-slate-800 text-slate-600"
                      }`}
                    >
                      <span className="font-bold text-xs">{gateInfo.g}</span>
                      <span className="text-[9px] line-clamp-1">{gateInfo.title}</span>
                      {isPassed && <CheckCircle2 className="w-3 h-3 text-emerald-400 mt-1" />}
                    </div>
                  );
                })}
              </div>
            </div>

          </div>
        </div>

      </div>
    </div>
  );
}

