  // Audio Canvas Visualizer
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let bars = 64;
    const draw = () => {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = "rgba(39, 39, 42, 0.4)";
      ctx.lineWidth = 1;
      for (let x = 0; x < width; x += 20) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = 0; y < height; y += 15) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      const barWidth = (width / bars) - 2;

      for (let i = 0; i < bars; i++) {
        let barHeight = 0;
        if (isPlaying) {
          const freq = Math.sin((Date.now() / 150) + i * 0.2) * 0.4 + 0.5;
          const noise = Math.random() * 0.3;
          barHeight = (freq + noise) * (height * 0.75);
        } else {
          barHeight = (Math.sin(i * 0.15) * 0.1 + 0.15) * height;
        }

        const x = i * (barWidth + 2);
        const y = height - barHeight;

        // Gradient bar
        const gradient = ctx.createLinearGradient(0, height, 0, 0);
        if (activeSpecimen.status === "VERIFIED") {
          gradient.addColorStop(0, "rgba(34, 197, 94, 0.2)");
          gradient.addColorStop(1, "rgba(34, 197, 94, 0.9)");
        } else if (activeSpecimen.status === "IMPLEMENTED/UNVERIFIED") {
          gradient.addColorStop(0, "rgba(234, 179, 8, 0.2)");
          gradient.addColorStop(1, "rgba(234, 179, 8, 0.9)");
        } else {
          gradient.addColorStop(0, "rgba(59, 130, 246, 0.2)");
          gradient.addColorStop(1, "rgba(59, 130, 246, 0.9)");
        }

        ctx.fillStyle = gradient;
        ctx.fillRect(x, y, barWidth, barHeight);

        // Cap indicator
        ctx.fillStyle = activeSpecimen.status === "VERIFIED" ? "#4ade80" : "#60a5fa";
        ctx.fillRect(x, y - 2, barWidth, 2);
      }

      animFrameRef.current = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
