      return prev.map(w => w.id === appId ? { ...w, zIndex: maxZ + 1, isMinimized: false } : w);
    });
  };

  const handleToggleWindow = (appId: AppId) => {
    setWindows(prev => {
      const win = prev.find(w => w.id === appId);
      if (!win) return prev;

      if (!win.isOpen) {
        const maxZ = Math.max(...prev.map(w => w.zIndex), 1);
        return prev.map(w => w.id === appId ? { ...w, isOpen: true, isMinimized: false, zIndex: maxZ + 1 } : w);
      } else if (win.isMinimized) {
        const maxZ = Math.max(...prev.map(w => w.zIndex), 1);
        return prev.map(w => w.id === appId ? { ...w, isMinimized: false, zIndex: maxZ + 1 } : w);
      } else if (activeAppId === appId) {
        return prev.map(w => w.id === appId ? { ...w, isMinimized: true } : w);
      } else {
        const maxZ = Math.max(...prev.map(w => w.zIndex), 1);
        return prev.map(w => w.id === appId ? { ...w, zIndex: maxZ + 1 } : w);
      }
    });
