}

import React, { useState } from 'react';
import { Shield, CheckCircle2, AlertTriangle, Clock, Key, FileCheck, Lock, Unlock, Server, Download } from 'lucide-react';
import { GateStatus, VerificationState } from '../types';

interface GovernanceAppProps {
  gates: GateStatus[];
  onUpdateGateState: (gateId: string, state: VerificationState) => void;
}

export default function GovernanceApp({ gates, onUpdateGateState }: GovernanceAppProps) {
  const [selectedGate, setSelectedGate] = useState<GateStatus>(gates[0]);
  const [shaInput, setShaInput] = useState('');
  const [auditLog, setAuditLog] = useState<string[]>([
    '[2026-09-14 08:12:00 UTC] G1 Witness transformation contract locked.',
    '[2026-09-14 09:30:15 UTC] G2 Read-Only evaluator zero-bypass confirmed.',
    '[2026-09-14 10:45:22 UTC] G3 Vocal naturalness stress testing verified (P01).',
    '[2026-09-14 11:10:00 UTC] G4 SPACE-006C integrity check initialized.'
  ]);

  const getStateBadge = (state: VerificationState) => {
    switch (state) {
      case 'VERIFIED':
        return <span className="px-2 py-0.5 text-xs bg-emerald-500/20 text-emerald-400 border border-emerald-500/40 rounded flex items-center gap-1 font-mono"><CheckCircle2 className="w-3 h-3" /> VERIFIED</span>;
      case 'IMPLEMENTED/UNVERIFIED':
        return <span className="px-2 py-0.5 text-xs bg-amber-500/20 text-amber-400 border border-amber-500/40 rounded flex items-center gap-1 font-mono"><Clock className="w-3 h-3" /> UNVERIFIED</span>;
      case 'FAILED':
        return <span className="px-2 py-0.5 text-xs bg-red-500/20 text-red-400 border border-red-500/40 rounded flex items-center gap-1 font-mono"><AlertTriangle className="w-3 h-3" /> FAILED</span>;
      case 'NOT_MEASURED':
        return <span className="px-2 py-0.5 text-xs bg-purple-500/20 text-purple-400 border border-purple-500/40 rounded flex items-center gap-1 font-mono"><Server className="w-3 h-3" /> NOT_MEASURED</span>;
      default:
        return <span className="px-2 py-0.5 text-xs bg-slate-700 text-slate-300 rounded font-mono">SPEC</span>;
    }
  };

  const handleVerifyHash = () => {
    if (!shaInput.trim()) return;
    const isMatch = shaInput.trim().toLowerCase() === selectedGate.witnessHash?.toLowerCase();
    const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 19) + ' UTC';
    if (isMatch) {
      onUpdateGateState(selectedGate.id, 'VERIFIED');
      setAuditLog(prev => [`[${timestamp}] Dual-Witness Match for ${selectedGate.id}: Verification PASSED`, ...prev]);
    } else {
      setAuditLog(prev => [`[${timestamp}] Dual-Witness Hash mismatch for ${selectedGate.id}: Invalid witness payload`, ...prev]);
    }
  };

  return (
    <div className="h-full bg-slate-950 text-slate-100 p-4 font-sans flex flex-col gap-4 overflow-y-auto">
      {/* Header Banner */}
      <div className="flex items-center justify-between border-b border-slate-800 pb-3">
        <div className="flex items-center gap-2">
          <Shield className="w-6 h-6 text-emerald-400" />
          <div>
            <h2 className="text-lg font-semibold tracking-wide text-slate-100 font-mono">MASTER GOVERNANCE REGISTRY</h2>
            <p className="text-xs text-slate-400">G1–G5 Static Integrity Gates & Verification Engine</p>
          </div>
        </div>
        <div className="flex items-center gap-2 text-xs font-mono bg-slate-900 px-3 py-1.5 rounded border border-slate-800 text-emerald-400">
          <Lock className="w-3.5 h-3.5" /> G1-G5 STRICT BYPASS DISABLED
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 flex-1">
        {/* Gates List */}
        <div className="bg-slate-900 border border-slate-800 rounded p-3 flex flex-col gap-2">
          <h3 className="text-xs font-mono font-semibold text-slate-400 uppercase tracking-wider mb-1">Stage Gates (Zero-Bypass)</h3>
          {gates.map(gate => {
            const isSelected = selectedGate.id === gate.id;
            return (
              <button
                key={gate.id}
                onClick={() => setSelectedGate(gate)}
                className={`p-3 rounded text-left border transition-all flex flex-col gap-1.5 ${
                  isSelected 
                    ? 'bg-slate-800/80 border-emerald-500/50 text-slate-100 shadow-md' 
                    : 'bg-slate-950/40 border-slate-800/80 hover:bg-slate-800/40 text-slate-300'
                }`}
              >
                <div className="flex items-center justify-between">
                  <span className="font-mono text-sm font-bold text-emerald-400">{gate.id}</span>
                  {getStateBadge(gate.state)}
                </div>
                <p className="text-xs font-medium text-slate-200">{gate.name}</p>
                <p className="text-[11px] text-slate-400 line-clamp-1 font-mono">{gate.witnessHash || 'No witness hash'}</p>
              </button>
            );
          })}
        </div>

        {/* Gate Details & Witness Inspector */}
        <div className="md:col-span-2 flex flex-col gap-4">
          <div className="bg-slate-900 border border-slate-800 rounded p-4 flex flex-col gap-3">
            <div className="flex items-center justify-between border-b border-slate-800 pb-2">
              <div>
                <span className="text-xs font-mono text-emerald-400 font-bold">{selectedGate.id} GATE SPECIFICATION</span>
                <h3 className="text-base font-semibold text-slate-100">{selectedGate.name}</h3>
              </div>
              {getStateBadge(selectedGate.state)}
            </div>

            <p className="text-xs text-slate-300 bg-slate-950 p-2.5 rounded border border-slate-800 font-sans">
              {selectedGate.description}
            </p>

            <div className="grid grid-cols-2 gap-3 text-xs font-mono">
              <div className="bg-slate-950 p-2.5 rounded border border-slate-800">
                <span className="text-slate-400 block text-[10px]">LAST AUDITED</span>
                <span className="text-slate-200">{selectedGate.lastAudited}</span>
              </div>
              <div className="bg-slate-950 p-2.5 rounded border border-slate-800">
                <span className="text-slate-400 block text-[10px]">STATE AUTHORIZATION</span>
                <span className="text-emerald-400 font-bold">HUMAN GOVERNOR LOCKED</span>
              </div>
            </div>

            {/* SHA-256 Dual Witness Audit Section */}
            <div className="mt-2 pt-3 border-t border-slate-800 flex flex-col gap-2">
              <label className="text-xs font-mono font-medium text-slate-300 flex items-center gap-1.5">
                <Key className="w-3.5 h-3.5 text-amber-400" /> DUAL-WITNESS SHA-256 BINARY AUDIT
              </label>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="Enter or paste witness SHA-256 hash to verify..."
                  value={shaInput}
                  onChange={e => setShaInput(e.target.value)}
                  className="flex-1 bg-slate-950 border border-slate-800 rounded px-3 py-1.5 text-xs font-mono text-slate-200 focus:outline-none focus:border-emerald-500"
                />
                <button
                  onClick={handleVerifyHash}
                  className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-mono rounded flex items-center gap-1 font-medium transition-colors"
                >
                  <FileCheck className="w-3.5 h-3.5" /> VERIFY WITNESS
                </button>
              </div>
              <div className="flex gap-2 mt-1">
                <button
                  onClick={() => onUpdateGateState(selectedGate.id, 'VERIFIED')}
                  className="px-2.5 py-1 bg-emerald-950/60 hover:bg-emerald-900/60 text-emerald-400 border border-emerald-800 text-[11px] font-mono rounded"
                >
                  FORCE STATE: VERIFIED
                </button>
                <button
                  onClick={() => onUpdateGateState(selectedGate.id, 'IMPLEMENTED/UNVERIFIED')}
                  className="px-2.5 py-1 bg-amber-950/60 hover:bg-amber-900/60 text-amber-400 border border-amber-800 text-[11px] font-mono rounded"
                >
                  FORCE STATE: UNVERIFIED
                </button>
                <button
                  onClick={() => onUpdateGateState(selectedGate.id, 'FAILED')}
                  className="px-2.5 py-1 bg-red-950/60 hover:bg-red-900/60 text-red-400 border border-red-800 text-[11px] font-mono rounded"
                >
                  FORCE STATE: FAILED
                </button>
              </div>
            </div>
          </div>

          {/* Audit Telemetry Log */}
          <div className="bg-slate-900 border border-slate-800 rounded p-3 flex flex-col gap-1.5">
            <div className="flex items-center justify-between">
              <h4 className="text-xs font-mono text-slate-400 uppercase tracking-wider">Gate Audit Telemetry Stream</h4>
              <button
                onClick={() => {
                  const blob = new Blob([auditLog.join('\n')], { type: 'text/plain' });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement('a');
                  a.href = url;
                  a.download = 'audit-log.txt';
                  a.click();
                  URL.revokeObjectURL(url);
                }}
                className="px-2 py-0.5 text-[10px] font-mono bg-slate-800 hover:bg-slate-700 text-slate-300 rounded border border-slate-700 flex items-center gap-1 transition-colors"
              >
                <Download className="w-3 h-3" /> EXPORT LOG
              </button>
            </div>
            <div className="bg-slate-950 p-2.5 rounded border border-slate-800 font-mono text-[11px] text-slate-300 h-28 overflow-y-auto space-y-1">
              {auditLog.map((log, i) => (
                <div key={i} className="text-slate-300">{log}</div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

