    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Activity, Play, Square, Hash, Cpu, BarChart2, ShieldCheck, AlertCircle } from 'lucide-react';
import { CorpusTrack } from '../types';

interface ForensicScannerAppProps {
  tracks: CorpusTrack[];
  selectedTrack: CorpusTrack;
  onSelectTrack: (track: CorpusTrack) => void;
}

export default function ForensicScannerApp({ tracks, selectedTrack, onSelectTrack }: ForensicScannerAppProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [scanProgress, setScanProgress] = useState(100);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const oscRef = useRef<OscillatorNode | null>(null);
  const gainRef = useRef<GainNode | null>(null);

  // Draw simulated FFT and PCM waveform canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let phase = 0;

    const render = () => {
      ctx.fillStyle = '#020617';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid lines
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let x = 0; x < canvas.width; x += 30) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 20) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      // Draw PCM Waveform
      ctx.beginPath();
      ctx.strokeStyle = isPlaying ? '#10b981' : '#06b6d4';
      ctx.lineWidth = 1.5;

      const midY = canvas.height / 2;
      for (let x = 0; x < canvas.width; x++) {
        const freq = selectedTrack.bpm / 30;
        const amp = isPlaying ? 35 : 18;
        const noise = (Math.sin(x * 0.05 + phase) * Math.cos(x * 0.02 - phase)) * amp;
        const y = midY + noise + (Math.sin((x + phase * 10) * 0.1) * 8);

        if (x === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();

      // FFT Spectral Bars at bottom
      ctx.fillStyle = isPlaying ? 'rgba(16, 185, 129, 0.3)' : 'rgba(6, 182, 212, 0.2)';
      const barCount = 32;
      const barWidth = canvas.width / barCount;
      for (let i = 0; i < barCount; i++) {
        const barHeight = Math.abs(Math.sin(i * 0.3 + phase * 2)) * (canvas.height * 0.4);
        ctx.fillRect(i * barWidth, canvas.height - barHeight, barWidth - 2, barHeight);
      }

      phase += isPlaying ? 0.08 : 0.02;
      animId = requestAnimationFrame(render);
    };

    render();
    return () => cancelAnimationFrame(animId);
  }, [isPlaying, selectedTrack]);

  const togglePlayback = () => {
    if (isPlaying) {
      if (oscRef.current) {
        oscRef.current.stop();
        oscRef.current.disconnect();
      }
      setIsPlaying(false);
    } else {
      try {
        const ctx = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
        audioCtxRef.current = ctx;

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        // Synth tone matching Room 05 dry acoustic frequency (warm drone ~130Hz)
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(130.81, ctx.currentTime); // C3 tone

        gain.gain.setValueAtTime(0.001, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.1);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start();
        oscRef.current = osc;
        gainRef.current = gain;
        setIsPlaying(true);
      } catch (err) {
        console.error('AudioContext error', err);
        setIsPlaying(true);
      }
    }
  };

  return (
    <div className="h-full bg-slate-950 text-slate-100 p-4 font-sans flex flex-col gap-4 overflow-y-auto">
      {/* App Header */}
      <div className="flex items-center justify-between border-b border-slate-800 pb-3">
        <div className="flex items-center gap-2">
          <Activity className="w-6 h-6 text-cyan-400" />
          <div>
            <h2 className="text-lg font-semibold tracking-wide text-slate-100 font-mono">BUILD 2 FORENSIC AUDIO SCANNER</h2>
            <p className="text-xs text-slate-400">Web Audio API PCM Decoding, FFT Spectral Analysis & SHA-256 Hashing</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={togglePlayback}
            className={`px-3 py-1.5 rounded font-mono text-xs flex items-center gap-1.5 font-semibold transition-all ${
              isPlaying 
                ? 'bg-red-950 text-red-400 border border-red-800 hover:bg-red-900' 
                : 'bg-emerald-600 text-white hover:bg-emerald-500'
            }`}
          >
            {isPlaying ? <Square className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
            {isPlaying ? 'STOP TONE' : 'AUDITION SPECIMEN'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Track Selector & Specimen Stats */}
        <div className="bg-slate-900 border border-slate-800 rounded p-3 flex flex-col gap-2">
          <h3 className="text-xs font-mono font-semibold text-slate-400 uppercase tracking-wider mb-1">Target Specimen</h3>
          {tracks.map(t => (
            <button
              key={t.id}
              onClick={() => onSelectTrack(t)}
              className={`p-2.5 rounded text-left border text-xs font-mono transition-all ${
                t.id === selectedTrack.id
                  ? 'bg-slate-800 border-cyan-500 text-slate-100'
                  : 'bg-slate-950/40 border-slate-800/80 hover:bg-slate-800/40 text-slate-300'
              }`}
            >
              <div className="font-semibold text-cyan-300">{t.title}</div>
              <div className="text-[10px] text-slate-400 mt-0.5">SHA: {t.sha256.substring(0, 14)}...</div>
            </button>
          ))}
        </div>

        {/* Real-time PCM Waveform & Spectrum Display */}
        <div className="md:col-span-2 flex flex-col gap-4">
          <div className="bg-slate-900 border border-slate-800 rounded p-4 flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-mono text-cyan-400 font-bold flex items-center gap-1">
                <BarChart2 className="w-3.5 h-3.5" /> REAL-TIME PCM WAVEFORM & FFT SPECTRAL DENSITY
              </span>
              <span className="text-xs font-mono text-slate-400">SAMPLE RATE: {selectedTrack.pcmSampleRate} Hz</span>
            </div>

            {/* Canvas */}
            <div className="relative rounded overflow-hidden border border-slate-800">
              <canvas ref={canvasRef} width={600} height={180} className="w-full h-44 bg-slate-950 block" />
              <div className="absolute top-2 left-2 text-[10px] font-mono bg-slate-900/80 px-2 py-0.5 rounded border border-slate-800 text-slate-300">
                DR RATIO: +{selectedTrack.drRatioDb} dB | RT60: {selectedTrack.t60DecayMs}ms
              </div>
            </div>

            {/* Envelope Morphology & Acoustic Physics Parameters */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-xs font-mono mt-1">
              <div className="bg-slate-950 p-2.5 rounded border border-slate-800">
                <span className="text-slate-400 block text-[10px]">ENVELOPE CLASS</span>
                <span className={`font-bold ${selectedTrack.envelopeClass === 'Class A' ? 'text-emerald-400' : 'text-amber-400'}`}>
                  {selectedTrack.envelopeClass}
                </span>
              </div>
              <div className="bg-slate-950 p-2.5 rounded border border-slate-800">
                <span className="text-slate-400 block text-[10px]">T60 DECAY</span>
                <span className="text-slate-200">{selectedTrack.t60DecayMs} ms</span>
              </div>
              <div className="bg-slate-950 p-2.5 rounded border border-slate-800">
                <span className="text-slate-400 block text-[10px]">D/R RATIO</span>
                <span className="text-slate-200">+{selectedTrack.drRatioDb} dB</span>
              </div>
              <div className="bg-slate-950 p-2.5 rounded border border-slate-800">
