interface CorpusCuratorAppProps {
  tracks: CorpusTrack[];
  onUpdateTrackLyrics: (trackId: string, lyrics: string, witnessObjects: string[]) => void;
}

export default function CorpusCuratorApp({ tracks, onUpdateTrackLyrics }: CorpusCuratorAppProps) {
  const [selectedTrackId, setSelectedTrackId] = useState<string>(tracks[0].id);
  const selectedTrack = tracks.find(t => t.id === selectedTrackId) || tracks[0];

  const [lyricsText, setLyricsText] = useState(selectedTrack.lyrics);
  const [witnessObjects, setWitnessObjects] = useState<string[]>(selectedTrack.witnessObjects);
  const [newObjectInput, setNewObjectInput] = useState('');
  const [metaphorWarning, setMetaphorWarning] = useState<string | null>(null);

  const handleSelectTrack = (track: CorpusTrack) => {
    setSelectedTrackId(track.id);
    setLyricsText(track.lyrics);
    setWitnessObjects(track.witnessObjects);
    setMetaphorWarning(null);
  };

  const handleLyricsChange = (text: string) => {
    setLyricsText(text);
    // Check for prohibited metaphor soup / glossy production language
    const forbiddenWords = ['cinematic', 'soaring', 'glossy', 'ocean of tears', 'fire in my soul', 'shatter the sky'];
    const matched = forbiddenWords.filter(w => text.toLowerCase().includes(w));
    if (matched.length > 0) {
      setMetaphorWarning(`PROHIBITED PHRASE DETECTED: "${matched.join(', ')}". Rejecting metaphor soup to enforce G1 witness constraints.`);
    } else {
      setMetaphorWarning(null);
    }
  };

  const handleAddWitnessObject = () => {
    if (!newObjectInput.trim()) return;
    if (witnessObjects.includes(newObjectInput.trim())) return;
    const updated = [...witnessObjects, newObjectInput.trim()];
    setWitnessObjects(updated);
    setNewObjectInput('');
    onUpdateTrackLyrics(selectedTrack.id, lyricsText, updated);
  };

  const handleRemoveWitnessObject = (obj: string) => {
    const updated = witnessObjects.filter(o => o !== obj);
    setWitnessObjects(updated);
    onUpdateTrackLyrics(selectedTrack.id, lyricsText, updated);
  };

  return (
    <div className="h-full bg-slate-950 text-slate-100 p-4 font-sans flex flex-col gap-4 overflow-y-auto">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-slate-800 pb-3">
        <div className="flex items-center gap-2">
          <BookOpen className="w-6 h-6 text-purple-400" />
          <div>
            <h2 className="text-lg font-semibold tracking-wide text-slate-100 font-mono">LYRICS & WITNESS OBJECT CURATOR</h2>
            <p className="text-xs text-slate-400">Physical Anchor Principle & Zero-Metaphor Verification Engine</p>
          </div>
        </div>
        <div className="text-xs font-mono bg-purple-950/60 text-purple-300 border border-purple-800 px-3 py-1.5 rounded flex items-center gap-1.5">
          <Lock className="w-3.5 h-3.5" /> PHYSICAL WITNESS RULE ACTIVE
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Track List */}
        <div className="bg-slate-900 border border-slate-800 rounded p-3 flex flex-col gap-2">
          <h3 className="text-xs font-mono font-semibold text-slate-400 uppercase tracking-wider mb-1">Lyrics Library</h3>
          {tracks.map(t => (
            <button
              key={t.id}
              onClick={() => handleSelectTrack(t)}
              className={`p-2.5 rounded text-left border text-xs font-mono transition-all ${
                t.id === selectedTrack.id
                  ? 'bg-slate-800 border-purple-500 text-slate-100'
                  : 'bg-slate-950/40 border-slate-800/80 hover:bg-slate-800/40 text-slate-300'
              }`}
            >
              <div className="font-semibold text-purple-300">{t.title}</div>
              <div className="text-[10px] text-slate-400 mt-0.5">{t.witnessObjects.length} Physical Witnesses</div>
            </button>
          ))}
        </div>

        {/* Lyrics & Physical Witness Inspector */}
        <div className="md:col-span-2 flex flex-col gap-4">
          <div className="bg-slate-900 border border-slate-800 rounded p-4 flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-mono text-purple-400 font-bold flex items-center gap-1">
                <FileText className="w-3.5 h-3.5" /> LYRICS WITNESS TEXT
              </span>
              <span className="text-xs font-mono text-slate-400">CORPUS #{selectedTrack.corpusNum}</span>
            </div>

            {metaphorWarning && (
              <div className="bg-red-950/80 border border-red-700 text-red-200 text-xs p-2.5 rounded flex items-center gap-2 font-mono">
                <XCircle className="w-4 h-4 text-red-400 flex-shrink-0" />
                <span>{metaphorWarning}</span>
              </div>
            )}

            <textarea
              value={lyricsText}
              onChange={e => handleLyricsChange(e.target.value)}
              className="w-full h-36 bg-slate-950 border border-slate-800 rounded p-3 font-mono text-xs text-slate-200 focus:outline-none focus:border-purple-500 leading-relaxed"
              placeholder="Enter lyrics grounded in physical witness objects..."
            />

            {/* Physical Witness Objects Tags */}
            <div className="mt-2 pt-3 border-t border-slate-800 flex flex-col gap-2">
              <label className="text-xs font-mono text-purple-300 font-semibold flex items-center gap-1">
                <Tag className="w-3.5 h-3.5" /> PHYSICAL WITNESS OBJECT ANCHORS
              </label>
              <div className="flex flex-wrap gap-2">
                {witnessObjects.map(obj => (
                  <span
                    key={obj}
                    className="px-2.5 py-1 bg-purple-950/60 border border-purple-700 text-purple-200 text-xs rounded-full font-mono flex items-center gap-1.5"
                  >
                    {obj}
                    <button
                      onClick={() => handleRemoveWitnessObject(obj)}
                      className="hover:text-red-400 text-purple-400"
                    >
                      ×
                    </button>
                  </span>
                ))}
              </div>

              <div className="flex gap-2 mt-2">
                <input
                  type="text"
                  placeholder="Add physical witness object (e.g. blue thread, stone, coarse salt)..."
                  value={newObjectInput}
                  onChange={e => setNewObjectInput(e.target.value)}
                  className="flex-1 bg-slate-950 border border-slate-800 rounded px-3 py-1 text-xs font-mono text-slate-200 focus:outline-none focus:border-purple-500"
