                <button
                  onClick={handleAddWitnessObject}
                  className="px-3 py-1 bg-purple-700 hover:bg-purple-600 text-white text-xs font-mono rounded flex items-center gap-1"
                >
                  <Plus className="w-3.5 h-3.5" /> ANCHOR OBJECT
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
