import React from 'react';
import { Minus, Square, X, Shield, Layers, Activity, BookOpen, CheckSquare } from 'lucide-react';
import { WindowState } from '../types';

interface WindowProps {
  window: WindowState;
  onClose: () => void;
  onMinimize: () => void;
  onMaximize: () => void;
  onFocus: () => void;
  children: React.ReactNode;
}

export default function Window({
  window,
  onClose,
  onMinimize,
  onMaximize,
  onFocus,
  children
}: WindowProps) {
  if (!window.isOpen || window.isMinimized) return null;

  const getIcon = (iconName: string) => {
    switch (iconName) {
      case 'Shield': return <Shield className="w-4 h-4 text-emerald-400" />;
      case 'Layers': return <Layers className="w-4 h-4 text-amber-400" />;
      case 'Activity': return <Activity className="w-4 h-4 text-cyan-400" />;
      case 'BookOpen': return <BookOpen className="w-4 h-4 text-purple-400" />;
      case 'CheckSquare': return <CheckSquare className="w-4 h-4 text-emerald-400" />;
      default: return <Shield className="w-4 h-4 text-slate-400" />;
    }
  };

  const style: React.CSSProperties = window.isMaximized
    ? {
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: '40px',
        zIndex: window.zIndex
      }
    : {
        position: 'absolute',
        top: `${window.position.y}px`,
        left: `${window.position.x}px`,
        width: `${window.size.width}px`,
        height: `${window.size.height}px`,
        zIndex: window.zIndex
      };

  return (
    <div
      onClick={onFocus}
      style={style}
      className="flex flex-col bg-slate-950 border border-slate-800 rounded-lg shadow-2xl overflow-hidden backdrop-blur-md transition-shadow"
    >
      {/* Window Header / Titlebar */}
      <div className="bg-slate-900 border-b border-slate-800 px-3 py-2 flex items-center justify-between select-none cursor-move">
        <div className="flex items-center gap-2 font-mono text-xs font-semibold text-slate-200">
          {getIcon(window.icon)}
          <span>{window.title}</span>
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={(e) => { e.stopPropagation(); onMinimize(); }}
            className="p-1 hover:bg-slate-800 rounded text-slate-400 hover:text-slate-200 transition-colors"
          >
            <Minus className="w-3.5 h-3.5" />
          </button>
          <button
            onClick={(e) => { e.stopPropagation(); onMaximize(); }}
            className="p-1 hover:bg-slate-800 rounded text-slate-400 hover:text-slate-200 transition-colors"
          >
            <Square className="w-3 h-3" />
          </button>
          <button
            onClick={(e) => { e.stopPropagation(); onClose(); }}
            className="p-1 hover:bg-red-950 hover:text-red-400 rounded text-slate-400 transition-colors"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {/* Window Content */}
      <div className="flex-1 overflow-hidden">
        {children}
      </div>
    </div>
  );
}

