import React, { useState } from "react";
import { WindowState, AppId, AppSlotEvent, LifecycleStage } from "./types";
import { APP_REGISTRY } from "./appRegistry";
import { Window } from "./components/Window";
import { Taskbar } from "./components/Taskbar";
import { Desktop } from "./components/Desktop";
import { AppLaunchMenu } from "./components/AppLaunchMenu";

export default function Component() {
  const [windows, setWindows] = useState<WindowState[]>([]);
  const [activeWindowId, setActiveWindowId] = useState<string | null>(null);
  const [zIndexCounter, setZIndexCounter] = useState<number>(100);
  const [isLaunchMenuOpen, setIsLaunchMenuOpen] = useState<boolean>(false);
  const [eventLogs, setEventLogs] = useState<AppSlotEvent[]>([]);

  // Handle event emission from any AppSlot
  const handleEmitEvent = (sourceAppId: string, eventName: string, payload?: Record<string, any>) => {
    const newLog: AppSlotEvent = {
      id: `evt-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
      timestamp: new Date().toISOString(),
      sourceAppId,
      eventName,
      payload
    };
    setEventLogs((prev) => [...prev.slice(-49), newLog]);
  };

  // Launch app or focus/restore existing window
  const handleLaunchApp = (appId: AppId) => {
    const existing = windows.find((w) => w.appId === appId);
    if (existing) {
      handleFocusWindow(existing.id);
      if (existing.isMinimized) {
        setWindows((prev) =>
          prev.map((w) =>
            w.id === existing.id
              ? { ...w, isMinimized: false, lifecycleStage: "restored" }
              : w
          )
        );
      }
      return;
    }

    const appDef = APP_REGISTRY.find((a) => a.id === appId);
    if (!appDef) return;

    const nextZIndex = zIndexCounter + 1;
    setZIndexCounter(nextZIndex);

    // Stagger window initial placement
    const offset = (windows.length % 5) * 24;
    const newWindow: WindowState = {
      id: `win-${appId}-${Date.now()}`,
      appId,
      title: appDef.name,
      x: 60 + offset,
      y: 40 + offset,
      width: appDef.defaultWidth,
      height: appDef.defaultHeight,
      minWidth: 420,
      minHeight: 320,
      zIndex: nextZIndex,
      isMinimized: false,
      isMaximized: false,
      lifecycleStage: "opening"
    };

    setWindows((prev) => [...prev, newWindow]);
    setActiveWindowId(newWindow.id);

    // Transition lifecycle stage: opening -> active
    setTimeout(() => {
      setWindows((prev) =>
        prev.map((w) =>
          w.id === newWindow.id ? { ...w, lifecycleStage: "active" } : w
        )
      );
    }, 100);

    handleEmitEvent(appId, "MODULE_REGISTERED_AND_LAUNCHED", { windowId: newWindow.id });
  };

  const handleFocusWindow = (id: string) => {
    const nextZIndex = zIndexCounter + 1;
    setZIndexCounter(nextZIndex);

    setWindows((prev) =>
      prev.map((w) => {
        if (w.id === id) {
          const stage: LifecycleStage = w.isMinimized ? "restored" : "active";
          return { ...w, zIndex: nextZIndex, isMinimized: false, lifecycleStage: stage };
        } else {
          return { ...w, lifecycleStage: w.isMinimized ? "minimized" : "inactive" };
        }
      })
    );
    setActiveWindowId(id);
  };

  const handleCloseWindow = (id: string) => {
    const closingWindow = windows.find((w) => w.id === id);
    if (closingWindow) {
      handleEmitEvent(closingWindow.appId, "MODULE_TEARDOWN_COMPLETED", { windowId: id });
    }

    setWindows((prev) => prev.filter((w) => w.id !== id));
    if (activeWindowId === id) {
      const remaining = windows.filter((w) => w.id !== id);
      if (remaining.length > 0) {
        const top = remaining.reduce((max, w) => (w.zIndex > max.zIndex ? w : max), remaining[0]);
        setActiveWindowId(top.id);
        setWindows((prev) =>
          prev.map((w) => (w.id === top.id ? { ...w, lifecycleStage: "active" } : w))
        );
      } else {
        setActiveWindowId(null);
      }
    }
  };

  const handleMinimizeWindow = (id: string) => {
    setWindows((prev) =>
      prev.map((w) =>
        w.id === id ? { ...w, isMinimized: true, lifecycleStage: "minimized" } : w
      )
    );
    if (activeWindowId === id) {
      const visible = windows.filter((w) => w.id !== id && !w.isMinimized);
      if (visible.length > 0) {
        const top = visible.reduce((max, w) => (w.zIndex > max.zIndex ? w : max), visible[0]);
        setActiveWindowId(top.id);
        setWindows((prev) =>
          prev.map((w) => (w.id === top.id ? { ...w, lifecycleStage: "active" } : w))
        );
      } else {
        setActiveWindowId(null);
      }
    }
  };

  const handleToggleMinimize = (id: string) => {
    const win = windows.find((w) => w.id === id);
    if (!win) return;
    if (win.isMinimized) {
      handleFocusWindow(id);
    } else {
      handleMinimizeWindow(id);
    }
  };

  const handleMaximizeWindow = (id: string) => {
    setWindows((prev) =>
      prev.map((w) => (w.id === id ? { ...w, isMaximized: !w.isMaximized } : w))
    );
  };

  const handleUpdateBounds = (
    id: string,
    bounds: { x: number; y: number; width: number; height: number }
  ) => {
    setWindows((prev) =>
      prev.map((w) => (w.id === id ? { ...w, ...bounds } : w))
    );
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-slate-950 font-sans antialiased text-slate-100 overflow-hidden select-none">
      {/* Desktop Workspace Container */}
      <div className="relative w-full h-screen flex flex-col justify-between overflow-hidden bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950">

        {/* Ambient Grid Background */}
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#1e293b15_1px,transparent_1px),linear-gradient(to_bottom,#1e293b15_1px,transparent_1px)] bg-[size:32px_32px] pointer-events-none" />

        {/* Desktop Icons Layer */}
        <Desktop onLaunchApp={handleLaunchApp} />

        {/* Floating Windows Area */}
        <div className="relative flex-1 w-full h-full pointer-events-none">
          {windows.map((win) => (
            <div key={win.id} className="pointer-events-auto">
              <Window
                window={win}
                isFocused={win.id === activeWindowId && !win.isMinimized}
                eventLogs={eventLogs}
                onEmitEvent={(evtName, payload) => handleEmitEvent(win.appId, evtName, payload)}
                onFocus={() => handleFocusWindow(win.id)}
                onClose={() => handleCloseWindow(win.id)}
                onMinimize={() => handleMinimizeWindow(win.id)}
                onMaximize={() => handleMaximizeWindow(win.id)}
                onUpdateBounds={(bounds) => handleUpdateBounds(win.id, bounds)}
              />
            </div>
          ))}
        </div>

        {/* Start / Launch Menu */}
        <AppLaunchMenu
          isOpen={isLaunchMenuOpen}
          onClose={() => setIsLaunchMenuOpen(false)}
          onLaunchApp={handleLaunchApp}
        />

        {/* Desktop Taskbar & Dock */}
        <Taskbar
          windows={windows}
          activeWindowId={activeWindowId}
          onToggleLaunchMenu={() => setIsLaunchMenuOpen((prev) => !prev)}
          isLaunchMenuOpen={isLaunchMenuOpen}
          onFocusWindow={handleFocusWindow}
          onToggleMinimize={handleToggleMinimize}
          onLaunchApp={handleLaunchApp}
        />
      </div>
    </div>
  );
}

