export const Window: React.FC<WindowProps> = ({
  window: win,
  isFocused,
  eventLogs,
  onEmitEvent,
  onFocus,
  onClose,
  onMinimize,
  onMaximize,
  onUpdateBounds
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const dragStartRef = useRef<{ mouseX: number; mouseY: number; winX: number; winY: number }>({ mouseX: 0, mouseY: 0, winX: 0, winY: 0 });
  const resizeStartRef = useRef<{ mouseX: number; mouseY: number; winW: number; winH: number }>({ mouseX: 0, mouseY: 0, winW: 0, winH: 0 });

  // Handle Dragging
  const handleHeaderMouseDown = (e: React.MouseEvent) => {
    if (win.isMaximized) return;
    onFocus();
    setIsDragging(true);
    dragStartRef.current = {
      mouseX: e.clientX,
      mouseY: e.clientY,
      winX: win.x,
      winY: win.y
    };
  };

  // Handle Resizing
  const handleResizeMouseDown = (e: React.MouseEvent) => {
    if (win.isMaximized) return;
    e.stopPropagation();
    onFocus();
    setIsResizing(true);
    resizeStartRef.current = {
      mouseX: e.clientX,
      mouseY: e.clientY,
      winW: win.width,
      winH: win.height
    };
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isDragging) {
        const dx = e.clientX - dragStartRef.current.mouseX;
        const dy = e.clientY - dragStartRef.current.mouseY;
        onUpdateBounds({
          x: Math.max(0, dragStartRef.current.winX + dx),
          y: Math.max(0, dragStartRef.current.winY + dy),
          width: win.width,
          height: win.height
        });
      } else if (isResizing) {
        const dw = e.clientX - resizeStartRef.current.mouseX;
        const dh = e.clientY - resizeStartRef.current.mouseY;
        onUpdateBounds({
          x: win.x,
          y: win.y,
          width: Math.max(win.minWidth, resizeStartRef.current.winW + dw),
          height: Math.max(win.minHeight, resizeStartRef.current.winH + dh)
        });
      }
    };

    const handleMouseUp = () => {
      setIsDragging(false);
      setIsResizing(false);
    };

    if (isDragging || isResizing) {
      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", handleMouseUp);
    }
    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDragging, isResizing, win.x, win.y, win.width, win.height, win.minWidth, win.minHeight, onUpdateBounds]);

  if (win.isMinimized) return null;

  const style: React.CSSProperties = win.isMaximized
    ? {
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "calc(100% - 44px)",
        zIndex: win.zIndex
      }
    : {
        position: "absolute",
        top: `${win.y}px`,
        left: `${win.x}px`,
        width: `${win.width}px`,
        height: `${win.height}px`,
        zIndex: win.zIndex
      };

  const slotContext: AppSlotContext = {
    appId: win.appId,
    windowId: win.id,
    isFocused,
    lifecycleStage: win.lifecycleStage,
    zIndex: win.zIndex,
    emitEvent: (eventName, payload) => onEmitEvent(eventName, payload),
    requestClose: onClose,
    requestMinimize: onMinimize,
    requestMaximize: onMaximize,
    eventLogs
  };

  return (
    <div
      onClick={onFocus}
      style={style}
      className={`flex flex-col rounded-xl overflow-hidden border shadow-2xl transition-shadow duration-150 select-none ${
        isFocused
          ? "border-emerald-500/50 shadow-emerald-950/30 bg-slate-950"
          : "border-slate-800 shadow-slate-950/40 bg-slate-950 opacity-95"
      }`}
    >
      {/* Window Titlebar */}
      <div
        onMouseDown={handleHeaderMouseDown}
        onDoubleClick={onMaximize}
        className={`h-9 px-3 flex items-center justify-between border-b cursor-grab active:cursor-grabbing ${
          isFocused ? "bg-slate-900 border-slate-800 text-slate-100" : "bg-slate-900/60 border-slate-800/60 text-slate-400"
        }`}
      >
        <div className="flex items-center gap-2">
          <span className={isFocused ? "text-emerald-400" : "text-slate-500"}>
            {getAppIcon(win.appId)}
          </span>
          <span className="text-xs font-medium tracking-wide truncate">{win.title}</span>
          <span className="text-[10px] font-mono px-1.5 py-0.5 bg-slate-950 border border-slate-800 text-cyan-400 rounded uppercase">
            {win.lifecycleStage}
          </span>
        </div>

        {/* Controls */}
        <div className="flex items-center gap-1" onMouseDown={(e) => e.stopPropagation()}>
          <button
            onClick={onMinimize}
            className="p-1.5 hover:bg-slate-800 text-slate-400 hover:text-slate-200 rounded transition-colors"
            title="Minimize"
          >
            <Minus className="w-3 h-3" />
          </button>
          <button
            onClick={onMaximize}
            className="p-1.5 hover:bg-slate-800 text-slate-400 hover:text-slate-200 rounded transition-colors"
            title={win.isMaximized ? "Restore" : "Maximize"}
          >
            {win.isMaximized ? <Copy className="w-3 h-3" /> : <Square className="w-3 h-3" />}
          </button>
          <button
            onClick={onClose}
            className="p-1.5 hover:bg-red-950 hover:text-red-400 text-slate-400 rounded transition-colors"
            title="Close"
          >
            <X className="w-3 h-3" />
          </button>
        </div>
      </div>

      {/* Window Content Area */}
      <div className="flex-1 overflow-hidden relative">
        <AppContentRouter appId={win.appId} slotContext={slotContext} />
      </div>

      {/* Resize Handle */}
      {!win.isMaximized && (
        <div
          onMouseDown={handleResizeMouseDown}
          className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize flex items-center justify-center text-slate-600 hover:text-emerald-400 transition-colors"
        >
          <div className="w-1.5 h-1.5 border-r border-b border-current mb-0.5 mr-0.5"></div>
        </div>
      )}
    </div>
  );
};

