export const Taskbar: React.FC<TaskbarProps> = ({
  windows,
  activeWindowId,
  onToggleLaunchMenu,
  isLaunchMenuOpen,
  onFocusWindow,
  onToggleMinimize,
  onLaunchApp
}) => {
  const [time, setTime] = useState<string>("");
  const [date, setDate] = useState<string>("");

  useEffect(() => {
    const updateClock = () => {
      const now = new Date();
      setTime(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
      setDate(now.toLocaleDateString([], { month: 'short', day: 'numeric' }));
    };
    updateClock();
    const timer = setInterval(updateClock, 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="h-11 bg-slate-950/90 backdrop-blur-md border-t border-slate-800/80 px-3 flex items-center justify-between z-30 select-none">
      {/* Start Button & Quick Shortcuts */}
      <div className="flex items-center gap-2">
        <button
          onClick={onToggleLaunchMenu}
          className={`px-3 py-1.5 rounded-lg border text-xs font-semibold flex items-center gap-2 transition-all ${
            isLaunchMenuOpen
              ? "bg-emerald-950 border-emerald-600 text-emerald-300 shadow-lg shadow-emerald-950/50"
              : "bg-slate-900 hover:bg-slate-800 border-slate-800 text-slate-200"
          }`}
        >
          <Cpu className="w-4 h-4 text-emerald-400" />
          <span>Elyzareth OS</span>
        </button>

        <div className="h-5 w-px bg-slate-800 mx-1" />

        {/* Quick Launch Icons */}
        <div className="flex items-center gap-1">
          {APP_REGISTRY.map((app) => (
            <button
              key={app.id}
              onClick={() => onLaunchApp(app.id)}
              className="p-1.5 hover:bg-slate-900 border border-transparent hover:border-slate-800 rounded-lg transition-colors"
              title={`Launch ${app.name}`}
            >
              {getTaskbarIcon(app.iconName)}
            </button>
          ))}
        </div>
      </div>

      {/* Running Windows Tabs */}
      <div className="flex-1 flex items-center gap-1.5 px-4 overflow-x-auto no-scrollbar">
        {windows.map((win) => {
          const isActive = win.id === activeWindowId && !win.isMinimized;
          const appDef = APP_REGISTRY.find((a) => a.id === win.appId);
          return (
            <button
              key={win.id}
              onClick={() => {
                if (isActive) {
                  onToggleMinimize(win.id);
                } else {
                  onFocusWindow(win.id);
                }
              }}
              className={`max-w-44 px-3 py-1.5 rounded-lg border text-xs flex items-center gap-2 transition-all truncate ${
                isActive
                  ? "bg-slate-900 border-emerald-500/60 text-emerald-300 font-medium"
                  : win.isMinimized
                  ? "bg-slate-950/40 border-slate-900 text-slate-500 hover:text-slate-300"
                  : "bg-slate-950 border-slate-800/80 text-slate-400 hover:text-slate-200"
              }`}
            >
              {appDef && getTaskbarIcon(appDef.iconName)}
              <span className="truncate">{win.title}</span>
            </button>
          );
        })}
      </div>

      {/* System Tray & Telemetry */}
      <div className="flex items-center gap-3 text-xs font-mono text-slate-400">
        <div className="flex items-center gap-1.5 px-2.5 py-1 bg-slate-900/80 border border-slate-800/80 rounded-lg text-[11px]">
          <CircleDot className="w-3 h-3 text-emerald-400 animate-pulse" />
          <span className="text-slate-300">v38.1</span>
        </div>
        <div className="flex flex-col text-right leading-tight text-[11px]">
          <span className="text-slate-200 font-medium">{time}</span>
          <span className="text-slate-500">{date}</span>
        </div>
      </div>
    </div>
  );
};

