                  setCandidateNotes("Draft #2 selected.");
                  slotContext.emitEvent("CANDIDATE_SELECTED", { candidateId: 2 });
                }}
                className={`p-3 rounded-lg border cursor-pointer transition-all ${
                  selectedCandidate === 2
