import React, { useState, useEffect } from "react";
import { AppProps } from "../types";
import {
  Layers,
  Volume2,
  Activity,
  AlertTriangle,
  CheckCircle2,
  Clock,
  Shield,
  FileText,
  Radio,
  Sliders,
  Send,
  Sparkles,
  Info
} from "lucide-react";

type RoomCategory =
  | "not_measured"
  | "dry_dead"
  | "small_intimate"
  | "natural_balanced"
  | "large_reverberant"
  | "uncontrolled_ambiguous";

type SittingRoomTab = "triage" | "observations" | "signal_input" | "telemetry";

interface AcousticObservation {
  id: string;
  timestamp: string;
  category: RoomCategory;
  characteristic: string;
  confidence: number | null;
  status: "MEASURED" | "NOT_MEASURED";
}

const ROOM_CATEGORY_INFO: Record<
  RoomCategory,
  { name: string; desc: string; acousticTraits: string }
> = {
  not_measured: {
    name: "NOT MEASURED",
    desc: "No audio signal loaded. Measurement suspended to prevent evidence fabrication.",
    acousticTraits: "Awaiting PCM audio signal buffer."
  },
  dry_dead: {
    name: "Dry / Dead Room",
    desc: "Absorptive surfaces, minimal acoustic reflections, dry direct sound path.",
    acousticTraits: "RT60 < 0.2s, high direct-to-reverberant (D/R) ratio, suppressed decay tails."
  },
  small_intimate: {
    name: "Small / Intimate Room",
    desc: "Short early reflections, warm low-mid resonance, proximity emphasis.",
    acousticTraits: "RT60 ~ 0.35s, early reflections < 15ms, dry vocal boundary."
  },
  natural_balanced: {
    name: "Natural / Balanced Room",
    desc: "Symmetrical diffusion, balanced frequency decay, moderate room footprint.",
    acousticTraits: "RT60 ~ 0.6s, linear spectral decay, balanced reverberant field."
  },
  large_reverberant: {
    name: "Large / Reverberant Room",
    desc: "Extended hall reverberation, dense reflection tail, spatial envelopment.",
    acousticTraits: "RT60 > 1.2s, late reflection onset, prominent diffuse field."
  },
  uncontrolled_ambiguous: {
    name: "Uncontrolled / Ambiguous Environment",
    desc: "Irregular flutter echo, phase interference, non-standard acoustic boundaries.",
    acousticTraits: "Irregular decay slope, low inter-aural cross-correlation (IACC)."
  }
};

export const SittingRoom: React.FC<AppProps> = ({ slotContext }) => {
  const [activeTab, setActiveTab] = useState<SittingRoomTab>("triage");
  const [hasSignal, setHasSignal] = useState<boolean>(false);
  const [signalName, setSignalName] = useState<string>("No Signal Loaded");
  const [selectedCategory, setSelectedCategory] = useState<RoomCategory>("not_measured");
  const [characteristicNote, setCharacteristicNote] = useState<string>("Dry room vocal track with 64 BPM tempo anchor.");
  const [observations, setObservations] = useState<AcousticObservation[]>([]);

  // Emit lifecycle open event on mount
  useEffect(() => {
    slotContext.emitEvent("SITTING_ROOM_OPENED", {
      windowId: slotContext.windowId,
      appId: slotContext.appId,
      timestamp: new Date().toISOString()
    });
  }, []);

  const handleTabChange = (tab: SittingRoomTab) => {
    setActiveTab(tab);
    slotContext.emitEvent("SITTING_ROOM_NAVIGATED", {
      windowId: slotContext.windowId,
      destinationTab: tab
    });
  };

  const handleToggleSignal = () => {
    if (!hasSignal) {
      setHasSignal(true);
      setSignalName("Sample Signal: Room05_Rustic_Vocal_64BPM.wav");
      setSelectedCategory("dry_dead");
      slotContext.emitEvent("ROOM_CLASSIFICATION_CHANGED", {
        windowId: slotContext.windowId,
        category: "dry_dead"
      });
    } else {
      setHasSignal(false);
      setSignalName("No Signal Loaded");
      setSelectedCategory("not_measured");
      slotContext.emitEvent("ROOM_CLASSIFICATION_CHANGED", {
        windowId: slotContext.windowId,
        category: "not_measured"
      });
    }
  };

  const handleRecordObservation = () => {
    const newObs: AcousticObservation = {
      id: `obs-${Date.now()}`,
      timestamp: new Date().toISOString(),
      category: selectedCategory,
      characteristic: hasSignal ? characteristicNote : "Measurement suspended: No signal present.",
      confidence: hasSignal ? 0.92 : null,
      status: hasSignal ? "MEASURED" : "NOT_MEASURED"
    };

    setObservations((prev) => [newObs, ...prev]);

    slotContext.emitEvent("ACOUSTIC_OBSERVATION_RECORDED", {
      windowId: slotContext.windowId,
      category: selectedCategory,
      status: newObs.status,
      timestamp: newObs.timestamp
    });
  };

  return (
    <div className="h-full w-full bg-slate-950 text-slate-100 flex flex-col justify-between overflow-hidden select-text font-sans">
      {/* Module Header Bar */}
      <div className="p-3 bg-slate-900/90 border-b border-slate-800 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-2.5">
          <div className="p-2 bg-indigo-950/80 border border-indigo-700/60 rounded-lg text-indigo-400">
            <Layers className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xs font-bold tracking-wide text-slate-100 uppercase font-mono">
                Sitting Room
              </h2>
              <span className="text-[10px] font-mono px-2 py-0.2 bg-slate-950 border border-slate-800 text-indigo-400 rounded">
                App 02
              </span>
            </div>
            <p className="text-[11px] text-slate-400 line-clamp-1">
              Acoustic Environment Triage • 5-Room Classification Module
            </p>
          </div>
        </div>

        {/* Status Indicators */}
        <div className="flex items-center gap-2 text-[10px] font-mono">
          <span className={`px-2 py-0.5 rounded border flex items-center gap-1 ${
            hasSignal ? "bg-emerald-950/80 text-emerald-300 border-emerald-800" : "bg-amber-950/80 text-amber-300 border-amber-800"
          }`}>
            <Radio className="w-3 h-3" />
            <span>{hasSignal ? "SIGNAL ACTIVE" : "NOT MEASURED"}</span>
          </span>
          <span className="px-2 py-0.5 bg-slate-950 border border-slate-800 text-slate-400 rounded">
            ID: {slotContext.windowId}
          </span>
        </div>
      </div>

      {/* Internal Navigation Bar */}
      <div className="px-3 py-1.5 bg-slate-950 border-b border-slate-900 flex items-center gap-1 overflow-x-auto no-scrollbar shrink-0 text-xs font-mono">
        <button
          onClick={() => handleTabChange("triage")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "triage"
              ? "bg-slate-800 text-indigo-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Sliders className="w-3.5 h-3.5 text-indigo-400" />
          <span>Room Triage</span>
        </button>

        <button
          onClick={() => handleTabChange("observations")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "observations"
              ? "bg-slate-800 text-indigo-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <FileText className="w-3.5 h-3.5 text-cyan-400" />
          <span>Witness Logs ({observations.length})</span>
        </button>

        <button
          onClick={() => handleTabChange("signal_input")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "signal_input"
              ? "bg-slate-800 text-indigo-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Volume2 className="w-3.5 h-3.5 text-teal-400" />
          <span>Audio Input</span>
        </button>

        <button
          onClick={() => handleTabChange("telemetry")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "telemetry"
              ? "bg-slate-800 text-indigo-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Activity className="w-3.5 h-3.5 text-emerald-400" />
          <span>Telemetry</span>
        </button>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 overflow-y-auto p-4 font-sans relative">
        {activeTab === "triage" && (
          <div className="space-y-4">
            {/* NOT MEASURED Safety Warning Banner */}
            {!hasSignal && (
              <div className="p-3 bg-amber-950/40 border border-amber-800/80 rounded-lg flex items-start gap-3 text-xs font-mono">
                <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
                <div className="space-y-0.5">
                  <span className="font-bold text-amber-300 block">NOT MEASURED SAFETY PROTOCOL ACTIVE</span>
                  <p className="text-amber-200/80 text-[11px] leading-relaxed">
                    No physical audio signal loaded. Acoustic measurements and room category classifications remain <strong className="text-amber-400">NOT MEASURED</strong> to prevent evidence fabrication. Load an audio signal under Audio Input to perform measurement.
                  </p>
                </div>
              </div>
            )}

            {/* Signal Control Toggle Bar */}
            <div className="p-3 bg-slate-900 border border-slate-800 rounded-lg flex items-center justify-between font-mono text-xs">
              <div className="flex items-center gap-2">
                <Radio className={`w-4 h-4 ${hasSignal ? "text-emerald-400 animate-pulse" : "text-slate-500"}`} />
                <span className="text-slate-300 font-medium">{signalName}</span>
              </div>
              <button
                onClick={handleToggleSignal}
                className={`px-3 py-1 rounded text-xs font-semibold transition-colors border ${
                  hasSignal
                    ? "bg-slate-950 border-slate-800 text-slate-300 hover:bg-slate-800"
                    : "bg-emerald-700 border-emerald-600 text-white hover:bg-emerald-600"
                }`}
              >
                {hasSignal ? "Unload Signal" : "Load Test Signal"}
              </button>
            </div>

            {/* 5-Room Category Selection Grid */}
            <div className="space-y-2 font-mono">
              <label className="text-xs text-slate-400 font-semibold block uppercase">
                Acoustic Room Classification (5 Categories):
              </label>
              <div className="grid grid-cols-2 gap-2 text-xs">
                {(
                  [
                    "dry_dead",
                    "small_intimate",
                    "natural_balanced",
                    "large_reverberant",
                    "uncontrolled_ambiguous"
                  ] as RoomCategory[]
                ).map((cat) => {
                  const info = ROOM_CATEGORY_INFO[cat];
                  const isSelected = selectedCategory === cat;
                  return (
                    <div
                      key={cat}
                      onClick={() => {
                        if (!hasSignal) return;
                        setSelectedCategory(cat);
                        slotContext.emitEvent("ROOM_CLASSIFICATION_CHANGED", {
                          windowId: slotContext.windowId,
                          category: cat
                        });
                      }}
                      className={`p-3 rounded-lg border transition-all ${
                        !hasSignal
                          ? "bg-slate-950 border-slate-900 opacity-50 cursor-not-allowed"
                          : isSelected
                          ? "bg-slate-900 border-indigo-500 text-slate-100 cursor-pointer shadow-lg shadow-indigo-950/30"
                          : "bg-slate-950 border-slate-800 text-slate-400 hover:border-slate-700 cursor-pointer"
                      }`}
                    >
                      <div className="flex items-center justify-between mb-1">
                        <span className={`font-bold ${isSelected ? "text-indigo-400" : "text-slate-300"}`}>
                          {info.name}
                        </span>
                        {isSelected && <CheckCircle2 className="w-3.5 h-3.5 text-indigo-400" />}
                      </div>
                      <p className="text-[11px] text-slate-400 leading-snug">{info.desc}</p>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Active Category Acoustic Traits Panel */}
            <div className="p-3.5 bg-slate-900/80 border border-slate-800 rounded-lg font-mono text-xs space-y-2">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <span className="text-slate-400 font-semibold">Active Acoustic Classification:</span>
                <span className={`px-2 py-0.5 rounded text-[11px] font-bold ${
                  hasSignal ? "bg-indigo-950 text-indigo-300 border border-indigo-800" : "bg-amber-950 text-amber-300 border border-amber-800"
                }`}>
                  {ROOM_CATEGORY_INFO[selectedCategory].name}
                </span>
              </div>
              <div className="text-[11px] text-slate-300">
                <span className="text-slate-500 block text-[10px] uppercase">Acoustic Characteristics:</span>
                <span>{ROOM_CATEGORY_INFO[selectedCategory].acousticTraits}</span>
              </div>
            </div>

            {/* Record Observation Button */}
            <button
              onClick={handleRecordObservation}
              className="w-full py-2 bg-indigo-700 hover:bg-indigo-600 border border-indigo-600 text-white rounded-lg font-mono text-xs font-semibold flex items-center justify-center gap-2 transition-colors"
            >
              <Send className="w-3.5 h-3.5" />
              <span>Record Timestamped Acoustic Witness Observation</span>
            </button>
          </div>
        )}

        {activeTab === "observations" && (
          <div className="space-y-3 font-mono text-xs">
            <div className="flex items-center justify-between text-slate-400 border-b border-slate-800 pb-2">
              <span className="font-bold text-slate-200">Acoustic Witness Observations Log</span>
              <span>Total Entries: {observations.length}</span>
            </div>

            {observations.length === 0 ? (
              <div className="p-8 text-center bg-slate-900/40 border border-slate-900 rounded-lg text-slate-500">
                <Info className="w-5 h-5 mx-auto mb-2 text-slate-600" />
                <p className="text-xs">No acoustic observations recorded yet.</p>
                <p className="text-[11px] text-slate-600 mt-1">Switch to 'Room Triage' tab to log witness observations.</p>
              </div>
            ) : (
              <div className="space-y-2 max-h-72 overflow-y-auto">
                {observations.map((obs) => (
                  <div key={obs.id} className="p-3 bg-slate-900 border border-slate-800 rounded-lg space-y-1">
                    <div className="flex items-center justify-between">
                      <span className="font-bold text-indigo-400">
                        {ROOM_CATEGORY_INFO[obs.category].name}
                      </span>
                      <span className={`px-2 py-0.5 rounded text-[10px] ${
                        obs.status === "MEASURED" ? "bg-emerald-950 text-emerald-300 border border-emerald-800" : "bg-amber-950 text-amber-300 border border-amber-800"
                      }`}>
                        {obs.status}
                      </span>
                    </div>
                    <p className="text-[11px] text-slate-300">{obs.characteristic}</p>
                    <div className="text-[10px] text-slate-500 flex items-center justify-between pt-1 border-t border-slate-800/60">
                      <span>ID: {obs.id}</span>
                      <span>{obs.timestamp.split("T")[1].slice(0, 8)}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === "signal_input" && (
          <div className="space-y-4 font-mono text-xs">
            <div className="p-3 bg-slate-900 border border-slate-800 rounded-lg">
              <span className="text-teal-400 font-bold block mb-1">Audio Input & Signal Selection</span>
              <p className="text-slate-400 text-[11px] leading-relaxed">
                Connect physical audio signals or select calibrated test signals for acoustic environment triage.
              </p>
            </div>

            <div className="p-4 bg-slate-950 border border-slate-800 rounded-lg space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-slate-300 font-semibold">Current Input State:</span>
                <span className={hasSignal ? "text-emerald-400 font-bold" : "text-amber-400 font-bold"}>
                  {hasSignal ? "SIGNAL CONNECTED" : "NO SIGNAL (NOT MEASURED)"}
                </span>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={handleToggleSignal}
                  className="flex-1 py-2 bg-slate-900 hover:bg-slate-800 border border-slate-700 text-slate-200 rounded text-xs font-semibold transition-colors"
                >
                  {hasSignal ? "Disconnect Audio Buffer" : "Load Room 05 Rustic Audio Buffer"}
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === "telemetry" && (
          <div className="space-y-3 font-mono text-xs">
            <div className="p-3 bg-slate-900 border border-slate-800 rounded-lg">
              <span className="text-emerald-400 font-bold block mb-1">Sitting Room Telemetry Stream</span>
              <p className="text-slate-400 text-[11px]">
                Exposes module events strictly through slotContext.emitEvent().
              </p>
            </div>
            <div className="p-3 bg-slate-950 border border-slate-900 rounded-lg space-y-1.5 text-[11px]">
              <div className="flex justify-between text-slate-400">
                <span>App ID:</span>
                <span className="text-indigo-400 font-bold">{slotContext.appId}</span>
              </div>
              <div className="flex justify-between text-slate-400">
                <span>Window ID:</span>
                <span className="text-slate-200">{slotContext.windowId}</span>
              </div>
              <div className="flex justify-between text-slate-400">
                <span>Active Category:</span>
                <span className="text-cyan-400">{ROOM_CATEGORY_INFO[selectedCategory].name}</span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="p-3 bg-slate-900/80 border-t border-slate-800 flex items-center justify-between text-xs font-mono text-slate-400 shrink-0">
        <span className="text-[11px]">Category: <strong className="text-indigo-400">{ROOM_CATEGORY_INFO[selectedCategory].name}</strong></span>
        <span className="text-[10px] text-slate-500">AppSlot Isolation Verified</span>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from "react";
import { AppProps } from "../types";
import {
  Activity,
  FileCode,
  Hash,
  Volume2,
  AlertTriangle,
  CheckCircle2,
  Clock,
  ShieldCheck,
  Radio,
  Sliders,
  Send,
  Upload,
  RefreshCw,
  FileCheck,
  Binary,
  Layers,
  XCircle
} from "lucide-react";

type AxiomTab = "binary_hash" | "pcm_header" | "evidence_log" | "telemetry";
type EvidenceState = "IDLE" | "FILE_SELECTED" | "FILE_HASHED" | "PCM_DECODED" | "DECODER_FAILURE";

interface EvidenceRecord {
  id: string;
  timestamp: string;
  fileName: string;
  fileSizeBytes: number;
  sha256Hash: string;
  pcmState: "DECODED" | "DECODER_FAILURE" | "NOT_MEASURED";
  sampleRateHz: number | null;
  channelCount: number | null;
  durationSeconds: number | null;
}

export const AxiomIntegrator: React.FC<AppProps> = ({ slotContext }) => {
  const [activeTab, setActiveTab] = useState<AxiomTab>("binary_hash");
  const [evidenceState, setEvidenceState] = useState<EvidenceState>("IDLE");
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Binary Evidence Layer (Raw File Bytes)
  const [fileName, setFileName] = useState<string>("No File Selected");
  const [fileSizeBytes, setFileSizeBytes] = useState<number | null>(null);
  const [fileType, setFileType] = useState<string>("");
  const [sha256Hash, setSha256Hash] = useState<string | null>(null);

  // Decoded PCM Evidence Layer (AudioContext PCM Header)
  const [sampleRateHz, setSampleRateHz] = useState<number | null>(null);
  const [channelCount, setChannelCount] = useState<number | null>(null);
  const [durationSeconds, setDurationSeconds] = useState<number | null>(null);
  const [totalFrameCount, setTotalFrameCount] = useState<number | null>(null);

  const [evidenceLogs, setEvidenceLogs] = useState<EvidenceRecord[]>([]);

  // Emit module open event on mount
  useEffect(() => {
    slotContext.emitEvent("AXIOM_MODULE_OPENED", {
      windowId: slotContext.windowId,
      appId: slotContext.appId,
      timestamp: new Date().toISOString()
    });
  }, []);

  const handleTabChange = (tab: AxiomTab) => {
    setActiveTab(tab);
    slotContext.emitEvent("AXIOM_NAVIGATED", {
      windowId: slotContext.windowId,
      destinationTab: tab
    });
  };

  // Helper: SHA-256 calculation using Web Crypto API
  const computeSHA256 = async (arrayBuffer: ArrayBuffer): Promise<string> => {
    const hashBuffer = await crypto.subtle.digest("SHA-256", arrayBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
  };

  // Process File ArrayBuffer: Hashing & PCM Decoding
  const processAudioArrayBuffer = async (name: string, size: number, type: string, arrayBuffer: ArrayBuffer) => {
    setIsProcessing(true);
    setErrorMessage(null);
    setFileName(name);
    setFileSizeBytes(size);
    setFileType(type);
    setEvidenceState("FILE_SELECTED");

    slotContext.emitEvent("AXIOM_FILE_SELECTED", {
      windowId: slotContext.windowId,
      fileName: name,
      fileSizeBytes: size
    });

    try {
      // Step 1: Compute SHA-256 Hash from raw file bytes
      const hashHex = await computeSHA256(arrayBuffer);
      setSha256Hash(hashHex);
      setEvidenceState("FILE_HASHED");

      slotContext.emitEvent("AXIOM_FILE_HASHED", {
        windowId: slotContext.windowId,
        sha256Hash: hashHex,
        fileSizeBytes: size
      });

      // Step 2: Attempt PCM Decoding via Web Audio API
      try {
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        // Clone ArrayBuffer because decodeAudioData detaches the buffer
        const bufferCopy = arrayBuffer.slice(0);
        const decodedBuffer = await audioCtx.decodeAudioData(bufferCopy);

        setSampleRateHz(decodedBuffer.sampleRate);
        setChannelCount(decodedBuffer.numberOfChannels);
        setDurationSeconds(decodedBuffer.duration);
        setTotalFrameCount(decodedBuffer.length);
        setEvidenceState("PCM_DECODED");

        slotContext.emitEvent("AXIOM_PCM_DECODED", {
          windowId: slotContext.windowId,
          sampleRateHz: decodedBuffer.sampleRate,
          channelCount: decodedBuffer.numberOfChannels,
          durationSeconds: decodedBuffer.duration,
          sha256Hash: hashHex
        });

        // Record Evidence Entry
        const record: EvidenceRecord = {
          id: `ev-${Date.now()}`,
          timestamp: new Date().toISOString(),
          fileName: name,
          fileSizeBytes: size,
          sha256Hash: hashHex,
          pcmState: "DECODED",
          sampleRateHz: decodedBuffer.sampleRate,
          channelCount: decodedBuffer.numberOfChannels,
          durationSeconds: decodedBuffer.duration
        };
        setEvidenceLogs((prev) => [record, ...prev]);

        audioCtx.close();
      } catch (decodeErr) {
        // PCM Decoding failed: do NOT fabricate PCM properties
        setSampleRateHz(null);
        setChannelCount(null);
        setDurationSeconds(null);
        setTotalFrameCount(null);
        setEvidenceState("DECODER_FAILURE");
        setErrorMessage(decodeErr instanceof Error ? decodeErr.message : "AudioContext failed to decode PCM binary stream.");

        slotContext.emitEvent("AXIOM_DECODER_FAILED", {
          windowId: slotContext.windowId,
          sha256Hash: hashHex,
          error: "PCM_DECODING_ERROR"
        });

        const record: EvidenceRecord = {
          id: `ev-${Date.now()}`,
          timestamp: new Date().toISOString(),
          fileName: name,
          fileSizeBytes: size,
          sha256Hash: hashHex,
          pcmState: "DECODER_FAILURE",
          sampleRateHz: null,
          channelCount: null,
          durationSeconds: null
        };
        setEvidenceLogs((prev) => [record, ...prev]);
      }
    } catch (hashErr) {
      setErrorMessage("Crypto API failed to calculate SHA-256 digest.");
    } finally {
      setIsProcessing(false);
    }
  };

  // User File Upload Handler
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const buffer = event.target?.result as ArrayBuffer;
      if (buffer) {
        processAudioArrayBuffer(file.name, file.size, file.type || "audio/file", buffer);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  // Synthetic Test Signal Buffer Generator (Generates calibrated PCM WAV buffer)
  const handleLoadSyntheticBuffer = () => {
    // 1-second 44100Hz 16-bit mono sine wave WAV buffer
    const sampleRate = 44100;
    const numSamples = sampleRate * 2; // 2 seconds
    const buffer = new ArrayBuffer(44 + numSamples * 2);
    const view = new DataView(buffer);

    /* WAV Header */
    const writeString = (offset: number, str: string) => {
      for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i));
    };
    writeString(0, "RIFF");
    view.setUint32(4, 36 + numSamples * 2, true);
    writeString(8, "WAVE");
    writeString(12, "fmt ");
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true); // PCM
    view.setUint16(22, 1, true); // Mono
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeString(36, "data");
    view.setUint32(40, numSamples * 2, true);

    for (let i = 0; i < numSamples; i++) {
      const t = i / sampleRate;
      const sample = Math.sin(2 * Math.PI * 220 * t) * 0.5; // 220 Hz tone
      view.setInt16(44 + i * 2, sample < 0 ? sample * 0x8000 : sample * 0x7fff, true);
    }

    processAudioArrayBuffer("calibrated_test_signal_220hz.wav", buffer.byteLength, "audio/wav", buffer);
  };

  return (
    <div className="h-full w-full bg-slate-950 text-slate-100 flex flex-col justify-between overflow-hidden select-text font-sans">
      {/* Module Header Bar */}
      <div className="p-3 bg-slate-900/90 border-b border-slate-800 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-2.5">
          <div className="p-2 bg-cyan-950/80 border border-cyan-700/60 rounded-lg text-cyan-400">
            <Activity className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xs font-bold tracking-wide text-slate-100 uppercase font-mono">
                Axiom Integrator
              </h2>
              <span className="text-[10px] font-mono px-2 py-0.2 bg-slate-950 border border-slate-800 text-cyan-400 rounded">
                App 03
              </span>
            </div>
            <p className="text-[11px] text-slate-400 line-clamp-1">
              Client-Side Audio File Hash & PCM Header Inspection
            </p>
          </div>
        </div>

        {/* State Badge */}
        <div className="flex items-center gap-2 text-[10px] font-mono">
          <span className={`px-2.5 py-0.5 rounded border flex items-center gap-1.5 ${
            evidenceState === "PCM_DECODED"
              ? "bg-emerald-950/80 text-emerald-300 border-emerald-800"
              : evidenceState === "FILE_HASHED"
              ? "bg-cyan-950/80 text-cyan-300 border-cyan-800"
              : evidenceState === "DECODER_FAILURE"
              ? "bg-red-950/80 text-red-300 border-red-800"
              : "bg-amber-950/80 text-amber-300 border-amber-800"
          }`}>
            <Binary className="w-3 h-3" />
            <span>{evidenceState}</span>
          </span>
        </div>
      </div>

      {/* Internal Navigation Bar */}
      <div className="px-3 py-1.5 bg-slate-950 border-b border-slate-900 flex items-center gap-1 overflow-x-auto no-scrollbar shrink-0 text-xs font-mono">
        <button
          onClick={() => handleTabChange("binary_hash")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "binary_hash"
              ? "bg-slate-800 text-cyan-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Hash className="w-3.5 h-3.5 text-cyan-400" />
          <span>Binary Hash</span>
        </button>

        <button
          onClick={() => handleTabChange("pcm_header")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "pcm_header"
              ? "bg-slate-800 text-cyan-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Volume2 className="w-3.5 h-3.5 text-emerald-400" />
          <span>PCM Header</span>
        </button>

        <button
          onClick={() => handleTabChange("evidence_log")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "evidence_log"
              ? "bg-slate-800 text-cyan-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <FileCheck className="w-3.5 h-3.5 text-indigo-400" />
          <span>Evidence Record ({evidenceLogs.length})</span>
        </button>

        <button
          onClick={() => handleTabChange("telemetry")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "telemetry"
              ? "bg-slate-800 text-cyan-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Radio className="w-3.5 h-3.5 text-teal-400" />
          <span>Telemetry</span>
        </button>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 overflow-y-auto p-4 font-mono text-xs relative space-y-4">
        {/* File Selection & Action Bar */}
        <div className="p-3.5 bg-slate-900 border border-slate-800 rounded-lg space-y-3">
          <div className="flex items-center justify-between">
            <span className="font-bold text-slate-200 flex items-center gap-1.5">
              <Upload className="w-4 h-4 text-cyan-400" />
              <span>Audio File Selection & Evidence Acquisition</span>
            </span>
            {isProcessing && (
              <span className="text-cyan-400 animate-pulse flex items-center gap-1 text-[11px]">
                <RefreshCw className="w-3 h-3 animate-spin" /> Processing Bytes...
              </span>
            )}
          </div>

          <div className="grid grid-cols-2 gap-2">
            <label className="py-2 px-3 bg-slate-950 hover:bg-slate-800 border border-slate-700 text-slate-200 rounded-lg cursor-pointer flex items-center justify-center gap-2 transition-colors text-xs font-semibold">
              <Upload className="w-3.5 h-3.5 text-cyan-400" />
              <span>Select Audio File</span>
              <input type="file" accept="audio/*" onChange={handleFileUpload} className="hidden" />
            </label>

            <button
              onClick={handleLoadSyntheticBuffer}
              className="py-2 px-3 bg-cyan-950 hover:bg-cyan-900 border border-cyan-800 text-cyan-300 rounded-lg flex items-center justify-center gap-2 transition-colors text-xs font-semibold"
            >
              <Radio className="w-3.5 h-3.5 text-cyan-400" />
              <span>Load Test Signal Buffer</span>
            </button>
          </div>
        </div>

        {/* Failure Warning */}
        {errorMessage && (
          <div className="p-3 bg-red-950/40 border border-red-800/80 rounded-lg flex items-start gap-2.5 text-xs">
            <XCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
            <div>
              <span className="font-bold text-red-300 block">DECODER FAILURE REPORTED</span>
              <p className="text-red-200/80 text-[11px] leading-relaxed mt-0.5">{errorMessage}</p>
              <p className="text-[10px] text-amber-400 mt-1">PCM parameters retained as NOT_MEASURED without fabrication.</p>
            </div>
          </div>
        )}

        {/* Tab 1: Binary Hash Evidence */}
        {activeTab === "binary_hash" && (
          <div className="space-y-3">
            <div className="p-3 bg-slate-900/60 border border-slate-800 rounded-lg space-y-2">
              <span className="text-cyan-400 font-bold block text-xs flex items-center gap-1.5">
                <Binary className="w-4 h-4" />
                <span>BINARY FILE EVIDENCE LAYER (Raw File Bytes)</span>
              </span>
              <p className="text-[11px] text-slate-400 leading-relaxed">
                Computes deterministic SHA-256 fingerprint directly from file byte array. Independent of PCM decoding.
              </p>
            </div>

            <div className="p-3.5 bg-slate-950 border border-slate-900 rounded-lg space-y-2.5">
              <div className="flex justify-between items-center text-xs">
                <span className="text-slate-500">Selected File Name:</span>
                <span className="text-slate-200 font-bold truncate max-w-xs">{fileName}</span>
              </div>
              <div className="flex justify-between items-center text-xs">
                <span className="text-slate-500">File Binary Size:</span>
                <span className="text-slate-300">{fileSizeBytes !== null ? `${fileSizeBytes.toLocaleString()} bytes` : "NOT MEASURED"}</span>
              </div>
              <div className="flex justify-between items-center text-xs">
                <span className="text-slate-500">MIME Content Type:</span>
                <span className="text-slate-400">{fileType || "NOT MEASURED"}</span>
              </div>
              <div className="pt-2 border-t border-slate-900 space-y-1">
                <span className="text-slate-500 text-[10px] uppercase block">SHA-256 Binary Digest Hash:</span>
                <div className="p-2.5 bg-slate-900 border border-slate-800 rounded font-mono text-[11px] text-emerald-400 break-all select-all">
                  {sha256Hash || "NOT MEASURED — Select an audio file or test buffer"}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tab 2: PCM Header Inspection */}
        {activeTab === "pcm_header" && (
          <div className="space-y-3">
            <div className="p-3 bg-slate-900/60 border border-slate-800 rounded-lg space-y-2">
              <span className="text-emerald-400 font-bold block text-xs flex items-center gap-1.5">
                <Volume2 className="w-4 h-4" />
                <span>DECODER PCM EVIDENCE LAYER (Web Audio API)</span>
              </span>
              <p className="text-[11px] text-slate-400 leading-relaxed">
                Inspects decoded audio buffer headers. Requires successful Web Audio PCM decode.
              </p>
            </div>

            <div className="grid grid-cols-2 gap-2 text-xs">
              <div className="p-3 bg-slate-950 border border-slate-900 rounded-lg space-y-1">
                <span className="text-slate-500 block text-[10px] uppercase">Sample Rate</span>
                <span className={`text-sm font-bold ${sampleRateHz !== null ? "text-emerald-400" : "text-amber-400"}`}>
                  {sampleRateHz !== null ? `${sampleRateHz} Hz` : "NOT MEASURED"}
                </span>
              </div>

              <div className="p-3 bg-slate-950 border border-slate-900 rounded-lg space-y-1">
                <span className="text-slate-500 block text-[10px] uppercase">Channel Count</span>
                <span className={`text-sm font-bold ${channelCount !== null ? "text-cyan-400" : "text-amber-400"}`}>
                  {channelCount !== null ? `${channelCount} ch (${channelCount === 1 ? "Mono" : "Stereo"})` : "NOT MEASURED"}
                </span>
              </div>

              <div className="p-3 bg-slate-950 border border-slate-900 rounded-lg space-y-1">
                <span className="text-slate-500 block text-[10px] uppercase">Exact Duration</span>
                <span className={`text-sm font-bold ${durationSeconds !== null ? "text-teal-400" : "text-amber-400"}`}>
                  {durationSeconds !== null ? `${durationSeconds.toFixed(3)} s` : "NOT MEASURED"}
                </span>
              </div>

              <div className="p-3 bg-slate-950 border border-slate-900 rounded-lg space-y-1">
                <span className="text-slate-500 block text-[10px] uppercase">Total Sample Frames</span>
                <span className={`text-sm font-bold ${totalFrameCount !== null ? "text-indigo-400" : "text-amber-400"}`}>
                  {totalFrameCount !== null ? totalFrameCount.toLocaleString() : "NOT MEASURED"}
                </span>
              </div>
            </div>
          </div>
        )}

        {/* Tab 3: Evidence Log */}
        {activeTab === "evidence_log" && (
          <div className="space-y-3">
            <div className="flex items-center justify-between text-slate-400 border-b border-slate-800 pb-2">
              <span className="font-bold text-slate-200">Acquired Binary & PCM Evidence Records</span>
              <span>Count: {evidenceLogs.length}</span>
            </div>

            {evidenceLogs.length === 0 ? (
              <div className="p-8 text-center bg-slate-900/40 border border-slate-900 rounded-lg text-slate-500">
                <FileCheck className="w-5 h-5 mx-auto mb-2 text-slate-600" />
                <p className="text-xs">No evidence records logged in this session.</p>
                <p className="text-[11px] text-slate-600 mt-1">Select an audio file or load a test signal buffer to generate evidence.</p>
              </div>
            ) : (
              <div className="space-y-2 max-h-64 overflow-y-auto">
                {evidenceLogs.map((log) => (
                  <div key={log.id} className="p-3 bg-slate-950 border border-slate-800 rounded-lg space-y-1.5">
                    <div className="flex items-center justify-between">
                      <span className="font-bold text-cyan-300 truncate max-w-xs">{log.fileName}</span>
                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                        log.pcmState === "DECODED"
                          ? "bg-emerald-950 text-emerald-300 border border-emerald-800"
                          : "bg-red-950 text-red-300 border border-red-800"
                      }`}>
                        {log.pcmState}
                      </span>
                    </div>
                    <div className="text-[10px] text-slate-400 font-mono truncate">
                      SHA-256: <span className="text-emerald-400">{log.sha256Hash}</span>
                    </div>
                    <div className="text-[10px] text-slate-500 flex items-center justify-between pt-1 border-t border-slate-900">
                      <span>{log.fileSizeBytes.toLocaleString()} bytes</span>
                      <span>{log.timestamp.split("T")[1].slice(0, 8)}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Tab 4: Telemetry */}
        {activeTab === "telemetry" && (
          <div className="space-y-3">
            <div className="p-3 bg-slate-900 border border-slate-800 rounded-lg">
              <span className="text-cyan-400 font-bold block mb-1">Axiom Integrator Telemetry</span>
              <p className="text-slate-400 text-[11px]">
                Communicates strictly via slotContext.emitEvent() with mandatory windowId correlation.
              </p>
            </div>
            <div className="p-3 bg-slate-950 border border-slate-900 rounded-lg space-y-1 text-[11px]">
              <div className="flex justify-between text-slate-400">
                <span>App ID:</span>
                <span className="text-cyan-400 font-bold">{slotContext.appId}</span>
              </div>
              <div className="flex justify-between text-slate-400">
                <span>Window ID:</span>
                <span className="text-slate-200">{slotContext.windowId}</span>
              </div>
              <div className="flex justify-between text-slate-400">
                <span>Current Evidence State:</span>
                <span className="text-emerald-400">{evidenceState}</span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="p-3 bg-slate-900/80 border-t border-slate-800 flex items-center justify-between text-xs font-mono text-slate-400 shrink-0">
        <span className="text-[11px]">Evidence State: <strong className="text-cyan-400">{evidenceState}</strong></span>
        <span className="text-[10px] text-slate-500">AppSlot Interface Verified</span>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from "react";
import { AppProps } from "../types";
import {
  ShieldCheck,
  CheckCircle2,
  AlertTriangle,
  XCircle,
  FileText,
  Sliders,
  Send,
  Lock,
  UserCheck,
  Info,
  Radio,
  Dna,
  Volume2,
  Activity
} from "lucide-react";

type DiagnosticBand =
  | "Band A (Locked Witness)"
  | "Band B (Implicit Witness)"
  | "Band C (Metaphor Diluted)"
  | "Band D (Unanchored / Violation)";

type G2DiagnosticBand =
  | "Band A (Faithful Realization)"
  | "Band B (Acceptable Drift)"
  | "Band C (Acoustic Mismatch)"
  | "Band D (Production Rupture / Unmeasured)";

type GovernanceTab = "g1_gate" | "g2_gate" | "evidence_audit" | "telemetry";
type HumanApprovalState = "PENDING_REVIEW" | "APPROVED" | "OVERRIDDEN_REJECT";

interface G1GateResult {
  gateId: "G1";
  status: "PASS" | "FAIL" | "CONDITIONAL";
  diagnosticBand: DiagnosticBand;
  witnessObjectDetected: boolean;
  ungroundedMetaphorDetected: boolean;
  witnessDensityScore: number; // Line-normalized Witness Anchor Density
  timestamp: string;
}

interface G2GateResult {
  gateId: "G2";
  status: "PASS" | "FAIL" | "CONDITIONAL";
  diagnosticBand: G2DiagnosticBand;
  decoderEvidenceAvailable: boolean;
  acousticEvidenceAvailable: boolean;
  durationValid: boolean;
  realizationEvidenceBasis: string;
  timestamp: string;
}

export const GovernanceMatrix: React.FC<AppProps> = ({ slotContext }) => {
  const [activeTab, setActiveTab] = useState<GovernanceTab>("g1_gate");

  // Read-Only Lower-Layer Evidence Inputs (From Apps 01, 02, 03)
  const [candidateLyricText, setCandidateLyricText] = useState(
    `Verse 1\nThe water sits inside the glass\nNo movement on the floor\nYou hold the blue thread until it breaks\nBeside the open door.`
  );
  const [witnessObjectAnchor, setWitnessObjectAnchor] = useState("Blue Thread");

  // App 02 Acoustic Context
  const [app02AcousticCategory, setApp02AcousticCategory] = useState("dry_dead");
  const [app02AcousticStatus, setApp02AcousticStatus] = useState<"MEASURED" | "NOT_MEASURED">("MEASURED");

  // App 03 Audio PCM Context
  const [app03DecoderStatus, setApp03DecoderStatus] = useState<"DECODED" | "DECODER_FAILURE" | "NOT_MEASURED">("DECODED");
  const [sha256AudioHash, setSha256AudioHash] = useState("4b63391788c03260842e4ecb7b411d51ee2479e0a6d0c91838ae073f1d8dd140");
  const [durationSeconds, setDurationSeconds] = useState(2.0);

  // Gate Results & Human Governor States
  const [g1Result, setG1Result] = useState<G1GateResult | null>(null);
  const [g2Result, setG2Result] = useState<G2GateResult | null>(null);
  const [humanApprovalState, setHumanApprovalState] = useState<HumanApprovalState>("PENDING_REVIEW");
  const [humanG2ApprovalState, setHumanG2ApprovalState] = useState<HumanApprovalState>("PENDING_REVIEW");

  // Emit lifecycle open event on mount
  useEffect(() => {
    slotContext.emitEvent("GOVERNANCE_MODULE_OPENED", {
      windowId: slotContext.windowId,
      appId: slotContext.appId,
      timestamp: new Date().toISOString()
    });
    // Auto-execute G1 and G2 evaluations
    evaluateG1WitnessGate();
    evaluateG2RealizationGate();
  }, []);

  const handleTabChange = (tab: GovernanceTab) => {
    setActiveTab(tab);
    slotContext.emitEvent("GOVERNANCE_NAVIGATED", {
      windowId: slotContext.windowId,
      destinationTab: tab
    });
  };

  // Executable G1 Witness Gate Evaluation Engine
  const evaluateG1WitnessGate = () => {
    const text = candidateLyricText.trim();
    const anchor = witnessObjectAnchor.trim().toLowerCase();

    if (text.length === 0 || anchor.length === 0) {
      const result: G1GateResult = {
        gateId: "G1",
        status: "FAIL",
        diagnosticBand: "Band D (Unanchored / Violation)",
        witnessObjectDetected: false,
        ungroundedMetaphorDetected: false,
        witnessDensityScore: 0.0,
        timestamp: new Date().toISOString()
      };
      setG1Result(result);
      return result;
    }

    const lines = text.split("\n").map((l) => l.trim()).filter((l) => l.length > 0);
    const totalNonEmptyLines = lines.length;

    if (totalNonEmptyLines === 0) {
      const result: G1GateResult = {
        gateId: "G1",
        status: "FAIL",
        diagnosticBand: "Band D (Unanchored / Violation)",
        witnessObjectDetected: false,
        ungroundedMetaphorDetected: false,
        witnessDensityScore: 0.0,
        timestamp: new Date().toISOString()
      };
      setG1Result(result);
      return result;
    }

    const matchingLinesCount = lines.filter((line) => line.toLowerCase().includes(anchor)).length;
    const densityScore = Math.min(1.0, Math.max(0.0, matchingLinesCount / totalNonEmptyLines));

    const textLower = text.toLowerCase();
    const forbiddenTropes = ["ocean of tears", "soaring heart", "endless sky", "cinematic swell", "burning desire"];
    const hasTrope = forbiddenTropes.some((trope) => textLower.includes(trope));

    const hasExplicitWitness = matchingLinesCount > 0;
    const hasImplicitEnvironment = !hasExplicitWitness && (textLower.includes("room") || textLower.includes("door") || textLower.includes("floor") || textLower.includes("wall"));

    let band: DiagnosticBand = "Band D (Unanchored / Violation)";
    let status: "PASS" | "FAIL" | "CONDITIONAL" = "FAIL";

    if (hasExplicitWitness && !hasTrope) {
      band = "Band A (Locked Witness)";
      status = "PASS";
    } else if (hasExplicitWitness && hasTrope) {
      band = "Band C (Metaphor Diluted)";
      status = "CONDITIONAL";
    } else if (!hasExplicitWitness && hasImplicitEnvironment) {
      band = "Band B (Implicit Witness)";
      status = "PASS";
    } else {
      band = "Band D (Unanchored / Violation)";
      status = "FAIL";
    }

    const result: G1GateResult = {
      gateId: "G1",
      status,
      diagnosticBand: band,
      witnessObjectDetected: hasExplicitWitness,
      ungroundedMetaphorDetected: hasTrope,
      witnessDensityScore: Number(densityScore.toFixed(4)),
      timestamp: new Date().toISOString()
    };

    setG1Result(result);

    slotContext.emitEvent("G1_EVALUATION_COMPLETED", {
      windowId: slotContext.windowId,
      status,
      diagnosticBand: band,
      witnessDensityScore: result.witnessDensityScore,
      timestamp: result.timestamp
    });

    return result;
  };

  // Executable Bounded G2 Realization Fidelity Gate Evaluation Engine
  const evaluateG2RealizationGate = () => {
    const isDecoderValid = app03DecoderStatus === "DECODED" && durationSeconds > 0;
    const isAcousticMeasured = app02AcousticStatus === "MEASURED";

    let band: G2DiagnosticBand = "Band D (Production Rupture / Unmeasured)";
    let status: "PASS" | "FAIL" | "CONDITIONAL" = "FAIL";
    let basis = "";

    if (isDecoderValid && isAcousticMeasured) {
      band = "Band A (Faithful Realization)";
      status = "PASS";
      basis = "Physical audio PCM decoded cleanly with valid duration (>0s) AND operational acoustic classification status is MEASURED.";
    } else if (isDecoderValid && !isAcousticMeasured) {
      band = "Band D (Production Rupture / Unmeasured)";
      status = "FAIL";
      basis = "Physical audio PCM decoded cleanly, but operational acoustic classification status is NOT_MEASURED. Realization evidence incomplete.";
    } else if (!isDecoderValid && isAcousticMeasured) {
      band = "Band D (Production Rupture / Unmeasured)";
      status = "FAIL";
      basis = "Acoustic status is MEASURED, but physical audio PCM decoder failed or duration is zero. Realization evidence broken.";
    } else {
      band = "Band D (Production Rupture / Unmeasured)";
      status = "FAIL";
      basis = "No measurable physical PCM audio or acoustic classification evidence available. Realization evidence NOT_MEASURED.";
    }

    const result: G2GateResult = {
      gateId: "G2",
      status,
      diagnosticBand: band,
      decoderEvidenceAvailable: app03DecoderStatus === "DECODED",
      acousticEvidenceAvailable: isAcousticMeasured,
      durationValid: durationSeconds > 0,
      realizationEvidenceBasis: basis,
      timestamp: new Date().toISOString()
    };

    setG2Result(result);

    slotContext.emitEvent("G2_EVALUATION_COMPLETED", {
      windowId: slotContext.windowId,
      status,
      diagnosticBand: band,
      timestamp: result.timestamp
    });

    return result;
  };

  const handleHumanG1Override = (approval: HumanApprovalState) => {
    setHumanApprovalState(approval);
    slotContext.emitEvent("HUMAN_GOVERNOR_OVERRIDE_TRIGGERED", {
      windowId: slotContext.windowId,
      approvalState: approval,
      gateId: "G1",
      timestamp: new Date().toISOString()
    });
  };

  const handleHumanG2Override = (approval: HumanApprovalState) => {
    setHumanG2ApprovalState(approval);
    slotContext.emitEvent("HUMAN_GOVERNOR_G2_OVERRIDE_TRIGGERED", {
      windowId: slotContext.windowId,
      approvalState: approval,
      gateId: "G2",
      timestamp: new Date().toISOString()
    });
  };

  return (
    <div className="h-full w-full bg-slate-950 text-slate-100 flex flex-col justify-between overflow-hidden select-text font-sans">
      {/* Module Header Bar */}
      <div className="p-3 bg-slate-900/90 border-b border-slate-800 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-2.5">
          <div className="p-2 bg-teal-950/80 border border-teal-700/60 rounded-lg text-teal-400">
            <ShieldCheck className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xs font-bold tracking-wide text-slate-100 uppercase font-mono">
                Governance Matrix
              </h2>
              <span className="text-[10px] font-mono px-2 py-0.2 bg-slate-950 border border-slate-800 text-teal-400 rounded">
                App 04
              </span>
            </div>
            <p className="text-[11px] text-slate-400 line-clamp-1">
              Read-Only Evaluator (ROE) • G1 Witness & G2 Realization Gates
            </p>
          </div>
        </div>

        {/* Human Governor Pill */}
        <div className="flex items-center gap-2 text-[10px] font-mono">
          <span className={`px-2.5 py-0.5 rounded border flex items-center gap-1.5 ${
            humanApprovalState === "APPROVED"
              ? "bg-emerald-950 text-emerald-300 border-emerald-800"
              : humanApprovalState === "OVERRIDDEN_REJECT"
              ? "bg-red-950 text-red-300 border-red-800"
              : "bg-amber-950 text-amber-300 border-amber-800"
          }`}>
            <UserCheck className="w-3 h-3" />
            <span>Gov: {humanApprovalState}</span>
          </span>
        </div>
      </div>

      {/* Navigation Bar */}
      <div className="px-3 py-1.5 bg-slate-950 border-b border-slate-900 flex items-center gap-1 overflow-x-auto no-scrollbar shrink-0 text-xs font-mono">
        <button
          onClick={() => handleTabChange("g1_gate")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "g1_gate"
              ? "bg-slate-800 text-teal-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <ShieldCheck className="w-3.5 h-3.5 text-teal-400" />
          <span>G1 Witness Gate</span>
        </button>

        <button
          onClick={() => handleTabChange("g2_gate")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "g2_gate"
              ? "bg-slate-800 text-teal-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Activity className="w-3.5 h-3.5 text-cyan-400" />
          <span>G2 Realization Gate</span>
        </button>

        <button
          onClick={() => handleTabChange("evidence_audit")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "evidence_audit"
              ? "bg-slate-800 text-teal-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <FileText className="w-3.5 h-3.5 text-indigo-400" />
          <span>Evidence Audit</span>
        </button>

        <button
          onClick={() => handleTabChange("telemetry")}
          className={`px-3 py-1 rounded-md transition-colors flex items-center gap-1.5 ${
            activeTab === "telemetry"
              ? "bg-slate-800 text-teal-300 font-semibold border border-slate-700"
              : "text-slate-400 hover:text-slate-200 hover:bg-slate-900"
          }`}
        >
          <Radio className="w-3.5 h-3.5 text-emerald-400" />
          <span>Telemetry</span>
        </button>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 overflow-y-auto p-4 font-mono text-xs relative space-y-4">
        {/* Tab 1: G1 Witness Gate */}
        {activeTab === "g1_gate" && (
          <div className="space-y-4">
            {/* G1 Evaluation Summary Banner */}
            {g1Result && (
              <div className={`p-3.5 rounded-lg border space-y-2 ${
                g1Result.status === "PASS"
                  ? "bg-emerald-950/40 border-emerald-800/80 text-emerald-100"
                  : g1Result.status === "CONDITIONAL"
                  ? "bg-amber-950/40 border-amber-800/80 text-amber-100"
                  : "bg-red-950/40 border-red-800/80 text-red-100"
              }`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {g1Result.status === "PASS" ? (
                      <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
                    ) : g1Result.status === "CONDITIONAL" ? (
                      <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
                    ) : (
                      <XCircle className="w-4 h-4 text-red-400 shrink-0" />
                    )}
                    <span className="font-bold text-sm">G1 GATE STATUS: {g1Result.status}</span>
                  </div>
                  <span className="text-[11px] px-2 py-0.5 bg-slate-950/80 border border-slate-800 rounded font-bold">
                    {g1Result.diagnosticBand}
                  </span>
                </div>

                <div className="grid grid-cols-2 gap-2 text-[11px] pt-1 border-t border-slate-900/60">
                  <div>
                    <span className="text-slate-400 block text-[10px] uppercase">Witness Density Score:</span>
                    <span className="text-emerald-400 font-bold text-xs">
                      {(g1Result.witnessDensityScore * 100).toFixed(1)}% (Line-Normalized)
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-400 block text-[10px] uppercase">Anchor Detected:</span>
                    <span className={g1Result.witnessObjectDetected ? "text-emerald-400 font-bold" : "text-red-400 font-bold"}>
                      {g1Result.witnessObjectDetected ? "EXPLICIT MATCH" : "NOT DETECTED"}
                    </span>
                  </div>
                </div>
              </div>
            )}

            {/* Editable Primary Inputs */}
            <div className="p-3.5 bg-slate-900 border border-slate-800 rounded-lg space-y-3">
              <div className="flex items-center justify-between">
                <span className="font-bold text-slate-200 text-xs">Primary Inputs (App 01 Lyric Studio)</span>
                <button
                  onClick={() => evaluateG1WitnessGate()}
                  className="px-2.5 py-1 bg-teal-800 hover:bg-teal-700 text-white rounded text-[11px] font-semibold transition-colors"
                >
                  Re-evaluate G1
                </button>
              </div>

              <div>
                <label className="text-[10px] text-slate-400 uppercase block mb-1">Declared Witness Anchor:</label>
                <input
                  type="text"
                  value={witnessObjectAnchor}
                  onChange={(e) => {
                    setWitnessObjectAnchor(e.target.value);
                  }}
                  className="w-full px-2.5 py-1.5 bg-slate-950 border border-slate-800 rounded text-slate-200 text-xs focus:outline-none focus:border-teal-500/60 font-mono"
                />
              </div>

              <div>
                <label className="text-[10px] text-slate-400 uppercase block mb-1">Candidate Lyric Text:</label>
                <textarea
                  value={candidateLyricText}
                  onChange={(e) => {
                    setCandidateLyricText(e.target.value);
                  }}
                  className="w-full h-24 p-2.5 bg-slate-950 border border-slate-800 rounded text-slate-200 text-xs focus:outline-none focus:border-teal-500/60 font-mono leading-relaxed resize-none"
                />
              </div>
            </div>

            {/* Human Governor Intercept Panel */}
            <div className="p-3.5 bg-slate-900 border border-slate-800 rounded-lg space-y-2">
              <div className="flex items-center justify-between">
                <span className="font-bold text-amber-300 text-xs flex items-center gap-1.5">
                  <UserCheck className="w-4 h-4 text-amber-400" />
                  <span>Human Governor Gate Intercept (G1)</span>
                </span>
                <span className="text-[10px] text-slate-500">Final Authority</span>
              </div>
              <p className="text-[11px] text-slate-400 leading-relaxed">
                The Human Governor retains absolute override authority over automated G1 decisions. Toggling approval updates governance telemetry without altering G1 witness scores.
              </p>

              <div className="flex gap-2 pt-1">
                <button
                  onClick={() => handleHumanG1Override("APPROVED")}
                  className={`flex-1 py-1.5 rounded font-semibold text-xs transition-colors border ${
                    humanApprovalState === "APPROVED"
                      ? "bg-emerald-900 border-emerald-600 text-emerald-200"
                      : "bg-slate-950 border-slate-800 text-slate-400 hover:text-slate-200"
                  }`}
                >
                  Approve Release
                </button>
                <button
                  onClick={() => handleHumanG1Override("OVERRIDDEN_REJECT")}
                  className={`flex-1 py-1.5 rounded font-semibold text-xs transition-colors border ${
                    humanApprovalState === "OVERRIDDEN_REJECT"
                      ? "bg-red-950 border-red-800 text-red-300"
                      : "bg-slate-950 border-slate-800 text-slate-400 hover:text-slate-200"
                  }`}
                >
                  Reject & Override
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Tab 2: G2 Realization Gate */}
        {activeTab === "g2_gate" && (
          <div className="space-y-4">
            {/* G2 Evaluation Summary Banner */}
            {g2Result && (
              <div className={`p-3.5 rounded-lg border space-y-2 ${
                g2Result.status === "PASS"
                  ? "bg-emerald-950/40 border-emerald-800/80 text-emerald-100"
                  : g2Result.status === "CONDITIONAL"
                  ? "bg-amber-950/40 border-amber-800/80 text-amber-100"
                  : "bg-red-950/40 border-red-800/80 text-red-100"
              }`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    {g2Result.status === "PASS" ? (
                      <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
                    ) : g2Result.status === "CONDITIONAL" ? (
                      <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
                    ) : (
                      <XCircle className="w-4 h-4 text-red-400 shrink-0" />
                    )}
                    <span className="font-bold text-sm">G2 GATE STATUS: {g2Result.status}</span>
                  </div>
                  <span className="text-[11px] px-2 py-0.5 bg-slate-950/80 border border-slate-800 rounded font-bold">
                    {g2Result.diagnosticBand}
                  </span>
                </div>

                <div className="text-[11px] text-slate-300 pt-1 border-t border-slate-900/60 leading-relaxed">
                  <span className="text-slate-400 block text-[10px] uppercase font-bold">Realization Evidence Basis:</span>
                  <span>{g2Result.realizationEvidenceBasis}</span>
                </div>
              </div>
            )}

            {/* Observable Evidence Inputs Toggle Bar */}
            <div className="p-3.5 bg-slate-900 border border-slate-800 rounded-lg space-y-3">
              <div className="flex items-center justify-between">
                <span className="font-bold text-slate-200 text-xs">Observable Evidence Controls (Apps 02 & 03)</span>
                <button
                  onClick={() => evaluateG2RealizationGate()}
                  className="px-2.5 py-1 bg-cyan-800 hover:bg-cyan-700 text-white rounded text-[11px] font-semibold transition-colors"
                >
                  Re-evaluate G2
                </button>
              </div>

              <div className="grid grid-cols-2 gap-2 text-xs">
                <div className="p-2.5 bg-slate-950 border border-slate-800 rounded space-y-1">
                  <span className="text-slate-500 block text-[10px] uppercase">App 03 PCM Decoder:</span>
                  <button
                    onClick={() => {
                      const next = app03DecoderStatus === "DECODED" ? "DECODER_FAILURE" : "DECODED";
                      setApp03DecoderStatus(next);
                    }}
                    className={`w-full py-1 rounded text-xs font-bold transition-colors border ${
                      app03DecoderStatus === "DECODED"
                        ? "bg-emerald-950 text-emerald-300 border-emerald-800"
                        : "bg-red-950 text-red-300 border-red-800"
                    }`}
                  >
                    {app03DecoderStatus}
                  </button>
                </div>

                <div className="p-2.5 bg-slate-950 border border-slate-800 rounded space-y-1">
                  <span className="text-slate-500 block text-[10px] uppercase">App 02 Acoustic Status:</span>
                  <button
                    onClick={() => {
                      const next = app02AcousticStatus === "MEASURED" ? "NOT_MEASURED" : "MEASURED";
                      setApp02AcousticStatus(next);
                    }}
                    className={`w-full py-1 rounded text-xs font-bold transition-colors border ${
                      app02AcousticStatus === "MEASURED"
                        ? "bg-emerald-950 text-emerald-300 border-emerald-800"
                        : "bg-amber-950 text-amber-300 border-amber-800"
                    }`}
                  >
                    {app02AcousticStatus}
                  </button>
                </div>
              </div>
            </div>

            {/* Human Governor G2 Intercept */}
            <div className="p-3.5 bg-slate-900 border border-slate-800 rounded-lg space-y-2">
              <div className="flex items-center justify-between">
                <span className="font-bold text-amber-300 text-xs flex items-center gap-1.5">
                  <UserCheck className="w-4 h-4 text-amber-400" />
                  <span>Human Governor Gate Intercept (G2)</span>
                </span>
                <span className="text-[10px] text-slate-500">Final Authority</span>
              </div>

              <div className="flex gap-2 pt-1">
                <button
                  onClick={() => handleHumanG2Override("APPROVED")}
                  className={`flex-1 py-1.5 rounded font-semibold text-xs transition-colors border ${
                    humanG2ApprovalState === "APPROVED"
                      ? "bg-emerald-900 border-emerald-600 text-emerald-200"
                      : "bg-slate-950 border-slate-800 text-slate-400 hover:text-slate-200"
                  }`}
                >
                  Approve Realization
                </button>
                <button
                  onClick={() => handleHumanG2Override("OVERRIDDEN_REJECT")}
                  className={`flex-1 py-1.5 rounded font-semibold text-xs transition-colors border ${
                    humanG2ApprovalState === "OVERRIDDEN_REJECT"
                      ? "bg-red-950 border-red-800 text-red-300"
                      : "bg-slate-950 border-slate-800 text-slate-400 hover:text-slate-200"
                  }`}
                >
                  Reject Realization
                </button>
              </div>
            </div>
          </div>
