// Elyzareth OS v38.1 - B03 MP3 Discovery Module (Verified Single-Space Architecture)
import React, { useState, useEffect, useRef } from "react";
import { SKINS } from "./skins";
import { DiscoveredFile, AuditMetrics } from "./types";
import AuditPanel from "./AuditPanel";
import PlaylistPanel from "./PlaylistPanel";
import VisualizerPanel from "./VisualizerPanel";
import ControlsPanel from "./ControlsPanel";
import LyricPanel from "./LyricPanel";
import { Palette, ShieldCheck, Folder } from "lucide-react";

const B01_SAMPLE_FILES: DiscoveredFile[] = [
  { id: "sample-1", filename: "sample_track_01.mp3", path: "sample_track_01.mp3" },
  { id: "sample-2", filename: "sample_track_02.mp3", path: "sample_track_02.mp3" },
  { id: "sample-3", filename: "sample_track_03.mp3", path: "sample_track_03.mp3" },
];

export default function ElyzarethPlayer() {
  const [currentSkinId, setCurrentSkinId] = useState<string>("aurora-purple");
  const [showSkinModal, setShowSkinModal] = useState<boolean>(false);
  const [selectedFolderName, setSelectedFolderName] = useState<string | null>(null);
  const [scanned, setScanned] = useState<boolean>(false);
  const [discoveredFiles, setDiscoveredFiles] = useState<DiscoveredFile[]>([]);
  const [selectedTrackId, setSelectedTrackId] = useState<string | null>(null);

  // Directory handle or file objects reference
  const dirHandleRef = useRef<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Folder Pick Handler
  const handlePickFolder = async () => {
    if ("showDirectoryPicker" in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        dirHandleRef.current = handle;
        setSelectedFolderName(handle.name);
        setScanned(false);
        setDiscoveredFiles([]);
        setAuditMetrics({
          mp3Discovered: 0,
          directoriesEntered: 0,
          lyricsRead: 0,
          jsonProcessed: 0,
          audioDecoded: 0,
          audioPlayed: 0,
        });
        return;
      } catch (err: any) {
        if (err.name === "AbortError") return;
      }
    }

    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      dirHandleRef.current = files;
      const firstPath = files[0].webkitRelativePath;
      const folderName = firstPath ? firstPath.split("/")[0] : "Selected Folder";
      setSelectedFolderName(folderName);
      setScanned(false);
      setDiscoveredFiles([]);
      setAuditMetrics({
        mp3Discovered: 0,
        directoriesEntered: 0,
        lyricsRead: 0,
        jsonProcessed: 0,
        audioDecoded: 0,
        audioPlayed: 0,
      });
    }
  };

  // Audit Metrics (Strict B03 measurements)
  const [auditMetrics, setAuditMetrics] = useState<AuditMetrics>({
    mp3Discovered: 0,
    directoriesEntered: 0,
    lyricsRead: 0,
    jsonProcessed: 0,
    audioDecoded: 0,
    audioPlayed: 0,
  });

  // EXPLICIT B03 SCAN FOLDER TRIGGER
  const handleScanFolder = async () => {
    if (!selectedFolderName) return;

    let mp3List: DiscoveredFile[] = [];
    let directoriesEnteredCount = 1; // Top-level directory accessed

    // Scenario A: DirectoryPicker handle available
    if (dirHandleRef.current && typeof dirHandleRef.current.values === "function") {
      try {
        let idx = 0;
        for await (const entry of dirHandleRef.current.values()) {
          // B03 RULE: DO NOT ENTER SUBFOLDERS (entry.kind === 'file' only)
          if (entry.kind === "file") {
            const filename = entry.name;
            if (filename.toLowerCase().endsWith(".mp3")) {
              idx++;
              mp3List.push({
                id: `mp3-${idx}-${filename}`,
                filename: filename,
                path: filename,
              });
            }
          }
        }
      } catch (err) {
        console.error("Directory enumeration failed:", err);
      }
    } 
    // Scenario B: File list from webkitdirectory input
    else if (dirHandleRef.current instanceof FileList || dirHandleRef.current instanceof Array) {
      const fileList: File[] = Array.from(dirHandleRef.current);
      let idx = 0;
      fileList.forEach((file) => {
        // NON-RECURSIVE CHECK: Check top-level files only
        const relativeParts = file.webkitRelativePath ? file.webkitRelativePath.split("/") : [file.name];
        if (relativeParts.length <= 2) {
          if (file.name.toLowerCase().endsWith(".mp3")) {
            idx++;
            mp3List.push({
              id: `mp3-${idx}-${file.name}`,
              filename: file.name,
              path: file.name,
            });
          }
        }
      });
    }

    setDiscoveredFiles(mp3List);
    setScanned(true);
    if (mp3List.length > 0) {
      setSelectedTrackId(mp3List[0].id);
    } else {
      setSelectedTrackId(null);
    }

    // Update Audit Metrics truthfully
    setAuditMetrics({
      mp3Discovered: mp3List.length,
      directoriesEntered: directoriesEnteredCount,
      lyricsRead: 0,
      jsonProcessed: 0,
      audioDecoded: 0,
      audioPlayed: 0,
    });
  };

  const skin = SKINS.find((s) => s.id === currentSkinId) || SKINS[0];
  const activeTrack = discoveredFiles.find((f) => f.id === selectedTrackId);

  return (
    <div className={`min-h-screen w-full ${skin.bg} ${skin.text} p-4 md:p-6 transition-colors duration-500 font-sans flex flex-col justify-between`}>
      {/* Hidden webkitdirectory file input for fallback folder picking */}
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileInputChange}
        style={{ display: "none" }}
        // @ts-ignore
        webkitdirectory=""
        directory=""
      />

      {/* HEADER SECTION */}
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6 pb-4 border-b border-white/10">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-xl md:text-2xl font-black tracking-tight flex items-center gap-2">
              <span className={skin.primary}>ELYZARETH</span> LOCAL MUSIC PLAYER
            </h1>
            <span className="text-[10px] px-2 py-0.5 rounded font-mono bg-purple-500/20 text-purple-300 border border-purple-500/30">
              v38.1 UniversalWindowShell
            </span>
          </div>
          <p className="text-xs text-white/50 font-mono mt-0.5">
            Single-Space Architecture • B03 MP3 Discovery Module
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={() => setShowSkinModal(!showSkinModal)}
            className={`px-3 py-1.5 rounded-lg border border-white/20 bg-white/5 hover:bg-white/10 transition-colors text-xs font-mono flex items-center gap-2 text-white shadow-sm`}
          >
            <Palette className="w-3.5 h-3.5 text-fuchsia-400" />
            <span>🎨 {skin.name}</span>
          </button>

          <div className="flex items-center gap-1 text-xs font-mono text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 px-2.5 py-1 rounded-lg">
            <ShieldCheck className="w-3.5 h-3.5" />
            <span>B01.2 + B02 FROZEN</span>
          </div>
        </div>
      </header>

      {/* SKIN SELECTOR MODAL */}
      {showSkinModal && (
        <div className="mb-6 p-4 rounded-xl border border-white/20 bg-black/80 backdrop-blur-xl grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2 font-mono text-xs">
          {SKINS.map((s) => (
            <button
              key={s.id}
              onClick={() => {
                setCurrentSkinId(s.id);
                setShowSkinModal(false);
              }}
              className={`p-2 rounded-lg text-left transition-all border ${
                s.id === skin.id
                  ? "border-white bg-white/20 font-bold"
                  : "border-white/10 bg-white/5 hover:bg-white/10"
              }`}
            >
              <div className="text-[11px] truncate">{s.name}</div>
            </button>
          ))}
        </div>
      )}

      {/* MAIN CONTENT GRID */}
      <main className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 mb-6">
        {/* LEFT COLUMN: Visualizer, Controls, Lyric Panel */}
        <div className="lg:col-span-5 space-y-6 flex flex-col justify-between">
          <VisualizerPanel skin={skin} activeTrackName={activeTrack?.filename || null} />
          <ControlsPanel skin={skin} activeTrackName={activeTrack?.filename || null} />
          <LyricPanel skin={skin} />
        </div>

        {/* RIGHT COLUMN: Playlist Panel & Audit Panel */}
        <div className="lg:col-span-7 space-y-6 flex flex-col justify-between">
          <PlaylistPanel
            skin={skin}
            files={discoveredFiles}
            selectedFolderName={selectedFolderName}
            scanned={scanned}
            selectedTrackId={selectedTrackId}
            onSelectTrack={(id) => setSelectedTrackId(id)}
            onScan={handleScanFolder}
            onPickFolder={handlePickFolder}
          />

          <AuditPanel
            skin={skin}
            metrics={auditMetrics}
            selectedFolderName={selectedFolderName}
            scanned={scanned}
          />
        </div>
      </main>

      {/* FOOTER */}
      <footer className="text-center font-mono text-[11px] text-white/30 pt-3 border-t border-white/5 flex flex-col sm:flex-row justify-between items-center gap-2">
        <span>Elyzareth OS v38.1 • B03 MP3 Discovery Gate</span>
        <span>Invariant Enforced: Filename Discovery Only (0 Audio Decoded)</span>
      </footer>
    </div>
  );
}

