import React, { useEffect, useRef } from 'react';
import { Skin, Track } from '../types';

interface CircularVisualizerProps {
  skin: Skin;
  isPlaying: boolean;
  currentSong: Track;
  size?: number;
}

export const CircularVisualizer: React.FC<CircularVisualizerProps> = ({
  skin,
  isPlaying,
  currentSong,
  size = 280
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    let angleOffset = 0;

    const render = () => {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = size * dpr;
      canvas.height = size * dpr;
      ctx.scale(dpr, dpr);

      ctx.clearRect(0, 0, size, size);

      const centerX = size / 2;
      const centerY = size / 2;
      const radius = size * 0.36;
      const numBars = 64;

      angleOffset += isPlaying ? 0.015 : 0.003;

      // Outer glow ring
      ctx.save();
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.strokeStyle = skin.visualizerPrimary;
      ctx.lineWidth = 2;
      ctx.globalAlpha = 0.4;
      ctx.shadowColor = skin.visualizerPrimary;
      ctx.shadowBlur = isPlaying ? 15 : 5;
      ctx.stroke();
      ctx.restore();

      // Spectrum Bars Around Ring
      for (let i = 0; i < numBars; i++) {
        const angle = (i / numBars) * Math.PI * 2 + angleOffset;

        // Generate simulated bar heights using sine waves
        const freq1 = Math.sin(i * 0.3 + angleOffset * 2);
        const freq2 = Math.cos(i * 0.5 - angleOffset * 3);
        const amplitude = isPlaying 
          ? (Math.abs(freq1 * freq2) * 22 + Math.sin(angleOffset * 4 + i) * 8 + 6)
          : (Math.abs(freq1) * 6 + 4);

        const x1 = centerX + Math.cos(angle) * (radius - 2);
        const y1 = centerY + Math.sin(angle) * (radius - 2);
        const x2 = centerX + Math.cos(angle) * (radius + amplitude);
        const y2 = centerY + Math.sin(angle) * (radius + amplitude);

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = i % 2 === 0 ? skin.visualizerPrimary : skin.visualizerSecondary;
        ctx.lineWidth = isPlaying ? 2.5 : 1.8;
        ctx.lineCap = 'round';
        ctx.globalAlpha = isPlaying ? 0.9 : 0.6;
        ctx.stroke();
      }

      // Inner subtle waveform
      ctx.beginPath();
      for (let i = 0; i <= 360; i += 5) {
        const rad = (i * Math.PI) / 180;
        const wave = Math.sin(rad * 6 + angleOffset * 5) * (isPlaying ? 4 : 1.5);
        const r = radius - 12 + wave;
        const x = centerX + Math.cos(rad) * r;
        const y = centerY + Math.sin(rad) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.strokeStyle = skin.visualizerSecondary;
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.5;
      ctx.stroke();

      animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [skin, isPlaying, size]);

  return (
    <div className="relative flex items-center justify-center">
      <canvas
        ref={canvasRef}
        style={{ width: size, height: size }}
        className="block"
      />
      <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6 pointer-events-none">
        <span className={`text-xs font-semibold uppercase tracking-wider ${skin.textMuted} mb-1`}>
          Now Playing
        </span>
        <h3 className={`text-base md:text-lg font-bold leading-tight ${skin.textColor} max-w-[180px] truncate`}>
          {currentSong.title}
        </h3>
        <p className={`text-xs ${skin.textMuted} mt-0.5`}>
          {currentSong.artist}
        </p>
        <div className={`mt-2 px-2.5 py-0.5 rounded-full text-[10px] font-mono border ${skin.badgeBg}`}>
          01:42 / {currentSong.duration}
        </div>
      </div>
    </div>
  );
};

