  return (
    <div className="relative flex items-center justify-center w-64 h-64 sm:w-72 sm:h-72 my-2 select-none">
      {/* Outer Glow Ring */}
      <div
        className={`absolute inset-0 rounded-full transition-all duration-700 blur-xl opacity-60 ${
          isPlaying ? 'scale-105' : 'scale-95'
        }`}
        style={{
          background: `radial-gradient(circle, ${skin.visualizerGlow} 0%, transparent 70%)`,
        }}
      />

      {/* Circular Spectrum Ring Placeholder */}
      <svg
        className={`w-full h-full absolute inset-0 transition-transform duration-1000 ${
          isPlaying ? 'animate-[spin_20s_linear_infinite]' : ''
        }`}
        viewBox="0 0 200 200"
      >
        <defs>
          <linearGradient id="visGradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={skin.accentHex} />
            <stop offset="100%" stopColor={skin.accentSecondaryHex} />
          </linearGradient>
        </defs>

        {/* Circular Ring Path */}
        <circle
          cx="100"
          cy="100"
          r="72"
          fill="none"
          stroke={skin.accentHex}
          strokeWidth="1.5"
          strokeOpacity="0.2"
        />

        {/* Radial spectrum bars */}
        {Array.from({ length: totalBars }).map((_, i) => {
          const angle = (i * 360) / totalBars;
          const rad = (angle * Math.PI) / 180;
          const baseRadius = 72;

          // Pseudo-random height for bars to create realistic waveform ring shape
          const seed = (i * 37) % 10;
          const height = isPlaying
            ? 8 + ((i % 5) * 4) + Math.sin(i * 0.8) * 6
            : 5 + (seed % 4);

          const x1 = 100 + Math.cos(rad) * baseRadius;
          const y1 = 100 + Math.sin(rad) * baseRadius;
          const x2 = 100 + Math.cos(rad) * (baseRadius + height);
          const y2 = 100 + Math.sin(rad) * (baseRadius + height);

          return (
            <line
              key={i}
              x1={x1}
              y1={y1}
              x2={x2}
              y2={y2}
              stroke="url(#visGradient)"
              strokeWidth="2.5"
              strokeLinecap="round"
              className="transition-all duration-300"
              style={{
                opacity: isPlaying ? 0.85 + (i % 3) * 0.05 : 0.4,
              }}
            />
          );
        })}
      </svg>

      {/* Central Circle with Music Note */}
      <div
        className={`w-36 h-36 sm:w-40 sm:h-40 rounded-full flex flex-col items-center justify-center z-10 shadow-xl border backdrop-blur-md transition-all duration-500 ${skin.cardBgClass} ${skin.cardBorderClass}`}
