        </span>
      </div>

      {/* Track List */}
      <div className="flex flex-col gap-1.5 max-h-[340px] overflow-y-auto pr-1 custom-scrollbar">
        {playlist.map((song) => {
          const isSelected = song.id === currentSongId;

          return (
            <div
              key={song.id}
              onClick={() => onSelectSong(song)}
              className={`group flex items-center justify-between p-2.5 rounded-xl border transition-all cursor-pointer ${
                isSelected
                  ? `${skin.cardBgClass} ${skin.cardBorderClass} shadow-md`
                  : 'bg-white/5 border-transparent hover:bg-white/10'
              }`}
              style={{
                borderColor: isSelected ? skin.accentHex : undefined,
              }}
            >
              {/* Song Icon & Name */}
              <div className="flex items-center gap-3 min-w-0 pr-2">
                <div
                  className={`w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0 text-xs font-bold transition-colors ${
                    isSelected ? 'text-white' : skin.textSecondary
                  }`}
                  style={{
                    backgroundColor: isSelected ? skin.accentHex : 'rgba(255,255,255,0.08)',
                  }}
                >
                  {isSelected ? <Play className="w-3.5 h-3.5 fill-current" /> : <Music className="w-3.5 h-3.5" />}
                </div>

                <div className="min-w-0 flex flex-col">
                  <span
                    className={`text-xs font-semibold truncate ${
                      isSelected ? skin.textPrimary : skin.textPrimary
                    }`}
                  >
                    {song.title}
                  </span>
                  {!isCompact && (
                    <span className={`text-[10px] font-mono truncate ${skin.textSecondary}`}>
                      {song.artist} • {song.version}
                    </span>
                  )}
                </div>
              </div>

              {/* Duration & Delete Icon */}
              <div className="flex items-center gap-2.5 flex-shrink-0">
                <span className={`text-[11px] font-mono ${skin.textSecondary}`}>
                  {song.duration}
                </span>

                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onDeleteClick(song.title);
                  }}
                  className={`p-1.5 rounded-lg opacity-60 hover:opacity-100 hover:text-red-400 transition-all ${skin.textSecondary}`}
                  title="Delete icon (disabled in Block 01)"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

