export default function App5Visualizer() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [isVisualizing, setIsVisualizing] = useState(true);

  useEffect(() => {
    let animId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let phase = 0;

    const render = () => {
      ctx.fillStyle = "#020617";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      if (isVisualizing) {
        phase += 0.03;
        const width = canvas.width;
        const height = canvas.height;
        const midY = height / 2;

        ctx.lineWidth = 2;

        // Draw 3 frequency waves
        for (let w = 0; w < 3; w++) {
          ctx.beginPath();
          ctx.strokeStyle = w === 0 ? "rgba(34, 211, 238, 0.8)" : (w === 1 ? "rgba(168, 85, 247, 0.6)" : "rgba(236, 72, 153, 0.5)");

          for (let x = 0; x < width; x += 4) {
            const freq = 0.015 + (w * 0.005);
            const amp = 30 + (w * 20);
            const y = midY + Math.sin(x * freq + phase + (w * 1.5)) * Math.sin(x * 0.005) * amp;

            if (x === 0) {
              ctx.moveTo(x, y);
            } else {
              ctx.lineTo(x, y);
            }
          }
          ctx.stroke();
        }
      }

      animId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animId);
    };
  }, [isVisualizing]);

  return (
    <div className="w-full space-y-4 font-mono text-xs">
      <div className="bg-slate-900 border border-slate-800 p-4 rounded-xl flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2.5 bg-pink-950 text-pink-400 border border-pink-800 rounded-lg">
            <Eye className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-sm font-bold text-slate-100">APP 05 — REAL-TIME AUDIO VISUALIZER</h2>
            <p className="text-[11px] text-slate-400">Reactive Frequency Waveform & WebGL Canvas Visualizer</p>
          </div>
        </div>
        <button
          onClick={() => setIsVisualizing(!isVisualizing)}
          className="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg font-semibold flex items-center gap-1.5"
        >
          {isVisualizing ? <Pause className="w-3.5 h-3.5 text-pink-400" /> : <Play className="w-3.5 h-3.5 text-emerald-400" />}
          <span>{isVisualizing ? "Pause Visualizer" : "Start Visualizer"}</span>
        </button>
      </div>

      <div className="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center justify-center min-h-[260px] relative overflow-hidden">
