import React, { useState, useEffect, useMemo } from 'react';

// ==========================================
// 1. ELYZARETH ENGINE SERVICE TYPES & CLASS
// ==========================================

export type RequestType = 'PING' | 'STRESS_TEST' | 'ANALYZE_G1';

export interface EngineRequest {
  app_id: 'APP_01';
  request_type: RequestType;
  payload: Record<string, unknown>;
}

export type G1Band = 'ANCHOR' | 'COHERENT' | 'REVIEW' | 'EROSION';

export interface G1EvidenceItem {
  rule: string;
  status: 'PASS' | 'WARN' | 'FAIL';
  detail: string;
}

export interface G1AnalysisResult {
  score: number;
  band: G1Band;
  specimen_id: string;
  evidence: G1EvidenceItem[];
  character_count: number;
  line_count: number;
  stanzas: number;
}

export interface EngineResponse {
  status: 'OK' | 'ERROR';
  timestamp: number;
  app_id: 'APP_01';
  payload: Record<string, unknown>;
}

export interface StressMetrics {
  total_sent: number;
  total_ack: number;
  zero_loss: boolean;
  min_latency_ms: number;
  max_latency_ms: number;
  avg_latency_ms: number;
}

export class ElyzarethEngineService {
  private attached: boolean = false;
  private logBuffer: string[] = [];
  private totalRequestsProcessed: number = 0;

  public attach(): boolean {
    this.attached = true;
    this.log('[ENGINE] Attached to client session as APP_01 service interface');
    return this.attached;
  }

  public status(): { attached: boolean; status: string; total_processed: number } {
    return {
      attached: this.attached,
      status: this.attached ? 'ONLINE' : 'DISCONNECTED',
      total_processed: this.totalRequestsProcessed,
    };
  }

  public async execute(request: EngineRequest): Promise<EngineResponse> {
    if (!this.attached) {
      this.log('[ENGINE_ERROR] Execution rejected: Engine not attached');
      throw new Error('ENGINE_NOT_ATTACHED');
    }

    const startTime = performance.now();
    this.totalRequestsProcessed++;

    let resultPayload: Record<string, unknown> = {};

    switch (request.request_type) {
      case 'PING':
        resultPayload = {
          acknowledged: true,
          request_type: 'PING',
          data: request.payload,
        };
        break;

      case 'STRESS_TEST': {
        const count = typeof request.payload.batch_size === 'number' ? request.payload.batch_size : 50;
        let ackCount = 0;
        const latencies: number[] = [];

        for (let i = 0; i < count; i++) {
          const t0 = performance.now();
          ackCount++;
          const t1 = performance.now();
          latencies.push(t1 - t0);
        }

        const minLat = Math.min(...latencies);
        const maxLat = Math.max(...latencies);
        const avgLat = latencies.reduce((a, b) => a + b, 0) / latencies.length;

        const metrics: StressMetrics = {
          total_sent: count,
          total_ack: ackCount,
          zero_loss: ackCount === count,
          min_latency_ms: Number(minLat.toFixed(3)),
          max_latency_ms: Number(maxLat.toFixed(3)),
          avg_latency_ms: Number(avgLat.toFixed(3)),
        };

        this.log(`[STRESS_TEST] batch=${count} ack=${ackCount} zero_loss=${metrics.zero_loss} avg_lat=${metrics.avg_latency_ms}ms`);

        resultPayload = {
          acknowledged: true,
          request_type: 'STRESS_TEST',
          metrics,
        };
        break;
      }

      case 'ANALYZE_G1': {
        const lyricText = typeof request.payload.lyric_text === 'string' ? request.payload.lyric_text : '';
        const specimenId = typeof request.payload.specimen_id === 'string' ? request.payload.specimen_id : `SPECIMEN-${Date.now()}`;

        const analysis = this.evaluateG1(lyricText, specimenId);
        this.log(`[G1_RES] specimen=${specimenId} score=${analysis.score} band=${analysis.band}`);

        resultPayload = {
          acknowledged: true,
          capability: 'G1',
          analysis,
        };
        break;
      }

      default:
        throw new Error(`UNSUPPORTED_REQUEST_TYPE: ${request.request_type}`);
    }

    const elapsed = Number((performance.now() - startTime).toFixed(2));
    this.log(`[ENGINE_RES] type=${request.request_type} status=OK elapsed=${elapsed}ms`);

    return {
      status: 'OK',
      timestamp: Date.now(),
      app_id: request.app_id,
      payload: resultPayload,
    };
  }

  private evaluateG1(text: string, specimenId: string): G1AnalysisResult {
    const lines = text.split('\n').filter(l => l.trim().length > 0);
    const lineCount = lines.length;
    const charCount = text.length;
    const stanzas = text.split(/\n\s*\n/).filter(s => s.trim().length > 0).length;

    const evidence: G1EvidenceItem[] = [];
    let scoreDeductions = 0;

    if (charCount < 20 || lineCount < 2) {
      evidence.push({
        rule: 'G1-R01: Structural Mass',
        status: 'FAIL',
        detail: 'Insufficient lyric length (< 20 chars or < 2 lines)',
      });
      scoreDeductions += 30;
    } else {
      evidence.push({
        rule: 'G1-R01: Structural Mass',
        status: 'PASS',
        detail: `Valid density: ${lineCount} lines, ${charCount} chars across ${stanzas} stanza(s)`,
      });
    }

    const lineLengths = lines.map(l => l.trim().length);
    const avgLen = lineLengths.length > 0 ? lineLengths.reduce((a, b) => a + b, 0) / lineLengths.length : 0;
    const variance = lineLengths.length > 0
      ? lineLengths.reduce((sq, n) => sq + Math.pow(n - avgLen, 2), 0) / lineLengths.length
      : 0;

    if (variance > 180) {
      evidence.push({
        rule: 'G1-R02: Rhythmic Cadence Variance',
        status: 'WARN',
        detail: `High line-length variance (${variance.toFixed(1)}). Potential rhythmic instability.`,
      });
      scoreDeductions += 12;
    } else {
      evidence.push({
        rule: 'G1-R02: Rhythmic Cadence Variance',
        status: 'PASS',
        detail: `Stable cadence variance (${variance.toFixed(1)}). Consistent metrical flow.`,
      });
    }

    const fillers = ['yeah', 'baby', 'oh oh', 'la la', 'na na', 'ooh', 'woo'];
    let fillerHits = 0;
    const lowerText = text.toLowerCase();
    fillers.forEach(f => {
      const matches = lowerText.split(f).length - 1;
      fillerHits += matches;
    });

    if (fillerHits > 4) {
      evidence.push({
        rule: 'G1-R03: Generic Cliché & Vocal Filler',
        status: 'WARN',
        detail: `Detected ${fillerHits} generic vocal filler instances. Deducting identity clarity.`,
      });
      scoreDeductions += 10;
    } else {
      evidence.push({
        rule: 'G1-R03: Generic Cliché & Vocal Filler',
        status: 'PASS',
        detail: `Low generic filler density (${fillerHits} hits). Clean identity footprint.`,
      });
    }

    const sectionHeaders = text.match(/\[(verse|chorus|bridge|outro|intro|hook)\]/gi);
    if (sectionHeaders && sectionHeaders.length >= 2) {
      evidence.push({
        rule: 'G1-R04: Structural Section Anchors',
        status: 'PASS',
        detail: `Explicit section markers found (${sectionHeaders.length} tags). High structural coherence.`,
      });
    } else {
      evidence.push({
        rule: 'G1-R04: Structural Section Anchors',
        status: 'WARN',
        detail: 'Fewer than 2 structural section markers ([Verse], [Chorus]).',
      });
      scoreDeductions += 5;
    }

    const finalScore = Math.max(0, Math.min(100, 100 - scoreDeductions));

    // Mapped strictly to diagnostic bands: Anchor: 94-100, Coherent: 85-93, Review: 79-84, Erosion: <=78
    let band: G1Band = 'EROSION';
    if (finalScore >= 94) {
      band = 'ANCHOR';
    } else if (finalScore >= 85) {
      band = 'COHERENT';
    } else if (finalScore >= 79) {
      band = 'REVIEW';
    } else {
      band = 'EROSION';
    }

    return {
      score: finalScore,
      band,
      specimen_id: specimenId,
      evidence,
      character_count: charCount,
      line_count: lineCount,
      stanzas,
    };
  }

  public getLogs(): string[] {
    return [...this.logBuffer];
  }

  private log(msg: string) {
    const entry = `[${new Date().toISOString()}] ${msg}`;
    this.logBuffer.unshift(entry);
    if (this.logBuffer.length > 100) this.logBuffer.pop();
  }
}

