                  color: log.includes('G1_RES') ? '#a3be8c' : log.includes('STRESS') ? '#ebcb8b' : log.includes('REQ') ? '#88c0d0' : '#d8dee9',
                }}
              >
                {log}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

