  ]);

  // G1 State
  const [g1Input, setG1Input] = useState<{ title: string; corpusId: string; verses: string; chorus: string; outro: string }>({
    title: "Salt the Steps",
    corpusId: "CORPUS-001-A",
    verses: "The cold air bite upon the porch frame.\nFootsteps ringing clear in winter quiet.",
    chorus: "Salt the steps before the frost sets in.\nKeep the entry threshold dry and bare.",
    outro: "Quiet ice, stillness remains."
  });
  const [g1Witness, setG1Witness] = useState<G1WitnessPayload | null>(null);

  // G2 State
  const [g2Result, setG2Result] = useState<G2EvaluationResult>({
    alignmentState: "UNTESTED",
    identityCheckPassed: false,
    ruleViolations: [],
    witnessHash: "0x00000000"
