function LyricGeneratorTenant() {
  const [topic, setTopic] = useState("");
  const [genre, setGenre] = useState("Indie Pop");
  const [lyricResult, setLyricResult] = useState<WriteLyricsResult | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const res = await writeLyrics({
        prompt: `${genre} song lyrics about: ${topic}`
      });
      setLyricResult(res);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate lyrics");
    } finally {
      setIsGenerating(false);
    }
  };

  const copyLyrics = () => {
    if (!lyricResult?.lyrics) return;
    navigator.clipboard.writeText(lyricResult.lyrics);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className="flex-1 p-6 overflow-y-auto flex flex-col gap-6 bg-slate-900/60">
      {/* Input Controls */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 flex flex-col gap-1.5">
          <label className="text-xs font-semibold text-slate-300">Lyric Theme / Prompt Topic</label>
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="e.g. Echoes in a frozen shell..."
            className="w-full px-3.5 py-2 bg-slate-950 border border-slate-800 rounded-lg text-xs text-slate-200 focus:outline-none focus:border-indigo-500 transition"
          />
        </div>

        <div className="flex flex-col gap-1.5">
          <label className="text-xs font-semibold text-slate-300">Style Baseline</label>
          <select
            value={genre}
            onChange={(e) => setGenre(e.target.value)}
            className="w-full px-3.5 py-2 bg-slate-950 border border-slate-800 rounded-lg text-xs text-slate-200 focus:outline-none focus:border-indigo-500 transition"
          >
            <option value="Indie Pop">Indie Pop</option>
            <option value="Modern Country">Modern Country</option>
            <option value="Ambient Acoustic">Ambient Acoustic</option>
            <option value="Post-Rock">Post-Rock</option>
          </select>
        </div>
      </div>

      <button
        onClick={handleGenerate}
        disabled={isGenerating || !topic.trim()}
        className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg font-semibold text-xs flex items-center justify-center gap-2 transition disabled:opacity-50 cursor-pointer"
      >
        <Sparkles className="w-4 h-4" />
        {isGenerating ? "Drafting Stanza Telemetry..." : "Generate Lyrics"}
      </button>

      {error && (
        <div className="p-3 bg-rose-950/50 border border-rose-800/80 rounded-lg text-xs font-mono text-rose-300">
          {error}
        </div>
      )}

      {/* Generated Output Display */}
      {lyricResult && (
        <div className="flex-1 bg-slate-950 border border-slate-800 rounded-xl p-4 flex flex-col gap-3 relative">
          <div className="flex items-center justify-between border-b border-slate-800/80 pb-2">
            <span className="text-[11px] font-mono text-slate-400 uppercase tracking-wider">
              {lyricResult.title || "Draft Output"}
            </span>
            <button
              onClick={copyLyrics}
              className="flex items-center gap-1 text-[11px] font-mono text-slate-400 hover:text-slate-200 transition"
            >
              {copied ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
              {copied ? "Copied" : "Copy"}
            </button>
          </div>
          <pre className="text-xs font-mono text-slate-200 whitespace-pre-wrap leading-relaxed">
            {lyricResult.lyrics}
          </pre>
        </div>
      )}
    </div>
  );
}

