export interface CandidateSubmission {
  candidateId: string;
  rawText: string;
  expectedPrimaryAnchor?: string;
  expectedSecondaryAnchors?: string[];
  expectedSensoryKeywords?: string[];
  expectedDeltaReasons?: string[];
  contradictoryPhysicalMarkers?: string[];
}

export interface AnchorAuditReport {
  primaryAnchorPresent: boolean;
  secondaryAnchorsFound: string[];
  sensoryEvidenceFound: string[];
  temporalAnchorPresent: boolean;
}

export interface ONMAuditReport {
  initialStateDetected: boolean;
  mutatedStateDetected: boolean;
  deltaReasonDetected: boolean;
  mutationTraceValid: boolean;
}

export interface G2AuditResult {
  candidateId: string;
  passed: boolean;
  evidencePresenceScore: number;
  anchorAudit: AnchorAuditReport;
  onmAudit: ONMAuditReport;
  identityDriftDetected: boolean;
  rejectionReasons: string[];
  timestamp: string;
}

/**
 * SPACE-006D — G2 Read-Only Candidate Evaluator (Refined Forensic Logic)
 * Strict forensic evaluator enforcing specific physical delta reasons and explicit physical contradictions.
 */
export function evaluateCandidate(candidate: CandidateSubmission): G2AuditResult {
  const text = candidate.rawText.toLowerCase();
  const rejectionReasons: string[] = [];

  // 1. Anchor Audit
  const primaryAnchor = candidate.expectedPrimaryAnchor?.toLowerCase() || "salt";
  const primaryAnchorPresent = text.includes(primaryAnchor);
  if (!primaryAnchorPresent) {
    rejectionReasons.push(`Primary anchor '${primaryAnchor}' missing from candidate text.`);
  }

  const secondaryList = candidate.expectedSecondaryAnchors || ["steps", "porch", "frost"];
  const secondaryAnchorsFound = secondaryList.filter((anchor) => text.includes(anchor.toLowerCase()));

  const sensoryList = candidate.expectedSensoryKeywords || ["cold", "crunch", "grey", "breath", "ice"];
  const sensoryEvidenceFound = sensoryList.filter((kw) => text.includes(kw.toLowerCase()));

  const temporalKeywords = ["morning", "dawn", "dusk", "night", "winter", "clock", "hour", "time", "seconds", "minutes"];
  const temporalAnchorPresent = temporalKeywords.some((tk) => text.includes(tk));

  const anchorAudit: AnchorAuditReport = {
    primaryAnchorPresent,
    secondaryAnchorsFound,
    sensoryEvidenceFound,
    temporalAnchorPresent,
  };

  // 2. ONM Audit (Object Narrative Mutation)
  const initialMarkers = ["before", "clean", "smooth", "dry", "intact", "quiet", "untouched", "bare"];
  const mutatedMarkers = ["after", "cracked", "salted", "thawed", "melted", "broken", "wet", "scattered"];

  // Refined: Delta reason strictly requires meaningful physical cause phrases, not generic connectors like "as the"
  const expectedDeltaReasons = candidate.expectedDeltaReasons || [
    "chemical reaction",
    "reaction",
    "heat",
    "friction",
    "pressure",
    "dissolves",
    "melts",
    "thaws",
    "corrodes",
    "temperature"
  ];

  const initialStateDetected = initialMarkers.some((m) => text.includes(m));
  const mutatedStateDetected = mutatedMarkers.some((m) => text.includes(m));
  const deltaReasonDetected = expectedDeltaReasons.some((reason) => text.includes(reason.toLowerCase()));

  // Requirement: mutationTraceValid requires initial + mutated + explicit physical delta reason
  const mutationTraceValid = initialStateDetected && mutatedStateDetected && deltaReasonDetected;

  if (!mutationTraceValid) {
    const missing: string[] = [];
    if (!initialStateDetected) missing.push("initial state");
    if (!mutatedStateDetected) missing.push("mutated state");
    if (!deltaReasonDetected) missing.push("explicit physical delta reason");
    rejectionReasons.push(`Incomplete ONM mutation trace: missing ${missing.join(", ")}.`);
  }

  const onmAudit: ONMAuditReport = {
    initialStateDetected,
    mutatedStateDetected,
    deltaReasonDetected,
    mutationTraceValid,
  };

  // 3. Evidence Presence Score (coverage of expected signals)
  let totalPoints = 0;
  let earnedPoints = 0;

  totalPoints += 1; // Primary anchor
  if (primaryAnchorPresent) earnedPoints += 1;

  totalPoints += secondaryList.length;
  earnedPoints += secondaryAnchorsFound.length;

  totalPoints += sensoryList.length;
  earnedPoints += sensoryEvidenceFound.length;

  totalPoints += 1; // Temporal anchor
  if (temporalAnchorPresent) earnedPoints += 1;

  totalPoints += 3; // Initial, Mutated, Delta Reason
  if (initialStateDetected) earnedPoints += 1;
  if (mutatedStateDetected) earnedPoints += 1;
  if (deltaReasonDetected) earnedPoints += 1;

  const evidencePresenceScore = Math.round((earnedPoints / (totalPoints || 1)) * 100) / 100;

  // 4. Refined Identity Drift: Identity drift requires explicit physical or narrative contradiction 
  // against the preserved witness, rather than simple unfamiliar vocabulary or genre terms.
  const contradictionMarkers = candidate.contradictoryPhysicalMarkers || [
    "sunny afternoon",
    "summer heat",
    "tropical",
    "boiling water",
    "fireplace"
  ];

  const identityDriftDetected = contradictionMarkers.some((marker) => text.includes(marker.toLowerCase()));

  if (identityDriftDetected) {
    rejectionReasons.push("Identity drift detected: candidate text explicitly contradicts preserved physical witness conditions.");
  }

  // Pass/Fail Gate
  const passed = primaryAnchorPresent && mutationTraceValid && !identityDriftDetected && rejectionReasons.length === 0;

  return {
    candidateId: candidate.candidateId,
    passed,
    evidencePresenceScore,
    anchorAudit,
    onmAudit,
    identityDriftDetected,
    rejectionReasons,
    timestamp: new Date().toISOString(),
  };
}

