type WindowState = "WINDOWED" | "SNAP_L" | "SNAP_R" | "MAXIMIZED" | "MINIMIZED" | "CLOSED";

// ==========================================
// LANDLORD: UniversalWindowShell (v38.1 OS Chrome)
// ==========================================
interface UniversalWindowShellProps {
  title: string;
  children: React.ReactNode;
}

function UniversalWindowShell({ title, children }: UniversalWindowShellProps) {
  const [windowState, setWindowState] = useState<WindowState>("WINDOWED");
  const [previousState, setPreviousState] = useState<WindowState>("WINDOWED");

  const handleStateChange = (newState: WindowState) => {
    if (newState === "MINIMIZED" || newState === "MAXIMIZED" || newState === "SNAP_L" || newState === "SNAP_R") {
      setPreviousState(windowState);
    }
    setWindowState(newState);
  };

  const getContainerStyles = () => {
    switch (windowState) {
      case "MAXIMIZED":
        return "w-full h-screen rounded-none border-0";
      case "SNAP_L":
        return "w-1/2 h-screen rounded-none border-r border-slate-800";
      case "SNAP_R":
        return "w-1/2 h-screen rounded-none border-l border-slate-800 ml-auto";
      case "MINIMIZED":
        return "w-80 h-12 overflow-hidden rounded-lg border border-slate-800";
      case "CLOSED":
        return "hidden";
      case "WINDOWED":
      default:
        return "w-full max-w-3xl h-[620px] rounded-xl border border-slate-800 shadow-2xl";
    }
  };

  if (windowState === "CLOSED") {
    return (
      <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-4">
        <div className="p-6 bg-slate-900 border border-slate-800 rounded-xl flex flex-col items-center gap-3">
          <ShieldAlert className="w-8 h-8 text-amber-400" />
          <p className="text-sm font-mono text-slate-300">UniversalWindowShell: Container Unmounted ({title})</p>
          <button
            onClick={() => handleStateChange(previousState !== "CLOSED" ? previousState : "WINDOWED")}
            className="px-4 py-2 text-xs font-semibold bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition cursor-pointer font-mono"
          >
            Re-Mount Container
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-4 font-sans">
      <div className={`bg-slate-900 flex flex-col transition-all duration-200 overflow-hidden ${getContainerStyles()}`}>

        {/* OS Chrome Authority Header */}
        <header className="px-4 py-2.5 bg-slate-950 border-b border-slate-800 flex items-center justify-between shrink-0 select-none">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-indigo-500/30 border border-indigo-400 flex items-center justify-center">
              <Lock className="w-2 h-2 text-indigo-300" />
            </div>
            <span className="text-xs font-mono font-bold tracking-wide text-slate-200">
              Elyzareth OS v38.1 <span className="text-slate-500">|</span> {title}
            </span>
          </div>

          {/* Window Lifecycle Controls */}
          <div className="flex items-center gap-1 font-mono">
            <button
              onClick={() => handleStateChange("SNAP_L")}
              title="Snap Left"
              className={`p-1.5 rounded hover:bg-slate-800 text-slate-400 hover:text-slate-200 ${windowState === "SNAP_L" ? "bg-indigo-600/30 text-indigo-300" : ""}`}
            >
              <PanelLeft className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={() => handleStateChange("SNAP_R")}
              title="Snap Right"
              className={`p-1.5 rounded hover:bg-slate-800 text-slate-400 hover:text-slate-200 ${windowState === "SNAP_R" ? "bg-indigo-600/30 text-indigo-300" : ""}`}
            >
              <PanelRight className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={() => handleStateChange(windowState === "MINIMIZED" ? previousState : "MINIMIZED")}
              title="Minimize"
              className="p-1.5 rounded hover:bg-slate-800 text-slate-400 hover:text-slate-200"
            >
              <Minus className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={() => handleStateChange(windowState === "MAXIMIZED" ? "WINDOWED" : "MAXIMIZED")}
              title="Maximize / Restore"
              className={`p-1.5 rounded hover:bg-slate-800 text-slate-400 hover:text-slate-200 ${windowState === "MAXIMIZED" ? "bg-indigo-600/30 text-indigo-300" : ""}`}
            >
              {windowState === "MAXIMIZED" ? <RotateCcw className="w-3.5 h-3.5" /> : <Square className="w-3.5 h-3.5" />}
            </button>
            <button
              onClick={() => handleStateChange("CLOSED")}
              title="Close Container"
              className="p-1.5 rounded hover:bg-rose-600 text-slate-400 hover:text-white transition"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        </header>

        {/* Minimized Dock Bar View */}
        {windowState === "MINIMIZED" ? (
          <div className="px-4 py-2 flex items-center justify-between text-xs text-slate-400 font-mono">
            <span className="flex items-center gap-2">
              <FileText className="w-3.5 h-3.5 text-indigo-400" />
              {title} (Docked)
            </span>
            <button
              onClick={() => handleStateChange(previousState)}
              className="text-indigo-400 hover:underline"
            >
              Restore
            </button>
          </div>
        ) : (
          /* Tenant Content Slot */
          <div className="flex-1 flex flex-col overflow-hidden">
            {children}
            <footer className="px-4 py-2 border-t border-slate-800/80 bg-slate-950/80 flex items-center justify-between text-[10px] font-mono text-slate-500 shrink-0">
              <span>UniversalWindowShell Authority: Active</span>
              <span>Geometry State: {windowState}</span>
            </footer>
          </div>
        )}

      </div>
    </div>
  );
}

// ==========================================
// TENANT: App 01 Lyric Generator (Pure Tenant)
// ==========================================
function LyricGeneratorTenant() {
  const [topic, setTopic] = useState("");
  const [genre, setGenre] = useState("Indie Pop");
  const [lyricResult, setLyricResult] = useState<WriteLyricsResult | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const res = await writeLyrics({
        prompt: `${genre} song lyrics about: ${topic}`
      });
      setLyricResult(res);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate lyrics");
    } finally {
      setIsGenerating(false);
    }
  };

  const copyLyrics = () => {
    if (!lyricResult?.lyrics) return;
    navigator.clipboard.writeText(lyricResult.lyrics);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className="flex-1 p-6 overflow-y-auto flex flex-col gap-6 bg-slate-900/60">
      {/* Input Controls */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 flex flex-col gap-1.5">
          <label className="text-xs font-semibold text-slate-300">Lyric Theme / Prompt Topic</label>
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="e.g. Echoes in a frozen shell..."
            className="w-full px-3.5 py-2 bg-slate-950 border border-slate-800 rounded-lg text-xs text-slate-200 focus:outline-none focus:border-indigo-500 transition"
          />
        </div>

        <div className="flex flex-col gap-1.5">
          <label className="text-xs font-semibold text-slate-300">Style Baseline</label>
          <select
            value={genre}
            onChange={(e) => setGenre(e.target.value)}
            className="w-full px-3.5 py-2 bg-slate-950 border border-slate-800 rounded-lg text-xs text-slate-200 focus:outline-none focus:border-indigo-500 transition"
          >
            <option value="Indie Pop">Indie Pop</option>
            <option value="Modern Country">Modern Country</option>
            <option value="Ambient Acoustic">Ambient Acoustic</option>
            <option value="Post-Rock">Post-Rock</option>
          </select>
        </div>
      </div>

      <button
        onClick={handleGenerate}
        disabled={isGenerating || !topic.trim()}
        className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg font-semibold text-xs flex items-center justify-center gap-2 transition disabled:opacity-50 cursor-pointer"
      >
        <Sparkles className="w-4 h-4" />
        {isGenerating ? "Drafting Stanza Telemetry..." : "Generate Lyrics"}
      </button>

      {error && (
        <div className="p-3 bg-rose-950/50 border border-rose-800/80 rounded-lg text-xs font-mono text-rose-300">
          {error}
        </div>
      )}

      {/* Generated Output Display */}
      {lyricResult && (
        <div className="flex-1 bg-slate-950 border border-slate-800 rounded-xl p-4 flex flex-col gap-3 relative">
          <div className="flex items-center justify-between border-b border-slate-800/80 pb-2">
            <span className="text-[11px] font-mono text-slate-400 uppercase tracking-wider">
              {lyricResult.title || "Draft Output"}
            </span>
            <button
              onClick={copyLyrics}
              className="flex items-center gap-1 text-[11px] font-mono text-slate-400 hover:text-slate-200 transition"
            >
              {copied ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
              {copied ? "Copied" : "Copy"}
            </button>
          </div>
          <pre className="text-xs font-mono text-slate-200 whitespace-pre-wrap leading-relaxed">
            {lyricResult.lyrics}
          </pre>
        </div>
      )}
    </div>
  );
}

