import React, { useState, useEffect } from "react";
import {
  Maximize2,
  Minimize2,
  Square,
  Play,
  CheckCircle2,
  AlertOctagon,
  RotateCcw,
  Monitor,
  ShieldCheck,
  Terminal,
  X,
  Lock,
  Layers,
  Activity
} from "lucide-react";

type WindowState =
  | "WINDOWED"
  | "SNAP_L"
  | "SNAP_R"
  | "MAXIMIZED"
  | "MINIMIZED"
  | "RESTORE"
  | "CLOSED";

interface WindowGeometry {
  x: number;
  y: number;
  w: number;
  h: number;
  opacity: number;
  zIndex: number;
}

interface TransitionLog {
  id: number;
  timestamp: string;
  fromState: WindowState;
  toState: WindowState;
  geometry: WindowGeometry;
  valid: boolean;
  notes: string;
}

const REQUIRED_SEQUENCE: WindowState[] = [
  "WINDOWED",
  "SNAP_L",
  "SNAP_R",
  "MAXIMIZED",
  "MINIMIZED",
  "RESTORE",
  "CLOSED"
];

export default function Component() {
  const [currentState, setCurrentState] = useState<WindowState>("WINDOWED");
  const [prevState, setPrevState] = useState<WindowState>("WINDOWED");
  const [sequenceIndex, setSequenceIndex] = useState<number>(0);
  const [isAutomating, setIsAutomating] = useState<boolean>(false);
  const [logs, setLogs] = useState<TransitionLog[]>([]);
  const [testResult, setTestResult] = useState<"IDLE" | "PASS" | "BLOCKER">("IDLE");
  const [blockerMessage, setBlockerMessage] = useState<string | null>(null);

  const DESKTOP_W = 800;
  const DESKTOP_H = 460;

  const getGeometryForState = (state: WindowState, prev: WindowState): WindowGeometry => {
    switch (state) {
      case "WINDOWED":
        return { x: 150, y: 50, w: 500, h: 320, opacity: 1, zIndex: 10 };
      case "SNAP_L":
        return { x: 0, y: 0, w: DESKTOP_W / 2, h: DESKTOP_H, opacity: 1, zIndex: 10 };
      case "SNAP_R":
        return { x: DESKTOP_W / 2, y: 0, w: DESKTOP_W / 2, h: DESKTOP_H, opacity: 1, zIndex: 10 };
      case "MAXIMIZED":
        return { x: 0, y: 0, w: DESKTOP_W, h: DESKTOP_H, opacity: 1, zIndex: 20 };
      case "MINIMIZED":
        return { x: 150, y: DESKTOP_H + 20, w: 500, h: 40, opacity: 0, zIndex: 0 };
      case "RESTORE":
        return { x: 150, y: 50, w: 500, h: 320, opacity: 1, zIndex: 10 };
      case "CLOSED":
        return { x: 150, y: 50, w: 0, h: 0, opacity: 0, zIndex: -1 };
      default:
        return { x: 150, y: 50, w: 500, h: 320, opacity: 1, zIndex: 10 };
    }
  };

  const currentGeometry = getGeometryForState(currentState, prevState);

  const validateTransition = (from: WindowState, to: WindowState): { valid: boolean; notes: string } => {
    const expectedNext = REQUIRED_SEQUENCE[sequenceIndex + 1];
    if (isAutomating && to !== expectedNext && expectedNext !== undefined) {
      return {
        valid: false,
        notes: `Out-of-order sequence violation. Expected ${expectedNext}, got ${to}`
      };
    }

    if (from === "CLOSED" && to !== "WINDOWED") {
      return { valid: false, notes: "Cannot transition from CLOSED to non-WINDOWED state" };
    }

    if (from === "MINIMIZED" && to !== "RESTORE" && to !== "CLOSED") {
      return { valid: false, notes: "MINIMIZED state must transition via RESTORE or direct CLOSE" };
    }

    return { valid: true, notes: `Valid transition: ${from} → ${to}` };
  };

  const executeTransition = (targetState: WindowState) => {
    const { valid, notes } = validateTransition(currentState, targetState);
    const newLog: TransitionLog = {
      id: Date.now(),
      timestamp: new Date().toISOString().split("T")[1].slice(0, 8),
      fromState: currentState,
      toState: targetState,
      geometry: getGeometryForState(targetState, currentState),
      valid,
      notes
    };

    setLogs((prev) => [newLog, ...prev]);

    if (!valid) {
      setTestResult("BLOCKER");
      setBlockerMessage(notes);
      setIsAutomating(false);
      return false;
    }

    setPrevState(currentState);
    setCurrentState(targetState);

    const nextIdx = REQUIRED_SEQUENCE.indexOf(targetState);
    if (nextIdx !== -1) {
      setSequenceIndex(nextIdx);
    }

    return true;
  };

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isAutomating) {
      if (sequenceIndex < REQUIRED_SEQUENCE.length - 1) {
        timer = setTimeout(() => {
          const nextTarget = REQUIRED_SEQUENCE[sequenceIndex + 1];
          const success = executeTransition(nextTarget);
          if (!success) {
            setIsAutomating(false);
          }
        }, 900);
      } else {
        setIsAutomating(false);
        setTestResult("PASS");
      }
    }
    return () => clearTimeout(timer);
  }, [isAutomating, sequenceIndex]);

  const handleReset = () => {
    setCurrentState("WINDOWED");
    setPrevState("WINDOWED");
    setSequenceIndex(0);
    setIsAutomating(false);
    setLogs([]);
    setTestResult("IDLE");
    setBlockerMessage(null);
  };

  const runAutomatedTest = () => {
    handleReset();
    setTimeout(() => {
      setIsAutomating(true);
    }, 100);
  };

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-4 font-mono select-none">
      <div className="w-full max-w-6xl flex flex-col gap-4">
        {/* Header Protocol Bar */}
        <div className="flex items-center justify-between border-b border-slate-800 pb-3">
          <div className="flex items-center gap-3">
            <ShieldCheck className="w-6 h-6 text-emerald-400" />
            <div>
              <h1 className="text-lg font-bold tracking-wider text-slate-100 flex items-center gap-2">
                UNIVERSAL WINDOW SHELL <span className="text-xs px-2 py-0.5 bg-slate-800 text-slate-300 rounded border border-slate-700">v38.1 ACCEPTANCE TEST</span>
              </h1>
              <p className="text-xs text-slate-400">
                Single-Variable State Machine Verification • Zero Architecture Mutation
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs text-slate-500 uppercase tracking-widest mr-2">State:</span>
            <span
              className={`px-3 py-1 text-xs font-bold rounded tracking-wider border ${
                testResult === "PASS"
                  ? "bg-emerald-950/80 text-emerald-300 border-emerald-500/50"
                  : testResult === "BLOCKER"
                  ? "bg-rose-950/80 text-rose-300 border-rose-500/50"
                  : "bg-slate-900 text-cyan-400 border-cyan-500/30"
              }`}
            >
              {testResult === "PASS" && "✓ ACCEPTANCE PASSED"}
              {testResult === "BLOCKER" && "⚠ BLOCKER DETECTED"}
              {testResult === "IDLE" && (isAutomating ? "EXECUTING TEST..." : "READY FOR PROTOCOL")}
            </span>
          </div>
        </div>

        {/* Main Grid: Desktop Viewport + Sequence Telemetry */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
          {/* Desktop Shell Boundary (8 cols) */}
          <div className="lg:col-span-8 flex flex-col gap-3">
            <div className="flex items-center justify-between px-2 text-xs text-slate-400">
              <span className="flex items-center gap-1.5">
                <Monitor className="w-3.5 h-3.5 text-slate-500" /> Isolated Desktop Viewport ({DESKTOP_W} x {DESKTOP_H}px)
              </span>
              <span className="text-slate-500">Corpus Context: <strong className="text-slate-400">ABSENT (Clean Desk)</strong></span>
            </div>

            {/* Simulated Desktop Container */}
            <div className="relative w-full h-[460px] bg-slate-900/90 rounded-lg border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-sm">
              <div
                className="absolute inset-0 opacity-10 pointer-events-none"
                style={{
                  backgroundImage: `radial-gradient(#94a3b8 1px, transparent 1px)`,
                  backgroundSize: "20px 20px"
                }}
              />

              {/* Snap Helper Overlay Indicators */}
              {currentState === "SNAP_L" && (
                <div className="absolute left-0 top-0 bottom-0 w-1/2 bg-cyan-500/10 border-r border-dashed border-cyan-500/40 flex items-center justify-center text-cyan-400/50 text-xs tracking-widest uppercase pointer-events-none">
                  Left Snap Zone
                </div>
              )}
              {currentState === "SNAP_R" && (
                <div className="absolute right-0 top-0 bottom-0 w-1/2 bg-cyan-500/10 border-l border-dashed border-cyan-500/40 flex items-center justify-center text-cyan-400/50 text-xs tracking-widest uppercase pointer-events-none">
                  Right Snap Zone
                </div>
              )}

              {/* Target Window Instance */}
              {currentState !== "CLOSED" && (
                <div
                  className="absolute transition-all duration-300 ease-in-out border rounded-md shadow-2xl flex flex-col overflow-hidden"
                  style={{
                    left: `${currentGeometry.x}px`,
                    top: `${currentGeometry.y}px`,
                    width: `${currentGeometry.w}px`,
                    height: `${currentGeometry.h}px`,
                    opacity: currentGeometry.opacity,
                    zIndex: currentGeometry.zIndex,
                    borderColor:
                      currentState === "MAXIMIZED"
                        ? "#38bdf8"
                        : currentState.startsWith("SNAP")
                        ? "#22d3ee"
                        : "#475569",
                    backgroundColor: "#0f172a"
                  }}
                >
                  {/* Universal Window TitleBar */}
                  <div className="h-8 bg-slate-800/90 border-b border-slate-700/60 px-3 flex items-center justify-between text-xs font-sans">
                    <div className="flex items-center gap-2">
                      <Layers className="w-3.5 h-3.5 text-cyan-400" />
                      <span className="font-semibold text-slate-200">App_01 :: Target Instance</span>
                      <span className="text-[10px] px-1.5 py-0.2 bg-slate-700 text-cyan-300 rounded">
                        {currentState}
                      </span>
                    </div>

                    {/* Window Controls */}
                    <div className="flex items-center gap-1.5">
                      <button
                        onClick={() => executeTransition("MINIMIZED")}
                        className="p-1 hover:bg-slate-700 rounded text-slate-400 hover:text-slate-200 transition-colors"
                        title="Minimize"
                      >
                        <Minimize2 className="w-3 h-3" />
                      </button>
                      <button
                        onClick={() =>
                          executeTransition(currentState === "MAXIMIZED" ? "RESTORE" : "MAXIMIZED")
                        }
                        className="p-1 hover:bg-slate-700 rounded text-slate-400 hover:text-slate-200 transition-colors"
                        title="Maximize / Restore"
                      >
                        {currentState === "MAXIMIZED" ? (
                          <Square className="w-3 h-3" />
                        ) : (
                          <Maximize2 className="w-3 h-3" />
                        )}
                      </button>
                      <button
                        onClick={() => executeTransition("CLOSED")}
                        className="p-1 hover:bg-rose-900/80 rounded text-slate-400 hover:text-rose-200 transition-colors"
                        title="Close"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  </div>

                  {/* Window Body Content */}
                  <div className="flex-1 p-4 flex flex-col justify-between text-xs text-slate-400">
                    <div className="space-y-2">
                      <div className="flex justify-between border-b border-slate-800 pb-2">
                        <span>Geometry Matrix:</span>
                        <span className="text-cyan-300">
                          [{currentGeometry.x}, {currentGeometry.y}, {currentGeometry.w}, {currentGeometry.h}]
                        </span>
                      </div>
                      <div className="flex justify-between border-b border-slate-800 pb-2">
                        <span>Z-Index / Opacity:</span>
                        <span className="text-slate-300">
                          z:{currentGeometry.zIndex} | op:{currentGeometry.opacity}
                        </span>
                      </div>
                      <div className="flex justify-between">
                        <span>State Machine Status:</span>
                        <span className="text-emerald-400 font-bold">{currentState}</span>
                      </div>
                    </div>

                    <div className="bg-slate-950/60 p-2.5 rounded border border-slate-800 text-[11px] text-slate-400 flex items-center justify-between">
                      <span className="flex items-center gap-1.5 text-slate-300">
                        <Lock className="w-3 h-3 text-amber-400" /> Core & Bottom Rail Preserved
                      </span>
                      <span className="text-emerald-400">100% Locked</span>
                    </div>
                  </div>
                </div>
              )}

              {/* Bottom System Rail Mock */}
              <div className="absolute bottom-0 inset-x-0 h-10 bg-slate-950/90 border-t border-slate-800/80 px-4 flex items-center justify-between text-xs text-slate-400">
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-1.5 text-slate-200 font-bold">
                    <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
                    SYSTEM BOOT
                  </div>
                  <span className="text-slate-600">|</span>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => executeTransition(currentState === "MINIMIZED" ? "RESTORE" : "MINIMIZED")}
                      className={`px-2 py-1 text-[11px] rounded flex items-center gap-1 border transition-colors ${
                        currentState !== "CLOSED"
                          ? "bg-slate-800 text-cyan-300 border-cyan-500/40"
                          : "bg-slate-900 text-slate-600 border-slate-800"
                      }`}
                    >
                      <Layers className="w-3 h-3" /> App_01
                    </button>
