/* 
====================================================================
SECTION 2: UNIVERSAL WINDOW SHELL — INVARIANT XI 🔒
Strict OS-owned container. Applications pass content only.
====================================================================
*/
interface WindowShellProps {
  instance: AppInstance;
  isFocused: boolean;
  onBringToFront: (id: string) => void;
  onSetWindowState: (id: string, state: WindowState) => void;
  onClose: (id: string) => void;
  onStartDrag: (id: string, e: React.MouseEvent) => void;
  children: React.ReactNode;
}

function UniversalWindowShell({
  instance,
  isFocused,
  onBringToFront,
  onSetWindowState,
  onClose,
  onStartDrag,
  children,
}: WindowShellProps) {
  if (instance.windowState === "MINIMIZED" || instance.lifecycleState === "TERMINATED") return null;

  let style: React.CSSProperties = {
    zIndex: instance.zIndex,
  };

  if (instance.windowState === "MAXIMIZED") {
    style = {
      ...style,
      top: "8px",
      left: "8px",
      width: "calc(100% - 16px)",
      height: "calc(100% - 16px)",
      position: "absolute",
    };
  } else if (instance.windowState === "SNAPPED_L") {
    style = {
      ...style,
      top: "0px",
      left: "0px",
      width: "50%",
      height: "100%",
      position: "absolute",
    };
  } else if (instance.windowState === "SNAPPED_R") {
    style = {
      ...style,
      top: "0px",
      right: "0px",
      width: "50%",
      height: "100%",
      position: "absolute",
    };
  } else {
    style = {
      ...style,
      top: `${instance.position.y}px`,
      left: `${instance.position.x}px`,
      width: `${instance.size.width}px`,
      height: `${instance.size.height}px`,
      position: "absolute",
    };
  }

  return (
    <div
      onClick={() => onBringToFront(instance.id)}
      style={style}
      className={`flex flex-col bg-slate-900 border rounded-lg shadow-2xl overflow-hidden transition-all duration-75 ${
        isFocused
          ? "border-emerald-500/90 shadow-emerald-950/40"
          : "border-slate-800 shadow-black/70 opacity-95 hover:opacity-100"
      }`}
    >
      {/* OS-OWNED INVARIANT TITLE BAR CHROME (HEADER HEIGHT: 36px / h-9) */}
      <div
        onMouseDown={(e) => onStartDrag(instance.id, e)}
        className={`h-9 px-3 flex items-center justify-between border-b cursor-move select-none transition ${
          isFocused ? "bg-slate-800/90 text-slate-100 border-slate-700" : "bg-slate-950/90 text-slate-400 border-slate-800"
        }`}
      >
        {/* [ ICON ] APPLICATION NAME */}
        <div className="flex items-center gap-2 text-xs font-semibold truncate max-w-[65%]">
          <div className="p-1 rounded bg-slate-900 border border-slate-700/60 text-emerald-400 flex-shrink-0">
            {instance.icon === "Sparkles" && <Sparkles className="w-3.5 h-3.5" />}
            {instance.icon === "FileText" && <FileText className="w-3.5 h-3.5" />}
            {instance.icon === "Activity" && <Activity className="w-3.5 h-3.5" />}
            {instance.icon === "Sliders" && <Sliders className="w-3.5 h-3.5" />}
            {instance.icon === "Radio" && <Radio className="w-3.5 h-3.5" />}
          </div>
          <span className="truncate">{instance.title}</span>
        </div>

        {/* UNIFORM INVARIANT CONTROL ACTIONS FOR ALL APPS: [—] [SNAP_L] [SNAP_R] [□] [×] */}
        <div className="flex items-center gap-1 flex-shrink-0">
          <button
            onClick={(e) => {
              e.stopPropagation();
              onSetWindowState(instance.id, "MINIMIZED");
            }}
            title="Minimize"
            className="p-1 rounded text-slate-400 hover:text-slate-100 hover:bg-slate-700/60 transition"
          >
            <Minus className="w-3 h-3" />
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onSetWindowState(instance.id, instance.windowState === "SNAPPED_L" ? "WINDOWED" : "SNAPPED_L");
            }}
            title="Snap Left (50%)"
            className={`p-1 rounded transition ${
              instance.windowState === "SNAPPED_L"
                ? "bg-emerald-950 border border-emerald-700 text-emerald-400"
                : "text-slate-400 hover:text-slate-100 hover:bg-slate-700/60"
            }`}
          >
            <PanelLeft className="w-3 h-3" />
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onSetWindowState(instance.id, instance.windowState === "SNAPPED_R" ? "WINDOWED" : "SNAPPED_R");
            }}
            title="Snap Right (50%)"
            className={`p-1 rounded transition ${
              instance.windowState === "SNAPPED_R"
                ? "bg-emerald-950 border border-emerald-700 text-emerald-400"
                : "text-slate-400 hover:text-slate-100 hover:bg-slate-700/60"
            }`}
          >
            <PanelRight className="w-3 h-3" />
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onSetWindowState(instance.id, instance.windowState === "MAXIMIZED" ? "WINDOWED" : "MAXIMIZED");
            }}
            title={instance.windowState === "MAXIMIZED" ? "Restore" : "Maximize"}
            className={`p-1 rounded transition ${
              instance.windowState === "MAXIMIZED"
                ? "bg-emerald-950 border border-emerald-700 text-emerald-400"
                : "text-slate-400 hover:text-slate-100 hover:bg-slate-700/60"
            }`}
          >
            {instance.windowState === "MAXIMIZED" ? (
              <Minimize2 className="w-3 h-3" />
            ) : (
              <Maximize2 className="w-3 h-3" />
            )}
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onClose(instance.id);
            }}
            title="Close Application (Terminate Lifecycle)"
            className="p-1 rounded text-slate-400 hover:text-red-400 hover:bg-red-950/60 transition"
          >
            <X className="w-3 h-3" />
          </button>
        </div>
      </div>

      {/* ARTIFACT CONTENT (APPLICATION PASSES CONTENT ONLY) */}
      <div className="flex-1 bg-slate-950/90 overflow-auto p-4 text-xs font-mono text-slate-300">
        {children}
      </div>
    </div>
  );
}

