      lifecycleState: "RUNNING",
      zIndex: 14,
      position: { x: 420, y: 190 },
      size: { width: 580, height: 400 },
      startTime: Date.now(),
    },
  ]);

  const [activeWindowId, setActiveWindowId] = useState<string | null>("win-visualizer-1");
  const [maxZIndex, setMaxZIndex] = useState<number>(30);

  // OS Global Navigation & Surface States (Ten-Screen Contract)
  const [showStartMenu, setShowStartMenu] = useState<boolean>(false);
  const [showForensicRack, setShowForensicRack] = useState<boolean>(false);
  const [showHelp, setShowHelp] = useState<boolean>(false);
  const [showAccount, setShowAccount] = useState<boolean>(false);
  const [showSpacesRegistry, setShowSpacesRegistry] = useState<boolean>(false);
  const [isSystemShutDown, setIsSystemShutDown] = useState<boolean>(false);

  // Global Audio Transport Context
  const [audioSource, setAudioSource] = useState<"SYSTEM_BOOT" | "USER_CORPUS" | "EVIDENCE">("SYSTEM_BOOT");
  const [isPlayingBoot, setIsPlayingBoot] = useState<boolean>(false);

  const draggingRef = useRef<{ id: string; startX: number; startY: number; posX: number; posY: number } | null>(null);

  const bringToFront = (id: string) => {
    setActiveWindowId(id);
    const newZ = maxZIndex + 1;
    setMaxZIndex(newZ);
    setWindows((prev) =>
      prev.map((w) =>
        w.id === id
          ? {
              ...w,
              zIndex: newZ,
              windowState: w.windowState === "MINIMIZED" ? "WINDOWED" : w.windowState,
              lifecycleState: "RUNNING",
            }
          : w
      )
    );
  };

  const openApp = (appId: string) => {
    setShowStartMenu(false);
    const manifest = REGISTERED_APPS.find((a) => a.id === appId);
    if (!manifest) return;

    const existing = windows.find((w) => w.appId === appId && w.lifecycleState !== "TERMINATED");
    if (existing) {
      bringToFront(existing.id);
      return;
    }

    const newZ = maxZIndex + 1;
    setMaxZIndex(newZ);
    const newWin: AppInstance = {
      id: `win-${appId}-${Date.now()}`,
      appId: manifest.id,
      title: `${manifest.name} — OS Runtime`,
      icon: manifest.icon,
      windowState: "WINDOWED",
      lifecycleState: "RUNNING",
      zIndex: newZ,
      position: { x: 280 + (windows.length % 5) * 30, y: 50 + (windows.length % 5) * 30 },
      size: { width: manifest.defaultWidth, height: manifest.defaultHeight },
      startTime: Date.now(),
    };
    setWindows((prev) => [...prev, newWin]);
    setActiveWindowId(newWin.id);
  };

  const setWindowState = (id: string, newState: WindowState) => {
    setWindows((prev) =>
      prev.map((w) => {
        if (w.id !== id) return w;

        let lastPos = w.lastPos || w.position;
        let lastSize = w.lastSize || w.size;

        if (w.windowState === "WINDOWED") {
          lastPos = { ...w.position };
          lastSize = { ...w.size };
        }

        let newPos = { ...w.position };
        let newSize = { ...w.size };

        if (newState === "WINDOWED") {
          newPos = lastPos;
          newSize = lastSize;
        }

        const newLifecycle = newState === "MINIMIZED" ? "MINIMIZED" : "RUNNING";

        return {
          ...w,
          windowState: newState,
          lifecycleState: newLifecycle,
          position: newPos,
          size: newSize,
          lastPos,
          lastSize,
        };
      })
    );
  };

  /* 
  ====================================================================
  SECTION 6 & 7: APPLICATION LIFECYCLE (INVARIANT XIII) & FAILURE ISOLATION
  CLOSE = Complete termination and resource flushing.
  ====================================================================
  */
  const closeWindow = (id: string) => {
    setWindows((prev) =>
      prev.map((w) => (w.id === id ? { ...w, lifecycleState: "TERMINATED" } : w))
    );
    if (activeWindowId === id) {
      setActiveWindowId(null);
    }
  };

  const startDrag = (id: string, e: React.MouseEvent) => {
    bringToFront(id);
    const win = windows.find((w) => w.id === id);
    if (!win || win.windowState !== "WINDOWED") return;

    draggingRef.current = {
      id,
      startX: e.clientX,
      startY: e.clientY,
      posX: win.position.x,
      posY: win.position.y,
    };

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (!draggingRef.current) return;
      const dx = moveEvent.clientX - draggingRef.current.startX;
      const dy = moveEvent.clientY - draggingRef.current.startY;
      const targetId = draggingRef.current.id;

      setWindows((prev) =>
        prev.map((w) =>
          w.id === targetId
            ? {
                ...w,
                position: {
                  x: Math.max(0, draggingRef.current!.posX + dx),
                  y: Math.max(0, draggingRef.current!.posY + dy),
                },
              }
            : w
        )
      );
    };

    const handleMouseUp = () => {
      draggingRef.current = null;
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
    };

    window.addEventListener("mousemove", handleMouseMove);
