            <div className="flex justify-between">
              <span className="text-slate-400">Total Records Reported:</span>
              <span
                className={`font-bold ${
                  jsonData?.total_records === targetTotalRecords
                    ? "text-emerald-400"
                    : jsonData?.total_records !== undefined
                    ? "text-rose-400"
                    : "text-slate-500"
                }`}
              >
                {jsonData?.total_records !== undefined ? jsonData.total_records : "UNPARSED"}
