            <div className="flex justify-between">
              <span className="text-slate-400">Required Gate Target:</span>
              <span className="text-indigo-400 font-bold">{targetTotalRecords} records</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Schema Witness Gate:</span>
              <span
                className={`font-bold ${
                  jsonWitnessValid ? "text-emerald-400" : "text-amber-400"
