              />
              <button
                onClick={() => dirInputRef.current?.click()}
                disabled={dirState === "PROCESSING"}
                className="px-4 py-2 bg-cyan-900/60 hover:bg-cyan-800/80 border border-cyan-700 text-cyan-200 text-xs font-bold rounded transition flex items-center gap-2 shadow-lg disabled:opacity-50"
              >
                <FolderOpen className="w-4 h-4 text-cyan-400" />
                Select Corpus Directory
              </button>

              {dirState === "PROCESSING" && (
                <span className="text-xs text-amber-400 flex items-center gap-1.5 animate-pulse">
                  <RefreshCw className="w-3.5 h-3.5 animate-spin text-amber-400" />
                  Hashing & Decoding...
                </span>
              )}
            </div>

            {audioSpecimens.length > 0 && (
              <button
                onClick={handleClearCache}
                className="px-2.5 py-1.5 bg-slate-900 hover:bg-rose-950 border border-slate-700 hover:border-rose-800 text-slate-400 hover:text-rose-300 text-xs rounded transition flex items-center gap-1.5"
                title="Clear IndexedDB Evidence Cache"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Clear Cache
              </button>
