                        </div>
                        <div className="text-[10px] text-slate-500 truncate max-w-xs">
                          {s.relativePath}
                        </div>
                      </td>
                      <td className="p-2.5 text-slate-400">{formatBytes(s.size)}</td>
                      <td className="p-2.5 text-slate-400">{s.type || s.extension}</td>
                      <td className="p-2.5 font-mono text-[11px]">
                        {s.sha256Status === "HASHING" ? (
                          <span className="text-amber-400 animate-pulse">Hashing...</span>
                        ) : s.sha256 ? (
                          <span className="text-cyan-300" title={s.sha256}>
                            {s.sha256.substring(0, 16)}...
