                        ) : (
                          <span className="text-slate-600">Pending</span>
                        )}
                      </td>
                      <td className="p-2.5 text-slate-300 font-mono">
                        {s.pcmStatus === "DECODING" ? (
                          <span className="text-amber-400 animate-pulse">Decoding...</span>
                        ) : s.pcmDecoded ? (
                          <span className="text-emerald-400">{formatSeconds(s.pcmDuration)}</span>
                        ) : (
                          <span className="text-slate-600">--</span>
                        )}
                      </td>
                      <td className="p-2.5 text-slate-400 font-mono">
                        {s.pcmSampleRate ? `${s.pcmSampleRate / 1000} kHz` : "--"}
                      </td>
                      <td className="p-2.5">
                        {s.pcmStatus === "DONE" && s.sha256Status === "DONE" ? (
                          <span className="text-[10px] px-2 py-0.5 rounded bg-emerald-950 border border-emerald-800 text-emerald-300 font-bold flex items-center gap-1 w-fit">
