        item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.physicalAnchor.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.lyricSnippet.toLowerCase().includes(searchQuery.toLowerCase());

