      if (decision === "Advance") {
        const nextGates: Record<string, CorpusItem["gate"]> = { G1: "G2", G2: "G3", G3: "G4", G4: "G5", G5: "G5" };
        const nextGate = nextGates[item.gate];
        return { 
          ...item, 
          gate: nextGate, 
          status: nextGate === "G5" ? "Frozen (G5)" : "In Audit",
          lastAudited: new Date().toISOString().split("T")[0] 
        };
      }
      if (decision === "Demote") {
        const prevGates: Record<string, CorpusItem["gate"]> = { G5: "G4", G4: "G3", G3: "G2", G2: "G1", G1: "G1" };
        return { 
          ...item, 
          gate: prevGates[item.gate], 
