import React, { useState, useEffect, useRef } from "react";
import {
  VisualizerTransform,
  MoodPreset,
  MoodPresetId,
  CompositionObject,
  StudioTrack,
} from "./types";
import { MOOD_PRESETS, INITIAL_OBJECTS, DEMO_TRACKS } from "./constants";
import CanvasRenderer from "./components/CanvasRenderer";
import InspectorDock from "./components/InspectorDock";
import TransportBar from "./components/TransportBar";

export default function Component() {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [currentTrack, setCurrentTrack] = useState<StudioTrack>(DEMO_TRACKS[0]);

  // Visualizer Transform state (Object properties)
  const [transform, setTransform] = useState<VisualizerTransform>({
    x: 50,
    y: 80,
    width: 100,
    height: 60,
    rotation: 0,
    locked: false,
  });

  // Active Mood Preset state
  const [preset, setPreset] = useState<MoodPreset>(MOOD_PRESETS.romantic);

  // Composition objects
  const [objects, setObjects] = useState<CompositionObject[]>(INITIAL_OBJECTS);
  const [selectedObjectId, setSelectedObjectId] = useState<string>("visualizer");

  // Simulated audio buffer for frequency reactivity
  const [audioData, setAudioData] = useState<number[]>(
    Array.from({ length: 64 }, () => Math.random() * 0.4 + 0.1)
  );

  // Playback timer & audio simulation
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime((prev) => (prev >= currentTrack.duration ? 0 : prev + 1));

        // Generate synthetic audio frequencies with peak dynamics
        setAudioData(
          Array.from({ length: 64 }, (_, i) => {
            const base = Math.sin((i / 64) * Math.PI * 4 + Date.now() * 0.005);
            return Math.max(0.1, (base * 0.5 + 0.5) * (Math.random() * 0.6 + 0.4));
          })
        );
      }, 200);
    }
    return () => clearInterval(interval);
  }, [isPlaying, currentTrack.duration]);

  const handleTransformChange = (changes: Partial<VisualizerTransform>) => {
    setTransform((prev) => ({ ...prev, ...changes }));
  };

  const handleSelectMood = (presetId: MoodPresetId) => {
    if (MOOD_PRESETS[presetId]) {
      setPreset(MOOD_PRESETS[presetId]);
    }
  };

  const handlePresetCustomChange = (changes: Partial<MoodPreset>) => {
    setPreset((prev) => ({ ...prev, ...changes, id: "custom", name: "Custom Mood" }));
  };

  const handleToggleObjectVisibility = (id: string) => {
    setObjects((prev) =>
      prev.map((o) => (o.id === id ? { ...o, visible: !o.visible } : o))
    );
  };

  return (
    <div className="min-h-screen w-full flex flex-col bg-slate-950 font-sans antialiased text-slate-100 overflow-hidden select-none">
      {/* Top Workspace Viewport + Right Inspector Dock */}
      <div className="flex-1 flex min-h-0 relative">
        <CanvasRenderer
          objects={objects}
          selectedObjectId={selectedObjectId}
          onSelectObject={(id) => setSelectedObjectId(id)}
          transform={transform}
          preset={preset}
          isPlaying={isPlaying}
          audioData={audioData}
          currentTrack={currentTrack}
        />

        <InspectorDock
          transform={transform}
          onTransformChange={handleTransformChange}
          preset={preset}
          onSelectMood={handleSelectMood}
          onPresetCustomChange={handlePresetCustomChange}
          objects={objects}
          onToggleObjectVisibility={handleToggleObjectVisibility}
          selectedObjectId={selectedObjectId}
          onSelectObject={(id) => setSelectedObjectId(id)}
        />
      </div>

      {/* Bottom Audio Transport & Deck Controls */}
      <TransportBar
        isPlaying={isPlaying}
        onTogglePlay={() => setIsPlaying(!isPlaying)}
        currentTrack={currentTrack}
        tracks={DEMO_TRACKS}
        onSelectTrack={(trk) => {
          setCurrentTrack(trk);
          setCurrentTime(0);
        }}
        currentTime={currentTime}
      />
    </div>
  );
}

export type VisualizerStyle = "wave" | "spectrum" | "ribbon" | "oscilloscope";

export type MoodPresetId = "romantic" | "dream" | "edm" | "acoustic" | "cinematic" | "custom";

export interface VisualizerTransform {
  x: number;       // percentage 0..100
  y: number;       // percentage 0..100
  width: number;   // percentage 10..200
  height: number;  // percentage 10..200
  rotation: number;// degrees 0..360
  locked: boolean;
}

export interface MoodPreset {
  id: MoodPresetId;
  name: string;
  icon: string;
  description: string;
  style: VisualizerStyle;
  sensitivity: number;
  glow: number;
  opacity: number;
  gradient: [string, string];
  lineWidth: number;
  peakMarkers: boolean;
  smoothing: number;
}

export interface CompositionObject {
  id: string;
  name: string;
  type: "artwork" | "logo" | "card" | "text" | "visualizer";
  visible: boolean;
  locked: boolean;
}

export interface StudioTrack {
  id: string;
  title: string;
  artist: string;
  album: string;
  duration: number;
  coverUrl: string;
  audioUrl?: string;
}

import React, { useRef, useEffect } from "react";
import { VisualizerTransform, MoodPreset } from "../types";

interface VisualizerEngineProps {
  transform: VisualizerTransform;
  preset: MoodPreset;
  isPlaying: boolean;
  audioData: number[];
  isSelected: boolean;
  onSelect: () => void;
  widthPx: number;
  heightPx: number;
}

export default function VisualizerEngine({
  transform,
  preset,
  isPlaying,
  audioData,
  isSelected,
  onSelect,
  widthPx,
  heightPx,
}: VisualizerEngineProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const animFrameRef = useRef<number | null>(null);
  const phaseRef = useRef<number>(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let localPhase = phaseRef.current;

    const render = () => {
      ctx.clearRect(0, 0, widthPx, heightPx);

      if (isPlaying) {
        localPhase += 0.05 * (1.1 - preset.smoothing);
        phaseRef.current = localPhase;
      }

      ctx.save();

      // Transform positioning
      const posX = (transform.x / 100) * widthPx;
      const posY = (transform.y / 100) * heightPx;
      const baseObjWidth = (transform.width / 100) * (widthPx * 0.8);
      const baseObjHeight = (transform.height / 100) * (heightPx * 0.3);

      ctx.translate(posX, posY);
      ctx.rotate((transform.rotation * Math.PI) / 180);
      ctx.globalAlpha = preset.opacity;

      // Create gradient
      const grad = ctx.createLinearGradient(
        -baseObjWidth / 2,
        0,
        baseObjWidth / 2,
        0
      );
      grad.addColorStop(0, preset.gradient[0]);
      grad.addColorStop(1, preset.gradient[1]);

      ctx.shadowColor = preset.gradient[0];
      ctx.shadowBlur = preset.glow;
      ctx.strokeStyle = grad;
      ctx.fillStyle = grad;
      ctx.lineWidth = preset.lineWidth;

      const numPoints = 64;

      if (preset.style === "wave") {
        ctx.beginPath();
        for (let i = 0; i < numPoints; i++) {
          const norm = i / (numPoints - 1);
          const x = -baseObjWidth / 2 + norm * baseObjWidth;
          const val = audioData[i % audioData.length] || 0.1;
          const amp = isPlaying ? val * preset.sensitivity : 0.15;
          const y =
            Math.sin(norm * Math.PI * 4 + localPhase) *
            baseObjHeight *
            0.5 *
            amp;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      } else if (preset.style === "spectrum") {
        const barWidth = baseObjWidth / numPoints;
        for (let i = 0; i < numPoints; i++) {
          const norm = i / numPoints;
          const x = -baseObjWidth / 2 + i * barWidth;
          const val = audioData[i % audioData.length] || 0.1;
          const barHeight = isPlaying
            ? val * preset.sensitivity * baseObjHeight
            : baseObjHeight * 0.1;

          ctx.fillRect(x, -barHeight / 2, barWidth * 0.75, barHeight);

          if (preset.peakMarkers && isPlaying) {
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(
              x,
              -barHeight / 2 - 4,
              barWidth * 0.75,
              2
            );
            ctx.fillStyle = grad;
          }
        }
      } else if (preset.style === "ribbon") {
        ctx.beginPath();
        for (let i = 0; i < numPoints; i++) {
          const norm = i / (numPoints - 1);
          const x = -baseObjWidth / 2 + norm * baseObjWidth;
          const val = audioData[i % audioData.length] || 0.1;
          const wave1 = Math.sin(norm * Math.PI * 3 + localPhase);
          const wave2 = Math.cos(norm * Math.PI * 5 - localPhase * 0.8);
          const y = (wave1 + wave2) * 0.5 * baseObjHeight * 0.4 * (isPlaying ? val * preset.sensitivity : 0.2);

          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();

        // Secondary soft fill band
        ctx.save();
        ctx.globalAlpha = preset.opacity * 0.25;
        ctx.lineTo(baseObjWidth / 2, baseObjHeight / 2);
        ctx.lineTo(-baseObjWidth / 2, baseObjHeight / 2);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      } else if (preset.style === "oscilloscope") {
        ctx.beginPath();
        for (let i = 0; i < numPoints; i++) {
          const norm = i / (numPoints - 1);
          const x = -baseObjWidth / 2 + norm * baseObjWidth;
          const val = audioData[i % audioData.length] || 0.05;
          const jitter = isPlaying
            ? (Math.random() - 0.5) * val * preset.sensitivity * baseObjHeight * 0.6
            : 0;
          const y = Math.sin(norm * Math.PI * 8 + localPhase * 2) * 8 + jitter;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      }

      // Selection Bounding Box
      if (isSelected) {
        ctx.save();
        ctx.shadowBlur = 0;
        ctx.strokeStyle = "#38bdf8";
        ctx.lineWidth = 1.5;
        ctx.setLineDash([6, 4]);
        const pad = 12;
        ctx.strokeRect(
          -baseObjWidth / 2 - pad,
          -baseObjHeight / 2 - pad,
          baseObjWidth + pad * 2,
          baseObjHeight + pad * 2
        );

        // Corner handles
        ctx.fillStyle = "#38bdf8";
        const hSize = 6;
        [
          [-baseObjWidth / 2 - pad, -baseObjHeight / 2 - pad],
          [baseObjWidth / 2 + pad, -baseObjHeight / 2 - pad],
          [baseObjWidth / 2 + pad, baseObjHeight / 2 + pad],
          [-baseObjWidth / 2 - pad, baseObjHeight / 2 + pad],
        ].forEach(([cx, cy]) => {
          ctx.fillRect(cx - hSize / 2, cy - hSize / 2, hSize, hSize);
        });

        // Rotation indicator dot top center
        ctx.beginPath();
        ctx.arc(0, -baseObjHeight / 2 - pad - 12, 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }

      ctx.restore();

      animFrameRef.current = requestAnimationFrame(render);
    };

    render();

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
  }, [
    transform,
    preset,
    isPlaying,
    audioData,
    isSelected,
    widthPx,
    heightPx,
  ]);

  return (
    <canvas
      ref={canvasRef}
      width={widthPx}
      height={heightPx}
      onClick={(e) => {
        e.stopPropagation();
        onSelect();
      }}
      className="absolute inset-0 z-20 cursor-pointer pointer-events-auto"
    />
  );
}

import React from "react";
import { StudioTrack } from "../types";
import { Play, Pause, SkipBack, SkipForward, Disc, Volume2, ShieldCheck } from "lucide-react";

interface TransportBarProps {
  isPlaying: boolean;
  onTogglePlay: () => void;
  currentTrack: StudioTrack;
  tracks: StudioTrack[];
  onSelectTrack: (track: StudioTrack) => void;
  currentTime: number;
}

export default function TransportBar({
  isPlaying,
  onTogglePlay,
  currentTrack,
  tracks,
  onSelectTrack,
  currentTime,
}: TransportBarProps) {
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = Math.floor(secs % 60);
    return `${m}:${s < 10 ? "0" : ""}${s}`;
  };

  return (
    <div className="h-16 bg-slate-950/95 border-t border-slate-800/80 px-4 flex items-center justify-between text-slate-200 z-30 select-none">
      {/* Current Track Info */}
      <div className="flex items-center gap-3 w-64">
        <div className="relative group">
          <img
            src={currentTrack.coverUrl}
            alt={currentTrack.title}
            className={`w-10 h-10 rounded border border-slate-700/80 object-cover ${
              isPlaying ? "animate-pulse" : ""
            }`}
          />
          <div className="absolute inset-0 bg-black/40 rounded flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
            <Disc className={`w-5 h-5 text-cyan-400 ${isPlaying ? "animate-spin" : ""}`} />
          </div>
        </div>

        <div className="min-w-0">
          <select
            value={currentTrack.id}
            onChange={(e) => {
              const selected = tracks.find((t) => t.id === e.target.value);
              if (selected) onSelectTrack(selected);
            }}
            className="bg-transparent text-xs font-semibold text-slate-100 hover:text-cyan-300 focus:outline-none cursor-pointer truncate max-w-[170px]"
          >
            {tracks.map((t) => (
              <option key={t.id} value={t.id} className="bg-slate-900 text-slate-200">
                {t.title}
              </option>
            ))}
          </select>
          <div className="text-[10px] text-slate-400 truncate">{currentTrack.artist}</div>
        </div>
      </div>

      {/* Main Playback Controls & Progress */}
      <div className="flex-1 max-w-xl flex flex-col items-center gap-1">
        <div className="flex items-center gap-4">
          <button
            type="button"
            onClick={() => {
              const idx = tracks.findIndex((t) => t.id === currentTrack.id);
              const prev = tracks[(idx - 1 + tracks.length) % tracks.length];
              onSelectTrack(prev);
            }}
            className="p-1.5 text-slate-400 hover:text-slate-100 transition"
          >
            <SkipBack className="w-4 h-4" />
          </button>

