import React, { useState, useRef } from "react";
import { Folder, Play, Pause, ShieldCheck, Download, RefreshCw, Activity, Layers, Lock, AlertTriangle, FileAudio } from "lucide-react";

export type TrackTelemetry = {
  trackId: string;
  fileName: string;
  relativePath: string;
  decoderStatus: "PENDING" | "PASS" | "FAIL";
  measuredStatus: "NOT_MEASURED" | "MEASURED";
  sampleRate?: number;
  channels?: number;
  durationSeconds?: number;
  pcmFrames?: number;
  transientEnergy?: number;
  fingerprint?: string;
  error?: string;
};

export type IngestionStats = {
  filesDiscovered: number;
  audioFiles: number;
  matchedToBaseline: number;
  unmatched: number;
  decodePassed: number;
  decodeFailed: number;
  measured: number;
  notMeasured: number;
};

// Simple DJB2-like hash for fast client-side audio PCM fingerprinting
function generatePcmFingerprint(channelData: Float32Array, sampleRate: number): string {
  let hash = 5381;
  const step = Math.max(1, Math.floor(channelData.length / 1000));
  for (let i = 0; i < channelData.length; i += step) {
    const val = Math.floor((channelData[i] + 1) * 32767);
    hash = ((hash << 5) + hash) ^ val;
  }
  const hex = (hash >>> 0).toString(16).padStart(8, "0");
  return `FP360-${sampleRate}-${hex.toUpperCase()}`;
}

export default function DirectoryScannerSpace() {
  const [telemetryMap, setTelemetryMap] = useState<Record<string, TrackTelemetry>>({});
  const [folderConnected, setFolderConnected] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [currentScanningFile, setCurrentScanningFile] = useState<string>("");
  const [selectedTrackId, setSelectedTrackId] = useState<string | null>(null);

  const folderInputRef = useRef<HTMLInputElement | null>(null);

  const telemetryList = Object.values(telemetryMap);

  const stats: IngestionStats = {
    filesDiscovered: telemetryList.length,
    audioFiles: telemetryList.length,
    matchedToBaseline: telemetryList.filter(t => t.decoderStatus === "PASS").length,
    unmatched: telemetryList.filter(t => t.decoderStatus === "FAIL").length,
    decodePassed: telemetryList.filter(t => t.decoderStatus === "PASS").length,
    decodeFailed: telemetryList.filter(t => t.decoderStatus === "FAIL").length,
    measured: telemetryList.filter(t => t.measuredStatus === "MEASURED").length,
    notMeasured: telemetryList.filter(t => t.measuredStatus === "NOT_MEASURED").length,
  };

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;

    const fileList = Array.from(e.target.files);
    const audioFiles = fileList.filter(f => 
      f.type.startsWith("audio/") || 
      f.name.endsWith(".mp3") || 
      f.name.endsWith(".wav") || 
      f.name.endsWith(".m4a") || 
      f.name.endsWith(".flac")
    );

    setFolderConnected(true);
    setIsScanning(true);

    const initialMap: Record<string, TrackTelemetry> = {};
    audioFiles.forEach((f, idx) => {
      const trackId = `TRK-${(idx + 1).toString().padStart(3, "0")}`;
      initialMap[trackId] = {
        trackId,
        fileName: f.name,
        relativePath: (f as any).webkitRelativePath || f.name,
        decoderStatus: "PENDING",
        measuredStatus: "NOT_MEASURED",
      };
    });

    setTelemetryMap(initialMap);

    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();

    for (let i = 0; i < audioFiles.length; i++) {
      const file = audioFiles[i];
      const trackId = `TRK-${(i + 1).toString().padStart(3, "0")}`;
      setCurrentScanningFile(file.name);

      try {
        const arrayBuffer = await file.arrayBuffer();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);

        const channelData = audioBuffer.getChannelData(0);
        const sampleRate = audioBuffer.sampleRate;
        const channels = audioBuffer.numberOfChannels;
        const durationSeconds = Number(audioBuffer.duration.toFixed(3));
        const pcmFrames = audioBuffer.length;

        let maxPeak = 0;
        for (let j = 0; j < channelData.length; j += 100) {
          const abs = Math.abs(channelData[j]);
          if (abs > maxPeak) maxPeak = abs;
        }

        const fingerprint = generatePcmFingerprint(channelData, sampleRate);

        setTelemetryMap(prev => ({
          ...prev,
          [trackId]: {
            ...prev[trackId],
            decoderStatus: "PASS",
            measuredStatus: "MEASURED",
            sampleRate,
            channels,
            durationSeconds,
            pcmFrames,
            transientEnergy: Number((20 * Math.log10(maxPeak || 0.0001)).toFixed(2)),
            fingerprint,
          }
        }));
      } catch (err: any) {
        setTelemetryMap(prev => ({
          ...prev,
          [trackId]: {
            ...prev[trackId],
            decoderStatus: "FAIL",
            measuredStatus: "NOT_MEASURED",
            error: err?.message || "WebAudio PCM Decode Failed",
          }
        }));
      }
    }

    await audioCtx.close();
    setIsScanning(false);
    setCurrentScanningFile("");
  };

  const exportTelemetry = () => {
    const data = {
      header: "ELYZARETH OS v38.0 PASS-3 EVIDENCE TELEMETRY",
      timestamp: new Date().toISOString(),
      stats,
      telemetry: telemetryList,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `pass3_evidence_telemetry_${Date.now()}.json`;
    a.click();
  };

  const selectedTrack = selectedTrackId ? telemetryMap[selectedTrackId] : null;

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col p-6 font-mono">
      {/* Header */}
      <header className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 pb-6 border-b border-slate-800">
        <div>
          <div className="flex items-center gap-3">
            <ShieldCheck className="w-8 h-8 text-emerald-400" />
            <h1 className="text-xl md:text-2xl font-bold tracking-tight text-white">
              🔬 Audio Corpus Directory Scanner
            </h1>
          </div>
          <p className="text-xs text-slate-400 mt-1">
            Pass-3 Client-Side Evidence Layer &bull; Immutable 360 Baseline &bull; PCM Validation Gate
          </p>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <input
            type="file"
            ref={folderInputRef}
            onChange={handleFolderSelect}
            // @ts-ignore
            webkitdirectory=""
            directory=""
            multiple
            className="hidden"
          />
          <button
            onClick={() => folderInputRef.current?.click()}
            disabled={isScanning}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 active:bg-emerald-700 text-slate-950 font-bold rounded-lg shadow-lg shadow-emerald-500/20 transition disabled:opacity-50 text-xs"
          >
            <Folder className="w-4 h-4" />
            {folderConnected ? "Rescan Directory" : "Select Corpus Directory"}
          </button>

          <button
            onClick={exportTelemetry}
            disabled={telemetryList.length === 0}
            className="flex items-center gap-2 px-4 py-2 bg-sky-500 hover:bg-sky-600 active:bg-sky-700 text-slate-950 font-bold rounded-lg shadow-lg shadow-sky-500/20 transition text-xs disabled:opacity-40 disabled:cursor-not-allowed"
          >
            <Download className="w-4 h-4" />
            Export Telemetry JSON
          </button>
        </div>
      </header>

      {/* Protocol Dashboard Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-3 my-6 text-xs">
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Corpus</div>
          <div className="text-lg font-bold text-sky-400 mt-0.5">360 READY</div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Folder</div>
          <div className={`text-lg font-bold mt-0.5 ${folderConnected ? "text-emerald-400" : "text-amber-400"}`}>
            {folderConnected ? "Connected" : "Disconnected"}
          </div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Discovered</div>
          <div className="text-lg font-bold text-white mt-0.5">{stats.filesDiscovered || "—"}</div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Audio Decoded</div>
          <div className="text-lg font-bold text-emerald-400 mt-0.5">{stats.decodePassed || "—"}</div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Fingerprinted</div>
          <div className="text-lg font-bold text-sky-400 mt-0.5">{stats.measured || "—"}</div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">NOT MEASURED</div>
          <div className="text-lg font-bold text-amber-400 mt-0.5">{stats.notMeasured || "—"}</div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Stage Gate</div>
          <div className="text-lg font-bold text-emerald-400 mt-0.5 flex items-center gap-1">
            <Lock className="w-3.5 h-3.5" />
            LOCKED
          </div>
        </div>
        <div className="bg-slate-900 border border-slate-800 rounded-lg p-3">
          <div className="text-slate-500">Credits</div>
          <div className="text-lg font-bold text-slate-300 mt-0.5">0.00</div>
        </div>
      </div>

      {isScanning && (
        <div className="bg-slate-900/90 border border-emerald-500/40 p-4 rounded-lg mb-6 flex items-center justify-between text-xs text-emerald-400">
          <div className="flex items-center gap-3">
            <RefreshCw className="w-4 h-4 animate-spin" />
            <span>Scanning PCM: <strong className="text-white">{currentScanningFile}</strong></span>
          </div>
          <span>{stats.measured} / {stats.filesDiscovered} Decoded</span>
        </div>
      )}

      {/* Main Body */}
      {telemetryList.length === 0 ? (
        <div className="flex-1 flex flex-col items-center justify-center rounded-xl border-2 border-dashed border-slate-800 bg-slate-900/50 p-12 text-center my-6">
          <Folder className="w-16 h-16 text-slate-600 mb-4 animate-pulse" />
          <h2 className="text-xl font-semibold text-slate-200">No Local Audio Directory Selected</h2>
          <p className="text-xs text-slate-400 max-w-md mt-2 leading-relaxed">
