          <div className="lg:col-span-2 bg-slate-900 border border-slate-800 rounded-xl flex flex-col overflow-hidden">
            <div className="p-3 border-b border-slate-800 text-xs font-semibold text-slate-400 flex items-center justify-between">
              <span>TRACK TELEMETRY LEDGER ({telemetryList.length} FILES)</span>
              <span>MEASUREMENT GATE: STRICT PCM</span>
            </div>

            <div className="flex-1 overflow-y-auto divide-y divide-slate-800/60 text-xs">
              {telemetryList.map((track) => {
                const isSelected = selectedTrackId === track.trackId;
                return (
                  <div
                    key={track.trackId}
                    onClick={() => setSelectedTrackId(track.trackId)}
                    className={`p-3 flex items-center justify-between gap-4 cursor-pointer transition ${
                      isSelected ? "bg-slate-800/90 border-l-4 border-emerald-400" : "hover:bg-slate-800/40"
