                        <div className="text-[10px] text-slate-500 truncate">{track.relativePath}</div>
                      </div>
                    </div>

                    <div className="flex items-center gap-4 shrink-0 text-right">
                      {track.decoderStatus === "PASS" ? (
                        <div>
                          <div className="text-emerald-400 font-bold text-[10px]">
                            {track.sampleRate}Hz &bull; {track.durationSeconds}s
                          </div>
                          <div className="text-[10px] text-sky-400 font-mono">{track.fingerprint}</div>
                        </div>
                      ) : (
