                      }`}>
                        {track.measuredStatus}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Inspector Panel */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 flex flex-col overflow-y-auto text-xs">
            <h3 className="font-bold text-slate-300 pb-3 border-b border-slate-800 flex items-center gap-2">
