import React, { useState, useMemo } from "react";
import { Upload, FileText, Filter, Layers, ShieldCheck } from "lucide-react";

interface SongItem {
  id?: string;
  baseTitle?: string;
  title?: string;
  version?: string | number;
  versionTotal?: number;
  tags?: string;
  lyrics?: string;
  model?: string;
  duration?: number;
  createdAt?: string;
  filePath?: string;
  [key: string]: any;
}

interface ProcessedSong {
  id: string;
  baseTitle: string;
  version: string;
  tags: string;
  lyrics: string;
  model: string;
  duration: string;
  status: "READY" | "CURE" | "REJECT" | "UNCERTAIN";
  cureNotes?: string;
  evidenceScore: number;
  isBestVersion: boolean;
  raw: SongItem;
}

export default function Component() {
  const [songs, setSongs] = useState<ProcessedSong[]>([]);
  const [fileName, setFileName] = useState<string>("");
  const [filterStatus, setFilterStatus] = useState<string>("ALL");
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [selectedSong, setSelectedSong] = useState<ProcessedSong | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileName(file.name);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        const rawList: SongItem[] = Array.isArray(json) ? json : json.clips || json.songs || [];
        processCorpus(rawList);
      } catch (err) {
        alert("Failed to parse JSON file.");
      }
    };
    reader.readAsText(file);
  };

  const processCorpus = (rawList: SongItem[]) => {
    const groups: { [baseTitle: string]: SongItem[] } = {};

    rawList.forEach((item, idx) => {
      const base = item.baseTitle || item.title || `Untitled_${idx}`;
      if (!groups[base]) groups[base] = [];
      groups[base].push(item);
    });

    const processed: ProcessedSong[] = [];

    Object.keys(groups).forEach((baseTitle) => {
      const versions = groups[baseTitle];

      let bestIdx = 0;
      let maxScore = -1;

      versions.forEach((v, idx) => {
        const lyricLen = (v.lyrics || "").length;
        const dur = v.duration || 0;
        const score = lyricLen * 0.4 + dur * 0.6;
        if (score > maxScore) {
          maxScore = score;
          bestIdx = idx;
        }
      });

      versions.forEach((v, idx) => {
        const isBest = idx === bestIdx;
        const lyricsText = v.lyrics || "";
        const tagsText = v.tags || "";

        let status: "READY" | "CURE" | "REJECT" | "UNCERTAIN" = "UNCERTAIN";
        let cureNotes = "";

        if (!lyricsText || lyricsText.trim().length < 20) {
          status = "REJECT";
          cureNotes = "Empty or incomplete lyrics payload.";
        } else if (lyricsText.includes("[Instrumental]") || tagsText.toLowerCase().includes("instrumental")) {
          status = "READY";
          cureNotes = "Instrumental specimen - G2 frozen baseline candidate.";
        } else if (lyricsText.length > 50 && isBest) {
          status = "READY";
          cureNotes = "Primary version candidate with intact lyric payload.";
        } else if (!isBest) {
          status = "CURE";
          cureNotes = "Secondary version - compare against primary before archiving.";
        }

        processed.push({
          id: v.id || `${baseTitle}_v${v.version || idx + 1}`,
          baseTitle,
          version: String(v.version || idx + 1),
          tags: tagsText,
          lyrics: lyricsText,
          model: v.model || "Suno v3/v4",
          duration: v.duration ? `${Math.round(v.duration)}s` : "N/A",
          status,
          cureNotes,
          evidenceScore: Math.min(100, Math.round((lyricsText.length / 10) + ((v.duration || 0) / 2))),
          isBestVersion: isBest,
          raw: v,
        });
      });
    });

    setSongs(processed);
  };

  const counts = useMemo(() => {
    return {
      total: songs.length,
      ready: songs.filter((s) => s.status === "READY").length,
      cure: songs.filter((s) => s.status === "CURE").length,
      reject: songs.filter((s) => s.status === "REJECT").length,
      uncertain: songs.filter((s) => s.status === "UNCERTAIN").length,
      baseTitles: new Set(songs.map((s) => s.baseTitle)).size,
    };
  }, [songs]);

  const filteredSongs = useMemo(() => {
    return songs.filter((song) => {
      const matchesStatus = filterStatus === "ALL" || song.status === filterStatus;
      const matchesSearch =
        song.baseTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
        song.tags.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesStatus && matchesSearch;
    });
  }, [songs, filterStatus, searchTerm]);

  const toggleStatus = (id: string, newStatus: "READY" | "CURE" | "REJECT" | "UNCERTAIN") => {
    setSongs((prev) =>
      prev.map((s) => (s.id === id ? { ...s, status: newStatus } : s))
    );
  };

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col p-6 font-mono text-sm">
      <header className="flex items-center justify-between pb-6 border-b border-slate-800">
        <div className="flex items-center gap-3">
          <ShieldCheck className="w-8 h-8 text-emerald-400" />
          <div>
            <h1 className="text-xl font-bold tracking-wider text-slate-100">ELDS CORPUS CURATOR v38.0</h1>
            <p className="text-xs text-slate-400">Pass 1 Forensic Triage Engine — Zero Render / Zero Credit Cost</p>
          </div>
        </div>

        <label className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-slate-950 px-4 py-2 rounded font-semibold cursor-pointer transition">
          <Upload className="w-4 h-4" />
          <span>{fileName ? "Change JSON" : "Upload JSON Directory"}</span>
          <input type="file" accept=".json" onChange={handleFileUpload} className="hidden" />
        </label>
      </header>

      {songs.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-6 gap-4 my-6">
          <div className="bg-slate-900 border border-slate-800 p-4 rounded">
            <p className="text-xs text-slate-400">Total Versions</p>
            <p className="text-2xl font-bold text-slate-100">{counts.total}</p>
            <p className="text-[10px] text-slate-500">{counts.baseTitles} Base Titles</p>
          </div>
          <div className="bg-slate-900 border border-emerald-900/50 p-4 rounded">
            <p className="text-xs text-emerald-400">🟢 READY</p>
            <p className="text-2xl font-bold text-emerald-400">{counts.ready}</p>
          </div>
          <div className="bg-slate-900 border border-amber-900/50 p-4 rounded">
            <p className="text-xs text-amber-400">🟡 CURE</p>
            <p className="text-2xl font-bold text-amber-400">{counts.cure}</p>
          </div>
          <div className="bg-slate-900 border border-rose-900/50 p-4 rounded">
            <p className="text-xs text-rose-400">🔴 REJECT</p>
            <p className="text-2xl font-bold text-rose-400">{counts.reject}</p>
          </div>
          <div className="bg-slate-900 border border-slate-800 p-4 rounded">
            <p className="text-xs text-slate-400">❔ UNCERTAIN</p>
            <p className="text-2xl font-bold text-slate-400">{counts.uncertain}</p>
          </div>
          <div className="bg-slate-900 border border-indigo-900/50 p-4 rounded">
            <p className="text-xs text-indigo-400">Survivor Rate</p>
            <p className="text-2xl font-bold text-indigo-400">
              {Math.round((counts.ready / counts.total) * 100 || 0)}%
            </p>
          </div>
        </div>
      )}

      {songs.length > 0 && (
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 mb-6">
          <input
            type="text"
            placeholder="Search base titles or tags..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full md:w-96 bg-slate-900 border border-slate-800 text-slate-200 px-4 py-2 rounded focus:outline-none focus:border-emerald-500"
          />

          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-slate-400" />
            {["ALL", "READY", "CURE", "REJECT", "UNCERTAIN"].map((st) => (
              <button
                key={st}
                onClick={() => setFilterStatus(st)}
                className={`px-3 py-1 rounded text-xs font-semibold ${
                  filterStatus === st
                    ? "bg-slate-100 text-slate-950"
                    : "bg-slate-900 text-slate-400 border border-slate-800 hover:text-slate-200"
                }`}
              >
                {st}
              </button>
            ))}
          </div>
        </div>
      )}

      {songs.length === 0 ? (
        <div className="flex-1 flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-lg p-12 text-center">
          <Layers className="w-16 h-16 text-slate-600 mb-4" />
          <h2 className="text-lg font-semibold text-slate-300">Awaiting Corpus JSON Intake</h2>
          <p className="text-xs text-slate-500 max-w-md my-2">
            Upload your directory export JSON (e.g. download (49).json) to trigger Pass 1 automated version competition, evidence scoring, and forensic triage.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1">
          <div className="md:col-span-2 bg-slate-900 border border-slate-800 rounded flex flex-col h-[600px] overflow-hidden">
            <div className="p-3 bg-slate-950 border-b border-slate-800 font-bold text-slate-400 text-xs grid grid-cols-12 gap-2">
              <span className="col-span-5">Base Title</span>
              <span className="col-span-2">Version</span>
              <span className="col-span-2">Score</span>
              <span className="col-span-3">Status</span>
            </div>
            <div className="overflow-y-auto flex-1 divide-y divide-slate-800/50">
              {filteredSongs.map((song) => (
                <div
                  key={song.id}
                  onClick={() => setSelectedSong(song)}
                  className={`p-3 grid grid-cols-12 gap-2 items-center cursor-pointer hover:bg-slate-800/40 transition ${
                    selectedSong?.id === song.id ? "bg-slate-800/80 border-l-4 border-emerald-400" : ""
                  }`}
                >
                  <div className="col-span-5 truncate font-medium text-slate-200 flex items-center gap-2">
                    {song.isBestVersion && <span className="text-emerald-400 text-xs">★</span>}
                    {song.baseTitle}
                  </div>
                  <div className="col-span-2 text-slate-400 text-xs">v{song.version}</div>
                  <div className="col-span-2 text-slate-400 text-xs">{song.evidenceScore}/100</div>
                  <div className="col-span-3 flex items-center gap-1">
                    {song.status === "READY" && (
                      <span className="bg-emerald-950 text-emerald-400 border border-emerald-800 text-[10px] px-2 py-0.5 rounded font-bold">
                        READY
                      </span>
                    )}
                    {song.status === "CURE" && (
                      <span className="bg-amber-950 text-amber-400 border border-amber-800 text-[10px] px-2 py-0.5 rounded font-bold">
                        CURE
                      </span>
                    )}
                    {song.status === "REJECT" && (
                      <span className="bg-rose-950 text-rose-400 border border-rose-800 text-[10px] px-2 py-0.5 rounded font-bold">
                        REJECT
                      </span>
                    )}
                    {song.status === "UNCERTAIN" && (
                      <span className="bg-slate-800 text-slate-400 text-[10px] px-2 py-0.5 rounded font-bold">
                        REVIEW
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-slate-900 border border-slate-800 rounded p-4 flex flex-col h-[600px]">
            {selectedSong ? (
              <div className="flex flex-col h-full gap-4">
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs text-slate-500">FORENSIC INSPECTOR</span>
                    {selectedSong.isBestVersion && (
                      <span className="text-[10px] text-emerald-400 bg-emerald-950 border border-emerald-800 px-2 py-0.5 rounded">
                        PRIMARY SURVIVOR
                      </span>
                    )}
                  </div>
                  <h3 className="text-lg font-bold text-slate-100">{selectedSong.baseTitle}</h3>
                  <p className="text-xs text-slate-400">
                    Version: {selectedSong.version} | Duration: {selectedSong.duration}
