export default function Component() {
  const [activeTab, setActiveTab] = useState<TabType>("m60_forensic");
  const [selectedSpecimen, setSelectedSpecimen] = useState<Specimen>(SPECIMENS[3]); // R2.6 default
  const [simDelay, setSimDelay] = useState<number>(0.425);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // Waveform canvas rendering for active specimen
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId: number;
    let phase = 0;

    const render = () => {
      ctx.fillStyle = "#090d16";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid lines (seconds 0 to 3)
      ctx.strokeStyle = "rgba(255, 255, 255, 0.07)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 30; i++) {
        const x = (i / 30) * canvas.width;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();

        if (i % 5 === 0) {
          ctx.fillStyle = "rgba(148, 163, 184, 0.4)";
          ctx.font = "10px monospace";
          ctx.fillText(`${(i / 10).toFixed(1)}s`, x + 3, canvas.height - 6);
        }
      }

      // Draw baseline room floor noise
      ctx.beginPath();
      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1.5;
      for (let x = 0; x < canvas.width; x++) {
        const noise = (Math.sin(x * 0.1 + phase) * 2) + (Math.random() - 0.5) * 3;
        const y = canvas.height / 2 + noise;
        if (x === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();

      const obsG = selectedSpecimen.observedGamma;
      const obsB = selectedSpecimen.observedBeta2;

      // Draw Gamma Onset Pulse if present
      if (obsG !== null) {
        const xG = (obsG / 3.0) * canvas.width;
        // Marker line
        ctx.strokeStyle = "#10b981";
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(xG, 0);
        ctx.lineTo(xG, canvas.height);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = "#10b981";
        ctx.fillText(`Γ Onset (${obsG.toFixed(3)}s)`, xG + 4, 20);

        // Transient Spike
        ctx.beginPath();
        ctx.strokeStyle = "#34d399";
        ctx.lineWidth = 2;
        const h = canvas.height / 2;
        ctx.moveTo(xG - 5, h);
        ctx.lineTo(xG, h - 35);
        ctx.lineTo(xG + 15, h + 25);
        ctx.lineTo(xG + 30, h - 10);
        ctx.lineTo(xG + 50, h);
        ctx.stroke();
      }

      // Draw Beta Secondary Pulse if present
      if (obsB !== null) {
        const xB = (obsB / 3.0) * canvas.width;
        ctx.strokeStyle = selectedSpecimen.status === "pass" ? "#10b981" : selectedSpecimen.status === "local_lock" ? "#f59e0b" : "#ef4444";
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(xB, 0);
        ctx.lineTo(xB, canvas.height);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = ctx.strokeStyle;
        ctx.fillText(`β₂ Onset (${obsB.toFixed(3)}s)`, xB + 4, 38);

        // Transient Spike
        ctx.beginPath();
        ctx.lineWidth = 2;
        const h = canvas.height / 2;
        ctx.moveTo(xB - 5, h);
        ctx.lineTo(xB, h - 30);
        ctx.lineTo(xB + 12, h + 20);
        ctx.lineTo(xB + 25, h - 8);
        ctx.lineTo(xB + 45, h);
        ctx.stroke();
      }

      // Highlight Δt_obs region
      if (obsG !== null && obsB !== null) {
        const xG = (obsG / 3.0) * canvas.width;
        const xB = (obsB / 3.0) * canvas.width;
        ctx.fillStyle = selectedSpecimen.status === "pass" ? "rgba(16, 185, 129, 0.12)" : selectedSpecimen.status === "local_lock" ? "rgba(245, 158, 11, 0.15)" : "rgba(239, 68, 68, 0.15)";
        ctx.fillRect(xG, 0, xB - xG, canvas.height);

        ctx.fillStyle = "#f8fafc";
        ctx.font = "bold 11px monospace";
        const midX = (xG + xB) / 2;
        ctx.fillText(`Δt_obs = ${selectedSpecimen.observedDt?.toFixed(3)}s`, midX - 40, canvas.height / 2 + 35);
      }

      // Pending Banner if R2.6
      if (selectedSpecimen.status === "pending") {
        ctx.fillStyle = "rgba(15, 23, 42, 0.85)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fbbf24";
        ctx.font = "bold 14px monospace";
        ctx.textAlign = "center";
        ctx.fillText("🔬 MEASUREMENT BLOCKED / CAPTION LAYER HOLD", canvas.width / 2, canvas.height / 2 - 10);
