                    )}

                    {/* Notes & Actions Block */}
                    <div className="mb-6">
                      <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2 font-mono">
                        Version Inspection Diagnostics
                      </label>
                      <textarea
                        value={currentActiveVersion.notes || ""}
                        onChange={(e) => handleNotesChange(activeSpecimen.id, currentActiveVersion.versionId, e.target.value)}
                        className="w-full h-24 bg-slate-950 border border-slate-800 rounded-lg p-3 text-xs text-slate-300 focus:outline-none focus:border-slate-700 font-mono leading-relaxed"
                        placeholder="Log physical acoustic mutations or arrangement leakage vectors here..."
