                        </div>
                      </div>

                      {/* Historical Run Tracking (Layer 10 Trend View) */}
                      <div className="border-t border-slate-800/40 pt-2 space-y-1.5">
                        <span className="block text-[9px] font-mono text-slate-500 uppercase tracking-wider">Preservation Trends (Delta Log)</span>
                        <div className="space-y-1 max-h-[100px] overflow-y-auto pr-1">
                          {historyLog.map((run, idx) => {
                            const prevRun = idx > 0 ? historyLog[idx - 1] : null;
                            const diff = prevRun ? run.preservation - prevRun.preservation : 0;
                            const diffText = diff >= 0 ? `+${diff}` : `${diff}`;
                            const diffClass = diff > 0 ? "text-teal-400" : diff < 0 ? "text-rose-400" : "text-slate-500";

                            return (
                              <div key={run.runId} className="flex justify-between items-center text-[10px] bg-slate-900/40 px-2 py-1 rounded font-mono">
                                <span className="text-slate-400">Run #{run.runId} <span className="text-slate-500 text-[9px]">({run.title})</span></span>
                                <div className="flex gap-2">
                                  <span className="text-slate-300">Pres: {run.preservation}%</span>
                                  {prevRun && (
                                    <span className={diffClass}>{diffText}</span>
                                  )}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  )}
