                      </>
                    )}
                  </button>
                </div>
              )}
            </div>

          </div>

          {/* Render Output Area */}
          {generatedClip && (
            <div className="bg-gradient-to-r from-teal-950/45 to-indigo-950/45 border border-teal-500/20 rounded-3xl p-5 flex flex-col sm:flex-row items-center gap-5">
              {generatedClip.coverImageUrl ? (
                <img src={generatedClip.coverImageUrl} alt="Cover" className="w-24 h-24 rounded-2xl object-cover shadow-lg border border-teal-500/10" />
              ) : (
                <div className="w-24 h-24 bg-slate-900 border border-slate-800 rounded-2xl flex items-center justify-center">
                  <Heart className="w-8 h-8 text-teal-400 animate-pulse" />
                </div>
              )}
              <div className="flex-1 w-full text-center sm:text-left space-y-2">
                <div>
                  <div className="flex items-center justify-center sm:justify-start gap-2">
                    <span className="text-[10px] bg-teal-500/10 text-teal-300 border border-teal-500/20 px-1.5 py-0.5 rounded font-mono font-bold uppercase tracking-wider">Studio Render</span>
                    <span className="text-[10px] font-mono text-slate-500">Seed: {generatedClip.seed || "Dynamic"}</span>
                  </div>
                  <h3 className="text-base font-bold text-slate-200 mt-1">{generatedClip.title}</h3>
                  <p className="text-xs text-slate-400 font-mono">{selectedStyle} Target</p>
                </div>
                <audio src={generatedClip.audioUrl} controls className="w-full mt-2 accent-teal-500 filter drop-shadow" />
              </div>
            </div>
          )}

        </div>

      </div>

    </div>
  );
}

import React, { useState, useRef, useEffect } from "react";
import { Play, Pause, RotateCcw, Volume2, Sliders, Music, CheckCircle2, Moon, Eye, Feather } from "lucide-react";

// Types
interface Track {
  id: string;
  title: string;
  role: string;
  url: string;
  description: string;
  principles: string[];
}

export default function Component() {
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [currentTrackIndex, setCurrentTrackIndex] = useState<number>(0);
  const [volume, setVolume] = useState<number>(0.8);
  const [currentTime, setCurrentTime] = useState<number>(0);
  const [duration, setDuration] = useState<number>(0);
  const [activeTab, setActiveTab] = useState<"console" | "manifesto" | "structure">("console");

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const tracks: Track[] = [
    {
      id: "4f1a797b-7689-4a8f-8f39-1f21c1791ebd",
      title: "After the Instruments Fell Silent (Take 1)",
      role: "Canonical Trilogy Ending",
      url: "https://storage.googleapis.com/producer-app-public/clips/4f1a797b-7689-4a8f-8f39-1f21c1791ebd.m4a",
      description: "The narrator slowly reconnects with the world. A solitary, exposed baritone voice carrying the full narrative weight, meeting subtle, distant vocal echoes on the final line as a real-time discovery of belonging.",
      principles: [
        "Solitary baritone witness carries the weight",
        "Arrangement as the narrative journey",
        "Echoes of others arrive only at the destination"
      ]
    },
    {
      id: "37886545-97ab-4b40-8480-ce7d327bbd48",
      title: "After the Instruments Fell Silent (Listener Version)",
      role: "Intimate Shadow / Campfire Testimony",
      url: "https://storage.googleapis.com/producer-app-public/clips/37886545-97ab-4b40-8480-ce7d327bbd48.m4a",
      description: "The narrator sits quietly after the realization. Extremely close mic presence, emphasizing the wood of the guitar and the breath of the storyteller, prioritizing silence and room acoustics.",
      principles: [
        "Porch-session microphone intimacy",
        "Silence and breath as musical values",
        "Completely stripped of vocal harmonies"
      ]
    }
  ];

  const currentTrack = tracks[currentTrackIndex];

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume]);

  useEffect(() => {
    setIsPlaying(false);
    setCurrentTime(0);
  }, [currentTrackIndex]);

  const handlePlayPause = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      audioRef.current.play().then(() => {
        setIsPlaying(true);
      }).catch((e) => console.log("Playback failed:", e));
    }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
    }
  };

  const handleLoadedMetadata = () => {
    if (audioRef.current) {
      setDuration(audioRef.current.duration);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (audioRef.current) {
      audioRef.current.currentTime = val;
      setCurrentTime(val);
    }
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds < 10 ? "0" : ""}${seconds}`;
  };

  return (
    <div className="min-h-screen w-full bg-[#12141c] text-[#d1d5db] flex flex-col items-center justify-center p-4 md:p-8 font-sans">
      <div className="w-full max-w-4xl bg-[#1a1d29] rounded-2xl border border-[#2b3044] shadow-2xl overflow-hidden flex flex-col md:flex-row">

        {/* Left Side: Navigation & Identity Info */}
        <div className="w-full md:w-80 bg-[#151722] p-6 border-b md:border-b-0 md:border-r border-[#2b3044] flex flex-col justify-between">
          <div>
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-[#2d324d] rounded-lg text-emerald-400">
                <Moon className="w-5 h-5" />
              </div>
              <div>
                <h1 className="text-md font-semibold tracking-wider text-white uppercase">Elyzareth OS</h1>
                <p className="text-xs text-gray-400">v33.0 • Baseline Active</p>
              </div>
            </div>

            <div className="space-y-1 mb-8">
              <button
                onClick={() => setActiveTab("console")}
                className={`w-full text-left px-4 py-2.5 rounded-lg text-sm transition-all flex items-center gap-3 ${
                  activeTab === "console" ? "bg-[#21263c] text-white font-medium border-l-2 border-emerald-400" : "text-gray-400 hover:bg-[#1a1d2d] hover:text-white"
                }`}
              >
                <Sliders className="w-4 h-4" /> Console Playback
              </button>
              <button
                onClick={() => setActiveTab("manifesto")}
                className={`w-full text-left px-4 py-2.5 rounded-lg text-sm transition-all flex items-center gap-3 ${
                  activeTab === "manifesto" ? "bg-[#21263c] text-white font-medium border-l-2 border-emerald-400" : "text-gray-400 hover:bg-[#1a1d2d] hover:text-white"
                }`}
              >
                <Feather className="w-4 h-4" /> The Human Rule
              </button>
              <button
                onClick={() => setActiveTab("structure")}
                className={`w-full text-left px-4 py-2.5 rounded-lg text-sm transition-all flex items-center gap-3 ${
                  activeTab === "structure" ? "bg-[#21263c] text-white font-medium border-l-2 border-emerald-400" : "text-gray-400 hover:bg-[#1a1d2d] hover:text-white"
                }`}
              >
                <Eye className="w-4 h-4" /> Trilogy Framework
              </button>
            </div>
          </div>

          <div className="mt-auto pt-6 border-t border-[#2b3044]/60 text-xs text-gray-500">
            <p>EP Campaign: The Human Journey</p>
            <p className="mt-1 font-mono text-[10px]">CURRENT: FREEZE PROTOCOL ACTIVE</p>
          </div>
        </div>

        {/* Right Side: Main Content Space */}
        <div className="flex-1 p-6 md:p-8 flex flex-col justify-between min-h-[500px]">

          {activeTab === "console" && (
            <div className="space-y-6">
              <div>
                <span className="text-[10px] font-mono tracking-widest text-emerald-400 uppercase bg-emerald-950/40 px-2 py-1 rounded border border-emerald-800/30">
                  Ready for Review
                </span>
                <h2 className="text-xl font-bold text-white mt-3">Movement Three: After the Instruments Fell Silent</h2>
                <p className="text-xs text-gray-400 mt-1">Select a monitor output below to compare presence angles.</p>
              </div>

              {/* Monitor selector cards */}
              <div className="grid grid-cols-1 gap-3">
                {tracks.map((track, idx) => (
                  <button
                    key={track.id}
                    onClick={() => setCurrentTrackIndex(idx)}
                    className={`w-full text-left p-4 rounded-xl border transition-all duration-200 ${
                      currentTrackIndex === idx
                        ? "bg-[#21263c] border-emerald-500/40 shadow-lg"
                        : "bg-[#181a24] border-[#2b3044]/60 hover:border-gray-500/30"
                    }`}
                  >
                    <div className="flex items-start justify-between">
                      <div>
                        <p className="text-[10px] font-mono tracking-wider text-gray-400 uppercase">{track.role}</p>
                        <h3 className="text-sm font-semibold text-white mt-1 flex items-center gap-2">
                          {track.title}
                          {currentTrackIndex === idx && <Music className="w-3.5 h-3.5 text-emerald-400 animate-pulse" />}
                        </h3>
                        <p className="text-xs text-gray-400 mt-2 line-clamp-2">{track.description}</p>
                      </div>
                    </div>
                  </button>
                ))}
              </div>

              {/* Selected Track Deep-Dive Principles */}
              <div className="bg-[#151722] p-4 rounded-xl border border-[#2b3044]/40">
                <h4 className="text-xs font-mono tracking-wider text-emerald-400 mb-2">PROD PRINCIPLES ACTIVE</h4>
                <ul className="space-y-1.5">
                  {currentTrack.principles.map((pr, i) => (
                    <li key={i} className="text-xs flex items-center gap-2 text-gray-300">
                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500 flex-shrink-0" />
                      {pr}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {activeTab === "manifesto" && (
            <div className="space-y-6">
              <div>
                <span className="text-[10px] font-mono tracking-widest text-emerald-400 uppercase bg-emerald-950/40 px-2 py-1 rounded border border-emerald-800/30">
                  The Core Principle
                </span>
                <h2 className="text-xl font-bold text-white mt-3">The Human Rule</h2>
              </div>
              <blockquote className="border-l-2 border-emerald-500/50 pl-4 py-1 italic text-gray-300 text-sm leading-relaxed">
                "Do not ask, 'How impressive is the song?' Ask, 'How close does the listener feel to the human being inside the song?'"
              </blockquote>
              <div className="space-y-3 text-xs text-gray-400 leading-relaxed">
                <p>
                  In a landscape populated with infinite options and technical loops, we define the Elyzareth OS framework around restraint. Overproduction is the default gravity; silence is the earned victory.
                </p>
                <p>
                  The narrator’s transition from a sterile system of measurement to organic connection is mapped directly into the tracks. The music does not play for the listener; it invites the listener to sit beside the witness.
                </p>
              </div>
            </div>
          )}

          {activeTab === "structure" && (
            <div className="space-y-4">
              <div>
                <span className="text-[10px] font-mono tracking-widest text-emerald-400 uppercase bg-emerald-950/40 px-2 py-1 rounded border border-emerald-800/30">
                  The Human Journey EP
                </span>
                <h2 className="text-xl font-bold text-white mt-3">Movement Structure</h2>
              </div>
              <div className="space-y-3">
                <div className="bg-[#151722] p-3 rounded-lg border border-[#2b3044]/40">
                  <h4 className="text-xs font-semibold text-white">Movement 1: The Weight</h4>
                  <p className="text-[11px] text-gray-400 mt-0.5">Isolation, measurement, ledgers, and locked-away columns. A solitary witness.</p>
