            </div>
          )}

          {/* Integrated Mini-Player (Bottom) */}
          <div className="mt-auto pt-6 border-t border-[#2b3044] space-y-4">
            <audio
              ref={audioRef}
              src={currentTrack.url}
              onTimeUpdate={handleTimeUpdate}
              onLoadedMetadata={handleLoadedMetadata}
              crossOrigin="anonymous"
            />

            {/* Progress Slider */}
            <div className="space-y-1">
              <input
                type="range"
                min={0}
                max={duration || 100}
                value={currentTime}
                onChange={handleSeek}
