      {/* 3. Now Playing Badge Card Layer */}
      {isVisible("card") && (
        <div
          onClick={(e) => {
            e.stopPropagation();
            onSelectObject("card");
          }}
          className={`absolute bottom-12 left-12 bg-slate-900/80 backdrop-blur-xl border p-3 rounded-xl flex items-center gap-3 cursor-pointer pointer-events-auto shadow-2xl transition-all ${
            selectedObjectId === "card"
              ? "ring-2 ring-cyan-400 border-cyan-400"
              : "border-slate-800/80 hover:border-slate-700"
          }`}
        >
          <div className="p-2 bg-rose-500/10 text-rose-400 rounded-lg border border-rose-500/20">
            <Radio className="w-5 h-5 animate-pulse" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-mono uppercase tracking-wider text-cyan-400">
                Now Playing
              </span>
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-ping" />
            </div>
            <div className="text-xs font-semibold text-slate-100">
              {currentTrack.title}
            </div>
            <div className="text-[10px] text-slate-400">
              {currentTrack.album}
            </div>
          </div>
        </div>
      )}

      {/* 4. Studio Watermark Logo Layer */}
      {isVisible("logo") && (
        <div
          onClick={(e) => {
            e.stopPropagation();
            onSelectObject("logo");
          }}
          className={`absolute top-8 left-8 flex items-center gap-2 cursor-pointer pointer-events-auto transition-all p-2 rounded-lg ${
            selectedObjectId === "logo"
              ? "ring-2 ring-cyan-400 bg-slate-900/80 border border-cyan-400"
              : "hover:bg-slate-900/40"
          }`}
        >
          <div className="w-7 h-7 bg-gradient-to-tr from-cyan-500 to-rose-500 rounded-lg flex items-center justify-center text-slate-950 font-bold text-xs shadow-md">
            E
          </div>
          <div>
            <div className="text-xs font-bold tracking-wider text-slate-100 uppercase">
              ELYZARETH STUDIO OS
            </div>
            <div className="text-[9px] font-mono text-slate-400">
