  // PLAYLIST CATALOG STATE
  const [playlist, setPlaylist] = useState<PlaylistTrack[]>(INITIAL_DEMO_TRACKS);
  const [activeTrackIndex, setActiveTrackIndex] = useState<number>(0);
  const [playlistSearch, setPlaylistSearch] = useState<string>("");

  // ================================================================================
  // v26.8 VISUALIZER ENGINE CONFIGURATION
