    showPeaks: true,
    locked: false
  });

  // OVERLAY CONFIG
  const [overlays, setOverlays] = useState<OverlayConfig>({
    playlist: {
      displayMode: 'minimal',
      xPct: 5.0,
      yPct: 14.0,
      widthPct: 28.0,
      rowsVisible: 8,
      opacity: 0.75,
      fontSize: 12,
      cornerRadius: 12,
      locked: false
    },
    moodPhase: {
      showInEditor: false,
      includeInRecording: false,
      xPct: 50.0,
      yPct: 11.0,
      fontSize: 10,
      locked: false
    },
    logo: {
      corner: 'top-right',
      widthPct: 5.0,
      opacity: 0.9,
      glow: true
    }
  });

  // Active Canvas Object Drag State
  const [activeDragObject, setActiveDragObject] = useState<'playlist' | 'moodPhase' | 'visualizer' | null>(null);
  const [selectedObject, setSelectedObject] = useState<'playlist' | 'moodPhase' | 'visualizer' | null>('visualizer');

  // Accordion Panels Expansion State (Left Inspector)
  const [expandedPanels, setExpandedPanels] = useState({
    visualizer: true,
    playlist: false,
    overlayProps: false,
    logo: false,
    text: false,
    artwork: false
  });

  const togglePanel = (panel: keyof typeof expandedPanels) => {
    setExpandedPanels(prev => ({ ...prev, [panel]: !prev[panel] }));
  };

  const [customUrlInput, setCustomUrlInput] = useState<string>('');
  const [urlError, setUrlError] = useState<string | null>(null);

  // Background Image State
  const [bgImage, setBgImage] = useState<HTMLImageElement | null>(null);
  const [bgDarkness, setBgDarkness] = useState<number>(0.5);
  const bgFileInputRef = useRef<HTMLInputElement | null>(null);

  // Recording State
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [recordedWebmUrl, setRecordedWebmUrl] = useState<string | null>(null);
  const [recordedMp4Url, setRecordedMp4Url] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  // Web Audio References
  const audioElementRef = useRef<HTMLAudioElement | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const audioDestinationRef = useRef<MediaStreamAudioDestinationNode | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const mediaSourceNodeRef = useRef<MediaElementAudioSourceNode | null>(null);
  const multiFileInputRef = useRef<HTMLInputElement | null>(null);

  // Core Engine References
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const animFrameRef = useRef<number | null>(null);
  const playheadStartRef = useRef<number>(0);
  const timeOffsetRef = useRef<number>(0);
  const lastFrameTimeRef = useRef<number>(0);
  const droppedFramesRef = useRef<number>(0);

  // Real-time telemetry state
  const [metrics, setMetrics] = useState<DiagnosticMetrics>({
    timelineTime: 0,
    audioTime: 0,
    driftMs: 0,
    currentMoodPhase: "Intro",
    fps: 60,
    droppedFrames: 0
  });

  // Sync Duration when audio loads metadata
  const handleAudioLoadedMetadata = () => {
    if (audioElementRef.current && audioElementRef.current.duration) {
      setTrackDuration(audioElementRef.current.duration);
    }
  };

  // Initialize Web Audio pipeline
  const initAudioEngine = () => {
    if (!audioCtxRef.current) {
      const AudioCtxClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      const ctx = new AudioCtxClass();
      const streamDest = ctx.createMediaStreamDestination();
      const masterGain = ctx.createGain();

      masterGain.gain.value = muted ? 0 : 0.9;
      masterGain.connect(ctx.destination);
      masterGain.connect(streamDest);

      audioCtxRef.current = ctx;
      audioDestinationRef.current = streamDest;
      masterGainRef.current = masterGain;

      if (audioElementRef.current && !mediaSourceNodeRef.current) {
        try {
          const source = ctx.createMediaElementSource(audioElementRef.current);
          source.connect(masterGain);
          mediaSourceNodeRef.current = source;
        } catch {
          // Handled
        }
      }
    }

    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const getCalculatedTime = (): number => {
    if (audioElementRef.current && !audioElementRef.current.paused) {
      return audioElementRef.current.currentTime;
    }
    if (playbackState === 'idle') return 0;
    if (playbackState === 'paused') return timeOffsetRef.current;
    if (playbackState === 'playing') {
      const elapsed = (performance.now() - playheadStartRef.current) / 1000;
      return Math.min(trackDuration, timeOffsetRef.current + elapsed);
    }
    return timeOffsetRef.current;
  };

  // Evaluate Mood Phase Interpolation
  const getCurrentMoodParams = (time: number) => {
    let current = DEFAULT_MOOD_MARKERS[0];
    let next = DEFAULT_MOOD_MARKERS[DEFAULT_MOOD_MARKERS.length - 1];

    for (let i = 0; i < DEFAULT_MOOD_MARKERS.length - 1; i++) {
      if (time >= DEFAULT_MOOD_MARKERS[i].time && time < DEFAULT_MOOD_MARKERS[i + 1].time) {
        current = DEFAULT_MOOD_MARKERS[i];
        next = DEFAULT_MOOD_MARKERS[i + 1];
        break;
      }
    }

    const durationSegment = next.time - current.time;
    const progress = durationSegment > 0 ? (time - current.time) / durationSegment : 0;

    const glowIntensity = current.glowIntensity + (next.glowIntensity - current.glowIntensity) * progress;
    const particleSpeed = current.particleSpeed + (next.particleSpeed - current.particleSpeed) * progress;
    const ringExpansion = current.ringExpansion + (next.ringExpansion - current.ringExpansion) * progress;

    return {
      phaseName: current.name,
      glowIntensity,
      particleSpeed,
      ringExpansion
    };
  };

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const renderLoop = (now: number) => {
      const time = getCalculatedTime();
      setCurrentTime(time);

      if (lastFrameTimeRef.current > 0) {
        const delta = now - lastFrameTimeRef.current;
        if (delta > 22) {
          droppedFramesRef.current++;
        }
      }
      lastFrameTimeRef.current = now;

      const audioRefTime = audioElementRef.current ? audioElementRef.current.currentTime : time;
      const drift = Math.abs(time - audioRefTime) * 1000;
      const moodParams = getCurrentMoodParams(time);

      setMetrics({
        timelineTime: time,
        audioTime: audioRefTime,
        driftMs: drift,
        currentMoodPhase: moodParams.phaseName,
        fps: Math.round(1000 / (now - (lastFrameTimeRef.current - 16.6) || 16.6)),
        droppedFrames: droppedFramesRef.current
      });

      drawSignatureCanvasFrame(ctx, canvas.width, canvas.height, time, moodParams);

      if (time >= trackDuration && playbackState === 'playing') {
        handleNextTrack();
      } else if (playbackState === 'playing') {
        animFrameRef.current = requestAnimationFrame(renderLoop);
      }
    };

    if (playbackState === 'playing') {
      animFrameRef.current = requestAnimationFrame(renderLoop);
    } else {
      const time = getCalculatedTime();
      const moodParams = getCurrentMoodParams(time);
      drawSignatureCanvasFrame(ctx, canvas.width, canvas.height, time, moodParams);
    }

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
  }, [
    playbackState, bgImage, bgDarkness, activeTrackIndex, playlist, showHeaderBranding,
    headerTitle, headerSubtitle, displaySongTitle, displayArtist, displayMode, activeTheme,
    logoImage, overlays, visualizer, selectedObject, showSafeArea, isRecording, previewDevice, trackDuration
  ]);

  // ================================================================================
  // ELYZARETH V26.8 COMPOSITION RENDER ENGINE (NEON SPECTRUM BARS & WAVEFORMS)
  // ================================================================================
  const drawSignatureCanvasFrame = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    time: number,
    moodParams: ReturnType<typeof getCurrentMoodParams>
  ) => {
    ctx.fillStyle = '#05050a';
    ctx.fillRect(0, 0, width, height);

    const marginX = width * 0.05;
    const marginY = height * 0.05;

    // 1. Ken Burns Slow Cinematic Zoom
    if (bgImage) {
      ctx.save();
      const kenBurnsScale = 1.05 + Math.sin(time * 0.04) * 0.04;
      const panX = Math.cos(time * 0.025) * 12;
      const panY = Math.sin(time * 0.025) * 8;

      const dw = width * kenBurnsScale;
      const dh = height * kenBurnsScale;
      const dx = (width - dw) / 2 + panX;
      const dy = (height - dh) / 2 + panY;

      ctx.drawImage(bgImage, dx, dy, dw, dh);
      ctx.fillStyle = `rgba(5, 5, 10, ${bgDarkness})`;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();
    } else {
      const bgGrad = ctx.createRadialGradient(width / 2, height / 2, 40, width / 2, height / 2, width * 0.75);
      bgGrad.addColorStop(0, '#130b24');
      bgGrad.addColorStop(0.6, '#090514');
      bgGrad.addColorStop(1, '#020108');
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 0, width, height);
    }

    // 2. Ambient Lighting Pulse
    const glowGrad = ctx.createRadialGradient(width / 2, height / 2, width * 0.25, width / 2, height / 2, width * 0.75);
    glowGrad.addColorStop(0, 'rgba(0,0,0,0)');
    glowGrad.addColorStop(1, activeTheme.glow);
    ctx.fillStyle = glowGrad;
    ctx.fillRect(0, 0, width, height);

    // 3. Floating Sparkles
    const numSparkles = 28;
    for (let i = 0; i < numSparkles; i++) {
      const sx = (Math.sin(i * 99 + time * 0.15 * moodParams.particleSpeed) * 0.5 + 0.5) * width;
      const sy = (Math.cos(i * 33 + time * 0.12 * moodParams.particleSpeed) * 0.5 + 0.5) * height;
      const sparkleAlpha = (Math.sin(time * 3 + i) * 0.5 + 0.5) * moodParams.glowIntensity;

      ctx.fillStyle = activeTheme.secondary;
      ctx.globalAlpha = sparkleAlpha;
      ctx.beginPath();
      ctx.arc(sx, sy, 1.5 + (i % 3), 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1.0;
    }

    // ================================================================================
    // 4. v26.8 MULTI-MODE AUDIO VISUALIZER RENDERER
    // ================================================================================

    // TYPE A: CENTERPIECE DUAL RING CIRCLE
    if (visualizer.type === 'circle') {
      const cx = displayMode === 'album' ? width * 0.58 : width / 2;
      const cy = height / 2;
      const ringRadius = (height * 0.18) + moodParams.ringExpansion + Math.sin(time * 2) * 6;

      ctx.save();
      ctx.translate(cx, cy);

      ctx.strokeStyle = activeTheme.primary;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, ringRadius, 0, Math.PI * 2);
      ctx.stroke();

      ctx.rotate(time * 0.2 * moodParams.particleSpeed);
      const nodes = 12;
      for (let i = 0; i < nodes; i++) {
        const angle = (i / nodes) * Math.PI * 2;
        const waveOffset = Math.sin(time * 4 + i) * 12;
        const nx = Math.cos(angle) * (ringRadius + 20 + waveOffset);
        const ny = Math.sin(angle) * (ringRadius + 20 + waveOffset);

        ctx.fillStyle = activeTheme.secondary;
        ctx.beginPath();
        ctx.arc(nx, ny, 3.5, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    // TYPE B: SPECTRUM BARS (VIBRANT NEON AUDIO FREQUENCY BAR GRAPH)
    else if (visualizer.type === 'bars') {
      ctx.save();
      const vizWidth = (width * visualizer.widthPct) / 100;
      const vizMaxHeight = (height * visualizer.heightPct) / 100;
      const vizX = (width * visualizer.xPct) / 100 - (vizWidth / 2);
      const vizY = (height * visualizer.yPct) / 100;

      const bars = visualizer.barCount;
      const gap = 3;
      const barWidth = Math.max(2, (vizWidth - (bars * gap)) / bars);

      // Gradient Palette Setup
      const neonGrad = ctx.createLinearGradient(vizX, vizY - vizMaxHeight, vizX + vizWidth, vizY);
      neonGrad.addColorStop(0.0, '#38bdf8'); // Cyan
      neonGrad.addColorStop(0.25, '#8b5cf6'); // Purple
      neonGrad.addColorStop(0.5, '#ec4899'); // Pink
      neonGrad.addColorStop(0.75, '#f97316'); // Orange
      neonGrad.addColorStop(1.0, '#eab308'); // Yellow

      for (let i = 0; i < bars; i++) {
        const x = vizX + i * (barWidth + gap);

        // Dynamic Frequency Wave Audio Simulation
        const centerDist = Math.abs(i - bars / 2) / (bars / 2);
        const freqWeight = Math.sin((i / bars) * Math.PI);
        const wave1 = Math.sin(time * 4 * visualizer.sensitivity + i * 0.15);
        const wave2 = Math.cos(time * 7 * visualizer.sensitivity - i * 0.22);
        const noise = (Math.sin(i * 33 + time * 10) * 0.5 + 0.5) * 0.3;

        let barVal = (Math.abs(wave1 * 0.6 + wave2 * 0.4) * freqWeight + noise) * visualizer.sensitivity;
        barVal = Math.min(1.0, Math.max(0.08, barVal));

        const barHeight = barVal * vizMaxHeight;

        // Draw Spectrum Bar
        ctx.fillStyle = visualizer.style === 'neon' ? neonGrad : activeTheme.primary;
        ctx.shadowColor = activeTheme.glow;
        ctx.shadowBlur = 8;

        if (typeof (ctx as any).roundRect === 'function') {
          ctx.beginPath();
          (ctx as any).roundRect(x, vizY - barHeight, barWidth, barHeight, [3, 3, 0, 0]);
          ctx.fill();
        } else {
          ctx.fillRect(x, vizY - barHeight, barWidth, barHeight);
        }

        // Draw Peak Dots
        if (visualizer.showPeaks) {
          const peakY = vizY - barHeight - 4;
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(x, peakY, barWidth, 2);
        }

        // Subtle Reflection Below Baseline
        ctx.fillStyle = visualizer.style === 'neon' ? 'rgba(236, 72, 153, 0.2)' : 'rgba(139, 92, 246, 0.2)';
        ctx.fillRect(x, vizY + 2, barWidth, barHeight * 0.25);
      }

      // Selection Frame in Studio Mode
      const isViewerExportRender = isRecording || canvasViewMode === 'viewer';
      if (selectedObject === 'visualizer' && !isViewerExportRender) {
        ctx.strokeStyle = '#ec4899';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(vizX - 6, vizY - vizMaxHeight - 12, vizWidth + 12, vizMaxHeight + 20);
      }

      ctx.restore();
    }

    // TYPE C: OSCILLOSCOPE WAVEFORM / LINE WAVE
    else if (visualizer.type === 'waveform' || visualizer.type === 'lineWave') {
      ctx.save();
      const vizWidth = (width * visualizer.widthPct) / 100;
      const vizMaxHeight = (height * visualizer.heightPct) / 100;
      const vizX = (width * visualizer.xPct) / 100 - (vizWidth / 2);
      const vizY = (height * visualizer.yPct) / 100;

      ctx.strokeStyle = activeTheme.secondary;
      ctx.lineWidth = 3;
      ctx.shadowColor = activeTheme.primary;
      ctx.shadowBlur = 12;

      ctx.beginPath();
      const points = 120;
      for (let i = 0; i <= points; i++) {
        const px = vizX + (i / points) * vizWidth;
        const wave = Math.sin(time * 5 + i * 0.15) * Math.cos(time * 3 + i * 0.1);
        const py = vizY + wave * (vizMaxHeight / 2) * visualizer.sensitivity;

        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();

      const isViewerExportRender = isRecording || canvasViewMode === 'viewer';
      if (selectedObject === 'visualizer' && !isViewerExportRender) {
        ctx.strokeStyle = '#ec4899';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(vizX - 6, vizY - vizMaxHeight / 2 - 10, vizWidth + 12, vizMaxHeight + 20);
      }

      ctx.restore();
    }

    // 5. TOP-LEFT HEADER BRANDING
    if (showHeaderBranding && (headerTitle.trim() !== '' || headerSubtitle.trim() !== '')) {
      if (headerTitle.trim() !== '') {
        ctx.fillStyle = '#ffffff';
        ctx.font = '700 13px "SF Pro Display", sans-serif';
        ctx.textAlign = 'left';
        ctx.fillText(headerTitle.toUpperCase(), marginX, marginY + 12);
      }

      if (headerSubtitle.trim() !== '') {
        ctx.fillStyle = activeTheme.secondary;
        ctx.font = '500 11px font-mono, monospace';
        ctx.fillText(headerSubtitle.toUpperCase(), marginX, marginY + 28);
      }
    }

    // 6. MOOD PHASE OVERLAY
    const isViewerExportRender = isRecording || canvasViewMode === 'viewer';
    const renderMoodPhase = isViewerExportRender
      ? overlays.moodPhase.includeInRecording
      : overlays.moodPhase.showInEditor;

    if (renderMoodPhase) {
      const moodX = (width * overlays.moodPhase.xPct) / 100;
      const moodY = (height * overlays.moodPhase.yPct) / 100;

      ctx.save();
      ctx.fillStyle = activeTheme.secondary;
      ctx.font = `600 ${overlays.moodPhase.fontSize}px font-mono, monospace`;
      ctx.textAlign = 'center';
      ctx.fillText(`MOOD PHASE: [ ${moodParams.phaseName.toUpperCase()} ]`, moodX, moodY);

      if (selectedObject === 'moodPhase' && !isViewerExportRender) {
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        ctx.strokeRect(moodX - 80, moodY - 12, 160, 18);
      }
      ctx.restore();
    }

    // 7. BRAND LOGO EMBLEM OVERLAY
    if (logoImage) {
      ctx.save();
      const responsiveLogoWidth = (width * (overlays.logo.widthPct / 100));
      const aspect = logoImage.height / logoImage.width || 1;
      const responsiveLogoHeight = responsiveLogoWidth * aspect;

      let lx = width - responsiveLogoWidth - marginX;
      let ly = marginY;

      if (overlays.logo.corner === 'top-left') {
        lx = marginX;
        ly = showHeaderBranding ? marginY + 40 : marginY;
      } else if (overlays.logo.corner === 'bottom-right') {
        lx = width - responsiveLogoWidth - marginX;
        ly = height - responsiveLogoHeight - marginY;
      } else if (overlays.logo.corner === 'bottom-left') {
        lx = marginX;
        ly = height - responsiveLogoHeight - marginY;
      }

      ctx.globalAlpha = overlays.logo.opacity;

      if (overlays.logo.glow) {
        const shimmerPulse = Math.sin(time * 2) * 0.3 + 0.7;
        ctx.shadowColor = activeTheme.primary;
        ctx.shadowBlur = 12 * shimmerPulse;
      }

      ctx.drawImage(logoImage, lx, ly, responsiveLogoWidth, responsiveLogoHeight);
      ctx.restore();
    }

    // ================================================================================
    // 8. v26.6 PLAYLIST OVERLAY DISPLAY MODES (OFF / MINIMAL GLASS CARD / FULL ALBUM)
    // ================================================================================
    if (displayMode === 'album' && playlist.length > 0) {
      const plMode = overlays.playlist.displayMode;

      if (plMode === 'minimal') {
        ctx.save();
        const plX = (width * overlays.playlist.xPct) / 100;
        const plY = (height * overlays.playlist.yPct) / 100;
        const plWidth = (width * overlays.playlist.widthPct) / 100;
        const cardHeight = 72;

        const currentTrack = playlist[activeTrackIndex] || playlist[0];

        ctx.fillStyle = `rgba(8, 8, 18, ${overlays.playlist.opacity})`;
        ctx.strokeStyle = activeTheme.glow;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        if (typeof (ctx as any).roundRect === 'function') {
          (ctx as any).roundRect(plX, plY, plWidth, cardHeight, overlays.playlist.cornerRadius);
        } else {
          ctx.rect(plX, plY, plWidth, cardHeight);
        }
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = activeTheme.secondary;
        ctx.font = '600 10px font-mono, monospace';
        ctx.textAlign = 'left';
        ctx.fillText('♪ NOW PLAYING', plX + 14, plY + 22);

        ctx.fillStyle = '#ffffff';
        ctx.font = '700 13px "SF Pro Display", sans-serif';
        ctx.fillText(currentTrack.title.toUpperCase(), plX + 14, plY + 42);

        ctx.fillStyle = '#94a3b8';
        ctx.font = '500 11px "SF Pro Display", sans-serif';
        ctx.fillText(currentTrack.artist, plX + 14, plY + 58);

        if (selectedObject === 'playlist' && !isViewerExportRender) {
          ctx.strokeStyle = '#8b5cf6';
          ctx.lineWidth = 1;
          ctx.setLineDash([3, 3]);
          ctx.strokeRect(plX - 1, plY - 1, plWidth + 2, cardHeight + 2);
        }

        ctx.restore();
      }

      else if (plMode === 'full') {
        ctx.save();
        const plX = (width * overlays.playlist.xPct) / 100;
        const plY = (height * overlays.playlist.yPct) / 100;
        const plWidth = (width * overlays.playlist.widthPct) / 100;

        const lineHeight = overlays.playlist.fontSize + 9;
        const visibleRows = overlays.playlist.rowsVisible;

        const scrollOffset = Math.max(0, Math.min(activeTrackIndex - 3, playlist.length - visibleRows));
        const displayedTracks = playlist.slice(scrollOffset, scrollOffset + visibleRows);

        const panelHeight = visibleRows * lineHeight + 20;

        ctx.fillStyle = `rgba(5, 5, 12, ${overlays.playlist.opacity})`;
        ctx.strokeStyle = activeTheme.glow;
        ctx.lineWidth = 1;
        ctx.beginPath();
        if (typeof (ctx as any).roundRect === 'function') {
          (ctx as any).roundRect(plX, plY, plWidth, panelHeight, overlays.playlist.cornerRadius);
        } else {
          ctx.rect(plX, plY, plWidth, panelHeight);
        }
        ctx.fill();
        ctx.stroke();

        ctx.font = `500 ${overlays.playlist.fontSize}px font-mono, monospace`;
        ctx.textAlign = 'left';

        for (let i = 0; i < displayedTracks.length; i++) {
          const actualIndex = scrollOffset + i;
          const itemY = plY + 16 + (i * lineHeight);
          const isCurrent = actualIndex === activeTrackIndex;
          const isPast = actualIndex < activeTrackIndex;

          const trackTitleFormatted = `${(actualIndex + 1).toString().padStart(2, '0')}. ${displayedTracks[i].title}`;

          if (isCurrent) {
            ctx.fillStyle = activeTheme.glow;
            ctx.fillRect(plX + 4, itemY - overlays.playlist.fontSize, plWidth - 8, lineHeight - 2);

            ctx.fillStyle = activeTheme.secondary;
            ctx.fillText(`▶ ${trackTitleFormatted}`, plX + 8, itemY);
          } else if (isPast) {
            ctx.fillStyle = 'rgba(148, 163, 184, 0.4)';
            ctx.fillText(`✓ ${trackTitleFormatted}`, plX + 8, itemY);
          } else {
            ctx.fillStyle = 'rgba(226, 232, 240, 0.7)';
            ctx.fillText(`  ${trackTitleFormatted}`, plX + 8, itemY);
          }
        }

        if (selectedObject === 'playlist' && !isViewerExportRender) {
          ctx.strokeStyle = '#8b5cf6';
          ctx.lineWidth = 1;
          ctx.setLineDash([3, 3]);
          ctx.strokeRect(plX - 1, plY - 1, plWidth + 2, panelHeight + 2);
        }

        ctx.restore();
      }
    }

    // 9. YOUTUBE SAFE AREA GUIDES (STUDIO HELPER)
    if (showSafeArea && !isViewerExportRender) {
      ctx.save();
      ctx.setLineDash([6, 6]);
      ctx.lineWidth = 1.5;

      ctx.strokeStyle = '#10b981';
      ctx.strokeRect(marginX, marginY, width - (marginX * 2), height - (marginY * 2));

      if (previewDevice === 'mobile') {
        const mobWidth = width * 0.7;
        ctx.strokeStyle = '#3b82f6';
        ctx.strokeRect((width - mobWidth) / 2, marginY, mobWidth, height - (marginY * 2));
      }

      ctx.restore();
    }
  };

  // ================================================================================
  // DIRECT CANVAS MOUSE DRAG & OBJECT SELECTION HANDLERS
  // ================================================================================
  const handleCanvasMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (canvasViewMode === 'viewer' || isRecording) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const clickX = ((e.clientX - rect.left) / rect.width) * 100;
    const clickY = ((e.clientY - rect.top) / rect.height) * 100;

    // Check hit on Visualizer (Spectrum Bars / Waveform)
    if (visualizer.type !== 'circle') {
      const vizX = visualizer.xPct;
      const vizY = visualizer.yPct;
      const vizW = visualizer.widthPct;
      const vizH = visualizer.heightPct;

      if (Math.abs(clickX - vizX) < vizW / 2 && Math.abs(clickY - vizY) < vizH) {
        if (!visualizer.locked) {
          setActiveDragObject('visualizer');
          setSelectedObject('visualizer');
        }
        return;
      }
    }

    // Check hit on Mood Phase
    if (overlays.moodPhase.showInEditor) {
      const moodX = overlays.moodPhase.xPct;
      const moodY = overlays.moodPhase.yPct;
      if (Math.abs(clickX - moodX) < 15 && Math.abs(clickY - moodY) < 5) {
        if (!overlays.moodPhase.locked) {
          setActiveDragObject('moodPhase');
          setSelectedObject('moodPhase');
        }
        return;
      }
    }

    // Check hit on Playlist Overlay
    if (overlays.playlist.displayMode !== 'off') {
      const plX = overlays.playlist.xPct;
      const plY = overlays.playlist.yPct;
      const plW = overlays.playlist.widthPct;
      const plH = overlays.playlist.displayMode === 'minimal' ? 15 : 35;

      if (clickX >= plX && clickX <= plX + plW && clickY >= plY && clickY <= plY + plH) {
        if (!overlays.playlist.locked) {
          setActiveDragObject('playlist');
          setSelectedObject('playlist');
        }
        return;
      }
    }

    setSelectedObject(null);
  };

  const handleCanvasMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!activeDragObject || isRecording) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseXPct = Math.max(2, Math.min(98, ((e.clientX - rect.left) / rect.width) * 100));
    const mouseYPct = Math.max(2, Math.min(98, ((e.clientY - rect.top) / rect.height) * 100));

    if (activeDragObject === 'visualizer') {
      setVisualizer(prev => ({
        ...prev,
        xPct: Math.round(mouseXPct),
        yPct: Math.round(mouseYPct)
      }));
    } else if (activeDragObject === 'playlist') {
      setOverlays(prev => ({
        ...prev,
        playlist: {
          ...prev.playlist,
          xPct: Math.round(mouseXPct),
          yPct: Math.round(mouseYPct)
        }
      }));
    } else if (activeDragObject === 'moodPhase') {
      setOverlays(prev => ({
        ...prev,
        moodPhase: {
          ...prev.moodPhase,
          xPct: Math.round(mouseXPct),
          yPct: Math.round(mouseYPct)
        }
      }));
    }
  };

  const handleCanvasMouseUp = () => {
    setActiveDragObject(null);
  };

  // MULTI-FILE UPLOAD & PLAYLIST MANAGER FUNCTIONS
  const handleMultiFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUrlError(null);
    const newTracks: PlaylistTrack[] = [];

    Array.from(files).forEach((file, idx) => {
      const cleanTitle = file.name
        .replace(/\.[^/.]+$/, "")
        .replace(/[-_]/g, " ")
        .trim();

      const blobUrl = URL.createObjectURL(file);

      newTracks.push({
        id: `upload-${Date.now()}-${idx}-${Math.random().toString(36).substring(2, 6)}`,
        title: cleanTitle,
        artist: "Uploaded Track",
        url: blobUrl,
        file
      });
    });

    setPlaylist((prev) => [...prev, ...newTracks]);

    if (playlist.length === 0 && newTracks.length > 0) {
      playTrackAtIndex(0, newTracks[0]);
    }
  };

  const playTrackAtIndex = (index: number, trackOverride?: PlaylistTrack) => {
    const track = trackOverride || playlist[index];
    if (!track) return;

    setActiveTrackIndex(index);
    setDisplaySongTitle(track.title);
    setDisplayArtist(track.artist);
    setUrlError(null);

    timeOffsetRef.current = 0;
    setCurrentTime(0);

    initAudioEngine();

    if (audioElementRef.current) {
      audioElementRef.current.src = track.url;
      audioElementRef.current.load();
      audioElementRef.current.play().then(() => {
        setPlaybackState('playing');
        playheadStartRef.current = performance.now();
      }).catch(() => {
        setPlaybackState('paused');
      });
    }
  };

  const handleNextTrack = () => {
    if (playlist.length === 0) return;
    const nextIndex = (activeTrackIndex + 1) % playlist.length;
    playTrackAtIndex(nextIndex);
  };

  const handlePrevTrack = () => {
    if (playlist.length === 0) return;
    const prevIndex = (activeTrackIndex - 1 + playlist.length) % playlist.length;
    playTrackAtIndex(prevIndex);
  };

  const handleRemoveTrack = (indexToRemove: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (playlist.length <= 1) {
      setUrlError("Playlist must contain at least 1 track.");
      return;
    }

    const updated = playlist.filter((_, idx) => idx !== indexToRemove);
    setPlaylist(updated);

    if (indexToRemove === activeTrackIndex) {
      const nextIdx = Math.min(activeTrackIndex, updated.length - 1);
      playTrackAtIndex(nextIdx, updated[nextIdx]);
    } else if (indexToRemove < activeTrackIndex) {
      setActiveTrackIndex(activeTrackIndex - 1);
    }
  };

  const handleMoveTrack = (index: number, direction: 'up' | 'down', e: React.MouseEvent) => {
    e.stopPropagation();
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= playlist.length) return;

    const updated = [...playlist];
    const [moved] = updated.splice(index, 1);
    updated.splice(targetIndex, 0, moved);

    setPlaylist(updated);

    if (activeTrackIndex === index) {
      setActiveTrackIndex(targetIndex);
    } else if (activeTrackIndex === targetIndex) {
      setActiveTrackIndex(index);
    }
  };

  const handleLoadCustomUrl = () => {
    setUrlError(null);
    if (!customUrlInput.trim()) return;
    let url = customUrlInput.trim();

    if (url.includes('youtube.com') || url.includes('youtu.be')) {
      setUrlError("YouTube links are protected by CORS. Please upload local audio files or paste a Flow Music link.");
      return;
    }

    const match = url.match(/song\/([a-f0-9-]+)/i);
    if (match && match[1]) {
      url = `https://storage.googleapis.com/producer-app-public/clips/${match[1]}.m4a`;
    }

    const customTrack: PlaylistTrack = {
      id: `custom-${Date.now()}`,
      title: "Loaded External Track",
      artist: "External Stream",
      url
    };

    setPlaylist((prev) => [...prev, customTrack]);
    playTrackAtIndex(playlist.length, customTrack);
    setCustomUrlInput('');
  };

  // Recording
  const startCanvasRecording = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    initAudioEngine();
    setRecordedWebmUrl(null);
    setRecordedMp4Url(null);

    const canvasStream = canvas.captureStream(60);
    const combinedStream = new MediaStream();
    canvasStream.getVideoTracks().forEach(track => combinedStream.addTrack(track));

    if (audioDestinationRef.current && audioDestinationRef.current.stream) {
      const audioTracks = audioDestinationRef.current.stream.getAudioTracks();
      if (audioTracks.length > 0) {
        combinedStream.addTrack(audioTracks[0]);
      }
    }

    let mimeType = 'video/webm;codecs=vp9,opus';
    if (!MediaRecorder.isTypeSupported(mimeType)) {
      mimeType = 'video/webm';
    }

    const recorder = new MediaRecorder(combinedStream, {
      mimeType,
      videoBitsPerSecond: 20_000_000,
      audioBitsPerSecond: 320_000
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        chunks.push(e.data);
      }
    };

    recorder.onstop = () => {
      const webmBlob = new Blob(chunks, { type: 'video/webm' });
      setRecordedWebmUrl(URL.createObjectURL(webmBlob));

      const mp4Blob = new Blob(chunks, { type: 'video/mp4' });
      setRecordedMp4Url(URL.createObjectURL(mp4Blob));

      setIsRecording(false);
    };

    mediaRecorderRef.current = recorder;
    recorder.start(100);
    setIsRecording(true);

    handlePlay();
  };

  const stopCanvasRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    handlePause();
  };

  const handlePlay = () => {
    initAudioEngine();
    playheadStartRef.current = performance.now();
    setPlaybackState('playing');

    if (audioElementRef.current) {
      audioElementRef.current.currentTime = getCalculatedTime();
      audioElementRef.current.play().catch(() => {});
    }
  };

  const handlePause = () => {
    timeOffsetRef.current = getCalculatedTime();
    setPlaybackState('paused');
    if (audioElementRef.current) {
      audioElementRef.current.pause();
    }
  };

  const handleStop = () => {
    timeOffsetRef.current = 0;
    setPlaybackState('idle');
    setCurrentTime(0);
    if (audioElementRef.current) {
      audioElementRef.current.pause();
      audioElementRef.current.currentTime = 0;
    }
    if (isRecording) {
      stopCanvasRecording();
    }
  };

  const handleSeek = (newTime: number) => {
    timeOffsetRef.current = Math.max(0, Math.min(newTime, trackDuration));
    playheadStartRef.current = performance.now();
    setCurrentTime(timeOffsetRef.current);
    if (audioElementRef.current) {
      audioElementRef.current.currentTime = newTime;
    }
  };

  const toggleMute = () => {
    setMuted(!muted);
    if (masterGainRef.current) {
      masterGainRef.current.gain.value = !muted ? 0 : 0.9;
    }
  };

  const handleBgImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const imgUrl = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      setBgImage(img);
    };
    img.src = imgUrl;
  };

  const handleLogoFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const imgUrl = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      setLogoImage(img);
    };
    img.src = imgUrl;
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const filteredPlaylist = playlist.filter((track) =>
    track.title.toLowerCase().includes(playlistSearch.toLowerCase()) ||
    track.artist.toLowerCase().includes(playlistSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-4 sm:p-6 font-sans relative overflow-x-hidden">
      <audio
        ref={audioElementRef}
        src={playlist[activeTrackIndex]?.url || ''}
        crossOrigin="anonymous"
        preload="auto"
        onLoadedMetadata={handleAudioLoadedMetadata}
      />

      <input
        type="file"
        ref={multiFileInputRef}
        onChange={handleMultiFileUpload}
        accept="audio/*"
        multiple
        className="hidden"
      />

      <input
        type="file"
        ref={bgFileInputRef}
        onChange={handleBgImageUpload}
        accept="image/*"
        className="hidden"
      />

      <input
        type="file"
        ref={logoFileInputRef}
        onChange={handleLogoFileUpload}
        accept="image/*"
        className="hidden"
      />

      <div className="w-full max-w-7xl space-y-4">

        {/* HEADER BAR */}
        <div className="flex items-center justify-between border-b border-slate-800 pb-3">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-purple-600/20 text-purple-400 rounded-lg border border-purple-500/30">
              <Sparkles className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white flex items-center gap-2">
                ELYZARETH OS <span className="text-xs px-2.5 py-0.5 rounded bg-purple-500/20 text-purple-300 border border-purple-500/30 font-mono">v26.8 VISUALIZER ENGINE</span>
              </h1>
              <p className="text-xs text-slate-400">Multi-Mode Audio Visualizer: Spectrum Bars, Waveform Line & Circle Particle Ring</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="flex items-center bg-slate-900 border border-slate-800 rounded-lg p-1 text-xs">
              <button
                onClick={() => setDisplayMode('album')}
                className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                  displayMode === 'album' ? 'bg-purple-600 text-white font-bold' : 'text-slate-400 hover:text-slate-200'
                }`}
              >
                <Disc className="w-3.5 h-3.5" /> Album Mode
              </button>
              <button
                onClick={() => setDisplayMode('single')}
                className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                  displayMode === 'single' ? 'bg-purple-600 text-white font-bold' : 'text-slate-400 hover:text-slate-200'
                }`}
              >
                <Layers className="w-3.5 h-3.5" /> Single Mode
              </button>
            </div>

            <button
              onClick={toggleMute}
              className="p-2 bg-slate-900 border border-slate-800 rounded-lg text-slate-400 hover:text-white transition"
              title={muted ? "Unmute Audio" : "Mute Audio"}
            >
              {muted ? <VolumeX className="w-4 h-4 text-red-400" /> : <Volume2 className="w-4 h-4 text-emerald-400" />}
            </button>

            <button
              onClick={() => setShowTelemetry(!showTelemetry)}
              className={`px-3 py-1.5 rounded-lg text-xs font-medium flex items-center gap-1.5 transition ${
                showTelemetry ? 'bg-purple-600/30 text-purple-300 border border-purple-500/50' : 'bg-slate-900 text-slate-400 border border-slate-800'
              }`}
            >
              <Activity className="w-3.5 h-3.5" /> Telemetry
            </button>
          </div>
        </div>

        {/* ================================================================================ */}
        {/* v26.8 DUAL-PANE SIDE-BY-SIDE STUDIO LAYOUT */}
        {/* ================================================================================ */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">

          {/* ================================================================================ */}
          {/* LEFT COLUMN: INSPECTOR & CONTROL SURFACE (4 COLS) */}
          {/* ================================================================================ */}
          {canvasViewMode === 'studio' && (
            <div className="lg:col-span-4 space-y-3 max-h-[82vh] overflow-y-auto pr-1 custom-scrollbar">

              {/* GLOBAL COLOR THEME SELECTOR */}
              <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-3.5 space-y-2">
                <span className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-1.5">
                  <Palette className="w-4 h-4" /> GLOBAL COLOR THEME
                </span>
                <div className="grid grid-cols-2 gap-1.5 text-xs font-medium">
