  // DISPLAY MODE & HEADER OVERLAY TOGGLE
  const [displayMode, setDisplayMode] = useState<DisplayMode>('single');
  const [showHeaderBranding, setShowHeaderBranding] = useState<boolean>(false);

  // GLOBAL COLOR THEME SELECTION
  const [activeTheme, setActiveTheme] = useState<ColorTheme>(COLOR_THEMES[0]);

  // LOGO EMBLEM CONTROLS (PERCENTAGE RESPONSIVE SCALING)
  const [logoImage, setLogoImage] = useState<HTMLImageElement | null>(null);
  const [logoCorner, setLogoCorner] = useState<LogoCorner>('top-right');
  const [logoPercentWidth, setLogoPercentWidth] = useState<number>(5.0); // % of video width
  const [logoOpacity, setLogoOpacity] = useState<number>(0.9);
  const [logoGlow, setLogoGlow] = useState<boolean>(true);
  const logoFileInputRef = useRef<HTMLInputElement | null>(null);

  // EDITABLE BRANDING & METADATA OVERLAYS
  const [headerTitle, setHeaderTitle] = useState<string>("");
  const [headerSubtitle, setHeaderSubtitle] = useState<string>("");
  const [displaySongTitle, setDisplaySongTitle] = useState<string>("AAJ KI RAAT-FINAL");
  const [displayArtist, setDisplayArtist] = useState<string>("Elyzareth Studio");

  // TRACKLIST OVERLAY STATE (8-10 VISIBLE SCROLLING WINDOW)
  const [tracklist, setTracklist] = useState<string[]>(INITIAL_20_TRACKLIST);
  const [activeTrackIndex, setActiveTrackIndex] = useState<number>(0);

  // Active track selection
  const [selectedTrack, setSelectedTrack] = useState(DEMO_TRACKS[0]);
  const [customUrlInput, setCustomUrlInput] = useState<string>('');
  const [urlError, setUrlError] = useState<string | null>(null);

  // Background Image & Visual Style State
  const [bgImage, setBgImage] = useState<HTMLImageElement | null>(null);
  const [bgDarkness, setBgDarkness] = useState<number>(0.5);
  const bgFileInputRef = useRef<HTMLInputElement | null>(null);

  // Recording State
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [recordedWebmUrl, setRecordedWebmUrl] = useState<string | null>(null);
  const [recordedMp4Url, setRecordedMp4Url] = useState<string | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  // Web Audio References
  const audioElementRef = useRef<HTMLAudioElement | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const audioDestinationRef = useRef<MediaStreamAudioDestinationNode | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);
  const mediaSourceNodeRef = useRef<MediaElementAudioSourceNode | null>(null);
  const audioFileInputRef = useRef<HTMLInputElement | null>(null);

  // Core Engine References
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const animFrameRef = useRef<number | null>(null);
  const playheadStartRef = useRef<number>(0);
  const timeOffsetRef = useRef<number>(0);
  const lastFrameTimeRef = useRef<number>(0);
  const droppedFramesRef = useRef<number>(0);

  // Real-time telemetry state
  const [metrics, setMetrics] = useState<DiagnosticMetrics>({
    timelineTime: 0,
    audioTime: 0,
    driftMs: 0,
    currentMoodPhase: "Intro",
    fps: 60,
    droppedFrames: 0
  });

  // Initialize Web Audio pipeline
  const initAudioEngine = () => {
    if (!audioCtxRef.current) {
      const AudioCtxClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      const ctx = new AudioCtxClass();
      const streamDest = ctx.createMediaStreamDestination();
      const masterGain = ctx.createGain();

      masterGain.gain.value = muted ? 0 : 0.9;
      masterGain.connect(ctx.destination);
      masterGain.connect(streamDest);

      audioCtxRef.current = ctx;
      audioDestinationRef.current = streamDest;
      masterGainRef.current = masterGain;

      if (audioElementRef.current && !mediaSourceNodeRef.current) {
        try {
          const source = ctx.createMediaElementSource(audioElementRef.current);
          source.connect(masterGain);
          mediaSourceNodeRef.current = source;
        } catch {
          // Handled if connected
        }
      }
    }

    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const getCalculatedTime = (): number => {
    if (audioElementRef.current && !audioElementRef.current.paused) {
      return audioElementRef.current.currentTime;
    }
    if (playbackState === 'idle') return 0;
    if (playbackState === 'paused') return timeOffsetRef.current;
    if (playbackState === 'playing') {
      const elapsed = (performance.now() - playheadStartRef.current) / 1000;
      return Math.min(duration, timeOffsetRef.current + elapsed);
    }
    return timeOffsetRef.current;
  };

  // Evaluate Mood Phase Interpolation
  const getCurrentMoodParams = (time: number) => {
    let current = DEFAULT_MOOD_MARKERS[0];
    let next = DEFAULT_MOOD_MARKERS[DEFAULT_MOOD_MARKERS.length - 1];

    for (let i = 0; i < DEFAULT_MOOD_MARKERS.length - 1; i++) {
      if (time >= DEFAULT_MOOD_MARKERS[i].time && time < DEFAULT_MOOD_MARKERS[i + 1].time) {
        current = DEFAULT_MOOD_MARKERS[i];
        next = DEFAULT_MOOD_MARKERS[i + 1];
        break;
      }
    }

    const durationSegment = next.time - current.time;
    const progress = durationSegment > 0 ? (time - current.time) / durationSegment : 0;

    const glowIntensity = current.glowIntensity + (next.glowIntensity - current.glowIntensity) * progress;
    const particleSpeed = current.particleSpeed + (next.particleSpeed - current.particleSpeed) * progress;
    const ringExpansion = current.ringExpansion + (next.ringExpansion - current.ringExpansion) * progress;

    return {
      phaseName: current.name,
      glowIntensity,
      particleSpeed,
      ringExpansion
    };
  };

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const renderLoop = (now: number) => {
      const time = getCalculatedTime();
      setCurrentTime(time);

      if (lastFrameTimeRef.current > 0) {
        const delta = now - lastFrameTimeRef.current;
        if (delta > 22) {
          droppedFramesRef.current++;
        }
      }
      lastFrameTimeRef.current = now;

      const audioRefTime = audioElementRef.current ? audioElementRef.current.currentTime : time;
      const drift = Math.abs(time - audioRefTime) * 1000;
      const moodParams = getCurrentMoodParams(time);

      setMetrics({
        timelineTime: time,
        audioTime: audioRefTime,
        driftMs: drift,
        currentMoodPhase: moodParams.phaseName,
        fps: Math.round(1000 / (now - (lastFrameTimeRef.current - 16.6) || 16.6)),
        droppedFrames: droppedFramesRef.current
      });

      drawSignatureCanvasFrame(ctx, canvas.width, canvas.height, time, moodParams);

      if (time >= duration && playbackState === 'playing') {
        handleStop();
      } else if (playbackState === 'playing') {
        animFrameRef.current = requestAnimationFrame(renderLoop);
      }
    };

    if (playbackState === 'playing') {
      animFrameRef.current = requestAnimationFrame(renderLoop);
    } else {
      const time = getCalculatedTime();
      const moodParams = getCurrentMoodParams(time);
      drawSignatureCanvasFrame(ctx, canvas.width, canvas.height, time, moodParams);
    }

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
    };
  }, [playbackState, bgImage, bgDarkness, selectedTrack, showHeaderBranding, headerTitle, headerSubtitle, displaySongTitle, displayArtist, displayMode, tracklist, activeTrackIndex, activeTheme, logoImage, logoCorner, logoPercentWidth, logoOpacity, logoGlow, showSafeArea, isRecording, previewDevice]);

  // ================================================================================
  // ELYZARETH V26.0 SIGNATURE RENDER ENGINE (PERCENTAGE RESPONSIVE SCALING & SAFE AREA)
  // ================================================================================
  const drawSignatureCanvasFrame = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    time: number,
    moodParams: ReturnType<typeof getCurrentMoodParams>
  ) => {
    ctx.fillStyle = '#05050a';
    ctx.fillRect(0, 0, width, height);

    // Responsive Percentage Margins (5% margin from edges)
    const marginX = width * 0.05;
    const marginY = height * 0.05;

    // 1. Ken Burns Slow Cinematic Zoom & Pan
    if (bgImage) {
      ctx.save();
      const kenBurnsScale = 1.05 + Math.sin(time * 0.04) * 0.04;
      const panX = Math.cos(time * 0.025) * 12;
      const panY = Math.sin(time * 0.025) * 8;

      const dw = width * kenBurnsScale;
      const dh = height * kenBurnsScale;
      const dx = (width - dw) / 2 + panX;
      const dy = (height - dh) / 2 + panY;

      ctx.drawImage(bgImage, dx, dy, dw, dh);

      ctx.fillStyle = `rgba(5, 5, 10, ${bgDarkness})`;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();
    } else {
      const bgGrad = ctx.createRadialGradient(width / 2, height / 2, 40, width / 2, height / 2, width * 0.75);
      bgGrad.addColorStop(0, '#130b24');
      bgGrad.addColorStop(0.6, '#090514');
      bgGrad.addColorStop(1, '#020108');
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 0, width, height);
    }

    // 2. Ambient Lighting Pulse
    const bassPulse = Math.abs(Math.sin(time * 3.1415)) * moodParams.glowIntensity;
    const glowGrad = ctx.createRadialGradient(width / 2, height / 2, width * 0.25, width / 2, height / 2, width * 0.75);
    glowGrad.addColorStop(0, 'rgba(0,0,0,0)');
    glowGrad.addColorStop(1, activeTheme.glow);
    ctx.fillStyle = glowGrad;
    ctx.fillRect(0, 0, width, height);

    // 3. Floating Sparkles
    const numSparkles = 28;
    for (let i = 0; i < numSparkles; i++) {
      const sx = (Math.sin(i * 99 + time * 0.15 * moodParams.particleSpeed) * 0.5 + 0.5) * width;
      const sy = (Math.cos(i * 33 + time * 0.12 * moodParams.particleSpeed) * 0.5 + 0.5) * height;
      const sparkleAlpha = (Math.sin(time * 3 + i) * 0.5 + 0.5) * moodParams.glowIntensity;

      ctx.fillStyle = activeTheme.secondary;
      ctx.globalAlpha = sparkleAlpha;
      ctx.beginPath();
      ctx.arc(sx, sy, 1.5 + (i % 3), 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1.0;
    }

    // 4. Centerpiece Dual Ring
    const cx = displayMode === 'album' ? width * 0.58 : width / 2;
    const cy = height / 2;
    const ringRadius = (height * 0.18) + moodParams.ringExpansion + Math.sin(time * 2) * 6;

    ctx.save();
    ctx.translate(cx, cy);

    ctx.strokeStyle = activeTheme.primary;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, ringRadius, 0, Math.PI * 2);
    ctx.stroke();

    ctx.rotate(time * 0.2 * moodParams.particleSpeed);
    const nodes = 12;
    for (let i = 0; i < nodes; i++) {
      const angle = (i / nodes) * Math.PI * 2;
      const waveOffset = Math.sin(time * 4 + i) * 12;
      const nx = Math.cos(angle) * (ringRadius + 20 + waveOffset);
      const ny = SinCos(angle) * (ringRadius + 20 + waveOffset);

      ctx.fillStyle = activeTheme.secondary;
      ctx.beginPath();
      ctx.arc(nx, ny, 3.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    // 5. OPTIONAL TOP-LEFT HEADER BRANDING
    if (showHeaderBranding && (headerTitle.trim() !== '' || headerSubtitle.trim() !== '')) {
      if (headerTitle.trim() !== '') {
        ctx.fillStyle = '#ffffff';
        ctx.font = '700 13px "SF Pro Display", sans-serif';
        ctx.textAlign = 'left';
        ctx.fillText(headerTitle.toUpperCase(), marginX, marginY + 12);
      }

      if (headerSubtitle.trim() !== '') {
        ctx.fillStyle = activeTheme.secondary;
        ctx.font = '500 11px font-mono, monospace';
        ctx.fillText(headerSubtitle.toUpperCase(), marginX, marginY + 28);
      }
    }

    // Active Mood Phase Tag (Top Center)
    ctx.fillStyle = activeTheme.secondary;
    ctx.font = '600 10px font-mono, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`MOOD PHASE: [ ${moodParams.phaseName.toUpperCase()} ]`, width / 2, marginY + 10);

    // 6. CUSTOM BRANDING LOGO EMBLEM OVERLAY (PERCENTAGE RESPONSIVE SCALING)
    if (logoImage) {
      ctx.save();
      const responsiveLogoWidth = (width * (logoPercentWidth / 100)); // e.g. 5% of canvas width
      const aspect = logoImage.height / logoImage.width || 1;
      const responsiveLogoHeight = responsiveLogoWidth * aspect;

      let lx = width - responsiveLogoWidth - marginX;
      let ly = marginY;

      if (logoCorner === 'top-left') {
        lx = marginX;
        ly = showHeaderBranding ? marginY + 40 : marginY;
      } else if (logoCorner === 'bottom-right') {
        lx = width - responsiveLogoWidth - marginX;
        ly = height - responsiveLogoHeight - marginY;
      } else if (logoCorner === 'bottom-left') {
        lx = marginX;
        ly = height - responsiveLogoHeight - marginY;
      }

      ctx.globalAlpha = logoOpacity;

      if (logoGlow) {
        const shimmerPulse = Math.sin(time * 2) * 0.3 + 0.7;
        ctx.shadowColor = activeTheme.primary;
        ctx.shadowBlur = 12 * shimmerPulse;
      }

      ctx.drawImage(logoImage, lx, ly, responsiveLogoWidth, responsiveLogoHeight);
      ctx.restore();
    }

    // 7. ALBUM MODE: 8-TRACK SCROLLING WINDOW OVERLAY
    if (displayMode === 'album' && tracklist.length > 0) {
      ctx.save();
      const sidebarWidth = width * 0.26; // Proportional 26% width
      const startY = marginY + 45;
      const lineHeight = 20;
      const visibleWindowSize = 8;

      const scrollOffset = Math.max(0, Math.min(activeTrackIndex - 3, tracklist.length - visibleWindowSize));
      const displayedTracks = tracklist.slice(scrollOffset, scrollOffset + visibleWindowSize);

      ctx.fillStyle = 'rgba(5, 5, 12, 0.75)';
      ctx.strokeStyle = activeTheme.glow;
      ctx.lineWidth = 1;
      ctx.beginPath();
      if (typeof ctx.roundRect === 'function') {
        ctx.roundRect(marginX, startY - 10, sidebarWidth, visibleWindowSize * lineHeight + 20, 8);
      } else {
        ctx.rect(marginX, startY - 10, sidebarWidth, visibleWindowSize * lineHeight + 20);
      }
      ctx.fill();
      ctx.stroke();

      ctx.font = '500 11px font-mono, monospace';
      ctx.textAlign = 'left';

      for (let i = 0; i < displayedTracks.length; i++) {
        const actualIndex = scrollOffset + i;
        const itemY = startY + 12 + (i * lineHeight);
        const isCurrent = actualIndex === activeTrackIndex;
        const isPast = actualIndex < activeTrackIndex;

        if (isCurrent) {
          ctx.fillStyle = activeTheme.glow;
          ctx.fillRect(marginX + 4, itemY - 12, sidebarWidth - 8, 16);

          ctx.fillStyle = activeTheme.secondary;
          ctx.fillText(`▶ ${displayedTracks[i]}`, marginX + 10, itemY);
        } else if (isPast) {
          ctx.fillStyle = 'rgba(148, 163, 184, 0.4)';
          ctx.fillText(`✓ ${displayedTracks[i]}`, marginX + 10, itemY);
        } else {
          ctx.fillStyle = 'rgba(226, 232, 240, 0.7)';
          ctx.fillText(`  ${displayedTracks[i]}`, marginX + 10, itemY);
        }
      }
      ctx.restore();
    }

    // 8. EDITABLE DISPLAY SONG TITLE & ARTIST (Bottom Center)
    if (displaySongTitle.trim() !== '') {
      ctx.fillStyle = '#ffffff';
      ctx.font = '600 16px "SF Pro Display", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(displaySongTitle.toUpperCase(), width / 2, height - marginY - 18);
    }

    if (displayArtist.trim() !== '') {
      ctx.fillStyle = '#94a3b8';
      ctx.font = '500 12px "SF Pro Display", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(displayArtist, width / 2, height - marginY);
    }

    // 9. YOUTUBE SAFE AREA GUIDES (VISIBLE ONLY WHILE EDITING - AUTO HIDDEN ON RECORDING)
    if (showSafeArea && !isRecording) {
      ctx.save();
      ctx.setLineDash([6, 6]);
      ctx.lineWidth = 1.5;

      // Green Safe Margin Box (5% Edge Margin)
      ctx.strokeStyle = '#10b981';
      ctx.strokeRect(marginX, marginY, width - (marginX * 2), height - (marginY * 2));

      // Mobile Crop Guide Box (Center Safe Area)
      if (previewDevice === 'mobile') {
        const mobWidth = width * 0.7; // Mobile 70% safe viewport
        ctx.strokeStyle = '#3b82f6';
        ctx.strokeRect((width - mobWidth) / 2, marginY, mobWidth, height - (marginY * 2));
      }

      ctx.restore();
    }
  };

  const SinCos = (a: number) => Math.sin(a);

  // RECORDING PIPELINE WITH CLEAN REAL AUDIO
  const startCanvasRecording = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    initAudioEngine();

    setRecordedWebmUrl(null);
    setRecordedMp4Url(null);

    const canvasStream = canvas.captureStream(60);
    const combinedStream = new MediaStream();
    canvasStream.getVideoTracks().forEach(track => combinedStream.addTrack(track));

    if (audioDestinationRef.current && audioDestinationRef.current.stream) {
      const audioTracks = audioDestinationRef.current.stream.getAudioTracks();
      if (audioTracks.length > 0) {
        combinedStream.addTrack(audioTracks[0]);
      }
    }

    let mimeType = 'video/webm;codecs=vp9,opus';
    if (!MediaRecorder.isTypeSupported(mimeType)) {
      mimeType = 'video/webm';
    }

    const recorder = new MediaRecorder(combinedStream, {
      mimeType,
      videoBitsPerSecond: 20_000_000,
      audioBitsPerSecond: 320_000
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size > 0) {
        chunks.push(e.data);
      }
    };

    recorder.onstop = () => {
      const webmBlob = new Blob(chunks, { type: 'video/webm' });
      setRecordedWebmUrl(URL.createObjectURL(webmBlob));

      const mp4Blob = new Blob(chunks, { type: 'video/mp4' });
      setRecordedMp4Url(URL.createObjectURL(mp4Blob));

      setIsRecording(false);
    };

    mediaRecorderRef.current = recorder;
    recorder.start(100);
    setIsRecording(true);

    handlePlay();
  };

  const stopCanvasRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    handlePause();
  };

  const handlePlay = () => {
    initAudioEngine();
    playheadStartRef.current = performance.now();
    setPlaybackState('playing');

    if (audioElementRef.current) {
      audioElementRef.current.currentTime = getCalculatedTime();
      audioElementRef.current.play().catch(() => {});
    }
  };

  const handlePause = () => {
    timeOffsetRef.current = getCalculatedTime();
    setPlaybackState('paused');
    if (audioElementRef.current) {
      audioElementRef.current.pause();
    }
  };

  const handleStop = () => {
    timeOffsetRef.current = 0;
    setPlaybackState('idle');
    setCurrentTime(0);
    if (audioElementRef.current) {
      audioElementRef.current.pause();
      audioElementRef.current.currentTime = 0;
    }
    if (isRecording) {
      stopCanvasRecording();
    }
  };

  const handleSeek = (newTime: number) => {
    timeOffsetRef.current = Math.max(0, Math.min(newTime, duration));
    playheadStartRef.current = performance.now();
    setCurrentTime(timeOffsetRef.current);
    if (audioElementRef.current) {
      audioElementRef.current.currentTime = newTime;
    }
  };

  const toggleMute = () => {
    setMuted(!muted);
    if (masterGainRef.current) {
      masterGainRef.current.gain.value = !muted ? 0 : 0.9;
    }
  };

  const handleSelectDemoTrack = (track: typeof DEMO_TRACKS[0]) => {
    setSelectedTrack(track);
    setDisplaySongTitle(track.title);
    setDisplayArtist(track.artist);
    setUrlError(null);
    handleStop();
    if (audioElementRef.current) {
      audioElementRef.current.src = track.url;
      audioElementRef.current.load();
    }
  };

  const handleLoadCustomUrl = () => {
    setUrlError(null);
    if (!customUrlInput.trim()) return;
    let url = customUrlInput.trim();

    if (url.includes('youtube.com') || url.includes('youtu.be')) {
      setUrlError("YouTube web page links are protected by browser CORS security. Please upload a local MP3/WAV file or paste a Flow Music song link.");
      return;
    }

    const match = url.match(/song\/([a-f0-9-]+)/i);
    if (match && match[1]) {
      url = `https://storage.googleapis.com/producer-app-public/clips/${match[1]}.m4a`;
    }

    const customTrack = {
      id: "custom",
      title: "Custom Stream Track",
      artist: "External Link",
      url
    };

    setSelectedTrack(customTrack);
    setDisplaySongTitle("Custom Loaded Song");
    setDisplayArtist("External Stream");
    handleStop();
    if (audioElementRef.current) {
      audioElementRef.current.src = url;
      audioElementRef.current.load();
    }
  };

  const handleAudioFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUrlError(null);
    const localBlobUrl = URL.createObjectURL(file);
    const cleanName = file.name.replace(/\.[^/.]+$/, "");

    const uploadedTrack = {
      id: `local-${Date.now()}`,
      title: cleanName,
      artist: "Elyzareth Studio",
      url: localBlobUrl
    };

    setSelectedTrack(uploadedTrack);
    setDisplaySongTitle(cleanName);
    setDisplayArtist("Elyzareth Studio");
    handleStop();

    if (audioElementRef.current) {
      audioElementRef.current.src = localBlobUrl;
      audioElementRef.current.load();
      initAudioEngine();
    }
  };

  const handleBgImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const imgUrl = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      setBgImage(img);
    };
    img.src = imgUrl;
  };

  const handleLogoFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const imgUrl = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      setLogoImage(img);
    };
    img.src = imgUrl;
  };

  const handleTracklistTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const lines = e.target.value.split('\n').filter(l => l.trim().length > 0);
    setTracklist(lines.slice(0, 20));
  };

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-6 font-sans">
      <audio
        ref={audioElementRef}
        src={selectedTrack.url}
        crossOrigin="anonymous"
        preload="auto"
      />

      <input
        type="file"
        ref={audioFileInputRef}
        onChange={handleAudioFileUpload}
        accept="audio/*"
        className="hidden"
      />

      <input
        type="file"
        ref={bgFileInputRef}
        onChange={handleBgImageUpload}
        accept="image/*"
        className="hidden"
      />

      <input
        type="file"
        ref={logoFileInputRef}
        onChange={handleLogoFileUpload}
        accept="image/*"
        className="hidden"
      />

      <div className="w-full max-w-5xl space-y-6">

        {/* HEADER BAR */}
        <div className="flex items-center justify-between border-b border-slate-800 pb-4">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-purple-600/20 text-purple-400 rounded-lg border border-purple-500/30">
              <Sparkles className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white flex items-center gap-2">
                ELYZARETH OS <span className="text-xs px-2.5 py-0.5 rounded bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 font-mono">v26.0 YOUTUBE SAFE LAYOUT</span>
              </h1>
              <p className="text-xs text-slate-400">Percentage Responsive Scaling, YouTube Safe Area & Device Previews</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {/* DISPLAY MODE SWITCH */}
            <div className="flex items-center bg-slate-900 border border-slate-800 rounded-lg p-1 text-xs">
              <button
                onClick={() => setDisplayMode('album')}
                className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                  displayMode === 'album' ? 'bg-purple-600 text-white font-bold' : 'text-slate-400 hover:text-slate-200'
                }`}
              >
                <Disc className="w-3.5 h-3.5" /> Album Mode
              </button>
              <button
                onClick={() => setDisplayMode('single')}
                className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                  displayMode === 'single' ? 'bg-purple-600 text-white font-bold' : 'text-slate-400 hover:text-slate-200'
                }`}
              >
                <Layers className="w-3.5 h-3.5" /> Single Mode
              </button>
            </div>

            <button
              onClick={toggleMute}
              className="p-2 bg-slate-900 border border-slate-800 rounded-lg text-slate-400 hover:text-white transition"
              title={muted ? "Unmute Audio" : "Mute Audio"}
            >
              {muted ? <VolumeX className="w-4 h-4 text-red-400" /> : <Volume2 className="w-4 h-4 text-emerald-400" />}
            </button>

            <button
              onClick={() => setShowTelemetry(!showTelemetry)}
              className={`px-3 py-1.5 rounded-lg text-xs font-medium flex items-center gap-1.5 transition ${
                showTelemetry ? 'bg-purple-600/30 text-purple-300 border border-purple-500/50' : 'bg-slate-900 text-slate-400 border border-slate-800'
              }`}
            >
              <Activity className="w-3.5 h-3.5" /> Telemetry
            </button>
          </div>
        </div>

        {/* YOUTUBE SAFE AREA & DEVICE PREVIEW BAR */}
        <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-4 space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-emerald-400 uppercase tracking-wider flex items-center gap-1.5">
              <Grid className="w-4 h-4" /> YOUTUBE SAFE AREA GUIDES & DEVICE PREVIEW
            </span>
            <button
              onClick={() => setShowSafeArea(!showSafeArea)}
              className={`px-3 py-1 rounded text-xs font-medium transition flex items-center gap-1.5 ${
                showSafeArea ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30' : 'bg-slate-800 text-slate-400'
              }`}
            >
              {showSafeArea ? <Eye className="w-3.5 h-3.5" /> : <EyeOff className="w-3.5 h-3.5" />}
              {showSafeArea ? 'Safe Area Guides: VISIBLE' : 'Safe Area Guides: HIDDEN'}
            </button>
          </div>

          <div className="flex items-center gap-2 text-xs">
            <span className="text-slate-400 font-medium">Device Framing Preview:</span>
            <button
              onClick={() => setPreviewDevice('desktop')}
              className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                previewDevice === 'desktop' ? 'bg-emerald-600 text-white font-bold' : 'bg-slate-950 text-slate-400'
              }`}
            >
              <Monitor className="w-3.5 h-3.5" /> Desktop
            </button>

            <button
              onClick={() => setPreviewDevice('mobile')}
              className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                previewDevice === 'mobile' ? 'bg-emerald-600 text-white font-bold' : 'bg-slate-950 text-slate-400'
              }`}
            >
              <Smartphone className="w-3.5 h-3.5" /> Mobile Crop
            </button>

            <button
              onClick={() => setPreviewDevice('tv')}
              className={`px-3 py-1 rounded font-medium flex items-center gap-1.5 transition ${
                previewDevice === 'tv' ? 'bg-emerald-600 text-white font-bold' : 'bg-slate-950 text-slate-400'
              }`}
            >
              <Tv className="w-3.5 h-3.5" /> TV Display
            </button>
          </div>
        </div>

        {/* GLOBAL COLOR THEME SELECTOR */}
        <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-4 space-y-3">
          <span className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-1.5">
            <Palette className="w-4 h-4" /> GLOBAL COLOR PALETTE THEME
          </span>
          <div className="grid grid-cols-2 sm:grid-cols-6 gap-2 text-xs font-medium">
            {COLOR_THEMES.map((theme) => (
              <button
                key={theme.id}
                onClick={() => setActiveTheme(theme)}
                className={`p-2 rounded-lg border text-center transition ${
                  activeTheme.id === theme.id
                    ? 'bg-purple-600/20 border-purple-500 text-white font-bold'
                    : 'bg-slate-950/60 border-slate-800 text-slate-400 hover:border-slate-700'
                }`}
              >
                {theme.name}
              </button>
            ))}
          </div>
        </div>

        {/* LOGO EMBLEM BRANDING CONTROLS */}
        <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-4 space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-1.5">
              <Shield className="w-4 h-4" /> BRAND LOGO EMBLEM (PNG / SVG)
            </span>
            {logoImage && (
              <button
                onClick={() => setLogoImage(null)}
                className="text-[11px] text-red-400 hover:text-red-300 underline"
              >
                Remove Logo
              </button>
            )}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-4 gap-3 text-xs">
            <button
              onClick={() => logoFileInputRef.current?.click()}
              className="px-4 py-2 bg-purple-600 hover:bg-purple-500 text-white font-semibold rounded-lg flex items-center justify-center gap-2 transition shadow-md shadow-purple-600/20"
            >
              <Upload className="w-4 h-4" /> Upload Logo PNG/SVG
            </button>

            <div className="flex items-center gap-2">
              <span className="text-slate-400">Position:</span>
              <select
                value={logoCorner}
                onChange={(e) => setLogoCorner(e.target.value as LogoCorner)}
                className="w-full bg-slate-950 border border-slate-800 rounded px-2.5 py-1.5 text-slate-200 focus:outline-none"
              >
                <option value="top-right">Top-Right (5% Margin)</option>
                <option value="top-left">Top-Left</option>
                <option value="bottom-right">Bottom-Right</option>
                <option value="bottom-left">Bottom-Left</option>
              </select>
            </div>

            {/* Percentage Scale Slider */}
            <div className="flex items-center gap-2 text-slate-400">
              <span>Width:</span>
              <input
                type="range"
                min={3.0}
                max={10.0}
                step={0.5}
                value={logoPercentWidth}
                onChange={(e) => setLogoPercentWidth(parseFloat(e.target.value))}
                className="w-full h-1.5 bg-slate-800 rounded appearance-none cursor-pointer accent-purple-500"
              />
              <span className="font-mono text-[11px] text-purple-300">{logoPercentWidth}%</span>
            </div>

            <button
              onClick={() => setLogoGlow(!logoGlow)}
              className={`px-3 py-1.5 rounded border font-medium transition ${
                logoGlow ? 'bg-purple-600/30 border-purple-500 text-purple-300' : 'bg-slate-950 border-slate-800 text-slate-500'
              }`}
            >
              {logoGlow ? '✨ Logo Shimmer: ON' : 'Logo Shimmer: OFF'}
            </button>
          </div>
        </div>

        {/* EDITABLE BRANDING & METADATA CONTROLS */}
        <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-4 space-y-4">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2">
            <div className="flex items-center gap-2">
              <span className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-1.5">
                <Type className="w-4 h-4" /> EDIT CANVAS TEXT OVERLAYS
              </span>
              <button
                onClick={() => setShowHeaderBranding(!showHeaderBranding)}
                className={`px-2.5 py-0.5 rounded text-[11px] font-medium flex items-center gap-1 transition ${
                  showHeaderBranding ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30' : 'bg-slate-800 text-slate-400'
                }`}
              >
                {showHeaderBranding ? <Eye className="w-3 h-3" /> : <EyeOff className="w-3 h-3" />}
                {showHeaderBranding ? 'Top-Left Header: ON' : 'Top-Left Header: OFF'}
              </button>
            </div>
            <span className="text-[11px] text-purple-300 font-mono">MODE: {displayMode.toUpperCase()}</span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
            {showHeaderBranding && (
              <>
                <div className="space-y-1">
                  <label className="text-slate-400 font-medium">Header Title (Top-Left):</label>
                  <input
