export default function Component() {
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [volume, setVolume] = useState<number>(0.8);
  const [currentTime, setCurrentTime] = useState<number>(0);
  const [duration, setDuration] = useState<number>(180);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const [copiedCid, setCopiedCid] = useState<boolean>(false);
  const [activeTab, setActiveTab] = useState<"genome" | "telemetry" | "gate">("genome");

  // Record state
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [recordedChunks, setRecordedChunks] = useState<Blob[]>([]);
  const [recordedVideoUrl, setRecordedVideoUrl] = useState<string | null>(null);
  const [recordingSeconds, setRecordingSeconds] = useState<number>(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const animRef = useRef<number | null>(null);

  // Web Audio refs
  const audioCtxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const mediaStreamDestRef = useRef<MediaStreamAudioDestinationNode | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);

  const songUrl = "https://storage.googleapis.com/producer-app-public/clips/54a04253-cd95-4b8a-a0ed-1f4a782da800.m4a";

  // Active scene
  const currentSection = LSJ_TIMELINE.find(
    (s) => currentTime >= s.timeRange[0] && currentTime < s.timeRange[1]
  ) || LSJ_TIMELINE[0];

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    audio.volume = isMuted ? 0 : volume;

    const updateTime = () => setCurrentTime(audio.currentTime);
    const updateDuration = () => setDuration(audio.duration || 180);
    const handleEnded = () => setIsPlaying(false);

    audio.addEventListener("timeupdate", updateTime);
    audio.addEventListener("loadedmetadata", updateDuration);
    audio.addEventListener("ended", handleEnded);

    return () => {
      audio.removeEventListener("timeupdate", updateTime);
      audio.removeEventListener("loadedmetadata", updateDuration);
      audio.removeEventListener("ended", handleEnded);
    };
  }, [isMuted, volume]);

  useEffect(() => {
    let timer: any = null;
    if (isRecording) {
      timer = setInterval(() => setRecordingSeconds((prev) => prev + 1), 1000);
    } else {
      setRecordingSeconds(0);
    }
    return () => clearInterval(timer);
  }, [isRecording]);

  const setupWebAudio = () => {
    if (audioCtxRef.current || !audioRef.current) return;

    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 128;

      const mediaStreamDest = ctx.createMediaStreamDestination();

      const source = ctx.createMediaElementSource(audioRef.current);
      source.connect(analyser);
      analyser.connect(ctx.destination);
      analyser.connect(mediaStreamDest);

      audioCtxRef.current = ctx;
      analyserRef.current = analyser;
      mediaStreamDestRef.current = mediaStreamDest;
    } catch (err) {
      console.warn("Web Audio setup notice:", err);
    }
  };

  const togglePlay = () => {
    const audio = audioRef.current;
    if (!audio) return;

    setupWebAudio();

    if (audioCtxRef.current && audioCtxRef.current.state === "suspended") {
      audioCtxRef.current.resume();
    }

    if (isPlaying) {
      audio.pause();
      setIsPlaying(false);
    } else {
      audio.play()
        .then(() => setIsPlaying(true))
        .catch((err) => {
          console.error("Audio playback error:", err);
          setIsPlaying(false);
        });
    }
  };

  const startRecording = () => {
    const canvas = canvasRef.current;
    const audio = audioRef.current;
    if (!canvas || !audio) return;

    setupWebAudio();

    if (audioCtxRef.current && audioCtxRef.current.state === "suspended") {
      audioCtxRef.current.resume();
    }

    try {
      const canvasStream = canvas.captureStream(60);
      const combinedStream = new MediaStream();

      canvasStream.getVideoTracks().forEach((track) => combinedStream.addTrack(track));

      if (mediaStreamDestRef.current && mediaStreamDestRef.current.stream.getAudioTracks().length > 0) {
        mediaStreamDestRef.current.stream.getAudioTracks().forEach((track) => combinedStream.addTrack(track));
      } else if ((audio as any).captureStream) {
        const audioStream = (audio as any).captureStream();
        audioStream.getAudioTracks().forEach((track: MediaStreamTrack) => combinedStream.addTrack(track));
      }

      let mimeType = "video/webm;codecs=vp9,opus";
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        mimeType = "video/webm";
      }

      const recorder = new MediaRecorder(combinedStream, { mimeType });
      const chunks: Blob[] = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: "video/webm" });
        const url = URL.createObjectURL(blob);
        setRecordedVideoUrl(url);
        setRecordedChunks(chunks);
      };

      recorder.start();
      mediaRecorderRef.current = recorder;
      setIsRecording(true);

      if (!isPlaying) togglePlay();
    } catch (err) {
      console.error("MediaRecorder capture error:", err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const downloadRecordedVideo = () => {
    if (!recordedVideoUrl) return;
    const a = document.createElement("a");
    a.href = recordedVideoUrl;
    a.download = "elyzareth_lsj_vgn_master.webm";
    a.click();
  };

  // Real-time Canvas Renderer (LSJ-VGN-001) - Dynamic Evolving Narrative Scenes
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let frame = 0;
    const dataArray = new Uint8Array(64);

    const render = () => {
      frame++;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      if (analyserRef.current && isPlaying) {
        analyserRef.current.getByteFrequencyData(dataArray);
      } else {
        for (let i = 0; i < 64; i++) {
          dataArray[i] = Math.max(15, Math.sin(frame * 0.05 + i * 0.2) * 35 + 25);
        }
      }

      const width = canvas.width;
      const height = canvas.height;
      const centerX = width / 2;
      const centerY = height / 2;

      if (currentSection.code === "LSJ-SCENE-00") {
        // Prelude (0:00 - 0:35) - Warm Horizon Glow & Soft Rain
        ctx.fillStyle = "#0f172a";
        ctx.fillRect(0, 0, width, height);

        const gradient = ctx.createRadialGradient(centerX, centerY, 10, centerX, centerY, 180);
        gradient.addColorStop(0, "rgba(245, 158, 11, 0.4)");
        gradient.addColorStop(1, "rgba(15, 23, 42, 0.95)");
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);

        ctx.beginPath();
        ctx.arc(centerX, centerY, 40 + Math.sin(frame * 0.04) * 12, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(245, 158, 11, 0.8)";
        ctx.lineWidth = 2.5;
        ctx.stroke();

      } else if (currentSection.code === "LSJ-SCENE-01") {
        // Intro Memory (0:35 - 0:55) - Bright French Window Grid
        ctx.fillStyle = "#0f172a";
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = "rgba(245, 158, 11, 0.7)";
        ctx.lineWidth = 3;
        ctx.strokeRect(centerX - 130, centerY - 90, 260, 180);
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - 90);
        ctx.lineTo(centerX, centerY + 90);
        ctx.moveTo(centerX - 130, centerY);
        ctx.lineTo(centerX + 130, centerY);
        ctx.stroke();

        ctx.strokeStyle = "rgba(2, 132, 199, 0.8)";
        ctx.lineWidth = 1.8;
        for (let r = 0; r < 35; r++) {
          const rx = (centerX - 120 + (r * 8) + frame * 0.8) % (centerX + 120);
          const ry = (centerY - 85 + (r * 12) + frame * 2.5) % (centerY + 85);
          ctx.beginPath();
          ctx.moveTo(rx, ry);
          ctx.lineTo(rx + 2, ry + 12);
          ctx.stroke();
        }

      } else if (currentSection.code === "LSJ-SCENE-02") {
        // Saxophone Peak (0:55 - 1:25) - Resonant Blue Saxophone Rings
        ctx.fillStyle = "rgba(15, 23, 42, 0.95)";
        ctx.fillRect(0, 0, width, height);

        const avgBass = (dataArray[0] + dataArray[1] + dataArray[2]) / 3;
        const ringRadius = 65 + (avgBass / 255) * 45;

        ctx.beginPath();
        ctx.arc(centerX, centerY, ringRadius, 0, Math.PI * 2);
        ctx.strokeStyle = "#0284c7";
        ctx.lineWidth = 4;
        ctx.shadowColor = "#0284c7";
        ctx.shadowBlur = 20;
        ctx.stroke();
        ctx.shadowBlur = 0;

        for (let j = 0; j < 30; j++) {
          const jx = (centerX + Math.sin(frame * 0.03 + j) * 200) % width;
          const jy = (centerY + Math.cos(frame * 0.03 + j) * 110) % height;
          ctx.beginPath();
          ctx.arc(jx, jy, 3, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(245, 158, 11, 0.9)";
          ctx.fill();
        }

      } else if (currentSection.code === "LSJ-SCENE-03") {
        // Reflection Departure (1:25 - 2:05) - Rain Mirrors & Shimmering Particles
        ctx.fillStyle = "#021329";
        ctx.fillRect(0, 0, width, height);

        // Rippling Rain Mirror Puddle Lines
        const numRipples = 5;
        for (let r = 0; r < numRipples; r++) {
          const ripRadius = ((frame * 1.5 + r * 40) % 180) + 20;
          ctx.beginPath();
          ctx.ellipse(centerX, centerY + 40, ripRadius * 1.6, ripRadius * 0.6, 0, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(2, 132, 199, ${1 - ripRadius / 200})`;
          ctx.lineWidth = 2;
          ctx.stroke();
        }

        // Shimmering Gold Dust
        for (let g = 0; g < 40; g++) {
          const gx = (centerX + Math.sin(frame * 0.02 + g) * 260) % width;
          const gy = (centerY - 50 + Math.cos(frame * 0.02 + g * 1.5) * 120) % height;
          ctx.beginPath();
          ctx.arc(gx, gy, 2, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(245, 158, 11, 0.85)";
          ctx.fill();
        }

      } else if (currentSection.code === "LSJ-SCENE-04") {
        // Jasmine Helix Reburst (2:05 - 2:40) - Dual Interlocking Wave Spiral
        ctx.fillStyle = "#0f172a";
        ctx.fillRect(0, 0, width, height);

        const avgBass = (dataArray[0] + dataArray[1] + dataArray[2]) / 3;
        const helixAmp = 40 + (avgBass / 255) * 35;

        // Helix 1 (Cyan)
        ctx.beginPath();
        ctx.strokeStyle = "#06b6d4";
        ctx.lineWidth = 3.5;
        for (let x = 0; x < width; x += 10) {
          const y = centerY + Math.sin((x + frame * 4) * 0.02) * helixAmp;
          if (x === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();

        // Helix 2 (Gold)
        ctx.beginPath();
        ctx.strokeStyle = "#f59e0b";
        ctx.lineWidth = 3.5;
        for (let x = 0; x < width; x += 10) {
          const y = centerY + Math.sin((x + frame * 4) * 0.02 + Math.PI) * helixAmp;
          if (x === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();

      } else {
        // Outro Silhouette (2:40 - 3:00) - Soft Fading Window Silhouette
        ctx.fillStyle = "#090d16";
        ctx.fillRect(0, 0, width, height);

        ctx.strokeStyle = "rgba(245, 158, 11, 0.5)";
        ctx.lineWidth = 2;
        ctx.strokeRect(centerX - 80, centerY - 60, 160, 120);

        ctx.beginPath();
        ctx.arc(centerX, centerY, 30 + Math.sin(frame * 0.02) * 6, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(2, 132, 199, 0.6)";
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }

      animRef.current = requestAnimationFrame(render);
    };

    render();

    return () => {
      if (animRef.current) cancelAnimationFrame(animRef.current);
    };
  }, [isPlaying, currentSection]);

  const copyGenomeId = () => {
