import React, { useState, useEffect } from "react";
import { THEMES } from "./themeEngine";
import { SCENES } from "./sceneEngine";
import { PerformanceMetrics, ThemeProfile, SharedStudioState } from "./types";
import { ResourceManager } from "./resourceManager";
import SceneCanvas from "./SceneCanvas";
import ControlPanel from "./ControlPanel";
import PerformanceHud from "./PerformanceHud";
import VisualizerView from "./VisualizerView";
import NodeGraphView from "./NodeGraphView";
import { Layers, Activity, Sparkles, Box, Monitor, Sliders, Play, Pause, ExternalLink } from "lucide-react";

export default function Component() {
  const [viewMode, setViewMode] = useState<"console" | "visualizer" | "dual">("dual");

  const [currentThemeKey, setCurrentThemeKey] = useState<string>("autumn-studio");
  const [targetThemeKey, setTargetThemeKey] = useState<string>("autumn-studio");
  const [themeProgress, setThemeProgress] = useState<number>(0);
  const [isInterpolating, setIsInterpolating] = useState<boolean>(false);

  const [currentSceneKey, setCurrentSceneKey] = useState<string>("recording-booth");
  const [particleCount, setParticleCount] = useState<number>(240);
  const [audioEnergy, setAudioEnergy] = useState<number>(0.45);
  const [isCameraDriftActive, setIsCameraDriftActive] = useState<boolean>(true);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [isHudVisible, setIsHudVisible] = useState<boolean>(true);

  const [metrics, setMetrics] = useState<PerformanceMetrics>({
    fps: 60,
    frameTimeMs: 16.7,
    particleCount: 240,
    activeTheme: THEMES["autumn-studio"].name,
    activeScene: SCENES["recording-booth"].name,
    interpolationProgress: 0,
    cameraOffsetX: 0,
    cameraOffsetY: 0,
    cameraZoom: 1.0,
    audioEnergy: 0.45,
    cacheHitRatio: 1.0,
    cachedAssetCount: 12,
    cpuRenderMs: 4.2,
  });

  const sharedState: SharedStudioState = {
    currentThemeKey,
    targetThemeKey,
    themeProgress,
    currentSceneKey,
    particleCount,
    audioEnergy,
    isCameraDriftActive,
    isPlaying,
    trackTitle: "Between Two Signals",
    trackArtist: "Elyzareth • Volume II",
  };

  // Handle smooth 600ms Theme Interpolation
  const handleSelectTheme = (newThemeKey: string) => {
    if (newThemeKey === targetThemeKey && !isInterpolating) return;

    setTargetThemeKey(newThemeKey);
    setIsInterpolating(true);
    setThemeProgress(0);

    const startTime = performance.now();
    const duration = 600; // 600ms

    const animate = (now: number) => {
      const elapsed = now - startTime;
      const progress = Math.min(1.0, elapsed / duration);
      setThemeProgress(progress);

      if (progress < 1.0) {
        requestAnimationFrame(animate);
      } else {
        setCurrentThemeKey(newThemeKey);
        setThemeProgress(0);
        setIsInterpolating(false);
      }
    };

    requestAnimationFrame(animate);
  };

  const handleMetricsUpdate = (partialMetrics: Partial<PerformanceMetrics>) => {
    setMetrics((prev) => ({
      ...prev,
      ...partialMetrics,
      activeTheme:
        currentThemeKey === targetThemeKey
          ? THEMES[currentThemeKey].name
          : `${THEMES[currentThemeKey].name} ➔ ${THEMES[targetThemeKey].name}`,
      activeScene: SCENES[currentSceneKey].name,
      cacheHitRatio: ResourceManager.getCacheHitRatio(),
      cachedAssetCount: ResourceManager.getCachedCount(),
    }));
  };

  const currentThemeObj: ThemeProfile = THEMES[currentThemeKey];
  const targetThemeObj: ThemeProfile = THEMES[targetThemeKey];
  const currentSceneObj = SCENES[currentSceneKey];

  // Fullscreen Presentation Mode Render
  if (viewMode === "visualizer") {
    return (
      <VisualizerView
        state={sharedState}
        currentThemeObj={currentThemeObj}
        targetThemeObj={targetThemeObj}
        currentSceneObj={currentSceneObj}
        onMetricsUpdate={handleMetricsUpdate}
        onExitFullscreen={() => setViewMode("dual")}
      />
    );
  }

  return (
