// Helper to convert hex to RGB
function hexToRgb(hex: string): { r: number; g: number; b: number } {
  let cleanHex = hex.replace("#", "");
  if (cleanHex.length === 3) {
    cleanHex = cleanHex.split("").map((c) => c + c).join("");
  }
  const num = parseInt(cleanHex, 16);
  return {
    r: (num >> 16) & 255,
    g: (num >> 8) & 255,
    b: num & 255,
  };
}

// Helper to convert RGB to Hex
function rgbToHex(r: number, g: number, b: number): string {
  const clamp = (val: number) => Math.min(255, Math.max(0, Math.round(val)));
  return (
    "#" +
    [r, g, b]
      .map((x) => clamp(x).toString(16).padStart(2, "0"))
      .join("")
  );
}

// Interpolate between two hex colors by factor t (0..1)
export function interpolateHex(color1: string, color2: string, t: number): string {
  const rgb1 = hexToRgb(color1);
  const rgb2 = hexToRgb(color2);
  const r = rgb1.r + (rgb2.r - rgb1.r) * t;
  const g = rgb1.g + (rgb2.g - rgb1.g) * t;
  const b = rgb1.b + (rgb2.b - rgb1.b) * t;
  return rgbToHex(r, g, b);
}

// Interpolate full ThemeColors structure
export function interpolateThemeColors(
  c1: ThemeColors,
  c2: ThemeColors,
  t: number
): ThemeColors {
  return {
    primary: interpolateHex(c1.primary, c2.primary, t),
    secondary: interpolateHex(c1.secondary, c2.secondary, t),
    accent: interpolateHex(c1.accent, c2.accent, t),
    bgDark: interpolateHex(c1.bgDark, c2.bgDark, t),
    bgLight: interpolateHex(c1.bgLight, c2.bgLight, t),
    glow: interpolateHex(c1.glow, c2.glow, t),
  };
}

export interface AssetCacheItem {
  key: string;
  loadedAt: number;
  sizeKb: number;
  type: "texture" | "mesh" | "audio" | "font";
  status: "cached" | "loading" | "purged";
}

class ResourceManagerClass {
  private cache: Map<string, AssetCacheItem> = new Map();
  private totalHits = 0;
  private totalRequests = 0;

  constructor() {
    // Pre-populate standard asset seeds
    const defaultAssets: [string, "texture" | "mesh" | "audio" | "font", number][] = [
      ["asset:mic-stand", "mesh", 420],
      ["asset:sound-foam-tile", "texture", 1280],
      ["asset:warm-lamp", "texture", 350],
      ["asset:bokeh-map", "texture", 2100],
      ["asset:rain-window", "texture", 1850],
      ["asset:neon-sign", "mesh", 610],
      ["asset:bookshelf-texture", "texture", 3200],
      ["asset:arch-shadow", "texture", 890],
      ["asset:desk-lamp", "mesh", 410],
      ["asset:aurora-mesh", "mesh", 1450],
      ["asset:starfield-map", "texture", 2900],
      ["asset:horizon-blur", "texture", 720],
    ];

    defaultAssets.forEach(([key, type, sizeKb]) => {
      this.cache.set(key, {
        key,
        loadedAt: Date.now(),
        sizeKb,
        type,
        status: "cached",
      });
    });
  }

  public requestAsset(key: string): boolean {
    this.totalRequests++;
    const item = this.cache.get(key);
    if (item && item.status === "cached") {
      this.totalHits++;
      return true; // Hit
    }

    // Miss: simulate async load
    this.cache.set(key, {
      key,
      loadedAt: Date.now(),
      sizeKb: 500 + Math.floor(Math.random() * 1000),
      type: "texture",
      status: "loading",
    });

    setTimeout(() => {
      const loaded = this.cache.get(key);
      if (loaded) {
        loaded.status = "cached";
      }
    }, 400);

    return false; // Miss
  }

  public getCacheHitRatio(): number {
    if (this.totalRequests === 0) return 1.0;
    return this.totalHits / this.totalRequests;
  }

  public getCachedCount(): number {
    let count = 0;
    this.cache.forEach((item) => {
      if (item.status === "cached") count++;
    });
    return count;
  }

  public getCacheList(): AssetCacheItem[] {
    return Array.from(this.cache.values());
  }
}

export const ResourceManager = new ResourceManagerClass();

import React, { useEffect, useRef } from "react";
import { ThemeProfile, SceneProfile, PerformanceMetrics, ThemeColors } from "./types";
import { interpolateThemeColors } from "./themeEngine";
import { PluginRegistry } from "./pluginApi";

interface SceneCanvasProps {
  currentTheme: ThemeProfile;
  targetTheme: ThemeProfile;
  themeProgress: number; // 0..1
  scene: SceneProfile;
  particleCount: number;
  audioEnergy: number; // 0..1
  isCameraDriftActive: boolean;
  onMetricsUpdate: (metrics: Partial<PerformanceMetrics>) => void;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  alpha: number;
  layer: number; // 0, 1, 2
}

export default function SceneCanvas({
  currentTheme,
  targetTheme,
  themeProgress,
  scene,
  particleCount,
  audioEnergy,
  isCameraDriftActive,
  onMetricsUpdate,
}: SceneCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const particlesRef = useRef<Particle[]>([]);
  const frameCountRef = useRef(0);
  const lastFpsCheckRef = useRef(performance.now());
  const currentFpsRef = useRef(60);

  // Initialize particles
  useEffect(() => {
    const particles: Particle[] = [];
    for (let i = 0; i < particleCount; i++) {
      particles.push({
        x: Math.random() * 1920,
        y: Math.random() * 1080,
        vx: (Math.random() - 0.5) * 0.8,
        vy: (Math.random() - 0.5) * 0.8,
        size: Math.random() * 3 + 1,
        alpha: Math.random() * 0.7 + 0.3,
        layer: Math.floor(Math.random() * 3),
      });
    }
    particlesRef.current = particles;
  }, [particleCount]);

  useEffect(() => {
    let animId: number;

    const render = (now: number) => {
      const renderStart = performance.now();
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const width = canvas.clientWidth || 800;
      const height = canvas.clientHeight || 600;
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }

      frameCountRef.current++;
      if (now - lastFpsCheckRef.current >= 500) {
        currentFpsRef.current = Math.round(
          (frameCountRef.current * 1000) / (now - lastFpsCheckRef.current)
        );
        frameCountRef.current = 0;
        lastFpsCheckRef.current = now;
      }

      const activeColors: ThemeColors = interpolateThemeColors(
        currentTheme.colors,
        targetTheme.colors,
        themeProgress
      );

      const timeSec = now / 1000;
      let camX = 0;
      let camY = 0;
      let camZoom = 1.0;

      if (isCameraDriftActive) {
        const period = scene.camera.periodSec || 40;
        const phase = (timeSec % period) / period;
        const rad = phase * Math.PI * 2;

        camX = Math.sin(rad) * scene.camera.driftX;
        camY = Math.cos(rad * 0.5) * scene.camera.driftY;
        const zoomRange = scene.camera.zoomMax - scene.camera.zoomMin;
        camZoom = scene.camera.zoomMin + (Math.sin(rad) * 0.5 + 0.5) * zoomRange;
      }

      ctx.save();
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      ctx.translate(centerX + camX, centerY + camY);
      ctx.scale(camZoom, camZoom);
      ctx.translate(-centerX, -centerY);

      // Background Gradient
      const bgGradient = ctx.createRadialGradient(
        centerX,
        centerY,
        width * 0.1,
        centerX,
        centerY,
        width * 0.8
      );
      bgGradient.addColorStop(0, activeColors.bgLight);
      bgGradient.addColorStop(1, activeColors.bgDark);
      ctx.fillStyle = bgGradient;
      ctx.fillRect(-50, -50, width + 100, height + 100);

      // Scene Accent Background
      if (scene.id === "aurora-sky") {
        ctx.save();
        ctx.globalCompositeOperation = "screen";
        for (let r = 0; r < 3; r++) {
          ctx.beginPath();
          const wavePhase = timeSec * 0.5 + r * 2;
          ctx.moveTo(0, height * 0.3 + Math.sin(wavePhase) * 40);
          ctx.bezierCurveTo(
            width * 0.3,
            height * 0.2 + Math.cos(wavePhase * 0.8) * 60,
            width * 0.7,
            height * 0.5 + Math.sin(wavePhase * 1.2) * 50,
            width,
            height * 0.35 + Math.cos(wavePhase) * 30
          );
          ctx.lineWidth = 60 + r * 20;
          ctx.strokeStyle = activeColors.glow + "33";
          ctx.stroke();
        }
        ctx.restore();
      }

      // Particles
      const particles = particlesRef.current;
      particles.forEach((p) => {
        const speedFactor = p.layer === 0 ? 0.2 : p.layer === 1 ? 0.5 : 1.0;
        p.x += p.vx * speedFactor;
        p.y += p.vy * speedFactor;

        if (p.x < 0) p.x = width;
        if (p.x > width) p.x = 0;
        if (p.y < 0) p.y = height;
        if (p.y > height) p.y = 0;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (1 + p.layer * 0.3), 0, Math.PI * 2);
        ctx.fillStyle = activeColors.accent;
        ctx.globalAlpha = p.alpha * (0.4 + p.layer * 0.2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
      });

      // Delegate Visualizer Rendering to Active Plugin!
      const activePlugin = PluginRegistry.getActivePlugin();
      activePlugin.render(
        ctx,
        width,
        height,
        { audioEnergy, timeSec },
        scene,
        { ...currentTheme, colors: activeColors }
      );

      // Vignette
      const vignette = ctx.createRadialGradient(
        centerX,
        centerY,
        width * 0.3,
        centerX,
        centerY,
        width * 0.7
      );
      vignette.addColorStop(0, "rgba(0,0,0,0)");
      vignette.addColorStop(1, `rgba(0,0,0,${scene.lighting.vignetteOpacity})`);
      ctx.fillStyle = vignette;
      ctx.fillRect(-50, -50, width + 100, height + 100);

      ctx.restore();

      const renderMs = performance.now() - renderStart;

      onMetricsUpdate({
        fps: currentFpsRef.current,
        frameTimeMs: Number((1000 / Math.max(1, currentFpsRef.current)).toFixed(1)),
        particleCount: particleCount,
        interpolationProgress: Number(themeProgress.toFixed(2)),
        cameraOffsetX: Number(camX.toFixed(1)),
        cameraOffsetY: Number(camY.toFixed(1)),
        cameraZoom: Number(camZoom.toFixed(3)),
        cpuRenderMs: Number(renderMs.toFixed(2)),
      });

      animId = requestAnimationFrame(render);
    };

    animId = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animId);
  }, [
    currentTheme,
    targetTheme,
    themeProgress,
    scene,
    particleCount,
    audioEnergy,
    isCameraDriftActive,
    onMetricsUpdate,
  ]);

  return (
    <canvas
      ref={canvasRef}
      className="w-full h-full block rounded-xl shadow-2xl transition-all duration-300"
    />
  );
}

