    const interval = setInterval(() => {
      setTimelineIndex((prev) => {
        const nextIndex = (prev + 1) % DEMO_TIMELINE.length;
        const marker = DEMO_TIMELINE[nextIndex];

        if (marker.action.sceneKey) {
          onSelectScene(marker.action.sceneKey);
          EventBus.publish("SCENE_CHANGED", marker.action.sceneKey);
        }
        if (marker.action.themeKey) {
          onSelectTheme(marker.action.themeKey);
          EventBus.publish("THEME_CHANGED", marker.action.themeKey);
        }
        if (marker.action.pluginId) {
          PluginRegistry.activatePlugin(marker.action.pluginId);
          setActivePluginId(marker.action.pluginId);
          EventBus.publish("PLUGIN_CHANGED", marker.action.pluginId);
        }
        if (marker.action.particleCount) {
          onParticleCountChange(marker.action.particleCount);
        }

        EventBus.publish("TIMELINE_EVENT", marker.label);
        return nextIndex;
      });
    }, 8000);

    return () => clearInterval(interval);
  }, [isTimelineRunning, onSelectScene, onSelectTheme, onParticleCountChange]);

  const handleLoadPreset = (preset: SongPreset) => {
    onSelectScene(preset.sceneKey);
    onSelectTheme(preset.themeKey);
    PluginRegistry.activatePlugin(preset.pluginId);
    setActivePluginId(preset.pluginId);
    onParticleCountChange(preset.particleCount);

    EventBus.publish("SCENE_CHANGED", preset.sceneKey);
    EventBus.publish("THEME_CHANGED", preset.themeKey);
    EventBus.publish("PLUGIN_CHANGED", preset.pluginId);
  };

  return (
    <div className="bg-slate-900/90 border border-slate-800 text-slate-100 rounded-xl p-5 shadow-2xl backdrop-blur-xl space-y-6">
