export interface AudioFrameData {
  audioEnergy: number;
  timeSec: number;
}

export interface VisualizerPlugin {
  id: string;
  name: string;
  description: string;
  render(
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    audioData: AudioFrameData,
    scene: SceneProfile,
    theme: ThemeProfile
  ): void;
}

// Built-in Plugins
export const CircularSpectrumPlugin: VisualizerPlugin = {
  id: "circular-spectrum",
  name: "Circular Spectrum Ring ⭕",
  description: "Radial frequency bars and audio-reactive center ring.",
  render(ctx, width, height, audioData, scene, theme) {
    const cx = width / 2;
    const cy = height / 2;
    const timeSec = audioData.timeSec;
    const energy = audioData.audioEnergy;

    ctx.save();
    const radius = 90 + energy * 40;
    const barCount = 48;

    for (let i = 0; i < barCount; i++) {
      const angle = (i / barCount) * Math.PI * 2;
      const h = 10 + Math.abs(Math.sin(timeSec * 5 + i * 0.2)) * energy * 70;

      const x1 = cx + Math.cos(angle) * radius;
      const y1 = cy + Math.sin(angle) * radius;
      const x2 = cx + Math.cos(angle) * (radius + h);
      const y2 = cy + Math.sin(angle) * (radius + h);

      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.lineWidth = 4;
      ctx.strokeStyle = i % 2 === 0 ? theme.colors.primary : theme.colors.accent;
      ctx.stroke();
    }
    ctx.restore();
  },
};

export const ParticleGalaxyPlugin: VisualizerPlugin = {
  id: "particle-galaxy",
  name: "Particle Galaxy 🌌",
  description: "Orbiting spiral stellar particles responding to low-frequency energy.",
  render(ctx, width, height, audioData, scene, theme) {
    const cx = width / 2;
    const cy = height / 2;
    const timeSec = audioData.timeSec;
    const energy = audioData.audioEnergy;

    ctx.save();
    const count = 60;
    for (let i = 0; i < count; i++) {
      const dist = 40 + i * 4 + Math.sin(timeSec + i) * 15;
      const angle = timeSec * 0.8 + i * 0.15;
      const x = cx + Math.cos(angle) * dist;
      const y = cy + Math.sin(angle) * dist;

      ctx.beginPath();
      ctx.arc(x, y, 2 + Math.sin(i) * 2 + energy * 3, 0, Math.PI * 2);
      ctx.fillStyle = i % 3 === 0 ? theme.colors.primary : theme.colors.glow;
      ctx.fill();
    }
    ctx.restore();
  },
};

export const WaveGridPlugin: VisualizerPlugin = {
  id: "wave-grid",
  name: "Perspective Wave Grid 🌊",
  description: "Retro 3D grid perspective line wireframe.",
  render(ctx, width, height, audioData, scene, theme) {
    const cx = width / 2;
    const cy = height / 2;
    const timeSec = audioData.timeSec;
    const energy = audioData.audioEnergy;

    ctx.save();
    const lines = 12;
    const horizonY = cy + 40;

    ctx.strokeStyle = theme.colors.accent + "66";
    ctx.lineWidth = 1.5;

    // Perspective converging lines
    for (let i = -lines; i <= lines; i++) {
      ctx.beginPath();
      ctx.moveTo(cx + i * 12, horizonY);
      ctx.lineTo(cx + i * 60, height);
      ctx.stroke();
    }

    // Horizontal moving grid lines
    const gridOffset = (timeSec * 40) % 30;
    for (let y = horizonY; y < height; y += 15 + (y - horizonY) * 0.1) {
      ctx.beginPath();
      ctx.moveTo(0, y + gridOffset * 0.2);
      ctx.lineTo(width, y + gridOffset * 0.2);
      ctx.strokeStyle = theme.colors.primary + "44";
      ctx.stroke();
    }
    ctx.restore();
  },
};

// Plugin Registry
class PluginRegistryClass {
  private plugins: Map<string, VisualizerPlugin> = new Map();
  private activePluginId: string = "circular-spectrum";

  constructor() {
    this.registerPlugin(CircularSpectrumPlugin);
    this.registerPlugin(ParticleGalaxyPlugin);
    this.registerPlugin(WaveGridPlugin);
  }

  public registerPlugin(plugin: VisualizerPlugin) {
    this.plugins.set(plugin.id, plugin);
  }

  public activatePlugin(id: string) {
    if (this.plugins.has(id)) {
      this.activePluginId = id;
    }
  }

  public getActivePlugin(): VisualizerPlugin {
    return this.plugins.get(this.activePluginId) || CircularSpectrumPlugin;
  }

  public getPluginsList(): VisualizerPlugin[] {
    return Array.from(this.plugins.values());
  }
}

export const PluginRegistry = new PluginRegistryClass();

export type StudioEventType =
  | "THEME_CHANGED"
  | "SCENE_CHANGED"
  | "PLUGIN_CHANGED"
  | "TIMELINE_EVENT"
  | "CAMERA_CHANGED";

export interface StudioEvent {
  type: StudioEventType;
  payload: any;
  timestamp: number;
}

class StudioEventBus {
  private listeners: Map<StudioEventType, Array<(event: StudioEvent) => void>> = new Map();
  private eventLog: StudioEvent[] = [];

  public subscribe(type: StudioEventType, callback: (event: StudioEvent) => void): () => void {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, []);
    }
    this.listeners.get(type)!.push(callback);

    return () => {
      const list = this.listeners.get(type) || [];
      this.listeners.set(
        type,
        list.filter((cb) => cb !== callback)
      );
    };
  }

  public publish(type: StudioEventType, payload: any) {
    const event: StudioEvent = { type, payload, timestamp: Date.now() };
    this.eventLog.unshift(event);
    if (this.eventLog.length > 20) this.eventLog.pop();

    const list = this.listeners.get(type) || [];
    list.forEach((cb) => cb(event));
  }

  public getLog(): StudioEvent[] {
    return this.eventLog;
  }
}

export const EventBus = new StudioEventBus();

