import React, { useRef, useEffect } from "react";
import { Theme, ThemeColors, ThemeAnimation } from "../types/theme";
import { lerpThemeColors, lerpThemeAnimation } from "../utils/colorUtils";

interface CanvasVisualizerProps {
  theme: Theme;
  isPlaying: boolean;
  waveformSpacing: number; // 8-12px padding fix
}

export default function CanvasVisualizer({
  theme,
  isPlaying,
  waveformSpacing,
}: CanvasVisualizerProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // Smooth Theme Transition Refs
  const currentColorsRef = useRef<ThemeColors>(theme.colors);
  const currentAnimationRef = useRef<ThemeAnimation>(theme.animation);

  const prevThemeRef = useRef<Theme>(theme);
  const transitionStartRef = useRef<number>(0);
  const transitionDuration = 600; // 600ms smooth interpolation

  useEffect(() => {
    if (prevThemeRef.current.id !== theme.id) {
      transitionStartRef.current = performance.now();
    }
  }, [theme]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animId: number;
    let time = 0;

    // Layered Particles (Background Dust vs Stars vs Foreground)
    const particleCount = 60;
    const particles = Array.from({ length: particleCount }).map((_, idx) => ({
      x: Math.random(),
      y: Math.random(),
      layer: idx % 3, // 0 = background dust, 1 = mid star, 2 = foreground
      size: (idx % 3) * 1.2 + 0.8,
      speedY: (Math.random() * 0.0004 + 0.0001) * ((idx % 3) + 1),
      speedX: (Math.random() - 0.5) * 0.0002,
      alpha: Math.random() * 0.4 + 0.2,
    }));

    const render = (timestamp: number) => {
      time += 0.015;

      // 1. Theme Smooth Interpolation Calculation
      if (prevThemeRef.current.id !== theme.id) {
        const elapsed = timestamp - transitionStartRef.current;
        const progress = Math.min(1, Math.max(0, elapsed / transitionDuration));

        currentColorsRef.current = lerpThemeColors(
          prevThemeRef.current.colors,
          theme.colors,
          progress
        );
        currentAnimationRef.current = lerpThemeAnimation(
          prevThemeRef.current.animation,
          theme.animation,
          progress
        );

        if (progress >= 1) {
          prevThemeRef.current = theme;
        }
      } else {
        currentColorsRef.current = theme.colors;
        currentAnimationRef.current = theme.animation;
      }

      const activeColors = currentColorsRef.current;
      const activeAnim = currentAnimationRef.current;

      const width = (canvas.width = canvas.parentElement?.clientWidth || 800);
      const height = (canvas.height = canvas.parentElement?.clientHeight || 450);

      ctx.clearRect(0, 0, width, height);

      // 2. Audio-Reactive Energy Multiplier
      const lowFreqEnergy = isPlaying ? Math.sin(time * 3) * 0.15 + 0.85 : 0.3;

      // 3. Ambient Radial Lighting (Audio-Reactive)
      const grad = ctx.createRadialGradient(
        width / 2,
        height / 2 - 20,
        15 * lowFreqEnergy,
        width / 2,
        height / 2,
        width * 0.65
      );
      grad.addColorStop(0, activeColors.glow);
      grad.addColorStop(1, "rgba(0, 0, 0, 0.96)");
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);

      // 4. Layered Motion Particles
      particles.forEach((p) => {
        if (isPlaying) {
          p.y -= p.speedY * activeAnim.particleIntensity * 1.5;
          p.x += p.speedX;
        } else {
          p.y -= p.speedY * 0.3;
        }

        if (p.y < 0) p.y = 1;
        if (p.x < 0) p.x = 1;
        if (p.x > 1) p.x = 0;

        ctx.beginPath();
        ctx.arc(p.x * width, p.y * height, p.size, 0, Math.PI * 2);
        ctx.fillStyle = activeColors.particles;
        ctx.globalAlpha = p.alpha * (p.layer === 0 ? 0.4 : 0.8);
        ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 5. Breathing Logo with Audio-Reactive Energy
      const logoBreath = activeAnim.logoBreathSpeed
        ? Math.sin(time * activeAnim.logoBreathSpeed) * 0.035 + 1.0 + (isPlaying ? (lowFreqEnergy - 0.85) * 0.08 : 0)
        : 1.0;

      ctx.save();
      ctx.translate(width / 2, height / 2 - 30);
      ctx.scale(logoBreath, logoBreath);

      // Audio Reactive Outer Ring Glow
      ctx.beginPath();
      ctx.arc(0, 0, 65, 0, Math.PI * 2);
      ctx.shadowColor = activeColors.primary;
      ctx.shadowBlur = isPlaying ? 22 * lowFreqEnergy : 10;
      ctx.strokeStyle = activeColors.primary;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Inner emblem
      ctx.shadowBlur = 0;
      ctx.fillStyle = activeColors.text.primary;
      ctx.font = "600 13px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("ELYZARETH", 0, -8);

      ctx.fillStyle = activeColors.text.secondary;
      ctx.font = "400 10px system-ui, sans-serif";
      ctx.fillText("STUDIO OS v2.0", 0, 10);
      ctx.restore();

      // 6. Waveform Rendering with Spacing Offset Fix
      const waveformBottomMargin = 20 + waveformSpacing;
      const waveY = height - waveformBottomMargin - 30;

      ctx.save();
      ctx.shadowColor = activeColors.waveform.glow;
      ctx.shadowBlur = activeAnim.waveformGlow * (isPlaying ? lowFreqEnergy : 0.5);

      ctx.beginPath();
      const points = 64;
      const sliceWidth = width / points;

      for (let i = 0; i <= points; i++) {
        const x = i * sliceWidth;
        const norm = i / points;
        const freqMult = isPlaying ? Math.sin(time * 3.5 + norm * Math.PI * 4) : 0.1;
        const offset = Math.sin(time * 2.2 + norm * 8) * (isPlaying ? 20 : 3) * freqMult * lowFreqEnergy;
        const y = waveY + offset;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }

      ctx.strokeStyle = activeColors.waveform.stroke;
      ctx.lineWidth = 2.5;
      ctx.stroke();

      ctx.lineTo(width, height - waveformBottomMargin);
      ctx.lineTo(0, height - waveformBottomMargin);
      ctx.closePath();
      ctx.fillStyle = activeColors.waveform.fill;
      ctx.fill();

      ctx.restore();

      animId = requestAnimationFrame(render);
    };

    animId = requestAnimationFrame(render);

    return () => cancelAnimationFrame(animId);
  }, [theme, isPlaying, waveformSpacing]);

  return <canvas ref={canvasRef} className="w-full h-full block" />;
}

