import { ThemeColors, ThemeAnimation } from "../types/theme";

// Helper to parse Hex, RGB, or RGBA into [r, g, b, a]
export function parseColor(colorStr: string): [number, number, number, number] {
  if (colorStr.startsWith("#")) {
    let hex = colorStr.slice(1);
    if (hex.length === 3) {
      hex = hex.split("").map((c) => c + c).join("");
    }
    const num = parseInt(hex, 16);
    return [(num >> 16) & 255, (num >> 8) & 255, num & 255, 1];
  }

  if (colorStr.startsWith("rgb")) {
    const parts = colorStr.match(/[\d.]+/g);
    if (parts) {
      return [
        parseFloat(parts[0]),
        parseFloat(parts[1]),
        parseFloat(parts[2]),
        parts[3] !== undefined ? parseFloat(parts[3]) : 1,
      ];
    }
  }

  return [255, 255, 255, 1];
}

// Lerp single value
export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

// Lerp color string
export function lerpColor(c1: string, c2: string, t: number): string {
  const [r1, g1, b1, a1] = parseColor(c1);
  const [r2, g2, b2, a2] = parseColor(c2);

  const r = Math.round(lerp(r1, r2, t));
  const g = Math.round(lerp(g1, g2, t));
  const b = Math.round(lerp(b1, b2, t));
  const a = lerp(a1, a2, t);

  return `rgba(${r}, ${g}, ${b}, ${a.toFixed(3)})`;
}

// Lerp complete ThemeColors structure
export function lerpThemeColors(from: ThemeColors, to: ThemeColors, t: number): ThemeColors {
  return {
    primary: lerpColor(from.primary, to.primary, t),
    secondary: lerpColor(from.secondary, to.secondary, t),
    accent: lerpColor(from.accent, to.accent, t),
    text: {
      primary: lerpColor(from.text.primary, to.text.primary, t),
      secondary: lerpColor(from.text.secondary, to.text.secondary, t),
      muted: lerpColor(from.text.muted, to.text.muted, t),
    },
    panel: {
      bg: lerpColor(from.panel.bg, to.panel.bg, t),
      border: lerpColor(from.panel.border, to.panel.border, t),
      tint: lerpColor(from.panel.tint, to.panel.tint, t),
    },
    waveform: {
      fill: lerpColor(from.waveform.fill, to.waveform.fill, t),
      stroke: lerpColor(from.waveform.stroke, to.waveform.stroke, t),
      glow: lerpColor(from.waveform.glow, to.waveform.glow, t),
    },
    particles: lerpColor(from.particles, to.particles, t),
    glow: lerpColor(from.glow, to.glow, t),
  };
}

export function lerpThemeAnimation(
  from: ThemeAnimation,
  to: ThemeAnimation,
  t: number
): ThemeAnimation {
  return {
    logoBreathSpeed: lerp(from.logoBreathSpeed, to.logoBreathSpeed, t),
    particleIntensity: lerp(from.particleIntensity, to.particleIntensity, t),
    waveformGlow: lerp(from.waveformGlow, to.waveformGlow, t),
    footerOpacity: lerp(from.footerOpacity, to.footerOpacity, t),
  };
}

