  const audioRef = useRef<HTMLAudioElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const bgFileInputRef = useRef<HTMLInputElement | null>(null);
  const thumbFileInputRef = useRef<HTMLInputElement | null>(null);
  const bgImgElementRef = useRef<HTMLImageElement | null>(null);
  const thumbImgElementRef = useRef<HTMLImageElement | null>(null);
  const visualizerContainerRef = useRef<HTMLDivElement | null>(null);
  const animationRef = useRef<number | null>(null);

  // Force pure 2D Canvas rendering loop for maximum rendering reliability
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) {
      console.error("2D Context not available");
      return;
    }

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;

      // Let canvas perfectly match parent container managed via CSS Tailwind aspect ratios
      canvas.width = parent.clientWidth;
      canvas.height = parent.clientHeight;
    };
    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);

    let frameCount = 0;

    const draw = () => {
      if (!canvas || !ctx) return;
      const width = canvas.width;
      const height = canvas.height;

      // Highly aesthetic procedural retro wave simulation that dances to the beat!
      // This completely bypasses browser CORS locks and Web Audio API play-block freezes.
      const rawData = new Uint8Array(128);
      for (let i = 0; i < 128; i++) {
        if (isPlaying) {
          const baseFreq = frameCount * 0.08;
          const bass = Math.abs(Math.sin(baseFreq + i * 0.12)) * 130;
          const mid = Math.abs(Math.cos(baseFreq * 1.5 + i * 0.22)) * 80;
          const treble = Math.sin(baseFreq * 3.0 + i * 0.45) * 35;
          const textFont = Math.random() * 20;

          // Modulate height slightly over time to simulate a real changing music structure
          const waveHeightModifier = 0.7 + Math.sin(frameCount * 0.01) * 0.3;
          rawData[i] = Math.min(255, Math.max(0, (bass + mid + treble + textFont) * waveHeightModifier));
        } else {
          // Slow ambient floating idle wave when paused
          rawData[i] = 12 + Math.sin(frameCount * 0.03 + i * 0.08) * 6;
        }
      }

      frameCount++;

      // Inertia-based rotation calculations (Clockwise continuous rotation with RPM)
      const rpmMap: Record<string, number> = { slow: 3, normal: 8, fast: 16, turbo: 24 };
      const currentRpm = rpmMap[vinylRpmSetting] || 8;
      const targetSpeed = isPlaying ? (currentRpm * Math.PI * 2) / 3600 : 0;
      // Interpolate speed for natural deceleration / momentum when stopping
      currentSpeedRef.current += (targetSpeed - currentSpeedRef.current) * 0.04;
      vinylAngleRef.current += currentSpeedRef.current;

      // Theme Colors Mapping (5 Curated Elyzareth OS Skins)
      let pColor = "#06b6d4"; // Cyan
      let sColor = "#ec4899"; // Pink
      let bColor = "#020617"; // Dark background

      if (themeColor === "gold") {
        pColor = "#fbbf24"; // Imperial Amber Gold
        sColor = "#f97316"; // Bright Orange Accent
        bColor = "#0c0a09"; // Warm Stone Black
      } else if (themeColor === "emerald") {
        pColor = "#10b981"; // Matrix Emerald Green
        sColor = "#06b6d4"; // Cyber Teal Accent
        bColor = "#020c08"; // Deep Forest Void
      } else if (themeColor === "ruby") {
        pColor = "#ef4444"; // Crimson Sunset Red
        sColor = "#f59e0b"; // Solar Yellow Accent
        bColor = "#120202"; // Deep Wine Black
      } else if (themeColor === "amethyst") {
        pColor = "#a855f7"; // Cosmic Amethyst Purple
        sColor = "#3b82f6"; // Stellar Sapphire Blue Accent
        bColor = "#090514"; // Deep Royal Violet Void
      }

      // Draw dark background behind the physical TV frame
      ctx.fillStyle = bColor;
      ctx.fillRect(0, 0, width, height);

      // --- CINEMATIC CAMERA DIRECTOR (Layered Motion Engine) ---
      let camOffsetX = 0;
      let camOffsetY = 0;
      let camScale = 1;

      if (cameraMode === "drift") {
        camOffsetX = Math.sin(frameCount * 0.008) * 8;
        camOffsetY = Math.cos(frameCount * 0.006) * 5;
      } else if (cameraMode === "floating") {
        camOffsetX = Math.sin(frameCount * 0.012) * 12;
        camOffsetY = Math.sin(frameCount * 0.015) * 10;
      } else if (cameraMode === "pushin") {
        camScale = 1 + (Math.sin(frameCount * 0.005) + 1) * 0.015;
      } else if (cameraMode === "breathing") {
        camScale = 1 + Math.sin(frameCount * 0.02) * 0.01;
      }

      ctx.save();
      ctx.translate(width / 2 + camOffsetX, height / 2 + camOffsetY);
      ctx.scale(camScale, camScale);
      ctx.translate(-width / 2, -height / 2);

      // --- SKEUOMORPHIC CURVED TV GEOMETRY ---
      const padLeft = width * 0.04;
      const padRight = width * 0.04;
      const padTop = height * 0.05;
      const padBottom = height * 0.16; // Leaves perfect breathing room for stand base
      const curveAmt = height * 0.026; // Slanted curve representing physical curved TV depth

      // 1. Draw 3D Brushed Metal TV Stand Column/Neck (Behind Bezel)
      const neckWidth = Math.max(16, width * 0.025);
      const neckX = width / 2;
      const neckY = height - padBottom + curveAmt;
      const baseY = height - 16; // Base stand Y center
      const neckH = baseY - neckY + 4; // Extends into base joint

      const neckGrad = ctx.createLinearGradient(neckX - neckWidth / 2, 0, neckX + neckWidth / 2, 0);
      neckGrad.addColorStop(0, "#1e293b");
      neckGrad.addColorStop(0.25, "#475569");
      neckGrad.addColorStop(0.5, "#f1f5f9");
      neckGrad.addColorStop(0.75, "#475569");
      neckGrad.addColorStop(1, "#1e293b");

      ctx.fillStyle = neckGrad;
      ctx.fillRect(neckX - neckWidth / 2, neckY, neckWidth, neckH);

      // 2. Draw Samsung-Style Curved Metallic Arc Stand Leg (Matching Reference Photo)
      const standW = Math.max(200, width * 0.58); // Wide sweeping curved metallic arch bar
      const barThick = Math.max(6, height * 0.012); // Thickness of metallic bar
      const arcDip = Math.max(8, height * 0.018);   // Forward curve dip

      // Dark contact shadow under the curved leg on the surface
      ctx.fillStyle = "rgba(0, 0, 0, 0.6)";
      ctx.beginPath();
      ctx.ellipse(neckX, baseY + arcDip + 3, standW / 2 + 8, barThick + 2, 0, 0, Math.PI * 2);
      ctx.fill();

      // Metallic Brushed Steel Gradient across wide curved arc leg
      const legGrad = ctx.createLinearGradient(neckX - standW / 2, 0, neckX + standW / 2, 0);
      legGrad.addColorStop(0, "#0f172a");
      legGrad.addColorStop(0.15, "#334155");
      legGrad.addColorStop(0.35, "#64748b");
      legGrad.addColorStop(0.5, "#f1f5f9"); // Bright central metallic reflection
      legGrad.addColorStop(0.65, "#64748b");
      legGrad.addColorStop(0.85, "#334155");
      legGrad.addColorStop(1, "#0f172a");

      ctx.fillStyle = legGrad;
      ctx.strokeStyle = "#94a3b8";
      ctx.lineWidth = 1;

      // Draw sweeping curved metallic leg bar
      ctx.beginPath();
      ctx.moveTo(neckX - standW / 2, baseY);
      ctx.quadraticCurveTo(neckX, baseY + arcDip, neckX + standW / 2, baseY);
      ctx.lineTo(neckX + standW / 2 - 3, baseY + barThick);
      ctx.quadraticCurveTo(neckX, baseY + arcDip + barThick + 2, neckX - standW / 2 + 3, baseY + barThick);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      // Metallic top rim highlight line
      ctx.strokeStyle = "#ffffffa0";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(neckX - standW / 2 + 6, baseY);
      ctx.quadraticCurveTo(neckX, baseY + arcDip, neckX + standW / 2 - 6, baseY);
      ctx.stroke();

      // 3. Center mounting joint collar block
      const jointW = neckWidth * 1.5;
      const jointH = 6;
      ctx.fillStyle = "#1e293b";
      ctx.strokeStyle = "#64748b";
      ctx.lineWidth = 1;
      ctx.fillRect(neckX - jointW / 2, baseY - 2, jointW, jointH);
      ctx.strokeRect(neckX - jointW / 2, baseY - 2, jointW, jointH);

      // 3. Save Context & Create Clip Mask for the Curved TV Screen
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(padLeft, padTop + curveAmt);
      ctx.quadraticCurveTo(width / 2, padTop, width - padRight, padTop + curveAmt);
      ctx.lineTo(width - padRight, height - padBottom + curveAmt);
      ctx.quadraticCurveTo(width / 2, height - padBottom, padLeft, height - padBottom + curveAmt);
      ctx.closePath();
      ctx.clip(); // Confines all following renders (wallpaper, grids, vinyl, text) inside the TV screen!

      // --- ALL CONTENT RENDERING INSIDE TV SCREEN ---

      // Draw dark screen base inside TV
      ctx.fillStyle = "#02040a";
      ctx.fillRect(0, 0, width, height);

      // Sunset sun circle center coordinates (moveable!)
      const sunX = (isWideLayout ? width * 0.72 : width / 2) + sunXOffset;
      const sunY = (height * 0.43) + sunYOffset;
      const sunRadius = isWideLayout ? Math.min(width, height) * 0.26 : Math.min(width, height) * 0.23;

      // Draw custom background wallpaper if loaded, or ambient radial fallback glow
      if (bgImgElementRef.current) {
        ctx.save();
        ctx.globalAlpha = bgWallpaperOpacity;

        // Draw image with "cover" aspect ratio fit
        const img = bgImgElementRef.current;
        const imgRatio = img.width / img.height;
        const canvasRatio = width / height;
        let drawW = width;
        let drawH = height;
        let drawX = 0;
        let drawY = 0;

        if (canvasRatio > imgRatio) {
          drawH = width / imgRatio;
          drawY = (height - drawH) / 2;
        } else {
          drawW = height * imgRatio;
          drawX = (width - drawW) / 2;
        }

        ctx.drawImage(img, drawX + bgXOffset, drawY + bgYOffset, drawW, drawH);
        ctx.restore();
      } else {
        // Subtle ambient radial background glow when no custom wallpaper is loaded
        ctx.save();
        const bgGrad = ctx.createRadialGradient(
          sunX, sunY, 10,
          sunX, sunY, Math.max(width, height) * 0.75
        );
        bgGrad.addColorStop(0, pColor + "22");
        bgGrad.addColorStop(0.5, sColor + "0e");
        bgGrad.addColorStop(1, "#02040a");
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);
        ctx.restore();
      }

      // --- Helper: Draw 3D Rotating Cylinder Drum Text on Right Side ---
      const draw3DCylinderText = () => {
        ctx.save();
        ctx.translate(sunX, sunY);

        const orbits = [0, Math.PI]; // 2 orbits for continuous 3D carousel

        ctx.font = `bold ${textSize}px ${textFont}`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";

        const getActiveTrackName = () => {
          const customTracks = tracklistText.split("\n").filter(line => line.trim() !== "");
          const trackLines = customTracks.length > 0 ? customTracks : defaultTracks;
          const rawTrack = trackLines[currentTrackIndex] || songTitle;
          return rawTrack.replace(/^\d+[\s.-]*/, "").trim();
        };

        const rings = [
          { yOffset: -20, color: albumColor, text: albumTitle, isStatic: true }, // Top Ring: Album Name
          { yOffset: 20, color: songColor, text: getActiveTrackName(), isStatic: false }    // Bottom Ring: Active Track
        ];

        // --- DRAW GLOWING 3D ROTATING CYLINDER DRUM BOARD ---
        ctx.save();
        const orbitRadius = sunRadius * 1.18; // Expanded width so characters wrap cleanly without clipping!
        const boardHeight = 58; // Comfortably framed board height
        const boardCurve = 8;

        // 1. Solid translucent glass backplate with subtle glow
        ctx.fillStyle = "rgba(10, 15, 32, 0.85)";
        ctx.shadowColor = pColor;
        ctx.shadowBlur = 14;
        ctx.beginPath();
        ctx.ellipse(0, -boardHeight, orbitRadius, boardCurve, 0, 0, Math.PI);
        ctx.lineTo(orbitRadius, boardHeight);
        ctx.ellipse(0, boardHeight, orbitRadius, boardCurve, 0, Math.PI, 0, true);
        ctx.lineTo(-orbitRadius, -boardHeight);
        ctx.fill();

        // 2. Top and bottom glowing rims
        ctx.strokeStyle = albumColor + "66";
        ctx.shadowColor = albumColor;
        ctx.shadowBlur = 12;
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.ellipse(0, -boardHeight, orbitRadius, boardCurve, 0, 0, Math.PI);
        ctx.stroke();

        ctx.strokeStyle = songColor + "66";
        ctx.shadowColor = songColor;
        ctx.beginPath();
        ctx.ellipse(0, boardHeight, orbitRadius, boardCurve, 0, 0, Math.PI);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // 3. Vertical rotating metal slats
        const slatsCount = 10;
        const baseSlatAngle = frameCount * (titleSpinSpeed * 0.012);
        ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
        ctx.lineWidth = 1;

        for (let s = 0; s < slatsCount; s++) {
          const angle = baseSlatAngle + (s / slatsCount) * Math.PI * 2;
          const x = orbitRadius * Math.sin(angle);
          const z = Math.cos(angle);

          if (z > 0) {
            ctx.save();
            ctx.strokeStyle = songColor + "22";
            ctx.shadowColor = songColor;
            ctx.shadowBlur = 4;
            ctx.beginPath();
            ctx.moveTo(x, -boardHeight + boardCurve * Math.sin(angle - Math.PI / 2));
            ctx.lineTo(x, boardHeight + boardCurve * Math.sin(angle - Math.PI / 2));
            ctx.stroke();
            ctx.restore();
          }
        }
        ctx.restore();

        rings.forEach(ring => {
          ctx.fillStyle = ring.color;
          ctx.shadowColor = ring.color;
          ctx.shadowBlur = 14;

          const chars = ring.text.toUpperCase().split("");
          // Adjust character spacing dynamically to prevent edge clipping
          const charSpacingAngle = Math.min(0.14, (Math.PI * 0.85) / Math.max(1, chars.length));

          for (const orbitOffset of orbits) {
            const baseAngle = ring.isStatic ? 0 + orbitOffset : (frameCount * (titleSpinSpeed * 0.012)) + orbitOffset;

            chars.forEach((char, charIdx) => {
              const charAngle = baseAngle + (charIdx - (chars.length - 1) / 2) * charSpacingAngle;
              const x = orbitRadius * 0.9 * Math.sin(charAngle);
              const z = Math.cos(charAngle);

              if (z > 0.08) {
                ctx.save();
                ctx.translate(x, ring.yOffset);
                ctx.scale(Math.abs(z), 1);
                ctx.globalAlpha = Math.min(1, z * 1.6);
                ctx.fillText(char, 0, 0);
                ctx.restore();
              }
            });
          }
        });

        ctx.restore();
      };

      // --- 1. BAR EQUALIZERS & RETRO BARS ---
      if (selectedStyle === "retro_bars") {
        const barWidth = (width / 40);
        ctx.fillStyle = pColor;
        for (let i = 0; i < 40; i++) {
          const rawVal = rawData[i % 128];
          const barHeight = (rawVal / 255) * (height * 0.7);
          const x = i * barWidth;
          const y = height - barHeight - 20;

          ctx.shadowBlur = 15;
          ctx.shadowColor = pColor;
          ctx.fillRect(x + 2, y, barWidth - 4, barHeight);
        }
        draw3DCylinderText();
      }
      // --- 2. CIRCULAR SPECTRUM / HALO / TUNNEL PORTALS ---
      else if (selectedStyle === "circular_spectrum" || selectedStyle === "cosmic_dust") {
        const centerX = (isWideLayout ? width * 0.72 : width / 2) + sunXOffset;
        const centerY = (height / 2) + sunYOffset;
        const baseRadius = isWideLayout ? Math.min(width, height) * 0.28 : Math.min(width, height) * 0.25;

        ctx.shadowBlur = 20;
        ctx.shadowColor = pColor;

        ctx.beginPath();
        for (let i = 0; i < 128; i++) {
          const angle = (i / 128) * Math.PI * 2;
          const amp = rawData[i] / 255;
          const r = baseRadius + amp * (baseRadius * 0.8);
          const x = centerX + Math.cos(angle) * r;
          const y = centerY + Math.sin(angle) * r;

          if (i === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
