      else if (selectedStyle === "liquid_chrome") {
        ctx.shadowBlur = 22; // Soft outer glow
        ctx.shadowColor = pColor;

        // Position wave baseline right above the bottom playlist container
        const waveBaseY = height * 0.72; 
        const maxWaveHeight = height * waveHeight;

        // Beat-synchronized pulse effect
        const pulse = isPlaying ? 1 + Math.sin(frameCount * 0.12) * 0.08 : 1;

        ctx.beginPath();
        ctx.moveTo(0, waveBaseY);
        for (let i = 0; i < width; i++) {
          const idx = Math.floor((i / width) * 128);
          const amp = rawData[idx] / 255;
          const offset = Math.sin(i * 0.03 + frameCount * 0.08) * amp * maxWaveHeight * pulse;
          ctx.lineTo(i, waveBaseY - offset);
