        ctx.strokeStyle = pColor + "dd"; // Slightly softened brightness
        ctx.lineWidth = 4.0;
        ctx.stroke();

        // Secondary subtle glowing reflection wave
        ctx.beginPath();
        ctx.moveTo(0, waveBaseY);
        for (let i = 0; i < width; i++) {
          const idx = Math.floor((i / width) * 128);
          const amp = rawData[idx] / 255;
          const offset = Math.cos(i * 0.02 + frameCount * 0.06) * amp * (maxWaveHeight * 0.5) * pulse;
          ctx.lineTo(i, waveBaseY - offset);
