        ctx.moveTo(0, horizonY);
        ctx.lineTo(width, horizonY);
        ctx.strokeStyle = pColor;
        ctx.lineWidth = 3;
        ctx.stroke();

        // Animated Perspective Grid Lines
        ctx.shadowBlur = 0;
        ctx.strokeStyle = pColor + "66";
        ctx.lineWidth = 1.5;
        const gridLinesCount = 18;
        for (let i = 0; i <= gridLinesCount; i++) {
