        const startY = height * 0.77; 
        const rowSpacing = Math.max(8, (height - startY - 8) / 10);
        for (let i = 0; i < 10; i++) {
          const lineY = startY + i * rowSpacing + 5;
          if (lineY <= height) {
            ctx.beginPath();
            ctx.moveTo(0, lineY);
            ctx.lineTo(width, lineY);
            ctx.stroke();
          }
