      }

      // --- 5. DRAW ALBUM PLAYLIST TRACKLIST & RICH BOTTOM STATS PANEL ---
      const customTracks = tracklistText.split("\n").filter(line => line.trim() !== "");
      const trackLines = customTracks.length > 0 ? customTracks : defaultTracks;

      if (trackLines.length > 0) {
        ctx.save();

        const startY = height * 0.73; 
        const containerH = height - startY - 12;
        const col1X = width * 0.08;
        const col2X = width * 0.52;
