        // Subtly tinted vertical gradient (95% dark bottom -> ambient gold tint top)
        const panelGrad = ctx.createLinearGradient(0, startY - 4, 0, startY + containerH);
        panelGrad.addColorStop(0, "rgba(22, 18, 10, 0.75)"); // Warm ambient top tint
