          const relativeIndex = isCol1 ? i : i - 5;
          const y = startY + 16 + relativeIndex * rowSpacing;

          const isActive = i === currentTrackIndex;
          const cleanTrackName = trackLines[i].replace(/^\d+[\s.-]*/, "").trim();
          const trackNum = (i + 1) < 10 ? `0${i + 1}` : `${i + 1}`;

          if (isActive) {
            ctx.font = "bold 15px monospace";
            ctx.fillStyle = "#ffffff";
            ctx.shadowColor = songColor;
            ctx.shadowBlur = 14;
            ctx.fillText(`▶ ${cleanTrackName.toUpperCase()}`, x - 10, y);

            // Active track duration
            ctx.font = "11px monospace";
            ctx.fillStyle = songColor;
            ctx.fillText(`${formatTime(currentTime)} / ${formatTime(duration || 225)}`, x + width * 0.32, y);
          } else {
            ctx.font = "12px monospace";
            ctx.fillStyle = "rgba(255, 255, 255, 0.78)";
            ctx.shadowBlur = 0;
            ctx.fillText(`${trackNum}   ${cleanTrackName}`, x, y);
          }
        }

        // Rich Bottom Stats & Metadata Banner
        const statsY = startY + containerH - 10;
        ctx.font = "bold 10px monospace";
        ctx.fillStyle = songColor;
        ctx.shadowColor = songColor;
        ctx.shadowBlur = 8;
        const formattedCurrent = formatTime(currentTime);
        const formattedTotal = formatTime(duration);
        ctx.fillText(`⏱ ${formattedCurrent} / ${formattedTotal}   •   120 BPM   •   SYNTHWAVE / ROMANCE   •   ELYZARETH OS V1.5`, width * 0.08, statsY);

        ctx.restore();
      }

      // --- FLOATING AMBIENT PARTICLES & MUSIC NOTES (Frequency-Reactive) ---
      ctx.save();
      particlesRef.current.forEach((p, idx) => {
        // Frequency band sensitivity (bass for large notes, treble for sparkles)
        const freqAmp = isPlaying ? rawData[idx % 128] / 255 : 0.2;
        const reactiveSize = p.size * (1 + freqAmp * 0.4);

        p.y -= p.speedY * (isPlaying ? 1 + freqAmp * 1.5 : 0.5);
        if (p.y < 0) {
          p.y = 1;
          p.x = Math.random();
        }
        ctx.font = `${reactiveSize}px sans-serif`;
        ctx.globalAlpha = p.opacity * (isPlaying ? 0.4 + freqAmp * 0.6 : 0.35);
        ctx.fillStyle = songColor;
        ctx.shadowColor = songColor;
        ctx.shadowBlur = 10;
        ctx.fillText(p.char, p.x * width, p.y * height);
      });
      ctx.restore();

      // --- 6. DRAW COVER ART THUMBNAIL (LEFT SIDE IN WIDE 16:9 MODE) (moveable!) ---
      if (isWideLayout) {
        const baseThumbSize = Math.min(width, height) * 0.44; // Resized slightly to prevent TV bezel clipping
        const thumbSize = baseThumbSize * thumbScale;
        const thumbX = (thumbSize / 2 + 30) + thumbXOffset; // Pushed rightward for padding breathing room
        const thumbY = (height * 0.43) + thumbYOffset;

        ctx.save();

        // 1. Draw Cassette/Acrylic 3D Turnplate Deck frame
        ctx.fillStyle = "rgba(10, 15, 30, 0.85)";
        ctx.strokeStyle = pColor + "aa";
        ctx.lineWidth = 3.5;
        ctx.shadowColor = pColor;
        ctx.shadowBlur = 20;
        ctx.beginPath();
        if (typeof (ctx as any).roundRect === "function") {
          (ctx as any).roundRect(thumbX - thumbSize / 2, thumbY - thumbSize / 2, thumbSize, thumbSize, 18);
        } else {
          ctx.rect(thumbX - thumbSize / 2, thumbY - thumbSize / 2, thumbSize, thumbSize);
        }
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0; // reset shadow

        // 2. Tech Deck corner LEDs & screw detailing (3D look)
        const pad = 12;
        const corners = [
          { x: thumbX - thumbSize/2 + pad, y: thumbY - thumbSize/2 + pad },
          { x: thumbX + thumbSize/2 - pad, y: thumbY - thumbSize/2 + pad },
          { x: thumbX - thumbSize/2 + pad, y: thumbY + thumbSize/2 - pad },
          { x: thumbX + thumbSize/2 - pad, y: thumbY + thumbSize/2 - pad },
        ];
        corners.forEach((c, idx) => {
          ctx.fillStyle = idx === 0 && isPlaying ? "#22c55e" : pColor; // top left blinker
          ctx.beginPath();
          ctx.arc(c.x, c.y, 4, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = "#ffffff55";
          ctx.lineWidth = 1;
          ctx.stroke();
        });

        // 3. Rotating DVD / Vinyl Disc rendering
        const diskRadius = thumbSize * 0.43;

        ctx.save();
        ctx.translate(thumbX, thumbY);
        ctx.rotate(vinylAngleRef.current);

        // Outer Vinyl Disk body
        ctx.shadowColor = "#000000";
        ctx.shadowBlur = 12;
        ctx.fillStyle = "#070b19"; // dark gloss record base
        ctx.beginPath();
        ctx.arc(0, 0, diskRadius, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Concentric Vinyl reflection grooves
        ctx.strokeStyle = "#ffffff11";
        ctx.lineWidth = 0.5;
        for (let r = diskRadius - 6; r > diskRadius * 0.45; r -= 5) {
          ctx.beginPath();
          ctx.arc(0, 0, r, 0, Math.PI * 2);
          ctx.stroke();
        }

        // Realistic CD/DVD metallic light sheen beams
        ctx.fillStyle = "rgba(255, 255, 255, 0.04)";
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.arc(0, 0, diskRadius, -0.4, 0.4);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.arc(0, 0, diskRadius, Math.PI - 0.4, Math.PI + 0.4);
        ctx.fill();

        // Outer layer ring: Rotating Album / Song text label
        ctx.save();
        ctx.font = "bold 7px monospace";
        ctx.fillStyle = pColor;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        const labelRadius = diskRadius * 0.64;
        const textToDraw = ` * ELYZARETH * ${songTitle.toUpperCase().slice(0, 24)} * `;
        const textChars = textToDraw.split("");
        const angleStep = (Math.PI * 2) / textChars.length;

        textChars.forEach((char, idx) => {
          const charAngle = idx * angleStep;
          ctx.save();
          ctx.rotate(charAngle);
          ctx.fillText(char, 0, -labelRadius);
          ctx.restore();
        });
