          ctx.drawImage(
            thumbImgElementRef.current,
            -coreRadius,
            -coreRadius,
            coreRadius * 2,
            coreRadius * 2
          );
        } else {
          // Stylish default Elyzareth record core label
          ctx.fillStyle = "#0c1022";
          ctx.beginPath();
          ctx.arc(0, 0, coreRadius, 0, Math.PI * 2);
          ctx.fill();

          ctx.strokeStyle = pColor;
          ctx.lineWidth = 1.5;
          ctx.shadowColor = pColor;
          ctx.shadowBlur = 8;
          ctx.beginPath();
          ctx.arc(0, 0, coreRadius * 0.82, 0, Math.PI * 2);
          ctx.stroke();

          ctx.font = "bold 10px serif";
          ctx.fillStyle = songColor;
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
