        ctx.fillStyle = "#020617";
        ctx.strokeStyle = "#ffffffaa";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        ctx.restore(); // restore translation & rotation

        // 4. Tone-Arm stylus (Pink & Fixed touching the record outer ring)
        const armStartX = thumbX + thumbSize / 2 - 12;
        const armStartY = thumbY - thumbSize / 2 + 12;

        const needleAngle = -0.45; 
        const needleX = thumbX + Math.cos(needleAngle) * (diskRadius * 0.85);
        const needleY = thumbY + Math.sin(needleAngle) * (diskRadius * 0.85);

        const armMidX = thumbX + thumbSize / 2 - 28;
        const armMidY = thumbY - 18;

        ctx.strokeStyle = "#ec4899";
        ctx.lineWidth = 3;
        ctx.shadowColor = "#ec4899";
        ctx.shadowBlur = 10;

        ctx.fillStyle = "#ec4899";
        ctx.beginPath();
        ctx.arc(armStartX, armStartY, 6, 0, Math.PI * 2);
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(armStartX, armStartY);
        ctx.lineTo(armMidX, armMidY);
        ctx.lineTo(needleX, needleY);
        ctx.stroke();

        ctx.fillStyle = "#ff49db";
        ctx.strokeStyle = "#ffffff";
        ctx.lineWidth = 1.5;
        ctx.shadowColor = "#ff49db";
        ctx.shadowBlur = 15;
        ctx.beginPath();
        ctx.arc(needleX, needleY, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        ctx.shadowBlur = 0;

        ctx.restore();
      }

      // --- 7. CLOSE TV SCREEN CLIP MASK ---
      ctx.restore();

      // --- 8. DRAW SKEUOMORPHIC CURVED TV OUTER BEZEL FRAME (On Top of Clipped Content) ---
      const bezelGrad = ctx.createLinearGradient(padLeft, padTop, width - padRight, padTop);
      bezelGrad.addColorStop(0, "#1e293b");
      bezelGrad.addColorStop(0.3, "#475569");
      bezelGrad.addColorStop(0.5, "#94a3b8");
      bezelGrad.addColorStop(0.7, "#475569");
      bezelGrad.addColorStop(1, "#1e293b");

