  }, [themeColor, selectedStyle, visualizerSpeed, isPlaying, captionText, bgImageUrl, bgWallpaperOpacity, bgXOffset, bgYOffset, aspectRatio, thumbImageUrl, textFont, textSize, sunXOffset, sunYOffset, thumbXOffset, thumbYOffset, tracklistText, thumbScale, albumTitle, vinylRpmSetting, currentTrackIndex, albumColor, songColor, waveHeight]);

