        await audioCtxRef.current.resume();
      }
    } catch (e) {
      console.warn("Failed to resume AudioContext:", e);
    }

    if (audioRef.current.paused) {
      audioRef.current.play().then(() => {
        setIsPlaying(true);
      }).catch(err => {
        console.error("Audio play failed:", err);
      });
    } else {
      audioRef.current.pause();
      setIsPlaying(false);
    }
  };

  const handleStop = () => {
    if (!audioRef.current) return;
    audioRef.current.pause();
    audioRef.current.currentTime = 0;
    setIsPlaying(false);
    setCurrentTime(0);
  };

  const handleTimeUpdate = () => {
    if (!audioRef.current) return;
    setCurrentTime(audioRef.current.currentTime);
  };

  const handleLoadedMetadata = () => {
    if (!audioRef.current) return;
    setDuration(audioRef.current.duration);
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (!audioRef.current) return;
    audioRef.current.currentTime = val;
    setCurrentTime(val);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    if (audioRef.current) {
      audioRef.current.volume = val;
    }
  };

  const handleGoogleDriveLink = () => {
    const url = prompt("Paste your Google Drive sharing link here:");
    if (!url) return;

    const reg = /\/file\/d\/([a-zA-Z0-9_-]+)/;
    const match = url.match(reg);
    if (match && match[1]) {
      const fileId = match[1];
      const directUrl = `https://docs.google.com/uc?export=open&id=${fileId}`;

      setAudioError(null);
      setCurrentAudioSrc(directUrl);
      setSongTitle("Google Drive Stream");
      setCurrentTime(0);

      setTimeout(() => {
        if (audioRef.current) {
          audioRef.current.play().then(() => setIsPlaying(true)).catch(() => {});
        }
      }, 200);
    } else {
      alert("Invalid Google Drive link format. Make sure it contains '/file/d/FILE_ID'.");
    }
  };

  const handleUrlSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!audioRef.current) return;

    let targetUrl = audioUrlInput.trim();
    if (!targetUrl) return;

    // Check if it is a Flow Music song link (e.g. flowmusic.app/song/UUID or just UUID)
    const flowMusicRegex = /(?:song\/)?([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i;
    const match = targetUrl.match(flowMusicRegex);
    if (match && match[1]) {
      const songId = match[1];
      targetUrl = `https://storage.googleapis.com/producer-app-public/clips/${songId}.m4a`;
      setSongTitle("Flow Music Track");
    } else {
      try {
        const parsedName = targetUrl.substring(targetUrl.lastIndexOf('/') + 1).split('?')[0];
        setSongTitle(decodeURIComponent(parsedName) || "Loaded Track");
      } catch {
        setSongTitle("Loaded Track");
      }
    }

    setAudioError(null);
    setCurrentAudioSrc(targetUrl);
    setCurrentTime(0);

    setTimeout(() => {
      if (audioRef.current) {
        audioRef.current.play().then(() => setIsPlaying(true)).catch(() => {});
      }
    }, 200);
  };

  const handleLocalFileLoad = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const file = files[0];

    if (currentAudioSrc.startsWith("blob:")) {
      URL.revokeObjectURL(currentAudioSrc);
    }

    const localBlobUrl = URL.createObjectURL(file);
    setAudioError(null);
    setCurrentAudioSrc(localBlobUrl);
