    // 2. Extract [CAPTION: ...] or [SUBTITLE: ...]
    const captionMatch = text.match(/\[CAPTION:\s*([^\]]+)\]/i) || text.match(/\[SUBTITLE:\s*([^\]]+)\]/i);
    if (captionMatch && captionMatch[1]) {
      setCaptionText(captionMatch[1].trim());
      captionUpdated = true;
    }

    if (titleUpdated || captionUpdated) {
      alert("⚡ Form Auto-Filled! Your song title and subtitles are now fully synced across the visualizer and YouTube metadata.");
