const getMaterialFamily = (objectName: string): string => {
  const name = objectName.toLowerCase();

  // Explicitly flag meta-instructions / prompt text as UNKNOWN
  if (/metaphor|prompt|related|instruction|write a|list of|choose/i.test(name)) {
    return "UNKNOWN";
  }

  if (/mirror|window|glass|spectacle|lens|pane|reflection|silver|compact|shade|prism|frame|surface/i.test(name)) {
    return "Glass";
  }
  if (/letter|postage|stamp|parchment|photo|ticket|book|notebook|paper|envelope|card|inkwell|wax|receipt|note|document/i.test(name)) {
    return "Paper";
  }
  if (/mug|cup|vessel|teapot|pot|plate|saucer|ceramic|clay|terracotta|shaker|jar|bowl|handle|glazed|chipped|sipped|tile/i.test(name)) {
    return "Ceramic";
  }
  if (/key|keyring|watch|clock|hanger|lock|ring|ruler|metal|brass|iron|steel|chain|powerbank|coin/i.test(name)) {
    return "Metal";
  }
  if (/chair|table|bench|deck|chest|wardrobe|wood|timber|pine|oak|shelf|board|box|desk/i.test(name)) {
    return "Wood";
  }

  // Default flexible physical fallback for custom physical objects
  return "Glass";
}

