              <span className="text-slate-500 text-[10px] block uppercase">Harmonic Signature</span>
              <span className="text-slate-300">{activeFossil.harmonicDNA}</span>
            </div>
          </div>

          <div className="p-3 rounded bg-slate-900/30 border border-slate-900 text-xs">
            <span className="text-slate-500 text-[10px] font-mono block uppercase mb-1">Reason for Historical Discard</span>
            <p className="text-slate-300 italic leading-relaxed">"{activeFossil.discardReason}"</p>
