                  {revivedBranchName}
                </span>
              </div>
            </div>
          )}

          <div className="flex justify-end gap-3 pt-2">
            <button 
              onClick={() => {
                setSelectedFossil(null);
                setRevivalState("idle");
              }}
              className="px-3 py-1.5 rounded text-xs bg-slate-900 hover:bg-slate-800 text-slate-400 transition-colors"
            >
