interface DriftBoundaryProps {
  simulatedDrift: number;
  setSimulatedDrift: (drift: number) => void;
}

export default function DriftBoundary({ simulatedDrift, setSimulatedDrift }: DriftBoundaryProps) {
  const getSafetyClassification = (drift: number) => {
    if (drift < 30) return { label: "COHERENT (Anchor Centroid Match)", color: "text-emerald-400", bg: "bg-emerald-950/40 border-emerald-900/40" };
    if (drift < 65) return { label: "MUTATED INTEGRITY (Valid Variation)", color: "text-teal-400", bg: "bg-teal-950/40 border-teal-900/40" };
    if (drift < 85) return { label: "DRIFT BOUNDARY REACHED (Unstable)", color: "text-amber-400", bg: "bg-amber-950/40 border-amber-900/40" };
    return { label: "MUTATION FRACTURE (Out of Bounds)", color: "text-rose-400", bg: "bg-rose-950/40 border-rose-900/40" };
  };

  const safety = getSafetyClassification(simulatedDrift);

  // Determine Primary Drift Driver dynamically
  const getPrimaryDriftDriver = () => {
    if (simulatedDrift < 15) return "None (Coherent)";
    const ac = simulatedDrift * 0.4;
    const sd = simulatedDrift;
    if (sd > ac) {
      return {
        name: "Structural Drift",
        val: Math.round(sd),
        share: 48
      };
    } else {
      return {
        name: "Acoustic Profile Offset",
        val: Math.round(ac),
        share: 32
      };
    }
  };

  const driver = getPrimaryDriftDriver();

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between">
        <div>
          <h3 className="text-base font-semibold text-slate-200">C17.1 Drift Boundary Monitor</h3>
          <p className="text-xs text-slate-400 mt-1">
            Tests active drafts against historical emotional centroids to ensure provenance stability.
          </p>
        </div>
        <span className="text-[10px] font-mono text-sky-400 bg-sky-950/50 border border-sky-900 px-2 py-0.5 rounded">
          REAL-TIME SIMULATION
        </span>
      </div>

      <div className="bg-slate-950 border border-slate-900 rounded-lg p-5 flex flex-col gap-5">

        {/* Dynamic Centroid Gauge */}
        <div className="space-y-2">
          <div className="flex justify-between items-center text-xs">
            <span className="text-slate-400 font-mono">Simulate Draft Mutation Distance:</span>
            <span className="font-mono font-bold text-teal-400 text-sm">{simulatedDrift}%</span>
          </div>

          <input 
            type="range" 
            min="5" 
            max="100" 
            value={simulatedDrift}
            onChange={(e) => setSimulatedDrift(Number(e.target.value))}
            className="w-full accent-teal-500 bg-slate-900 rounded-lg appearance-none h-2 cursor-pointer"
          />

          <div className="flex justify-between text-[10px] text-slate-500 font-mono">
            <span>Core Anchor (0%)</span>
            <span>Centroid (50%)</span>
            <span>Fracture (100%)</span>
          </div>
        </div>

        {/* Dynamic primary contributor analysis sidebar */}
        {typeof driver !== "string" && (
          <div className="p-3 bg-rose-950/10 border border-rose-900/40 rounded-lg flex items-center justify-between font-mono text-xs">
            <div className="flex items-center gap-2">
              <span className="h-2 w-2 rounded-full bg-rose-400 animate-pulse"></span>
              <span className="text-slate-400">Primary Drift Driver:</span>
              <span className="text-slate-200 font-semibold">{driver.name}</span>
            </div>
            <span className="text-rose-400 font-bold">+{driver.val}% (+{driver.share}% Share)</span>
          </div>
