  };

  // Run Flow Guard Validation
  const runFlowGuardValidation = () => {
    const targetObj = activePacket.parameters.signatureObject;
    const familyName = getMaterialFamily(targetObj);
    const defaultRules: ConflictRepairConfig = {
      bannedKeywords: [],
      phraseRules: [],
      lineRules: [],
      tokenRules: {}
    };
    const rules = CONFLICT_MAP[familyName] || defaultRules;
    const bannedList = rules.bannedKeywords;

    let contaminationDetected = false;
    let offendingLines: any[] = [];
    const lines = activePacket.rawLyrics.split("\n");

    lines.forEach((line, index) => {
      const foundBanned = bannedList.find(word => line.toLowerCase().includes(word));
      if (foundBanned) {
        contaminationDetected = true;
        offendingLines.push({
          lineNumber: index + 1,
          originalText: line,
          reason: `Contamination caught: Forbidden token [${foundBanned}] for locked object [${targetObj}].`
        });
      }
    });

    // Run custom sanitizer check
    const guard = sanitizeAndGuard(activePacket.rawLyrics, targetObj);
    let finalLyrics = activePacket.rawLyrics;
    let qaStatus: "PASSED" | "REPAIRED" | "FAILED" = "PASSED";
    let anchorScore = 1.0;

    if (!guard.isValidMatch) {
      qaStatus = "FAILED";
      anchorScore = 0.5;
      offendingLines.push({
        lineNumber: 1,
        originalText: "Target Object Missing",
        reason: `Physical Anchor Missing: Your signature object "${targetObj}" was not physically introduced in Verse 1.`
      });
    } else if (contaminationDetected && rules) {
      qaStatus = "REPAIRED";
      anchorScore = 0.85;

      lines.forEach((line, index) => {
        const hasBanned = bannedList.some(word => line.toLowerCase().includes(word));
        if (!hasBanned) return;

        let updated = line;
        let repaired = false;

        // Priority 1: Phrase-level replacement
        for (const pr of rules.phraseRules) {
          if (pr.pattern.test(updated)) {
            updated = updated.replace(pr.pattern, pr.replacement);
            repaired = true;
          }
        }

        // Priority 2: Line-level replacement
        if (!repaired) {
          for (const lr of rules.lineRules) {
            const matchesAll = lr.keywords.every(keyword => updated.toLowerCase().includes(keyword));
            if (matchesAll) {
              updated = lr.replacement;
              repaired = true;
              break;
            }
          }
        }

        // Priority 3: Token-level replacement fallback
        if (!repaired) {
          bannedList.forEach(word => {
            const regex = new RegExp(`\\b${word}\\b`, "gi");
            if (regex.test(updated)) {
              const fallback = rules.tokenRules[word.toLowerCase()] || word;
              updated = updated.replace(regex, fallback);
            }
          });
        }

        lines[index] = updated;
      });
      finalLyrics = lines.join("\n");
    }

    setActivePacket(prev => ({
      ...prev,
      qaStatus,
      finalSanitizedLyrics: finalLyrics,
      analyzerMetrics: {
        anchorStabilityScore: anchorScore,
        contaminationDetected: contaminationDetected || !guard.isValidMatch,
        offendingLines
      },
      status: qaStatus === "FAILED" ? "draft" : "validated"
    }));
  };

  // Generate dynamic V9.6 blueprint lyrics conforming precisely to structural enforcements
