        ? getMizoLyrics(activeJourney)
        : getHinglishLyrics(activeJourney);

    const combinedBlend = `${activePacket.parameters.genrePrimary} fused with ${activePacket.parameters.genreSecondary}`;

    // Determine the material family of the target object
    const familyName = getMaterialFamily(targetObj);
