          <button 
            onClick={() => setIsPlaying(!isPlaying)} 
            className="w-8 h-8 rounded-full bg-[#FAF8F5] text-[#211E1A] flex items-center justify-center hover:scale-105 transition-transform"
          >
            {isPlaying ? <Pause size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" className="ml-0.5" />}
          </button>
          <button onClick={() => { setPlaybackTime(181); setIsPlaying(false); }} className="text-[#8C7F65] hover:text-white"><SkipForward size={16} /></button>
          <span className="text-[#FAF8F5] text-[11px]">{formatTime(playbackTime)} / 3:01</span>
        </div>

        {/* Dynamic Simulated Waveform Progress Bar */}
        <div className="flex-1 w-full max-w-2xl px-4 flex items-center gap-2 relative">
          <div className="w-full h-8 flex items-end gap-[2px] opacity-40 relative">
            {/* Draw a beautiful simulated audio wave */}
            {Array.from({ length: 70 }).map((_, i) => {
              const height = 15 + Math.sin(i * 0.15) * 10 + Math.cos(i * 0.3) * 5;
              const isPassed = (i / 70) <= (playbackTime / 181);
              return (
                <div 
                  key={i} 
                  style={{ height: `${height}%` }} 
                  className={`w-[4px] rounded-t-sm transition-colors ${isPassed ? "bg-emerald-400" : "bg-[#8C7F65]"}`}
                />
              );
            })}
          </div>
        </div>

