        <div className="flex items-center gap-4 shrink-0 text-[#8C7F65]">
          <button className="hover:text-white"><Shuffle size={14} /></button>
          <button className="hover:text-white"><Repeat size={14} /></button>
          <button className="hover:text-white"><ListMusic size={14} /></button>
          <button onClick={() => setIsMuted(!isMuted)} className="hover:text-white">
            {isMuted ? <VolumeX size={16} /> : <Volume2 size={16} />}
          </button>
          <button className="hover:text-white"><Maximize2 size={14} /></button>
        </div>
      </div>

