      qaStatus = "REPAIRED";
      anchorScore = 0.85;

      lines.forEach((line, index) => {
        const hasBanned = bannedList.some(word => line.toLowerCase().includes(word));
        if (!hasBanned) return;

        let updated = line;
        let repaired = false;

        // Priority 1: Phrase-level replacement
        for (const pr of rules.phraseRules) {
          if (pr.pattern.test(updated)) {
            updated = updated.replace(pr.pattern, pr.replacement);
            repaired = true;
          }
        }

        // Priority 2: Line-level replacement
        if (!repaired) {
          for (const lr of rules.lineRules) {
            const matchesAll = lr.keywords.every(keyword => updated.toLowerCase().includes(keyword));
            if (matchesAll) {
              updated = lr.replacement;
              repaired = true;
              break;
            }
          }
        }

        // Priority 3: Token-level replacement fallback
        if (!repaired) {
          bannedList.forEach(word => {
            const regex = new RegExp(`\\b${word}\\b`, "gi");
            if (regex.test(updated)) {
              const fallback = rules.tokenRules[word.toLowerCase()] || word;
              updated = updated.replace(regex, fallback);
            }
          });
        }

        lines[index] = updated;
      });
      finalLyrics = lines.join("\n");
    }

    setActivePacket(prev => ({
      ...prev,
      qaStatus,
      finalSanitizedLyrics: finalLyrics,
      analyzerMetrics: {
