export interface DiagnosticEvidence {
  status: "success" | "warning" | "error";
  category: string;
  message: string;
}

export interface DiagnosticResult {
  structureValid: boolean;
  sectionsFound: string[];
  fourLineRulePassed: boolean;
  fourLineErrors: string[];
  slopWordsFound: string[];
  anomaliesFound: string[];
  slopScore: number; // 0 to 100
  physicalDensity: number; // 0 to 100
  physicsFound: string[];
  verseChorusRatio: number; // ratio
  verseChorusRating: string;
  repetitionRate: number; // % of duplicate content words
  repetitionDetails: string[];
  overallQualityScore: number; // 0 to 100
  suggestions: string[];
  evidence: DiagnosticEvidence[];
}

const SLOP_WORDS = [
  "whisper", "echo", "shadow", "tapestry", "symphony", "neon", "dance", "holding on", 
  "letting go", "spark", "ember", "vibe", "eternal", "rhythm", "melodic", "endless", 
  "ignite", "fade away", "glowing", "starlight", "cosmic", "veins", "soul", "heartbeat"
];

const ANOMALY_WORDS = [
  "banana", "pineapple", "irrelevant", "random", "test word", "placeholder", "foo", "bar", "lorem", "ipsum"
];

const PHYSICS_WORDS = [
  "iron", "copper", "steel", "brass", "pine", "timber", "wood", "concrete", "mortar", 
  "plaster", "lead", "solder", "wire", "current", "volt", "ampere", "meter", "screw", 
  "bolt", "beam", "joist", "foundation", "clay", "sand", "tension", "friction", 
  "gravity", "mass", "load", "density", "pressure", "temperature", "bellows", "wick", 
  "kerosene", "oil", "mercury", "quartz", "piston", "gears", "rust", "oxidation",
  "lantern", "lamp", "flame", "glass", "snow", "window", "door", "floor", "roof", "house", "fire", "rain", "wall",
  "bicycle", "wheel", "table", "nail", "key", "refrigerator", "candle", "wax", "metal", "stone", "brick", "pipe"
];

export function runDiagnostics(lyricsText: string, profile: "physical_poetry" | "gospel" | "ballad" | "experimental" = "physical_poetry"): DiagnosticResult {
  const lines = lyricsText.split("\n").map(l => l.trim());
  const suggestions: string[] = [];
  const evidence: DiagnosticEvidence[] = [];

  // 1. Structure Check
  const sectionRegex = /^\[?(intro|verse\s*\d*|chorus|final chorus|bridge|outro)\]?$/i;
  const sectionsFound: string[] = [];
  let currentSection = "";
  const sectionLineCounts: Record<string, number> = {};

  lines.forEach(line => {
    const rawLine = line.replace(/^\[|\]$/g, "").trim();
    if (sectionRegex.test(rawLine) || /^\[(.*?)\]$/.test(line)) {
      currentSection = rawLine.toLowerCase();
      sectionsFound.push(rawLine);
      sectionLineCounts[rawLine] = 0;
    } else if (line.length > 0 && currentSection) {
      if (!line.startsWith("(") || !line.endsWith(")")) {
        sectionLineCounts[sectionsFound[sectionsFound.length - 1]]++;
      }
    }
  });

  const lowercaseSections = sectionsFound.map(s => s.toLowerCase());

  // Check sequence
  const expectedSequence = ["intro", "verse 1", "chorus", "verse 2", "chorus", "verse 3", "chorus", "verse 4", "chorus", "bridge", "outro"];
  let sequenceScore = 0;
  expectedSequence.forEach(exp => {
    if (lowercaseSections.some(s => s.includes(exp))) sequenceScore++;
  });
  const structureValid = sequenceScore >= 4 || sectionsFound.length >= 3;

  // PROFILE-SPECIFIC RULES
  if (profile === "experimental") {
    evidence.push({
      status: "success",
      category: "Structure Layout",
      message: "[Experimental Profile Mode] Ignored standard sequence constraints. Entropy layout validated."
    });
  } else if (structureValid) {
    evidence.push({
      status: "success",
      category: "Structure Layout",
      message: `Parsed ${sectionsFound.length} logical song blocks (${sectionsFound.slice(0, 4).join(", ")}...).`
    });
  } else {
    suggestions.push("Structure deviates from standard song formatting.");
    evidence.push({
      status: "warning",
      category: "Structure Layout",
      message: `Asymmetrical or custom layout detected (${sectionsFound.length} parsed sections).`
    });
  }

  // 2. 4-Line Rule (Bible V1.2)
  let fourLineRulePassed = true;
  const fourLineErrors: string[] = [];

  Object.entries(sectionLineCounts).forEach(([section, count]) => {
    const isVerse = section.toLowerCase().startsWith("verse");
    const isChorus = section.toLowerCase().startsWith("chorus");
    if ((isVerse || isChorus) && count !== 4) {
      fourLineRulePassed = false;
      fourLineErrors.push(`${section} has ${count} lines (Expected exactly 4)`);
    }
  });

  if (profile === "experimental" || profile === "ballad") {
    evidence.push({
      status: "success",
      category: "Line Constraints",
      message: `[${profile === "ballad" ? "Ballad" : "Experimental"} Profile Mode] Strict 4-line rule bypassed.`
    });
  } else if (fourLineRulePassed && sectionsFound.length > 0) {
    evidence.push({
      status: "success",
      category: "Line Constraints",
      message: "All Verses & Choruses contain exactly 4 load-bearing lines. Fully compliant with Bible V1.2."
    });
  } else if (sectionsFound.length > 0) {
    suggestions.push("Bible V1.2 4-Line Rule violated: Some verses/choruses do not have exactly 4 lines.");
    evidence.push({
      status: "error",
      category: "Line Constraints",
      message: `Bible V1.2 violation: ${fourLineErrors.length} blocks deviate from the 4-line boundary.`
    });
  }

  // 3. Contextual Anomaly & Irrelevant Noise Scan
  const lowercaseText = lyricsText.toLowerCase();
  const anomaliesFound = ANOMALY_WORDS.filter(w => lowercaseText.includes(w));
  if (lowercaseText.includes("irrelevant word inserted") || lowercaseText.includes("←")) {
    if (!anomaliesFound.includes("inline annotation")) anomaliesFound.push("inline annotation (←)");
  }

  if (anomaliesFound.length > 0) {
    suggestions.push(`Irrelevant noise artifact detected: "${anomaliesFound.join(", ")}". Purge before committing to master.`);
    evidence.push({
      status: "error",
      category: "Contextual Anomaly Filter",
      message: `Contamination detected: Found non-sequitur or noise artifact "${anomaliesFound.join(", ")}".`
    });
  } else {
    evidence.push({
      status: "success",
      category: "Contextual Anomaly Filter",
      message: "No non-sequiturs or out-of-context noise insertions detected."
    });
  }

  // 4. Repetition Analysis
  const rawWords = lowercaseText.match(/[a-z0-9'\-]+/g) || [];
  const contentWords = rawWords.filter(w => w.length > 4); 
  const wordCounts: Record<string, number> = {};
  contentWords.forEach(w => {
    wordCounts[w] = (wordCounts[w] || 0) + 1;
  });

  const duplicates = Object.entries(wordCounts)
    .filter(([_, count]) => count > 3)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3);

  const repetitionRate = contentWords.length > 0 
    ? Math.round((contentWords.filter(w => (wordCounts[w] || 0) > 3).length / contentWords.length) * 100)
    : 0;

  const repetitionDetails = duplicates.map(([word, count]) => `"${word}" repeated ${count}x`);

  if (repetitionRate > 40 && profile !== "experimental") {
    suggestions.push("High lexical repetition detected outside choruses.");
    evidence.push({
      status: "warning",
      category: "Repetition Metrics",
      message: `Lexical repetition elevated (${repetitionRate}%).`
    });
  } else {
    evidence.push({
      status: "success",
      category: "Repetition Metrics",
      message: `Lexical saturation stable (${repetitionRate}%).`
    });
  }

  // 5. AI Slop Finder with Contextual Metaphor Discrimination (v12)
  const slopWordsFound = SLOP_WORDS.filter(word => lowercaseText.includes(word));
  const slopScore = Math.min(100, Math.round((slopWordsFound.length / 5) * 100));

  // Contextual pass for physical/acoustic usage vs abstract cliché
  const contextualPassedWords: string[] = [];
  const trueSlopWords: string[] = [];

  slopWordsFound.forEach(word => {
    if ((word === "shadow" || word === "shadows" || word === "echo" || word === "rhythm") && 
        (lowercaseText.includes("wall") || lowercaseText.includes("hall") || lowercaseText.includes("room") || lowercaseText.includes("wood") || lowercaseText.includes("stone") || lowercaseText.includes("glass"))) {
      contextualPassedWords.push(word);
    } else {
      trueSlopWords.push(word);
    }
  });

  if (contextualPassedWords.length > 0) {
    evidence.push({
      status: "success",
      category: "🟨 Contextual Metaphor Validation",
      message: `Validated physical/acoustic usage for: "${contextualPassedWords.join(", ")}" (bound to physical surfaces).`
    });
  }

  if (profile === "experimental") {
    evidence.push({
      status: "success",
      category: "AI Slop Protection",
      message: "[Experimental Mode] AI slop protection metrics relaxed."
    });
  } else if (trueSlopWords.length > 0) {
    suggestions.push(`Slop detected: Avoid clichés like "${trueSlopWords.slice(0, 3).join(", ")}".`);
    evidence.push({
      status: "error",
      category: "AI Slop Protection",
      message: `Cliché contamination found: "${trueSlopWords.slice(0, 3).join(", ")}".`
    });
  } else {
    suggestions.push("Clean Room Approved: Zero standard AI slop keywords detected.");
    evidence.push({
      status: "success",
      category: "AI Slop Protection",
      message: "Clean Room Approved: Zero unanchored generative text watermarks found."
    });
  }

  // 6. Physical & Spiritual Grounding Density
  const physicsFound = PHYSICS_WORDS.filter(word => lowercaseText.includes(word));
  const physicalDensity = Math.min(100, Math.round((physicsFound.length / 5) * 100));

  // Check for recurring central witness objects (e.g. lantern appearing 3+ times)
  const lanternCount = (lowercaseText.match(/lantern/g) || []).length;
  if (lanternCount >= 2 || physicsFound.length >= 4) {
    evidence.push({
      status: "success",
      category: "Physical Witness Object",
      message: `Primary Witness Anchor recognized (${physicsFound.slice(0, 4).join(", ")}). Recurring structural metaphor confirmed.`
    });
  }

  if (profile === "physical_poetry" || profile === "ballad") {
    if (physicalDensity < 45) {
      suggestions.push("Low physical density. Inject more load-bearing physical objects.");
      evidence.push({
        status: "warning",
        category: "Physical Grounding",
        message: `Abstract language detected. Physical density is at ${physicalDensity}%.`
      });
    } else {
      evidence.push({
        status: "success",
        category: "Physical Grounding",
        message: `Excellent physical density (${physicalDensity}%).`
      });
    }
  } else {
    evidence.push({
      status: "success",
      category: "Physical Grounding",
      message: `Physical density mode active (${physicalDensity}%).`
    });
  }

  // 7. Overall Quality Score
  let score = 100;
  if (profile !== "experimental") {
    if (!fourLineRulePassed) score -= 20;
    if (anomaliesFound.length > 0) score -= 30; // heavy penalty for out-of-context noise
    score -= (slopWordsFound.length * 8); 
    score += Math.min(15, Math.round(physicalDensity / 5)); 
  } else {
    score = 100;
  }
  const overallQualityScore = Math.max(0, Math.min(100, score));

  return {
    structureValid,
    sectionsFound,
    fourLineRulePassed,
    fourLineErrors,
    slopWordsFound,
    anomaliesFound,
    slopScore,
    physicalDensity,
    physicsFound,
    verseChorusRatio: 1,
    verseChorusRating: "Stable",
    repetitionRate,
    repetitionDetails,
    overallQualityScore,
    suggestions,
    evidence
  };
}

export function cleanAndCompressLyrics(lyricsText: string): string {
  const lines = lyricsText.split("\n");
  const cleaned: string[] = [];
  let emptyLineCount = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === "") {
      emptyLineCount++;
      if (emptyLineCount <= 1) {
        cleaned.push("");
      }
    } else {
      emptyLineCount = 0;
      cleaned.push(line);
    }
  }

  return cleaned.join("\n").trim();
}

