export interface DiagnosticEvidence {
  status: "success" | "warning" | "error";
  category: string;
  message: string;
}

export interface DiagnosticResult {
  structureValid: boolean;
  sectionsFound: string[];
  fourLineRulePassed: boolean;
  fourLineErrors: string[];
  slopWordsFound: string[];
  slopScore: number; // 0 to 100
  physicalDensity: number; // 0 to 100
  physicsFound: string[];
  verseChorusRatio: number; // ratio
  verseChorusRating: string;
  repetitionRate: number; // % of duplicate content words
  repetitionDetails: string[];
  overallQualityScore: number; // 0 to 100
  suggestions: string[];
  evidence: DiagnosticEvidence[];
}

const SLOP_WORDS = [
  "whisper", "echo", "shadow", "tapestry", "symphony", "neon", "dance", "holding on", 
  "letting go", "spark", "ember", "vibe", "eternal", "rhythm", "melodic", "endless", 
  "ignite", "fade away", "glowing", "starlight", "cosmic", "veins", "soul", "heartbeat"
];

const PHYSICS_WORDS = [
  "iron", "copper", "steel", "brass", "pine", "timber", "wood", "concrete", "mortar", 
  "plaster", "lead", "solder", "wire", "current", "volt", "ampere", "meter", "screw", 
  "bolt", "beam", "joist", "foundation", "clay", "sand", "tension", "friction", 
  "gravity", "mass", "load", "density", "pressure", "temperature", "bellows", "wick", 
  "kerosene", "oil", "mercury", "quartz", "friction", "piston", "gears", "rust", "oxidation"
];

export function runDiagnostics(lyricsText: string, profile: "physical_poetry" | "gospel" | "ballad" | "experimental" = "physical_poetry"): DiagnosticResult {
  const lines = lyricsText.split("\n").map(l => l.trim());
  const suggestions: string[] = [];
  const evidence: DiagnosticEvidence[] = [];

  // 1. Structure Check
  const sectionRegex = /^\[(.*?)\]$/;
  const sectionsFound: string[] = [];
  let currentSection = "";
  const sectionLineCounts: Record<string, number> = {};

  lines.forEach(line => {
    const match = line.match(sectionRegex);
    if (match) {
      currentSection = match[1].toLowerCase();
      sectionsFound.push(match[1]);
      sectionLineCounts[match[1]] = 0;
    } else if (line.length > 0 && currentSection) {
      if (!line.startsWith("(") || !line.endsWith(")")) {
        sectionLineCounts[sectionsFound[sectionsFound.length - 1]]++;
      }
    }
  });

  const lowercaseSections = sectionsFound.map(s => s.toLowerCase());

  // Check sequence
  const expectedSequence = ["intro", "verse 1", "chorus", "verse 2", "chorus", "verse 3", "chorus", "verse 4", "chorus", "bridge", "outro"];
  let sequenceScore = 0;
  expectedSequence.forEach(exp => {
    if (lowercaseSections.includes(exp)) sequenceScore++;
  });
  const structureValid = sequenceScore >= 9;

  // PROFILE-SPECIFIC RULES
  // a) Structure & Layout checks
  if (profile === "experimental") {
    evidence.push({
      status: "success",
      category: "Structure Layout",
      message: "[Experimental Profile Mode] Ignored standard sequence constraints. Entropy layout validated."
    });
  } else if (structureValid) {
    evidence.push({
      status: "success",
      category: "Structure Layout",
      message: "Fully matches Elyzareth OS structure pattern (V1 → Ch → V2 → Ch → V3 → Ch → V4 → Ch → Bridge → Outro)."
    });
  } else {
    suggestions.push("Structure deviates from Elyzareth OS v9 (Intro-V1-Ch-V2-Ch-V3-Ch-V4-Ch-Bridge-Outro).");
    evidence.push({
      status: "warning",
      category: "Structure Layout",
      message: `Asymmetrical or custom layout detected (${sectionsFound.length} parsed sections). Check sequence.`
    });
  }

  // 2. 4-Line Rule (Bible V1.2)
  let fourLineRulePassed = true;
  const fourLineErrors: string[] = [];

  Object.entries(sectionLineCounts).forEach(([section, count]) => {
    const isVerse = section.toLowerCase().startsWith("verse");
    const isChorus = section.toLowerCase().startsWith("chorus");
    if ((isVerse || isChorus) && count !== 4) {
      fourLineRulePassed = false;
      fourLineErrors.push(`${section} has ${count} lines (Expected exactly 4)`);
    }
  });

  if (profile === "experimental" || profile === "ballad") {
    evidence.push({
      status: "success",
      category: "Line Constraints",
      message: `[${profile === "ballad" ? "Ballad" : "Experimental"} Profile Mode] Strict 4-line rule bypassed. Flexible lines permitted.`
    });
  } else if (fourLineRulePassed && sectionsFound.length > 0) {
    evidence.push({
      status: "success",
      category: "Line Constraints",
      message: "All structural Verses & Choruses contain exactly 4 load-bearing lines. Fully compliant with Bible V1.2."
    });
  } else if (sectionsFound.length > 0) {
    suggestions.push("Bible V1.2 4-Line Rule violated: Some verses/choruses do not have exactly 4 lines.");
    evidence.push({
      status: "error",
      category: "Line Constraints",
      message: `Bible V1.2 violation: ${fourLineErrors.length} blocks deviate from the strict 4-line boundary.`
    });
  }

  // 3. Verse/Chorus Balance
  const totalVerses = lowercaseSections.filter(s => s.startsWith("verse")).length;
  const totalChoruses = lowercaseSections.filter(s => s.startsWith("chorus")).length;
  const verseChorusRatio = totalChoruses > 0 ? Number((totalVerses / totalChoruses).toFixed(2)) : 0;
  let verseChorusRating = "Unbalanced";

  if (profile === "experimental") {
    verseChorusRating = "Ignored";
    evidence.push({
      status: "success",
      category: "Symmetry Balance",
      message: "[Experimental Mode] Structural symmetry checks bypassed."
    });
  } else if (totalVerses === 4 && totalChoruses === 4) {
    verseChorusRating = "Perfect OS Balance (4V:4C)";
    evidence.push({
      status: "success",
      category: "Symmetry Balance",
      message: "Perfect symmetry: 4 verses and 4 choruses balanced perfectly in tension-distribution."
    });
  } else if (verseChorusRatio >= 1 && verseChorusRatio <= 2) {
    verseChorusRating = "Stable";
    evidence.push({
      status: "success",
      category: "Symmetry Balance",
      message: `Stable verse-to-chorus distribution ratio of ${verseChorusRatio}.`
    });
  } else {
    suggestions.push(`Asymmetrical arrangement parsed (${totalVerses} Verses to ${totalChoruses} Choruses).`);
    evidence.push({
      status: "warning",
      category: "Symmetry Balance",
      message: `High structural asymmetry: ${totalVerses} verses and ${totalChoruses} choruses parsed.`
    });
  }

  // 4. Repetition Analysis
  const lowercaseText = lyricsText.toLowerCase();
  const rawWords = lowercaseText.match(/[a-z0-9'\-]+/g) || [];
  const contentWords = rawWords.filter(w => w.length > 4); 
  const wordCounts: Record<string, number> = {};
  contentWords.forEach(w => {
    wordCounts[w] = (wordCounts[w] || 0) + 1;
  });

  const duplicates = Object.entries(wordCounts)
    .filter(([_, count]) => count > 3)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3);

  const repetitionRate = contentWords.length > 0 
    ? Math.round((contentWords.filter(w => (wordCounts[w] || 0) > 3).length / contentWords.length) * 100)
    : 0;

  const repetitionDetails = duplicates.map(([word, count]) => `"${word}" repeated ${count}x`);

  if (repetitionRate > 40 && profile !== "experimental") {
    suggestions.push("High lexical repetition detected outside choruses. Inject novel adjectives.");
    evidence.push({
      status: "warning",
      category: "Repetition Metrics",
      message: `Lexical repetition is elevated (${repetitionRate}%). Heavy repeated targets: ${repetitionDetails.slice(0, 2).join(", ")}.`
    });
  } else {
    evidence.push({
      status: "success",
      category: "Repetition Metrics",
      message: `Lexical saturation stable (${repetitionRate}%). No unnecessary word padding detected.`
    });
  }

  // 5. AI Slop Finder
  const slopWordsFound = SLOP_WORDS.filter(word => lowercaseText.includes(word));
  const slopScore = Math.min(100, Math.round((slopWordsFound.length / 5) * 100));

  if (profile === "experimental") {
    evidence.push({
      status: "success",
      category: "AI Slop Protection",
      message: "[Experimental Mode] AI slop protection metrics relaxed."
    });
  } else if (slopWordsFound.length > 0) {
    suggestions.push(`Slop detected: Avoid AI clichés like "${slopWordsFound.slice(0, 3).join(", ")}".`);
    evidence.push({
      status: "error",
      category: "AI Slop Protection",
      message: `Contamination found: "${slopWordsFound.slice(0, 3).join(", ")}" violating Clean Room standards.`
    });
  } else {
    suggestions.push("Clean Room Approved: Zero standard AI slop keywords detected.");
    evidence.push({
      status: "success",
      category: "AI Slop Protection",
      message: "Clean Room Approved: Zero standard generative text watermarks or templates found."
    });
  }

  // 6. Physical & Spiritual Grounding Density
  const physicsFound = PHYSICS_WORDS.filter(word => lowercaseText.includes(word));
  const physicalDensity = Math.min(100, Math.round((physicsFound.length / 6) * 100));

  const spiritualWords = ["light", "grace", "stone", "faith", "cross", "hope", "sky", "soil", "dirt", "dust", "blood", "witness"];
  const spiritualFound = spiritualWords.filter(w => lowercaseText.includes(w));

  if (profile === "gospel") {
    const spiritualScore = Math.min(100, Math.round((spiritualFound.length / 4) * 100));
    if (spiritualScore < 50) {
      suggestions.push("Low spiritual gravity. Inject more sacred grounding vectors (faith, grace, cross, blood, dust).");
      evidence.push({
        status: "warning",
        category: "Spiritual Gravity",
        message: `Spiritual score is at ${spiritualScore}%. Consider anchoring the text in deeper sacred variables.`
      });
    } else {
      evidence.push({
        status: "success",
        category: "Spiritual Gravity",
        message: `Excellent sacred grounding parsed: ${spiritualFound.slice(0, 3).join(", ")} (${spiritualScore}% spiritual density).`
      });
    }
  } else if (profile === "physical_poetry" || profile === "ballad") {
    if (physicalDensity < 45) {
      suggestions.push("Low physical density. Inject more grounding load-bearing objects or concrete materials.");
      evidence.push({
        status: "warning",
        category: "Physical Grounding",
        message: `Abstract language detected. Physical density is at ${physicalDensity}%. Add tangible load-bearing markers.`
      });
    } else {
      suggestions.push("Robust grounding: Excellent integration of tangible objects.");
      evidence.push({
        status: "success",
        category: "Physical Grounding",
        message: `Excellent physical density (${physicalDensity}%). Highly concrete references parsed: ${physicsFound.slice(0, 3).join(", ")}.`
      });
    }
  } else {
    evidence.push({
      status: "success",
      category: "Physical Grounding",
      message: `[Experimental Mode] Physical density metric ignored. Found ${physicsFound.length} raw physical elements.`
    });
  }

  // 7. Overall Quality Score
  let score = 100;
  if (profile !== "experimental") {
    if (!structureValid) score -= 15;
    if (!fourLineRulePassed && profile !== "ballad") score -= 20;
    score -= (slopWordsFound.length * 8); 
    score += Math.min(15, Math.round(physicalDensity / 5)); 
    if (repetitionRate > 40) score -= 10;
    if (totalVerses !== 4 || totalChoruses !== 4) score -= 5;
    if (profile === "gospel" && spiritualFound.length > 2) score += 10; // spiritual bonus
  } else {
    score = 100; // experimental is always optimal entropy
  }
  const overallQualityScore = Math.max(0, Math.min(100, score));

  return {
    structureValid,
    sectionsFound,
    fourLineRulePassed,
    fourLineErrors,
    slopWordsFound,
    slopScore,
    physicalDensity,
    physicsFound,
    verseChorusRatio,
    verseChorusRating,
    repetitionRate,
    repetitionDetails,
    overallQualityScore,
    suggestions,
    evidence
  };
}

export function cleanAndCompressLyrics(lyricsText: string): string {
  const lines = lyricsText.split("\n");
  const cleaned: string[] = [];
  let emptyLineCount = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === "") {
      emptyLineCount++;
      if (emptyLineCount <= 1) {
        cleaned.push("");
      }
    } else {
      emptyLineCount = 0;
      cleaned.push(line);
    }
  }

  return cleaned.join("\n").trim();
}

