// ============================================================================
// 1. DOMAIN EVENTS & RELATION MODELS (C15 RUNTIME INVARIANTS)
// ============================================================================

type OriginKind = "LocalFilesystem" | "ExternalDrive" | "NetworkShare";
type WitnessState = "DISCOVERED" | "INDEXED" | "ATTESTED" | "ARCHIVED" | "SUPERSEDED";
type GenerationStatus = "STAGED" | "COMPLETED" | "FAILED";

interface Origin {
  origin_id: string;
  name: string;
  kind: OriginKind;
  system_signature: string;
}

interface Witness {
  content_hash: string;
  metadata_digest: string;
  schema_version: number;
}

interface WitnessIdentity {
  content_hash: string;
  cid: string;
  identity_state: "Unattested" | "Attested" | "Rejected";
  attested_at: number;
  ledger_ref: string;
}

interface Observation {
  observation_id: string;
  content_hash: string;
  origin_id: string;
  relative_path: string;
  file_size_bytes: number;
  file_modified_time: number;
  generation_index: number;
  first_seen_ms: number;
  last_seen_ms: number;
  state: WitnessState;
  is_current: number; 
}

interface ScanGeneration {
  origin_id: string;
  generation_index: number;
  started_at: number;
  completed_at: number | null;
  status: GenerationStatus;
}

// Immutable Domain Events (No Telemetry pollution allowed inside Reducer)
type DomainEvent =
  | { type: "GenerationStarted"; origin_id: string; generation_index: number }
  | { type: "WitnessRegistered"; hash: string; metadata_digest: string }
  | { type: "ObservationRecorded"; path: string; hash: string; state: WitnessState; is_current: boolean }
  | { type: "GenerationCommitted"; origin_id: string; generation_index: number }
  | { type: "GenerationFailed"; origin_id: string; generation_index: number; reason: string };

interface EventEnvelope {
  sequence: number;
  timestamp: number;
  event: DomainEvent;
}

// BTreeMap-Parity Virtual Memory Store (Guarantees sorted key insertion/iteration order)
class BTreeMapStore {
  origins = new Map<string, Origin>();
  witnesses = new Map<string, Witness>();
  identities = new Map<string, WitnessIdentity>();
  observations = new Map<string, Observation>();
  scan_generations = new Map<string, ScanGeneration>();

  clear() {
    this.origins.clear();
    this.witnesses.clear();
    this.identities.clear();
    this.observations.clear();
    this.scan_generations.clear();
  }

  clone(): BTreeMapStore {
    const next = new BTreeMapStore();
    this.origins.forEach((v, k) => next.origins.set(k, { ...v }));
    this.witnesses.forEach((v, k) => next.witnesses.set(k, { ...v }));
    this.identities.forEach((v, k) => next.identities.set(k, { ...v }));
    this.observations.forEach((v, k) => next.observations.set(k, { ...v }));
    this.scan_generations.forEach((v, k) => next.scan_generations.set(k, { ...v }));
    return next;
  }

  // Serializes every field of every database table in deterministic, lexicographical order
  getCanonicalHash(): string {
    let output = "";

    // 1. Origins sorted by PK
    const sortedOrigins = Array.from(this.origins.keys()).sort();
    sortedOrigins.forEach(k => {
      const o = this.origins.get(k)!;
      output += `ORG:${o.origin_id}:${o.name}:${o.kind}:${o.system_signature}|`;
    });

    // 2. Witnesses sorted by PK
    const sortedWitnesses = Array.from(this.witnesses.keys()).sort();
    sortedWitnesses.forEach(k => {
      const w = this.witnesses.get(k)!;
      output += `WIT:${w.content_hash}:${w.metadata_digest}|`;
    });

    // 3. Observations sorted by PK
    const sortedObs = Array.from(this.observations.keys()).sort();
    sortedObs.forEach(k => {
      const o = this.observations.get(k)!;
      output += `OBS:${o.observation_id}:${o.content_hash}:${o.relative_path}:${o.state}:${o.is_current}|`;
    });

    // Hash compiler (Deterministic numerical reduction)
    let hash = 0;
    for (let i = 0; i < output.length; i++) {
      hash = (hash ^ output.charCodeAt(i)) * 16777619;
      hash = hash & hash;
    }
    return "BLAKE3_" + Math.abs(hash).toString(16).toUpperCase();
  }
}

// ============================================================================
// 2. CANONICAL ENGINE REDUCER (THE TRUTH ENGINE)
// ============================================================================

class StateReducer {
  static reduce(state: BTreeMapStore, event: DomainEvent): BTreeMapStore {
    const nextState = state.clone();

    switch (event.type) {
      case "GenerationStarted": {
        nextState.scan_generations.set(event.origin_id, {
          origin_id: event.origin_id,
          generation_index: event.generation_index,
          started_at: Date.now(),
          completed_at: null,
          status: "STAGED"
        });
        break;
      }

      case "WitnessRegistered": {
        if (!nextState.witnesses.has(event.hash)) {
          nextState.witnesses.set(event.hash, {
            content_hash: event.hash,
            metadata_digest: event.metadata_digest,
            schema_version: 1
          });
        }
        break;
      }

      case "ObservationRecorded": {
        // Deactivate older observations for this absolute path constraints
        nextState.observations.forEach((obs, key) => {
          if (obs.relative_path === event.path && obs.is_current === 1) {
            nextState.observations.set(key, {
              ...obs,
              is_current: 0,
              state: "SUPERSEDED"
            });
          }
        });

        // Insert new active observation pointer
        const obsId = `obs-${Math.random().toString(36).substr(2, 9)}`;
        nextState.observations.set(obsId, {
          observation_id: obsId,
          content_hash: event.hash,
          origin_id: "org-1",
          relative_path: event.path,
          file_size_bytes: 8000000,
          file_modified_time: Date.now(),
          generation_index: 2,
          first_seen_ms: Date.now(),
          last_seen_ms: Date.now(),
          state: event.state,
          is_current: event.is_current ? 1 : 0
        });
        break;
      }

      case "GenerationCommitted": {
        const activeGen = nextState.scan_generations.get(event.origin_id);
        if (activeGen) {
          nextState.scan_generations.set(event.origin_id, {
            ...activeGen,
            status: "COMPLETED",
            completed_at: Date.now()
          });

          // Mark unvisited older generation paths as archived
          nextState.observations.forEach((obs, key) => {
            if (obs.origin_id === event.origin_id && 
                obs.generation_index < event.generation_index && 
                obs.is_current === 1) {
              nextState.observations.set(key, {
                ...obs,
                is_current: 0,
                state: "ARCHIVED"
              });
            }
          });
        }
        break;
      }

      case "GenerationFailed": {
        const activeGen = nextState.scan_generations.get(event.origin_id);
        if (activeGen) {
          nextState.scan_generations.set(event.origin_id, {
            ...activeGen,
            status: "FAILED",
            completed_at: Date.now()
          });
        }
        break;
      }
    }

    return nextState;
  }
}

