      currentLedger.push({ sequence: sequenceIdx++, timestamp: Date.now(), event: audioEvent });
      currentLedger.push({ sequence: sequenceIdx++, timestamp: Date.now(), event: audioObs });
      logs.push(`[Seq #${sequenceIdx - 1}] FS_EVENT -> Sighted: audio.mp3 -> Registered Content ID: ${audioHash}`);
      setVerificationChecklist(prev => ({ ...prev, assetIdMatches: true }));

      // Event C: Observe companion metadata payload
      const metaEvent: DomainEvent = { type: "WitnessRegistered", hash: "H_SUNO_JSON_09", metadata_digest: "MD_SUNO_PROMPT_METADATA" };
      const metaObs: DomainEvent = { type: "ObservationRecorded", path: "tracks/metadata.json", hash: "H_SUNO_JSON_09", state: "INDEXED", is_current: true };

      currentStore = StateReducer.reduce(currentStore, metaEvent);
      currentStore = StateReducer.reduce(currentStore, metaObs);
      currentLedger.push({ sequence: sequenceIdx++, timestamp: Date.now(), event: metaEvent });
      currentLedger.push({ sequence: sequenceIdx++, timestamp: Date.now(), event: metaObs });
      logs.push(`[Seq #${sequenceIdx - 1}] FS_EVENT -> Sighted: metadata.json -> Registered prompt schemas`);
      setVerificationChecklist(prev => ({ ...prev, metadataMatches: true }));

      // Event D: Authoritative commit of generation
      const commitEvent: DomainEvent = { type: "GenerationCommitted", origin_id: "org-1", generation_index: 3 };
      currentStore = StateReducer.reduce(currentStore, commitEvent);
      currentLedger.push({ sequence: sequenceIdx++, timestamp: Date.now(), event: commitEvent });
      logs.push(`[Seq #${sequenceIdx - 1}] DAEMON -> Committing Generation run #3 to SQLite Store`);
      setVerificationChecklist(prev => ({ ...prev, sqliteMatches: true, conformancePasses: true }));

      // Finalize states
      setStore(currentStore);
      setDomainLedger(currentLedger);
      setDaemonLog(logs);
      setActiveFuzzState("INGESTED");
