interface EdgeCaseTest {
  id: string;
  name: string;
  type: string;
  expectedClass: "Accepted" | "Warning" | "Rejected";
  desc: string;
}

const EDGE_CASES: EdgeCaseTest[] = [
  { id: "EC-001", name: "Idempotency (Duplicate)", type: "idempotency", expectedClass: "Warning", desc: "Re-importing a Suno payload should skip duplicating specs, events, or clip rows." },
  { id: "EC-002", name: "Incomplete Witness", type: "missing_audio", expectedClass: "Warning", desc: "Clips ingested without actual physical audio on disk default to IncompleteWitness." },
  { id: "EC-003", name: "Integrity Mismatch", type: "corrupted_hash", expectedClass: "Rejected", desc: "If calculated physical audio hash mismatches expected metadata, block ingestion." },
  { id: "EC-004", name: "Duplicate Audio Refs", type: "duplicate_audio", expectedClass: "Accepted", desc: "Two distinct clips sharing identical audio SHA256 checksums map to one file Asset." },
  { id: "EC-005", name: "Broken Parent Trace", type: "broken_parent", expectedClass: "Warning", desc: "Ingesting an extend trace whose parent UUID is missing creates an Unresolved placeholder node." },
  { id: "EC-006", name: "Foreign Payload Fields", type: "schema_resilience", expectedClass: "Accepted", desc: "Retains extra payload fields in ProviderMetadata.raw_json without breaking standard normalization." },
  { id: "EC-007", name: "Full Ledger Replay", type: "db_replay", expectedClass: "Accepted", desc: "Drop database tables and replay 3 sequential seed batches; tests 100% hash/structural determinism." }
];

export default function Component() {
  // Database Tables State (The Ledger Engine)
  const [specifications, setSpecifications] = useState<any[]>([]);
  const [generations, setGenerations] = useState<any[]>([]);
  const [clips, setClips] = useState<any[]>([]);
  const [lineageEdges, setLineageEdges] = useState<any[]>([]);
  const [assets, setAssets] = useState<any[]>([]);
  const [providerMetadata, setProviderMetadata] = useState<any[]>([]);

  // Local Discovery Engine State
  const [watchDirectory, setWatchDirectory] = useState<string>("D:\\Music\\Suno Explorer");
  const [isScanning, setIsScanning] = useState<boolean>(false);
  const [discoveryQueue, setDiscoveryQueue] = useState<number>(3);
  const [incompleteWitnesses, setIncompleteWitnesses] = useState<number>(0);
  const [unresolvedLineages, setUnresolvedLineages] = useState<number>(0);
  const [replayDrift, setReplayDrift] = useState<number>(0);
  const [hashCollisions, setHashCollisions] = useState<number>(0);
  const [scannedFiles, setScannedFiles] = useState<string[]>([
    "Five Witnesses/metadata.json",
    "Five Witnesses/audio.mp3",
    "Five Witnesses/lyrics.txt",
    "Five Witnesses/thumbnail.jpg"
  ]);

  // Replay Validation Protocol State
  const [replayPhase, setReplayPhase] = useState<string>("IDLE");
  const [digestA, setDigestA] = useState<string>("");
  const [digestB, setDigestB] = useState<string>("");
  const [replayStatus, setReplayStatus] = useState<string>("");

  // UI state
  const [selectedSchema, setSelectedSchema] = useState<"elyzareth_dna" | "elyzareth_ledger_event" | "elyzareth_governance" | "elyzareth_physical_assets" | "elyzareth_access_layer" | "elyzareth_discovery">("elyzareth_dna");
  const [terminalLogs, setTerminalLogs] = useState<string[]>([
    "SYS_INIT: ECAM Runtime Console v30.0 Initialized.",
    "SYS_INIT: Discovery Engine binding on: 'D:\\Music\\Suno Explorer'",
    "SYS_INIT: Local Asset Server active on port 8787. Status: WAITING_FOR_CLIENT"
  ]);
  const [selectedTab, setSelectedTab] = useState<"visualizer" | "ledger" | "code">("visualizer");
  const [selectedNode, setSelectedNode] = useState<any | null>(null);
  const [inspectorTab, setInspectorTab] = useState<"properties" | "lineage" | "audit">("properties");
  const [copied, setCopied] = useState<string | null>(null);
  const [lastTestOutcome, setLastTestOutcome] = useState<{ id: string; status: string; note: string } | null>(null);

  // Manual Edge state
  const [edgeSourceId, setEdgeSourceId] = useState<string>("");
  const [edgeSourceType, setEdgeSourceType] = useState<"Upload" | "Clip">("Clip");
  const [edgeTargetId, setEdgeTargetId] = useState<string>("");
  const [edgeTargetType, setEdgeTargetType] = useState<"Upload" | "Clip">("Clip");
  const [edgeRelation, setEdgeRelation] = useState<"Upload" | "Extend" | "Cover" | "Edit" | "Remaster" | "Concat">("Extend");
  const [validationError, setValidationError] = useState<string | null>(null);

  // Copy Clipboard Trigger
  const handleCopy = (key: string, text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(key);
    setTimeout(() => setCopied(null), 2000);
  };

  // Add Log Helper
  const addLog = (msg: string) => {
    const timestamp = new Date().toISOString().split("T")[1].slice(0, -1);
    setTerminalLogs(prev => [...prev, `[${timestamp}] ${msg}`]);
  };

  // Directory Scan trigger
  const triggerDirectoryScan = () => {
    setIsScanning(true);
    addLog(`DISCOVERY: Initializing scanning sweep of '${watchDirectory}'...`);
    setTimeout(() => {
      setIsScanning(false);
      addLog(`DISCOVERY: Scan complete. Found 2 new directories. Discovery Queue: ${discoveryQueue}`);
    }, 1200);
  };

  // Clear Ledger State
  const handleResetLedger = () => {
    setSpecifications([]);
    setGenerations([]);
    setClips([]);
    setLineageEdges([]);
    setAssets([]);
    setProviderMetadata([]);
    setSelectedNode(null);
    setValidationError(null);
    setLastTestOutcome(null);
    setDiscoveryQueue(3);
    setIncompleteWitnesses(0);
    setUnresolvedLineages(0);
    setHashCollisions(0);
    setTerminalLogs([
      "KNL_WARN: Local database tables purged.",
      "KNL_STATUS: Logical time synchronized to T=0.",
      "SYS_INIT: Discovery Engine binding on: 'D:\\Music\\Suno Explorer'"
    ]);
  };

  // Check if target can reach source (DFS Cycle Detection)
  const isReachable = (startId: string, destinationId: string, visited: Set<string>): boolean => {
    if (startId === destinationId) return true;
    if (visited.has(startId)) return false;
    visited.add(startId);

    // Find all active lineage edges where startId is the source
    const neighbors = lineageEdges.filter(e => e.source_id === startId);
    for (const edge of neighbors) {
      if (isReachable(edge.target_id, destinationId, visited)) {
        return true;
      }
    }
    return false;
  };

  // Upstream Provenance Tracer (Trace to Root)
  const computeTraceToRoot = (nodeId: string): any[] => {
    const tracePath = [];
    let currentId = nodeId;
    let iterations = 0;

    // Guard recursion to avoid browser lockup
    while (iterations < 100) {
      const edge = lineageEdges.find(e => e.target_id === currentId);
      if (!edge) break;
      tracePath.push(edge);
      currentId = edge.source_id;
      iterations++;
    }
    return tracePath;
  };

  // Downstream Provenance Tracer (Descendants)
  const computeDescendants = (nodeId: string): string[] => {
    const descendants: string[] = [];
    const queue = [nodeId];
    const visited = new Set<string>([nodeId]);

    while (queue.length > 0) {
      const current = queue.shift()!;
      const neighbors = lineageEdges.filter(e => e.source_id === current);
      for (const edge of neighbors) {
        if (!visited.has(edge.target_id)) {
          visited.add(edge.target_id);
          descendants.push(edge.target_id);
          queue.push(edge.target_id);
        }
      }
    }
    return descendants;
  };

  // Calculate deterministic Digest representaton of current active tables state
  const calculateStateDigest = (
    specs: any[], 
    gens: any[], 
    clps: any[], 
    edges: any[], 
    asts: any[]
  ): string => {
    const contentString = [
      specs.map(s => s.id).sort().join(","),
      gens.map(g => g.id).sort().join(","),
      clps.map(c => c.id + ":" + c.audio_hash).sort().join(","),
      edges.map(e => e.source_id + "->" + e.target_id).sort().join(","),
      asts.map(a => a.clip_id + ":" + a.audio_path).sort().join(",")
    ].join("|");
    return generateHash(contentString);
  };

  // Run the full 4-Phase Replay Verification Protocol live
  const runReplayVerificationProtocol = () => {
    // Phase 1: Seed & Manifest Extract
    setReplayPhase("SEED");
    addLog("REPLAY_TEST [1/4]: Starting Phase 1 (Seed Manifest Generation)...");

    // Ensure seed scenarios are indexed to make the manifest robust
    if (clips.length === 0) {
      executeIngestion(SCENARIOS[0]);
      executeIngestion(SCENARIOS[1]);
      executeIngestion(SCENARIOS[2]);
    }

    const initialDigest = calculateStateDigest(specifications, generations, clips, lineageEdges, assets);
    setDigestA(initialDigest);
    addLog(`REPLAY_TEST [1/4]: Manifest A calculated. StateDigestA = ${initialDigest.slice(0, 16)}...`);

    // Phase 2: Purge Immutable tables
    setTimeout(() => {
      setReplayPhase("PURGE");
      addLog("REPLAY_TEST [2/4]: Starting Phase 2 (Ledger Purging)...");
      addLog("REPLAY_TEST [2/4]: Truncating Specifications, Generations, Clips, Edges, Assets, and ProviderMetadata.");
      addLog("REPLAY_TEST [2/4]: Configuration watched_paths preserved.");

      // Temporary purge memory state
      setSpecifications([]);
      setGenerations([]);
      setClips([]);
      setLineageEdges([]);
      setAssets([]);
      setProviderMetadata([]);
      setSelectedNode(null);
    }, 1200);

    // Phase 3: Deterministic Replay
    setTimeout(() => {
      setReplayPhase("REPLAY");
      addLog("REPLAY_TEST [3/4]: Starting Phase 3 (Uncommitted DiscoveryPackage Replay)...");
      addLog("REPLAY_TEST [3/4]: Playing back DiscoveryPackages (SCEN-A, SCEN-B, SCEN-C) under zero network/random drift.");

      // Reconstitute table rows sequentially from static scenarios
      executeIngestion(SCENARIOS[0]);
      executeIngestion(SCENARIOS[1]);
      executeIngestion(SCENARIOS[2]);
    }, 2400);

    // Phase 4: Compare
    setTimeout(() => {
      setReplayPhase("COMPARE");
      addLog("REPLAY_TEST [4/4]: Starting Phase 4 (State Manifest comparison)...");

      // Compute Digest B
      const finalDigest = calculateStateDigest(specifications, generations, clips, lineageEdges, assets);
      setDigestB(finalDigest);
      addLog(`REPLAY_TEST [4/4]: Manifest B calculated. StateDigestB = ${finalDigest.slice(0, 16)}...`);

      if (initialDigest === finalDigest) {
        setReplayStatus("PASS");
        addLog("KNL_REPLAY_PASS: Replay Invariants verified! Digest A == Digest B. Logical timing drift = 0.00ms. Database replay matches exactly down to the bit.");
      } else {
        setReplayStatus("FAIL");
        addLog("KNL_REPLAY_FAIL: Mismatch detected in replayed hashes! Drift or side-effects detected.");
      }
    }, 3600);
  };

  // Complete Ingestion Cycle (Discovery -> Validation -> Normalization -> Commit)
  const executeIngestion = (scenario: PresetScenario) => {
    const p = scenario.payload;

    // 1. Discovery Phase
    addLog(`DISCOVERY: Identified candidates in folder: '${scenario.name}'`);
    addLog(`DISCOVERY: Loading evidence package: [metadata.json, audio.mp3, lyrics.txt, thumbnail.jpg]`);

    // 2. Validation Phase
    addLog(`VALIDATION: Running local checksum validations on physical binary...`);
    const file_hash = generateHash(`${p.title}_audio_binary`);
    addLog(`VALIDATION: Computed Local SHA-256 footprint: ${file_hash.slice(0, 16)}... [PASS]`);

    // 3. Normalization (L0 Intent Specification Creation)
    const specId = generateHash(p.prompt + p.tags.sort().join(",") + p.model);
    const existingSpec = specifications.find(s => s.id === specId);

    let isSpecNew = false;
    if (!existingSpec) {
      const newSpec = {
        id: specId,
        prompt: p.prompt,
        tags: p.tags,
        model: p.model
      };
      setSpecifications(prev => [...prev, newSpec]);
      isSpecNew = true;
      addLog(`L0_NORMALIZATION: Normalized creative specification. Generated unique Spec ID: ${specId.slice(0, 12)}...`);
    } else {
      addLog(`L0_NORMALIZATION: Specification match found on ledger. Deduplicated reference pointing to spec: ${specId.slice(0, 12)}...`);
    }

    // 4. Ingest L1 Event (Generation Anchor)
    const genId = "gen_" + Math.random().toString(36).substring(2, 10);
    const newGen = {
      id: genId,
      specification_id: specId,
      created_at: p.created_at
    };
    setGenerations(prev => [...prev, newGen]);
    addLog(`L1_LEDGER: Committed immutable Generation event anchor [${genId}] logical_timestamp=${p.created_at}`);

    // 5. Ingest L1 Clips and Lines
    const addedClips: any[] = [];
    const addedEdges: any[] = [];
    const addedAssets: any[] = [];
    const addedMeta: any[] = [];

    p.clips.forEach(c => {
      const audioHash = generateHash(`${c.id}_audio_binary`);
      const metaHash = generateHash(`${c.id}_raw_payload_json`);

      const newClip = {
        id: c.id,
        generation_id: genId,
        variant: c.variant,
        variant_total: p.clips.length,
        duration_ms: Math.round(c.duration_s * 1000),
        audio_hash: audioHash,
        metadata_hash: metaHash,
        title: `${p.title} (v${c.variant})`,
        witness_status: "Verified"
      };
      addedClips.push(newClip);

      if (c.parent_id && c.parent_type && c.relation_type) {
        const edge = {
          source_id: c.parent_id,
          source_type: c.parent_type,
          target_id: c.id,
          target_type: "Clip",
          relation: c.relation_type
        };
        addedEdges.push(edge);
      }

      const asset = {
        clip_id: c.id,
        audio_path: `${watchDirectory}\\${p.title}\\audio.mp3`,
        thumbnail_path: `${watchDirectory}\\${p.title}\\thumbnail.jpg`,
        lyrics_path: `${watchDirectory}\\${p.title}\\lyrics.txt`,
        metadata_path: `${watchDirectory}\\${p.title}\\metadata.json`
      };
      addedAssets.push(asset);

      const meta = {
        clip_id: c.id,
        provider: p.model.startsWith("suno") ? "Suno" : "Custom",
        provider_clip_id: `provider_id_${c.id.slice(0,8)}`,
        raw_json_hash: generateHash(`provider_json_${c.id}`),
        imported_at: new Date().toISOString()
      };
      addedMeta.push(meta);
    });

    setClips(prev => [...prev, ...addedClips]);
    setLineageEdges(prev => [...prev, ...addedEdges]);
    setAssets(prev => [...prev, ...addedAssets]);
    setProviderMetadata(prev => [...prev, ...addedMeta]);

    // Update operational dashboard variables
    setDiscoveryQueue(prev => Math.max(0, prev - 1));

    // Logging L2 edge creation
    if (addedEdges.length > 0) {
      addedEdges.forEach(edge => {
        addLog(`L2_LINEAGE: Established mutation link [${edge.source_id.slice(0, 8)}] &rarr; [${edge.target_id.slice(0, 8)}] via ${edge.relation.toUpperCase()}`);
      });
    }

    addedClips.forEach(clip => {
      addLog(`L1_WITNESS: Registered Audio Witness [${clip.id.slice(0, 8)}] (${(clip.duration_ms/1000).toFixed(2)}s).`);
    });

    addLog(`KNL_COMMIT: Block Sealed! Creative lineage graph successfully expanded.`);
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-slate-950 text-slate-100 font-sans p-4">

      {/* Header summary bar */}
      <div className="w-full max-w-7xl flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 mb-6 border-b border-slate-800 pb-5">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="px-2 py-0.5 text-xs font-mono bg-emerald-950 text-emerald-400 border border-emerald-800 rounded">v30.0 RUNTIME</span>
            <span className="text-slate-400 text-sm font-mono">// Elyzareth OS Local Asset Control Console</span>
          </div>
          <h1 className="text-2xl md:text-3xl font-extrabold tracking-tight bg-gradient-to-r from-emerald-400 to-violet-400 bg-clip-text text-transparent">
            Sovereign Ledger Console
          </h1>
        </div>

        {/* Server state HUD */}
        <div className="flex flex-wrap items-center gap-4 text-xs font-mono">
          <div className="p-2 rounded bg-slate-900 border border-slate-850 flex items-center gap-2">
            <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-ping"></span>
            <span className="text-slate-400">Server: <strong className="text-emerald-400">localhost:8787</strong></span>
          </div>
          <button 
            onClick={handleResetLedger}
            className="flex items-center gap-2 px-3 py-2 rounded-lg border border-red-900 bg-red-950/20 text-red-400 hover:bg-red-950/50 transition"
          >
            <Trash2 className="w-3.5 h-3.5" /> Purge DB
          </button>
        </div>
      </div>

      {/* Operational Metrics KPIs */}
      <div className="w-full max-w-7xl grid grid-cols-2 md:grid-cols-6 gap-4 mb-6">
        <div className="p-3.5 rounded-xl bg-slate-900/50 border border-slate-850 flex flex-col">
          <span className="text-slate-500 text-[10px] uppercase font-mono tracking-wider mb-1">Discovery Queue</span>
          <span className={`text-xl font-mono font-bold ${discoveryQueue > 0 ? "text-amber-400 animate-pulse" : "text-slate-400"}`}>{discoveryQueue} Candidates</span>
        </div>
        <div className="p-3.5 rounded-xl bg-slate-900/50 border border-slate-850 flex flex-col">
          <span className="text-slate-500 text-[10px] uppercase font-mono tracking-wider mb-1">Incomplete Witnesses</span>
          <span className="text-xl font-mono font-bold text-slate-100">{incompleteWitnesses} Files missing</span>
        </div>
        <div className="p-3.5 rounded-xl bg-slate-900/50 border border-slate-850 flex flex-col">
          <span className="text-slate-500 text-[10px] uppercase font-mono tracking-wider mb-1">Unresolved Lineages</span>
          <span className="text-xl font-mono font-bold text-slate-100">{unresolvedLineages} Orphaning</span>
        </div>
        <div className="p-3.5 rounded-xl bg-slate-900/50 border border-slate-850 flex flex-col">
          <span className="text-slate-500 text-[10px] uppercase font-mono tracking-wider mb-1">Deduplicated Specs</span>
          <span className="text-xl font-mono font-bold text-blue-400">{specifications.length} Layer 0</span>
        </div>
        <div className="p-3.5 rounded-xl bg-slate-900/50 border border-slate-850 flex flex-col">
          <span className="text-slate-500 text-[10px] uppercase font-mono tracking-wider mb-1">Replay Drift</span>
          <span className="text-xl font-mono font-bold text-emerald-400">{replayDrift} ms</span>
        </div>
        <div className="p-3.5 rounded-xl bg-slate-900/50 border border-slate-850 flex flex-col">
          <span className="text-slate-500 text-[10px] uppercase font-mono tracking-wider mb-1">Hash Collisions</span>
          <span className="text-xl font-mono font-bold text-slate-100">{hashCollisions} Shared Files</span>
        </div>
      </div>

      {/* Main Grid Layout */}
      <div className="w-full max-w-7xl grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Left Column: Local Discovery Engine Panel */}
        <div className="lg:col-span-4 flex flex-col gap-6">

          {/* Watched Directory Panel */}
          <div className="rounded-xl border border-slate-800 bg-slate-900/60 p-5 flex flex-col gap-4">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <Folder className="w-4 h-4 text-emerald-400" />
                <h2 className="text-sm font-mono font-bold tracking-wider uppercase text-slate-300">Local Discovery Engine</h2>
              </div>
              <span className="px-1.5 py-0.5 rounded bg-emerald-950 text-emerald-400 border border-emerald-800 text-[9px] font-mono animate-pulse">WATCHING</span>
            </div>

            <div className="text-xs font-mono space-y-3">
              <div>
                <label className="text-[10px] text-slate-500 block mb-1">WATCHING FILE SYSTEM PATH:</label>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={watchDirectory}
                    onChange={(e) => setWatchDirectory(e.target.value)}
                    className="flex-1 bg-slate-950 border border-slate-850 p-2 rounded text-slate-300 text-xs focus:border-emerald-500 focus:outline-none"
                  />
                  <button 
                    onClick={triggerDirectoryScan}
                    disabled={isScanning}
                    className="px-3 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-800 text-slate-950 font-bold rounded flex items-center justify-center transition"
                  >
                    <RefreshCw className={`w-3.5 h-3.5 ${isScanning ? "animate-spin" : ""}`} />
                  </button>
                </div>
              </div>

