export const RUST_SCHEMAS = {
  elyzareth_dna: `// crate: elyzareth-dna (L0: The Intent Specification Crate)
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Specification {
    /// SHA-256 fingerprint of (prompt + sorted_tags + model)
    pub id: SpecificationId,
    pub prompt: String,
    pub tags: Vec<String>,
    pub model: String,
}

impl Specification {
    pub fn calculate_id(prompt: &str, tags: &[String], model: &str) -> SpecificationId {
        let mut hasher = sha2::Sha256::new();
        hasher.update(prompt.as_bytes());
        let mut sorted_tags = tags.to_vec();
        sorted_tags.sort();
        for tag in sorted_tags {
            hasher.update(tag.as_bytes());
        }
        hasher.update(model.as_bytes());
        SpecificationId(hasher.finalize().into())
    }
}
`,

  elyzareth_ledger_event: `// crate: elyzareth-ledger (L1: The Execution & Witness Crate)
use chrono::{DateTime, Utc};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaMetadata {
    pub schema_version: u32,
    pub adr_version: String,
    pub kernel_version: String,
    pub created_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Generation {
