}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Clip {
    pub id: ClipId,
    pub generation_id: GenerationId,
    pub variant: u8,
    pub variant_total: u8,
    pub duration_ms: u64,
    pub audio_hash: Sha256Hash,
