}
`,

  elyzareth_governance: `// crate: elyzareth-catalog (L2: The Governance / Provenance Graph)
use serde::{Deserialize, Serialize};
use std::collections::HashSet;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum NodeId {
    Upload(UploadId),
    Clip(ClipId),
    /// Unresolved node reference for handling broken parent chains gracefully
    Unresolved(String),
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum LineageRelation {
    Upload,
    Extend,
    Cover,
    Edit,
    Remaster,
    Concat,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LineageEdge {
    pub source: NodeId,
    pub target: NodeId,
    pub relation: LineageRelation,

    // Enforces ADR-025: Transition and rationale metadata
    pub transition_offset_ms: Option<u64>,
    pub rationale: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum IngestionClassification {
    Accepted,
    AcceptedWithWarnings(String),
    Rejected(String),
}

/// Robust Transaction Kernel managing edge cases and idempotency invariants
pub trait IngestionKernel {
    /// Idempotency Guard (EC-001): Checks if Clip already exists on disk or ledger
    fn check_duplicate_clip(&self, clip_id: &ClipId) -> Option<&Clip>;

    /// Invariant 1: Cycle Detection
    fn check_acyclicity(&self, source: &NodeId, target: &NodeId) -> bool;

    /// Invariant Rule: Classifies an incoming transaction
    fn classify_transaction(
        &self,
        clip: &Clip,
        parent: Option<&NodeId>,
        has_physical_audio: bool,
    ) -> IngestionClassification;
}

pub struct ComplianceHarness<'a> {
    pub active_clips: &'a [Clip],
    pub active_edges: &'a [LineageEdge],
}

impl<'a> IngestionKernel for ComplianceHarness<'a> {
    fn check_duplicate_clip(&self, clip_id: &ClipId) -> Option<&Clip> {
        self.active_clips.iter().find(|c| &c.id == clip_id)
    }

    fn check_acyclicity(&self, source: &NodeId, target: &NodeId) -> bool {
        if source == target {
            return false;
        }
        let mut visited = HashSet::new();
        !self.is_reachable(target, source, &mut visited)
    }

    fn classify_transaction(
        &self,
        clip: &Clip,
        parent: Option<&NodeId>,
        has_physical_audio: bool,
    ) -> IngestionClassification {
        // EC-001 Check duplicate
        if self.check_duplicate_clip(&clip.id).is_some() {
            return IngestionClassification::AcceptedWithWarnings(
                "Idempotent Match: Ingestion skipped, Clip already securely recorded.".to_string()
            );
        }

        // EC-003 Check Corrupted binary
        if clip.witness_status == WitnessStatus::CorruptedWitness {
            return IngestionClassification::Rejected(
                "Integrity Fault: Physical checksum mismatch detected!".to_string()
            );
        }

        // EC-002 Check Missing audio
        if !has_physical_audio {
            return IngestionClassification::AcceptedWithWarnings(
                "Incomplete Witness: Ingested metadata, but physical audio binary is missing.".to_string()
            );
        }

        // EC-005 Broken lineage check
        if let Some(NodeId::Unresolved(parent_id)) = parent {
            return IngestionClassification::AcceptedWithWarnings(
                format!("Broken Lineage: Edge resolved to Unresolved({}) to protect history.", parent_id)
            );
        }

        IngestionClassification::Accepted
    }
}

impl<'a> ComplianceHarness<'a> {
    fn is_reachable(&self, current: &NodeId, destination: &NodeId, visited: &mut HashSet<NodeId>) -> bool {
        if current == destination {
            return true;
        }
        if !visited.insert(current.clone()) {
            return false;
        }
        for edge in self.active_edges.iter().filter(|e| &e.source == current) {
            if self.is_reachable(&edge.target, destination, visited) {
                return true;
            }
        }
        false
    }
}
`,

