  elyzareth_access_layer: `// crate: elyzareth-access (L3: Local Access & Publication Layer)
// Enforces ADR-023: Sovereign local access to files and metadata
use axum::{
    routing::{get, post},
    extract::{Path, State},
    response::{IntoResponse, Response},
    Json, Router,
};
use std::sync::Arc;
use std::path::PathBuf;

pub struct ServerState {
    pub db_connection: Arc<DatabaseConnection>,
    pub local_storage_path: PathBuf,
}

pub fn create_access_layer_router(state: Arc<ServerState>) -> Router {
    Router::new()
        // Standard L3 Local API endpoints consumed by Flow offline client
        .route("/api/v1/library", get(get_library))
        .route("/api/v1/clip/:id", get(get_clip_by_id))
        .route("/api/v1/lineage/:id", get(get_lineage_by_id))
        .route("/api/v1/assets/stream/:id", get(stream_local_audio))
        .with_state(state)
}

/// GET /api/v1/library
async fn get_library(
    State(state): State<Arc<ServerState>>,
) -> Json<Vec<ClipListItem>> {
    let library = state.db_connection.fetch_all_clips().unwrap();
    Json(library)
}

/// GET /api/v1/clip/:id
async fn get_clip_by_id(
    Path(id): Path<String>,
    State(state): State<Arc<ServerState>>,
) -> Json<ClipDetailResponse> {
    let clip = state.db_connection.get_clip(&id).unwrap();
    let spec = state.db_connection.get_spec_by_clip(&id).unwrap();

    Json(ClipDetailResponse {
        clip_id: clip.id,
        title: clip.title,
        duration_ms: clip.duration_ms,
        specification: spec,
        audio_stream_url: format!("/api/v1/assets/stream/{}", clip.id),
        artwork_url: format!("/srv/assets/artwork/{}.webp", clip.id),
    })
}

/// GET /api/v1/assets/stream/:id
async fn stream_local_audio(
    Path(id): Path<String>,
    State(state): State<Arc<ServerState>>,
) -> Response {
    let asset = state.db_connection.get_asset_by_clip(&id).unwrap();
    let audio_file_path = state.local_storage_path.join(asset.audio_path);

    let file = tokio::fs::File::open(audio_file_path).await.unwrap();
    let body = axum::body::Body::from_stream(tokio_util::io::ReaderStream::new(file));

    Response::builder()
        .header("content-type", "audio/mpeg")
        .header("cross-origin-resource-policy", "cross-origin")
        .body(body)
        .unwrap()
        .into_response()
}
