export default function AdrRegistry() {
  const [selectedAdr, setSelectedAdr] = useState<ADR>(ADR_LIST[0]);
  const [signatures, setSignatures] = useState<Record<string, string>>({});
  const [isSigning, setIsSigning] = useState(false);

  const handleSign = (adrId: string) => {
    setIsSigning(true);
    setTimeout(() => {
      // Simulate cryptographic hash generation based on ADR fields
      const dateString = new Date().toISOString();
      const mockHash = `EOSIG-2026-${adrId}-${Math.random().toString(36).substring(2, 10).toUpperCase()}-SHA256`;
      setSignatures((prev) => ({ ...prev, [adrId]: mockHash }));
      setIsSigning(false);
    }, 1200);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 font-mono text-xs">
      {/* ADR Sidebar Selector */}
