          Architectural Decision Records form the constitution. Changes require signing to maintain the logical provenance.
        </p>

        <div className="space-y-2">
          {ADR_LIST.map((adr) => {
            const signed = !!signatures[adr.id];
            return (
              <button
                key={adr.id}
                onClick={() => setSelectedAdr(adr)}
                className={`w-full text-left p-3 rounded transition-all duration-250 border flex flex-col gap-1 ${
                  selectedAdr.id === adr.id
                    ? "bg-indigo-950/40 border-indigo-500/80 text-indigo-200"
                    : "bg-neutral-950/60 border-neutral-850 hover:border-neutral-800 text-neutral-400"
                }`}
              >
                <div className="flex items-center justify-between w-full">
                  <span className="font-bold text-neutral-300">{adr.id}</span>
                  <span className={`text-[10px] px-1.5 py-0.2 rounded font-bold ${
                    signed ? "bg-emerald-950/40 text-emerald-400 border border-emerald-900/40" : "bg-yellow-950/30 text-yellow-500 border border-yellow-900/30"
                  }`}>
                    {signed ? "SIGNED & SEALED" : "ACCEPTED (UNRELEASED)"}
                  </span>
                </div>
                <div className="text-neutral-300 font-semibold line-clamp-1">{adr.title}</div>
                <div className="text-[10px] text-neutral-500 mt-1 flex justify-between">
