      <div className="lg:col-span-7 bg-neutral-900 border border-neutral-800 rounded-lg p-5 flex flex-col justify-between">
        <div>
          <div className="flex items-center justify-between border-b border-neutral-800 pb-3 mb-4">
            <div className="flex items-center gap-2">
              <Lock className="w-4 h-4 text-indigo-400 animate-pulse" />
              <h3 className="font-bold text-neutral-200 uppercase tracking-wider text-sm">{selectedAdr.id} — Readout</h3>
            </div>
            <span className="text-neutral-500 font-bold">{selectedAdr.date}</span>
          </div>

          <h2 className="text-sm font-bold text-neutral-100 mb-4">{selectedAdr.title}</h2>

          <div className="space-y-4 pr-1">
            <div className="bg-neutral-950 p-3 rounded border border-neutral-850">
