import React, { useState, useEffect, useRef } from "react";
import { Activity, Play, RefreshCw, CheckCircle2, ShieldAlert, Cpu, Hash, Binary, ShieldCheck } from "lucide-react";

interface AuditLog {
  timestamp: string;
  module: string;
  event: string;
  message: string;
  hash?: string;
  type: "info" | "success" | "warn" | "contract";
}

export default function InteractiveAudit() {
  const [isRunning, setIsRunning] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [spfHash, setSpfHash] = useState<string>("");
  const [exfHash, setExfHash] = useState<string>("");
  const [stats, setStats] = useState({ itemsScanned: 0, verifiedInvariants: 0, integrityPass: 0 });
  const logsEndRef = useRef<HTMLDivElement | null>(null);

  const steps = [
    {
      module: "Provider Driver (PAL)",
      event: "RawPayloadDispatched",
      message: "Dispatched raw Suno Chirp payload stream. Intercepting network requests and headers...",
      type: "info" as const
    },
    {
      module: "Discovery Engine",
      event: "EnvelopeGenerated",
      message: "Wrapped raw response in a write-once DiscoveryEnvelope. Sealed retrieved_at: 1721520000.",
      type: "success" as const,
      stat: "itemsScanned"
    },
    {
      module: "Normalizer Engine",
      event: "PayloadNormalized",
      message: "Standardizing keys into provider-agnostic L3 formats (modelSeed, stylePrompt, originalTitle).",
      type: "contract" as const,
      generateSpf: true
    },
    {
      module: "Identity Resolver",
      event: "IdentityResolved",
      message: "Resolving lineage. Match detected: Associated normalized payload with Creative Identity 'Cinematic Horizons' (ID-HORIZONS). Linked as version overlay.",
      type: "contract" as const
    },
    {
      module: "AssetAcquisitionEngine (AAE)",
      event: "StreamActive",
      message: "Engaging stateless streaming buffer capture for audio segments, companion LRC files, and high-res art assets.",
      type: "info" as const
    },
    {
      module: "Lyrics Engine",
      event: "LyricsIngested",
      message: "Parsed sync lyric timelines. Writing provider-agnostic LRC formatting to disk workspace cache.",
      type: "success" as const
    },
    {
      module: "Integrity Engine",
      event: "IntegrityVerified",
      message: "Running CTS check. Matching size-on-disk headers against envelope checksum boundaries.",
      type: "contract" as const,
      stat: "integrityPass"
    },
    {
      module: "Asset Intelligence Engine (AIE)",
      event: "LineageMapped",
      message: "Computed stylistic similarity vector density. Appending emotional vector mapping parameters to relationship graph.",
      type: "success" as const
    },
    {
      module: "Creative DNA Engine",
      event: "VerificationPassed",
      message: "Sealing physical binaries and normalization descriptors with dual-hash lock (SPF spec & EXF execution hashes).",
      type: "success" as const,
      generateExf: true,
      stat: "verifiedInvariants"
    },
    {
      module: "KernelBus",
      event: "Completed",
      message: "Transaction logged in immutable append-only ledger safely. Acquisition loop completed.",
      type: "success" as const
    }
  ];

  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [logs]);

  const addLog = (log: AuditLog) => {
    setLogs((prev) => [...prev, log]);
  };

  const runSimulation = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setLogs([]);
    setCurrentStep(0);
    setSpfHash("");
    setExfHash("");

    addLog({
      timestamp: new Date().toLocaleTimeString(),
      module: "KernelBus",
      event: "Boot",
      message: "Bootstrapping deterministic execution context for ESS. Verifying CTS module integrity...",
      type: "info"
    });

    for (let i = 0; i < steps.length; i++) {
      await new Promise((resolve) => setTimeout(resolve, 1400));
      setCurrentStep(i + 1);
      const step = steps[i];

      let generatedHash = "";
      if (step.generateSpf) {
        const hash = "SPF-" + Math.random().toString(36).substring(2, 10).toUpperCase() + "-X";
        setSpfHash(hash);
        generatedHash = hash;
      }
      if (step.generateExf) {
        const hash = "EXF-" + Math.random().toString(36).substring(2, 10).toUpperCase() + "-K";
        setExfHash(hash);
        generatedHash = hash;
      }

      addLog({
        timestamp: new Date().toLocaleTimeString(),
        module: step.module,
        event: step.event,
        message: step.message,
        hash: generatedHash || undefined,
        type: step.type
      });

      if (step.stat) {
        setStats((prev) => ({
          ...prev,
          [step.stat as string]: prev[step.stat as keyof typeof prev] + 1
        }));
      }
    }
    setIsRunning(false);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 font-mono text-xs">
      {/* Left Column: Diagnostics & Control */}
      <div className="lg:col-span-4 bg-neutral-900 border border-neutral-800 rounded-lg p-5 flex flex-col justify-between">
        <div>
          <div className="flex items-center gap-2 mb-4 border-b border-neutral-800 pb-3">
            <Cpu className="w-5 h-5 text-emerald-400" />
            <h3 className="font-bold text-neutral-200 uppercase tracking-wider text-sm">Ingestion Diagnostic</h3>
          </div>

          {/* Core Counters */}
          <div className="grid grid-cols-3 gap-2 mb-6">
            <div className="bg-neutral-950 p-2 border border-neutral-850 rounded text-center">
              <span className="text-[10px] text-neutral-500 block uppercase">Scanned</span>
              <span className="text-sm font-bold text-neutral-300">{stats.itemsScanned}</span>
            </div>
            <div className="bg-neutral-950 p-2 border border-neutral-850 rounded text-center">
              <span className="text-[10px] text-neutral-500 block uppercase">CTS Invariants</span>
              <span className="text-sm font-bold text-indigo-400">{stats.verifiedInvariants}</span>
            </div>
            <div className="bg-neutral-950 p-2 border border-neutral-850 rounded text-center">
              <span className="text-[10px] text-neutral-500 block uppercase">Integrity Passes</span>
              <span className="text-sm font-bold text-emerald-500">{stats.integrityPass}</span>
            </div>
          </div>

          {/* Hash Sealing Status */}
          <div className="space-y-3">
            <div>
              <div className="flex justify-between items-center mb-1">
                <span className="text-[10px] text-neutral-400 font-bold uppercase">Specification Hash (SPF)</span>
                {spfHash ? <span className="text-[9px] bg-indigo-950 text-indigo-400 border border-indigo-900/60 px-1 rounded font-bold">SEALED</span> : <span className="text-[9px] text-neutral-500">PENDING</span>}
              </div>
              <div className="bg-neutral-950 p-2 border border-neutral-850 rounded text-neutral-300 flex items-center gap-1.5 h-8">
                {spfHash ? (
                  <>
                    <Hash className="w-3.5 h-3.5 text-indigo-400 shrink-0" />
                    <span className="font-mono text-[10px] text-indigo-300 select-all">{spfHash}</span>
                  </>
                ) : (
                  <span className="text-neutral-600 italic">No asset metadata sealed yet</span>
                )}
              </div>
            </div>

            <div>
              <div className="flex justify-between items-center mb-1">
                <span className="text-[10px] text-neutral-400 font-bold uppercase">Execution Hash (EXF)</span>
                {exfHash ? <span className="text-[9px] bg-emerald-950 text-emerald-400 border border-emerald-900/60 px-1 rounded font-bold">ATTESTED</span> : <span className="text-[9px] text-neutral-500">PENDING</span>}
              </div>
              <div className="bg-neutral-950 p-2 border border-neutral-850 rounded text-neutral-300 flex items-center gap-1.5 h-8">
                {exfHash ? (
                  <>
                    <Binary className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                    <span className="font-mono text-[10px] text-emerald-300 select-all">{exfHash}</span>
                  </>
                ) : (
                  <span className="text-neutral-600 italic">No creative DNA generated yet</span>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Action Controls */}
        <div className="pt-4 mt-6 border-t border-neutral-800">
          <button
            disabled={isRunning}
            onClick={runSimulation}
            className={`w-full py-2.5 rounded font-bold flex items-center justify-center gap-2 transition-all ${
              isRunning
                ? "bg-neutral-800 text-neutral-500 cursor-not-allowed"
                : "bg-emerald-600 hover:bg-emerald-500 active:bg-emerald-700 text-white shadow-lg shadow-emerald-950/20"
            }`}
          >
            {isRunning ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                <span>AUDITING CYCLE ACTIVE...</span>
              </>
            ) : (
              <>
                <Play className="w-4 h-4 fill-white" />
                <span>START DETERMINISTIC INGESTION</span>
              </>
            )}
          </button>
        </div>
      </div>

