                    driver.status === "ACTIVE" ? "bg-emerald-950/40 text-emerald-400 border border-emerald-900/30" : "bg-neutral-900 text-neutral-600 border border-neutral-850"
                  }`}>{driver.status}</span>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Selected Driver Contracts checklist */}
        <div className="bg-neutral-950 p-4 rounded border border-neutral-850 font-mono text-xs">
          <div className="flex items-center gap-1.5 mb-2.5">
            <Layers className="w-4 h-4 text-indigo-400" />
            <span className="font-bold text-neutral-300 uppercase">Driver Interface Bounds</span>
          </div>

          <div className="grid grid-cols-2 gap-2 text-[10px]">
            {["Scan()", "Acquire()", "Metadata()", "Artwork()", "Lyrics()", "Relationships()"].map((contract) => {
              const supported = selectedDriver.supportedContracts.includes(contract);
              return (
                <div key={contract} className="flex items-center gap-2 bg-neutral-900 p-1.5 rounded border border-neutral-850/50">
                  <div className={`w-1.5 h-1.5 rounded-full shrink-0 ${supported ? "bg-emerald-500" : "bg-neutral-700"}`} />
                  <span className={supported ? "text-neutral-300 font-bold" : "text-neutral-600 line-through"}>{contract}</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { 
  Play, RotateCcw, AlertTriangle, ShieldCheck, Cpu, Database, 
  Activity, RefreshCw, Terminal as TermIcon, CheckCircle2, XCircle, 
  Hash, Clock, Settings, Layers, PlayCircle, Eye, ShieldAlert
} from "lucide-react";

import { Kernel } from "./kernel";
import { KernelState } from "./state";
import { ConsolidatedReport, ReplayReport } from "./diagnostics";

// --- SPRINT 1.4: IMPORTS FROM SPEC-COMPILING RUNTIME SUBMODULES ---
import { Task, TaskState, TaskFactory } from "./task";
import { Scheduler, PolicyEngine, ExecutionPlan } from "./scheduler";
import { RuntimeOrchestrator, RuntimeReport } from "./orchestrator";

export default function SovereignKernelTerminal() {
  // Instantiates the production facades strictly as single sources of truth (Section 9.0)
  const kernelRef = useRef<Kernel>(new Kernel());
  const orchestratorRef = useRef<RuntimeOrchestrator>(new RuntimeOrchestrator(kernelRef.current));
  const schedulerRef = useRef<Scheduler>(new Scheduler(new PolicyEngine({ max_priority_level: 5, allow_circular_dependencies: false })));

  // Tab Controller on Right Column: "bus" (Event Sequencer) | "orchestrator" (Task Scheduler)
  const [activeTab, setActiveTab] = useState<"bus" | "orchestrator">("orchestrator");

  // Single-source passive React state: derived purely from ConsolidatedReport & RuntimeReport
  const [report, setReport] = useState<ConsolidatedReport | null>(null);
  const [runtimeReport, setRuntimeReport] = useState<RuntimeReport | null>(null);
  const [activePlan, setActivePlan] = useState<ExecutionPlan | null>(null);
  const [tasksList, setTasksList] = useState<Task[]>([]);

  // Testing variables
  const [injectCycle, setInjectCycle] = useState<boolean>(false);
  const [corruptReplay, setCorruptReplay] = useState<boolean>(false);
  const [replayResult, setReplayResult] = useState<ReplayReport | null>(null);
  const [isReplaying, setIsReplaying] = useState<boolean>(false);
  const [consoleLogs, setConsoleLogs] = useState<string[]>([]);
  const [orchestratorState, setOrchestratorState] = useState<"Idle" | "Running" | "Completed">("Idle");

  const logsEndRef = useRef<HTMLDivElement>(null);

  // Sync snapshot and seed tasks upon initial load
  useEffect(() => {
    // Scaffold initial strict task structures (Section 1.4.1)
    orchestratorRef.current.registerTask(TaskFactory.create("metadata.commit", "elyzareth.observability.lens", "commit_0x9FA2", 4, []));
    orchestratorRef.current.registerTask(TaskFactory.create("lyrics.compile", "elyzareth.lyrics.engine", "compile_EVID_GRAPH", 3, ["metadata.commit"]));
    orchestratorRef.current.registerTask(TaskFactory.create("dsp.render", "elyzareth.dsp.spectrum", "render_spectral_FFT", 2, ["lyrics.compile"]));
    orchestratorRef.current.registerTask(TaskFactory.create("replay.audit", "elyzareth.replay.audit", "audit_CTS_re-run", 1, ["dsp.render"]));

    syncState();
    setConsoleLogs(["[SYSTEM] Sovereign Kernel Terminal offline. Awaiting BootPlan sequence load."]);
  }, []);

  useEffect(() => {
    if (logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [consoleLogs]);

  // Synchronize passive UI snapshot from kernel and orchestrator authoritative state
  const syncState = (customLogs?: string[]) => {
    const snap = kernelRef.current.snapshot();
    setReport(snap);
    setRuntimeReport(orchestratorRef.current.generateReport());
    setTasksList(Array.from(orchestratorRef.current.getTasks().values()));
    setActivePlan(orchestratorRef.current.getActivePlan() || null);
    if (customLogs) {
      setConsoleLogs(prev => [...prev, ...customLogs]);
    }
  };

  // --- FAÇADE INTERFACE HANDLERS (SECTION 9.0 - STRICT NO SETTERS) ---
  const handleStepPhase = () => {
    const nextSnap = kernelRef.current.boot(injectCycle);
    setReport(nextSnap);
    setConsoleLogs(prev => [...prev, `[BOOT] Phase advanced step-wise (Current State: ${nextSnap.snapshot.state})`]);
  };

  const handleAutoBoot = () => {
    const nextSnap = kernelRef.current.boot(injectCycle);
    setReport(nextSnap);
    setConsoleLogs(prev => [...prev, `[BOOT] Automated bootstrap completed safely.`]);
  };

  const handleHaltCore = () => {
    const nextSnap = kernelRef.current.shutdown();
    orchestratorRef.current.resetTasks();
    setOrchestratorState("Idle");
    setReport(nextSnap);
    setRuntimeReport(orchestratorRef.current.generateReport());
    setTasksList(Array.from(orchestratorRef.current.getTasks().values()));
    setActivePlan(null);
    setConsoleLogs(prev => [...prev, `[SYSTEM] Kernel shutdown processed. All clocks and tasks frozen.`]);
  };

  const handleWarmReboot = () => {
    const nextSnap = kernelRef.current.warm_reboot();
    orchestratorRef.current.resetTasks();
    setOrchestratorState("Idle");
    setReport(nextSnap);
    setRuntimeReport(orchestratorRef.current.generateReport());
    setTasksList(Array.from(orchestratorRef.current.getTasks().values()));
    setActivePlan(null);
    setConsoleLogs(prev => [...prev, `[SYSTEM] Warm reboot executed. Advanced Clock to Epoch ${nextSnap.snapshot.epoch}.`]);
  };

  const handleDispatch = (typeId: string, payload: string) => {
    const nextSnap = kernelRef.current.dispatch(typeId, payload);
    setReport(nextSnap);
    setConsoleLogs(prev => [...prev, `[EVENT] Dispatched unsorted "${typeId}" event.`]);
  };

  const handleSequenceAndFlush = () => {
    const nextSnap = kernelRef.current.process_queues();
    setReport(nextSnap);
    setConsoleLogs(prev => [...prev, `[SEQUENCER] Chronological sort executed. Advanced Tick to: ${nextSnap.snapshot.tick}.`]);
  };

  const handleReplayAudit = () => {
    if (!report) return;
    setIsReplaying(true);
    setReplayResult(null);

    setTimeout(() => {
      const audit = kernelRef.current.replay_audit(corruptReplay);
      setReplayResult(audit);
      setIsReplaying(false);
      setConsoleLogs(prev => [...prev, `[AUDIT] CTS Replay Check completed: ${audit.parity_match ? "PASSED" : "FAILED"}`]);
    }, 1000);
  };

  // --- SPRINT 1.4: SCHEDULER & ORCHESTRATION HANDLERS ---
  const handleCompilePlan = () => {
    if (snapshot.state !== KernelState.Active) {
      setConsoleLogs(prev => [...prev, `[REJECTED] Schedulers and admission require an ACTIVE kernel state.`]);
      return;
    }
    try {
      // The UI never calls the scheduler directly. It routes through Orchestrator repositories
      const plan = schedulerRef.current.schedule(orchestratorRef.current.getTasks());
      orchestratorRef.current.resetTasks();
      setOrchestratorState("Idle");
      setConsoleLogs(prev => [...prev, `[SCHEDULER] Compiled ExecutionPlan ${plan.plan_id} (topologically sorted order: ${plan.ordered_task_ids.join(" -> ")})`]);
      syncState();
    } catch (err: any) {
      setConsoleLogs(prev => [...prev, `[SCHEDULER ERROR] ${err.message}`]);
    }
  };

  const handleExecutePlan = () => {
    const plan = orchestratorRef.current.getActivePlan();
    if (!plan) {
      setConsoleLogs(prev => [...prev, `[REJECTED] No active plan compiled. Select "Compile Plan" first.`]);
      return;
    }

    setOrchestratorState("Running");
    orchestratorRef.current.executePlan(plan, (rReport, kSnap) => {
      setReport(kSnap);
      setRuntimeReport(rReport);
      setTasksList(Array.from(orchestratorRef.current.getTasks().values()));
      setConsoleLogs(prev => [...prev, `[ORCHESTRATOR] Advanced plan execution tick. Task queues flushed.`]);

      const finished = rReport.completed_count === rReport.total_tasks;
      if (finished) {
        setOrchestratorState("Completed");
      }
    });
  };

  const handleResetOrchestrator = () => {
    orchestratorRef.current.resetTasks();
    setOrchestratorState("Idle");
    syncState([`[ORCHESTRATOR] Subsystems reset. All tasks returned to Queued status.`]);
  };

  if (!report) return null;

  const { snapshot, health, invariants, system_integrity_hash } = report;

  return (
    <div className="min-h-screen w-full bg-slate-950 text-slate-100 flex flex-col font-sans p-4 md:p-6 select-none font-mono">

      {/* Header Panel */}
      <header className="border-b border-slate-800 pb-4 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="bg-emerald-500/10 p-2 rounded-lg border border-emerald-500/20">
            <Cpu className="w-6 h-6 text-emerald-400 animate-pulse" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-lg font-bold tracking-wider text-slate-200">ELYZARETH OS</h1>
              <span className="bg-slate-800 text-xs px-2 py-0.5 rounded text-slate-400 font-mono">DEBUGGER-v30.1</span>
            </div>
            <p className="text-xs text-slate-400">Section 7.0 Consolidated Read-Only Diagnostic Workspace</p>
          </div>
        </div>

        {/* Passive Diagnostic Clock Readout */}
        <div className="flex items-center gap-6 text-sm font-mono bg-slate-900 px-4 py-2.5 rounded-lg border border-slate-800">
          <div className="flex flex-col">
            <span className="text-[10px] text-slate-500 uppercase tracking-wider">State Machine</span>
            <span className={`font-bold ${
              snapshot.state === KernelState.Active ? "text-emerald-400" :
              snapshot.state === KernelState.Booting ? "text-amber-400" :
              snapshot.state === KernelState.Faulted ? "text-rose-500 animate-pulse" : "text-slate-400"
            }`}>{snapshot.state}</span>
          </div>
          <div className="h-6 w-px bg-slate-800" />
          <div className="flex flex-col">
            <span className="text-[10px] text-slate-500 uppercase tracking-wider">Logical Clock</span>
            <span className="text-slate-300 font-bold">E:{snapshot.epoch} | T:{snapshot.tick} | S:{snapshot.sequence}</span>
          </div>
          <div className="h-6 w-px bg-slate-800" />
          <div className="flex flex-col">
            <span className="text-[10px] text-slate-500 uppercase tracking-wider">Integrity Hash</span>
            <span className="text-emerald-500 font-bold flex items-center gap-1">
              <Hash className="w-3.5 h-3.5" /> {system_integrity_hash.slice(0, 10)}
            </span>
          </div>
        </div>
      </header>

      {/* Main Panel Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-grow items-stretch">

        {/* Left Hand: Declarative BootPlan & Controls */}
        <section className="lg:col-span-4 flex flex-col gap-6">

          {/* Declarative BootPlan Executor */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 flex flex-col justify-between">
            <div>
              <div className="flex items-center justify-between mb-4">
                <h2 className="font-semibold text-sm tracking-wider uppercase text-slate-300 flex items-center gap-2">
                  <Layers className="w-4 h-4 text-emerald-400" />
                  Declarative BootPlan
                </h2>
                <span className="text-xs bg-emerald-500/10 text-emerald-400 px-2.5 py-0.5 rounded-full border border-emerald-500/20">
                  Section 1.1
                </span>
              </div>

              <div className="space-y-2 font-mono text-xs">
                {[
                  { name: "0. Uninitialized", desc: "Awaiting boot sequence init" },
                  { name: "1. Load Config", desc: "Hash manifest parameters" },
                  { name: "2. Validate Dependencies", desc: "Sort acyclic capability trees" },
                  { name: "3. Seal Capabilities", desc: "Seal Cap Registry against writes" },
                  { name: "4. Resolve Services", desc: "Scaffold ConstructionPlan container" },
                  { name: "5. Setup Event Bus", desc: "Spin up Clock & Queue channels" },
                  { name: "6. Activate Kernel", desc: "Active operational state reached" }
                ].map((bp, idx) => (
                  <div key={idx} className={`p-2 rounded flex flex-col gap-1 transition-all ${
                    snapshot.state === KernelState.Active && idx === 6 ? "text-emerald-400 bg-emerald-950/10 border-l-2 border-emerald-500" :
                    snapshot.state === KernelState.Booting ? "bg-amber-500/10 text-amber-300 border-l-2 border-amber-500" : "text-slate-500 bg-slate-950/35"
                  }`}>
                    <div className="flex items-center justify-between">
                      <span className="font-bold">{bp.name}</span>
                      {snapshot.state === KernelState.Active ? (
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                      ) : null}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Controls */}
            <div className="mt-6 pt-4 border-t border-slate-800 flex flex-col gap-3">
              <div className="flex gap-2">
                <button
                  disabled={snapshot.state === KernelState.Active || snapshot.state === KernelState.Faulted}
                  onClick={handleStepPhase}
                  className="flex-1 bg-amber-500 hover:bg-amber-600 disabled:bg-slate-800 disabled:text-slate-500 text-slate-950 font-bold py-2 px-3 rounded-lg text-xs transition flex items-center justify-center gap-1.5"
                >
                  <PlayCircle className="w-4 h-4" /> Step Phase
                </button>
                <button
                  onClick={handleAutoBoot}
                  disabled={snapshot.state === KernelState.Active}
                  className="flex-1 bg-emerald-500 hover:bg-emerald-600 disabled:bg-slate-800 disabled:text-slate-500 text-slate-950 font-bold py-2 px-3 rounded-lg text-xs transition flex items-center justify-center gap-1.5"
                >
                  <Cpu className="w-4 h-4" /> AutoBoot
                </button>
              </div>

              {/* Adversarial Loop Configuration */}
              <div className="bg-slate-950/50 p-3 rounded-lg border border-slate-800 flex items-center justify-between">
                <div className="flex flex-col">
                  <span className="text-xs font-semibold text-slate-300 flex items-center gap-1.5">
                    <AlertTriangle className="w-3.5 h-3.5 text-amber-400" /> Boundary Testing
                  </span>
                  <span className="text-[10px] text-slate-500">Inject topology dependency loop</span>
                </div>
                <button
                  disabled={snapshot.state === KernelState.Active}
                  onClick={() => setInjectCycle(!injectCycle)}
                  className={`text-xs px-3 py-1 rounded font-bold transition ${
                    injectCycle 
                    ? "bg-rose-500/20 text-rose-400 border border-rose-500/30" 
                    : "bg-slate-800 text-slate-400 hover:bg-slate-700"
                  }`}
                >
                  {injectCycle ? "Cycle Enabled" : "Clear"}
                </button>
              </div>
            </div>
          </div>

          {/* Operational Interface Controllers */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-5">
            <h2 className="font-semibold text-sm tracking-wider uppercase text-slate-300 mb-4 flex items-center gap-2">
              <Settings className="w-4 h-4 text-emerald-400" />
              Service Operations
            </h2>
            <div className="grid grid-cols-2 gap-3">
              <button
                disabled={snapshot.state !== KernelState.Active}
                onClick={handleHaltCore}
                className="bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 border border-rose-500/20 font-bold py-2.5 px-3 rounded-lg text-xs transition flex items-center justify-center gap-2 disabled:opacity-40 disabled:pointer-events-none"
              >
                <XCircle className="w-4 h-4" /> Halt Core
              </button>
              <button
                disabled={snapshot.state !== KernelState.Active}
                onClick={handleWarmReboot}
                className="bg-sky-500/10 hover:bg-sky-500/20 text-sky-400 border border-sky-500/20 font-bold py-2.5 px-3 rounded-lg text-xs transition flex items-center justify-center gap-2 disabled:opacity-40 disabled:pointer-events-none"
              >
                <RotateCcw className="w-4 h-4" /> Warm Reboot
              </button>
            </div>
          </div>

        </section>

        {/* Center: Capability Registry vs Live Service Container */}
        <section className="lg:col-span-4 flex flex-col gap-6">

          {/* Metadata vs Instance Container Panels */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 space-y-5">

            {/* Section 3.1 Metadata Registry */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-xs tracking-wider uppercase text-slate-300 flex items-center gap-2">
                  <Database className="w-3.5 h-3.5 text-emerald-400" />
                  Capability Metadata Registry
                </h3>
                <span className={`text-[10px] font-mono font-bold px-2 py-0.5 rounded ${
                  invariants.registry_sealed ? "bg-emerald-500/15 text-emerald-400 border border-emerald-500/20" : "bg-amber-500/15 text-amber-400 border border-amber-500/20"
                }`}>
                  {invariants.registry_sealed ? "FROZEN" : "MUTABLE"}
                </span>
              </div>
              <div className="space-y-2 max-h-[140px] overflow-y-auto">
                {snapshot.registered_capabilities.map((cap, idx) => (
                  <div key={idx} className="bg-slate-950 p-2 rounded-lg border border-slate-800 flex flex-col gap-1 text-[11px] font-mono">
                    <div className="flex justify-between font-bold">
                      <span className="text-slate-300">{cap.id}</span>
                      <span className="text-emerald-400">C:v{cap.contract_version}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Section 4.1 Service Container */}
            <div className="border-t border-slate-800/80 pt-4">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-xs tracking-wider uppercase text-slate-300 flex items-center gap-2">
                  <Settings className="w-3.5 h-3.5 text-emerald-400" />
                  Active Service Container
                </h3>
                <span className={`text-[10px] font-mono font-bold px-2 py-0.5 rounded ${
                  invariants.container_immutable ? "bg-emerald-500/15 text-emerald-400 border border-emerald-500/20" : "bg-amber-500/15 text-amber-400 border border-amber-500/20"
                }`}>
                  {invariants.container_immutable ? "IMMUTABLE" : "UNRESOLVED"}
                </span>
              </div>
              <div className="space-y-2 max-h-[140px] overflow-y-auto">
                {snapshot.instantiated_services.map((srv, idx) => (
                  <div key={idx} className="bg-slate-950 p-2.5 rounded-lg border border-slate-800 flex flex-col gap-1 text-[11px] font-mono">
                    <div className="flex justify-between font-bold">
                      <span className="text-sky-400">{srv}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

          </div>

          {/* Console logger */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 flex-grow flex flex-col justify-between min-h-[220px]">
            <h2 className="font-semibold text-sm tracking-wider uppercase text-slate-300 mb-3 flex items-center gap-2">
              <TermIcon className="w-4 h-4 text-emerald-400" />
              Diagnostics Console Feed
            </h2>
            <div className="bg-slate-950 rounded-lg p-3 flex-grow font-mono text-xs overflow-y-auto max-h-[180px] border border-slate-900 space-y-1.5 scrollbar-thin">
              {consoleLogs.map((log, idx) => (
                <div key={idx} className="flex gap-2 items-start leading-relaxed text-slate-300 font-mono text-[10px]">
                  <span>{log}</span>
                </div>
              ))}
              <div ref={logsEndRef} />
            </div>
          </div>

        </section>

        {/* Right Pane with Tabs for Sequencer & Orchestrator */}
        <section className="lg:col-span-4 flex flex-col gap-6">

          {/* Tab Navigation */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl p-1 flex gap-2">
            <button
              onClick={() => setActiveTab("orchestrator")}
              className={`flex-1 text-center py-2 text-xs font-bold rounded-lg transition ${
                activeTab === "orchestrator" 
                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" 
                : "text-slate-400 hover:text-slate-200"
              }`}
            >
              Task Orchestrator
            </button>
            <button
              onClick={() => setActiveTab("bus")}
              className={`flex-1 text-center py-2 text-xs font-bold rounded-lg transition ${
                activeTab === "bus" 
                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" 
                : "text-slate-400 hover:text-slate-200"
              }`}
            >
              Deterministic Sequencer
            </button>
          </div>

          {/* TAB 1: RUNTIME ORCHESTRATOR PANEL (SPRINT 1.4) */}
          {activeTab === "orchestrator" && (
            <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 flex flex-col gap-4 flex-grow">
              <div>
                <h2 className="font-semibold text-sm tracking-wider uppercase text-slate-300 flex items-center justify-between">
                  <span>Runtime Orchestrator</span>
                  <span className="text-[10px] bg-emerald-500/15 text-emerald-400 px-2 py-0.5 rounded-full border border-emerald-500/20 font-bold">
                    Section 1.4
                  </span>
                </h2>
                <p className="text-[10px] text-slate-500 mt-1 leading-relaxed">
                  Topological scheduler coordinating execution batches cleanly through the Kernel façade.
                </p>
              </div>

              {/* Task Queue Grid */}
              <div className="bg-slate-950 border border-slate-800 rounded-lg p-3 flex-grow max-h-[220px] overflow-y-auto">
                <div className="text-[10px] text-slate-500 uppercase tracking-wider mb-2 font-bold pb-1.5 border-b border-slate-900">
                  Task Admission Queue
                </div>
                <div className="space-y-2">
                  {tasksList.map((task, idx) => (
                    <div key={idx} className="bg-slate-900/60 border border-slate-800/40 p-2 rounded flex flex-col gap-1 text-[10px] font-mono">
                      <div className="flex justify-between items-center">
                        <span className="font-bold text-slate-300">{task.id}</span>
                        <span className={`text-[9px] px-2 py-0.5 rounded font-bold ${
                          task.state === TaskState.Completed ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" :
                          task.state === TaskState.Running ? "bg-amber-500/10 text-amber-400 border border-amber-500/20 animate-pulse" :
                          "bg-slate-800 text-slate-400"
                        }`}>
                          {task.state}
                        </span>
                      </div>
                      <div className="flex justify-between text-[9px] text-slate-500">
                        <span>P:{task.priority} | Requires: {task.dependencies.length > 0 ? task.dependencies.join(",") : "None"}</span>
                        <span>Caps: {task.capability_id.split(".").pop()}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

