// --- SECTION 2.0: KERNEL STATE MACHINE CONSTITUTIONS ---

export enum KernelState {
    Uninitialized = "Uninitialized",
    Booting = "Booting",
    Active = "Active",
    ShuttingDown = "ShuttingDown",
    Halted = "Halted",
    Faulted = "Faulted"
}

export class KernelStateMachine {
    /// Validates whether a state transition conforms strictly to ELY-KRN-SPEC-30.2.
    public static isTransitionAllowed(from: KernelState, to: KernelState): boolean {
        switch (from) {
            case KernelState.Uninitialized:
                return to === KernelState.Booting;

            case KernelState.Booting:
                return to === KernelState.Active || to === KernelState.Faulted;

            case KernelState.Active:
                return to === KernelState.ShuttingDown || to === KernelState.Faulted;

            case KernelState.ShuttingDown:
                return to === KernelState.Halted;

            case KernelState.Halted:
                return to === KernelState.Booting; // Warm Reboot Path

            case KernelState.Faulted:
                return to === KernelState.Halted; // Diagnostic Reset Path

            default:
                return false;
        }
    }
}

