// --- SECTION 5.0: TEMPORAL EVENT DOMAIN & LOGICAL TIME (ELY-KRN-SPEC-30.2) ---

import { InvariantVerifier } from "./contracts";

// --- TimeCoordinate (Immutable Value Object) ---
export class TimeCoordinate {
    constructor(
        public readonly epoch: number,
        public readonly tick: number,
        public readonly sequence: number
    ) {
        Object.freeze(this); // Guarantees absolute immutability of coordinates
    }

    /// Enforces lexicographical monotonic ordering: (Epoch -> Tick -> Sequence)
    public isBefore(other: TimeCoordinate): boolean {
        if (this.epoch !== other.epoch) return this.epoch < other.epoch;
        if (this.tick !== other.tick) return this.tick < other.tick;
        return this.sequence < other.sequence;
    }

    public equals(other: TimeCoordinate): boolean {
        return this.epoch === other.epoch && this.tick === other.tick && this.sequence === other.sequence;
    }

    public toString(): string {
        return `E:${this.epoch}|T:${this.tick}|S:${this.sequence}`;
    }
}

// --- LogicalClock (Sole Authority over Time Mutation) ---
export class LogicalClock {
    private _epoch: number = 0;
    private _tick: number = 0;
    private _sequence: number = 0;

    public current(): TimeCoordinate {
        return new TimeCoordinate(this._epoch, this._tick, this._sequence);
    }

    public nextSequence(): number {
        this._sequence += 1;
        return this._sequence;
    }

    public advanceTick(): TimeCoordinate {
        this._tick += 1;
        this._sequence = 0; // Invariant: Sequence automatically resets to 0 on tick advance
        return this.current();
    }

    public advanceEpoch(): TimeCoordinate {
        this._epoch += 1;
        this._tick = 0;
        this._sequence = 0;
        return this.current();
    }
}

// --- EventID & EventEnvelope ---
export class EventID {
    /// Generates identity separate from payload integrity verification checks
    public static derive(coordinate: TimeCoordinate, type_id: string, payload_hash: string): string {
        let hash = 0;
        const inputStr = `${coordinate.toString()}-${type_id}-${payload_hash}`;
        for (let i = 0; i < inputStr.length; i++) {
            const char = inputStr.charCodeAt(i);
            hash = (hash << 5) - hash + char;
            hash = hash & hash;
        }
        return "0xID" + Math.abs(hash).toString(16).toUpperCase() + "B3F";
    }
}

export interface EventEnvelope {
    readonly id: string; // Cryptographic EventID
    readonly coordinate: TimeCoordinate;
    readonly type_id: string;
    readonly payload_hash: string;
    readonly payload: string;
}

// --- EventBus (Unyielding Sequencer Queue) ---
export class EventBus implements InvariantVerifier {
    private unsortedQueue: Omit<EventEnvelope, "id" | "payload_hash">[] = [];
    private readonly journal: EventEnvelope[] = [];

    constructor(private readonly clock: LogicalClock) {}

    public dispatch(type_id: string, payload: string): void {
        const nextSeq = this.clock.nextSequence();
        const coordinate = new TimeCoordinate(
            this.clock.current().epoch,
            this.clock.current().tick,
            nextSeq
        );

        this.unsortedQueue.push({
            coordinate,
            type_id,
            payload
        });
    }

    /// Sorts the pending queue lexicographically using immutable TimeCoordinates
    public sequenceAndFlush(): readonly EventEnvelope[] {
        if (this.unsortedQueue.length === 0) return [];

        const sorted = [...this.unsortedQueue].sort((a, b) => {
            if (a.coordinate.equals(b.coordinate)) return 0;
            return a.coordinate.isBefore(b.coordinate) ? -1 : 1;
        });

        const flushed: EventEnvelope[] = sorted.map(evt => {
            const payloadHash = this.generateHash(evt.payload);
            const id = EventID.derive(evt.coordinate, evt.type_id, payloadHash);
            return {
                ...evt,
                id,
                payload_hash: payloadHash
            };
        });

        this.journal.push(...flushed);
        this.unsortedQueue = [];
        this.clock.advanceTick(); // Sole clock advance pathway upon sequence flush
        return flushed;
    }

    public getJournal(): readonly EventEnvelope[] {
        return Object.freeze([...this.journal]);
    }

    public getUnsorted(): readonly any[] {
        return Object.freeze([...this.unsortedQueue]);
    }

    public verify_invariants(): boolean {
        // Clock Invariant: Event bus cannot possess logs exceeding the current Epoch
        const currentClock = this.clock.current();
        return this.journal.every(evt => evt.coordinate.epoch <= currentClock.epoch);
    }

    public signature(): string {
        const sequenceChain = this.journal.map(e => e.id).join("-");
        return this.generateHash(sequenceChain || "empty-bus");
    }

    private generateHash(str: string): string {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = (hash << 5) - hash + char;
            hash = hash & hash;
        }
        return "0x" + Math.abs(hash).toString(16).toUpperCase() + "B3F29C";
    }
}

// --- SECTION 4.0: SERVICE RESOLUTION CONTAINER (ELY-KRN-SPEC-30.3) ---

export enum Lifecycle {
    Singleton = "Singleton",
    Transient = "Transient"
}

export interface ServiceDescriptor {
    readonly id: string;
    readonly capability_id: string;
    readonly lifecycle: Lifecycle;
    readonly dependencies: readonly string[];
}

export class DependencyGraph {
    private readonly nodes: Map<string, ServiceDescriptor> = new Map();

    public addNode(descriptor: ServiceDescriptor): void {
        this.nodes.set(descriptor.id, descriptor);
    }

    /// Performs a recursive depth-first topological sort to detect cycles and calculate resolution order
    public sort(): string[] {
        const sorted: string[] = [];
        const visited: Map<string, boolean> = new Map(); // true = visiting (in stack), false = visited
        const nodesList = Array.from(this.nodes.values());

        const visit = (nodeId: string) => {
            if (visited.get(nodeId) === true) {
                throw new Error(`[CRITICAL] CYCLIC DEPENDENCY DETECTED: Loop involving service "${nodeId}"`);
            }
            if (visited.get(nodeId) === undefined) {
                visited.set(nodeId, true); // Mark as visiting

                const descriptor = this.nodes.get(nodeId);
                if (descriptor) {
                    for (const depId of descriptor.dependencies) {
                        // Find service providing this capability dependency
                        const provider = nodesList.find(n => n.capability_id === depId);
                        if (!provider) {
                            throw new Error(`[CRITICAL] MISSING CAPABILITY PROVIDER: Service "${nodeId}" requires unresolved capability "${depId}"`);
                        }
                        visit(provider.id);
                    }
                }

                visited.set(nodeId, false); // Mark as fully visited
                sorted.push(nodeId);
            }
        };

        for (const id of this.nodes.keys()) {
            if (visited.get(id) === undefined) {
                visit(id);
            }
        }

        return sorted;
    }

    public getDescriptor(id: string): ServiceDescriptor | undefined {
        return this.nodes.get(id);
    }
}

export class ConstructionPlan {
    constructor(
        public readonly ordered_service_ids: readonly string[],
        private readonly graph: DependencyGraph
    ) {
        Object.freeze(this);
    }

    public listDescriptors(): ServiceDescriptor[] {
        return this.ordered_service_ids.map(id => this.graph.getDescriptor(id)!);
    }
}

export class ServiceContainer {
    private readonly instances: Map<string, any> = new Map();

    constructor(private readonly plan: ConstructionPlan) {}

    /// Instantiates read-only instances strictly following the verified ConstructionPlan
    public instantiate(mockFactories: Map<string, () => any>): void {
        const descriptors = this.plan.listDescriptors();
        for (const desc of descriptors) {
            if (desc.lifecycle === Lifecycle.Singleton) {
                const factory = mockFactories.get(desc.id);
                if (!factory) {
                    throw new Error(`[CRITICAL] CONSTRUCTION FAILURE: No factory registered to construct singleton "${desc.id}"`);
                }
                this.instances.set(desc.id, factory());
            }
        }
    }

    public resolve<T>(service_id: string): T {
        const desc = this.plan.listDescriptors().find(d => d.id === service_id);
        if (!desc) {
            throw new Error(`[CRITICAL] RESOLUTION FAILURE: Service "${service_id}" is not in the ConstructionPlan.`);
        }

        if (desc.lifecycle === Lifecycle.Singleton) {
            const instance = this.instances.get(service_id);
            if (!instance) {
                throw new Error(`[CRITICAL] SERVICE LIFECYCLE LEAK: Singleton "${service_id}" called before container instantiation.`);
            }
            return instance;
        }

        // Transient Lifecycle - Instantiated deterministically per resolution request
        return desc.id as any;
    }
}

