}

export interface BootReport {
    readonly is_success: boolean;
    readonly duration_ms: number;
    readonly manifest_hash: string;
    readonly phase_logs: readonly string[];
}

export class BootExecutor {
    private readonly logs: string[] = [];
    private current_phase_index: number = 0;

    constructor(
        private readonly phases: readonly BootPhase[],
        private readonly eventBus: EventBus,
        private readonly setKernelState: (state: KernelState) => void
    ) {}

    public execute(inject_cycle: boolean): BootReport {
        const startTime = Date.now();
        this.setKernelState(KernelState.Booting);
        this.logEvent("PhaseStarted", `Boot sequence initiated at epoch reference.`);

        try {
            for (const phase of this.phases) {
                this.current_phase_index = phase.phase_index;
                this.logs.push(`[BOOT] Running phase ${phase.phase_index}: ${phase.name}`);

                // Special mock case for injecting dependency cycle dynamically
                if (phase.phase_index === 2 && inject_cycle) {
                    throw new Error("[CRITICAL] Topolgical Sort failed: Cycle detected.");
                }

                const verified = phase.verify_invariant();
                if (!verified) {
                    throw new Error(`[CRITICAL] Invariant verification failed at phase: ${phase.name}`);
                }

                this.logEvent("PhaseCompleted", `Phase ${phase.phase_index} invariant validated: OK`);
            }

            this.setKernelState(KernelState.Active);
