export interface SnapshotReport {
    readonly state: KernelState;
    readonly epoch: number;
    readonly tick: number;
    readonly sequence: number;
    readonly registered_capabilities: readonly CapabilityMetadata[];
    readonly instantiated_services: readonly string[];
    readonly unsorted_event_queue?: readonly any[];
}

export interface HealthReport {
    readonly is_operational: boolean;
    readonly service_health: Map<string, boolean>;
    readonly buffer_depth: number;
}

export interface InvariantReport {
    readonly boot_deterministic: boolean;
    readonly registry_sealed: boolean;
    readonly container_immutable: boolean;
    readonly dependency_graph_acyclic: boolean;
}

export interface ReplayReport {
    readonly original_signature: string;
    readonly replay_signature: string;
    readonly parity_match: boolean;
    readonly audit_logs: readonly string[];
}

export interface ConsolidatedReport {
    readonly timestamp: string;
    readonly snapshot: SnapshotReport;
    readonly health: HealthReport;
    readonly invariants: InvariantReport;
    readonly last_replay?: ReplayReport;
    readonly system_integrity_hash: string;
}

export class DiagnosticsEngine {
    public static generateReport(
        state: KernelState,
        clock: { epoch: number; tick: number; sequence: number },
        capabilities: readonly CapabilityMetadata[],
        services: readonly string[],
        is_sealed: boolean,
        is_immutable: boolean,
        is_acyclic: boolean,
        last_replay?: ReplayReport,
        integrity_hash: string = "0xEMPTY",
        unsorted_queue: readonly any[] = []
    ): ConsolidatedReport {
        const snapshot: SnapshotReport = {
            state,
            epoch: clock.epoch,
            tick: clock.tick,
            sequence: clock.sequence,
            registered_capabilities: Object.freeze([...capabilities]),
            instantiated_services: Object.freeze([...services]),
            unsorted_event_queue: Object.freeze([...unsorted_queue])
        };

        const health: HealthReport = {
            is_operational: state === KernelState.Active,
            service_health: new Map(services.map(s => [s, true])),
            buffer_depth: 0
        };

        const invariants: InvariantReport = {
            boot_deterministic: true,
            registry_sealed: is_sealed,
            container_immutable: is_immutable,
            dependency_graph_acyclic: is_acyclic
        };

        return {
            timestamp: new Date().toISOString().split("T")[1].slice(0, 8),
            snapshot,
            health,
            invariants,
            last_replay,
            system_integrity_hash: integrity_hash
        };
    }
}

