import { KernelState, KernelStateMachine } from "./state";
import { CapabilityRegistry, CapabilityMetadata } from "./capability";
import { DependencyGraph, ConstructionPlan, ServiceContainer, Lifecycle } from "./container";
import { LogicalClock, EventBus, EventEnvelope, EventID } from "./event";
import { BootExecutor, BootPhase } from "./boot";
import { ConsolidatedReport, DiagnosticsEngine, ReplayReport } from "./diagnostics";

class KernelRuntime {
    public state: KernelState = KernelState.Uninitialized;
    public readonly clock: LogicalClock = new LogicalClock();
    public readonly registry: CapabilityRegistry = new CapabilityRegistry();
    public readonly eventBus: EventBus;

    // Scaffolding plan items resolved at boot
    public container?: ServiceContainer;
    public is_acyclic: boolean = true;

    constructor() {
        this.eventBus = new EventBus(this.clock);
    }
}

export class Kernel {
    private readonly runtime: KernelRuntime = new KernelRuntime();

    /// Orchestrates step-wise or automated boot utilizing the private KernelRuntime
    public boot(inject_cycle: boolean): ConsolidatedReport {
        if (this.runtime.state !== KernelState.Uninitialized) {
            throw new Error(`[CRITICAL] BOOT FAILURE: Kernel is already in state: ${this.runtime.state}`);
        }

        this.runtime.is_acyclic = !inject_cycle;

        const bootPhases: BootPhase[] = [
            {
                phase_index: 1,
                name: "Load Config",
                preconditions: [],
                action_description: "Initialize config parameters.",
                verify_invariant: () => true
            },
            {
                phase_index: 2,
                name: "Validate Dependencies",
                preconditions: ["Load Config"],
                action_description: "Topologically sort and check for loops.",
                verify_invariant: () => this.runtime.is_acyclic
            },
            {
                phase_index: 3,
                name: "Seal Capabilities",
                preconditions: ["Validate Dependencies"],
                action_description: "Freeze capability metadata registry.",
                verify_invariant: () => {
                    this.runtime.registry.seal();
                    return this.runtime.registry.isSealed();
                }
            },
            {
                phase_index: 4,
                name: "Resolve Services",
                preconditions: ["Seal Capabilities"],
                action_description: "Build ConstructionPlan and ServiceContainer.",
                verify_invariant: () => {
                    const graph = new DependencyGraph();
                    graph.addNode({ id: "srv_obs_lens", capability_id: "elyzareth.observability.lens", lifecycle: Lifecycle.Singleton, dependencies: [] });
                    graph.addNode({ id: "srv_lyrics", capability_id: "elyzareth.lyrics.engine", lifecycle: Lifecycle.Singleton, dependencies: ["elyzareth.observability.lens"] });

                    const sorted = graph.sort();
                    const plan = new ConstructionPlan(sorted, graph);
                    this.runtime.container = new ServiceContainer(plan);
                    return this.runtime.container !== undefined;
                }
            },
            {
                phase_index: 5,
                name: "Setup Event Bus",
                preconditions: ["Resolve Services"],
                action_description: "Initialize event loop pipelines.",
                verify_invariant: () => true
            },
            {
                phase_index: 6,
                name: "Activate Kernel",
                preconditions: ["Setup Event Bus"],
                action_description: "Handover thread to operational supervisors.",
                verify_invariant: () => true
            }
        ];

        const executor = new BootExecutor(
            bootPhases,
            this.runtime.eventBus,
            (newState) => { this.runtime.state = newState; }
        );

        executor.execute(inject_cycle);
        return this.snapshot();
    }

    public shutdown(): ConsolidatedReport {
        this.runtime.state = KernelState.ShuttingDown;
        this.runtime.clock.advanceEpoch(); // Advances Epoch upon warm reset / shutdown
        this.runtime.state = KernelState.Halted;
        return this.snapshot();
    }

    public warm_reboot(): ConsolidatedReport {
        this.runtime.state = KernelState.Booting;
        this.runtime.clock.advanceEpoch();
        this.runtime.state = KernelState.Active;
        return this.snapshot();
    }

    public dispatch(typeId: string, payload: string): ConsolidatedReport {
        this.runtime.eventBus.dispatch(typeId, payload);
        return this.snapshot();
    }

    public process_queues(): ConsolidatedReport {
        this.runtime.eventBus.sequenceAndFlush();
        return this.snapshot();
    }

    public replay_audit(corrupt: boolean): ReplayReport {
        const originalStream = this.runtime.eventBus.getJournal();
        const originalHash = this.runtime.eventBus.signature();
        const count = originalStream.length;

        const audit_logs: string[] = [
            `[AUDIT] Launching automated replay verification stream...`,
            `[AUDIT] Log contained ${count} historical envelopes.`
        ];

        const reprocessed = originalStream.map((evt, index) => {
            let payload = evt.payload;
            if (corrupt && index === Math.floor(count / 2)) {
                payload = "CORRUPTED_EVENT_DATA_ALTERED_119";
                audit_logs.push(`[WARN] Adversarial payload drift injected at index ${index}.`);
            }
            const payloadHash = this.generateHash(payload);
            const id = EventID.derive(evt.coordinate, evt.type_id, payloadHash);
            return {
                ...evt,
                id,
                payload,
                payload_hash: payloadHash
            };
        });

        const replayHash = this.generateHash(reprocessed.map(e => e.id).join("-"));
        const matches = replayHash === originalHash;

        if (matches) {
            audit_logs.push(`[SUCCESS] Temporal coordinates matched exactly. Observed Determinism verified.`);
        } else {
            audit_logs.push(`[ERROR] SYSTEM DRIFT DETECTED: Hash signature mismatch.`);
        }

        return {
            original_signature: originalHash,
            replay_signature: replayHash,
            parity_match: matches,
            audit_logs: Object.freeze(audit_logs)
        };
    }

    public snapshot(lastReplay?: ReplayReport): ConsolidatedReport {
        const clock = this.runtime.clock.current();
        const mockCapabilities: CapabilityMetadata[] = [
            { id: "elyzareth.observability.lens", contract_version: "2.1.0", impl_version: "2.1.4", dependencies: [], verification_signature: "0x9F4B3C" },
            { id: "elyzareth.lyrics.engine", contract_version: "3.0.1", impl_version: "3.0.1", dependencies: ["elyzareth.observability.lens"], verification_signature: "0xA7D2C4" }
        ];

        return DiagnosticsEngine.generateReport(
            this.runtime.state,
            { epoch: clock.epoch, tick: clock.tick, sequence: clock.sequence },
            mockCapabilities,
            ["srv_obs_lens", "srv_lyrics"],
            this.runtime.registry.isSealed(),
            this.runtime.container !== undefined,
            this.runtime.is_acyclic,
            lastReplay,
            this.runtime.eventBus.signature(),
            this.runtime.eventBus.getUnsorted()
        );
    }

    private generateHash(str: string): string {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = (hash << 5) - hash + char;
            hash = hash & hash;
        }
        return "0x" + Math.abs(hash).toString(16).toUpperCase() + "B3F29C";
    }
}

// --- SECTION 1.4.1: TASK DOMAIN SPECIFICATIONS (ELY-RT-SPEC-30.0) ---

export enum TaskState {
    Queued = "Queued",
    Ready = "Ready",
    Running = "Running",
    Completed = "Completed",
    Failed = "Failed"
}

export interface Task {
    readonly id: string;
    readonly capability_id: string;
    readonly payload: string;
    readonly priority: number;
    readonly dependencies: readonly string[]; // Task ID dependencies
    readonly state: TaskState;
    readonly metadata: Record<string, string>;
}

export class TaskFactory {
    public static create(
        id: string,
        capability_id: string,
        payload: string,
        priority: number = 0,
        dependencies: string[] = []
    ): Task {
        const task: Task = {
            id,
            capability_id,
            payload,
            priority,
            dependencies: Object.freeze([...dependencies]),
            state: TaskState.Queued,
            metadata: Object.freeze({ created_at: new Date().toISOString() })
        };
        return Object.freeze(task);
    }

    public static transition(task: Task, next_state: TaskState): Task {
        const updated: Task = {
            ...task,
            state: next_state
        };
        return Object.freeze(updated);
    }
}

// --- SECTION 1.4.2: SCHEDULING POLICIES & EXECUTION PLANS (ELY-RT-SPEC-30.0) ---

import { Task, TaskState } from "./task";

export interface PolicyRules {
    readonly max_priority_level: number;
    readonly allow_circular_dependencies: boolean;
}

export class PolicyEngine {
    constructor(private readonly rules: PolicyRules) {}

    /// Enforces priority, structural validation, and capability constraints on enqueued tasks
    public validateTask(task: Task): boolean {
        if (task.priority > this.rules.max_priority_level) {
            throw new Error(`[ADMISSION REJECTED] Priority level ${task.priority} exceeds configured maximum.`);
        }
        return true;
    }
}

export class ExecutionPlan {
    constructor(
        public readonly plan_id: string,
        public readonly ordered_task_ids: readonly string[],
        public readonly creation_timestamp: string
    ) {
        Object.freeze(this); // Immutability guarantee: an execution plan is frozen once scheduled
    }
}

export class Scheduler {
    constructor(private readonly policyEngine: PolicyEngine) {}

    /// Topologically sorts the tasks list into a strict sequential ExecutionPlan
    public schedule(tasks: Map<string, Task>): ExecutionPlan {
        const sortedIds: string[] = [];
        const visited: Map<string, boolean> = new Map(); // true = visiting (in stack), false = visited

        const visit = (taskId: string) => {
            if (visited.get(taskId) === true) {
                throw new Error(`[CRITICAL] SCHEDULER FAULT: Cycle detected in task dependency graph at "${taskId}"`);
            }
            if (visited.get(taskId) === undefined) {
                visited.set(taskId, true); // Mark as visiting

                const task = tasks.get(taskId);
                if (task) {
                    this.policyEngine.validateTask(task);
                    for (const depId of task.dependencies) {
                        if (!tasks.has(depId)) {
                            throw new Error(`[CRITICAL] SCHEDULER FAULT: Missing dependent task "${depId}" required by "${taskId}"`);
                        }
                        visit(depId);
                    }
                }

                visited.set(taskId, false); // Visited
                sortedIds.push(taskId);
            }
        };

        // Enforce priority-based seeding before topological sort for deterministic tie-breaking
        const sortedByPriority = Array.from(tasks.values()).sort((a, b) => b.priority - a.priority);

        for (const task of sortedByPriority) {
            if (visited.get(task.id) === undefined) {
                visit(task.id);
            }
        }

        const planId = "plan_0x" + Math.random().toString(16).slice(2, 10).toUpperCase();
        return new ExecutionPlan(planId, Object.freeze(sortedIds), new Date().toISOString());
    }
}

// --- SECTION 1.4.3: RUNTIME ORCHESTRATOR GATEWAY (ELY-RT-SPEC-30.0) ---

import { Kernel } from "./kernel";
import { Task, TaskState, TaskFactory } from "./task";
import { ExecutionPlan } from "./scheduler";
import { ConsolidatedReport } from "./diagnostics";

export interface RuntimeReport {
    readonly active_plan_id: string;
    readonly total_tasks: number;
    readonly completed_count: number;
    readonly failed_count: number;
    readonly task_states: Map<string, TaskState>;
}

export class RuntimeOrchestrator {
    private readonly tasks: Map<string, Task> = new Map();
    private activePlan?: ExecutionPlan;

    constructor(private readonly kernel: Kernel) {}

    public registerTask(task: Task): void {
        this.tasks.set(task.id, task);
    }

    public getTasks(): Map<string, Task> {
        return this.tasks;
    }

    public getActivePlan(): ExecutionPlan | undefined {
        return this.activePlan;
    }

    public resetTasks(): void {
        this.activePlan = undefined;
        for (const [id, t] of this.tasks.entries()) {
            this.tasks.set(id, TaskFactory.transition(t, TaskState.Queued));
        }
    }

    public executePlan(plan: ExecutionPlan, onStep: (report: RuntimeReport, kernelSnap: ConsolidatedReport) => void): void {
        this.activePlan = plan;
        let index = 0;

        const processNext = () => {
            if (!this.activePlan || index >= this.activePlan.ordered_task_ids.length) {
                return;
            }

            const taskId = this.activePlan.ordered_task_ids[index];
            const task = this.tasks.get(taskId)!;

            // Transition state to Running
            this.tasks.set(taskId, TaskFactory.transition(task, TaskState.Running));

            // Return diagnostic metrics snapshot showing "Running"
            onStep(this.generateReport(), this.kernel.snapshot());

            setTimeout(() => {
                // The scheduler/orchestrator never advances the clock. Time remains sole Kernel domain.
                // Dispatching the task payload onto the deterministic kernel event bus:
                const kernelSnap = this.kernel.dispatch("TaskExecute", `Task: ${task.id} (Capability: ${task.capability_id})`);

                // Advance kernel logical queues
                const executedSnap = this.kernel.process_queues();

                // Transition state to Completed
                this.tasks.set(taskId, TaskFactory.transition(task, TaskState.Completed));

                index++;

                // Return diagnostic metrics snapshot showing "Completed"
                onStep(this.generateReport(), executedSnap);

                // Execute asynchronously to simulate discrete system execution ticks
                setTimeout(processNext, 400);
            }, 300);
        };

        processNext();
    }

    public generateReport(): RuntimeReport {
        const taskStates = new Map<string, TaskState>();
        let completed = 0;
        let failed = 0;

        for (const [id, t] of this.tasks.entries()) {
            taskStates.set(id, t.state);
            if (t.state === TaskState.Completed) completed++;
            if (t.state === TaskState.Failed) failed++;
        }

        return {
            active_plan_id: this.activePlan ? this.activePlan.plan_id : "no-active-plan",
            total_tasks: this.tasks.size,
            completed_count: completed,
            failed_count: failed,
            task_states: taskStates
        };
    }
}

