              <p className="font-mono text-xs">Waiting for execution cycle dispatch...</p>
            </div>
          ) : (
            logs.map((log, index) => {
              const typeStyles = {
                info: "text-blue-400 border-blue-900/30 bg-blue-950/10",
                success: "text-emerald-400 border-emerald-900/30 bg-emerald-950/10",
                warn: "text-yellow-400 border-yellow-900/30 bg-yellow-950/10",
                contract: "text-indigo-400 border-indigo-900/30 bg-indigo-950/10"
              };
              return (
                <div key={index} className="p-2.5 rounded border border-neutral-850 bg-neutral-900/40 flex flex-col gap-1">
                  <div className="flex items-center justify-between text-[10px] font-bold">
