        loneliness = 0.78;
        hope = 0.35;
        focus = 0.70;
      }

      if (timeOfDay === "night") {
        calm -= 0.15;
        loneliness += 0.10;
      }
      if (rainIntensity > 0.7) {
        calm += 0.05;
        focus += 0.10;
      }
    }

    setEmotionalVector({
      calm: Math.min(1, Math.max(0, calm)),
      hope: Math.min(1, Math.max(0, hope)),
      loneliness: Math.min(1, Math.max(0, loneliness)),
      focus: Math.min(1, Math.max(0, focus))
    });
