} from "lucide-react";

// ============================================================================
// STATE-LOCKED KINETIC DATA
// ============================================================================

interface KineticStep {
  time: string;
  seconds: number;
  phase: string;
  logicalTick: string;
  delta: string;
  direction: "FORWARD" | "SLIP" | "HALT";
}

const KINETIC_STEPS: KineticStep[] = [
  { time: "00:00", seconds: 0, phase: "SYSTEM RESUME", logicalTick: "000000", delta: "+0.0 ms", direction: "FORWARD" },
  { time: "00:22", seconds: 22, phase: "COUPLED ROTATION", logicalTick: "002420", delta: "+4.1 ms", direction: "FORWARD" },
  { time: "00:58", seconds: 58, phase: "TEMPORAL EXPANSION", logicalTick: "008412", delta: "+8.2 ms", direction: "FORWARD" },
  { time: "01:34", seconds: 94, phase: "TIME SLIP ACTIVE", logicalTick: "019484", delta: "-142 ms", direction: "SLIP" },
  { time: "02:10", seconds: 130, phase: "CAUSALITY CASCADE", logicalTick: "024501", delta: "+3.4 ms", direction: "FORWARD" },
  { time: "02:46", seconds: 166, phase: "UNSTABLE INTERRUPT", logicalTick: "032890", delta: "ERR_HALT", direction: "HALT" }
];

export default function Component() {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(22); // Default to "COUPLED ROTATION" to initialize with movement
  const [volume, setVolume] = useState(0.85);
  const [isMuted, setIsMuted] = useState(false);
  const [audioError, setAudioError] = useState(false);

  // Concentric independent ring angles
  const [clockAngle1, setClockAngle1] = useState(45);
  const [clockAngle2, setClockAngle2] = useState(120);
  const [clockAngle3, setClockAngle3] = useState(280);

  // Separate playback state tracking for each ring to implement microsecond cascade halts
  const [isOuterRingSpinning, setIsOuterRingSpinning] = useState(false);
  const [isMiddleRingSpinning, setIsMiddleRingSpinning] = useState(false);
  const [isInnerRingSpinning, setIsInnerRingSpinning] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Raw storage URL to the generated Immutable Light track (serving as Volume II loop basis)
  const audioUrl = "https://storage.googleapis.com/producer-app-public/clips/8285764f-e64d-4069-8745-6fc53c4a3d24.m4a";

  useEffect(() => {
    if (isPlaying) {
      audioRef.current?.play().catch(() => {
        setAudioError(true);
      });
    } else {
      audioRef.current?.pause();
    }
  }, [isPlaying]);

  // Synchronized playback controls handling ring state bindings
  useEffect(() => {
    if (isPlaying && currentTime < 166) {
      setIsOuterRingSpinning(true);
      setIsMiddleRingSpinning(true);
      setIsInnerRingSpinning(true);
    } else {
      // Direct freeze if paused manually
      setIsOuterRingSpinning(false);
      setIsMiddleRingSpinning(false);
      setIsInnerRingSpinning(false);
    }
  }, [isPlaying, currentTime]);

  // Cascade Halt state triggers for independent engine component spin decay
  useEffect(() => {
    if (currentTime >= 166) {
      // Middle Ring immediately freezes
      setIsMiddleRingSpinning(false);

      // Outer Ring continues for 280ms before hard lock
      const timerOuter = setTimeout(() => {
        setIsOuterRingSpinning(false);
      }, 280);

      // Inner Ring executes exactly two discrete ticks (~450ms) before hard halt
      const timerInner = setTimeout(() => {
        setIsInnerRingSpinning(false);
      }, 450);

      return () => {
        clearTimeout(timerOuter);
        clearTimeout(timerInner);
      };
    }
  }, [currentTime]);

  // Physics engine loops for Ring 1 (Outer)
  useEffect(() => {
    if (!isOuterRingSpinning) return;
    const interval = setInterval(() => {
      let speedModifier = 1.0;
      if (currentTime >= 94 && currentTime < 102) speedModifier = 1.8;
      else if (currentTime >= 102 && currentTime < 118) speedModifier = 3.6;
      else if (currentTime >= 118 && currentTime < 126) speedModifier = 1.8;
      else if (currentTime >= 126 && currentTime < 130) speedModifier = 1.2;

      setClockAngle1(prev => (prev + 0.3 * speedModifier) % 360);
    }, 16);
    return () => clearInterval(interval);
  }, [isOuterRingSpinning, currentTime]);

  // Physics engine loops for Ring 2 (Middle)
  useEffect(() => {
    if (!isMiddleRingSpinning) return;
    const interval = setInterval(() => {
      let speedModifier = 1.0;
      if (currentTime >= 94 && currentTime < 102) speedModifier = 1.8;
      else if (currentTime >= 102 && currentTime < 118) speedModifier = 3.6;
      else if (currentTime >= 118 && currentTime < 126) speedModifier = 1.8;
      else if (currentTime >= 126 && currentTime < 130) speedModifier = 1.2;

      setClockAngle2(prev => (prev - 1.0 * speedModifier) % 360);
    }, 16);
    return () => clearInterval(interval);
