    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [currentTime]);

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const activeSecs = Math.floor(audioRef.current.currentTime);
      if (activeSecs >= 166) {
        setCurrentTime(166);
        setIsPlaying(false);
