  };

  const handleSeek = (seconds: number) => {
    setCurrentTime(seconds);
    if (audioRef.current) {
      audioRef.current.currentTime = seconds;
    }
  };

  const formatRealTime = (secs: number) => {
    const m = Math.floor(secs / 60).toString().padStart(2, "0");
    const s = (secs % 60).toString().padStart(2, "0");
    return `${m}:${s}`;
  };

  // The Time-Slip mathematical translation: Perceived Time vs Machine Sequence Time
  const getLogicalTimeDisplay = () => {
    if (currentTime >= 166) {
      return "03:14:08.52.."; // Cutoff / unfinished final digit representing interrupt
    }
    const isTimeSlip = currentTime >= 94 && currentTime < 130;
    if (isTimeSlip) {
      // Machine time slips forward at 2x rate relative to real elapsed seconds
      const baseTicks = 94 * 1000;
      const slippedTicks = (currentTime - 94) * 2000;
      return formatTicks(baseTicks + slippedTicks);
    } else {
      return formatTicks(currentTime * 1000);
    }
  };

  const formatTicks = (ms: number) => {
    const totalSecs = Math.floor(ms / 1000);
    const m = Math.floor(totalSecs / 60).toString().padStart(2, "0");
    const s = (totalSecs % 60).toString().padStart(2, "0");
    const dec = Math.floor(ms % 1000).toString().padStart(3, "0");
    return `${m}:${s}:${dec}`;
  };

  const getActiveStepIndex = () => {
    let activeIdx = 0;
    for (let i = 0; i < KINETIC_STEPS.length; i++) {
