        {/* LEFT COMPARTMENT: HORIZONTAL KINETIC PROPAGATION */}
        <div className={`lg:col-span-7 relative p-6 flex flex-col justify-between border-b lg:border-b-0 lg:border-r border-amber-950/40 min-h-[550px] transition-all duration-1000 ${
