}

import React, { useState, useEffect, useRef } from "react";
import { 
  Play, Pause, SkipForward, SkipBack, Volume2, 
  Shield, Activity, Cpu, Music, Info, Terminal, VolumeX
} from "lucide-react";

// ============================================================================
// STYLED STATIC DATA
// ============================================================================

interface TrackSection {
  time: string;
  seconds: number;
  phase: string;
  lyrics: string;
  hash: string; // Add stage-specific stable hashes to avoid nervous visual jitter
}

const TRACK_SECTIONS: TrackSection[] = [
  { time: "00:00", seconds: 0, phase: "INTRO (Initialization)", lyrics: "Clock starts now", hash: "0x8FA1..C32E" },
  { time: "00:18", seconds: 18, phase: "VERSE 1", lyrics: "Silent systems start to breathe", hash: "0x91B3..F8A2" },
  { time: "00:54", seconds: 54, phase: "PRE-CHORUS", lyrics: "Logs remember. Memory endures.", hash: "0xA3D8..E149" },
  { time: "01:30", seconds: 90, phase: "CHORUS", lyrics: "Immutable light, we write tomorrow", hash: "0xB2E7..D651" },
  { time: "02:06", seconds: 126, phase: "VERSE 2", lyrics: "Promises burned in electric skies", hash: "0xC5F4..B80E" },
  { time: "02:42", seconds: 162, phase: "VERSE 3", lyrics: "Frozen skylines slowly shine", hash: "0xD19A..A4F7" },
  { time: "03:18", seconds: 198, phase: "BRIDGE", lyrics: "Boot sequence complete.", hash: "0xE8C2..92B3" },
  { time: "03:54", seconds: 234, phase: "POST-CHORUS", lyrics: "Every promise written lives", hash: "0xF4D1..87A6" },
  { time: "04:30", seconds: 270, phase: "OUTRO", lyrics: "The signal never lies...", hash: "0x0000..9999" }
];

const INVARIANTS = [
  "TI-001", "TI-002", "TI-004", "TI-005", "TI-006", 
  "TI-007", "TI-008", "TI-009", "TI-010", "TI-011", "UI-001"
];

export default function Component() {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(18); // default to Verse 1 start to look like the design mockup
  const [volume, setVolume] = useState(0.8);
  const [isMuted, setIsMuted] = useState(false);
  const [audioError, setAudioError] = useState(false);
  const [celloDrones, setCelloDrones] = useState(true);

  // Animated triggers
  const [beamPulse, setBeamPulse] = useState(true);
  const [commitPulse, setCommitPulse] = useState(true);

  // Secondary delay state to let the card fade in after a brief silence once the beam has collapsed
  const [showCeremonialCard, setShowCeremonialCard] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Raw storage URL to the generated Immutable Light track
  const audioUrl = "https://storage.googleapis.com/producer-app-public/clips/8285764f-e64d-4069-8745-6fc53c4a3d24.m4a";

  useEffect(() => {
    if (isPlaying) {
      audioRef.current?.play().catch(() => {
        setAudioError(true);
      });
    } else {
      audioRef.current?.pause();
    }
  }, [isPlaying]);

  // Periodic slow breathing animations
  useEffect(() => {
    const interval = setInterval(() => {
      setBeamPulse(prev => !prev);
    }, 2800);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setCommitPulse(prev => !prev);
    }, 4500);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = isMuted ? 0 : volume;
    }
  }, [volume, isMuted]);

  // Global keydown handler for accessibility and space/seek controls
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if user is typing in a text field
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }
      if (e.key === " " || e.key === "Spacebar") {
        e.preventDefault();
        setIsPlaying(prev => !prev);
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        handleSectionClick(Math.min(298, currentTime + 10));
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        handleSectionClick(Math.max(0, currentTime - 10));
      } else if (e.key === "m" || e.key === "M") {
        e.preventDefault();
        setIsMuted(prev => !prev);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [currentTime]);

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(Math.floor(audioRef.current.currentTime));
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newTime = parseFloat(e.target.value);
    setCurrentTime(newTime);
    if (audioRef.current) {
      audioRef.current.currentTime = newTime;
    }
  };

  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60).toString().padStart(2, "0");
    const s = (secs % 60).toString().padStart(2, "0");
    return `${m}:${s}`;
  };

  const getActiveSectionIndex = () => {
    let activeIdx = 0;
    for (let i = 0; i < TRACK_SECTIONS.length; i++) {
      if (currentTime >= TRACK_SECTIONS[i].seconds) {
        activeIdx = i;
      } else {
        break;
      }
    }
    return activeIdx;
  };

  const activeIndex = getActiveSectionIndex();

