  useEffect(() => {
    if (isSealedState) {
      const timer = setTimeout(() => {
        setShowCeremonialCard(true);
      }, 2000); // 2000ms ensures the 1500ms beam collapse finishes, leaving a clean 500ms window of complete suspension before card fade-in
      return () => clearTimeout(timer);
    } else {
      setShowCeremonialCard(false);
    }
