  return (
    <div className="min-h-screen w-full text-slate-100 flex flex-col items-center justify-center p-4 md:p-8 font-mono select-none transition-colors duration-1000 bg-slate-950">

      {/* BACKGROUND GRAPHIC VECTOR CONTAINER */}
      <div className={`relative max-w-6xl w-full bg-[#0a0f18] rounded-xl border border-slate-800/80 shadow-2xl overflow-hidden grid grid-cols-1 lg:grid-cols-12 transition-all duration-1000 ${
        isSealedState ? "shadow-red-950/20 border-red-900/30" : isDiagnosticsMode ? "shadow-cyan-950/20 border-cyan-500/30" : "shadow-blue-950/20"
      }`}>

        {/* LEFT COLUMN: THE VISUAL ART / COVER CONSOLE */}
        <div className={`lg:col-span-7 relative p-6 flex flex-col justify-between border-b lg:border-b-0 lg:border-r border-slate-800/80 bg-gradient-to-b min-h-[500px] transition-colors duration-1000 ${
          isSealedState ? "from-[#1a0808] to-[#0a0101]" : isDiagnosticsMode ? "from-[#081e28] to-[#010a12]" : "from-[#0b1320] to-[#040811]"
        }`}>

          {/* Cover Header */}
          <div className="space-y-1">
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-blue-400 font-bold tracking-[0.3em] uppercase block">ELYZARETH OS</span>
                {isPlaying && !isSealedState && (
                  <span className={`text-[8px] px-1.5 py-0.2 border font-bold animate-pulse rounded transition-colors duration-1000 ${
                    isDiagnosticsMode 
                      ? "bg-cyan-950 text-cyan-400 border-cyan-800" 
                      : "bg-emerald-950 text-emerald-400 border-emerald-800"
                  }`}>
                    {isDiagnosticsMode ? "● DIAGNOSTICS ACTIVE" : "● ACTIVE STREAM"}
                  </span>
                )}
                {isSealedState && (
                  <span className="text-[8px] px-1.5 py-0.2 border font-bold rounded bg-red-950 text-red-400 border-red-800">
                    ■ ARCHIVED SYSTEM
                  </span>
                )}
              </div>

              {/* Event Commits Ledger Overlay */}
              <div className="text-right text-[8px] text-slate-500 font-bold">
                {isSealedState ? (
                  <span className="text-red-500 font-mono">[LEDGER SEALED]</span>
                ) : (
                  <>
                    <span className="text-cyan-500 font-mono">[COMMIT #04{activeIndex + 1}]</span> {TRACK_SECTIONS[activeIndex].phase} ✓ VERIFIED
                  </>
                )}
              </div>
            </div>

            <h2 className="text-3xl md:text-4xl font-extrabold tracking-widest text-slate-100 uppercase bg-clip-text text-transparent bg-gradient-to-r from-slate-100 via-blue-200 to-slate-200">
              IMMUTABLE LIGHT
            </h2>
            <p className="text-[9px] text-red-500 font-bold tracking-[0.4em] uppercase">LOGS REMEMBER. MEMORY ENDURES.</p>
          </div>

          {/* Epic Cyberpunk Illustration Space */}
          <div className="relative my-8 flex-1 w-full rounded border border-slate-850 bg-[#050912]/80 flex flex-col items-center justify-center overflow-hidden">
            {/* Grid Scanline Overlay */}
            <div className="absolute inset-0 bg-[linear-gradient(rgba(18,24,38,0.2)_1px,_transparent_1px),_linear-gradient(90deg,_rgba(18,24,38,0.2)_1px,_transparent_1px)] bg-[size:16px_16px] pointer-events-none opacity-40" />
            <div className="absolute inset-0 bg-[linear-gradient(to_bottom,_rgba(13,148,136,0.02)_50%,_transparent_50%)] bg-[size:100%_4px] pointer-events-none" />

            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-950/20 via-transparent to-transparent" />

