            <div className={`absolute top-0 bottom-0 left-1/2 -translate-x-1/2 bg-gradient-to-b from-blue-400 via-cyan-500 to-transparent shadow-[0_0_15px_rgba(56,189,248,0.6)] transition-all duration-[1500ms] ${
              isSealedState 
                ? "w-[0px] opacity-0 blur-[1px]" 
