          isDiagnosticsMode ? "from-[#081e28] to-[#010a12]" : "from-[#0b1320] to-[#040811]"
        }`}>

          {/* Cover Header */}
          <div className="space-y-1">
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-blue-400 font-bold tracking-[0.3em] uppercase block">ELYZARETH OS</span>
                {isPlaying && (
                  <span className={`text-[8px] px-1.5 py-0.2 border font-bold animate-pulse rounded transition-colors duration-1000 ${
                    isDiagnosticsMode 
                      ? "bg-cyan-950 text-cyan-400 border-cyan-800" 
                      : "bg-emerald-950 text-emerald-400 border-emerald-800"
                  }`}>
                    {isDiagnosticsMode ? "● DIAGNOSTICS ACTIVE" : "● ACTIVE STREAM"}
                  </span>
                )}
              </div>

              {/* Event Commits Ledger Overlay */}
              <div className="text-right text-[8px] text-slate-500 font-bold">
                <span className="text-cyan-500 font-mono">[COMMIT #04{activeIndex + 1}]</span> {TRACK_SECTIONS[activeIndex].phase} ✓ VERIFIED
              </div>
            </div>

            <h2 className="text-3xl md:text-4xl font-extrabold tracking-widest text-slate-100 uppercase bg-clip-text text-transparent bg-gradient-to-r from-slate-100 via-blue-200 to-slate-200">
              IMMUTABLE LIGHT
            </h2>
            <p className="text-[9px] text-red-500 font-bold tracking-[0.4em] uppercase">LOGS REMEMBER. MEMORY ENDURES.</p>
          </div>

