            {/* Grid Scanline Overlay (2% Opacity) */}
            <div className="absolute inset-0 bg-[linear-gradient(rgba(18,24,38,0.2)_1px,_transparent_1px),_linear-gradient(90deg,_rgba(18,24,38,0.2)_1px,_transparent_1px)] bg-[size:16px_16px] pointer-events-none opacity-40" />
            <div className="absolute inset-0 bg-[linear-gradient(to_bottom,_rgba(13,148,136,0.02)_50%,_transparent_50%)] bg-[size:100%_4px] pointer-events-none" />

            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-950/20 via-transparent to-transparent" />

