            <div className={`absolute top-0 bottom-0 w-[3px] bg-gradient-to-b from-blue-400 via-cyan-500 to-transparent shadow-[0_0_15px_rgba(56,189,248,0.6)] transition-all duration-1000 ${
              beamPulse ? "opacity-100 scale-x-110" : "opacity-60 scale-x-90"
