            {/* Invariants locked panel (Overlay Left) */}
            <div className="absolute left-4 top-4 p-3 bg-slate-950/80 border border-slate-850 rounded backdrop-blur-sm text-[9px] text-slate-400 space-y-1.5 z-10 w-36">
