              </div>
              <div className="border-t border-slate-850 pt-1 text-[8px] text-slate-500">
                ELYZARETH CORE v31.0
              </div>
            </div>

            {/* System Status Panel (Overlay Right) */}
            <div className="absolute right-4 top-4 p-3 bg-slate-950/80 border border-slate-850 rounded backdrop-blur-sm text-[9px] text-slate-400 space-y-1.5 z-10 w-44">
