                min="0" 
                max="100" 
                value={progress}
                onChange={handleProgressChange}
                className="w-full h-1.5 bg-white/10 rounded-lg appearance-none cursor-pointer accent-sky-400 transition-all"
              />
            </div>

            {/* Core Action buttons */}
            <div className="flex items-center justify-between">

              {/* Back skip */}
              <button 
                onClick={handlePrev}
                className="p-2.5 rounded-full hover:bg-white/5 text-slate-400 hover:text-white transition-all"
              >
                <SkipBack className="w-5 h-5" />
              </button>

              {/* Main Play / Pause Circle */}
              <button 
                onClick={togglePlay}
                style={{ backgroundColor: track.accentColor }}
                className="p-4 rounded-full text-white hover:scale-105 active:scale-95 transition-all shadow-lg hover:shadow-xl"
              >
                {isPlaying ? <Pause className="w-6 h-6 fill-white" /> : <Play className="w-6 h-6 fill-white ml-0.5" />}
              </button>

              {/* Forward skip */}
              <button 
                onClick={handleNext}
                className="p-2.5 rounded-full hover:bg-white/5 text-slate-400 hover:text-white transition-all"
              >
                <SkipForward className="w-5 h-5" />
              </button>

            </div>

            {/* Quick Track Select Carousel list */}
            <div className="flex items-center gap-2 overflow-x-auto py-2 scrollbar-none">
              {ALBUM_TRACKS.map((t, idx) => (
                <button
                  key={t.id}
                  onClick={() => {
                    setProgress(0);
                    setCurrentTrackIndex(idx);
                    setIsPlaying(false);
                  }}
                  className={`flex-shrink-0 flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs tracking-wider transition-all ${currentTrackIndex === idx ? "bg-white/10 border-white/20 text-white font-semibold" : "bg-transparent border-white/5 text-slate-400 hover:border-white/10 hover:text-slate-200"}`}
                >
                  <span className="font-mono text-[10px] opacity-60">{t.trackNum}</span>
                  <span>{t.title}</span>
                </button>
              ))}
            </div>

          </div>

        </div>

      </div>

      {/* Embedded Raw Audio tag to keep things fully playable and sandboxed */}
      <audio 
        ref={audioRef}
        src={track.mediaUrl}
        onTimeUpdate={handleTimeUpdate}
        onEnded={handleNext}
        crossOrigin="anonymous"
      />

      {/* Subtitle / Footer Citation */}
      <p className="mt-6 text-center text-xs tracking-[0.25em] text-slate-500 uppercase flex items-center gap-2 relative z-10">
        <span>ELYZARETH // THE HUMAN JOURNEY</span>
        <span>•</span>
        <span>ARCHITECTURAL SOUND TRACKBOOK</span>
      </p>

    </div>
  );
}

