export default function Component() {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTimeFormatted, setCurrentTimeFormatted] = useState("0:00");
  const [volume, setVolume] = useState(0.8);
  const [activeTab, setActiveTab] = useState<"visualizer" | "lyrics" | "telemetry">("visualizer");

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const track = ALBUM_TRACKS[currentTrackIndex];

  // Initialize audio volume on mount
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, []);

  // Sync volume change
  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    if (audioRef.current) {
      audioRef.current.volume = val;
    }
  };

  // Toggle Play / Pause
  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      audioRef.current.play().then(() => {
        setIsPlaying(true);
      }).catch(err => {
        console.error("Audio playback error:", err);
      });
    }
  };

  // Handle skip next / previous
  const handleNext = () => {
    const nextIdx = (currentTrackIndex + 1) % ALBUM_TRACKS.length;
    setProgress(0);
    setCurrentTrackIndex(nextIdx);
    setIsPlaying(false);
  };

  const handlePrev = () => {
    const prevIdx = (currentTrackIndex - 1 + ALBUM_TRACKS.length) % ALBUM_TRACKS.length;
    setProgress(0);
    setCurrentTrackIndex(prevIdx);
    setIsPlaying(false);
  };

  // Autoplay or handle track change
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.src = track.mediaUrl;
      audioRef.current.load();
      if (isPlaying) {
        audioRef.current.play().then(() => {
          setIsPlaying(true);
        }).catch(() => {
          setIsPlaying(false);
        });
      }
    }
  }, [currentTrackIndex]);

  // Audio TimeUpdate Listener
  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const cur = audioRef.current.currentTime;
      const dur = audioRef.current.duration || 1;
      setProgress((cur / dur) * 100);

      const mins = Math.floor(cur / 60);
      const secs = Math.floor(cur % 60);
      setCurrentTimeFormatted(`${mins}:${secs < 10 ? "0" : ""}${secs}`);
    }
  };

  // Handle progress slider manual adjustment
  const handleProgressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (audioRef.current) {
      const val = parseFloat(e.target.value);
      const dur = audioRef.current.duration || 0;
      audioRef.current.currentTime = (val / 100) * dur;
      setProgress(val);
    }
  };

  // Render Starfield Background canvas simulation
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId: number;
    let width = canvas.width = canvas.offsetWidth;
    let height = canvas.height = canvas.offsetHeight;

    // Handle Resize
    const resizeObserver = new ResizeObserver(() => {
      if (canvas) {
        width = canvas.width = canvas.offsetWidth;
        height = canvas.height = canvas.offsetHeight;
      }
    });
    resizeObserver.observe(canvas);

    // Star Generation based on current track index speed & color accents
    interface Star {
      x: number;
      y: number;
      size: number;
      speed: number;
      alpha: number;
      alphaSpeed: number;
      angle: number;
    }

    const starCount = 120;
    const stars: Star[] = [];
    for (let i = 0; i < starCount; i++) {
      stars.push({
        x: Math.random() * width,
        y: Math.random() * height,
        size: Math.random() * 1.8 + 0.3,
        speed: Math.random() * 0.15 + 0.05,
        alpha: Math.random() * 0.8 + 0.2,
        alphaSpeed: Math.random() * 0.01 + 0.005,
        angle: Math.random() * Math.PI * 2
      });
    }

    // Constellation lines helper
    const drawConstellations = () => {
      ctx.strokeStyle = "rgba(14, 165, 233, 0.08)";
      ctx.lineWidth = 0.5;
      for (let i = 0; i < stars.length; i++) {
        for (let j = i + 1; j < stars.length; j++) {
          const dist = Math.hypot(stars[i].x - stars[j].x, stars[i].y - stars[j].y);
          if (dist < 75) {
            ctx.beginPath();
            ctx.moveTo(stars[i].x, stars[i].y);
            ctx.lineTo(stars[j].x, stars[j].y);
            ctx.stroke();
          }
        }
      }
    };

    const drawPulseGraphic = (time: number) => {
      // Harmonic wave in background
      ctx.strokeStyle = `${track.accentColor}30`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      const waveSpeed = isPlaying ? time * 0.004 : time * 0.0005;
      for (let x = 0; x < width; x++) {
        const amplitude = isPlaying ? 22 : 6;
        const frequency = 0.008;
        const y = height * 0.7 + Math.sin(x * frequency + waveSpeed) * amplitude;
        if (x === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      }
      ctx.stroke();
    };

    let lastTime = 0;
    const render = (time: number) => {
      ctx.fillStyle = track.bgTone;
      ctx.fillRect(0, 0, width, height);

      // Stars Update
      stars.forEach((star) => {
        // Shimmer / twinkle
        star.alpha += star.alphaSpeed;
        if (star.alpha > 0.95 || star.alpha < 0.15) {
          star.alphaSpeed = -star.alphaSpeed;
        }

        // Slow movement based on play status
        const currentSpeed = isPlaying ? star.speed * 2.2 : star.speed;
        star.y -= currentSpeed;
        if (star.y < 0) {
          star.y = height;
          star.x = Math.random() * width;
        }

        // Draw star
        ctx.fillStyle = `rgba(255, 255, 255, ${star.alpha})`;
        ctx.beginPath();
        ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
        ctx.fill();

        // High glow for current accent stars
        if (star.size > 1.8) {
          ctx.shadowBlur = 10;
          ctx.shadowColor = track.accentColor;
          ctx.fillStyle = track.accentColor;
          ctx.beginPath();
          ctx.arc(star.x, star.y, star.size * 1.2, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0; // Reset
        }
      });

      drawConstellations();
      drawPulseGraphic(time);

      animationFrameId = requestAnimationFrame(render);
    };

    render(0);

    return () => {
      cancelAnimationFrame(animationFrameId);
      resizeObserver.disconnect();
    };
  }, [currentTrackIndex, isPlaying]);

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center p-4 md:p-8 bg-zinc-950 text-slate-100 select-none relative overflow-hidden font-sans">

      {/* Absolute background visualizer canvas */}
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none z-0 opacity-80" />

      {/* Main Container Wrapper */}
      <div className="w-full max-w-5xl bg-zinc-900/60 backdrop-blur-xl border border-white/5 rounded-2xl shadow-2xl overflow-hidden z-10 flex flex-col md:flex-row min-h-[600px]">

        {/* Left Panel: Track Information, Album Cover & Visual Dashboard */}
        <div className="w-full md:w-5/12 p-6 md:p-8 flex flex-col justify-between border-b md:border-b-0 md:border-r border-white/5 relative z-10">

          {/* Header OS Identifier */}
          <div className="flex items-center justify-between text-xs tracking-[0.2em] uppercase text-slate-400">
            <div className="flex items-center gap-2">
              <Cpu className="w-4 h-4 text-sky-400 animate-pulse" />
              <span>ELYZARETH OS v30.0</span>
            </div>
            <span className="px-2 py-0.5 rounded bg-white/5 text-[10px] text-emerald-400 font-mono">STATUS: ACTIVE</span>
          </div>

          {/* Cinematic Album Disc Jacket Mock */}
          <div className="my-8 flex flex-col items-center justify-center">
            <div className="relative w-56 h-56 rounded-xl overflow-hidden shadow-2xl border border-white/10 group flex items-center justify-center">

              {/* Dynamic colorful overlay representing the current track aesthetic */}
              <div className={`absolute inset-0 bg-gradient-to-tr ${track.color} opacity-90 transition-all duration-1000`} />

              {/* High-tech Solarpunk circuit pattern glow overlay */}
              <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#fff_1px,transparent_1px)] [background-size:16px_16px]" />

              <div className="relative text-center p-6 flex flex-col justify-between h-full w-full z-10">
                <div className="text-left">
                  <span className="text-[10px] tracking-[0.3em] font-mono text-white/50 block mb-1">RELEASE COMPLIANCE</span>
                  <span className="text-xs font-semibold tracking-wider text-white">THE HUMAN JOURNEY</span>
                </div>

                <div className="my-auto">
                  <h2 className="text-2xl font-bold tracking-tight text-white mb-1">{track.title}</h2>
                  <p className="text-xs tracking-widest text-sky-300 font-mono uppercase">{track.subtitle}</p>
                </div>

                <div className="flex items-center justify-between text-[10px] tracking-widest font-mono text-white/40">
                  <span>FP-EA93-71A6</span>
                  <span>v30.0 LTS</span>
                </div>
              </div>

              {/* Heart Pulse Visualizer on Album Jacket */}
              <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center justify-center gap-1 opacity-60">
                <div className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-ping" />
              </div>
            </div>
          </div>

          {/* Meta Info, Accents & Volume Slider */}
          <div className="space-y-4">
            <div>
              <span className="text-[10px] tracking-[0.25em] text-slate-400 uppercase block mb-1">CURRENT SEQUENCE DEPLOYED</span>
              <h1 className="text-xl font-bold tracking-wide text-white">{track.title}</h1>
              <p className="text-sm text-sky-400 tracking-wider font-mono uppercase">{track.subtitle}</p>
            </div>

            <div className="border-t border-white/5 pt-4 flex items-center justify-between text-xs text-slate-400 font-mono">
              <div className="flex items-center gap-2">
                <Music className="w-3.5 h-3.5" />
                <span>Format: v2 (Stereo)</span>
              </div>
              <div className="flex items-center gap-2">
                <Volume2 className="w-3.5 h-3.5" />
                <input 
                  type="range" 
                  min="0" 
                  max="1" 
                  step="0.01" 
                  value={volume}
                  onChange={handleVolumeChange}
                  className="w-16 h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-sky-400"
                />
              </div>
            </div>
          </div>

        </div>

        {/* Right Panel: Interactive Visualizer tabs, Interactive Controls, and Lyrics console */}
        <div className="w-full md:w-7/12 p-6 md:p-8 flex flex-col justify-between relative z-10">

          {/* Tabs header */}
          <div className="flex items-center justify-start gap-4 border-b border-white/5 pb-4">
            <button 
              onClick={() => setActiveTab("visualizer")}
              className={`text-xs uppercase tracking-widest font-mono pb-2 relative transition-all ${activeTab === "visualizer" ? "text-sky-400 font-bold" : "text-slate-400 hover:text-slate-200"}`}
            >
              System Interface
              {activeTab === "visualizer" && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-sky-400 rounded" />}
            </button>
            <button 
              onClick={() => setActiveTab("lyrics")}
              className={`text-xs uppercase tracking-widest font-mono pb-2 relative transition-all ${activeTab === "lyrics" ? "text-sky-400 font-bold" : "text-slate-400 hover:text-slate-200"}`}
            >
              Lyrical Schemas
              {activeTab === "lyrics" && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-sky-400 rounded" />}
            </button>
            <button 
              onClick={() => setActiveTab("telemetry")}
              className={`text-xs uppercase tracking-widest font-mono pb-2 relative transition-all ${activeTab === "telemetry" ? "text-sky-400 font-bold" : "text-slate-400 hover:text-slate-200"}`}
            >
              Telemetry Dashboard
              {activeTab === "telemetry" && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-sky-400 rounded" />}
            </button>
          </div>

          {/* Dynamic Tab Content Area */}
          <div className="flex-grow py-6 overflow-y-auto max-h-[350px] scrollbar-thin scrollbar-thumb-white/5 scrollbar-track-transparent">

            {activeTab === "visualizer" && (
              <div className="space-y-6 animate-fadeIn">
                <div className="p-4 rounded-xl bg-white/[0.02] border border-white/5 space-y-3">
                  <h3 className="text-xs uppercase tracking-widest text-slate-400 font-mono flex items-center gap-2">
                    <Sparkles className="w-3.5 h-3.5 text-pink-400" />
