                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-ping" />
                      <span>Replay Pure</span>
                    </div>
                    <div className="px-2 py-1 rounded bg-white/5">
                      <span>Widescreen 16:9 Matrix</span>
                    </div>
                  </div>
                </div>

                {/* Simulated EKG Heartbeat Graphic */}
                <div className="p-4 rounded-xl bg-white/[0.02] border border-white/5 flex flex-col justify-center items-center h-28 relative overflow-hidden">
                  <span className="absolute top-2 left-3 text-[10px] tracking-widest font-mono text-slate-500">EKG PROVENANCE SEQUENCE</span>
                  <div className="w-full max-w-sm flex items-center justify-center relative mt-2">
                    {/* Pulsing Neon EKG svg line */}
                    <svg viewBox="0 0 400 100" className="w-full h-16 stroke-rose-500 fill-none stroke-2">
                      <path d="M 0 50 L 120 50 L 130 30 L 140 70 L 150 50 L 180 50 L 190 20 L 200 80 L 210 50 L 240 50" className={isPlaying ? "animate-pulse" : ""} />
                      {/* Heart symbol right in the center */}
                      <path d="M 230 40 C 230 35, 235 30, 240 30 C 245 30, 250 35, 250 40 C 250 50, 240 60, 240 60 C 240 60, 230 50, 230 40 Z" fill={track.accentColor} className={isPlaying ? "animate-bounce" : ""} />
                      <path d="M 240 50 L 270 50 L 280 10 L 290 90 L 300 50 L 400 50" className={isPlaying ? "animate-pulse" : ""} />
                    </svg>
                  </div>
                </div>
              </div>
            )}

            {activeTab === "lyrics" && (
              <div className="space-y-4 animate-fadeIn font-mono text-xs text-slate-300 leading-relaxed whitespace-pre-line p-4 rounded-xl bg-white/[0.01] border border-white/5">
