export default function Component() {
  const [selectedScenarioId, setSelectedScenarioId] = useState<string>("quiet-longing");
  const [compareTargetId, setCompareTargetId] = useState<string>("sunlight");
  const [replayIndex, setReplayIndex] = useState<number>(0);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [playSpeed, setPlaySpeed] = useState<number>(1000);
  const [selectedRecordSeq, setSelectedRecordSeq] = useState<number | null>(null);

  // Load scenarios
  const scenario = useMemo(() => {
    return scenarios.find(s => s.id === selectedScenarioId) || scenarios[0];
  }, [selectedScenarioId]);

  // Set replay index to max on scenario change
  useEffect(() => {
    setReplayIndex(scenario.records.length);
    setIsPlaying(false);
  }, [scenario]);

  // Set comparative target to a different scenario by default
  useEffect(() => {
    const other = scenarios.find(s => s.id !== selectedScenarioId);
    if (other) setCompareTargetId(other.id);
  }, [selectedScenarioId]);

  // Pure fold optimization with useMemo based strictly on active records
  const activeRecords = useMemo(() => {
    return scenario.records.slice(0, replayIndex);
  }, [scenario, replayIndex]);

  const report = useMemo(() => {
    return calculateAnalytics(activeRecords);
  }, [activeRecords]);

  // Pre-calculate full scenario reports for comparative engine (C19)
  const fullScenarioReports = useMemo(() => {
    const map: Record<string, any> = {};
    for (const sc of scenarios) {
      map[sc.id] = calculateAnalytics(sc.records);
    }
    return map;
  }, []);

  const deltaReport = useMemo(() => {
    const base = report;
    const compare = fullScenarioReports[compareTargetId];
    if (!base || !compare) return null;
    return compareScenarioReports(base, compare, selectedScenarioId, compareTargetId);
  }, [report, fullScenarioReports, selectedScenarioId, compareTargetId]);

  // C20: Compute historical telemetry trend trajectory over chronological segments
  const reportHistory = useMemo(() => {
    const history: any[] = [];
    for (let i = 1; i <= replayIndex; i++) {
      history.push(calculateAnalytics(scenario.records.slice(0, i)));
    }
    return history;
  }, [scenario, replayIndex]);

  const trendAnalysis = useMemo(() => {
    return calculateTrendAnalysis(reportHistory);
  }, [reportHistory]);

  // Replay control system
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    if (isPlaying) {
      timer = setInterval(() => {
        setReplayIndex(prev => {
          if (prev >= scenario.records.length) {
            setIsPlaying(false);
            return prev;
          }
          return prev + 1;
        });
      }, playSpeed);
    }
    return () => {
      if (timer) clearInterval(timer);
    };
  }, [isPlaying, playSpeed, scenario]);

  const handleStepBack = () => {
    setIsPlaying(false);
    setReplayIndex(prev => Math.max(0, prev - 1));
  };

  const handleStepForward = () => {
    setIsPlaying(false);
