export function EvidenceTraceView({ report, records, onSelectRecord }: TraceProps) {
  const [activeObsId, setActiveObsId] = useState<string | null>(null);

  // Sync activeObsId state when report.observations changes to prevent pointing to deleted/stale records
  useEffect(() => {
    if (report.observations.length > 0) {
      const exists = report.observations.some(o => o.id === activeObsId);
      if (!exists) {
        setActiveObsId(report.observations[0].id);
      }
    } else {
      setActiveObsId(null);
