      case "elyzareth-roe": return <Activity className="w-4 h-4 text-purple-400" />;
      case "elyzareth-entropy": return <Network className="w-4 h-4 text-amber-400" />;
      default: return <Database className="w-4 h-4 text-zinc-400" />;
