        case "ExecutionSubmitted":
          total_executions++;
          pm.execs++;
          break;
        case "ExecutionCompleted":
          successful_executions++;
          pm.comps++;
          total_latency_ms += r.event.duration_ms;
          latency_count++;
          pm.lat_sum += r.event.duration_ms;
          pm.lat_cnt++;
