                {/* Narrative Observations Block */}
                <div className="mt-4 bg-zinc-900/60 p-3 border-l-2 border-emerald-500 rounded text-xs text-zinc-400">
                  <span className="font-bold text-zinc-300 block mb-1">C17 Operational Observation:</span>
                  {activeReport.observations[0]}
                </div>
              </div>
            )}

            {/* C16-L4 Step-by-Step Replay Timeline Controller */}
            {records.length > 0 && (
              <div className="bg-zinc-950/60 border border-zinc-800 rounded-md p-4">
                <div className="flex items-center justify-between border-b border-zinc-800 pb-3 mb-4">
