                    <Cpu className="h-4 w-4 text-emerald-500" /> C16-L4 Step Replay Controller
                  </h2>
                  <span className="text-[10px] text-zinc-500">Sequence-locked Replay Mode</span>
                </div>

                {replayEvents.length === 0 ? (
                  <button
                    onClick={initReplayTimeline}
                    className="w-full py-2 bg-zinc-900 border border-zinc-800 hover:border-zinc-700 rounded text-xs font-bold transition-all"
                  >
                    Load Current Timeline Into Replay Sandbox
                  </button>
                ) : (
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                      <div className="text-xs">
                        Step <span className="font-bold text-emerald-400">{currentReplayIndex + 1}</span> of <span className="text-zinc-400">{replayEvents.length}</span>
                      </div>
                      <div className="flex gap-2">
                        <button
                          onClick={() => { setReplayEvents([]); setCurrentReplayIndex(-1); }}
                          className="p-1 px-2 text-[10px] border border-zinc-800 hover:border-zinc-700 bg-zinc-900 rounded text-zinc-400"
                        >
                          Reset
                        </button>
                        <button
                          onClick={stepReplay}
                          disabled={currentReplayIndex === replayEvents.length - 1}
                          className={`p-1 px-3 text-[10px] font-bold rounded flex items-center gap-1 transition-all ${
                            currentReplayIndex === replayEvents.length - 1
                              ? "bg-zinc-800 text-zinc-600 cursor-not-allowed"
                              : "bg-emerald-500 hover:bg-emerald-600 text-zinc-950"
                          }`}
                        >
                          Step Forward <ArrowRight className="h-2.5 w-2.5" />
                        </button>
                      </div>
                    </div>

                    {/* Step visualization display */}
                    <div className="bg-zinc-900 border border-zinc-800 p-3 rounded">
                      <div className="flex justify-between items-center text-[10px] text-zinc-500 mb-2 border-b border-zinc-800 pb-1">
                        <span>REPLAY SEQ: #{replayEvents[currentReplayIndex]?.sequence_number}</span>
                        <span>EPOCH: {replayEvents[currentReplayIndex]?.timestamp_epoch_ms}ms</span>
                      </div>
                      <div className="text-xs font-bold text-emerald-400">
                        {replayEvents[currentReplayIndex]?.event.type}
                      </div>
                      <p className="text-[10px] text-zinc-400 mt-1">
                        Executed by provider <span className="font-bold text-zinc-300">{replayEvents[currentReplayIndex]?.provider}</span>. 
                        Provenance mapping hashes isolated. No execution path drift detected.
                      </p>
                    </div>
                  </div>
                )}
              </div>
            )}

          </div>

        </div>

      </div>
    </div>
  );
}

