                    setLogs([`[SYSTEM] Intent normalization complete. Emitting validation frame.`]);
                  }
                }}
                className="w-full py-2 bg-[#E11D48] hover:bg-[#EF4444] text-white rounded text-xs font-semibold font-mono tracking-wide transition uppercase flex items-center justify-center gap-1.5"
                disabled={isProcessing}
