            <div className="flex items-center justify-between border-b border-[#1F2937] pb-2">
              <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-[#94A3B8] flex items-center gap-1.5">
                <Terminal className="w-4 h-4 text-emerald-400" /> Live Event Log
              </h2>
              <button 
                onClick={handleRunSimulation}
                className="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-500 rounded text-[10px] text-white font-mono font-bold transition flex items-center gap-1"
                disabled={isProcessing}
              >
                <Play className="w-3 h-3" /> Execute Pipeline
              </button>
            </div>

            <div className="h-44 bg-[#060810] border border-[#1F2937] rounded p-2.5 font-mono text-[10px] text-emerald-400 overflow-y-auto flex flex-col gap-1 scrollbar-thin select-text">
