                <div key={idx} className="leading-tight border-l border-emerald-500/10 pl-1.5">
                  {log}
                </div>
              ))}
            </div>
          </section>

        </div>

        {/* Column 2: Stage Timeline & Inspection (span 4) */}
        <div className="lg:col-span-4 flex flex-col gap-4">

          <div className="bg-[#111622] border border-[#1F2937] rounded-lg p-4 flex flex-col gap-3">
            <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-[#94A3B8] border-b border-[#1F2937] pb-2 flex items-center gap-1.5">
              <Layers className="w-4 h-4 text-[#E11D48]" /> Stage Timeline (P1.1)
            </h2>

            <div className="flex flex-col gap-1.5 overflow-y-auto max-h-[500px] scrollbar-thin pr-1">
              {selectedBlueprint.stages.map((stage) => {
                const isActive = stage.id === activeStageId;
                return (
                  <div 
                    key={stage.id}
                    onClick={() => setActiveStageId(stage.id)}
                    className={`cursor-pointer p-2.5 rounded border transition flex items-center justify-between font-mono text-xs ${
                      isActive 
