                        : "bg-[#090D16] border-[#1F2937] hover:bg-[#111520] text-[#94A3B8]"
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <span className={`w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-bold ${
                        isActive ? "bg-[#E11D48] text-white" : "bg-slate-800 text-[#94A3B8]"
                      }`}>
                        {stage.id}
                      </span>
                      <span>{stage.name}</span>
                    </div>
                    {stage.status === "passed" ? (
                      <CheckCircle className="w-3.5 h-3.5 text-emerald-400" />
                    ) : (
                      <div className="w-2.5 h-2.5 rounded-full bg-slate-700 animate-pulse"></div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Active Stage Inspection Panel */}
          <section className="bg-[#111622] border border-[#1F2937] rounded-lg p-5 flex flex-col gap-3">
            <h3 className="text-xs font-mono font-bold uppercase tracking-wider text-[#94A3B8] border-b border-[#1F2937] pb-2 flex items-center gap-1">
