            </h3>
            <div className="font-mono text-xs flex flex-col gap-2">
              <div className="bg-[#090D16] border border-[#1F2937] p-3 rounded">
                <span className="text-[10px] text-[#64748B] block uppercase font-bold">Active Subsystem</span>
                <span className="text-white text-sm font-semibold">{activeStage.name}</span>
              </div>
              <div className="bg-[#090D16] border border-[#1F2937] p-3 rounded leading-relaxed text-[#94A3B8] text-[11px]">
                {activeStage.description}
              </div>
              <div className="flex flex-col gap-1 mt-1 border-t border-[#1F2937] pt-2">
                <span className="text-[9px] text-[#64748B] uppercase font-bold">Stage Metrics</span>
