                    <span className="text-cyan-400 font-bold">{m.value} {m.unit || ""}</span>
                  </div>
                ))}
              </div>
            </div>
          </section>

        </div>

        {/* Column 3: Metrics & Creative DNA Registry (span 4) */}
        <div className="lg:col-span-4 flex flex-col gap-4">

          {/* Validation Metrics Panel */}
          <section className="bg-[#111622] border border-[#1F2937] rounded-lg p-5 flex flex-col gap-4">
            <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-[#94A3B8] border-b border-[#1F2937] pb-2 flex items-center gap-1.5">
              <PieChart className="w-4 h-4 text-[#E11D48]" /> Diagnostics Summary
            </h2>

            <div className="flex flex-col gap-3 text-xs font-mono">
              {/* Entropy Analyzer score */}
              <div className="p-2.5 bg-[#090D16] border border-[#1F2937] rounded">
                <div className="flex justify-between items-center text-[10px] text-[#94A3B8] mb-1">
                  <span className="font-bold">ENTROPY FACTOR</span>
                  <span className="text-emerald-400 font-bold">{selectedBlueprint.entropy}</span>
                </div>
                <div className="w-full h-1.5 bg-[#1F2937] rounded overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-emerald-500 to-[#E11D48]" 
                    style={{ width: `${selectedBlueprint.entropy * 100}%` }}
                  ></div>
                </div>
              </div>

              {/* Emotional Coordinate grid */}
              <div className="p-2.5 bg-[#090D16] border border-[#1F2937] rounded flex flex-col gap-1.5">
                <span className="text-[10px] text-[#64748B] uppercase font-bold">Emotional Topology Map</span>
                <div className="relative w-full h-24 bg-[#05070D] border border-[#1E293B] rounded flex items-center justify-center overflow-hidden">
                  <div className="absolute inset-0 grid grid-cols-2 grid-rows-2">
                    <div className="border-r border-b border-slate-800/40"></div>
