export default function Component() {
  const [events, setEvents] = useState<LedgerEvent[]>(initialEvents);
  const [selectedEvent, setSelectedEvent] = useState<LedgerEvent | null>(initialEvents[0]);
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [selectedSubsystem, setSelectedSubsystem] = useState<string>("All");
  const [selectedCorrelationId, setSelectedCorrelationId] = useState<string>("All");
  const [selectedSession, setSelectedSession] = useState<string>("All");

  // Replay Simulator State
  const [isReplaying, setIsReplaying] = useState<boolean>(false);
  const [replayTick, setReplayTick] = useState<number>(0);
  const [replayMax, setReplayMax] = useState<number>(initialEvents.length - 1);
  const [playbackSpeed, setPlaybackSpeed] = useState<number>(1000); // ms per event
  const [logs, setLogs] = useState<string[]>(["[SYSTEM] Elyzareth C14 Lens Observability system active."]);

  // Filters for dropdowns
  const uniqueSubsystems = useMemo(() => ["All", ...Array.from(new Set(initialEvents.map(e => e.subsystem)))], []);
  const uniqueCorrelationIds = useMemo(() => ["All", ...Array.from(new Set(initialEvents.map(e => e.correlationId)))], []);
  const uniqueSessions = useMemo(() => ["All", ...Array.from(new Set(initialEvents.map(e => e.sessionId)))], []);

  // Filtered events for the general view
  const filteredEvents = useMemo(() => {
    return events.filter(e => {
      const matchesSearch = e.details.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            e.type.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            e.correlationId.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesSubsystem = selectedSubsystem === "All" || e.subsystem === selectedSubsystem;
      const matchesCorrelation = selectedCorrelationId === "All" || e.correlationId === selectedCorrelationId;
      const matchesSession = selectedSession === "All" || e.sessionId === selectedSession;
      return matchesSearch && matchesSubsystem && matchesCorrelation && matchesSession;
    });
  }, [events, searchTerm, selectedSubsystem, selectedCorrelationId, selectedSession]);

  // Logs stream ref for auto scrolling
  const logTerminalRef = useRef<HTMLDivElement>(null);

  // Auto scroll logs
  useEffect(() => {
    if (logTerminalRef.current) {
      logTerminalRef.current.scrollTop = logTerminalRef.current.scrollHeight;
    }
  }, [logs]);

  // Replay Simulator Logic
  useEffect(() => {
    let interval: any = null;
    if (isReplaying) {
      interval = setInterval(() => {
        setReplayTick(prev => {
          if (prev >= replayMax) {
            setIsReplaying(false);
            setLogs(l => [...l, `[SYSTEM] Replay simulation reached end-of-chain at Tick ${initialEvents[replayMax].tick}`]);
            return prev;
          }
          const nextTickIdx = prev + 1;
          const targetEv = initialEvents[nextTickIdx];
          setSelectedEvent(targetEv);
          setLogs(l => [...l, `[TICK ${targetEv.tick}] [${targetEv.subsystem}] Dispatching ${targetEv.type} (Session: ${targetEv.sessionId}, CID: ${targetEv.correlationId})`]);
          return nextTickIdx;
        });
      }, playbackSpeed);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isReplaying, replayMax, playbackSpeed]);

  const handleStartReplay = () => {
    setIsReplaying(true);
    setLogs(l => [...l, `[SYSTEM] Initiating sequential session-replay simulation...`]);
  };

  const handlePauseReplay = () => {
    setIsReplaying(false);
    setLogs(l => [...l, `[SYSTEM] Replay simulation paused at index ${replayTick}.`]);
  };

  const handleResetReplay = () => {
    setIsReplaying(false);
    setReplayTick(0);
    setSelectedEvent(initialEvents[0]);
    setLogs([`[SYSTEM] Replay simulator state reset. Immutable baseline at Tick ${initialEvents[0].tick} re-established.`]);
  };

  // Quick stats computed
  const avgLatency = useMemo(() => {
    const sum = events.reduce((acc, curr) => acc + curr.latencyMs, 0);
    return (sum / events.length).toFixed(3);
  }, [events]);

  const errorCount = useMemo(() => {
    return events.filter(e => e.status === "error").length;
  }, [events]);

  // B. Layer Heat Map Calculation
  const subsystemLoadMetrics = useMemo(() => {
    const counts: Record<string, number> = {};
    events.forEach(e => {
      counts[e.subsystem] = (counts[e.subsystem] || 0) + 1;
    });
    const maxVal = Math.max(...Object.values(counts), 1);
    return Object.entries(counts).map(([sub, count]) => ({
      subsystem: sub,
      count,
      intensity: (count / maxVal) * 100
    }));
  }, [events]);

  // D. Provenance Backtrace Graph (Trace backwards to Boot Init)
  const provenanceBacktrace = useMemo(() => {
    if (!selectedEvent) return [];
    // Filter events in the same session that came before or equal to the selectedEvent
    const ancestors = events
      .filter(e => e.sessionId === selectedEvent.sessionId && e.tick <= selectedEvent.tick)
      .sort((a, b) => b.tick - a.tick); // Newest first
    return ancestors;
  }, [selectedEvent, events]);

  // A. Correlation Tree Visualization of the active selected session / transaction Group
  const correlationTree = useMemo(() => {
    if (!selectedEvent) return null;
    const sessionEvents = events.filter(e => e.sessionId === selectedEvent.sessionId);

    // Group events in this session by Correlation ID
    const groups: Record<string, LedgerEvent[]> = {};
    sessionEvents.forEach(e => {
      if (!groups[e.correlationId]) groups[e.correlationId] = [];
      groups[e.correlationId].push(e);
    });

    return {
      sessionId: selectedEvent.sessionId,
      transactions: Object.entries(groups).map(([cid, evs]) => ({
        correlationId: cid,
        steps: evs.sort((a, b) => a.tick - b.tick)
      }))
    };
  }, [selectedEvent, events]);

  // Dynamic Time Travel Reconstruction of Subsystem State mapping
  const reconstructedState = useMemo(() => {
    if (!selectedEvent) return null;

    const currentTick = selectedEvent.tick;
    const cid = selectedEvent.correlationId;
    const sid = selectedEvent.sessionId;

    return {
      kernel: {
        tick: currentTick,
        status: currentTick >= 15292 ? "DEGRADED (Rollback pending)" : "NOMINAL",
        activeCid: cid,
        activeSession: sid,
        bootHash: "0x8B4F3A5C9E11D48A"
      },
      composition: {
        profile: currentTick >= 15281 ? "Resonance Curve Alpha (Mapped)" : "UNINITIALIZED",
        nodes: currentTick >= 15281 ? ["InputResonance", "ValenceAttenuator", "TemporalIntegrator"] : []
      },
      capability: {
        boundary: currentTick >= 15282 ? "Isolated [ROE Engine Port Bound]" : "STRICT_RESTRICTED",
        memoryAddress: "0x7FFD_8E1F_90A1"
      },
      contract: {
        invariants: ["C12.1_TemporalMonotonicity", "C12.2_BoundedCapability", "C12.3_ClampingInvariant"],
        activeVerification: selectedEvent.subsystem === "Contract" ? "ACTIVE_AUDIT" : "IDLE (Pre-verified)",
        validationStatus: selectedEvent.status === "error" ? "VIOLATION_TRIGGERED" : "SATISFIED"
      },
      supervisor: {
        dualConsensusDrift: selectedEvent.status === "error" ? "DIVERGENT (Core 1 != Core 2)" : "0.0000ms (SYNC)",
        activeRollbackAddress: currentTick >= 15292 ? "Tick 15289 (Stable)" : "N/A"
      }
    };
  }, [selectedEvent]);

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-start bg-[#0A0C10] text-[#E1E6EB] font-sans p-4 md:p-8 select-none">

      {/* Header Panel */}
      <header className="w-full max-w-7xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 pb-6 mb-6 border-b border-[#1E2330]">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="px-2 py-0.5 text-xs font-mono font-bold bg-[#E11D48] text-white rounded">C14</span>
            <h1 className="text-xl md:text-2xl font-semibold tracking-tight text-white flex items-center gap-2">
              ELYZARETH OS Lens <span className="text-xs text-[#94A3B8] font-mono font-bold">v25.0 KIL (Baseline Sealed)</span>
            </h1>
          </div>
          <p className="text-xs md:text-sm text-[#94A3B8] max-w-2xl">
            Real-time multi-ledger correlation and deterministic replay. Observe architecture without state mutation.
          </p>
        </div>

        {/* Real-time telemetry badges */}
        <div className="flex flex-wrap gap-2 text-xs font-mono">
          <div className="bg-[#111827] border border-[#1E293B] px-3 py-1.5 rounded flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <span>KERNEL STATE: <span className="text-emerald-400 font-bold">100% SEALED</span></span>
          </div>
          <div className="bg-[#111827] border border-[#1E293B] px-3 py-1.5 rounded flex items-center gap-2">
            <Clock className="w-3.5 h-3.5 text-[#E11D48]" />
            <span>AVG LATENCY: <span className="text-white font-bold">{avgLatency}ms</span></span>
          </div>
          <div className="bg-[#111827] border border-[#1E293B] px-3 py-1.5 rounded flex items-center gap-2">
            <ShieldCheck className="w-3.5 h-3.5 text-[#E11D48]" />
            <span>PROVENANCE: <span className="text-white font-bold">L2 INDEPENDENT</span></span>
          </div>
        </div>
      </header>

      <main className="w-full max-w-7xl grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Column 1: Left Dashboard & Replay Engine Controls (span 4) */}
        <div className="lg:col-span-4 flex flex-col gap-6">

          {/* Replay Studio Card */}
          <section className="bg-[#111622] border border-[#1F2937] rounded-lg p-5 flex flex-col gap-4">
            <div className="flex items-center justify-between border-b border-[#1F2937] pb-3">
              <div className="flex items-center gap-2">
                <Cpu className="w-4 h-4 text-[#E11D48]" />
                <h2 className="text-sm font-semibold text-white tracking-wide uppercase font-mono">Phase 3: Replay Studio</h2>
