    { id: "2", correlationId: "tx-init-001", logicalTick: 1, subsystem: "C10 Comp", type: "SUCCESS", message: "Tarjan DAG cycle proof: 0 loops found. BootPlan committed." },
    { id: "3", correlationId: "tx-init-001", logicalTick: 2, subsystem: "C10 Comp", type: "INFO", message: "Phase-bound boot: Constructing services..." },
    { id: "4", correlationId: "tx-init-001", logicalTick: 3, subsystem: "C10 Comp", type: "SUCCESS", message: "Phase-bound boot: ResourcesAcquired. Sockets & memory pools online." },
    { id: "5", correlationId: "tx-init-001", logicalTick: 4, subsystem: "C11 Cap", type: "SUCCESS", message: "Negotiated Binding: SafeService authorized for StorageWriter." },
    { id: "6", correlationId: "tx-init-001", logicalTick: 5, subsystem: "C12 Contract", type: "INFO", message: "ContractRegistered: [ID: 0x2E..4F] 'AudioRendererInterface'" },
    { id: "7", correlationId: "tx-init-001", logicalTick: 6, subsystem: "C8/C9 State", type: "SUCCESS", message: "System Online. Monotonic scheduler ticking active." },
  ]);

  // C12 State
  const [expectedSequence, setExpectedSequence] = useState<number>(3);
  const [contractMessages, setContractMessages] = useState<ContractMessage[]>([
    { sequence: 1, payload: "frame_data: [256 Samples; nominal]", signature: "sig_valid_001", status: "Delivered" },
    { sequence: 2, payload: "frame_data: [256 Samples; nominal]", signature: "sig_valid_002", status: "Delivered" },
  ]);
  const [bufferedMessages, setBufferedMessages] = useState<ContractMessage[]>([]);
  const [newPayload, setNewPayload] = useState<string>("frame_data: [256 Samples; audio_frame]");
  const [newSeq, setNewSeq] = useState<number>(3);
  const [corruptSig, setCorruptSig] = useState<boolean>(false);

  // C10 Boot Simulation States
  const [bootLog, setBootLog] = useState<string[]>([]);
  const [isBooting, setIsBooting] = useState<boolean>(false);
  const [simulateBootError, setSimulateBootError] = useState<boolean>(false);

  // Console feed reference for auto-scroll
  const consoleEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (consoleEndRef.current) {
      consoleEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [ledger]);

  // Auto Tick Loop
  useEffect(() => {
    let interval: any;
    if (autoTickActive && schedulerState !== "Offline") {
      interval = setInterval(() => {
        setLogicalTick(prev => {
          const nextTick = prev + 1;

          // Occasional background contract data transmission
          if (nextTick % 12 === 0) {
            transmitAutomaticMessage(nextTick);
          }

          // Run C13 Heartbeat check simulation
          if (nextTick % 8 === 0) {
            simulateHeartbeatCheck(nextTick);
          }

          return nextTick;
        });
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [autoTickActive, schedulerState, expectedSequence, services]);

  const addLog = (subsystem: CorrelationLog["subsystem"], type: CorrelationLog["type"], message: string, customTick?: number) => {
    const txId = `tx-${Math.random().toString(16).substr(2, 4)}-${Math.random().toString(16).substr(2, 4)}`;
    setCorrelationId(txId);
    setLedger(prev => [
      ...prev,
      {
        id: Math.random().toString(),
        correlationId: txId,
        logicalTick: customTick !== undefined ? customTick : logicalTick,
        subsystem,
        type,
        message
      }
    ]);
  };

  const transmitAutomaticMessage = (tick: number) => {
    setExpectedSequence(prevSeq => {
      const payload = "frame_data: [Auto-Tick Stream Packet]";
      const newMsg: ContractMessage = {
        sequence: prevSeq,
        payload,
        signature: `sig_valid_tick_${tick}`,
        status: "Delivered"
      };
      setContractMessages(prev => [...prev, newMsg]);
      addLog("C12 Contract", "SUCCESS", `Automatic packet verified & dispatched to mailbox. Sequence: ${prevSeq}`, tick);
      return prevSeq + 1;
    });
  };

  const simulateHeartbeatCheck = (tick: number) => {
    // Audit current service states
    addLog("C13 Super", "INFO", "Supervisor checking operational watchdogs...", tick);

    // Check if any service is in HalfOpen state and resolve trial
    setServices((prevServices: Service[]) => {
      let changed = false;
      const updated = prevServices.map((s: Service): Service => {
        if (s.circuitState === "HalfOpen") {
          changed = true;
          // Resolve trial (80% chance of success under normal background ticks)
          const success = Math.random() > 0.2;
          if (success) {
            addLog("C13 Super", "SUCCESS", `Trial outcome SUCCESS on '${s.name}'. Resetting recovery budget. Circuit: Closed.`, tick);
            return { ...s, circuitState: "Closed" as CircuitState, retryAttempts: 0, health: "Healthy" as ServiceHealth };
          } else {
            const nextAttempts = s.retryAttempts + 1;
            if (nextAttempts > s.maxRetries) {
              addLog("C13 Super", "FATAL", `Trial outcome FAILED on '${s.name}'. Maximum retry budget exceeded (${s.maxRetries}). Escalating fault!`, tick);
              setSchedulerState("Degraded");
              return { ...s, circuitState: "Quarantined" as CircuitState, retryAttempts: nextAttempts, health: "Failed" as ServiceHealth };
            } else {
              addLog("C13 Super", "WARN", `Trial outcome FAILED on '${s.name}'. Retrying... (${nextAttempts}/${s.maxRetries})`, tick);
              return { ...s, retryAttempts: nextAttempts };
            }
          }
        }
        return s;
      });
      return changed ? updated : prevServices;
    });
  };

  // C12 Manual Message Dispatch
  const handleManualDispatch = () => {
    const signature = corruptSig ? "SIG_CORRUPT_ERR_25" : `sig_valid_manual_${newSeq}`;
    const newMsg: ContractMessage = {
      sequence: newSeq,
      payload: newPayload,
      signature,
      status: "Pending"
    };

    // 1. Signature check (Payload Integrity)
    if (corruptSig) {
      newMsg.status = "Rejected";
      newMsg.error = "PayloadCorruption: Integrated signature fails hash verification.";
      setContractMessages(prev => [...prev, newMsg]);
      addLog("C12 Contract", "FATAL", `PayloadCorruption detected on sequence ${newSeq}. Signature validation failed.`);
      return;
    }

    // 2. Sequence checks
    if (newSeq === expectedSequence) {
      // Nominal sequence path
      newMsg.status = "Delivered";
      setContractMessages(prev => [...prev, newMsg]);
      addLog("C12 Contract", "SUCCESS", `Payload verified. Monotonic order matching. Dispatched to mailbox. Sequence: ${newSeq}`);

      // Look if this fulfills any buffered sequence gaps
      let currentExpected = newSeq + 1;
      let nextBuffer = [...bufferedMessages];
      let deliveredFromBuffer: ContractMessage[] = [];

      // Sort and consume contiguous sequences from buffer
      nextBuffer.sort((a, b) => a.sequence - b.sequence);

      while (nextBuffer.length > 0 && nextBuffer[0].sequence === currentExpected) {
        const bufferedMsg = nextBuffer.shift()!;
        bufferedMsg.status = "Delivered";
        deliveredFromBuffer.push(bufferedMsg);
        addLog("C12 Contract", "SUCCESS", `Buffered Delivery Policy: Re-validated and delivered buffered sequence: ${bufferedMsg.sequence}`);
        currentExpected += 1;
      }

      setBufferedMessages(nextBuffer);
      setContractMessages(prev => [...prev, ...deliveredFromBuffer]);
      setExpectedSequence(currentExpected);
      setNewSeq(currentExpected);
    } else if (newSeq > expectedSequence) {
      // Out of order packet gap detected
      newMsg.status = "Buffered";
      newMsg.error = `BufferedDelivery: Sequence gap detected. Expected: ${expectedSequence}. Holding in isolation.`;
      setBufferedMessages(prev => [...prev, newMsg]);
      addLog("C12 Contract", "WARN", `Out-of-Order Gap detected on Sequence ${newSeq}. Storing in temporary isolation buffer.`);
    } else {
      // Duplicate / Legacy sequence
      newMsg.status = "Rejected";
      newMsg.error = `DuplicateSequence: Expected ${expectedSequence}. Discarding stale envelope.`;
      setContractMessages(prev => [...prev, newMsg]);
      addLog("C12 Contract", "FATAL", `DuplicateSequence rejected on Sequence ${newSeq}. Stale packet dropped.`);
    }
  };

  // C13 Manual Anomaly Injector
  const injectAnomaly = (serviceName: string, reason: FaultReason) => {
    addLog("C13 Super", "WARN", `Manual anomaly injected on '${serviceName}': ${reason}`);

    setServices((prev: Service[]) => prev.map((s: Service): Service => {
      if (s.name === serviceName) {
        // Closed -> Open -> HalfOpen sequence triggers
        let targetState: CircuitState = "Open" as CircuitState;
        let targetHealth: ServiceHealth = "Degraded" as ServiceHealth;
        let nextAttempts = s.retryAttempts;

        if (s.circuitState === "Closed") {
          addLog("C13 Super", "WARN", `Watchdog tripped on '${s.name}'. Opening Circuit Breaker. Capability suspended.`);
          targetState = "Open" as CircuitState;
        }

        // Auto transition to HalfOpen for recovery verification
        addLog("C13 Super", "INFO", `RecoveryPolicy: Transitioning '${s.name}' to HalfOpen state. Routing trial packets.`);
        targetState = "HalfOpen" as CircuitState;
        nextAttempts += 1;

        return {
          ...s,
          circuitState: targetState,
          health: targetHealth,
          retryAttempts: nextAttempts
        };
      }
      return s;
    }));
  };

  // C10 Boot Sequence Simulation
  const triggerBootSequence = () => {
    setIsBooting(true);
    setSchedulerState("RegistryActive");
    setBootLog(["[INFO] Initiating Phase-bound boot scheduling...", "[INFO] Phase 1: Freeze Registry boundary."]);

    setTimeout(() => {
      setBootLog(prev => [...prev, "[SUCCESS] Registry Frozen. Active service list locked immutable.", "[INFO] Phase 2: Resolving Dependency DAG via Tarjan's check."]);
      setSchedulerState("RegistryFrozen");
    }, 1200);

    setTimeout(() => {
      setBootLog(prev => [...prev, "[SUCCESS] BootPlan constructed. Cycle checks passed. Boot sequence: elyzareth_types -> elyzareth_registry -> elyzareth_runtime -> elyzareth_execution -> elyzareth_pool -> roe_renderer -> elyzareth_audio", "[INFO] Phase 3: Constructing services in-memory objects."]);
      setSchedulerState("GraphValidated");
    }, 2400);

    setTimeout(() => {
      if (simulateBootError) {
        setBootLog(prev => [
          ...prev, 
          "[FATAL] Service construction failed on 'roe_renderer' due to driver allocation timeout.",
          "[WARN] EMERGENCY ROLLBACK ACTIVATED: Tearing down previously constructed blocks...",
          "[INFO] Rollback: elyzareth_pool -> Terminated",
          "[INFO] Rollback: elyzareth_execution -> Terminated",
          "[INFO] Rollback: elyzareth_runtime -> Terminated",
          "[INFO] Rollback: elyzareth_registry -> Terminated",
          "[INFO] Rollback: elyzareth_types -> Terminated",
          "[SUCCESS] Rollback complete. System returned cleanly to OFFLINE state to prevent state corruption."
        ]);
        setSchedulerState("Offline");
        setIsBooting(false);
        addLog("C10 Comp", "FATAL", "Boot sequence failed on 'roe_renderer'. Safe emergency rollback executed cleanly.");
      } else {
        setBootLog(prev => [...prev, "[SUCCESS] All service instances constructed.", "[INFO] Phase 4: Acquiring Sockets, Channels, and Memory buffers."]);
        setSchedulerState("Constructing");
      }
    }, 3600);

    if (!simulateBootError) {
      setTimeout(() => {
        setBootLog(prev => [...prev, "[SUCCESS] Sockets open. Channels aligned. Memory boundaries frozen.", "[INFO] Phase 5: Logical Time loop online."]);
        setSchedulerState("ResourcesAcquired");
      }, 4800);

      setTimeout(() => {
        setBootLog(prev => [...prev, "[SUCCESS] System Online. Ticking loop established at sequence 0."]);
        setSchedulerState("Online");
        setIsBooting(false);
        addLog("C10 Comp", "SUCCESS", "Kernel composed successfully. Stable baseline operational.");
      }, 6000);
    }
  };

  return (
