                  className="bg-zinc-800 text-zinc-300 border border-zinc-700 hover:bg-zinc-700 px-3 py-2 rounded disabled:opacity-50"
                  title="Force Single Logical Tick"
                >
                  <RefreshCw className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>

          {/* Core Panel */}
          <div className="flex-1 flex flex-col min-w-0 bg-zinc-900">
            <div className="flex-1 p-6 overflow-y-auto">

              {/* Tab: Overview */}
              {activeTab === "overview" && (
                <div className="space-y-6">
                  <div className="flex items-start justify-between gap-4">
                    <div>
                      <h2 className="text-lg font-bold text-cyan-400">System Kernel Blueprint</h2>
