                  </div>

                  {/* Active Composed Services */}
                  <div className="space-y-3">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-zinc-400">Active Service Composition</h3>
                    <div className="border border-zinc-800 rounded overflow-hidden">
