                    <h2 className="text-lg font-bold text-cyan-400">C10 Composition & Sorter Engine</h2>
                    <p className="text-xs text-zinc-400">Cycles verification, topological compilation, and automatic rollback on boot failure</p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Sorter / Simulator Controls */}
                    <div className="bg-zinc-950 p-5 rounded border border-zinc-800 space-y-4">
                      <span className="text-xs font-bold text-zinc-400 uppercase tracking-wider block">Phase Controller</span>

                      <div className="flex items-center justify-between p-3 bg-zinc-900 rounded border border-zinc-800">
                        <div className="space-y-0.5">
                          <label className="text-xs font-bold text-zinc-300">Force Boot Failure</label>
