          const delta = (Math.random() - 0.49) * 0.4;
          const newValue = Math.min(100, Math.max(50, +(metric.value + delta).toFixed(2)));
          const trendValue = +(newValue - metric.prevValue).toFixed(2);
          const trend: "up" | "down" | "stable" = trendValue > 0.05 ? "up" : trendValue < -0.05 ? "down" : "stable";
          const samples = metric.samples + 1;
          const confidence = Math.min(0.99, Math.max(0.85, +(metric.confidence + (Math.random() - 0.5) * 0.01).toFixed(3)));

          const now = new Date();
          const timestamp = now.toTimeString().split(" ")[0];

          if (metric.id === "KHI") {
            return metric; // calculated below
          }

          return {
            ...metric,
            value: newValue,
            trend,
            trendValue,
            samples,
            confidence,
            timestamp,
            details: {
              ...metric.details,
              variance: (0.001 + Math.random() * 0.01).toFixed(4)
            }
          };
        });

        // Compute KHI based on updated components
        const bc = next.find(m => m.id === "BC")?.value || 83.02;
        const rf = next.find(m => m.id === "RF")?.value || 97.40;
        const cis = next.find(m => m.id === "CIS")?.value || 88.00;

        const khiValue = +(bc * 0.4 + rf * 0.35 + cis * 0.25).toFixed(2);
        const khiMetric = next.find(m => m.id === "KHI")!;
        const khiTrendValue = +(khiValue - khiMetric.prevValue).toFixed(2);
        const khiTrend: "up" | "down" | "stable" = khiTrendValue > 0.02 ? "up" : khiTrendValue < -0.02 ? "down" : "stable";

        const now = new Date();
        const timestamp = now.toTimeString().split(" ")[0];

