          const updatedRF = [...h.RF, rf];
          const updatedCIS = [...h.CIS, cis];
          const updatedKHI = [...h.KHI, khiValue];

          if (updatedBC.length > 20) updatedBC.shift();
          if (updatedRF.length > 20) updatedRF.shift();
          if (updatedCIS.length > 20) updatedCIS.shift();
          if (updatedKHI.length > 20) updatedKHI.shift();

          return {
            BC: updatedBC,
            RF: updatedRF,
            CIS: updatedCIS,
            KHI: updatedKHI
          };
        });

        return next.map(m => {
