import React, { useState, useEffect, useMemo, useRef } from "react";
import { 
  Play, Pause, RefreshCw, Shield, Activity, HardDrive, List, AlertTriangle, 
  Settings, CheckCircle, Database, ChevronRight, Zap, Clock, Heart, Sliders, PlayCircle, Code, FileCode
} from "lucide-react";

// --- Rust Equivalent Types for common/ ---
type SystemState = "Boot" | "Idle" | "Active" | "Degraded" | "Recovery" | "Shutdown";

interface TransitionRequest {
  envelopeId: string;
  targetState: SystemState;
  reasonCode: string;
  originSubsystem: string;
  correlationId: string;
  signature: number[];
}

interface StateTraceRecord {
  traceId: string;
  transitionSequence: number;
  timestampNs: number;
  previousState: SystemState;
  nextState: SystemState;
  reasonCode: string;
  originSubsystem: string;
  correlationId: string;
  envelopeId: string;
  decisionId: string | null;
  executionDurationNs: number;
  result: "Accepted" | "Rejected";
  policyManifestVersion: string;
  kernelVersion: string;
}

export default function Component() {
  // --- Rust Kernel Emulation ---
  const [currentState, setCurrentState] = useState<SystemState>("Boot");
  const [transitionSequence, setTransitionSequence] = useState<number>(0);
  const [traceLogs, setTraceLogs] = useState<StateTraceRecord[]>([]);
  const [activeTab, setActiveTab] = useState<"simulator" | "rust">("simulator");
  const [showRustSuccess, setShowRustSuccess] = useState(true);

  // Health / Telemetry State
  const [latency, setLatency] = useState(4);
  const [errorRate, setErrorRate] = useState(0);
  const [saturation, setSaturation] = useState(12);

  // New Event Router counters as requested by Chief Architect
  const [eventRouterCounts, setEventRouterCounts] = useState({
    received: 0,
    validated: 0,
    rejected: 0,
    ledgerWritten: 0,
    subscribers: 6,
    queue: 0
  });

  // Dynamic calculation of SHS (Rule 006-010)
  // L: 0.25, E: 0.45, S: 0.30
  const systemHealthScore = useMemo(() => {
    const latPenalty = Math.min(100, (latency / 500) * 100) * 0.25;
    const errPenalty = Math.min(100, (errorRate / 10) * 100) * 0.45;
    const satPenalty = Math.min(100, (saturation / 100) * 100) * 0.30;
    return Math.max(0, Math.round(100 - (latPenalty + errPenalty + satPenalty)));
  }, [latency, errorRate, saturation]);

  // Audio Context for sound telemetry
  const audioCtxRef = useRef<AudioContext | null>(null);

  const playSystemBeep = (freq: number, dur: number, type: "sine" | "triangle" | "sawtooth" = "sine") => {
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === "suspended") {
        ctx.resume();
      }
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.04, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + dur);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + dur);
    } catch (e) {
      // Audio synthesis blocked or unsupported
    }
  };

  // Rule 001: Immutable Transition Matrix validation
  const validateTransition = (prev: SystemState, next: SystemState): boolean => {
    if (prev === "Shutdown") return false; // Terminal state (Rule 001)
    if (prev === "Boot") return ["Idle", "Degraded", "Shutdown"].includes(next);
    if (prev === "Idle") return ["Active", "Degraded", "Shutdown"].includes(next);
    if (prev === "Active") return ["Idle", "Degraded", "Recovery", "Shutdown"].includes(next);
    if (prev === "Degraded") return ["Active", "Recovery", "Shutdown"].includes(next);
    if (prev === "Recovery") return ["Active", "Degraded", "Shutdown"].includes(next);
    return false;
  };

  // Safe Transition Trigger (Rule 004 & Rule 005)
  const executeTransition = (target: SystemState, reason: string, subsystem: string) => {
    const start = performance.now();
    const isValid = validateTransition(currentState, target);
    const nextSeq = transitionSequence + 1;
    const duration = Math.round((performance.now() - start) * 1000000); // Nanoseconds conversion

    if (isValid) {
      setCurrentState(target);
      setTransitionSequence(nextSeq);
      playSystemBeep(target === "Shutdown" ? 180 : 330, 0.25, "triangle");

      setEventRouterCounts(prev => ({
        ...prev,
        received: prev.received + 1,
        validated: prev.validated + 1,
        ledgerWritten: prev.ledgerWritten + 1
      }));
    } else {
      playSystemBeep(120, 0.4, "sawtooth");
      setEventRouterCounts(prev => ({
        ...prev,
        received: prev.received + 1,
        rejected: prev.rejected + 1
      }));
    }

    const newTrace: StateTraceRecord = {
      traceId: `tx_u7_${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      transitionSequence: nextSeq,
      timestampNs: Date.now() * 1000000,
      previousState: currentState,
      nextState: target,
      reasonCode: reason,
      originSubsystem: subsystem,
      correlationId: `corr_${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      envelopeId: `env_${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      decisionId: `pe_dec_${Math.floor(Math.random() * 1000)}`,
      executionDurationNs: duration + 120, // Add artificial offset for measurement realism
      result: isValid ? "Accepted" : "Rejected",
      policyManifestVersion: "25.1-Baseline",
      kernelVersion: "0.1.0-Rust-ready"
    };

    setTraceLogs(prev => [newTrace, ...prev].slice(0, 30));
  };

  // Auto emulation loop
  useEffect(() => {
    const timer = setInterval(() => {
      // Randomly cycle metrics to simulate real-world conditions
      setLatency(prev => Math.max(2, Math.min(120, prev + (Math.random() > 0.5 ? 5 : -5))));
      setSaturation(prev => Math.max(0, Math.min(100, prev + (Math.random() > 0.6 ? 2 : -2))));

      if (Math.random() < 0.15 && currentState !== "Shutdown") {
        // Trigger policy transition recommendations
        if (systemHealthScore < 80 && currentState === "Idle") {
          executeTransition("Degraded", "ERR_HEALTH_DEGRADED", "HEALTH_MONITOR");
        } else if (currentState === "Boot") {
          executeTransition("Idle", "BOOT_SUCCESS", "BOOTLOADER");
        } else if (currentState === "Active" && Math.random() < 0.3) {
          executeTransition("Idle", "SYS_QUEUE_CLEARED", "SCHEDULER");
        } else if (currentState === "Idle" && Math.random() < 0.4) {
          executeTransition("Active", "HEAVY_TASK_QUEUE_INCOMING", "SCHEDULER");
        }
      }
    }, 1500);

    return () => clearInterval(timer);
  }, [currentState, transitionSequence, systemHealthScore]);

  return (
