import React, { useState, useEffect } from "react";
import { 
  ShieldAlert, 
  Scale, 
  Cpu, 
  Database, 
  MessageSquareText, 
  Activity, 
  Radio, 
  AlertTriangle, 
  Play, 
  RefreshCw, 
  Layers, 
  CheckCircle2, 
  XCircle, 
  Code, 
  Server, 
  Check, 
  Flame, 
  HelpCircle, 
  HardDrive, 
  Terminal, 
  Network,
  Lock,
  ArrowRight,
  Eye,
  History,
  Info
} from "lucide-react";
import { ElyzarethEventRouter } from "./engine";
import { SUBSYSTEMS } from "./subsystems";
import { EOSAEnvelope, SystemMetrics, LedgerRecord } from "./types";

// Map subsystem names to Lucide icons
const IconMap: Record<string, React.ComponentType<any>> = {
  "Flow Guard": ShieldAlert,
  "Rules of Engagement (ROE)": Scale,
  "Blueprint Engine": Cpu,
  "Memory Engine": Database,
  "Prompt Composer": MessageSquareText,
  "Audit": Activity,
  "Telemetry": Radio,
};

export default function Component() {
  const [activeTab, setActiveTab] = useState<"pipeline" | "ledger" | "contracts" | "topology">("pipeline");
  const [router] = useState(() => new ElyzarethEventRouter());
  const [metrics, setMetrics] = useState<SystemMetrics>(router.getMetrics());
  const [selectedSubsystem, setSelectedSubsystem] = useState(SUBSYSTEMS[0]);
  const [selectedTemplate, setSelectedTemplate] = useState(SUBSYSTEMS[0].templates[0]);

  // Custom Envelope Editor State
  const [customType, setCustomType] = useState(selectedTemplate.type);
  const [customPayload, setCustomPayload] = useState(JSON.stringify(selectedTemplate.payload, null, 2));
  const [customSignature, setCustomSignature] = useState("FG_sig_098x");

  // Chaos settings
  const [injectSchema, setInjectSchema] = useState(false);
  const [injectSequence, setInjectSequence] = useState(false);
  const [injectLedger, setInjectLedger] = useState(false);
  const [injectSubscriber, setInjectSubscriber] = useState(false);

  // Simulation run state
  const [isProcessing, setIsProcessing] = useState(false);
  const [pipelineStep, setPipelineStep] = useState<"idle" | "validation" | "sequencing" | "ledger" | "dispatch" | "complete">("idle");
  const [pipelineLogs, setPipelineLogs] = useState<{
    validation: { state: "idle" | "pending" | "success" | "error"; text: string };
    sequencing: { state: "idle" | "pending" | "success" | "error"; text: string };
    ledger: { state: "idle" | "pending" | "success" | "error"; text: string };
    dispatch: { state: "idle" | "pending" | "success" | "error"; text: string };
  }>({
    validation: { state: "idle", text: "" },
    sequencing: { state: "idle", text: "" },
    ledger: { state: "idle", text: "" },
    dispatch: { state: "idle", text: "" },
  });

  const [activeResult, setActiveResult] = useState<any>(null);
  const [kernelLog, setKernelLog] = useState<any[]>([]);

  // Sync templates on subsystem change
  useEffect(() => {
    const defaultTemplate = selectedSubsystem.templates[0];
    setSelectedTemplate(defaultTemplate);
    setCustomType(defaultTemplate.type);
    setCustomPayload(JSON.stringify(defaultTemplate.payload, null, 2));

    // Auto matching prefix signature helper
    const prefix = selectedSubsystem.name === "Flow Guard" ? "FG_" :
                   selectedSubsystem.name === "Rules of Engagement (ROE)" ? "ROE_" :
                   selectedSubsystem.name === "Blueprint Engine" ? "BP_" :
                   selectedSubsystem.name === "Memory Engine" ? "ME_" :
                   selectedSubsystem.name === "Prompt Composer" ? "PC_" :
                   selectedSubsystem.name === "Audit" ? "AD_" : "TL_";
    setCustomSignature(`${prefix}sig_${Math.floor(Math.random() * 10000)}`);
  }, [selectedSubsystem]);

  // Sync template presets
  const handleTemplateChange = (tmpl: any) => {
    setSelectedTemplate(tmpl);
    setCustomType(tmpl.type);
    setCustomPayload(JSON.stringify(tmpl.payload, null, 2));
  };

  // Run pipeline
  const handleSendEnvelope = async () => {
    if (isProcessing) return;
    setIsProcessing(true);
    setActiveResult(null);

    // Parse payload safely
    let parsedPayload = {};
    try {
      parsedPayload = JSON.parse(customPayload);
    } catch (e: any) {
      setPipelineLogs({
        validation: { state: "error", text: `SyntaxError in Payload JSON: ${e.message}` },
        sequencing: { state: "idle", text: "" },
        ledger: { state: "idle", text: "" },
        dispatch: { state: "idle", text: "" },
      });
      setPipelineStep("validation");
      setIsProcessing(false);
      return;
    }

    const envelope: EOSAEnvelope = {
      id: `env-${Math.floor(Math.random() * 1000000)}`,
      timestamp: new Date().toISOString(),
      source: selectedSubsystem.name,
      type: customType,
      payload: parsedPayload,
      signature: customSignature
    };

    setPipelineLogs({
      validation: { state: "idle", text: "" },
      sequencing: { state: "idle", text: "" },
      ledger: { state: "idle", text: "" },
      dispatch: { state: "idle", text: "" },
    });

    router.injectSchemaError = injectSchema;
    router.injectSequenceError = injectSequence;
    router.injectLedgerError = injectLedger;
    router.injectSubscriberError = injectSubscriber;

    setPipelineStep("validation");

    const result = await router.submitEvent(envelope, (step, details, status) => {
      setPipelineStep(step as any);
      setPipelineLogs(prev => ({
        ...prev,
        [step]: { state: status, text: details }
      }));
    });

    setPipelineStep("complete");
    setActiveResult(result);
    setMetrics(router.getMetrics());
    setKernelLog([...router.kernelEventsLog]);
    setIsProcessing(false);
  };

  // Replay execution flow
  const handleReplayRecord = async (record: LedgerRecord) => {
    if (isProcessing) return;
    setIsProcessing(true);

    setActiveTab("pipeline");
    setPipelineStep("dispatch");
    setPipelineLogs({
      validation: { state: "success", text: "[Replay Mode]: Skipped Schema Verification (Immutable verified block)" },
      sequencing: { state: "success", text: `[Replay Mode]: Sequence Pin Preserved (#${record.sequence})` },
      ledger: { state: "success", text: "[Replay Mode]: Ledger Write Bypassed (Append-only storage remains unchanged)" },
      dispatch: { state: "idle", text: "" }
    });

    router.injectSubscriberError = injectSubscriber;

    await router.replayEvent(record, (step, details, status) => {
      setPipelineLogs(prev => ({
        ...prev,
        dispatch: { state: status, text: details }
      }));
    });

    setPipelineStep("complete");
    setMetrics(router.getMetrics());
    setKernelLog([...router.kernelEventsLog]);
    setIsProcessing(false);
  };

  const handleReset = () => {
    router.resetLedger();
    setMetrics(router.getMetrics());
