export function validateEnvelope(envelope: EOSAEnvelope): { success: boolean; error?: string } {
  const subsystem = SUBSYSTEMS.find(s => s.name === envelope.source);
  if (!subsystem) {
    return { success: false, error: `Envelope ValidationError: Subsystem source '${envelope.source}' is unrecognized by kernel.` };
  }

  // Common Envelope Guarantees
  if (!envelope.id || envelope.id.trim() === "") {
    return { success: false, error: "EnvelopeValidationError: 'id' cannot be blank." };
  }
  if (!envelope.timestamp || isNaN(Date.parse(envelope.timestamp))) {
    return { success: false, error: "EnvelopeValidationError: 'timestamp' must be a valid ISO format date." };
  }
  if (!envelope.type || envelope.type.trim() === "") {
    return { success: false, error: "EnvelopeValidationError: Event 'type' cannot be blank." };
  }
  if (!envelope.payload) {
    return { success: false, error: "EnvelopeValidationError: Envelope 'payload' is required." };
  }

  // Source-Specific Rules
  const sig = envelope.signature || "";
  switch (envelope.source) {
    case "Flow Guard": {
      if (!sig.startsWith("FG_")) {
        return { success: false, error: "EnvelopeValidationError: Flow Guard signature must begin with 'FG_'." };
      }
      const { security_level, token_hash } = envelope.payload;
      if (typeof security_level !== "number" || security_level < 1 || security_level > 5) {
        return { success: false, error: "EnvelopeValidationError: Flow Guard payload rule violated: security_level must be an integer between 1 and 5." };
      }
      if (typeof token_hash !== "string" || token_hash.trim() === "") {
        return { success: false, error: "EnvelopeValidationError: Flow Guard payload rule violated: token_hash is required and cannot be empty." };
      }
      break;
    }
    case "Rules of Engagement (ROE)": {
      if (!sig.startsWith("ROE_")) {
        return { success: false, error: "EnvelopeValidationError: ROE signature must begin with 'ROE_'." };
      }
      const { alignment_axis, compliance_threshold } = envelope.payload;
      if (typeof alignment_axis !== "string" || alignment_axis.trim() === "") {
        return { success: false, error: "EnvelopeValidationError: ROE payload rule violated: alignment_axis must be a non-empty string." };
      }
      if (typeof compliance_threshold !== "number" || compliance_threshold < 0 || compliance_threshold > 1) {
        return { success: false, error: "EnvelopeValidationError: ROE payload rule violated: compliance_threshold must be between 0.0 and 1.0." };
      }
      break;
    }
    case "Blueprint Engine": {
      if (!sig.startsWith("BP_")) {
        return { success: false, error: "EnvelopeValidationError: Blueprint Engine signature must begin with 'BP_'." };
      }
      const { blueprint_id, active_nodes } = envelope.payload;
      if (typeof blueprint_id !== "string" || blueprint_id.trim() === "") {
        return { success: false, error: "EnvelopeValidationError: Blueprint Engine payload rule violated: blueprint_id must be a non-empty string." };
      }
      if (!Array.isArray(active_nodes) || active_nodes.length === 0) {
        return { success: false, error: "EnvelopeValidationError: Blueprint Engine payload rule violated: active_nodes must be an array with at least 1 element." };
      }
      break;
    }
    case "Memory Engine": {
      if (!sig.startsWith("ME_")) {
        return { success: false, error: "EnvelopeValidationError: Memory Engine signature must begin with 'ME_'." };
      }
      const { storage_type, keys_updated } = envelope.payload;
      if (storage_type !== "volatile" && storage_type !== "persistent") {
        return { success: false, error: "EnvelopeValidationError: Memory Engine payload rule violated: storage_type must be either 'volatile' or 'persistent'." };
      }
      if (typeof keys_updated !== "number" || keys_updated < 0) {
        return { success: false, error: "EnvelopeValidationError: Memory Engine payload rule violated: keys_updated must be a non-negative number." };
      }
      break;
    }
    case "Prompt Composer": {
      if (!sig.startsWith("PC_")) {
        return { success: false, error: "EnvelopeValidationError: Prompt Composer signature must begin with 'PC_'." };
      }
      const { prompt_token_count, context_window_id } = envelope.payload;
      if (typeof prompt_token_count !== "number" || prompt_token_count <= 0) {
        return { success: false, error: "EnvelopeValidationError: Prompt Composer payload rule violated: prompt_token_count must be a positive integer." };
      }
      if (typeof context_window_id !== "string" || context_window_id.trim() === "") {
        return { success: false, error: "EnvelopeValidationError: Prompt Composer payload rule violated: context_window_id must be a non-empty string." };
      }
      break;
    }
    case "Audit": {
      if (!sig.startsWith("AD_")) {
        return { success: false, error: "EnvelopeValidationError: Audit signature must begin with 'AD_'." };
      }
      const { audit_score, violations_detected } = envelope.payload;
      if (typeof audit_score !== "number" || audit_score < 0 || audit_score > 100) {
        return { success: false, error: "EnvelopeValidationError: Audit payload rule violated: audit_score must be between 0 and 100." };
      }
      if (typeof violations_detected !== "number" || !Number.isInteger(violations_detected)) {
        return { success: false, error: "EnvelopeValidationError: Audit payload rule violated: violations_detected must be an integer." };
      }
      break;
    }
    case "Telemetry": {
      if (!sig.startsWith("TL_")) {
        return { success: false, error: "EnvelopeValidationError: Telemetry signature must begin with 'TL_'." };
      }
      const { latency_ms, resources } = envelope.payload;
      if (typeof latency_ms !== "number" || latency_ms < 0) {
        return { success: false, error: "EnvelopeValidationError: Telemetry payload rule violated: latency_ms must be a positive number." };
      }
      if (!resources || typeof resources !== "object") {
        return { success: false, error: "EnvelopeValidationError: Telemetry payload rule violated: resources object is required." };
      }
      break;
    }
    default:
      return { success: false, error: "EnvelopeValidationError: Unrecognized subsystem source." };
  }

  return { success: true };
}

