// Helper to generate dummy hash for cryptographic lock demonstration
function generateHash(data: string): string {
  let hash = 0;
  for (let i = 0; i < data.length; i++) {
    const char = data.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return "0x" + Math.abs(hash).toString(16).padStart(8, "0");
}

export class ElyzarethEventRouter {
  private ledger: LedgerRecord[] = [];
  private currentSequence = 0;
  private subscribers: EventSubscriber[] = [];
  private metrics: SystemMetrics = {
    totalReceived: 0,
    totalCommitted: 0,
    totalFailed: 0,
    averageLatencyMs: 12.4,
    activeSequence: 0,
    integrityVerified: true,
    validationLatencyMs: 2.3,
    sequenceLatencyMs: 0.1,
    ledgerLatencyMs: 1.8,
    dispatchLatencyMs: 8.2
  };

  // Atomic sequence allocator queue
  private allocationLock = false;

  // Active Kernel Events log for telemetry tab
  public kernelEventsLog: { timestamp: string; eventType: KernelEventType; detail: string }[] = [];

  // Chaos parameters
  public injectSchemaError = false;
  public injectSequenceError = false;
  public injectLedgerError = false;
  public injectSubscriberError = false;

  constructor() {
    // Register initial default subscribers (all subsystems represented per layout recommendation)
    this.subscribers = [
      {
        id: "sub-flow-guard",
        name: "Flow Guard",
        interests: ["*"],
        onEvent: async (record) => {
          await new Promise(r => setTimeout(r, 6)); // 6ms processing
        },
        lastStatus: "idle",
        lastLatencyMs: 0
      },
      {
        id: "sub-blueprint",
        name: "Blueprint Engine",
        interests: ["blueprint_compiled"],
        onEvent: async (record) => {
          await new Promise(r => setTimeout(r, 8)); // 8ms processing
        },
        lastStatus: "idle",
        lastLatencyMs: 0
      },
      {
        id: "sub-memory",
        name: "Memory Engine",
        interests: ["snapshot_stored", "security_level_changed"],
        onEvent: async (record) => {
          await new Promise(r => setTimeout(r, 11)); // 11ms processing
        },
        lastStatus: "idle",
        lastLatencyMs: 0
      },
      {
        id: "sub-audit",
        name: "Audit Trail",
        interests: ["*"],
        onEvent: async (record) => {
          if (this.injectSubscriberError) throw new Error("Connection refused by socket daemon.");
          await new Promise(r => setTimeout(r, 2)); // 2ms processing
        },
        lastStatus: "idle",
        lastLatencyMs: 0
      },
      {
        id: "sub-telemetry",
        name: "Telemetry Collector",
        interests: ["heartbeat_ping", "compliance_checked"],
        onEvent: async (record) => {
          await new Promise(r => setTimeout(r, 4)); // 4ms processing
        },
        lastStatus: "idle",
        lastLatencyMs: 0
      }
    ];
  }

  public getLedger(): LedgerRecord[] {
    return this.ledger;
  }

  public getSubscribers(): EventSubscriber[] {
    return this.subscribers;
  }

  public getMetrics(): SystemMetrics {
    // Verify integrity across the entire chain on request
    let verified = true;
    for (let i = 0; i < this.ledger.length; i++) {
      const record = this.ledger[i];
      const prevHash = i === 0 ? "0x00000000" : this.ledger[i - 1].hash;
      const expectedHash = generateHash(record.sequence + JSON.stringify(record.envelope) + prevHash);
      if (record.previousHash !== prevHash || record.hash !== expectedHash) {
        verified = false;
        break;
      }
    }
    this.metrics.integrityVerified = verified;
    return this.metrics;
  }

  public toggleSubscriberFault(id: string) {
    const sub = this.subscribers.find(s => s.id === id);
    if (sub) {
      sub.isFaulty = !sub.isFaulty;
    }
  }

  // Kernel Event Logger Helper
  private emitKernelEvent(eventType: KernelEventType, detail: string) {
    this.kernelEventsLog.unshift({
      timestamp: new Date().toISOString(),
      eventType,
      detail
    });
  }

  // Live Replay Mode
  public async replayEvent(
    record: LedgerRecord,
    onStep: (step: string, details: string, state: "pending" | "success" | "error") => void
  ): Promise<boolean> {
    onStep("dispatch", `ReplayEngine routing historical Block #${record.sequence} directly to subscribers...`, "pending");
    await new Promise(r => setTimeout(r, 600));

    const dispatchTraces: string[] = [];
    let failures = 0;

    for (const sub of this.subscribers) {
      const matches = sub.interests.includes("*") || sub.interests.includes(record.envelope.type);
      if (matches) {
        const startSub = performance.now();
        try {
          if (sub.isFaulty) throw new Error(`Simulated fault on replay: ${sub.name}`);
          await sub.onEvent(record);
          sub.lastLatencyMs = Math.round(performance.now() - startSub);
          sub.lastStatus = "success";
          dispatchTraces.push(`✔ [Replay] ${sub.name}: Handled in ${sub.lastLatencyMs} ms`);
        } catch (e: any) {
          sub.lastLatencyMs = Math.round(performance.now() - startSub);
          sub.lastStatus = this.injectSubscriberError ? "timeout" : "failed";
          failures++;
          dispatchTraces.push(`❌ [Replay] ${sub.name} FAIL: ${e.message}`);
        }
      }
    }

    if (failures > 0) {
      onStep("dispatch", `Replay completed with non-blocking issues:\n${dispatchTraces.join("\n")}`, "success");
      this.emitKernelEvent(KernelEventType.DispatchFailed, `Replay event #${record.sequence} encountered subscriber issues.`);
      return false;
    } else {
      onStep("dispatch", `Replay broadcasted clean to all matching subscribers:\n${dispatchTraces.join("\n")}`, "success");
      this.emitKernelEvent(KernelEventType.DispatchCompleted, `Replay event #${record.sequence} successfully routed.`);
      return true;
    }
  }

  // Concurrency-safe Sequence Number Allocation
  private async allocateSequenceAtomic(): Promise<number> {
    while (this.allocationLock) {
      await new Promise(r => setTimeout(r, 10));
    }

    this.allocationLock = true;
    try {
      const nextSeq = this.currentSequence + 1;
      return nextSeq;
    } finally {
      this.allocationLock = false;
    }
  }

  // Live submitEvent flow
  public async submitEvent(
    envelope: EOSAEnvelope,
    onStep: (step: string, details: string, state: "pending" | "success" | "error") => void
  ): Promise<EventRouterResult> {
    const startTime = performance.now();
    this.metrics.totalReceived += 1;

    try {
      // Step 1: Schema Validation
      const valStart = performance.now();
      onStep("validation", "EnvelopeValidator checking schema constraints, signatures, and envelope structure...", "pending");

      if (this.injectSchemaError) {
        throw {
          type: "EnvelopeValidationError",
          message: "EnvelopeValidationError: Schema integrity check failed. Chaos injection enabled."
        };
      }

      const valRes = validateEnvelope(envelope);
      if (!valRes.success) {
        throw {
          type: "EnvelopeValidationError",
          message: valRes.error || "EnvelopeValidationError: Unknown validation anomaly."
        };
      }

      const validatedEnvelope: ValidatedEnvelope = {
        ...envelope,
        validatedAt: new Date().toISOString(),
        schemaVersion: "EOSA.Envelope.v1" // Enforce clear schema version metadata (Invariant Added)
      };

      await new Promise(r => setTimeout(r, 450));
      onStep("validation", "Schema successfully verified. Subsystem signature locked.", "success");
      this.emitKernelEvent(KernelEventType.EnvelopeAccepted, `Envelope Accepted: ID ${envelope.id} [${envelope.source}]`);
      const valEnd = performance.now();
      this.metrics.validationLatencyMs = Number((valEnd - valStart).toFixed(2));

      // Step 2: Assign Sequence (Atomic lock guarantees)
      const seqStart = performance.now();
      onStep("sequencing", "SequenceAllocator locking global ticket register to provision an atomic, gapless monotonic index...", "pending");

      if (this.injectSequenceError) {
        throw {
          type: "SequenceAllocationError",
          message: "SequenceAllocationError: Lock contention on monotonic allocator. Global tick sequence rejected."
        };
      }

      const sequence = await this.allocateSequenceAtomic();
      await new Promise(r => setTimeout(r, 400));
      onStep("sequencing", `Assigned globally unique sequence number: #${sequence} under atomic lock integrity.`, "success");
      const seqEnd = performance.now();
      this.metrics.sequenceLatencyMs = Number((seqEnd - seqStart).toFixed(2));

      // Step 3: Commit to Ledger
      const ledgerStart = performance.now();
      onStep("ledger", "LedgerWriter preparing append-only disk commit with cryptographic backward-linking key...", "pending");

      if (this.injectLedgerError) {
        throw {
          type: "LedgerWriteError",
          message: "LedgerWriteError: Storage boundary reached. Flash journal is write-locked."
        };
      }

      const prevRecord = this.ledger[this.ledger.length - 1];
      const previousHash = prevRecord ? prevRecord.hash : "0x00000000";
      const hash = generateHash(sequence + JSON.stringify(validatedEnvelope) + previousHash);

      // Store explicit version metadata in each record (Invariant Recommendation)
      const record: LedgerRecord = {
        sequence,
        envelope: validatedEnvelope,
        committedAt: new Date().toISOString(),
        previousHash,
        hash,
        kernelVersion: "24.1.0",
        ledgerFormat: "EOSA-L1"
      };

      // State update
      this.ledger.push(record);
      this.currentSequence = sequence;
      this.metrics.activeSequence = sequence;
      this.metrics.totalCommitted += 1;

      await new Promise(r => setTimeout(r, 450));
      onStep("ledger", `Successfully committed to ledger block. Hash signature generated: ${hash}`, "success");
      this.emitKernelEvent(KernelEventType.LedgerCommitted, `Ledger Commit Success: Block #${sequence} [Hash: ${hash.slice(0,8)}]`);
      const ledgerEnd = performance.now();
      this.metrics.ledgerLatencyMs = Number((ledgerEnd - ledgerStart).toFixed(2));

      // Step 4: Dispatch to Subscribers (uses COMMITTED RECORD as target - Refinement 2)
      const dispatchStart = performance.now();
      onStep("dispatch", "Dispatcher distributing immutable LedgerRecord transaction payload to active consumers...", "pending");

      const dispatchTraces: string[] = [];
      let subFailuresCount = 0;

      for (const sub of this.subscribers) {
        const matches = sub.interests.includes("*") || sub.interests.includes(validatedEnvelope.type);
        if (matches) {
          const startSub = performance.now();
          try {
            if (this.injectSubscriberError && sub.name === "Audit Trail") {
              // Simulate timeout
              await new Promise(r => setTimeout(r, 200));
              throw new Error("TCP Connection Timeout: Destination un-routable");
            }
            await sub.onEvent(record);
            sub.lastLatencyMs = Math.round(performance.now() - startSub);
            sub.lastStatus = "success";
            dispatchTraces.push(`✔ ${sub.name}: Received in ${sub.lastLatencyMs}ms`);
          } catch (e: any) {
            sub.lastLatencyMs = Math.round(performance.now() - startSub);
            sub.lastStatus = "timeout";
            subFailuresCount++;
            dispatchTraces.push(`❌ ${sub.name} FAIL: ${e.message}`);
          }
        } else {
          sub.lastStatus = "idle";
          sub.lastLatencyMs = 0;
        }
      }

      await new Promise(r => setTimeout(r, 500));

      if (subFailuresCount > 0) {
        onStep(
          "dispatch",
          `Dispatch completed with non-blocking exceptions:\n${dispatchTraces.join("\n")}\n\n*System preserved: Record remains committed to Ledger.*`,
          "success"
        );
        this.emitKernelEvent(KernelEventType.DispatchFailed, `Dispatch of event #${sequence} completed with ${subFailuresCount} warnings.`);
      } else {
        onStep("dispatch", `Successfully broadcasted committed record to matching subscribers:\n${dispatchTraces.join("\n")}`, "success");
        this.emitKernelEvent(KernelEventType.DispatchCompleted, `Dispatch of event #${sequence} completed cleanly.`);
      }

      const dispatchEnd = performance.now();
      this.metrics.dispatchLatencyMs = Number((dispatchEnd - dispatchStart).toFixed(2));

      // Latency calculation
      const duration = performance.now() - startTime;
      this.metrics.averageLatencyMs = Number(((this.metrics.averageLatencyMs * 4 + duration) / 5).toFixed(2));

      return {
        success: true,
        sequence,
        record
      };

    } catch (err: any) {
      this.metrics.totalFailed += 1;
      const errorType = err.type || "EnvelopeValidationError";
      const errorMsg = err.message || "Unknown hardware or consensus fault.";

      // Visual feedback of exception
      const errorStep = errorType === "EnvelopeValidationError" ? "validation" :
                        errorType === "SequenceAllocationError" ? "sequencing" : "ledger";

      onStep(errorStep, `CRITICAL: ${errorMsg}`, "error");

      return {
        success: false,
        error: {
          type: errorType,
          message: errorMsg,
          stack: `at ElyzarethEventRouter.submitEvent (kernel/router.ts:135:12)\nat dispatchPipeline (kernel/pipeline.ts:24:4)`
        }
      };
    }
  }

  public resetLedger() {
    this.ledger = [];
    this.currentSequence = 0;
    this.kernelEventsLog = [];
    this.subscribers.forEach(s => {
      s.lastStatus = "idle";
      s.lastLatencyMs = 0;
    });
    this.metrics = {
      totalReceived: 0,
      totalCommitted: 0,
      totalFailed: 0,
      averageLatencyMs: 12.4,
      activeSequence: 0,
      integrityVerified: true,
      validationLatencyMs: 2.3,
      sequenceLatencyMs: 0.1,
      ledgerLatencyMs: 1.8,
      dispatchLatencyMs: 8.2
    };
  }
}

