    const contract = selectedContract;
    const renderer = mockRenderers.find(r => r.id === selectedSimulatorRendererId) || mockRenderers[0];

    const addLog = (msg: string) => {
      setSimulationLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);
    };

    switch (simStepRef.current) {
      case 0:
        setSimState("QUEUED");
        setSimProgress(15);
        addLog(`ROE Job initialized. Scheduling execution thread...`);
        addLog(`State updated: QUEUED. Priority: NORMAL.`);
        simStepRef.current = 1;
        break;
      case 1:
        setSimState("ALLOCATING");
        setSimProgress(30);
        addLog(`Allocating target thread pool on renderer: ${renderer.name}`);
        addLog(`Verifying adapter compatibility signature (${renderer.adapterVersion})...`);
        simStepRef.current = 2;
        break;
      case 2:
        setSimState("RUNNING");
        setSimProgress(50);
        addLog(`State updated: RUNNING. Executing non-destructive prompt layers...`);

        // Check for failures injected during running state
        if (injectableFailure === "GPU_TIMEOUT") {
          addLog(`[ALERT] Injected Timeout Event: GPU process hung or timed out!`);
          simStepRef.current = 10; // Trigger timeout logic
        } else if (injectableFailure === "MEMORY_EXHAUSTION") {
          addLog(`[ALERT] Injected Memory Event: Physical buffer limit exceeded!`);
          simStepRef.current = 20; // Trigger memory limit escalation logic
        } else if (injectableFailure === "NETWORK_LOSS") {
          addLog(`[ALERT] Injected Connection Event: Heartbeat handshakes dropped!`);
          simStepRef.current = 30; // Trigger network drop failure
        } else {
          simStepRef.current = 3;
        }
        break;
      case 3:
        setSimState("VALIDATING");
        setSimProgress(80);
        addLog(`Handshake completed. Executing AST validations and integrity check...`);
        if (injectableFailure === "VALIDATION_FAILURE") {
          addLog(`[CRITICAL] Safety assertions failure: Contract integrity hash verification failed!`);
          simStepRef.current = 40; // Trigger abort rollback
        } else {
          simStepRef.current = 4;
        }
        break;
      case 4:
        setSimState("COMPLETED");
        setSimProgress(100);
        addLog(`[SUCCESS] Stems successfully generated and validated. Integrity check: 100% compliant.`);
        addLog(`Writing render outputs to secure blockchain blocks...`);

        // Save to immutable ledger
        const finalExec: RenderExecution = {
          executionId: "EXEC-00" + Math.floor(1000 + Math.random() * 9000),
          contractId: contract.id,
          promptPackageId: "PKG-" + Math.random().toString(36).substring(3, 7).toUpperCase(),
          rendererId: renderer.id,
          adapterVersion: renderer.adapterVersion,
          policyId: policy.policyId,
          state: "COMPLETED",
          startedAt: new Date(Date.now() - 10000).toISOString(),
          completedAt: new Date().toISOString(),
          outputHashes: ["sha256-stem-generated-" + Math.random().toString(36).substring(5)],
          verificationStatus: "PASS",
          cpuPeak: Number((20 + Math.random() * 30).toFixed(1)),
          memoryPeakMb: Math.floor(256 + Math.random() * 200),
          attempts: simAttemptsRef.current + 1,
          fidelityScore: Number((98 + Math.random() * 2).toFixed(2)),
          errorLog: ["Execution parsed cleanly."]
        };
        setLedger(prev => [finalExec, ...prev]);
        clearInterval(simTimerRef.current);
        simTimerRef.current = null;
        break;

      // Failures
      case 10: // GPU TIMEOUT RECOVERY
        setSimState("TIMEOUT");
        addLog(`Handling Timeout Policy: evaluating max retry limit (${policy.maxRetries})...`);
        if (simAttemptsRef.current < policy.maxRetries) {
          simAttemptsRef.current += 1;
          setSimState("RETRYING");
          addLog(`Retry triggered: attempt ${simAttemptsRef.current} of ${policy.maxRetries}. Delaying with backoff strategy [${policy.backoffStrategy}]...`);
          // Go back to running state on next tick
          simStepRef.current = 2;
        } else {
          addLog(`[CRITICAL] Retries exhausted. Aborting thread. Fallback sequence disabled.`);
          setSimState("FAILED");
          clearInterval(simTimerRef.current);
          simTimerRef.current = null;
        }
        break;

      case 20: // MEMORY EXHAUSTION RECOVERY
        setSimState("FAILED");
        addLog(`Memory pool exhausted. Max limits: 1024MB.`);
        if (policy.fallbackOrder.length > 0) {
          addLog(`Escalation Policy matched: routing render queue to secondary pool adapter...`);
          addLog(`New target dispatcher scheduled: ${policy.fallbackOrder[0]}`);
          // Simulated routing to alternate
          setSelectedSimulatorRendererId(policy.fallbackOrder[0]);
          setSimState("ROLLBACK");
          addLog(`State changed: ROLLBACK. Cleaning corrupted registers...`);
          simStepRef.current = 1; // Try allocating again
        } else {
          addLog(`[CRITICAL] No compatible recovery adapters registered. Thread dumped.`);
          clearInterval(simTimerRef.current);
          simTimerRef.current = null;
        }
        break;

      case 30: // NETWORK LOSS
        setSimState("FAILED");
        addLog(`Network interface offline. Thread aborted.`);
        clearInterval(simTimerRef.current);
        simTimerRef.current = null;
        break;

      case 40: // VALIDATION FAILURE
        setSimState("ROLLBACK");
        addLog(`Handling Integrity Failure: abortOnIntegrityFailure = ${policy.abortOnIntegrityFailure ? "TRUE" : "FALSE"}`);
        if (policy.abortOnIntegrityFailure) {
          addLog(`[CRITICAL] Immediate Abort triggered. Wiping local staging outputs.`);
          setSimState("FAILED");
          clearInterval(simTimerRef.current);
          simTimerRef.current = null;
        } else {
          addLog(`Bypassing hash mismatch warning. Continuing payload publishing...`);
          simStepRef.current = 4; // Continue to completion
        }
        break;
    }
  };

  const startROESimulation = () => {
    if (simTimerRef.current) clearInterval(simTimerRef.current);
    simStepRef.current = 0;
    simAttemptsRef.current = 0;
    setSimProgress(0);
    setSimulationLogs([]);
    setSimState("PENDING");

    setSimulationLogs([`[${new Date().toLocaleTimeString()}] [ROE-CORE] Handshaking dispatcher queue...`]);

    simTimerRef.current = setInterval(() => {
      runSimulatorStep();
    }, 1500);
  };

  const stopROESimulation = () => {
    if (simTimerRef.current) {
      clearInterval(simTimerRef.current);
      simTimerRef.current = null;
    }
    setSimState("CANCELLED");
    setSimulationLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] [ROE-STOP] User cancelled active execution.`]);
  };

