                            c.lyrics.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesState = filterState === "ALL" || c.currentState === filterState;
      const matchesCompiler = filterCompiler === "ALL" || c.compilerVersion === filterCompiler;
      const matchesTension = c.semanticPhysics.tension >= minTension;
      const matchesWitness = c.semanticPhysics.witnessStrength >= minWitness;
      return matchesSearch && matchesState && matchesCompiler && matchesTension && matchesWitness;
