  // Deterministic Semantic Physics Calculator
  const executeSPEAnalysis = () => {
    setIsAnalyzing(true);
    setTimeout(() => {
      const text = sandboxLyrics.toLowerCase();
      const lines = sandboxLyrics.split("\n").filter(l => l.trim() !== "");
      const words = text.replace(/[^\w\s]/g, "").split(/\s+/).filter(w => w.length > 0);

      const lineCount = lines.length || 1;
      const wordCount = words.length || 1;

      // 1. Tension: ratio of long lines to short lines
      const lineLengths = lines.map(l => l.length);
      const avgLineLength = lineLengths.reduce((a, b) => a + b, 0) / lineCount;
      const longLines = lineLengths.filter(len => len > avgLineLength).length;
      const tension = Math.min(0.95, Math.max(0.2, (longLines / lineCount) * 1.2));

      // 2. Resonance: Repetitive word frequencies indicating sound reflections
      const uniqueWords = new Set(words);
      const wordRepetitionRatio = 1 - (uniqueWords.size / wordCount);
      const resonance = Math.min(0.98, Math.max(0.15, wordRepetitionRatio * 2.5 + 0.3));

      // 3. Entropy: Variation in structural geometry (line length divergence)
      const variance = lineLengths.map(x => Math.pow(x - avgLineLength, 2)).reduce((a, b) => a + b, 0) / lineCount;
      const stdDev = Math.sqrt(variance);
      const entropy = Math.min(0.95, Math.max(0.1, stdDev / (avgLineLength || 1)));

      // 4. Witness Strength: Deterministic occurrence of verification/regulatory language
      const witnessAnchorWords = ["witness", "observe", "evidence", "proof", "sovereign", "rule", "physics", "compile", "validate", "deterministic", "freeze", "static"];
      const witnessCount = words.filter(w => witnessAnchorWords.includes(w)).length;
      const witnessStrength = Math.min(1.0, Math.max(0.25, (witnessCount / wordCount) * 12 + 0.3));

      // 5. Scene Stability: structural symmetry (rhyme-zone line parity)
      const sceneStability = Math.min(0.95, Math.max(0.3, lineCount % 2 === 0 ? 0.9 : 0.65));

      // 6. Imagery Compression: Lexical density (ratio of words length > 5 characters)
      const longWords = words.filter(w => w.length > 5).length;
      const imageryCompression = Math.min(0.95, Math.max(0.2, longWords / wordCount * 1.8));

      // 7. Emotional Momentum: Punctuation density and stanza transitions
      const exclamationCount = (sandboxLyrics.match(/!/g) || []).length;
      const chorusPresence = text.includes("[chorus]") ? 0.3 : 0;
      const emotionalMomentum = Math.min(0.95, Math.max(0.1, (exclamationCount * 0.15) + chorusPresence + 0.35));

      // 8. Narrative Density: Unique metadata elements per line
      const narrativeDensity = Math.min(0.98, Math.max(0.25, uniqueWords.size / (wordCount || 1) * 1.1));

      setSandboxAnalysis({
        tension,
        resonance,
        entropy,
        witnessStrength,
        sceneStability,
        imageryCompression,
        emotionalMomentum,
        narrativeDensity
      });
      setIsAnalyzing(false);
    }, 1000);
  };

  // DPSE Deterministic Prompt Synthesis Compiler Backend
