        technicalHints = "Aspect Ratio 9:16, zero handheld jitter, absolute locked-camera mount, stationary depth of field, rendering pass optimized for maximum state duration.";
      } else {
        ruleLog.push(`[RULE-COMPPLY] Scene Stability (${physics.sceneStability.toFixed(2)}) <= 0.80: Standard pan limits.`);
        technicalHints = "Aspect Ratio 9:16, smooth controlled camera pan, low frequency spatial drift, 30fps baseline compiler targets.";
      }

      const exclusions = "No automated AI hallucinations, no synthesized artist names, no generic thematic descriptors, zero lyric adjustments, no unvalidated AST structures.";

      // Truncate based on Renderer maxPromptLength limits
      const fullPromptLen = scene.length + atmosphere.length + emotionalArc.length + physicalAnchors.length;
      if (fullPromptLen > renderer.maxPromptLength) {
        ruleLog.push(`[DPSE-WARN] Synthesized prompt length (${fullPromptLen} chars) exceeds target limit of ${renderer.maxPromptLength} for renderer. Initiating lossless architectural compression...`);
        // Simple non-destructive truncation as simulation
        scene = scene.substring(0, Math.floor(renderer.maxPromptLength * 0.3)) + "... [Compressed]";
        atmosphere = atmosphere.substring(0, Math.floor(renderer.maxPromptLength * 0.3)) + "... [Compressed]";
      } else {
        ruleLog.push(`[DPSE-SUCCESS] Structured payload fits target bounds (size: ${fullPromptLen}/${renderer.maxPromptLength} chars)`);
      }

      const packageId = "PKG-" + Math.random().toString(36).substring(3, 11).toUpperCase();
      const synthesisHash = "sha256-synthesis-" + Math.random().toString(36).substring(7);

      setSynthesizedPackage({
