      logs.push(`[INFO] Initiating manifest verify sequence...`);
      logs.push(`[INFO] Contract: ${contract.id} (${contract.title})`);
      logs.push(`[INFO] Renderer Platform: ${renderer.name} (${renderer.version})`);

      // Step 1: Check status of provider
      if (renderer.status === "OFFLINE") {
