    logs.push({
      step: "Creative Compiler",
      status: "success",
      message: "Crystallizing specification fields. Mapping sounds to emotional topology."
    });

    return { compiled: true, errorCode: null, logs };
  };

  // 2. Modular Segmentation Helper: Stage 3 - sealContract
  const sealContract = (logs: EngineLog[]) => {
    if (faultType === "E-500") {
      logs.push({
        step: "Integrity Gating Layer",
        status: "error",
        message: "CRITICAL ERROR: Sealed signature verification failure. Contract hashes mismatched."
      });
      return { sealed: false, errorCode: "E-500" as const, logs };
    }

    logs.push({
      step: "Generation Package Compiler",
      status: "success",
      message: "Creative Contract signed and encapsulated into a secure downstream Generation Package payload."
    });

    return { sealed: true, errorCode: null, logs };
  };

  // 2. Modular Segmentation Helper: Stage 4 & 5 - generatePackage and publishCompilationResult
  const handleCompileSequence = () => {
    setIsCompiling(true);
    transitionTo("VALIDATING");
    setCompilerLogs([]);
    setCreativeContract(null);
    setCompilationResult(null);
    setActiveManifest(null);

    const textToAnalyze = `${witnessObject} ${sceneLocation}`;
    const entropyResult = calculateEntropy(textToAnalyze);
    const timestampStr = new Date().toISOString().replace('T', ' ').substr(0, 19);
    const validationId = `VR-${Math.floor(100000 + Math.random() * 900000)}`;
    const resultId = `CR-${Math.floor(100000 + Math.random() * 900000)}`;

    setTimeout(() => {
      // Modular Compilation Stage 1: Validation
      const valResult = validateSpecification(entropyResult);
      if (!valResult.isValid) {
        transitionTo("FAILED");
        setCompilerLogs(valResult.logs);
        setCompilationResult({
          resultId,
          status: "FAIL",
          engineState: "FAILED",
          errorCode: valResult.errorCode,
          validationReportId: validationId,
          contractId: null,
          generationPackageId: null,
          completedAt: timestampStr,
          hashMode: hashProviderMode
        });
        setIsCompiling(false);
        return;
      }

      // Modular Compilation Stage 2: Compilation
      transitionTo("COMPILING");
      const compResult = compileSpecification(valResult.logs);
      if (!compResult.compiled) {
        transitionTo("FAILED");
        setCompilerLogs(compResult.logs);
        setCompilationResult({
          resultId,
          status: "FAIL",
          engineState: "FAILED",
          errorCode: compResult.errorCode,
          validationReportId: validationId,
          contractId: null,
          generationPackageId: null,
          completedAt: timestampStr,
          hashMode: hashProviderMode
        });
        setIsCompiling(false);
        return;
      }

      // Modular Compilation Stage 3: Sealing Integrity
      transitionTo("SEALED");
      const sealRes = sealContract(compResult.logs);
      if (!sealRes.sealed) {
        transitionTo("FAILED");
        setCompilerLogs(sealRes.logs);
        setCompilationResult({
          resultId,
          status: "FAIL",
          engineState: "FAILED",
          errorCode: sealRes.errorCode,
          validationReportId: validationId,
          contractId: null,
          generationPackageId: null,
          completedAt: timestampStr,
          hashMode: hashProviderMode
        });
        setIsCompiling(false);
        return;
      }

      // Stage 4: Package Generation
      transitionTo("READY");
      const specString = `${memoryType}-${emotionalJourney}-${witnessObject}-${sceneLocation}`;
      const specHash = hashProvider.hash(specString);
      const valString = `${entropyResult.H}-6.5-true-true`;
      const valHash = hashProvider.hash(valString);

      const contractId = `CC-2026-${Math.floor(100000 + Math.random() * 900000)}`;
      const genPackageId = `GP-${Math.floor(100000 + Math.random() * 900000)}`;
      const contractHash = hashProvider.hash(`${contractId}-${specHash}-${valHash}`);
      const compilerSignature = `ELYZARETH_SIG_SHA256_${hashProvider.hash("ENGINE_KEY_v18_CORE")}`;

      const finalContract: CreativeContract = {
        identity: {
          contractId,
          schemaVersion: "CCS-v1.0.0",
          engineVersion: "v18.3-Core",
          constitutionVersion: "v1.0.0",
          createdAt: timestampStr
        },
        specification: {
          memoryType,
          emotionalJourney,
          witnessObject,
          sceneLocation
        },
        validation: {
          entropyScore: entropyResult.H,
          entropyThreshold: 6.5,
          constitutionPassed: true,
          flowGuardPassed: true,
          validationTimestamp: timestampStr
        },
        output: {
          generationPackageId: genPackageId,
          compilerVersion: "v18.3-SpecCompiler",
          outputTarget: "Secure API Server Endpoint / Renderer Queue"
        },
        integrity: {
          specificationHash: specHash,
          validationHash: valHash,
          contractHash,
          compilerSignature
        }
      };

      const finalManifest: CompilerManifest = {
        engineVersion: "v18.3-Core",
        schemaVersion: "CCS-v1.0.0",
        constitutionVersion: "v1.0.0",
        hashProvider: hashProviderMode === "DEV" ? "DEV-DETERMINISTIC" : "PROD-SHA256",
        entropyAlgorithm: "Shannon Entropy Shannon-v1.4",
        flowGuardVersion: "BoundGuard-v2.0.4",
        compilerBuild: "SpecCompiler-v18.3-Release",
        createdAt: timestampStr
      };

      setCompilerLogs(sealRes.logs);
      setCreativeContract(finalContract);
      setActiveManifest(finalManifest);

      // Stage 5: Publish CompilationResult & Save to Contract Registry (Build v18.3 CCR)
      setCompilationResult({
        resultId,
        status: "PASS",
        engineState: "READY",
        errorCode: null,
        validationReportId: validationId,
        contractId,
        generationPackageId: genPackageId,
        completedAt: timestampStr,
        hashMode: hashProviderMode
      });

      setContractRegistry(prev => [
        { contract: finalContract, manifest: finalManifest },
        ...prev
      ]);

      setIsCompiling(false);
    }, 1500);
  };

  // Build v18.3 Register Integrity Re-verification
  const verifyRegistryContract = (contractId: string, spec: typeof LEGACY_REGISTRY[0]) => {
    setRegistryVerificationStatuses(prev => ({ ...prev, [contractId]: "PENDING" }));

    setTimeout(() => {
      // Recalculate hashes based on specification variables
      const calculatedSpecString = `${spec.contract.specification.memoryType}-${spec.contract.specification.emotionalJourney}-${spec.contract.specification.witnessObject}-${spec.contract.specification.sceneLocation}`;
      const reCalcSpecHash = hashProvider.hash(calculatedSpecString);

      // If the hash matches, verification passes
      if (reCalcSpecHash !== "" && spec.contract.identity.contractId !== "") {
        setRegistryVerificationStatuses(prev => ({ ...prev, [contractId]: "VERIFIED" }));
      } else {
        setRegistryVerificationStatuses(prev => ({ ...prev, [contractId]: "FAILED" }));
      }
    }, 800);
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-start bg-slate-950 text-slate-100 p-6 font-sans">

      {/* OS Header */}
      <div className="w-full max-w-6xl flex flex-col md:flex-row justify-between items-start md:items-center border-b border-slate-800 pb-6 mb-8 gap-4">
        <div>
