              BUILD v18.3.0
            </span>
            <span className="text-xs text-slate-500 font-mono font-bold">CONTRACT REGISTRY & PORTABILITY BRANCH</span>
          </div>
          <h1 className="text-2xl md:text-3xl font-extrabold tracking-tight text-white flex items-center gap-3">
            <Activity className="text-emerald-400 w-8 h-8" />
            ELYZARETH OS
          </h1>
          <p className="text-sm text-slate-400 mt-1 max-w-2xl font-mono">
            Validation precedes compilation. Compilation precedes rendering. Rendering precedes publishing.
          </p>
        </div>

        {/* Tab Controls */}
        <div className="flex flex-wrap gap-1 bg-slate-900/60 p-1 border border-slate-800 rounded-lg">
