            onClick={() => setActiveTab("deck")}
            className={`px-4 py-2 text-xs font-semibold rounded transition-all duration-200 flex items-center gap-2 ${
              activeTab === "deck" ? "bg-emerald-500 text-slate-950 shadow-md" : "text-slate-400 hover:text-slate-200"
