  const handleRunPreset = (preset: typeof PRESETS[0]) => {
    setPromptInput(preset.prompt);
    addConsoleLog(`Loaded preset: "${preset.name}"`);
  };

  // Dry run compile function returning trace output strictly for validation suite run
  const compileDryRun = (inputStr: string) => {
    const cleaned = inputStr
      .toLowerCase()
      .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "")
      .replace(/\s{2,}/g, " ")
      .trim();

    // 1. Intent check
    let primaryEmotion = "Quiet Comfort";
    if (cleaned.includes("porch") || cleaned.includes("tea") || cleaned.includes("aging")) {
      primaryEmotion = "Familial Nostalgia";
    } else if (cleaned.includes("distance") || cleaned.includes("voice") || cleaned.includes("reunion")) {
      primaryEmotion = "Hopeful Anticipation";
    } else if (cleaned.includes("revenge") || cleaned.includes("strike")) {
      primaryEmotion = "Retribution";
    } else if (cleaned.includes("bullet") || cleaned.includes("highway") || cleaned.includes("chase")) {
      primaryEmotion = "Urgency / Panic";
    } else if (cleaned.includes("orbit") || cleaned.includes("space") || cleaned.includes("cosmic")) {
      primaryEmotion = "Cosmic Nihilism";
    } else if (cleaned.includes("dark night") || cleaned.includes("dark")) {
      primaryEmotion = "Ambiguous";
    }

    // 2. Constitution Law check
    if (primaryEmotion === "Cosmic Nihilism") {
      return { status: "Deterministic Stop", stage: "Constitution Layer", reason: "Law 1 Violation: Non-human cosmic drift" };
    }

    if (primaryEmotion === "Ambiguous") {
      return { status: "Review Intent", stage: "Intent Parser", reason: "Ambiguous emotional spectrum requires verification" };
    }

    // 3. Token check
    const triggeredTokens = forbiddenTokens.filter(t => cleaned.includes(t));
    if (triggeredTokens.length > 0) {
      return { status: "Deterministic Stop", stage: "Lexicon Gate", reason: `Token Filter matched: [${triggeredTokens.join(", ")}]` };
    }

    // 4. Concept filter check
    const triggeredConcepts = forbiddenConcepts.filter(c => {
      if (c === "violence" && (cleaned.includes("bullet") || cleaned.includes("shoot"))) return true;
      if (c === "high-speed transit" && (cleaned.includes("highway") || cleaned.includes("chase"))) return true;
      if (c === "supernatural" && (cleaned.includes("demon") || cleaned.includes("shadow"))) return true;
      if (c === "retribution" && (cleaned.includes("revenge") || cleaned.includes("strike"))) return true;
      return false;
    });

    if (triggeredConcepts.length > 0) {
      return { status: "Deterministic Stop", stage: "Lexicon Gate", reason: `Concept filter mapped: [${triggeredConcepts.join(", ")}]` };
    }

    // 5. Conflict resolver check
    const hasConflict = cleaned.includes("revenge") || cleaned.includes("vengeance");
    if (hasConflict) {
      return { status: "Deterministic Stop", stage: "Conflict Resolver", reason: "Love paradigm intersects Retribution" };
    }

    return { status: "Authorized", stage: "Blueprint Crystallizer", reason: "All structural & policy constraint gates cleared successfully" };
  };

  // Run the batch test suite
  const runValidationSuite = async () => {
    setIsRunningSuite(true);
    setSuiteResults([]);
    addConsoleLog("Initializing Validation Pack v1.0 Test Run...");

    for (const test of VALIDATION_SUITE) {
      addConsoleLog(`Executing ${test.id}: "${test.name}"...`);
      await sleep(150);
      const res = compileDryRun(test.prompt);
      const isPassed = res.status === test.expected;

      setSuiteResults(prev => [...prev, {
        ...test,
        actual: res.status,
        stage: res.stage,
        reason: res.reason,
        passed: isPassed
      }]);
