      setCompilerStats({
        tokensFiltered: triggeredTokens.length,
        conceptsBlocked: triggeredConcepts.length,
        vocabularyCandidates: 0,
        constraintsChecked: 3,
        executionTime: (performance.now() - startTime).toFixed(1),
        blueprintSize: "0 bytes"
      });
      setIsCompiling(false);
      return;
    }
    setCompletedStages(prev => [...prev, "lexicon"]);

    // Stage 5: Conflict Resolver
    setActiveStage("resolver");
    addConsoleLog("Running conflict detection on intersecting emotional frameworks...");
    await sleep(600);

    const hasConflict = cleaned.includes("revenge") || cleaned.includes("vengeance");
    if (hasConflict) {
      setFailedStage("resolver");
      setConflictReport({
        status: "DETERMINISTIC_STOP",
        conflict_detector: {
          approved_elements: ["Love", "Peace"],
          prohibited_elements: ["Revenge"],
          conflict_identified: true,
          resolution_recommendation: "Remove 'revenge' or replace with 'forgiveness'."
        },
