import React, { useState, useEffect } from "react";
import { 
  Shield, 
  Terminal, 
  Play, 
  CheckCircle2, 
  XCircle, 
  AlertTriangle, 
  Cpu, 
  Sliders, 
  Code, 
  Sparkles, 
  RotateCcw,
  BookOpen,
  FileText,
  Lock,
  Layers,
  ChevronDown,
  ChevronRight,
  BarChart4
} from "lucide-react";

// Preset test scenarios
const PRESETS = [
  {
    name: "Peaceful Love Song",
    prompt: "Write a peaceful love song about absolute stillness and safety...!!!",
    type: "valid"
  },
  {
    name: "Nostalgic Family Memory",
    prompt: "Write a song about old porch steps, warm tea, and aging together.",
    type: "valid"
  },
  {
    name: "Hopeful Reunion",
    prompt: "A quiet song about distance closing, hearing their voice again.",
    type: "valid"
  },
  {
    name: "Conflict: Peace & Revenge",
    prompt: "Write a peaceful love song but with deep revenge and striking back.",
    type: "conflict"
  },
  {
    name: "Violation: Bullet & Highway",
    prompt: "A song about a fast highway chase with a silver bullet.",
    type: "violation"
  },
  {
    name: "Violation: Space Orbit & Shadow",
    prompt: "A cosmic melody of entering high orbit and searching the dark shadows.",
    type: "violation"
  }
];

// Pipeline Stages for visual indicator
const STAGES = [
  { id: "normalization", label: "Normalization Layer", phase: "Pre-Process" },
  { id: "parser", label: "Intent Parser", phase: "Parse" },
  { id: "constitution", label: "Constitution Layer (v1.0)", phase: "Constitutional" },
  { id: "lexicon", label: "Lexicon & Concept Gate", phase: "Gate" },
  { id: "resolver", label: "Conflict Resolver", phase: "Resolution" },
  { id: "policy", label: "Policy Layer (v3.2)", phase: "Policy" },
  { id: "planner", label: "Emotional & Symbol Planner", phase: "Planning" },
  { id: "style", label: "Style Compiler", phase: "Styling" },
  { id: "crystallizer", label: "Blueprint Crystallizer", phase: "Crystallization" },
  { id: "generator", label: "Lyric Generator (v1.5)", phase: "Generation" }
];

export default function Component() {
  const [promptInput, setPromptInput] = useState(PRESETS[0].prompt);
  const [isCompiling, setIsCompiling] = useState(false);
  const [activeStage, setActiveStage] = useState<string | null>(null);
  const [completedStages, setCompletedStages] = useState<string[]>([]);
  const [failedStage, setFailedStage] = useState<string | null>(null);

  // Collapsible Blueprint sections state
  const [openBlueprintSections, setOpenBlueprintSections] = useState({
    meta: true,
    journey: true,
    symbol: true,
    style: true,
    structure: false,
    vocabulary: false,
    forbidden: false
  });

  const toggleBlueprintSection = (section: string) => {
    setOpenBlueprintSections(prev => ({
      ...prev,
      [section]: !prev[section as keyof typeof prev]
    }));
  };

  // Custom Policy Settings for user interaction
  const [policyVersion, setPolicyVersion] = useState("3.2");
  const [forbiddenTokens, setForbiddenTokens] = useState<string[]>([
    "highway", "bullet", "demon", "shadow", "orbit", "codeine", "police", "revenge"
  ]);
  const [forbiddenConcepts, setForbiddenConcepts] = useState<string[]>([
    "violence", "high-speed transit", "supernatural", "nihilism", "cosmic travel", "retribution"
  ]);

  // Simulation outputs
  const [validationReport, setValidationReport] = useState<any>(null);
  const [conflictReport, setConflictReport] = useState<any>(null);
  const [crystallizedBlueprint, setCrystallizedBlueprint] = useState<any>(null);
  const [constraintReport, setConstraintReport] = useState<any>(null);
  const [generatedLyrics, setGeneratedLyrics] = useState<string | null>(null);
  const [normalizedPrompt, setNormalizedPrompt] = useState<string>("");
  const [compilerStats, setCompilerStats] = useState<any>(null);
  const [systemConsole, setSystemConsole] = useState<string[]>(["Elyzareth OS v2.0 initialized. Awaiting compile signal."]);

  const addConsoleLog = (msg: string) => {
    setSystemConsole(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);
  };

  const handleRunPreset = (preset: typeof PRESETS[0]) => {
    setPromptInput(preset.prompt);
    addConsoleLog(`Loaded preset: "${preset.name}"`);
  };

  const executeCompilation = async () => {
    setIsCompiling(true);
    setActiveStage(null);
    setCompletedStages([]);
    setFailedStage(null);
    setValidationReport(null);
    setConflictReport(null);
    setCrystallizedBlueprint(null);
    setConstraintReport(null);
    setGeneratedLyrics(null);
    setNormalizedPrompt("");
    setCompilerStats(null);
    setSystemConsole([]);

    addConsoleLog("Starting compilation sequence...");
    const startTime = performance.now();

    // Stage 1: Normalization Layer
    setActiveStage("normalization");
    addConsoleLog("Entering Normalization Layer...");
    await sleep(500);

    // Normalize source string: clean punctuation, strip extra spaces, uniform casing
    const cleaned = promptInput
      .toLowerCase()
      .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "")
      .replace(/\s{2,}/g, " ")
      .trim();

    setNormalizedPrompt(cleaned);
    addConsoleLog(`Source code normalized: "${cleaned}"`);
    setCompletedStages(prev => [...prev, "normalization"]);

    // Stage 2: Intent Parser
    setActiveStage("parser");
    addConsoleLog("Parsing user input intent and emotional resonance vectors...");
    await sleep(600);
    setCompletedStages(prev => [...prev, "parser"]);

    // Determine Intent Parameters
    let primaryEmotion = "Quiet Comfort";
    let secondaryEmotion = "Warmth";
    let relationship = "Human Connection";
    let journeyMap = "Stillness -> Grounding";

    if (cleaned.includes("porch") || cleaned.includes("tea") || cleaned.includes("aging")) {
      primaryEmotion = "Familial Nostalgia";
      secondaryEmotion = "Nostalgic Comfort";
      relationship = "Parent / Child or Long Partnership";
      journeyMap = "Memory -> Healing";
    } else if (cleaned.includes("distance") || cleaned.includes("voice") || cleaned.includes("reunion")) {
      primaryEmotion = "Hopeful Anticipation";
      secondaryEmotion = "Relief";
      relationship = "Deep Attachment";
      journeyMap = "Distance -> Reunion";
    } else if (cleaned.includes("revenge") || cleaned.includes("strike")) {
      primaryEmotion = "Retribution";
      secondaryEmotion = "Bitterness";
      relationship = "Adversarial";
      journeyMap = "Conflict -> Destruction";
    } else if (cleaned.includes("bullet") || cleaned.includes("highway") || cleaned.includes("chase")) {
      primaryEmotion = "Urgency / Panic";
      secondaryEmotion = "Threat";
      relationship = "Unspecified";
      journeyMap = "Flight -> Impact";
    } else if (cleaned.includes("orbit") || cleaned.includes("space") || cleaned.includes("cosmic")) {
      primaryEmotion = "Cosmic Nihilism";
      secondaryEmotion = "Isolation";
      relationship = "None (Void)";
      journeyMap = "Ascent -> Emptiness";
    }

    const intentReport = {
      system_version: { compiler: "2.0.0", constitution: "1.0", policy: policyVersion },
      intent_classification: {
        primary_emotion: primaryEmotion,
        secondary_emotion: secondaryEmotion,
        relationship: relationship,
        journey_map: journeyMap,
        confidence_score: 0.96
      }
    };
    setValidationReport(intentReport);
    addConsoleLog(`Parsed primary emotional vector: ${primaryEmotion}`);

    // Stage 3: Constitution Layer
    setActiveStage("constitution");
    addConsoleLog("Evaluating Constitution Layer (v1.0 Immutable Constraints)...");
    await sleep(700);

    // Law 1 check (Human Emotional Journey Only)
    const isHumanJourney = primaryEmotion !== "Cosmic Nihilism";
    if (!isHumanJourney) {
      setFailedStage("constitution");
      addConsoleLog("DETERMINISTIC STOP: Constitution Law 1 Violation detected (Non-human/Cosmic Nihilism abstraction).");
      setCompilerStats({
        tokensFiltered: promptInput.split(" ").length,
        conceptsRejected: 1,
        vocabularyCandidates: 0,
        constraintsChecked: 1,
        executionTime: (performance.now() - startTime).toFixed(1),
        blueprintSize: "0 bytes"
      });
      setIsCompiling(false);
      return;
    }
    setCompletedStages(prev => [...prev, "constitution"]);

    // Stage 4: Lexicon & Concept Gate
    setActiveStage("lexicon");
    addConsoleLog("Filtering lexicon space and semantic concepts...");
    await sleep(800);

    // Token Filter Check
    const triggeredTokens = forbiddenTokens.filter(t => cleaned.includes(t));
    const triggeredConcepts = forbiddenConcepts.filter(c => {
      if (c === "violence" && (cleaned.includes("bullet") || cleaned.includes("shoot") || cleaned.includes("kill"))) return true;
      if (c === "high-speed transit" && (cleaned.includes("highway") || cleaned.includes("chase") || cleaned.includes("fast"))) return true;
      if (c === "supernatural" && (cleaned.includes("demon") || cleaned.includes("ghost") || cleaned.includes("shadow"))) return true;
