// -------------------------------------------------------------
// Pure Physics Verification Suite Component (SPL v1.1 Enabled)
// -------------------------------------------------------------
interface VerificationProps {
  currentState: EngineState;
  gain: number;
  thermalLoad: number;
  activeLaws: string[];
}

function LocalVerificationSuite({ currentState, gain, thermalLoad, activeLaws }: VerificationProps) {
  const [activeTab, setActiveTab] = useState<"entropy" | "gain" | "surface">("surface");

  // Run Experiment 1: Entropy Sweep (M_g is fixed, S sweeps 0 to 1)
  const getEntropySweepData = () => {
    const data = [];
    for (let S = 0.0; S <= 1.0; S += 0.05) {
      const simulatedState = processPhysicsCycle(currentState, {
        gain: gain,
        thermal_load: S,
        laws: activeLaws,
      });
      data.push({
        S: parseFloat(S.toFixed(2)),
        pressure: simulatedState.engine.container.pressure,
        divergence: simulatedState.engine.observer.flow_guard.divergence_index,
        coherence: simulatedState.engine.observer.flow_guard.coherence,
        recovery: simulatedState.engine.recovery_manager.active_level,
      });
    }
    return data;
  };

  // Run Experiment 2: Gain Sweep (S is fixed, M_g sweeps 0.1 to 1.0)
  const getGainSweepData = () => {
    const data = [];
    for (let Mg = 0.1; Mg <= 1.0; Mg += 0.05) {
      const simulatedState = processPhysicsCycle(currentState, {
        gain: Mg,
        thermal_load: thermalLoad,
        laws: activeLaws,
      });

      // Calculate average law resonance
      const resonances = Object.values(simulatedState.engine.observer.flow_guard.law_resonance);
      const avgRes = resonances.length > 0 ? resonances.reduce((a, b) => a + b, 0) / resonances.length : 1.0;

      data.push({
        Mg: parseFloat(Mg.toFixed(2)),
        pressure: simulatedState.engine.container.pressure,
        coherence: simulatedState.engine.observer.flow_guard.coherence,
        resonance: parseFloat(avgRes.toFixed(2)),
        recovery: simulatedState.engine.recovery_manager.active_level,
      });
    }
    return data;
  };

  // Run Experiment 3: 2D Stability Surface (S vs M_g)
  const getSurfaceData = () => {
    const grid = [];
    // We want Y-axis to represent Entropy S (high to low)
    for (let S = 1.0; S >= 0.1; S -= 0.1) {
      const row = [];
      // X-axis represents Modulator Gain Mg (low to high)
      for (let Mg = 0.1; Mg <= 1.0; Mg += 0.1) {
        const simulatedState = processPhysicsCycle(currentState, {
          gain: Mg,
          thermal_load: S,
          laws: activeLaws,
        });
        row.push({
          S: parseFloat(S.toFixed(1)),
          Mg: parseFloat(Mg.toFixed(1)),
          coherence: simulatedState.engine.observer.flow_guard.coherence,
          recovery: simulatedState.engine.recovery_manager.active_level,
        });
      }
      grid.push(row);
    }
    return grid;
  };

  const entropySweep = getEntropySweepData();
  const gainSweep = getGainSweepData();
  const surfaceGrid = getSurfaceData();

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-lg p-5 flex flex-col gap-4 text-slate-100 shadow-xl">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center border-b border-slate-800 pb-3 gap-3">
        <div>
          <h3 className="text-sm font-bold tracking-wider text-emerald-400 uppercase flex items-center gap-2">
            <Compass className="w-4 h-4" /> Protocol 0: Physics Verification Lab
          </h3>
          <p className="text-[10px] text-slate-500 mt-1 uppercase font-semibold font-mono">
            Analytical validation of state evolution equations (v3.2 Rules Locked)
          </p>
        </div>

        {/* Tab Controls */}
        <div className="flex bg-slate-950 p-0.5 rounded border border-slate-850">
          <button
            onClick={() => setActiveTab("surface")}
            className={`px-3 py-1 text-xs font-bold rounded flex items-center gap-1.5 transition-colors ${
              activeTab === "surface" ? "bg-emerald-600 text-white" : "text-slate-400 hover:text-white"
            }`}
          >
            <Grid3X3 className="w-3.5 h-3.5" /> 2D Collapse Map
          </button>
          <button
            onClick={() => setActiveTab("entropy")}
            className={`px-3 py-1 text-xs font-bold rounded flex items-center gap-1.5 transition-colors ${
              activeTab === "entropy" ? "bg-emerald-600 text-white" : "text-slate-400 hover:text-white"
            }`}
          >
            <BarChart3 className="w-3.5 h-3.5" /> S-Sweep
          </button>
