export const processPhysicsCycle = (
  state: EngineState,
  userModifications: {
    gain?: number;
    phase?: number;
    thermal_load?: number;
    laws?: string[];
  }
): EngineState => {
  const nextState = JSON.parse(JSON.stringify(state)) as EngineState;

  // Apply inputs to Modulator and Entropy
  if (userModifications.gain !== undefined) {
    nextState.engine.modulator.gain = parseFloat(userModifications.gain.toFixed(2));
  }
  if (userModifications.phase !== undefined) {
    nextState.engine.modulator.phase = parseFloat(userModifications.phase.toFixed(2));
  }
  if (userModifications.thermal_load !== undefined) {
    nextState.entropy.thermal_load = parseFloat(userModifications.thermal_load.toFixed(2));
  }
  if (userModifications.laws !== undefined) {
    nextState.engine.laws = userModifications.laws;
  }

  const S = nextState.entropy.thermal_load;
  const M_g = nextState.engine.modulator.gain;
  const lawsCount = nextState.engine.laws.length;

  // Calculate Container Pressure P_c = S * M_g * Constant
  const P_c = Math.min(1.0, parseFloat((S * M_g * 1.25).toFixed(3)));
  nextState.engine.container.pressure = P_c;

  // 1. Calculate Divergence Index
  // Divergence increases with raw Entropy (S) and decreases with Modulator Gain (M_g)
  const baseDivergence = S * (1.2 - M_g);
  nextState.engine.observer.flow_guard.divergence_index = Math.max(
    0,
    Math.min(1.0, parseFloat(baseDivergence.toFixed(3)))
  );

  // 2. Calculate Law Resonance
  // Law compliance changes depending on constraints and stability. If gain is too low or thermal load too high, laws breach.
  const law_res: { [key: string]: number } = {};
  let totalResonance = 0;

  nextState.engine.laws.forEach((law) => {
    let lawVal = 1.0;
    if (law === "four_line_rule") {
      lawVal = Math.max(0.4, 1.0 - (S > 0.85 ? (S - 0.85) * 2.0 : 0) + (M_g - 0.8) * 0.2);
    } else if (law === "structure_rule_v9") {
      lawVal = Math.max(0.3, 0.95 - (S > 0.75 ? (S - 0.75) * 1.5 : 0) + (M_g - 0.8) * 0.3);
    } else if (law === "no_english_bleed") {
      lawVal = Math.max(0.2, 0.9 - (S > 0.9 ? (S - 0.9) * 3.0 : 0) + (M_g - 0.8) * 0.1);
    }
    const finalVal = parseFloat(Math.min(1.0, Math.max(0.0, lawVal)).toFixed(3));
    law_res[law] = finalVal;
    totalResonance += finalVal;
  });

  const avgLawResonance = lawsCount > 0 ? totalResonance / lawsCount : 1.0;
  nextState.engine.observer.flow_guard.law_resonance = law_res;

  // 3. Compute Coherence C = M_g * (1.0 - Divergence) * LawResonance
  const rawCoherence = M_g * (1.0 - nextState.engine.observer.flow_guard.divergence_index) * avgLawResonance;
  const C = Math.max(0, Math.min(1.0, parseFloat(rawCoherence.toFixed(3))));
  nextState.engine.observer.flow_guard.coherence = C;
  nextState.state.coherence = C;

  // Calculate Stability
  const stability = Math.max(0, Math.min(1.0, parseFloat((M_g * (1.0 - S * 0.5)).toFixed(3))));
  nextState.state.stability = stability;

  // 4. Recovery Manager Logic
  let recLevel: 0 | 1 | 2 | 3 = 0;
  let actionStr = "";
  let reasonStr = "All active laws successfully observed.";
  let evidenceStr = `Coherence index (${C}) is above target threshold (${nextState.engine.observer.collapse_threshold}).`;

  if (C < nextState.engine.observer.collapse_threshold) {
    if (C < 0.35) {
      recLevel = 3;
      actionStr = "CRITICAL BREACH: Flow Guard triggered Clean Room Reset.";
      reasonStr = "Thermal load causing critical kinetic overflow.";
      evidenceStr = `Coherence (${C}) collapsed below emergency limit (0.35).`;
    } else if (C < 0.5) {
      recLevel = 2;
      actionStr = "WARNING: Restricting Entropy Bandwidth & Increasing Modulator Constraints.";
      reasonStr = "Divergence index crossed safe operating boundary.";
      evidenceStr = `Observer divergence is ${nextState.engine.observer.flow_guard.divergence_index} (limit < 0.40).`;
    } else {
      recLevel = 1;
      actionStr = "DIVERGENCE: Micro-adjusting gain / Adaptive Phase Offset applied.";
      reasonStr = "Minor structural drift in containment geometry.";
      evidenceStr = `Average Law Resonance dropped to ${(avgLawResonance * 100).toFixed(1)}%.`;
    }
  }

  nextState.engine.recovery_manager.active_level = recLevel;
  nextState.engine.observer.flow_guard.status = recLevel > 0 ? "breached" : "observing";
  nextState.engine.observer.flow_guard.reason = reasonStr;
  nextState.engine.observer.flow_guard.evidence = evidenceStr;

  // Append action if it changes
  const prevLevel = state.engine.recovery_manager.active_level;
  if (recLevel !== prevLevel && actionStr !== "") {
    const actions = [...nextState.engine.recovery_manager.control_actions];
    actions.unshift({
      level: recLevel,
      action: actionStr,
      timestamp: new Date().toLocaleTimeString(),
    });
    // Keep list compact
    nextState.engine.recovery_manager.control_actions = actions.slice(0, 5);
  }

  // Update recommendation
  if (recLevel === 0) {
    nextState.engine.observer.flow_guard.recommendation = "System stable. Observer geometry optimal.";
  } else if (recLevel === 1) {
    nextState.engine.observer.flow_guard.recommendation = "Recommend slight increase of Modulation Gain (+0.05).";
  } else if (recLevel === 2) {
    nextState.engine.observer.flow_guard.recommendation = "Divergence high. Restrict Thermal Load below 0.65.";
  } else {
    nextState.engine.observer.flow_guard.recommendation = "Collapse impossible. Perform hard Clean Room Reset.";
  }

  // Update state collapse status
  nextState.state.collapsed = recLevel === 0 && C >= nextState.engine.observer.collapse_threshold;

  // 5. Update Phase Containers in Music Director
  // Each phase handles local entropy budget. The active phase is determined sequentially.
  let activeIdx = nextState.music_director.composition.current_phase_index;

  nextState.music_director.phases = nextState.music_director.phases.map((phase, idx) => {
    const isCurrent = idx === activeIdx;

    // Local physics computation for each phase
    const phaseEntropy = S * phase.entropy_budget;
    const localDivergence = phaseEntropy * (1.1 - M_g);
    const localResonance = Math.max(0.1, avgLawResonance - localDivergence * 0.3);
    const localCoherence = parseFloat(
      Math.max(0, Math.min(1.0, M_g * (1.0 - localDivergence) * localResonance)).toFixed(3)
    );

    let localRec: 0 | 1 | 2 | 3 = 0;
    if (localCoherence < nextState.engine.observer.collapse_threshold) {
      localRec = localCoherence < 0.4 ? 3 : localCoherence < 0.55 ? 2 : 1;
    }

    return {
      ...phase,
      vocabulary_resonance: parseFloat(Math.min(1.0, avgLawResonance * 1.05).toFixed(3)),
      law_resonance: parseFloat(localResonance.toFixed(3)),
      coherence: localCoherence,
      collapsed: localRec === 0,
      recovery_level: localRec,
      constants_applied: ["Symmetric Stanzaic", "Four-Line Rule"],
      collapse_time_ms: idx * 42 + 25,
    };
  });

  // Adaptive Memory Update
  if (nextState.state.collapsed) {
    nextState.memory_engine.state = "stabilizing";
    nextState.memory_engine.active_context_size_kb = parseFloat(
      (12.4 + Math.random() * 0.2).toFixed(2)
    );
  } else {
    nextState.memory_engine.state = "idle";
  }

  return nextState;
};

