  // Helper: linear interpolation (lerp)
  const lerp = (start: number, end: number, amt: number) => {
    return (1 - amt) * start + amt * end;
  };

  // Get current continuous state coordinates under v1.7 continuous model
  const getContinuousState = (t: number) => {
    const floorIndex = Math.floor(t);
    const ceilIndex = Math.min(floorIndex + 1, SONGS.length - 1);
    const fraction = t - floorIndex;

    const sStart = SONGS[floorIndex];
    const sEnd = SONGS[ceilIndex];

    return {
      x: parseFloat(lerp(sStart.x, sEnd.x, fraction).toFixed(2)),
      y: parseFloat(lerp(sStart.y, sEnd.y, fraction).toFixed(2)),
      tension: parseFloat(lerp(sStart.tensionScore, sEnd.tensionScore, fraction).toFixed(2)),
      activeClusterId: fraction < 0.5 ? sStart.clusterId : sEnd.clusterId,
      activeClusterName: fraction < 0.5 ? sStart.cluster : sEnd.cluster,
      approachingNode: fraction > 0 ? sEnd.name : sStart.name,
      fraction
    };
  };

  const liveState = getContinuousState(timelineTime);

  // v1.8 Exponential Decay Simulator Effect
  // As the simulation plays or is scrubbed, simulate cognitive attention and recall fidelity decaying
  useEffect(() => {
    if (engineMode === "v1.8") {
      // Whenever timelineTime is adjusted or simulation progresses:
      // Real-time attention spikes dynamically upon crossing a node (integer index)
      const fraction = liveState.fraction;

      // Attention curve: Spikes at node entry, decays exponentially as playhead traverses the vector gap
      const calculatedAttention = Math.max(
        15,
        Math.round(100 * Math.exp(-2.5 * fraction * decaySpeedMultiplier))
      );
      setAttentionLevel(calculatedAttention);

      // Memory retention decay accumulates over the timeline (slower linear-exponential decay)
      const calculatedRetention = Math.max(
        5,
        Math.round(100 * Math.exp(-0.08 * timelineTime * decaySpeedMultiplier))
      );
      setMemoryRetention(calculatedRetention);
    }
  }, [timelineTime, decaySpeedMultiplier, engineMode]);

  // Coordinate mapper functions for SVG rendering
  // Coordinates are mapped from [-100, 100] to a [50, 750] x [400, 50] grid space.
  const mapX = (x: number, width: number = 800) => {
    return ((x + 100) / 200) * (width - 100) + 50;
  };

  // Invert Y axis so that High Energy (y = +100) is at the top of the screen
  const mapY = (y: number, height: number = 450) => {
