let audioCtx: AudioContext | null = null;

export function playPhysicsNode(x: number, y: number, tension: number) {
  try {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }

    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }

    const now = audioCtx.currentTime;

    // Y-axis (-100 to 100) maps to base frequency (lower energy = deeper, higher energy = higher pitch)
    const normalizedY = (y + 100) / 200; // 0 to 1
    const baseFreq = 120 + normalizedY * 500; // 120Hz to 620Hz

    // Create oscillator
    const osc = audioCtx.createOscillator();
    const osc2 = audioCtx.createOscillator();

    // Choose wave based on tension
    if (tension > 75) {
      osc.type = "sawtooth";
      osc2.type = "triangle";
    } else if (tension > 40) {
      osc.type = "square";
      osc2.type = "sine";
    } else {
      osc.type = "sine";
      osc2.type = "sine";
    }

    osc.frequency.setValueAtTime(baseFreq, now);
    // Slightly detune second osc for cinematic thickness
    osc2.frequency.setValueAtTime(baseFreq * 1.015, now);

    // Low pass filter driven by energy/tension
    const filter = audioCtx.createBiquadFilter();
    filter.type = "lowpass";
    const filterFreq = 200 + (normalizedY * 2000) + (tension * 15);
    filter.frequency.setValueAtTime(filterFreq, now);
    filter.Q.setValueAtTime(4, now);

    // Panning based on X-axis (-100 to 100) (Internal/Left, External/Right)
    const panner = audioCtx.createStereoPanner ? audioCtx.createStereoPanner() : null;
    const panVal = Math.min(Math.max(x / 100, -1), 1);
    if (panner) {
      panner.pan.setValueAtTime(panVal, now);
    }

    // Gain envelope
    const gainNode = audioCtx.createGain();
    gainNode.gain.setValueAtTime(0, now);
    gainNode.gain.linearRampToValueAtTime(0.25, now + 0.05);
    // Exponential decay
    gainNode.gain.exponentialRampToValueAtTime(0.001, now + 1.2);

    // Routing
    osc.connect(filter);
    osc2.connect(filter);

    if (panner) {
      filter.connect(panner);
      panner.connect(gainNode);
    } else {
      filter.connect(gainNode);
    }

    gainNode.connect(audioCtx.destination);

    osc.start(now);
    osc2.start(now);
    osc.stop(now + 1.3);
    osc2.stop(now + 1.3);
  } catch (e) {
    console.warn("Web Audio Context not initialized or supported yet.", e);
  }
}

export function playArpeggio(trajectory: {x: number, y: number, tension: number}[]) {
  try {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }

    const now = audioCtx.currentTime;
    trajectory.forEach((node, idx) => {
      const timeOffset = idx * 0.15; // Fast sweep

      const osc = audioCtx!.createOscillator();
      const gainNode = audioCtx!.createGain();
      const filter = audioCtx!.createBiquadFilter();

      const normY = (node.y + 100) / 200;
      const freq = 180 + normY * 600;

      osc.type = "sine";
      osc.frequency.setValueAtTime(freq, now + timeOffset);

      filter.type = "lowpass";
      filter.frequency.setValueAtTime(300 + normY * 1500, now + timeOffset);

      gainNode.gain.setValueAtTime(0, now + timeOffset);
      gainNode.gain.linearRampToValueAtTime(0.12, now + timeOffset + 0.02);
      gainNode.gain.exponentialRampToValueAtTime(0.001, now + timeOffset + 0.35);

      osc.connect(filter);
      filter.connect(gainNode);
      gainNode.connect(audioCtx!.destination);

      osc.start(now + timeOffset);
      osc.stop(now + timeOffset + 0.4);
    });
  } catch (e) {
    console.warn(e);
  }
}

