export type LyricMode = 
  | "grounded" 
  | "mechanical" 
  | "surreal" 
  | "dream_logic" 
  | "symbolic" 
  | "experimental";

export interface EvidenceItem {
  id: string;
  lineIndex: number;
  text: string;
  object: string;
  action: string;
  domain: "mechanical" | "acoustic" | "natural" | "biological" | "astronomical" | "abstract" | "unknown";
  observable: boolean;
  intensity: number; // 0-1
}

export interface SemanticLink {
  source: string;
  target: string;
  strength: number; // 0-1
  type: string;
}

export interface SemanticNode {
  id: string;
  label: string;
  domain: string;
  occurrences: number;
  valency: number; // connectedness
}

export interface RuleResult {
  id: string;
  name: string;
  description: string;
  weight: number;
  priority: "CRITICAL" | "HIGH" | "MEDIUM" | "LOW";
  status: "verified" | "stable" | "unstable" | "domain_drift" | "insufficient_evidence";
  evidenceCount: number;
  violations: string[];
  justification: string;
  provenance: {
    lineIndex: number;
    text: string;
    token: string;
    domain: string;
  }[];
  whyNotRecord?: {
    token: string;
    reason: string;
  };
}

export interface ConfidenceMetrics {
  sampleLength: number; // text length penalty/bonus
  domainStability: number; // percentage
  parserCoverage: number; // mapped tokens
  ruleAgreement: number; // consistency
  overall: number; // weighted combination
}

export interface DiagnosticMetadata {
  diagnosticId: string;
  constitutionVersion: string;
  parserVersion: string;
  neighborhoodEngineVersion: string;
  timestamp: string;
}

export interface ParserCoverageStats {
  recognizedPercent: number;
  unknownPercent: number;
  ambiguousPercent: number;
}

export interface ValidationTestResult {
  testId: string;
  category: string;
  specimenName: string;
  expectedBehavior: string;
  actualTelemetry: string;
  verdict: "PASS" | "FAIL";
}

export interface DiagnosticReport {
  metadata: DiagnosticMetadata;
  mode: LyricMode;
  evidence: EvidenceItem[];
  nodes: SemanticNode[];
  links: SemanticLink[];
  rules: RuleResult[];
  confidence: ConfidenceMetrics;
  coverage: ParserCoverageStats;
  validationSuite: ValidationTestResult[];
}

