  // Custom Calibration State
  const [customTitle, setCustomTitle] = useState<string>("Diagnostic Run Alpha");
  const [savedRecords, setSavedRecords] = useState<ArchiveEntry[]>([]);
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [archiveFilter, setArchiveFilter] = useState<string>("ALL"); // ALL, PASS, FAIL, HEAR

  // UI Panels State
  const [isConstitutionOpen, setIsConstitutionOpen] = useState<boolean>(false);
  const [isArchiveOpen, setIsArchiveOpen] = useState<boolean>(false);

  // Load Archive from LocalStorage on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem("elyzareth_brain_archive");
      if (stored) {
        setSavedRecords(JSON.parse(stored));
      }
    } catch (e) {
      console.error("Failed to load archive", e);
    }
  }, []);

  // Save Archive to LocalStorage
  const saveArchiveToStorage = (updated: ArchiveEntry[]) => {
    try {
      localStorage.setItem("elyzareth_brain_archive", JSON.stringify(updated));
      setSavedRecords(updated);
    } catch (e) {
      console.error("Failed to save archive", e);
    }
  };

  // Preset Selection
  const handlePresetSelect = (presetId: string) => {
    const preset = presetsData.find((p) => p.id === presetId) as Preset | undefined;
    if (preset) {
      setSelectedPresetId(presetId);
      setLyrics(preset.lyrics);
      setCustomTitle(preset.title.replace("Clinical Sample: ", ""));

      const fullTelemetry = calculateRealtimeTelemetry(preset.lyrics);
      setActiveTelemetry(fullTelemetry);
      setCurrentStep(-1);
      setIsProcessing(false);
      setSimulationLog([`Operator loaded preset spec: ${preset.title}`]);
    }
  };

  // Rule Parser for Realtime Custom Lyric Calculations
  const calculateRealtimeTelemetry = (text: string): Telemetry => {
    const textLower = text.toLowerCase();

    // Banned Words check (Rule III: Cliché Template Bleed)
    const bannedWords = ["neon", "whisper", "echo", "shadows", "cage", "key", "void", "dancing stars", "whispers", "echoes"];
    let detectedBanned: string[] = [];
    bannedWords.forEach(word => {
      if (textLower.includes(word)) {
        detectedBanned.push(word);
      }
    });

    // Concrete Grounding & Observable Consequences (Rule II)
    const physicalAnchors = ["cold", "heat", "steam", "pressure", "expansion", "metal", "steel", "oil", "soil", "iron", "oxide", "ice", "boil", "water", "salt", "coal", "stone", "copper", "rust", "concrete", "temperature", "kelvin", "folded", "letter", "knock", "door", "boot", "step", "glass", "dust", "wire", "plate"];
    let detectedPhysical: string[] = [];
    physicalAnchors.forEach(word => {
      const regex = new RegExp(`\\b${word}\\b`, 'gi');
      if (textLower.match(regex)) {
        detectedPhysical.push(word);
      }
    });

    // Structure rules (Rule IV)
    const hasIntro = textLower.includes("[intro]");
    const hasVerse = textLower.includes("[verse");
    const hasChorus = textLower.includes("[chorus]");
    const hasBridge = textLower.includes("[bridge]");
    const hasOutro = textLower.includes("[outro]");

    // Base math calculations
    let originality = Math.max(0.05, 1.0 - (detectedBanned.length * 0.22));
    let concreteGrounding = Math.min(0.99, 0.25 + (detectedPhysical.length * 0.08) + (hasBridge ? 0.12 : 0));
    let coherence = Math.min(0.99, 0.15 + (detectedPhysical.length * 0.06) - (detectedBanned.length * 0.10) + (hasChorus ? 0.15 : 0) + (hasVerse ? 0.1 : 0));

    // Normalize bounds
    coherence = Math.max(0.08, Math.min(0.98, coherence));
    concreteGrounding = Math.max(0.10, Math.min(0.98, concreteGrounding));

    // New telemetry mappings
    let stateChange = Math.min(0.98, 0.2 + (concreteGrounding * 0.6) + (hasIntro && hasOutro ? 0.15 : 0));
    let evidenceDensity = Math.max(0.10, Math.min(0.98, (concreteGrounding * 0.7) + (originality * 0.3)));
    let continuity = Math.min(0.98, 0.3 + (coherence * 0.5) + (hasChorus ? 0.15 : 0));
    let alignment = Math.max(0.05, Math.min(0.99, (originality * 0.4) + (coherence * 0.3) + (evidenceDensity * 0.3)));

    // Structural scoring (Intro-Verse-Chorus matching)
    const totalLines = text.split("\n").filter(l => l.trim().length > 0).length;
    if (totalLines < 8) {
      coherence *= 0.7;
      concreteGrounding *= 0.6;
    }

    // Determine Verdict
    let verdict: "PASS" | "FAIL" | "HEAR" = "HEAR";
    let confidence = 75;
    let cause = "Standard calibration evaluation completed with stable boundaries.";
    let witnessReport = "";

    if (alignment < 0.4 || coherence < 0.3) {
      verdict = "FAIL";
      confidence = Math.round(85 + (1.0 - alignment) * 10);
      cause = detectedBanned.length > 0 
        ? `Framework Misalignment. Cliché density detected: [${detectedBanned.join(", ")}].`
        : "Thermodynamic field collapse. Structural coherence score fell below framework alignment threshold.";
      witnessReport = "The specimen presents framework misalignment. It relies on unsupported emotional declarations, bleeding natural human taste into generic high-entropy database patterns. Actionable evidence is lacking.";
    } else if (coherence > 0.70 && concreteGrounding > 0.65 && alignment > 0.75) {
      verdict = "PASS";
      confidence = Math.round(90 + (coherence * 5) + (concreteGrounding * 3));
      cause = "Optimal framework alignment. Flawless observable grounding and narrative progression.";
      witnessReport = "Observation validates this specimen as aligned with ELYZARETH OS principles. Emotional consequence is perfectly conducted through concrete actions and environmental change. Final creative judgment reserved for the artist.";
    } else {
      verdict = "HEAR";
      confidence = Math.round(60 + (concreteGrounding * 20));
      cause = "Authentic but structurally irregular. Low cliché clusters but high semantic entropy or unstable continuity.";
      witnessReport = "This writing presents genuine, unbleached semantic signals, but lacks stable geometric structure. A raw, unmodeled trace. Recommended to review evidence checklist before production.";
    }

    // Build Traceable Evidence Items
    const evidence: EvidenceItem[] = [];

    if (detectedPhysical.length >= 4) {
      evidence.push({
        label: "Concrete Grounding Verified",
        type: "success",
        description: `Identified ${detectedPhysical.length} distinct observable triggers [${detectedPhysical.slice(0, 4).join(", ")}...]. Energy is conducted through physical actions.`
      });
    } else if (detectedPhysical.length > 0) {
      evidence.push({
        label: "Moderate Grounding Baseline",
        type: "success",
        description: `Found limited observable transitions [${detectedPhysical.join(", ")}]. Anchoring meets baseline framework expectations.`
      });
    } else {
      evidence.push({
        label: "Assertion Over Evidence Deficit",
        type: "warning",
        description: "No physical state changes or human action triggers detected. Relying heavily on emotional assertions."
      });
    }

    if (detectedBanned.length === 0) {
      evidence.push({
        label: "Cliché Attractor Clearance",
        type: "success",
        description: "No prohibited semantic anchors or low-effort generic pairings detected. Safe voice calibration verified."
      });
    } else {
      evidence.push({
        label: "Token Gravity Warnings",
        type: "error",
        description: `Metaphor pairings triggered warnings on: [${detectedBanned.join(", ")}]. Potential template bleed.`
      });
    }

    const structureMatch = hasIntro && hasVerse && hasChorus;
    if (structureMatch) {
      evidence.push({
        label: "Structural Continuity Maintained",
        type: "success",
        description: "Core structural movements (Intro, Verse, Chorus) detected. Geometric progression validated."
      });
    } else {
      evidence.push({
        label: "Geometric Discontinuity",
        type: "warning",
        description: "Missing conventional architectural segments. High-entropy temporal layout detected."
      });
    }

    if (totalLines >= 12) {
      evidence.push({
        label: "High Evidence Density",
        type: "success",
        description: `Specimen contains ${totalLines} lines of active data, consistently supporting emotional claims with observable consequences.`
      });
    } else {
      evidence.push({
        label: "Evidence Density Warning",
        type: "warning",
        description: `Insufficent sample size (${totalLines} lines). Telemetry points are below optimal threshold to establish absolute continuity bounds.`
      });
    }

    return {
      originality: parseFloat(originality.toFixed(2)),
      coherence: parseFloat(coherence.toFixed(2)),
      concreteGrounding: parseFloat(concreteGrounding.toFixed(2)),
      stateChange: parseFloat(stateChange.toFixed(2)),
      evidenceDensity: parseFloat(evidenceDensity.toFixed(2)),
      continuity: parseFloat(continuity.toFixed(2)),
      alignment: parseFloat(alignment.toFixed(2)),
      verdict,
      confidence: Math.min(99, Math.max(50, confidence)),
      cause,
      witnessReport,
      evidence
    };
  };

  // Run Simulated Diagnostics
  const handleInitiateDiagnostic = () => {
    setIsProcessing(true);
    setCurrentStep(0);
    setSimulationLog(["⚡ COMMENCING FIELD DIAGNOSTIC... INITIALIZING PIPELINE..."]);

