        setSimulationLog(prev => [...prev, step.log]);

        if (idx === steps.length - 1) {
          // Final Step completed
          setTimeout(() => {
            const finalTelemetry = calculateRealtimeTelemetry(lyrics);
            setActiveTelemetry(finalTelemetry);
            setCurrentStep(5);
            setIsProcessing(false);
            setSimulationLog(prev => [
              ...prev, 
              `✅ DIAGNOSTIC RUN COMPLETED. RESULT: ${finalTelemetry.verdict} (${finalTelemetry.confidence}% Certainty)`
            ]);
