  });

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-start bg-[#050907] text-[#D8E6DE] font-mono select-none antialiased">

      {/* 1. Header & Terminal Branding */}
      <header className="w-full max-w-7xl px-6 pt-6 pb-4 border-b border-[#14231B] flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-[#070D0A]/70 backdrop-blur-md sticky top-0 z-40">
        <div>
