]

import React, { useState, useEffect, useRef } from "react";
import { 
  Play, Pause, RefreshCw, Terminal, CheckCircle2, AlertTriangle, 
  XCircle, Archive, Shield, Layers, HelpCircle, Activity, 
  Cpu, FileText, Send, Database, Trash2, ArrowRight, Settings
} from "lucide-react";
import { PRESETS } from "./presets";
import { ENGINE_CONTRACT } from "./contract";

interface Metric {
  name: string;
  code: string;
  value: number;
  goal: string;
  description: string;
}

interface Diagnosis {
  decision: "PASS" | "REVISE" | "QUARANTINE" | "REJECT";
  summary: string;
  warnings: string[];
  witness_report?: {
    story_coherent: boolean;
    emotional_continuity: boolean;
    vocabulary_original: boolean;
    no_cliches: boolean;
    witness_intact: boolean;
  };
}

interface FlightRecord {
  scanNum: number;
  timestamp: string;
  decision: "PASS" | "REVISE" | "QUARANTINE" | "REJECT";
  linesCount: number;
  entropy: number;
}

export default function Component() {
  const [activeTab, setActiveTab]: [any, any] = useState("wheel");
  const [inputText, setInputText]: [any, any] = useState(PRESETS[0].lyrics);
  const [inputContext, setInputContext]: [any, any] = useState(PRESETS[0].context);
  const [selectedPresetId, setSelectedPresetId]: [any, any] = useState("pres_1");

  // Scan state
  const [isScanning, setIsScanning] = useState<boolean>(false);
  const [currentStep, setCurrentStep] = useState<number>(-1);
  const [scanSpeed, setScanSpeed] = useState<number>(500); // ms per step

  // Flight Recorder State (Traceability ledger)
  const [flightHistory, setFlightHistory] = useState<FlightRecord[]>([
    { scanNum: 1, timestamp: "22:15:02", decision: "REVISE", linesCount: 6, entropy: 0.54 },
    { scanNum: 2, timestamp: "22:18:40", decision: "PASS", linesCount: 8, entropy: 0.88 }
  ]);

  // Live calculated or customized metrics
  const [metrics, setMetrics] = useState<Record<string, number>>({
    entropy: 0.88,
    coherence: 0.94,
    pressure: 0.85,
    gain: 0.75,
    memory: 0.12,
    recovery: 0.90,
    flow_guard: 1.00
  });

  const [diagnosis, setDiagnosis] = useState<Diagnosis>({
    decision: "PASS",
    summary: "Exquisite structural balance. Zero English-word bleed. High thematic cohesion with concrete, physical anchors.",
    warnings: [],
    witness_report: {
      story_coherent: true,
      emotional_continuity: true,
      vocabulary_original: true,
      no_cliches: true,
      witness_intact: true
    }
  });

  // Local storage history of scanned/archived records
  const [archiveList, setArchiveList] = useState<any[]>([]);
  const [archiveFilter, setArchiveFilter] = useState<string>("ALL");

  // Web Audio Context for clinical retro diagnostic hums and sound alerts
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Initialize archive list from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem("elyzareth_archive");
    if (saved) {
      try {
        setArchiveList(JSON.parse(saved));
      } catch (e) {
        console.error(e);
      }
    } else {
      const initial = [
        {
          id: "arch_1",
          title: "Laut Aao",
          timestamp: "2026-07-04 14:23",
          lyrics: "Khaali kamra, dheemi saans,\nDeewaron pe tera aks.\nWaqt ruka hai us mod par,\nJahan chhoota tha tera hath.",
          decision: "PASS",
          metrics: { entropy: 0.88, coherence: 0.94, pressure: 0.85, flow_guard: 1.0 }
        },
        {
          id: "arch_2",
          title: "Pehli Dafa",
          timestamp: "2026-07-04 12:10",
          lyrics: "Pehli dafa jab unse mile\nKuchh bol na paaye hum.\nSookhi pattiyaan gir rahi thi\nUsi mod pe khade rahe hum.",
          decision: "PASS",
          metrics: { entropy: 0.82, coherence: 0.88, pressure: 0.79, flow_guard: 1.0 }
        },
        {
          id: "arch_3",
          title: "Neon Shadows Overload",
          timestamp: "2026-07-03 18:45",
          lyrics: "Lost in the neon skies tonight,\nEverything is fading, out of sight.\nMy heart beats in the dark, alright.",
          decision: "REJECT",
          metrics: { entropy: 0.21, coherence: 0.45, pressure: 0.30, flow_guard: 0.20 }
        },
        {
          id: "arch_4",
          title: "Quantum Waveform 8",
          timestamp: "2026-07-03 15:20",
          lyrics: "[Frequency Lock]\nEntropy trace dynamic alpha.",
          decision: "QUARANTINE",
          metrics: { entropy: 0.95, coherence: 0.15, pressure: 0.90, flow_guard: 0.50 }
        }
      ];
      localStorage.setItem("elyzareth_archive", JSON.stringify(initial));
      setArchiveList(initial);
    }
  }, []);

  // Web Audio trigger function
  const playDiagnosticBeep = (freq: number, duration: number, type: "sine" | "triangle" | "sawtooth" | "square" = "sine") => {
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === "suspended") {
        ctx.resume();
      }
      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.type = type;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gainNode.gain.setValueAtTime(0.08, ctx.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + duration);
    } catch (e) {
      // Audio fallback
    }
  };

  // Pipeline execution sequence ("THE WHEEL")
  const pipelineSteps = [
    { name: "Import", desc: "Ingesting physical and text payload." },
    { name: "Preprocess", desc: "Stripping extraneous tokens & white space." },
    { name: "Memory Load", desc: "Checking template overlap & duplicate indices." },
    { name: "Physics Scan", desc: "Measuring entropy, coherence, pressure, gain." },
    { name: "Flow Guard Check", desc: "Validating against ELYZARETH OS rule thresholds." },
    { name: "Rule Evaluation", desc: "Synthesizing constraints (4-Line rule)." },
    { name: "Creative Diagnosis", desc: "Formulating clinical recommendations." },
    { name: "Report", desc: "Synthesizing terminal outputs." }
  ];

  // Helper to load presets
  const loadPreset = (presetId: string) => {
    const found = PRESETS.find(p => p.id === presetId);
    if (found) {
      setSelectedPresetId(presetId);
      setInputText(found.lyrics);
      setInputContext(found.context);
      setMetrics(found.expected_metrics);

      const m = found.expected_metrics;
      setDiagnosis({
        decision: found.diagnosis.decision,
        summary: found.diagnosis.summary,
        warnings: found.diagnosis.warnings,
        witness_report: {
          story_coherent: m.coherence >= 0.70,
          emotional_continuity: m.flow_guard >= 0.80,
          vocabulary_original: m.entropy >= 0.65,
          no_cliches: m.memory < 0.45,
          witness_intact: m.pressure >= 0.60
        }
      });
      playDiagnosticBeep(440, 0.1, "sine");
    }
  };

  // Live evaluation algorithm (Heuristics)
  const calculateHeuristics = (text: string, context: string) => {
    const lines = text.split("\n").filter(l => l.trim().length > 0);
    const words = text.toLowerCase().match(/\b\w+\b/g) || [];
    const uniqueWords = new Set(words);

    // 1. Entropy calculation based on unique-to-total word ratio
    let entropyVal = words.length > 0 ? uniqueWords.size / words.length : 0;
    entropyVal = Math.min(1.0, Math.max(0.1, entropyVal * 1.2));

    // 2. Coherence calculation
    const lineLengths = lines.map(l => l.length);
    const avgLen = lineLengths.length > 0 ? lineLengths.reduce((a,b)=>a+b, 0) / lineLengths.length : 0;
    let lengthVariance = 0;
    if (lineLengths.length > 0) {
      const sqDiffs = lineLengths.map(l => Math.pow(l - avgLen, 2));
      lengthVariance = Math.sqrt(sqDiffs.reduce((a,b)=>a+b, 0) / lineLengths.length);
    }
    let coherenceVal = lengthVariance > 30 ? 0.65 : 0.92;

    // 3. Pressure calculation
    const physicalKeywords = ["kamra", "room", "floor", "door", "deewaron", "saans", "hath", "water", "stone", "cold", "clock", "light", "pattiyaan"];
    const abstractKeywords = ["dil", "pyaar", "feeling", "love", "baby", "heart", "sad", "happy", "destiny", "control"];

    let physCount = 0;
    let absCount = 0;
    words.forEach(w => {
      if (physicalKeywords.includes(w)) physCount++;
      if (abstractKeywords.includes(w)) absCount++;
    });

    let pressureVal = 0.5;
    if (physCount + absCount > 0) {
      pressureVal = physCount / (physCount + absCount);
    } else {
      pressureVal = Math.min(0.95, Math.max(0.4, 0.7 + (lines.length % 5) * 0.05));
    }

    // 4. Cliché Memory trigger
    const aiClichs = ["neon", "shadows", "whispers", "shatter", "ticking clock", "dancing in the dark", "digital world", "fading", "rhythm", "beat"];
    let memoryOverlapCount = 0;
    const lowerText = text.toLowerCase();
    aiClichs.forEach(c => {
      if (lowerText.includes(c)) memoryOverlapCount++;
    });
    const memoryVal = Math.min(0.98, Math.max(0.05, memoryOverlapCount * 0.25 + 0.1));

    // 5. Flow Guard score
    const englishWordsInHindi = ["love", "baby", "neon", "tonight", "alright", "rhythm", "beat", "digital", "control"];
    let isHindiUrduContext = context.toLowerCase().includes("hindi") || context.toLowerCase().includes("hinglish") || /[\u0900-\u097F]/.test(text);
    let flowGuardVal = 1.0;
    if (isHindiUrduContext) {
      let intrusionCount = 0;
      englishWordsInHindi.forEach(w => {
        if (words.includes(w)) intrusionCount++;
      });
      if (intrusionCount > 0) {
        flowGuardVal = Math.max(0.2, 1.0 - intrusionCount * 0.2);
      }
    }

    const gainVal = Math.min(0.95, Math.max(0.3, 0.5 + (lines.length % 4) * 0.1));
    const recoveryVal = Math.min(0.95, Math.max(0.4, 0.8 - (memoryVal * 0.3)));

    const computedMetrics = {
      entropy: parseFloat(entropyVal.toFixed(2)),
      coherence: parseFloat(coherenceVal.toFixed(2)),
      pressure: parseFloat(pressureVal.toFixed(2)),
      gain: parseFloat(gainVal.toFixed(2)),
      memory: parseFloat(memoryVal.toFixed(2)),
      recovery: parseFloat(recoveryVal.toFixed(2)),
      flow_guard: parseFloat(flowGuardVal.toFixed(2))
    };

    let decision: "PASS" | "REVISE" | "QUARANTINE" | "REJECT" = "PASS";
    let summary = "Optimal balance. Zero critical rules broken. Preserves original organic poetry.";
    const warnings: string[] = [];

    if (computedMetrics.flow_guard < 0.8) {
      decision = "REVISE";
      warnings.push("High-Taste Guard: English vocabulary intrusion detected in Hinglish context.");
    }
    if (computedMetrics.memory > 0.45) {
      decision = decision === "REVISE" ? "REJECT" : "REVISE";
      warnings.push(`Extreme Token Gravity: Cliché overlap density too high (${Math.round(computedMetrics.memory * 100)}%).`);
    }
    if (computedMetrics.pressure < 0.5) {
      warnings.push("Low Physical Pressure: Lyrics use abstract emotion labels instead of structural objects.");
    }
    if (lines.length % 4 !== 0) {
      warnings.push("Asymmetrical Layout: Lines do not fit the perfect 4-line rule framework.");
    }

    if (computedMetrics.entropy > 0.95 && computedMetrics.coherence < 0.3) {
      decision = "QUARANTINE";
      summary = "Unorthodox entropy trace. Completely avoids generic AI models, potentially brilliant or purely static.";
    } else if (computedMetrics.memory > 0.7) {
      decision = "REJECT";
      summary = "AI template bleed. Heavy generic training weight detected. Lock down and reject.";
    } else if (decision === "REVISE") {
      summary = "Structure requires targeted intervention. Redesign cliché nodes and restore high-taste Romanized stability.";
    } else if (decision === "PASS") {
      summary = "Exquisite structural balance. Zero English-word bleed. Metaphor integrity is preserved.";
    }

    return { 
      metrics: computedMetrics, 
      diagnosis: { 
        decision, 
        summary, 
        warnings,
        witness_report: {
          story_coherent: computedMetrics.coherence >= 0.70,
          emotional_continuity: computedMetrics.flow_guard >= 0.80,
          vocabulary_original: computedMetrics.entropy >= 0.65,
          no_cliches: computedMetrics.memory < 0.45,
          witness_intact: computedMetrics.pressure >= 0.60
        }
      } 
    };
  };

  // Trigger full diagnostic cycle ("THE WHEEL")
  const triggerScan = () => {
    setIsScanning(true);
    setCurrentStep(0);
    playDiagnosticBeep(600, 0.15, "sawtooth");
  };

  // Run stepping logic
  useEffect(() => {
    if (!isScanning) return;

    if (currentStep < pipelineSteps.length) {
      const timer = setTimeout(() => {
        const stepFreq = 300 + currentStep * 80;
        playDiagnosticBeep(stepFreq, 0.05, "sine");
        setCurrentStep(prev => prev + 1);
      }, scanSpeed);
      return () => clearTimeout(timer);
    } else {
      setIsScanning(false);
      const results = calculateHeuristics(inputText, inputContext);
      setMetrics(results.metrics);
      setDiagnosis(results.diagnosis);

      // Update Flight Recorder (Traceability ledger)
      const lines = inputText.split("\n").filter(l => l.trim().length > 0);
      const newRecord: FlightRecord = {
        scanNum: flightHistory.length + 1,
        timestamp: new Date().toTimeString().split(" ")[0],
        decision: results.diagnosis.decision,
        linesCount: lines.length,
        entropy: results.metrics.entropy
      };
      setFlightHistory(prev => [...prev, newRecord]);

      // Sound cues
      if (results.diagnosis.decision === "PASS") {
        playDiagnosticBeep(880, 0.3, "sine");
        setTimeout(() => playDiagnosticBeep(1100, 0.4, "sine"), 150);
      } else if (results.diagnosis.decision === "REJECT") {
        playDiagnosticBeep(150, 0.6, "sawtooth");
      } else {
        playDiagnosticBeep(330, 0.4, "triangle");
      }
    }
  }, [isScanning, currentStep]);

  // Archive Current Run
  const archiveCurrentRun = () => {
    const newArch = {
      id: "arch_" + Date.now(),
      title: `${inputText.substring(0, 15).replace(/\n/g, " ")}...`,
      timestamp: new Date().toISOString().replace("T", " ").substring(0, 16),
      lyrics: inputText,
      decision: diagnosis.decision,
      metrics: metrics
    };
    const updated = [newArch, ...archiveList];
    setArchiveList(updated);
    localStorage.setItem("elyzareth_archive", JSON.stringify(updated));
    playDiagnosticBeep(950, 0.15, "sine");
  };

  // Clear archive
  const clearArchive = () => {
    setArchiveList([]);
    localStorage.removeItem("elyzareth_archive");
    playDiagnosticBeep(200, 0.3, "sawtooth");
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-neutral-950 text-neutral-200 font-sans p-4 md:p-8">
      {/* Root Container */}
      <div className="w-full max-w-6xl bg-neutral-900 border border-neutral-800 rounded-lg overflow-hidden shadow-2xl flex flex-col">

        {/* Header Terminal Band */}
        <div className="bg-neutral-950 px-6 py-4 border-b border-neutral-800 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-3.5 h-3.5 rounded-full bg-emerald-500 animate-pulse" />
            <div>
              <h1 className="text-sm font-mono tracking-wider text-emerald-400 font-bold uppercase">ELYZARETH OS v1.0 // THE BRAIN</h1>
              <p className="text-xs text-neutral-500 font-mono">Status: Witness-Centered Lyric Decision Engine</p>
            </div>
          </div>

          {/* Navigation Controls */}
          <div className="flex bg-neutral-900 p-1 rounded border border-neutral-800 font-mono text-xs">
            <button 
              onClick={() => { setActiveTab("wheel"); playDiagnosticBeep(440, 0.05); }}
              className={`px-3 py-1.5 rounded transition ${activeTab === "wheel" ? "bg-emerald-950 text-emerald-400 border border-emerald-800/50" : "text-neutral-400 hover:text-neutral-100"}`}
            >
              <Cpu className="w-3 h-3 inline mr-1" />
              The Wheel
            </button>
            <button 
              onClick={() => { setActiveTab("contract"); playDiagnosticBeep(440, 0.05); }}
              className={`px-3 py-1.5 rounded transition ${activeTab === "contract" ? "bg-emerald-950 text-emerald-400 border border-emerald-800/50" : "text-neutral-400 hover:text-neutral-100"}`}
            >
              <FileText className="w-3 h-3 inline mr-1" />
              Engine Contract
            </button>
            <button 
              onClick={() => { setActiveTab("archive"); playDiagnosticBeep(440, 0.05); }}
              className={`px-3 py-1.5 rounded transition ${activeTab === "archive" ? "bg-emerald-950 text-emerald-400 border border-emerald-800/50" : "text-neutral-400 hover:text-neutral-100"}`}
            >
              <Archive className="w-3 h-3 inline mr-1" />
              Diagnostic Archive
            </button>
          </div>
        </div>

        {/* Workspace Layout */}
        <div className="p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 min-h-[600px]">

          {activeTab === "wheel" && (
            <>
              {/* Left Panel: Input & Prescription Preset Loader */}
