                        className={`text-left p-2 rounded text-xs font-mono border transition ${selectedPresetId === p.id ? "bg-emerald-950/40 border-emerald-500/50 text-emerald-400" : "bg-neutral-900 border-neutral-800 text-neutral-400 hover:border-neutral-700 hover:text-neutral-300"}`}
                      >
                        <div className="truncate font-semibold">{p.title}</div>
                        <div className="text-[10px] text-neutral-600 truncate">{p.context}</div>
