                    <input 
                      type="text" 
                      value={inputContext}
                      onChange={(e) => { (setInputContext as any)(e.target.value); (setSelectedPresetId as any)("custom"); }}
                      className="w-full bg-neutral-900 border border-neutral-800 rounded px-2.5 py-1.5 text-xs font-mono text-neutral-300 focus:outline-none focus:border-emerald-700"
                      placeholder="e.g. Album: Restless Nights | Genre: Melancholic Indie"
                    />
                  </div>

                  <div className="flex-1 min-h-[180px] flex flex-col">
                    <textarea
                      value={inputText}
                      onChange={(e) => { (setInputText as any)(e.target.value); (setSelectedPresetId as any)("custom"); }}
                      className="w-full flex-1 bg-neutral-900 border border-neutral-800 rounded p-3 text-xs font-mono text-neutral-200 focus:outline-none focus:border-emerald-700 resize-none leading-relaxed"
                      placeholder="Paste or write lyrics directly into Elyzareth OS Brain..."
                    />
                  </div>

                  {/* FLIGHT RECORDER (Traceability Ledger) */}
                  <div className="mt-3 p-3 bg-neutral-900/50 border border-neutral-800 rounded font-mono">
                    <div className="flex items-center justify-between mb-2 text-[10px] text-neutral-500 uppercase font-bold tracking-wider">
                      <span>Flight Recorder (Traceability Log)</span>
                      <span className="text-[8px] text-emerald-500">Active Session</span>
                    </div>
                    {flightHistory.length === 0 ? (
                      <div className="text-[9px] text-neutral-600 text-center py-2">No history recorded yet for current session.</div>
                    ) : (
                      <div className="flex flex-col gap-1.5 max-h-[80px] overflow-y-auto pr-1">
                        {flightHistory.map((item, index) => (
                          <div key={index} className="flex justify-between items-center text-[10px] border-b border-neutral-800/40 pb-1">
                            <span className="text-neutral-400">Scan 0{item.scanNum} [{item.timestamp}]</span>
                            <div className="flex items-center gap-2">
                              <span className="text-neutral-500">{item.linesCount} lines</span>
                              <span className={`px-1.5 py-0.5 rounded text-[8px] font-bold ${
                                item.decision === "PASS" ? "bg-emerald-950/80 text-emerald-400 border border-emerald-900/50" :
                                item.decision === "REVISE" ? "bg-amber-950/80 text-amber-400 border border-amber-900/50" :
                                item.decision === "QUARANTINE" ? "bg-orange-950/80 text-orange-400 border border-orange-900/50" :
                                "bg-red-950/80 text-red-400 border border-red-900/50"
                              }`}>
                                {item.decision}
                              </span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Manual metric fine-tuning controls */}
                  <div className="mt-3 pt-3 border-t border-neutral-800">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-[10px] font-mono text-neutral-500 uppercase flex items-center gap-1">
                        <Settings className="w-3 h-3" /> manual override sliders
                      </span>
                    </div>
                    <div className="grid grid-cols-2 gap-3 text-[10px] font-mono">
                      <div>
                        <div className="flex justify-between text-neutral-400">
                          <span>Entropy</span>
                          <span>{metrics.entropy}</span>
                        </div>
                        <input 
                          type="range" min="0" max="1" step="0.01" value={metrics.entropy} 
                          onChange={(e) => setMetrics({...metrics, entropy: parseFloat(e.target.value)})}
                          className="w-full accent-emerald-500 bg-neutral-800 h-1 rounded"
                        />
                      </div>
                      <div>
                        <div className="flex justify-between text-neutral-400">
                          <span>Coherence</span>
                          <span>{metrics.coherence}</span>
                        </div>
                        <input 
                          type="range" min="0" max="1" step="0.01" value={metrics.coherence} 
                          onChange={(e) => setMetrics({...metrics, coherence: parseFloat(e.target.value)})}
                          className="w-full accent-emerald-500 bg-neutral-800 h-1 rounded"
                        />
                      </div>
                    </div>
                  </div>

                  <button
                    onClick={triggerScan}
                    disabled={isScanning || !inputText.trim()}
                    className="mt-4 w-full bg-emerald-500 hover:bg-emerald-400 disabled:bg-neutral-800 disabled:text-neutral-600 transition text-neutral-950 font-bold font-mono text-xs py-2.5 rounded flex items-center justify-center gap-2"
                  >
                    <RefreshCw className={`w-4 h-4 ${isScanning ? "animate-spin" : ""}`} />
                    {isScanning ? "EXECUTING SCAN SEQUENCE..." : "TRIGGER ENGINE THE WHEEL SCAN"}
                  </button>
                </div>
              </div>

