                      const isDone = currentStep > idx;
                      return (
                        <div 
                          key={step.name}
                          className={`p-2 rounded border font-mono transition text-left ${
                            isActive 
                              ? "bg-emerald-950/50 border-emerald-400 text-emerald-300 animate-pulse" 
