                      if (key === "memory" && val > 0.45) { ratingColor = "text-red-500 border-red-950"; ratingDesc = "SLOP OVERFLOW"; }
                      if (key === "flow_guard" && val < 0.8) { ratingColor = "text-red-400 border-red-950"; ratingDesc = "VIOLATION"; }
                      if (key === "pressure" && val < 0.5) { ratingColor = "text-amber-400 border-amber-950"; ratingDesc = "LOW LOAD"; }

                      return (
                        <div key={key} className={`bg-neutral-900/60 p-2.5 rounded border border-neutral-800 text-left font-mono`}>
                          <div className="text-[10px] text-neutral-500 uppercase font-semibold">{key.replace("_", " ")}</div>
