// Types for State Structure
interface IntrinsicState {
  emotion: { x: number; y: number }; // Joy-Sorrow, Calm-Anger axes
  intent: number; // Intent alignment [0, 1]
  momentum: number; // Narrative momentum
}

interface KnowledgeState {
  memoryStack: string[];
  historyDepth: number;
}

interface StructuralState {
  activeCharacter: string;
  sceneConsistency: number; // [0, 1]
  relationshipTension: number; // [0, 1]
}

interface QualityState {
  entropy: number; // \Omega(t)
  flowStability: number; // \Phi(t)
  witnessDrift: number; // \Delta W(t)
  errorReductionRatio: number; // \eta(t)
  stabilityScore: number; // \Sigma composite lab metric
  // Component metrics for Sigma breakdown
  errComponent: number;
  witnessComponent: number;
  flowComponent: number;
  constraintComponent: number;
}

interface ELYCreativeState {
  tick: number;
  X: IntrinsicState;
  K: KnowledgeState;
  D: StructuralState;
  Q: QualityState;
  coordinate: { x: number; y: number }; // Coordinates on 2D manifold representation
  decision: "ACCEPT" | "REFINE" | "REJECT";
  description: string;
}

// Simulated Basins of Attraction
const BASINS = [
  { id: "A", name: "COHERENCE ANCHOR (S0)", x: 0.0, y: 0.0, radius: 0.15, color: "rgba(34, 211, 238, 0.15)" },
  { id: "B", name: "DRAMATIC TENSION", x: 0.35, y: 0.25, radius: 0.2, color: "rgba(244, 63, 94, 0.1)" },
  { id: "C", name: "MELANCHOLIC DRIFT", x: -0.3, y: -0.3, radius: 0.18, color: "rgba(168, 85, 247, 0.1)" },
  { id: "D", name: "RESOLVED FINALE", x: 0.4, y: -0.2, radius: 0.15, color: "rgba(34, 197, 94, 0.1)" }
];

// Helper to draw text progress blocks for Witness Integrity
const getIntegrityBlocks = (drift: number): string => {
  const integrity = Math.max(0, Math.min(100, Math.round((1 - drift) * 100)));
  const filledCount = Math.round(integrity / 10);
  const emptyCount = 10 - filledCount;
  return "█".repeat(filledCount) + "░".repeat(emptyCount) + ` ${integrity}%`;
};

export default function Component() {
  // Global Simulation Parameters
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTick, setCurrentTick] = useState(0);
  const [speedMs, setSpeedMs] = useState(1200); // Ms per tick
  const [researchMode, setResearchMode] = useState(true);
  const [selectedRun, setSelectedRun] = useState<"A" | "B" | "C" | "C1" | "C2" | "C3" | "C4">("B"); // Added Sweep Runs
  const [selectedNode, setSelectedNode] = useState<string>("flowguard");
  const [promptInput, setPromptInput] = useState("Cold iron lock. Shifting floorboards. Pendulum swinging in empty space.");

  // Configuration Sliders (Manually Overriding the Sim parameters)
  const [userEntropy, setUserEntropy] = useState(0.45);
  const [flowGuardGain, setFlowGuardGain] = useState(0.7);
  const [witnessInertia, setWitnessInertia] = useState(0.85);
  const [constraintStrictness, setConstraintStrictness] = useState(0.75);

  // Trajectory Simulation States (Generated arrays of ticks)
  const [runA, setRunA] = useState<ELYCreativeState[]>([]);
  const [runB, setRunB] = useState<ELYCreativeState[]>([]);
  const [runC, setRunC] = useState<ELYCreativeState[]>([]);

  // Sweep Trajectory Runs (C1 - C4)
  const [runC1, setRunC1] = useState<ELYCreativeState[]>([]);
  const [runC2, setRunC2] = useState<ELYCreativeState[]>([]);
  const [runC3, setRunC3] = useState<ELYCreativeState[]>([]);
  const [runC4, setRunC4] = useState<ELYCreativeState[]>([]);

  const [savedExperiments, setSavedExperiments] = useState<any[]>([
    { id: "FG-2026-001", name: "Stable Baseline (B)", omega: 0.45, gain: 0.70, inertia: 0.85, strictness: 0.75 },
    { id: "FG-2026-002", name: "Exploratory Run (C)", omega: 0.85, gain: 0.25, inertia: 0.40, strictness: 0.30 },
    { id: "FG-2026-003", name: "Oscillatory Gain Sweep (C4)", omega: 0.80, gain: 1.20, inertia: 0.85, strictness: 0.75 }
  ]);

  const [activeTab, setActiveTab] = useState<"visualizer" | "sweeplab">("visualizer");
  const [activeLogs, setActiveLogs] = useState<string[]>([]);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // Generate complete hypothetical trajectory data on initialization & parameter updates
  useEffect(() => {
    generateAllTrajectories();
  }, [userEntropy, flowGuardGain, witnessInertia, constraintStrictness, promptInput]);

  const generateAllTrajectories = () => {
    const seedLogs: string[] = [
      `00:00.000 [ORCHESTRATOR] Initializing ELY OS Studio Simulation Laboratory v0.1`,
      `00:00.024 [ORCHESTRATOR] Parsing prompt token coordinates: "${promptInput.slice(0, 32)}..."`,
      `00:00.042 [INITIALIZATION] Formulating initial value problem S(0) on manifold`
    ];

    // Build Trajectory for Run A: Low Entropy (\Omega = 0.15) -> Deterministic Convergence
    const trajA = simulateTrajectory(0.15, 0.9, 0.95, 0.9, 0.0, 0.0, false);
    // Build Trajectory for Run B: Medium/Optimized Entropy (\Omega = 0.45) -> Controlled Exploration
    const trajB = simulateTrajectory(userEntropy, flowGuardGain, witnessInertia, constraintStrictness, 0.1, -0.05, false);
    // Build Trajectory for Run C: High/Chotic Entropy (\Omega = 0.85) -> Divergent Drifting
    const trajC = simulateTrajectory(0.85, 0.25, 0.4, 0.3, -0.2, 0.25, false);

    // Build Isolated Flow Guard Sweep Runs (Isolating Gain K, holding everything else constant)
    const trajC1 = simulateTrajectory(0.80, 0.20, 0.85, 0.75, -0.15, 0.15, false); // C1: Low Gain (Large drift)
    const trajC2 = simulateTrajectory(0.80, 0.50, 0.85, 0.75, -0.15, 0.15, false); // C2: Medium Gain (Stable decay)
    const trajC3 = simulateTrajectory(0.80, 0.80, 0.85, 0.75, -0.15, 0.15, true);  // C3: High Gain (Oscillating)
    const trajC4 = simulateTrajectory(0.80, 1.20, 0.85, 0.75, -0.15, 0.15, true);  // C4: Ultra Gain (Heavy oscillation)

    setRunA(trajA);
    setRunB(trajB);
    setRunC(trajC);

    setRunC1(trajC1);
    setRunC2(trajC2);
    setRunC3(trajC3);
    setRunC4(trajC4);

    // Mock updates logs array with precise offsets
    const currentRun = 
      selectedRun === "A" ? trajA : 
      selectedRun === "B" ? trajB : 
      selectedRun === "C" ? trajC :
      selectedRun === "C1" ? trajC1 :
      selectedRun === "C2" ? trajC2 :
      selectedRun === "C3" ? trajC3 : trajC4;

    const logs = [
      `00:00.000 [ORCHESTRATOR] S(0) successfully compiled on Creative State Manifold`,
      `00:00.042 [INITIALIZATION] IVP bounds verified: S0 in constraint subset C`
    ];

    currentRun.forEach((state, idx) => {
      if (idx <= currentTick) {
        const msBase = (idx * 125) + 80;
        logs.push(`00:0${idx}.${(msBase).toString().padStart(3, '0')} [TICK ${idx}] Proposed state S*(${idx}) calculated. Entropy: ${state.Q.entropy.toFixed(2)}.`);
        logs.push(`00:0${idx}.${(msBase + 42).toString().padStart(3, '0')} [TICK ${idx}] Witness Integrity: ${getIntegrityBlocks(state.Q.witnessDrift)}.`);
        if (state.Q.witnessDrift > 0.4) {
          logs.push(`00:0${idx}.${(msBase + 62).toString().padStart(3, '0')} [FLOW GUARD] Applied corrective controller vector u(${idx}): ${state.description}`);
        }
        logs.push(`00:0${idx}.${(msBase + 93).toString().padStart(3, '0')} [ORCHESTRATOR] Transformed candidate state S(${idx}) status: ${state.decision}`);
      }
    });

    setActiveLogs(logs.reverse());
  };

  // Trajectory Simulation Core Mathematical Generator (State-space approximation model)
  const simulateTrajectory = (
    omega: number, 
    gain: number, 
    inertia: number, 
    strictness: number,
    offsetX: number,
    offsetY: number,
    oscillating: boolean // Simulate overshooting/oscillation for high gains
  ): ELYCreativeState[] => {
    const trajectory: ELYCreativeState[] = [];

    // Initial State S0
    let currentX = -0.15 + offsetX;
    let currentY = -0.1 + offsetY;
    let currentMomentum = 1.0;
    let emotionX = -0.4;
    let emotionY = -0.2;

    for (let t = 0; t <= 15; t++) {
      // 1. Calculate Unconstrained Generative Dynamics G(S(t), \Omega(t), u(t))
      const stepIntensity = 0.15 + omega * 0.25;
      const angle = (t * 0.45) + (Math.random() - 0.5) * (omega * 2.0);

      let targetX = currentX + Math.cos(angle) * stepIntensity;
      let targetY = currentY + Math.sin(angle) * stepIntensity;

      // 2. Compute Flow Guard Feedback Controller u(t) = \Phi(e(t))
      let closestBasin = BASINS[0];
      let minDist = 999;
      BASINS.forEach(b => {
        const d = Math.sqrt(Math.pow(targetX - b.x, 2) + Math.pow(targetY - b.y, 2));
        if (d < minDist) {
          minDist = d;
          closestBasin = b;
        }
      });

      // Feedback vector pulling candidate towards attractor center
      const errorX = closestBasin.x - targetX;
      const errorY = closestBasin.y - targetY;

      let ctrlX = errorX * gain * 0.5;
      let ctrlY = errorY * gain * 0.5;

      if (oscillating && t > 2) {
        // High gain feedback overshoot: alternate sign to simulate oscillatory spring action
        const overshootScale = gain * 0.45;
        ctrlX += Math.sin(t * 2.5) * overshootScale * (t % 2 === 0 ? 1 : -1);
        ctrlY += Math.cos(t * 2.5) * overshootScale * (t % 2 === 0 ? -1 : 1);
      }

      targetX += ctrlX;
      targetY += ctrlY;

      // 3. Apply Constraint Operator Projection C (pulls back into admissible boundary)
      const allowedRadius = 0.5 - (strictness * 0.25);
      const originDist = Math.sqrt(targetX * targetX + targetY * targetY);
      if (originDist > allowedRadius) {
        targetX = (targetX / originDist) * allowedRadius;
        targetY = (targetY / originDist) * allowedRadius;
      }

      // Slow moving Witness updating inertia
      const witnessDrift = Math.min(1.0, Math.max(0.0, originDist * (1.0 - inertia)));

      // Decision calculation
      let decision: "ACCEPT" | "REFINE" | "REJECT" = "ACCEPT";
      if (witnessDrift > 0.45 && omega > 0.6) {
        decision = "REFINE";
      } else if (originDist > 0.45) {
        decision = "REJECT";
      }

      // Update state coordinates
      currentX = targetX;
      currentY = targetY;
      currentMomentum = Math.max(0.1, currentMomentum - 0.05 + (t * 0.02) * (1 - omega));
      emotionX = Math.min(1.0, Math.max(-1.0, emotionX + (closestBasin.x * 0.1)));
      emotionY = Math.min(1.0, Math.max(-1.0, emotionY + (closestBasin.y * 0.1)));

      // Pre-calculate error reduction ratio \eta(t) = |e(t)| / |e(t-1)|
      let errRatio = 1.0;
      if (t > 0) {
        const prevErr = Math.sqrt(Math.pow(trajectory[t-1].coordinate.x - closestBasin.x, 2) + Math.pow(trajectory[t-1].coordinate.y - closestBasin.y, 2));
        const currErr = Math.sqrt(Math.pow(targetX - closestBasin.x, 2) + Math.pow(targetY - closestBasin.y, 2));
        errRatio = currErr / (prevErr || 0.01);
      }

      // Compute Composite Stability Score \Sigma (Framework-defined composite)
      // \Sigma = w1(1-e) + w2(1-\Delta W) + w3(\Phi) + w4(C_satisfaction)
      const e_bar = Math.min(1.0, Math.max(0.0, originDist));
      const delta_W_bar = witnessDrift;
      const phi_bar = Math.max(0.01, 1.0 - (originDist * 0.8) - (witnessDrift * 0.2));
      const C_satisfaction = decision === "ACCEPT" ? 1.0 : decision === "REFINE" ? 0.5 : 0.0;
      const sigma = (0.3 * (1.0 - e_bar)) + (0.3 * (1.0 - delta_W_bar)) + (0.2 * phi_bar) + (0.2 * C_satisfaction);

      // Compile State representation
      trajectory.push({
        tick: t,
        X: {
          emotion: { x: emotionX, y: emotionY },
          intent: Math.max(0.1, 1.0 - (witnessDrift * 0.6)),
          momentum: currentMomentum
        },
        K: {
          memoryStack: [
            "Witness established: Iron lock",
            `Attractor lock: ${closestBasin.name}`,
            t > 4 ? "Warp verified at T+5" : "Init bounds holding",
            t > 10 ? "Semantic promise archived" : "Sensing trajectory"
          ],
          historyDepth: t + 1
        },
        D: {
          activeCharacter: t < 6 ? "THE OBSERVER" : "THE WITNESS",
          sceneConsistency: Math.max(0.1, 1.0 - witnessDrift),
          relationshipTension: Math.min(1.0, 0.2 + (originDist * 1.5))
        },
        Q: {
          entropy: omega,
          flowStability: phi_bar,
          witnessDrift: witnessDrift,
          errorReductionRatio: errRatio,
          stabilityScore: sigma,
          errComponent: 1.0 - e_bar,
          witnessComponent: 1.0 - delta_W_bar,
          flowComponent: phi_bar,
          constraintComponent: C_satisfaction
        },
        coordinate: { x: currentX, y: currentY },
        decision,
        description: `State projected at coordinates (${currentX.toFixed(2)}, ${currentY.toFixed(2)}) inside ${closestBasin.name.split(" ")[0]} field boundary.`
      });
    }

    return trajectory;
  };

  // Helper to compute tracking error e(t) for a state
  const getTrackingError = (state: ELYCreativeState): number => {
    let closestBasin = BASINS[0];
    let minDist = 999;
    BASINS.forEach(b => {
      const d = Math.sqrt(Math.pow(state.coordinate.x - b.x, 2) + Math.pow(state.coordinate.y - b.y, 2));
      if (d < minDist) {
        minDist = d;
        closestBasin = b;
      }
    });
    return minDist;
  };

  // Draw the State Manifold & State Trajectory inside Canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;

    // Clear Canvas with nice Grid lines
    ctx.fillStyle = "#030712";
    ctx.fillRect(0, 0, width, height);

    // Draw Grid Coordinate Lines
    ctx.strokeStyle = "rgba(6, 182, 212, 0.05)";
    ctx.lineWidth = 1;
    for (let i = 0; i < width; i += 40) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i, height);
      ctx.stroke();
    }
    for (let j = 0; j < height; j += 40) {
      ctx.beginPath();
      ctx.moveTo(0, j);
      ctx.lineTo(width, j);
      ctx.stroke();
    }

    const centerX = width / 2;
    const centerY = height / 2;
    const scale = width * 0.8; // Transform state [-0.5, 0.5] to canvas size

    // Axis Labels showing COHERENCE vs EXPLORATION
    ctx.fillStyle = "rgba(6, 182, 212, 0.35)";
    ctx.font = "8px monospace";
    ctx.fillText("COHERENCE (Conceptual Axis)", centerX + 8, 20);
    ctx.fillText("EXPLORATION (Conceptual Axis)", width - 130, centerY - 8);

    // Axis arrows
    ctx.strokeStyle = "rgba(6, 182, 212, 0.2)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(centerX, height - 10);
    ctx.lineTo(centerX, 10);
    ctx.moveTo(centerX - 4, 15);
    ctx.lineTo(centerX, 10);
    ctx.lineTo(centerX + 4, 15);
    ctx.moveTo(10, centerY);
    ctx.lineTo(width - 10, centerY);
    ctx.moveTo(width - 15, centerY - 4);
    ctx.lineTo(width - 10, centerY);
    ctx.lineTo(width - 15, centerY + 4);
    ctx.stroke();

    // Draw Attractor Basins
    BASINS.forEach(b => {
      const x = centerX + b.x * scale;
      const y = centerY - b.y * scale; // Flip Y for typical cartesian
      const r = b.radius * scale;

      // Glow effect
      const glow = ctx.createRadialGradient(x, y, 0, x, y, r);
      glow.addColorStop(0, b.color);
      glow.addColorStop(1, "transparent");
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();

      // Basin Center Point
      ctx.fillStyle = b.id === "A" ? "#22d3ee" : b.id === "B" ? "#f43f5e" : b.id === "C" ? "#a855f7" : "#22c55e";
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();

      // Basin label
      ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
      ctx.font = "9px monospace";
      ctx.fillText(b.name.split(" ")[0], x + 8, y + 3);
    });

    // Draw Admissible Set Boundary Constraint circle (C)
    const allowedRadius = (0.5 - (constraintStrictness * 0.25)) * scale;
    ctx.strokeStyle = "rgba(239, 68, 68, 0.25)";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.arc(centerX, centerY, allowedRadius, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = "rgba(239, 68, 68, 0.05)";
    ctx.fillText("ADMISSIBLE BOUNDARY C (Conceptual)", centerX - allowedRadius + 8, centerY - allowedRadius - 6);

    // Draw Multi-Candidate Futures (Radiating unconstrained proposals from the active node)
    const currentTraj = 
      selectedRun === "A" ? runA : 
      selectedRun === "B" ? runB : 
      selectedRun === "C" ? runC :
      selectedRun === "C1" ? runC1 :
      selectedRun === "C2" ? runC2 :
      selectedRun === "C3" ? runC3 : runC4;

    if (currentTraj.length > 0 && currentTick < currentTraj.length) {
      const activeState = currentTraj[currentTick];
      const startX = centerX + activeState.coordinate.x * scale;
      const startY = centerY - activeState.coordinate.y * scale;

      // Draw 3 radiating candidate branches representing unconstrained G(S(t))
      const branchAngles = [-0.6, 0.0, 0.6];
      branchAngles.forEach((angOffset, bIdx) => {
        const branchAngle = (currentTick * 0.45) + angOffset;
        const branchDist = 45 + (userEntropy * 30);
        const endX = startX + Math.cos(branchAngle) * branchDist;
        const endY = startY + Math.sin(branchAngle) * branchDist;

        // Faint candidate branch line
        ctx.strokeStyle = "rgba(244, 63, 94, 0.25)";
        ctx.lineWidth = 1;
        ctx.setLineDash([2, 3]);
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
        ctx.setLineDash([]);

        // Candidate node head
        ctx.fillStyle = "rgba(244, 63, 94, 0.5)";
        ctx.beginPath();
        ctx.arc(endX, endY, 3, 0, Math.PI * 2);
        ctx.fill();

        // Faint label
        ctx.fillStyle = "rgba(244, 63, 94, 0.4)";
        ctx.font = "7px monospace";
        ctx.fillText(`S* Candidate ${String.fromCharCode(65 + bIdx)}`, endX + 6, endY + 2);
      });
    }

    // Draw Trajectories
    const drawPath = (states: ELYCreativeState[], color: string, active: boolean, widthVal: number) => {
      if (states.length === 0) return;
      ctx.strokeStyle = color;
      ctx.lineWidth = widthVal;
      ctx.beginPath();

      states.forEach((s, idx) => {
        if (idx > currentTick) return;
        const x = centerX + s.coordinate.x * scale;
        const y = centerY - s.coordinate.y * scale;

        if (idx === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // Draw active node head
      if (currentTick < states.length) {
        const activeState = states[currentTick];
        const x = centerX + activeState.coordinate.x * scale;
        const y = centerY - activeState.coordinate.y * scale;

        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.arc(x, y, active ? 6 : 4, 0, Math.PI * 2);
        ctx.fill();

        if (active) {
          ctx.strokeStyle = "#fff";
          ctx.lineWidth = 1.5;
          ctx.beginPath();
          ctx.arc(x, y, 9, 0, Math.PI * 2);
          ctx.stroke();
        }
      }
    };

    if (researchMode) {
      drawPath(runA, "rgba(22, 163, 74, 0.45)", selectedRun === "A", 1.5); // Low Entropy
      drawPath(runB, "rgba(34, 211, 238, 0.8)", selectedRun === "B", 2.5); // Optimized
      drawPath(runC, "rgba(244, 63, 94, 0.45)", selectedRun === "C", 1.5);  // High Entropy

      // Draw Sweep tracks if selected
      if (selectedRun === "C1") drawPath(runC1, "#22c55e", true, 2.5);
      if (selectedRun === "C2") drawPath(runC2, "#3b82f6", true, 2.5);
      if (selectedRun === "C3") drawPath(runC3, "#eab308", true, 2.5);
      if (selectedRun === "C4") drawPath(runC4, "#ef4444", true, 2.5);
    } else {
      const currentTraj = 
        selectedRun === "A" ? runA : 
        selectedRun === "B" ? runB : 
        selectedRun === "C" ? runC :
        selectedRun === "C1" ? runC1 :
        selectedRun === "C2" ? runC2 :
        selectedRun === "C3" ? runC3 : runC4;

      const trajColor = 
        selectedRun === "A" ? "#22c55e" : 
        selectedRun === "B" ? "#22d3ee" : 
        selectedRun === "C" ? "#f43f5e" :
        selectedRun === "C1" ? "#22c55e" :
        selectedRun === "C2" ? "#3b82f6" :
        selectedRun === "C3" ? "#eab308" : "#ef4444";

      drawPath(currentTraj, trajColor, true, 2.5);
    }

  }, [currentTick, runA, runB, runC, researchMode, selectedRun, constraintStrictness]);

  // Simulation Clock Tick Effect
  useEffect(() => {
    if (!isPlaying) return;

    const timer = setInterval(() => {
      setCurrentTick(prev => {
        if (prev >= 15) {
          setIsPlaying(false);
          return 15;
        }
        return prev + 1;
      });
    }, speedMs);

    return () => clearInterval(timer);
  }, [isPlaying, speedMs]);

  // Dynamically update active logs on current tick changes
  useEffect(() => {
    const currentRun = 
      selectedRun === "A" ? runA : 
      selectedRun === "B" ? runB : 
      selectedRun === "C" ? runC :
      selectedRun === "C1" ? runC1 :
      selectedRun === "C2" ? runC2 :
      selectedRun === "C3" ? runC3 : runC4;

    if (currentRun.length === 0) return;

    const logs = [
      `00:00.000 [ORCHESTRATOR] S(0) successfully compiled on Creative State Manifold`,
      `00:00.042 [INITIALIZATION] IVP bounds verified: S0 in constraint subset C`
    ];

    currentRun.forEach((state, idx) => {
      if (idx <= currentTick) {
        const msBase = (idx * 125) + 80;
        logs.push(`00:0${idx}.${(msBase).toString().padStart(3, '0')} [TICK ${idx}] Proposed state S*(${idx}) calculated. Entropy: ${state.Q.entropy.toFixed(2)}.`);
        logs.push(`00:0${idx}.${(msBase + 42).toString().padStart(3, '0')} [TICK ${idx}] Witness Integrity: ${getIntegrityBlocks(state.Q.witnessDrift)}.`);
        if (state.Q.witnessDrift > 0.4) {
          logs.push(`00:0${idx}.${(msBase + 62).toString().padStart(3, '0')} [FLOW GUARD] Applied corrective controller vector u(${idx}): ${state.description}`);
        }
        logs.push(`00:0${idx}.${(msBase + 93).toString().padStart(3, '0')} [ORCHESTRATOR] Transformed candidate state S(${idx}) status: ${state.decision}`);
      }
    });

    setActiveLogs(logs.reverse());
  }, [currentTick, selectedRun, runA, runB, runC, runC1, runC2, runC3, runC4]);

  // Handle saving current parameters as an Experiment Record
  const handleSaveExperiment = () => {
    const id = `FG-2026-${(savedExperiments.length + 1).toString().padStart(3, "0")}`;
    const newRecord = {
      id,
      name: `Custom Lab Run (${selectedRun})`,
      omega: userEntropy,
      gain: flowGuardGain,
      inertia: witnessInertia,
      strictness: constraintStrictness
    };
    setSavedExperiments(prev => [...prev, newRecord]);
    const traceLogs = [...activeLogs];
    traceLogs.unshift(`[ORCHESTRATOR] Experiment successfully cataloged as ${id}`);
    setActiveLogs(traceLogs);
  };

  const handleLoadExperiment = (exp: any) => {
    setUserEntropy(exp.omega);
    setFlowGuardGain(exp.gain);
    setWitnessInertia(exp.inertia);
    setConstraintStrictness(exp.strictness);
    generateAllTrajectories();
  };

