              {activeLogs.map((log, idx) => (
                <div 
                  key={idx} 
                  className={`border-l pl-2 leading-relaxed ${log.includes("WARN") || log.includes("REJECT") ? "border-red-500 text-red-400" : log.includes("FLOW GUARD") || log.includes("DECISION") ? "border-orange-500 text-orange-400" : "border-cyan-950 text-[#8aa1ae]"}`}
                >
