// Helper for multi-vortex directional routing (asymmetric convection transport)
const getBranchingBias = (from: string, to: string) => {
  // Perimeter Convection Ring (Vortex Loop 1)
  if (from === "alpha" && to === "beta") return 1.0;
  if (from === "beta" && to === "gamma") return 1.0;
  if (from === "gamma" && to === "delta") return 1.0;
  if (from === "delta" && to === "alpha") return 1.0;

  if (from === "beta" && to === "alpha") return -1.0;
  if (from === "gamma" && to === "beta") return -1.0;
  if (from === "delta" && to === "gamma") return -1.0;
  if (from === "alpha" && to === "delta") return -1.0;

  // Intersecting Branching Bridges (Vortex Loop 2 & Junction splits)
  if (from === "alpha" && to === "gamma") return 1.5; 
  if (from === "delta" && to === "beta") return 1.5;  

  if (from === "gamma" && to === "alpha") return -1.5;
  if (from === "beta" && to === "delta") return -1.5;
  return 0.0;
};

