  }, [isPlaying, speedMultiplier, couplingStrength, feedbackAlpha, thermalNoiseFloor, thermalDiffusionRate, vortexBias, branchingBias, plasticityRate, potentialGravity, landscapeAdaptationRate, activeSpecimens, phases, thermalEnergy, edgePlasticity, specimenCoords, basinDepths, basinCenters, creativeMomentum, isSongPlaying, impulseActive, isRelaxing]);

