  const [songColor, setSongColor] = useState("#f59e0b");  // Yellow/Gold
  const [bgImageUrl, setBgImageUrl] = useState<string | null>(null);
  const [bgWallpaperOpacity, setBgWallpaperOpacity] = useState(0.35);
  const [bgXOffset, setBgXOffset] = useState(0);
  const [bgYOffset, setBgYOffset] = useState(0);
  const [aspectRatio, setAspectRatio] = useState("16:9"); // "1:1" or "16:9"
  const [thumbImageUrl, setThumbImageUrl] = useState<string | null>(null);
  const [currentAudioSrc, setCurrentAudioSrc] = useState(AUDIO_URL);
  const [tracklistText, setTracklistText] = useState("");
  const [activeTab, setActiveTab] = useState("design"); // "design" or "youtube"
  const [songThemeInput, setSongThemeInput] = useState("A romantic synthwave ballad about longing, retro nights, and endless horizons.");
  const [audioError, setAudioError] = useState<string | null>(null);
  const [isRecordingVideo, setIsRecordingVideo] = useState(false);
  const [recordedChunks, setRecordedChunks] = useState<Blob[]>([]);
  const [vinylRpmSetting, setVinylRpmSetting] = useState("normal"); // slow, normal, fast, turbo
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [useCors, setUseCors] = useState(false);
