  const audioSourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const audioDestRef = useRef<MediaStreamAudioDestinationNode | null>(null);
  const vinylAngleRef = useRef(0);
  const currentSpeedRef = useRef(0);

  // Custom Offset positions for layout elements (Movable sun and thumbnail)
  const [sunXOffset, setSunXOffset] = useState(0);
  const [sunYOffset, setSunYOffset] = useState(0);
  const [thumbXOffset, setThumbXOffset] = useState(0);
  const [thumbYOffset, setThumbYOffset] = useState(0);
  const [thumbScale, setThumbScale] = useState(1.0);

  const isWideLayout = aspectRatio === "16:9";

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const bgFileInputRef = useRef<HTMLInputElement | null>(null);
  const thumbFileInputRef = useRef<HTMLInputElement | null>(null);
  const bgImgElementRef = useRef<HTMLImageElement | null>(null);
  const thumbImgElementRef = useRef<HTMLImageElement | null>(null);
  const visualizerContainerRef = useRef<HTMLDivElement | null>(null);
  const animationRef = useRef<number | null>(null);

  // Force pure 2D Canvas rendering loop for maximum rendering reliability
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) {
      console.error("2D Context not available");
      return;
    }

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;

      // Let canvas perfectly match parent container managed via CSS Tailwind aspect ratios
      canvas.width = parent.clientWidth;
      canvas.height = parent.clientHeight;
    };
    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);

    let frameCount = 0;

    const draw = () => {
      if (!canvas || !ctx) return;
      const width = canvas.width;
      const height = canvas.height;

      // Highly aesthetic procedural retro wave simulation that dances to the beat!
      // This completely bypasses browser CORS locks and Web Audio API play-block freezes.
      const rawData = new Uint8Array(128);
      for (let i = 0; i < 128; i++) {
        if (isPlaying) {
          const baseFreq = frameCount * 0.08;
          const bass = Math.abs(Math.sin(baseFreq + i * 0.12)) * 130;
          const mid = Math.abs(Math.cos(baseFreq * 1.5 + i * 0.22)) * 80;
          const treble = Math.sin(baseFreq * 3.0 + i * 0.45) * 35;
          const textFont = Math.random() * 20;

          // Modulate height slightly over time to simulate a real changing music structure
          const waveHeightModifier = 0.7 + Math.sin(frameCount * 0.01) * 0.3;
          rawData[i] = Math.min(255, Math.max(0, (bass + mid + treble + textFont) * waveHeightModifier));
        } else {
          // Slow ambient floating idle wave when paused
          rawData[i] = 12 + Math.sin(frameCount * 0.03 + i * 0.08) * 6;
        }
      }

      frameCount++;

      // Inertia-based rotation calculations (Clockwise continuous rotation with RPM)
      const rpmMap: Record<string, number> = { slow: 3, normal: 8, fast: 16, turbo: 24 };
      const currentRpm = rpmMap[vinylRpmSetting] || 8;
      const targetSpeed = isPlaying ? (currentRpm * Math.PI * 2) / 3600 : 0;
      // Interpolate speed for natural deceleration / momentum when stopping
      currentSpeedRef.current += (targetSpeed - currentSpeedRef.current) * 0.04;
      vinylAngleRef.current += currentSpeedRef.current;

      // Theme Colors Mapping (5 Curated Elyzareth OS Skins)
      let pColor = "#06b6d4"; // Cyan
      let sColor = "#ec4899"; // Pink
      let bColor = "#020617"; // Dark background

      if (themeColor === "gold") {
        pColor = "#fbbf24"; // Imperial Amber Gold
        sColor = "#f97316"; // Bright Orange Accent
        bColor = "#0c0a09"; // Warm Stone Black
      } else if (themeColor === "emerald") {
        pColor = "#10b981"; // Matrix Emerald Green
        sColor = "#06b6d4"; // Cyber Teal Accent
        bColor = "#020c08"; // Deep Forest Void
      } else if (themeColor === "ruby") {
        pColor = "#ef4444"; // Crimson Sunset Red
        sColor = "#f59e0b"; // Solar Yellow Accent
        bColor = "#120202"; // Deep Wine Black
      } else if (themeColor === "amethyst") {
        pColor = "#a855f7"; // Cosmic Amethyst Purple
        sColor = "#3b82f6"; // Stellar Sapphire Blue Accent
        bColor = "#090514"; // Deep Royal Violet Void
      }

      // Draw dark background behind the physical TV frame
      ctx.fillStyle = bColor;
      ctx.fillRect(0, 0, width, height);

      // --- SKEUOMORPHIC CURVED TV GEOMETRY ---
      const padLeft = width * 0.04;
      const padRight = width * 0.04;
      const padTop = height * 0.05;
      const padBottom = height * 0.16; // Leaves perfect breathing room for stand base
      const curveAmt = height * 0.026; // Slanted curve representing physical curved TV depth

      // 1. Draw 3D Brushed Metal TV Stand Column/Neck (Behind Bezel)
      const neckWidth = Math.max(16, width * 0.025);
      const neckX = width / 2;
      const neckY = height - padBottom + curveAmt;
      const baseY = height - 12; // Base plate Y center
      const neckH = baseY - neckY + 2; // Extends slightly into base for robust overlapping

      const neckGrad = ctx.createLinearGradient(neckX - neckWidth / 2, 0, neckX + neckWidth / 2, 0);
      neckGrad.addColorStop(0, "#334155");
      neckGrad.addColorStop(0.25, "#64748b");
      neckGrad.addColorStop(0.5, "#f1f5f9");
      neckGrad.addColorStop(0.75, "#64748b");
      neckGrad.addColorStop(1, "#334155");

      ctx.fillStyle = neckGrad;
      ctx.fillRect(neckX - neckWidth / 2, neckY, neckWidth, neckH);

      // 2. Draw 3D Curved TV Stand Base Plate
      const baseW = Math.max(110, width * 0.22);
      const baseH = Math.max(8, height * 0.022);

      const baseGrad = ctx.createLinearGradient(neckX - baseW / 2, 0, neckX + baseW / 2, 0);
      baseGrad.addColorStop(0, "#1e293b");
      baseGrad.addColorStop(0.2, "#475569");
      baseGrad.addColorStop(0.5, "#cbd5e1");
      baseGrad.addColorStop(0.8, "#475569");
      baseGrad.addColorStop(1, "#1e293b");

      ctx.fillStyle = baseGrad;
      ctx.beginPath();
      ctx.ellipse(neckX, baseY, baseW / 2, baseH, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "#94a3b8";
      ctx.lineWidth = 1;
      ctx.stroke();

      // 3. Draw metallic collar/socket ring at the base of the neck to stand securely INSIDE the plate
      ctx.fillStyle = "#0f172a";
      ctx.strokeStyle = "#94a3b8";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.ellipse(neckX, baseY, neckWidth * 0.8, 3, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // 3. Save Context & Create Clip Mask for the Curved TV Screen
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(padLeft, padTop + curveAmt);
      ctx.quadraticCurveTo(width / 2, padTop, width - padRight, padTop + curveAmt);
      ctx.lineTo(width - padRight, height - padBottom + curveAmt);
      ctx.quadraticCurveTo(width / 2, height - padBottom, padLeft, height - padBottom + curveAmt);
      ctx.closePath();
      ctx.clip(); // Confines all following renders (wallpaper, grids, vinyl, text) inside the TV screen!

      // --- ALL CONTENT RENDERING INSIDE TV SCREEN ---

      // Draw dark screen base inside TV
      ctx.fillStyle = "#02040a";
      ctx.fillRect(0, 0, width, height);

      // Draw custom background wallpaper if loaded
      if (bgImgElementRef.current) {
        ctx.save();
        ctx.globalAlpha = bgWallpaperOpacity;

        // Draw image with "cover" aspect ratio fit
        const img = bgImgElementRef.current;
        const imgRatio = img.width / img.height;
        const canvasRatio = width / height;
        let drawW = width;
        let drawH = height;
        let drawX = 0;
        let drawY = 0;

        if (canvasRatio > imgRatio) {
          drawH = width / imgRatio;
          drawY = (height - drawH) / 2;
        } else {
          drawW = height * imgRatio;
