    setCurrentTime(0);
  };

  const handleLocalFileLoad = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const file = files[0];

    if (!audioRef.current) return;

    // Revoke old blob URL to avoid memory leaks
    if (currentAudioSrc.startsWith("blob:")) {
      URL.revokeObjectURL(currentAudioSrc);
    }

    // Create high-performance native blob URL
    const localBlobUrl = URL.createObjectURL(file);

    if (audioRef.current) {
      audioRef.current.pause();
    }
    setIsPlaying(false);
    setAudioError(null);

    // Set state reactively to the blob URL to enable smooth streaming and seek play
    setCurrentAudioSrc(localBlobUrl);
    setSongTitle(`${file.name} [Local File]`);
    setCurrentTime(0);
  };

  const handleExportFrame = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dataUrl = canvas.toDataURL("image/png");
    const link = document.createElement("a");
    link.download = `${songTitle.replace(/[^a-z0-9]/gi, "_").toLowerCase()}_visualizer_frame.png`;
    link.href = dataUrl;
    link.click();
  };

  const handleGenerateMetadata = () => {
    const text = songThemeInput;
    let titleUpdated = false;
    let captionUpdated = false;

    // 1. Extract [TITLE: ...]
    const titleMatch = text.match(/\[TITLE:\s*([^\]]+)\]/i);
    if (titleMatch && titleMatch[1]) {
      setSongTitle(titleMatch[1].trim());
      titleUpdated = true;
    }

    // 2. Extract [CAPTION: ...] or [SUBTITLE: ...]
    const captionMatch = text.match(/\[CAPTION:\s*([^\]]+)\]/i) || text.match(/\[SUBTITLE:\s*([^\]]+)\]/i);
    if (captionMatch && captionMatch[1]) {
      setCaptionText(captionMatch[1].trim());
      captionUpdated = true;
    }

    if (titleUpdated || captionUpdated) {
      alert("⚡ Form Auto-Filled! Your song title and subtitles are now fully synced across the visualizer and YouTube metadata.");
    } else {
      alert("📝 Theme Updated! Tip: Add [TITLE: Your Song Name] inside the box to automatically sync the 3D Sunset text and metadata.");
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Copied to clipboard! 📋");
