  const handleStartRecording = async () => {
    const canvas = canvasRef.current;
    const audio = audioRef.current;
    if (!canvas || !audio) return;

    try {
      setRecordedChunks([]);

      const canvasStream = canvas.captureStream(30);
      const combinedTracks: MediaStreamTrack[] = [];

      let audioStream: MediaStream | null = null;
      try {
        if ('captureStream' in audio) {
          audioStream = (audio as any).captureStream();
        } else if ('mozCaptureStream' in audio) {
          audioStream = (audio as any).mozCaptureStream();
        } else {
          // Web Audio fallback only if direct capture is unsupported
          if (!audioCtxRef.current) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            audioCtxRef.current = ctx;
            const source = ctx.createMediaElementSource(audio);
            audioSourceRef.current = source;
            const dest = ctx.createMediaStreamDestination();
            audioDestRef.current = dest;
            source.connect(dest);
            source.connect(ctx.destination);
          }
          audioStream = audioDestRef.current ? audioDestRef.current.stream : null;
        }
      } catch (e) {
        console.warn("Direct element stream capture fallback applied", e);
      }

      if (audioStream) {
        audioStream.getAudioTracks().forEach(track => combinedTracks.push(track));
      }

      canvasStream.getVideoTracks().forEach(track => combinedTracks.push(track));

      const combinedStream = new MediaStream(combinedTracks);
      recordingStreamRef.current = combinedStream;

      let mimeType = "video/mp4";
      if (!MediaRecorder.isTypeSupported(mimeType)) {
        const optionsList = [
          "video/mp4;codecs=h264",
          "video/webm;codecs=vp9,opus",
          "video/webm"
        ];
        for (const option of optionsList) {
          if (MediaRecorder.isTypeSupported(option)) {
            mimeType = option;
            break;
          }
        }
      }

      let recorder: MediaRecorder;
      try {
        recorder = new MediaRecorder(combinedStream, { mimeType });
      } catch (e) {
        recorder = new MediaRecorder(combinedStream);
      }

      mediaRecorderRef.current = recorder;
      const chunks: Blob[] = [];

      recorder.ondataavailable = (evt) => {
        if (evt.data && evt.data.size > 0) {
          chunks.push(evt.data);
        }
      };

      recorder.onstop = () => {
        const completeBlob = new Blob(chunks, { type: mimeType });
        const videoUrl = URL.createObjectURL(completeBlob);

        const link = document.createElement("a");
        link.download = `${songTitle.replace(/[^a-z0-9]/gi, "_").toLowerCase()}_visualizer_hd.mp4`;
        link.href = videoUrl;
        link.click();

        if (recordingStreamRef.current) {
          recordingStreamRef.current.getTracks().forEach(track => track.stop());
        }
        setIsRecordingVideo(false);
      };

      audio.play().catch(() => {});
      setIsPlaying(true);

      setIsRecordingVideo(true);
      recorder.start(100);
    } catch (err) {
      console.error("Recording initialization failed:", err);
      alert("Failed to start recording. Please ensure you play music once before starting.");
    }
  };

