              title="Toggle Fullscreen"
            >
              <Maximize className="w-4 h-4" />
            </button>
          </div>

          {/* YouTube Caption/Subtitle Bar (Lower Box) - Only renders when captionText has content */}
          {captionText && (
            <div className="bg-slate-950/90 border border-slate-800 rounded-xl p-4 flex items-center justify-center min-h-[64px] shadow-lg relative overflow-hidden">
              {/* Cinematic yellow accent bars on the side */}
              <div className="absolute left-2 top-1/2 -translate-y-1/2 h-5 w-1 bg-yellow-400 rounded-full" />
              <div className="absolute right-2 top-1/2 -translate-y-1/2 h-5 w-1 bg-yellow-400 rounded-full" />

              <p className="text-sm font-bold font-sans text-center text-yellow-300 tracking-wide select-none drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
                {captionText}
              </p>
            </div>
          )}

        </div>

      </div>
    </div>
  );
}

