const getMaterialFamily = (objectName: string): string => {
  const name = objectName.toLowerCase();
  if (/mirror|window|glass|spectacle|lens|pane/i.test(name)) {
    return "Glass";
  }
  if (/letter|postage|stamp|parchment|photo|ticket|book|notebook|paper|envelope|card|inkwell|wax/i.test(name)) {
    return "Paper";
  }
  if (/mug|cup|vessel|teapot|pot|plate|saucer|ceramic|clay|terracotta|shaker|jar|bowl|handle|glazed|chipped|sipped/i.test(name)) {
    return "Ceramic";
  }
  if (/key|keyring|watch|clock|hanger|lock|ring|ruler|metal|brass|iron|steel/i.test(name)) {
    return "Metal";
  }
  if (/chair|table|bench|deck|chest|wardrobe|wood|timber|pine|oak|shelf|board/i.test(name)) {
    return "Wood";
  }
  return "Ceramic"; // Default fallback
}

