function sanitizeAndGuard(rawLyrics: string, targetObject: string) {
  let cleanLyrics = rawLyrics.replace(/\(([^)]+vector[^)]*)\)/gi, '').trim();
  cleanLyrics = cleanLyrics.replace(/  +/g, ' ');
  const cleanTarget = targetObject.split('(')[0].trim().toLowerCase();
  const lines = cleanLyrics.split('\n');
  const hasObjectInVerse1 = lines.slice(0, 15).some(line => line.toLowerCase().includes(cleanTarget));
  return {
    cleanLyrics,
    isValidMatch: !!hasObjectInVerse1
  };
}

