// User-Defined Elyzareth Sanitizer & Flow Guard
function sanitizeAndGuard(rawLyrics: string, targetObject: string) {
  // 1. Strip technical parenthetical leaks like (paper/ink vector)
  let cleanLyrics = rawLyrics.replace(/\(([^)]+vector[^)]*)\)/gi, '').trim();

  // 2. Clean double spaces caused by the stripping process
  cleanLyrics = cleanLyrics.replace(/  +/g, ' ');

  // 3. Normalize checking strings (strip formatting for the comparison)
  const cleanTarget = targetObject.split('(')[0].trim().toLowerCase(); // "unread letter"

  // 4. Robust Section-Based Block Extraction for Verse 1 (No longer paragraph spacing sensitive)
  const lines = cleanLyrics.split('\n');
  let verse1Lines: string[] = [];
  let insideVerse1 = false;

  for (let line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('[Verse 1]')) {
      insideVerse1 = true;
      continue;
    }
    if (insideVerse1 && trimmed.startsWith('[')) {
      break; // Hit next section block, terminate harvest
    }
    if (insideVerse1 && trimmed !== "") {
      verse1Lines.push(trimmed.toLowerCase());
    }
  }

  const verse1Text = verse1Lines.length > 0 ? verse1Lines.join('\n') : lines.slice(0, 15).join('\n').toLowerCase();

  // 5. Dynamic Stem & Lemmatization Match: supports singular and plural variations for custom objects
  const targetStems = cleanTarget.split(/\s+/).filter(word => word.length > 2);
  const isValidMatch = targetStems.length > 0 
    ? targetStems.every(stem => {
        const stemReg = new RegExp(`\\b${stem}s?\\b`, 'i');
        return stemReg.test(verse1Text);
      })
    : verse1Text.includes(cleanTarget);

  return {
    cleanLyrics,
    isValidMatch: !!isValidMatch
  };
}

