                        if (!target) return null;
                        return (
                          <line
                            key={`${node.id}-${connId}`}
                            x1={`${node.x}%`}
                            y1={`${node.y}%`}
                            x2={`${target.x}%`}
                            y2={`${target.y}%`}
                            stroke="#3D352B"
                            strokeWidth="1.5"
                            strokeDasharray={selectedNode.id === node.id || selectedNode.id === target.id ? "1 0" : "4 4"}
